/// Validate selected-call custody against the actual machine owner. This does
/// not infer an unwind contract for any other call or resolve layout offsets.
pub(crate) fn validate_exact_aarch64_eh_call_identity(
    func: &IrMachFunction,
) -> Result<(), PipelineError> {
    eh_call_identity::exact_calls(func)
        .map(|_| ())
        .map_err(|detail| PipelineError::MalformedAarch64Eh {
            function: func.name.clone(),
            detail: format!("invalid AArch64 EH metadata/layout: {detail}"),
        })
}

