/// Structured bounded-fsym summary for one function prepared by the pipeline.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct FsymTrustIrPipelineSummary {
    pub module_name: String,
    pub function_name: String,
    pub scanned: bool,
    pub diagnostic_count: usize,
    pub warning_count: usize,
    pub unknown_obligation_count: usize,
    pub skipped: Option<FsymTrustIrPipelineSkip>,
    pub diagnostics: Vec<FsymTrustIrPipelineDiagnostic>,
    pub unknown_obligations: Vec<FsymTrustIrPipelineUnknown>,
    /// Count of deref-coverage gaps (dropped obligations) the scan reported for
    /// this function. A non-zero count makes `run_fsym_trust_ir_preflight`
    /// return `PipelineError::FsymCoverageGap` (fail-closed), mirroring the CLI
    /// gate on `report.has_coverage_error()`.
    pub coverage_error_count: usize,
    /// Rendered detail for each coverage gap, for diagnostics.
    pub coverage_errors: Vec<String>,
}

/// Structured bounded-fsym skip surfaced by the codegen pipeline.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct FsymTrustIrPipelineSkip {
    pub reason: String,
    pub detail: String,
}

/// Structured concrete fsym diagnostic surfaced by the codegen pipeline.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct FsymTrustIrPipelineDiagnostic {
    pub kind: String,
    pub block: u32,
    pub inst_index: usize,
    pub span: Option<FsymTrustIrPipelineSourceSpan>,
    pub message: String,
    pub warning: String,
}

/// Structured source location carried by a bounded fsym diagnostic.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct FsymTrustIrPipelineSourceSpan {
    pub file: u32,
    pub line: u32,
    pub col: u32,
}

/// Structured non-concrete fsym obligation surfaced by the codegen pipeline.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct FsymTrustIrPipelineUnknown {
    pub kind: String,
    pub label: String,
    pub block: u32,
    pub inst_index: usize,
    pub reason: String,
    pub warning: String,
}

/// A single proof fact cited by a proof-optimization certificate.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ProofOptimizationConsumedFactCitation {
    pub name: String,
    pub payload: Option<String>,
}

/// Stable, serializable citation for a proof-optimization certificate emitted
/// by `trust-cg-opt`.
///
/// The underlying `OptCertificate` stays in `trust-cg-opt`; codegen/release/replay
/// artifacts carry this compact form so downstream tooling can cite the
/// certificate identity and its proof/validation hashes without depending on
/// pass-internal data structures.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ProofOptimizationCertificateCitation {
    pub function_name: String,
    pub certificate_id: String,
    pub proof_hash: String,
    pub validation_hash: String,
    pub source_region_hash: String,
    pub target_region_hash: String,
    pub transform_name: String,
    pub transform_version: u32,
    pub admission: String,
    pub kind: String,
    pub status: String,
    pub rejection_code: Option<String>,
    pub rejection_fact: Option<String>,
    pub rejection_detail: Option<String>,
    pub consumed_facts: Vec<ProofOptimizationConsumedFactCitation>,
}

impl ProofOptimizationCertificateCitation {
    fn from_opt_certificate(
        function_name: &str,
        certificate: &trust_cg_opt::proof_opts::OptCertificate,
    ) -> Self {
        let consumed_facts = certificate
            .consumed_facts
            .iter()
            .copied()
            .map(|fact| ProofOptimizationConsumedFactCitation {
                name: fact.stable_name().to_owned(),
                payload: fact.payload(),
            })
            .collect();
        let rejection = certificate.rejection.as_ref();

        Self {
            function_name: function_name.to_owned(),
            certificate_id: format_u128_identity(certificate.certificate_id),
            proof_hash: format_u128_identity(certificate.proof_hash),
            validation_hash: format_u128_identity(certificate.validation_hash),
            source_region_hash: format_u128_identity(certificate.source_region_hash),
            target_region_hash: format_u128_identity(certificate.target_region_hash),
            transform_name: certificate.transform.name.clone(),
            transform_version: certificate.transform.version,
            admission: certificate.route.admission.clone(),
            kind: format!("{:?}", certificate.kind),
            status: if rejection.is_some() {
                "rejected".to_owned()
            } else {
                "applied".to_owned()
            },
            rejection_code: rejection.map(|rejection| rejection.code.as_str().to_owned()),
            rejection_fact: rejection.map(|rejection| rejection.fact.clone()),
            rejection_detail: rejection.map(|rejection| rejection.detail.clone()),
            consumed_facts,
        }
    }

    pub fn to_json_value(&self) -> serde_json::Value {
        let consumed_facts = self
            .consumed_facts
            .iter()
            .map(|fact| {
                let mut object = serde_json::Map::with_capacity(2);
                object.insert(
                    "name".to_owned(),
                    serde_json::Value::String(fact.name.clone()),
                );
                object.insert(
                    "payload".to_owned(),
                    fact.payload
                        .as_ref()
                        .map_or(serde_json::Value::Null, |payload| {
                            serde_json::Value::String(payload.clone())
                        }),
                );
                serde_json::Value::Object(object)
            })
            .collect();

        let mut object = serde_json::Map::with_capacity(15);
        object.insert(
            "function_name".to_owned(),
            serde_json::Value::String(self.function_name.clone()),
        );
        object.insert(
            "certificate_id".to_owned(),
            serde_json::Value::String(self.certificate_id.clone()),
        );
        object.insert(
            "proof_hash".to_owned(),
            serde_json::Value::String(self.proof_hash.clone()),
        );
        object.insert(
            "validation_hash".to_owned(),
            serde_json::Value::String(self.validation_hash.clone()),
        );
        object.insert(
            "source_region_hash".to_owned(),
            serde_json::Value::String(self.source_region_hash.clone()),
        );
        object.insert(
            "target_region_hash".to_owned(),
            serde_json::Value::String(self.target_region_hash.clone()),
        );
        object.insert(
            "transform_name".to_owned(),
            serde_json::Value::String(self.transform_name.clone()),
        );
        object.insert(
            "transform_version".to_owned(),
            serde_json::Value::Number(serde_json::Number::from(u64::from(self.transform_version))),
        );
        object.insert(
            "admission".to_owned(),
            serde_json::Value::String(self.admission.clone()),
        );
        object.insert(
            "kind".to_owned(),
            serde_json::Value::String(self.kind.clone()),
        );
        object.insert(
            "status".to_owned(),
            serde_json::Value::String(self.status.clone()),
        );
        object.insert(
            "rejection_code".to_owned(),
            self.rejection_code
                .as_ref()
                .map_or(serde_json::Value::Null, |code| {
                    serde_json::Value::String(code.clone())
                }),
        );
        object.insert(
            "rejection_fact".to_owned(),
            self.rejection_fact
                .as_ref()
                .map_or(serde_json::Value::Null, |fact| {
                    serde_json::Value::String(fact.clone())
                }),
        );
        object.insert(
            "rejection_detail".to_owned(),
            self.rejection_detail
                .as_ref()
                .map_or(serde_json::Value::Null, |detail| {
                    serde_json::Value::String(detail.clone())
                }),
        );
        object.insert(
            "consumed_facts".to_owned(),
            serde_json::Value::Array(consumed_facts),
        );
        serde_json::Value::Object(object)
    }
}

fn format_u128_identity(value: u128) -> String {
    format!("{value:032x}")
}

fn proof_optimization_certificate_citations(
    function_name: &str,
    certificates: &[trust_cg_opt::proof_opts::OptCertificate],
) -> Vec<ProofOptimizationCertificateCitation> {
    certificates
        .iter()
        .map(|certificate| {
            ProofOptimizationCertificateCitation::from_opt_certificate(function_name, certificate)
        })
        .collect()
}

#[cfg(feature = "verify")]
fn fsym_trust_ir_summary_from_report(
    module_name: &str,
    function_name: &str,
    report: trust_cg_verify::fsym_trust_ir::FsymTrustIrReport,
) -> FsymTrustIrPipelineSummary {
    let diagnostics: Vec<FsymTrustIrPipelineDiagnostic> = report
        .diagnostics
        .iter()
        .filter(|diagnostic| diagnostic.function == function_name)
        .map(|diagnostic| FsymTrustIrPipelineDiagnostic {
            kind: format!("{:?}", diagnostic.kind),
            block: diagnostic.block,
            inst_index: diagnostic.inst_index,
            span: diagnostic.span.map(|span| FsymTrustIrPipelineSourceSpan {
                file: span.file,
                line: span.line,
                col: span.col,
            }),
            message: diagnostic.message.clone(),
            warning: diagnostic.render(
                trust_cg_verify::fsym_trust_ir::FsymTrustIrSeverity::Warning,
                None,
            ),
        })
        .collect();

    let unknown_obligations: Vec<FsymTrustIrPipelineUnknown> = report
        .unknown_obligations
        .iter()
        .filter(|unknown| unknown.function == function_name)
        .map(|unknown| FsymTrustIrPipelineUnknown {
            kind: format!("{:?}", unknown.kind),
            label: unknown.label.clone(),
            block: unknown.block,
            inst_index: unknown.inst_index,
            reason: unknown.reason.clone(),
            warning: unknown.render(None),
        })
        .collect();

    let skipped = report
        .skipped_functions
        .iter()
        .find(|skip| skip.function == function_name)
        .map(|skip| FsymTrustIrPipelineSkip {
            reason: format!("{:?}", skip.reason),
            detail: skip.detail.clone(),
        });

    let scanned = report
        .scanned_function_names
        .iter()
        .any(|name| name == function_name);
    let warning_count =
        diagnostics.len() + unknown_obligations.len() + usize::from(skipped.is_some());

    // Carry deref-coverage gaps for this function so the preflight can fail
    // closed on them (the #49 dropped-obligation class), matching the CLI gate.
    let coverage_errors: Vec<String> = report
        .coverage_errors
        .iter()
        .filter(|err| err.function == function_name)
        .map(|err| err.render(None))
        .collect();

    FsymTrustIrPipelineSummary {
        module_name: module_name.to_owned(),
        function_name: function_name.to_owned(),
        scanned,
        diagnostic_count: diagnostics.len(),
        warning_count,
        unknown_obligation_count: unknown_obligations.len(),
        skipped,
        diagnostics,
        unknown_obligations,
        coverage_error_count: coverage_errors.len(),
        coverage_errors,
    }
}

fn provenance_from_isel_trust_ir_origins(
    isel_func: &trust_cg_lower::isel::ISelFunction,
) -> Option<trust_cg_ir::ProvenanceMap> {
    let mut provenance = trust_cg_ir::ProvenanceMap::new();
    let mut recorded = false;
    let pass = trust_cg_ir::PassId::new("codegen-trust_ir-provenance");
    let mut ir_inst_idx = 0_u32;

    for block_ref in &isel_func.block_order {
        let Some(block) = isel_func.blocks.get(block_ref) else {
            continue;
        };
        for inst_idx in 0..block.insts.len() {
            if let Some(origin) = block.trust_ir_origins.get(inst_idx).copied().flatten() {
                provenance.record_lowering(origin, &[InstId(ir_inst_idx)], pass.clone());
                recorded = true;
            }
            ir_inst_idx = ir_inst_idx.saturating_add(1);
        }
    }

    recorded.then_some(provenance)
}

fn trust_ir_source_locs_from_input(
    input: &trust_cg_lower::Function,
) -> BTreeMap<trust_cg_ir::TrustIrInstId, trust_cg_ir::SourceLoc> {
    let mut source_locs = BTreeMap::new();

    for block_ref in input.layout_order() {
        let Some(block) = input.blocks.get(&block_ref) else {
            continue;
        };
        let trust_ir_origins = input.trust_ir_origins.get(&block_ref);
        for inst_idx in 0..block.instructions.len() {
            let Some(origin) = trust_ir_origins
                .and_then(|origins| origins.get(inst_idx))
                .copied()
                .flatten()
            else {
                continue;
            };
            let Some(loc) = block.source_locs.get(inst_idx).copied().flatten() else {
                continue;
            };
            source_locs.entry(origin).or_insert(loc);
        }
    }

    source_locs
}

/// Line rows from each emitted instruction's own `source_loc`, at the exact
/// byte offset the encoder gives it: pseudo instructions emit no bytes and
/// every other instruction exactly one 4-byte word (the encoder refuses any
/// other width), which is the layout [`encoded_instruction_offsets`] walks.
fn source_line_entries_from_inst_source_locs(
    ir_func: &IrMachFunction,
) -> Vec<crate::dwarf_info::SourceLineEntry> {
    encoded_instruction_offsets(ir_func)
        .into_iter()
        .filter_map(|(inst_id, offset)| {
            let loc = ir_func.insts[inst_id.0 as usize].source_loc.as_ref()?;
            Some(crate::dwarf_info::SourceLineEntry {
                address: u64::from(offset),
                line: loc.line,
                column: loc.col as u16,
                is_stmt: true,
            })
        })
        .collect()
}

fn source_line_entries_from_provenance(
    provenance: &trust_cg_ir::ProvenanceMap,
    trust_ir_source_locs: &BTreeMap<trust_cg_ir::TrustIrInstId, trust_cg_ir::SourceLoc>,
) -> Vec<crate::dwarf_info::SourceLineEntry> {
    provenance
        .source_offsets()
        .filter_map(|(offset, trust_ir_ids)| {
            trust_ir_ids.iter().find_map(|trust_ir_id| {
                trust_ir_source_locs.get(trust_ir_id).map(|loc| {
                    crate::dwarf_info::SourceLineEntry {
                        address: offset as u64,
                        line: loc.line,
                        column: loc.col as u16,
                        is_stmt: true,
                    }
                })
            })
        })
        .collect()
}

fn mark_consecutive_line_statements(
    mut line_entries: Vec<crate::dwarf_info::SourceLineEntry>,
) -> Vec<crate::dwarf_info::SourceLineEntry> {
    let mut previous_line = None;
    for entry in &mut line_entries {
        let is_new_line = previous_line != Some(entry.line);
        entry.is_stmt = is_new_line;
        previous_line = Some(entry.line);
    }
    line_entries
}

fn build_source_line_entries(
    ir_func: &IrMachFunction,
    debug_provenance: Option<(
        &trust_cg_ir::ProvenanceMap,
        &BTreeMap<trust_cg_ir::TrustIrInstId, trust_cg_ir::SourceLoc>,
    )>,
) -> Vec<crate::dwarf_info::SourceLineEntry> {
    if let Some((provenance, trust_ir_source_locs)) = debug_provenance {
        let line_entries = source_line_entries_from_provenance(provenance, trust_ir_source_locs);
        if !line_entries.is_empty() {
            return mark_consecutive_line_statements(line_entries);
        }
    }

    mark_consecutive_line_statements(source_line_entries_from_inst_source_locs(ir_func))
}

#[cfg(feature = "verify")]
pub use trust_cg_verify::CegisPassStats;
pub use trust_cg_verify::CegisRunOutcome;

#[cfg(not(feature = "verify"))]
#[derive(Debug, Clone, Default)]
pub struct CegisPassStats {
    pub functions_seen: u64,
    pub cache_hits: u64,
    pub cache_misses: u64,
    pub cache_puts: u64,
    pub candidates: u64,
    pub verified: u64,
    pub rejected: u64,
    pub budget_exhausted: u64,
    pub solver_calls: u64,
}

/// Statistics and typed terminal state from an enabled CEGIS invocation.
#[derive(Debug, Clone)]
pub struct CegisPassRun {
    pub outcome: CegisRunOutcome,
    pub stats: CegisPassStats,
}

// ---------------------------------------------------------------------------
// Input format detection and module loading
// ---------------------------------------------------------------------------

/// Magic bytes for the binary trust_ir bitcode (.tmbc) format.
///
/// trust-cg owns this envelope and writes it ([`encode_tmbc`]), so the
/// spelling stays here. Which container a buffer claims is decided by
/// trust-ir's shared `codec::sniff_format`, which knows this magic as
/// `TRUST_CG_CONTAINER_MAGIC`; the const assertion below refuses to compile a
/// trust-cg whose writer and that sniff disagree, since every tMBC file this
/// crate wrote would then be refused as "not a binary module".
pub const TMBC_MAGIC: &[u8; 4] = b"tMBC";

const _: () = assert!(
    magic_eq(TMBC_MAGIC, &trust_ir::codec::TRUST_CG_CONTAINER_MAGIC),
    "TMBC_MAGIC must be the tMBC magic trust_ir::codec::sniff_format recognises"
);

/// Byte equality of two magics, usable in a const assertion.
const fn magic_eq<const N: usize>(left: &[u8; N], right: &[u8; N]) -> bool {
    let mut index = 0;
    while index < N {
        if left[index] != right[index] {
            return false;
        }
        index += 1;
    }
    true
}

/// Current version of the .tmbc wire format.
pub const TMBC_VERSION: u32 = 1;

/// Magic bytes of the canonical trust-ir binary module container.
///
/// This is the first 8 bytes of every `trust_ir::binary::serialize_module`
/// output: the artifact trust-ir's own conformance `.tmbc` fixtures, Clean's
/// `--emit trustir-bin`, and the Lean library envelope's `module_binary_hex`
/// all carry, bare, with no `tMBC` envelope around it.
///
/// It is trust-ir's own `codec::TRUST_IR_BINARY_MAGIC`, the constant trust-ir's
/// binary codec reads and writes and its `codec::sniff_format` matches, so the
/// magic is spelled once (roadmap WS4.9 / WS7.4, finding F-115). trust-cg never
/// compares against it to choose a container; [`decode_binary`] asks
/// `sniff_format`. It stays public for callers that build or inspect a bare
/// container.
pub const TRUST_IR_BINARY_MAGIC: &[u8; 8] = &trust_ir::codec::TRUST_IR_BINARY_MAGIC;

/// The named refusal for bytes that are neither binary container.
///
/// Callers and tests match on this phrase, so it is a constant.
pub const NOT_A_BINARY_MODULE: &str = "neither a TRUST_IR module nor a tMBC envelope";

/// The 8-byte magic of a trust-ir level-S TEMPLATE blob (amendment S, wire
/// v57; `trust_ir::binary::serialize_template`), spelled by trust-ir.
///
/// A template is not a module: a template consumer instantiates it into one,
/// and a module consumer refuses it by this magic, never decoding any of it
/// (trust-ir's must-refuse row `template_blob_is_not_a_module`). trust-cg
/// consumes no template.
pub const TRUST_IS_TEMPLATE_MAGIC: &[u8; 8] = &trust_ir::codec::TRUST_IS_TEMPLATE_MAGIC;

/// The name every module entry gives a [`TRUST_IS_TEMPLATE_MAGIC`] input,
/// inside its [`NOT_A_BINARY_MODULE`] refusal. A constant: tests match on it.
pub const TEMPLATE_IS_NOT_A_MODULE: &str =
    "a trust-ir level-S template blob (TRUST_IS magic), not a module";

/// The banner of trust-ir's template text form (amendment S). Template text is
/// not a module either; the text reader refuses it by name.
pub const TRUST_IR_TEMPLATE_TEXT_HEADER: &str = "; TrustIr template text format";

/// Detected input format for trust_ir module files.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum InputFormat {
    /// JSON wire format (.json).
    Json,
    /// Binary trust_ir module: either the canonical bare `TRUST_IR`
    /// container or trust-cg's `tMBC` envelope around it (.tmbc). The
    /// container is decided by magic at decode time, see [`decode_binary`].
    Tmbc,
    /// Human-readable text format (.trust_ir), produced by
    /// `trust_ir::Module`'s `Display` impl and parsed by `trust_ir::parser`.
    TrustIr,
}

/// Format selection mode, used when the caller wants either explicit
/// choice or the legacy auto-detect behaviour.
///
/// `Tmbc`, `Json`, and `Text` force the corresponding parser and ignore
/// both the file extension and any magic-byte mismatch until decode.
/// `Auto` restores the pre-#414 behaviour: prefer `.tmbc`/`.json`/`.trust_ir`
/// by extension, then sniff magic bytes, finally fall back to JSON.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FormatMode {
    /// Force binary trust_ir bitcode (.tmbc).
    Tmbc,
    /// Force JSON wire format.
    Json,
    /// Force human-readable `.trust_ir` text format (#413).
    ///
    /// The text format is produced by `trust_ir::Module`'s `Display` impl
    /// and parsed by `trust_ir::parser::parse_module`. The parser is
    /// gated behind the upstream `parser` feature, which Trust Codegen now
    /// enables in `[workspace.dependencies]`.
    Text,
    /// Auto-detect by extension and magic bytes (legacy behaviour).
    Auto,
}

/// Detect the input format of a trust_ir module file (legacy auto-detect).
///
/// Checks file extension first (`.tmbc`, `.trust_ir`, or `.json`). For
/// unknown extensions, reads the leading bytes and asks trust-ir's
/// `codec::sniff_format` whether they claim either binary container
/// (`TRUST_IR` or `tMBC`) or a level-S template blob (`TRUST_IS`, sent to the
/// binary reader to be refused by name); otherwise, sniffs for the text-format header
/// `; TrustIr text format` (produced by `trust_ir::Module`'s `Display` impl).
///
/// Only the binary decision is delegated. The text-or-JSON fallback keeps its
/// own rule (it also takes an unquoted `module ` prefix, which `sniff_format`
/// does not, and falls back to JSON rather than to "unknown"), so adopting
/// the shared sniff changes no text or JSON dispatch.
///
/// Prefer `load_module_as` for new code: binary `.tmbc` is the intended default and JSON input is
/// a debug-only opt-in.
pub fn detect_input_format(path: &std::path::Path) -> InputFormat {
    match path.extension().and_then(|ext| ext.to_str()) {
        Some("tmbc") => return InputFormat::Tmbc,
        Some("json") => return InputFormat::Json,
        Some("trust_ir") => return InputFormat::TrustIr,
        _ => {}
    }

    // Fall back to magic-byte detection. trust_ir text-format modules start
    // with the exact comment `; trust_ir text format v1` (see
    // `trust_ir::display`). We treat any leading `;` trust_ir header or
    // `module ` prefix as a text-format hint, then fall back to JSON.
    //
    // The sniff buffer MUST be at least as long as the longest needle: the
    // `; trust_ir text format` header is 22 bytes (it was only 18 bytes under
    // the legacy `; tmir text format` name, so the old 20-byte buffer silently
    // stopped matching after the tmir -> trust_ir rename — a 20-byte slice can
    // never `starts_with` a 22-byte needle). We also use a short-read-tolerant
    // fill loop instead of `read_exact` so that short-but-valid text modules
    // (e.g. `module "x"`) are sniffed rather than misclassified as JSON on EOF.
    let mut magic = [0u8; 32];
    let mut filled = 0usize;
    if let Ok(mut file) = std::fs::File::open(path) {
        use std::io::Read;
        while filled < magic.len() {
            match file.read(&mut magic[filled..]) {
                Ok(0) => break,
                Ok(n) => filled += n,
                Err(ref err) if err.kind() == std::io::ErrorKind::Interrupted => continue,
                Err(_) => break,
            }
        }
    }
    let magic = &magic[..filled];
    // A template blob goes to the binary reader, which refuses it by name.
    if routes_to_binary_reader(magic) {
        return InputFormat::Tmbc;
    }
    if is_trust_ir_text_header(magic)
        || magic.starts_with(TRUST_IR_TEMPLATE_TEXT_HEADER.as_bytes())
        || magic.starts_with(b"module ")
    {
        return InputFormat::TrustIr;
    }
    InputFormat::Json
}

/// True if `prefix` begins with a trust_ir text-format header comment.
///
/// Accepts both the snake_case `; trust_ir text format` spelling (used by the
/// `.trust_ir` extension, the `--emit-trust_ir` flag, and vendored conformance
/// fixtures) and the CamelCase `; TrustIr text format` spelling emitted by the
/// upstream `trust_ir::Module` `Display` impl, so the loader recognises files
/// produced by any toolchain version regardless of header styling drift.
fn is_trust_ir_text_header(prefix: &[u8]) -> bool {
    prefix.starts_with(b"; trust_ir text format") || prefix.starts_with(b"; TrustIr text format")
}

/// Load a trust_ir module from a file using the legacy auto-detect path.
///
/// Kept for in-tree callers that still want the old behaviour. The CLI
/// now uses [`load_module_as`] and defaults to binary `.tmbc`.
pub fn load_module(path: &std::path::Path) -> Result<trust_ir::Module, PipelineError> {
    load_module_as(path, FormatMode::Auto)
}

/// Load a trust_ir module from a file with an explicit format selection.
///
/// - `FormatMode::Tmbc`: parse the file as a binary trust_ir module, either
///   the canonical bare `TRUST_IR` container or a `tMBC` envelope (see
///   [`decode_binary`]). If neither magic matches, return a clear
///   `PipelineError::ModuleIo` error that names the `--format=json` CLI escape
///   hatch.
/// - `FormatMode::Json`: parse the file as a JSON-serialised
///   `trust_ir::Module`, regardless of extension.
/// - `FormatMode::Text`: parse the file as a human-readable `.trust_ir`
///   text module via `trust_ir::parser::parse_module` (#413).
/// - `FormatMode::Auto`: preserve the pre-#414 auto-detect behaviour
///   (extension + magic-byte sniffing, JSON fallback; now also
///   recognises `.trust_ir`).
pub fn load_module_as(
    path: &std::path::Path,
    mode: FormatMode,
) -> Result<trust_ir::Module, PipelineError> {
    match mode {
        FormatMode::Tmbc => {
            let bytes =
                crate::resource_limits::read_file_bounded(path).map_err(PipelineError::ModuleIo)?;
            let claim = sniff_format(&bytes);
            if !is_binary_container(claim) {
                return Err(PipelineError::ModuleIo(format!(
                    "'{}' is {}; the CLI defaults to binary trust_ir input. Pass \
                     `--format=json` if this file is a trust_ir JSON wire-format module, \
                     `--format=text` if it is `.trust_ir` text, or regenerate it with \
                     `trust_ir::binary::serialize_module`.",
                    path.display(),
                    not_a_binary_module(&bytes, claim)
                )));
            }
            decode_binary(&bytes)
        }
        FormatMode::Json => {
            let json =
                crate::resource_limits::read_utf8_bounded(path).map_err(PipelineError::ModuleIo)?;
            serde_json::from_str(&json).map_err(|err: serde_json::Error| {
                PipelineError::ModuleIo(format!("JSON error: {err}"))
            })
        }
        FormatMode::Text => {
            let text =
                crate::resource_limits::read_utf8_bounded(path).map_err(PipelineError::ModuleIo)?;
            parse_trust_ir_text(&text)
        }
        FormatMode::Auto => match detect_input_format(path) {
            InputFormat::Json => {
                let json = crate::resource_limits::read_utf8_bounded(path)
                    .map_err(PipelineError::ModuleIo)?;
                serde_json::from_str(&json).map_err(|err: serde_json::Error| {
                    PipelineError::ModuleIo(format!("JSON error: {err}"))
                })
            }
            InputFormat::Tmbc => {
                let bytes = crate::resource_limits::read_file_bounded(path)
                    .map_err(PipelineError::ModuleIo)?;
                decode_binary_container(&bytes).map_err(|message| {
                    PipelineError::ModuleIo(format!("'{}': {message}", path.display()))
                })
            }
            InputFormat::TrustIr => {
                let text = crate::resource_limits::read_utf8_bounded(path)
                    .map_err(PipelineError::ModuleIo)?;
                parse_trust_ir_text(&text)
            }
        },
    }
}

/// Load a trust_ir module from in-memory bytes, auto-detecting the format.
///
/// Bytes starting with either binary container magic (`TRUST_IR` or `tMBC`)
/// are decoded by [`decode_binary`], and a level-S template blob
/// ([`TRUST_IS_TEMPLATE_MAGIC`]) is refused there by name. UTF-8 text that
/// begins with `; TrustIr text format` or `module ` is parsed as `.trust_ir`
/// text (#413). Otherwise the bytes are interpreted as a UTF-8 JSON string.
pub fn load_module_from_bytes(bytes: &[u8]) -> Result<trust_ir::Module, PipelineError> {
    if routes_to_binary_reader(bytes) {
        return decode_binary(bytes);
    }
    let text =
        std::str::from_utf8(bytes).map_err(|err| PipelineError::ModuleIo(err.to_string()))?;
    let trimmed = text.trim_start();
    if is_trust_ir_text_header(trimmed.as_bytes())
        || trimmed.starts_with(TRUST_IR_TEMPLATE_TEXT_HEADER)
        || trimmed.starts_with("module ")
    {
        return parse_trust_ir_text(text);
    }
    serde_json::from_str(text)
        .map_err(|err: serde_json::Error| PipelineError::ModuleIo(format!("JSON error: {err}")))
}

/// Parse a `.trust_ir` human-readable text-format module via
/// `trust_ir::parser::parse_module` (#413).
///
/// Requires the `parser` feature on the upstream `trust_ir` crate, which
/// Trust Codegen's `[workspace.dependencies]` now enables.
pub fn parse_trust_ir_text(text: &str) -> Result<trust_ir::Module, PipelineError> {
    if text.trim_start().starts_with(TRUST_IR_TEMPLATE_TEXT_HEADER) {
        return Err(PipelineError::ModuleIo(format!(
            "the input is trust-ir template text (`{TRUST_IR_TEMPLATE_TEXT_HEADER}`): \
             {TEMPLATE_IS_NOT_A_MODULE}"
        )));
    }
    if text.as_bytes().starts_with(TRUST_IS_TEMPLATE_MAGIC) {
        return Err(PipelineError::ModuleIo(format!(
            "the input is a trust-ir template blob (`TRUST_IS` magic), not text: \
             {TEMPLATE_IS_NOT_A_MODULE}"
        )));
    }
    trust_ir::parser::parse_module(text)
        .map_err(|err| PipelineError::ModuleIo(format!(".trust_ir parse error: {err}")))
}

/// Render a `trust_ir::Module` to `.trust_ir` human-readable text via its
/// `Display` impl (always on in upstream; see `trust_ir::display`).
///
/// The returned string round-trips through `trust_ir::parser::parse_module`.
pub fn encode_trust_ir_text(module: &trust_ir::Module) -> String {
    format!("{}", module)
}

/// Serialize a `trust_ir::Module` as `.trust_ir` text and write it to disk (#413).
pub fn save_module_to_trust_ir_text(
    module: &trust_ir::Module,
    path: &std::path::Path,
) -> Result<(), PipelineError> {
    let text = encode_trust_ir_text(module);
    std::fs::write(path, text).map_err(|e| {
        PipelineError::ModuleIo(format!(
            "failed to write .trust_ir text file {}: {e}",
            path.display()
        ))
    })
}

// ---------------------------------------------------------------------------
// Binary trust_ir bitcode (.tmbc) codec
// ---------------------------------------------------------------------------

/// True if the auto-detecting entries hand `prefix` to [`decode_binary`]:
/// trust-ir's shared `codec::sniff_format` (exact prefixes, no whitespace
/// skipping) reads it as either binary container, the canonical bare
/// `TRUST_IR` module or trust-cg's `tMBC` envelope, or as a level-S template
/// blob (`TemplateBinary`, the `TRUST_IS` magic), which [`decode_binary`]
/// refuses by name ([`TEMPLATE_IS_NOT_A_MODULE`]) and never decodes.
fn routes_to_binary_reader(prefix: &[u8]) -> bool {
    let claim = sniff_format(prefix);
    is_binary_container(claim) || claim == Some(SniffedFormat::TemplateBinary)
}

/// True if a `sniff_format` claim names one of the two binary containers.
fn is_binary_container(claim: Option<SniffedFormat>) -> bool {
    matches!(
        claim,
        Some(SniffedFormat::Binary | SniffedFormat::TrustCgContainer)
    )
}

/// The [`NOT_A_BINARY_MODULE`] refusal text for `bytes`: the first 8 bytes;
/// for a level-S template blob (the sniff's `TemplateBinary`, i.e. the
/// [`TRUST_IS_TEMPLATE_MAGIC`]) the name [`TEMPLATE_IS_NOT_A_MODULE`]; and,
/// when trust-ir's sniff reads the bytes as JSON or text, that claim, so the
/// caller can see which `--format` the file wanted.
fn not_a_binary_module(bytes: &[u8], claim: Option<SniffedFormat>) -> String {
    let hex = leading_bytes_hex(bytes);
    match claim {
        Some(SniffedFormat::TemplateBinary) => format!(
            "{NOT_A_BINARY_MODULE}: the input is {TEMPLATE_IS_NOT_A_MODULE} (first 8 bytes: {hex})"
        ),
        Some(claim @ (SniffedFormat::Json | SniffedFormat::Text)) => format!(
            "{NOT_A_BINARY_MODULE} (first 8 bytes: {hex}; the bytes read as {})",
            claim.describe()
        ),
        _ => format!("{NOT_A_BINARY_MODULE} (first 8 bytes: {hex})"),
    }
}

/// Render up to the first 8 bytes of `bytes` as space-separated hex, for
/// the [`NOT_A_BINARY_MODULE`] refusal.
fn leading_bytes_hex(bytes: &[u8]) -> String {
    let shown = &bytes[..bytes.len().min(TRUST_IR_BINARY_MAGIC.len())];
    if shown.is_empty() {
        return "none, the input is empty".to_string();
    }
    shown
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<Vec<_>>()
        .join(" ")
}

/// Decode a binary trust_ir module, choosing the container by magic.
///
/// The magic is read by trust-ir's `codec::sniff_format`, the one spelling of
/// the rule that trust-ir's own `trust-ir` CLI also reads (at the pinned
/// revision; `trust-ir-fmt` and `trust-ir-diff` adopt it in roadmap WS4.13),
/// so trust-cg and that CLI cannot disagree about which bytes are which
/// container:
///
/// - `TRUST_IR`: the canonical bare container written by
///   `trust_ir::binary::serialize_module`. The whole buffer goes to
///   `trust_ir::binary::deserialize_module_with_wire_version`, so the pinned
///   reader's own version window, ambiguous-lineage refusal (v26..=v28) and
///   trailing-byte check all apply unchanged, and the declared version then
///   holds the producer to its stamping rule
///   ([`PipelineError::ProducerOmittedBodyGate`]).
/// - `tMBC`: trust-cg's envelope around that same payload, decoded by
///   [`decode_tmbc`] exactly as before.
/// - Anything else (a template, JSON, text, MessagePack, unknown or empty
///   bytes) is refused with [`NOT_A_BINARY_MODULE`], the first 8 bytes, and
///   what the sniff read them as when it recognised JSON or text. Nothing is
///   guessed: `TRUST_IS` (a level-S template blob, which the sniff calls
///   `TemplateBinary`, or a one-byte near miss of a module) is refused, never
///   decoded, and named ([`TEMPLATE_IS_NOT_A_MODULE`]); the right magic after
///   a leading byte of whitespace is refused too.
pub fn decode_binary(bytes: &[u8]) -> Result<trust_ir::Module, PipelineError> {
    decode_binary_container(bytes).map_err(PipelineError::ModuleIo)
}

fn decode_binary_container(bytes: &[u8]) -> Result<trust_ir::Module, String> {
    let as_message = |error: PipelineError| match error {
        PipelineError::ModuleIo(message) => message,
        other => other.to_string(),
    };
    match sniff_format(bytes) {
        Some(SniffedFormat::Binary) => {
            decode_trust_ir_payload(bytes, "TRUST_IR module").map_err(as_message)
        }
        Some(SniffedFormat::TrustCgContainer) => decode_tmbc(bytes).map_err(as_message),
        claim => Err(not_a_binary_module(bytes, claim)),
    }
}

/// Decode a binary trust_ir bitcode (.tmbc) buffer into a `trust_ir::Module`.
///
/// Format: `tMBC` magic (4 bytes) + version u32-LE (4 bytes) + `trust_ir::binary`
/// payload (itself prefixed with `TRUST_IR` magic + u32-LE version; see
/// `trust_ir::binary::deserialize_module`).
///
/// The outer `tMBC` envelope is Trust Codegen's transport-layer header. The inner
/// payload is produced by the upstream `trust_ir/binary` feature — a compact,
/// zero-extra-dependency encoding with its own `TRUST_IR` magic and version.
pub fn decode_tmbc(bytes: &[u8]) -> Result<trust_ir::Module, PipelineError> {
    if bytes.len() < 8 {
        return Err(PipelineError::ModuleIo(format!(
            "invalid tMBC data: expected at least 8 bytes, got {}",
            bytes.len()
        )));
    }

    if &bytes[..4] != TMBC_MAGIC {
        return Err(PipelineError::ModuleIo(format!(
            "invalid tMBC magic: expected {:?}, got {:?}",
            TMBC_MAGIC,
            &bytes[..4]
        )));
    }

    let version = u32::from_le_bytes([bytes[4], bytes[5], bytes[6], bytes[7]]);
    if version != TMBC_VERSION {
        return Err(PipelineError::ModuleIo(format!(
            "unsupported tMBC version: {version}"
        )));
    }

    decode_trust_ir_payload(&bytes[8..], "tMBC payload")
}

/// Decode a bare `TRUST_IR` payload with trust-ir's pinned reader (its
/// version window, ambiguous-lineage refusal and trailing-byte check apply
/// unchanged), then hold the PRODUCER to the wire version the header
/// declared: a v41+ blob whose bodied function carries no codegen license was
/// written by a producer that skipped a mandatory stamp, and is refused as
/// [`PipelineError::ProducerOmittedBodyGate`] before any policy can
/// grandfather it. `what` names the container in the deserialization error.
fn decode_trust_ir_payload(payload: &[u8], what: &str) -> Result<trust_ir::Module, PipelineError> {
    let (module, wire_version) = trust_ir::binary::deserialize_module_with_wire_version(payload)
        .map_err(|e| PipelineError::ModuleIo(format!("failed to deserialize {what}: {e}")))?;
    if let Some(error) = trust_ir_build::decoded_provenance_errors(&module, wire_version)
        .into_iter()
        .next()
    {
        return Err(match error {
            trust_ir_build::ValidationError::ProducerOmittedBodyGate {
                name, wire_version, ..
            } => PipelineError::ProducerOmittedBodyGate {
                function: name,
                wire_version,
            },
            // The layer has one rule today; a rule a later pin adds is refused
            // with trust-ir's text rather than dropped -- by the reader, so as
            // a module-decoding refusal (`ModuleIo`), not instruction selection.
            other => PipelineError::ModuleIo(format!("decoded-provenance refusal: {other}")),
        });
    }
    Ok(module)
}

/// Encode a `trust_ir::Module` into binary trust_ir bitcode (.tmbc) format.
///
/// Format: `tMBC` magic (4 bytes) + version u32-LE (4 bytes) + `trust_ir::binary`
/// payload. The inner payload is produced by `trust_ir::binary::serialize_module`,
/// which carries its own `TRUST_IR` magic + u32-LE version header.
///
/// A module carrying a construct that is still ahead of its wire tag (the
/// constructs `trust_ir::Inst::binary_wire_gap` names, or an inlining-chain
/// scope link, the producer-internal `Ty::Error`, a count past the format's
/// `u32`) has no canonical image — trust-ir's writer refuses it — so it is
/// refused by name as [`PipelineError::NoTmbcWireImage`].
pub fn encode_tmbc(module: &trust_ir::Module) -> Result<Vec<u8>, PipelineError> {
    if let Some(blocker) = trust_ir_build::wire_identity_blocker(module) {
        return Err(PipelineError::NoTmbcWireImage(blocker.to_string()));
    }
    let payload = trust_ir::binary::serialize_module(module)
        .map_err(|refusal| PipelineError::NoTmbcWireImage(refusal.to_string()))?;

    let mut buf = Vec::with_capacity(8 + payload.len());
    buf.extend_from_slice(TMBC_MAGIC);
    buf.extend_from_slice(&TMBC_VERSION.to_le_bytes());
    buf.extend_from_slice(&payload);
    Ok(buf)
}

/// Serialize a `trust_ir::Module` and write it to a `.tmbc` file on disk.
pub fn save_module_to_tmbc(
    module: &trust_ir::Module,
    path: &std::path::Path,
) -> Result<(), PipelineError> {
    let buf = encode_tmbc(module)?;
    std::fs::write(path, buf).map_err(|e| {
        PipelineError::ModuleIo(format!("failed to write tMBC file {}: {e}", path.display()))
    })
}

// ---------------------------------------------------------------------------
// CompilationUnit — holds all state across compilation phases
// ---------------------------------------------------------------------------

/// Holds the state of a single function being compiled through the pipeline.
pub struct CompilationUnit {
    /// The function name.
    pub name: String,
    /// The IR-level function (shared model used by opt and frame lowering).
    pub ir_func: IrMachFunction,
    /// Encoded machine code bytes (populated after encoding phase).
    pub code: Vec<u8>,
    /// Pipeline configuration.
    pub config: PipelineConfig,
}

impl CompilationUnit {
    /// Create a new compilation unit from an IR function.
    pub fn new(ir_func: IrMachFunction, config: PipelineConfig) -> Self {
        let name = ir_func.name.clone();
        Self {
            name,
            ir_func,
            code: Vec::new(),
            config,
        }
    }
}

// ---------------------------------------------------------------------------
// Adapter: trust_cg_lower::isel::ISelFunction -> trust_cg_ir::MachFunction
// ---------------------------------------------------------------------------

// NOTE: `map_isel_opcode()` has been ELIMINATED as of issue #73.
//
// The ISel now uses `trust_cg_ir::AArch64Opcode` directly (re-exported via
// `trust_cg_lower::isel::AArch64Opcode`). There is no longer a separate ISel
// opcode enum, so no mapping is needed. The `isel_to_ir` adapter below
// uses `isel_inst.opcode` directly as an `IrOpcode`.

/// Convert ISel's `ISelFunction` to the canonical `trust_cg_ir::MachFunction`.
///
/// Delegates to `ISelFunction::to_ir_func()` which owns the conversion logic
/// (issue #73 consolidation). This thin wrapper is preserved for backward
/// compatibility — new code should call `isel_func.to_ir_func()` directly.
pub fn isel_to_ir(
    isel_func: &trust_cg_lower::isel::ISelFunction,
    _param_types: &[trust_cg_ir::function::Type],
    _return_types: &[trust_cg_ir::function::Type],
) -> IrMachFunction {
    // The ISelFunction::to_ir_func() method derives the IR signature from
    // the ISel's own signature using From<Signature>. The param_types and
    // return_types arguments are now unused — they were only needed when
    // the conversion was done externally.
    isel_func.to_ir_func()
}

// ---------------------------------------------------------------------------
// Adapter: trust_cg_ir::MachFunction -> trust_cg_regalloc::RegAllocFunction
// ---------------------------------------------------------------------------

/// Convert the canonical `trust_cg_ir::MachFunction` to `RegAllocFunction` format.
///
/// The `RegAllocFunction` separates defs from uses for liveness analysis.
/// We use a simple heuristic: first operand is def, rest are uses
/// (for most instructions). Special cases: branches and calls have no defs.
///
/// Uses `From`/`TryFrom` impls from `trust_cg_regalloc::machine_types` for
/// individual block and operand conversions (issue #73 consolidation).
pub fn ir_to_regalloc(
    ir_func: &IrMachFunction,
) -> Result<trust_cg_regalloc::RegAllocFunction, PipelineError> {
    use trust_cg_regalloc::machine_types as ra;

    let mut ra_func = ra::RegAllocFunction {
        name: ir_func.name.clone(),
        insts: Vec::new(),
        blocks: Vec::new(),
        block_order: ir_func.block_order.clone(),
        entry_block: ir_func.entry,
        next_vreg: ir_func.next_vreg,
        next_stack_slot: ir_func.stack_slots.len() as u32,
        stack_slots: BTreeMap::new(),
    };

    // Convert stack slots using From impl (issue #73).
    for (i, slot) in ir_func.stack_slots.iter().enumerate() {
        ra_func.stack_slots.insert(
            trust_cg_ir::types::StackSlotId(i as u32),
            ra::RegAllocStackSlot::from(slot),
        );
    }

    // Convert instructions.
    // InstFlags are unified (issue #73) — same type in trust_cg_ir and trust_cg_regalloc,
    // so flags pass through directly without conversion.
    for ir_inst in &ir_func.insts {
        let (defs, uses, tied_operands) = classify_def_use(ir_inst)?;
        let mut implicit_defs: Vec<PReg> = ir_inst.implicit_defs.to_vec();
        let implicit_uses: Vec<PReg> = ir_inst.implicit_uses.to_vec();

        if is_aarch64_call_boundary(ir_inst) {
            add_aarch64_call_clobbers(&mut implicit_defs);
        }

        ra_func.insts.push(ra::RegAllocInst {
            opcode: ir_inst.opcode as u16,
            defs,
            uses,
            implicit_defs,
            implicit_uses,
            tied_operands,
            flags: ir_inst.flags,
        });
    }

    // Convert blocks using From impl (issue #73).
    for ir_block in &ir_func.blocks {
        ra_func.blocks.push(ra::RegAllocBlock::from(ir_block));
    }

    Ok(ra_func)
}

pub(crate) fn derive_ir_cfg_edges_from_branch_operands(
    ir_func: &IrMachFunction,
) -> Vec<(BlockId, BlockId)> {
    let mut edges = Vec::new();
    for (layout_idx, &block_id) in ir_func.block_order.iter().enumerate() {
        let Some(block) = ir_func.blocks.get(block_id.0 as usize) else {
            continue;
        };
        // Trailing `AlignNop` padding (loop-head alignment inserts it AFTER a
        // block's terminator when the next block is an aligned loop header) is
        // not control flow: skip it when locating the terminator, or a block
        // ending in `B`/`Ret` + padding would spuriously derive a fallthrough
        // edge into the very loop header the padding aligns.
        let last_real_inst = block.insts.iter().rev().find_map(|inst_id| {
            ir_func
                .insts
                .get(inst_id.0 as usize)
                .filter(|inst| !inst.is_pseudo() && inst.opcode != IrOpcode::AlignNop)
        });

        for &inst_id in &block.insts {
            let Some(inst) = ir_func.insts.get(inst_id.0 as usize) else {
                continue;
            };
            // Jump-table dispatch successors: a dense switch reaches its case and
            // default blocks only through the data-driven indirect `Br`, recorded
            // on `ir_func.jump_tables[idx].targets` (referenced by an
            // `Adr ..., JumpTableIndex(idx)` operand) rather than as explicit
            // `Block` operands. Seed those edges so the CFG round-trip keeps the
            // targets reachable and laid out (defect #5).
            for operand in &inst.operands {
                if let Some(jt_idx) = operand.as_jump_table_index()
                    && let Some(jt) = ir_func.jump_tables.get(jt_idx as usize)
                {
                    for &target in &jt.targets {
                        edges.push((block_id, target));
                    }
                }
            }
            if let Some(address) = ir_func.jump_table_address_expansions.get(&inst_id)
                && let Some(table) = ir_func.jump_tables.get(address.table as usize)
            {
                edges.extend(table.targets.iter().map(|&target| (block_id, target)));
            }
            if !inst.is_branch() && !inst.is_terminator() {
                continue;
            }
            for operand in &inst.operands {
                if let IrOperand::Block(target) = operand {
                    edges.push((block_id, *target));
                }
            }
        }

        // The encoder lays blocks out contiguously. Any block without a hard
        // non-fallthrough terminator therefore reaches the next layout block,
        // including the final post-layout form where a redundant `B next` was
        // deliberately elided.
        let hard_terminator = last_real_inst.is_some_and(|inst| {
            inst.is_unconditional_branch()
                || inst.is_return()
                // BRK is not globally flagged as a terminator because exact
                // guard expansions use an intra-block `B.cond; BRK; continue`
                // shape. It is nevertheless non-fallthrough when it is the
                // block's last real instruction.
                || matches!(inst.opcode, IrOpcode::Brk)
                || (inst.is_terminator() && !inst.is_conditional_branch())
        });
        if !hard_terminator && let Some(&fallthrough) = ir_func.block_order.get(layout_idx + 1) {
            edges.push((block_id, fallthrough));
        }
    }

    // The unwinder transfers control from each protected call site to its
    // landing pad without an encoded branch operand.  These edges are still
    // semantic CFG authority for liveness and must match the successors that
    // Invoke lowering records.
    for call_site in &ir_func.eh_metadata.call_sites {
        if let Some(landing_pad) = call_site.landing_pad_block {
            edges.push((call_site.call_block, landing_pad));
        }
    }

    edges
}

/// Reconstruct inter-block CFG edges after branch resolution. AArch64 branch
/// displacements are measured in fixed-width instruction units from the branch
/// itself, so every resolved local target can be mapped back to a laid-out
/// block start exactly. The only permitted non-block targets are the validated
/// `conditional +2; BRK` guard expansions, whose skip stays within the current
/// block and therefore does not create an inter-block liveness edge.
/// Phase 7.25 companion to the proof-only guard expansions: replace every
/// opaque LL/SC atomic pseudo with its exclusive retry loop. Runs after
/// register allocation, spill materialization (which keeps every reload,
/// spill store and emergency register save of a pseudo's operands before or
/// after the pseudo — `materialize_spilled_llsc_pseudo`) and frame lowering,
/// so no spill or reload can be placed inside a load-exclusive/store-exclusive
/// window. The post-expansion window check refuses any that is by name
/// (`[TCG-LLSC-SPILL-WINDOW]`), as the final-stream enforcement does again
/// before encoding.
fn expand_aarch64_llsc_atomics(ir_func: &mut IrMachFunction) -> Result<(), PipelineError> {
    crate::llsc::expand_llsc_atomics(ir_func).map_err(|error| {
        let malformed = PipelineError::MalformedAarch64Function {
            function: ir_func.name.clone(),
            detail: error.to_string(),
        };
        mach_id_refusal_or(ir_func, "LL/SC expansion", malformed)
    })?;
    check_aarch64_exclusive_windows(ir_func)
}

/// [`crate::llsc::check_exclusive_windows`] as a pipeline error.
fn check_aarch64_exclusive_windows(ir_func: &IrMachFunction) -> Result<(), PipelineError> {
    crate::llsc::check_exclusive_windows(ir_func)
        .map(|_| ())
        .map_err(|error| PipelineError::MalformedAarch64Function {
            function: ir_func.name.clone(),
            detail: error.to_string(),
        })
}

/// Greppable tag for a flagged pair spill access, which spill
/// materialization never forms.
pub const AARCH64_PAIR_SPILL_TAG: &str = "[TCG-A64-PAIR-SPILL]";
/// Greppable tag for any other flagged spill access that is not a
/// single-register `LDR`/`STR`.
pub const AARCH64_SPILL_SHAPE_TAG: &str = "[TCG-A64-SPILL-SHAPE]";

/// Refuse every `SPILL_SLOT_ACCESS`-flagged instruction that is not a
/// single-register, non-writeback `LDR`/`STR`.
///
/// Spill materialization forms only those (`make_spill_load` /
/// `make_spill_store`, whose address operands frame lowering rewrites in
/// place), for Q registers as for GPR, D, S and H registers, and no pass
/// fuses two of them: the allocator never forms an `LDP`/`STP` pair spill of
/// two allocated registers into adjacent slots. A flagged pair
/// (`[TCG-A64-PAIR-SPILL]`) or any other flagged shape
/// (`[TCG-A64-SPILL-SHAPE]`) in a final stream therefore did not come from
/// spill materialization, and the frame dataflow net would only decline it,
/// so it is refused by name instead of encoded unchecked.
fn reject_aarch64_unformed_spill_shapes(func: &IrMachFunction) -> Result<(), PipelineError> {
    for (block_idx, block) in func.blocks.iter().enumerate() {
        for (position, &inst_id) in block.insts.iter().enumerate() {
            let Some(inst) = func.insts.get(inst_id.0 as usize) else {
                continue;
            };
            if inst.is_pseudo() || !inst.flags.is_spill_slot_access() {
                continue;
            }
            let single = matches!(inst.opcode, IrOpcode::LdrRI | IrOpcode::StrRI)
                && (2..=3).contains(&inst.operands.len())
                && matches!(
                    inst.operands.first(),
                    Some(IrOperand::PReg(_) | IrOperand::VReg(_))
                );
            if single {
                continue;
            }
            let pair = matches!(
                inst.opcode,
                IrOpcode::LdpRI
                    | IrOpcode::StpRI
                    | IrOpcode::StpPreIndex
                    | IrOpcode::LdpPostIndex
                    | IrOpcode::NeonLdpQPost
                    | IrOpcode::NeonStpQPost
            );
            let (tag, what) = if pair {
                (
                    AARCH64_PAIR_SPILL_TAG,
                    "is a pair spill access; spill materialization never pairs two spilled \
                     registers into adjacent slots",
                )
            } else {
                (
                    AARCH64_SPILL_SHAPE_TAG,
                    "is not a single-register LDR/STR spill access",
                )
            };
            return Err(PipelineError::MalformedAarch64Function {
                function: func.name.clone(),
                detail: format!(
                    "{tag} block {block_idx} instruction #{position} ({:?}) is flagged \
                     SPILL_SLOT_ACCESS but {what}",
                    inst.opcode
                ),
            });
        }
    }
    Ok(())
}

/// Ids of resolved branches that are internal to an expanded LL/SC retry
/// loop (exact template match per block; see [`crate::llsc`]).
fn llsc_internal_branch_ids(ir_func: &IrMachFunction) -> BTreeSet<InstId> {
    let mut internal = BTreeSet::new();
    for &block_id in &ir_func.block_order {
        let real: Vec<(InstId, &IrMachInst)> = ir_func
            .block(block_id)
            .insts
            .iter()
            .map(|&inst_id| (inst_id, ir_func.inst(inst_id)))
            .filter(|(_, inst)| !inst.is_pseudo())
            .collect();
        internal.extend(crate::llsc::llsc_internal_branches(&real));
    }
    internal
}

fn derive_ir_cfg_edges_from_resolved_stream(
    ir_func: &IrMachFunction,
) -> Result<Vec<(BlockId, BlockId)>, String> {
    let mut edges = derive_ir_cfg_edges_from_branch_operands(ir_func);
    let llsc_internal = llsc_internal_branch_ids(ir_func);
    let mut block_starts: BTreeMap<i64, Vec<BlockId>> = BTreeMap::new();
    let mut real_insts: BTreeMap<i64, (BlockId, InstId)> = BTreeMap::new();
    let mut inst_offsets: FxHashMap<InstId, (BlockId, i64)> = FxHashMap::default();
    let mut offset = 0i64;

    for &block_id in &ir_func.block_order {
        block_starts.entry(offset).or_default().push(block_id);
        for &inst_id in &ir_func.block(block_id).insts {
            let inst = ir_func.inst(inst_id);
            if inst.is_pseudo() {
                continue;
            }
            real_insts.insert(offset, (block_id, inst_id));
            inst_offsets.insert(inst_id, (block_id, offset));
            offset += 1;
        }
    }

    for &block_id in &ir_func.block_order {
        for &inst_id in &ir_func.block(block_id).insts {
            let inst = ir_func.inst(inst_id);
            let displacement = match inst.opcode {
                IrOpcode::B | IrOpcode::TailCall => {
                    inst.operands.first().and_then(IrOperand::as_imm)
                }
                IrOpcode::BCond | IrOpcode::Bcc | IrOpcode::Cbz | IrOpcode::Cbnz => {
                    inst.operands.get(1).and_then(IrOperand::as_imm)
                }
                IrOpcode::Tbz | IrOpcode::Tbnz => inst.operands.get(2).and_then(IrOperand::as_imm),
                _ => None,
            };
            let Some(displacement) = displacement else {
                continue;
            };
            let Some(&(source_block, inst_offset)) = inst_offsets.get(&inst_id) else {
                continue;
            };
            // An exactly recognized LL/SC loop branch stays inside its own
            // block (retry edge, compare-failure exit) or falls to the
            // instruction after CLREX; it adds no CFG edge beyond the block's
            // ordinary fallthrough.
            if llsc_internal.contains(&inst_id) {
                continue;
            }
            let target_offset = inst_offset + displacement;

            if let Some(targets) = block_starts.get(&target_offset) {
                // Empty blocks may share a byte offset. Enter the first one in
                // layout order; its fallthrough chain conservatively reaches
                // the remaining co-located blocks.
                if let Some(&target) = targets.first() {
                    edges.push((source_block, target));
                }
                continue;
            }

            let is_conditional = matches!(
                inst.opcode,
                IrOpcode::BCond
                    | IrOpcode::Bcc
                    | IrOpcode::Cbz
                    | IrOpcode::Cbnz
                    | IrOpcode::Tbz
                    | IrOpcode::Tbnz
            );
            let is_guard_skip = is_conditional
                && displacement == 2
                && real_insts
                    .get(&(inst_offset + 1))
                    .is_some_and(|&(trap_block, trap_id)| {
                        trap_block == source_block && ir_func.inst(trap_id).opcode == IrOpcode::Brk
                    });
            if is_guard_skip
                && (real_insts
                    .get(&target_offset)
                    .is_some_and(|&(target_block, _)| target_block == source_block)
                    || target_offset == offset)
            {
                continue;
            }

            if let Some(&(target_block, _)) = real_insts.get(&target_offset) {
                return Err(format!(
                    "resolved branch instruction {:?} in {:?} targets the middle of {:?}",
                    inst_id, source_block, target_block
                ));
            }
            if inst.opcode == IrOpcode::TailCall {
                // A resolved direct tail call may target another function and
                // has no successor within this MachFunction.
                continue;
            }
            return Err(format!(
                "resolved branch instruction {:?} in {:?} targets instruction offset {} outside the laid-out function",
                inst_id, source_block, target_offset
            ));
        }
    }

    Ok(edges)
}

pub(crate) fn install_ir_cfg_edges(ir_func: &mut IrMachFunction, edges: Vec<(BlockId, BlockId)>) {
    for block in &mut ir_func.blocks {
        block.preds.clear();
        block.succs.clear();
    }

    for (from, to) in edges {
        let from_idx = from.0 as usize;
        let to_idx = to.0 as usize;
        if from_idx >= ir_func.blocks.len() || to_idx >= ir_func.blocks.len() {
            continue;
        }
        if !ir_func.blocks[from_idx].succs.contains(&to) {
            ir_func.blocks[from_idx].succs.push(to);
        }
        if !ir_func.blocks[to_idx].preds.contains(&from) {
            ir_func.blocks[to_idx].preds.push(from);
        }
    }
}

fn reconstruct_aarch64_resolved_cfg(ir_func: &IrMachFunction) -> Result<IrMachFunction, String> {
    let mut reconstructed = ir_func.clone();
    let edges = derive_ir_cfg_edges_from_resolved_stream(&reconstructed)?;
    install_ir_cfg_edges(&mut reconstructed, edges);
    Ok(reconstructed)
}

fn rebuild_ir_cfg_edges_from_branch_operands(ir_func: &mut IrMachFunction) {
    let edges = derive_ir_cfg_edges_from_branch_operands(ir_func);
    install_ir_cfg_edges(ir_func, edges);
}

fn add_aarch64_call_clobbers(implicit_defs: &mut Vec<PReg>) {
    let mut clobbers: Vec<PReg> = trust_cg_regalloc::aarch64_caller_saved_regs()
        .into_iter()
        .collect();
    clobbers.sort_by_key(|preg| preg.encoding());

    for preg in clobbers {
        if !implicit_defs.contains(&preg) {
            implicit_defs.push(preg);
        }
    }
}

/// Structural AArch64 call boundary. Do not trust mutable `InstFlags` for
/// allocation or argument authority: opcode identity survives every MachIR
/// adapter, and `TailCall` is the only branch form that consumes call args.
fn is_aarch64_call_boundary(inst: &IrMachInst) -> bool {
    matches!(
        inst.opcode,
        IrOpcode::Bl | IrOpcode::BL | IrOpcode::Blr | IrOpcode::BLR | IrOpcode::TailCall
    )
}

/// Validate pair intent while original virtual classes and identities remain
/// available. A no-spill allocation can erase an invalid class just as a
/// scratch rewrite can, so this check also belongs before allocation.
fn checked_pair_memory_intent(
    inst: &IrMachInst,
) -> Result<Option<crate::aarch64::encode::PairMemoryDescriptor>, PipelineError> {
    if !matches!(
        inst.opcode,
        IrOpcode::StpRI
            | IrOpcode::LdpRI
            | IrOpcode::StpPreIndex
            | IrOpcode::LdpPostIndex
            | IrOpcode::NeonLdpQPost
            | IrOpcode::NeonStpQPost
    ) {
        return Ok(None);
    }
    crate::aarch64::encode::pair_memory_descriptor(inst)
        .map(Some)
        .map_err(|error| PipelineError::RegAlloc(format!("invalid pair memory intent: {error}")))
}

/// Check narrow RO intent before allocation or scratch assignment can erase
/// virtual classes. Full-width RO instructions retain their separate contract.
fn checked_narrow_register_offset_intent(
    inst: &IrMachInst,
) -> Result<Option<(crate::aarch64::encoding_mem::RegExtend, bool)>, PipelineError> {
    if !matches!(
        inst.opcode,
        IrOpcode::LdrbRO | IrOpcode::LdrhRO | IrOpcode::StrbRO | IrOpcode::StrhRO
    ) {
        return Ok(None);
    }
    crate::aarch64::encode::narrow_register_offset_intent(inst)
        .map(Some)
        .map_err(|error| {
            PipelineError::RegAlloc(format!("invalid narrow register-offset intent: {error}"))
        })
}

/// Classify operands into defs and uses for regalloc.
///
/// Convention:
/// - For most ALU instructions: operand[0] is def, rest are uses
/// - For ordinary stores: all operands are uses (no register def)
/// - For exclusive stores: operand[0] is the status def, rest are uses
/// - For branches/calls/returns: all operands are uses
/// - For loads: operand[0] is def, rest are uses
///
/// Uses `TryFrom<&MachOperand>` for `RegAllocOperand` (issue #73) for the
/// individual operand conversions. The TryFrom impl rejects IR-only variants
/// (FrameIndex, MemOp, Special) that must be lowered before register
/// allocation.
fn classify_def_use(
    inst: &IrMachInst,
) -> Result<
    (
        Vec<trust_cg_regalloc::RegAllocOperand>,
        Vec<trust_cg_regalloc::RegAllocOperand>,
        Vec<(u32, u32)>,
    ),
    PipelineError,
> {
    use trust_cg_regalloc::machine_types::RegAllocOperand as RaOp;

    checked_pair_memory_intent(inst)?;
    checked_narrow_register_offset_intent(inst)?;
    let convert_op = |op: &IrOperand| -> Result<RaOp, PipelineError> {
        RaOp::try_from(op).map_err(|e| PipelineError::InvalidOperand(e.message))
    };

    let (def_positions, use_positions) = classify_operand_positions(inst);
    let defs: Vec<_> = def_positions
        .iter()
        .map(|&pos| convert_op(&inst.operands[pos]))
        .collect::<Result<_, _>>()?;
    let uses: Vec<_> = use_positions
        .iter()
        .map(|&pos| convert_op(&inst.operands[pos]))
        .collect::<Result<_, _>>()?;

    let mut tied_operands = Vec::new();
    for (def_idx, &def_pos) in def_positions.iter().enumerate() {
        if let Some(use_idx) = use_positions.iter().position(|&p| p == def_pos) {
            tied_operands.push((def_idx as u32, use_idx as u32));
        }
    }

    Ok((defs, uses, tied_operands))
}

// NOTE: `convert_ir_flags_to_regalloc()` has been ELIMINATED as of issue #73.
//
// InstFlags are now unified: trust_cg_regalloc re-exports trust_cg_ir::InstFlags
// directly. The bit-for-bit flag conversion function is no longer needed —
// flags pass through directly in ir_to_regalloc().

// ---------------------------------------------------------------------------
// Apply register allocation results back to IR
// ---------------------------------------------------------------------------

fn project_allocated_preg(preg: PReg, class: RegClass) -> Option<PReg> {
    match class {
        RegClass::Gpr64 => match preg_class(preg) {
            RegClass::Gpr64 => Some(preg),
            RegClass::Gpr32 | RegClass::System => gpr32_to_gpr64(preg),
            _ => None,
        },
        RegClass::Gpr32 | RegClass::System => match preg_class(preg) {
            RegClass::Gpr32 | RegClass::System => Some(preg),
            RegClass::Gpr64 => gpr64_to_gpr32(preg),
            _ => None,
        },
        _ if preg_class(preg) == class => Some(preg),
        _ => None,
    }
}

fn allocated_preg_for_vreg(vreg: VReg, allocation: &BTreeMap<VReg, PReg>) -> Option<PReg> {
    allocation
        .get(&vreg)
        .and_then(|&preg| project_allocated_preg(preg, vreg.class))
}

/// Rewrite all VReg operands in the IR function with their allocated PRegs.
pub fn apply_regalloc(ir_func: &mut IrMachFunction, allocation: &BTreeMap<VReg, PReg>) {
    for inst in &mut ir_func.insts {
        for operand in &mut inst.operands {
            if let IrOperand::VReg(vreg) = operand
                && let Some(preg) = allocated_preg_for_vreg(*vreg, allocation)
            {
                *operand = IrOperand::PReg(preg);
            }
            // If not found in allocation, the vreg was spilled.
            // Spill code insertion should have already handled this.
        }
    }
}

fn apply_regalloc_to_regalloc(
    ra_func: &mut trust_cg_regalloc::RegAllocFunction,
    allocation: &BTreeMap<VReg, PReg>,
) {
    fn rewrite_operand(
        operand: &mut trust_cg_regalloc::machine_types::RegAllocOperand,
        allocation: &BTreeMap<VReg, PReg>,
    ) {
        if let trust_cg_regalloc::machine_types::RegAllocOperand::VReg(vreg) = operand
            && let Some(preg) = allocated_preg_for_vreg(*vreg, allocation)
        {
            *operand = trust_cg_regalloc::machine_types::RegAllocOperand::PReg(preg);
        }
    }

    for inst in &mut ra_func.insts {
        for operand in &mut inst.defs {
            rewrite_operand(operand, allocation);
        }
        for operand in &mut inst.uses {
            rewrite_operand(operand, allocation);
        }
    }
}

fn spill_slot_shape(class: RegClass) -> (u32, u32) {
    match class {
        RegClass::Gpr32 | RegClass::Fpr32 | RegClass::System => (4, 4),
        RegClass::Gpr64 | RegClass::Fpr64 => (8, 8),
        RegClass::Fpr128 => (16, 16),
        RegClass::Fpr16 => (2, 2),
        RegClass::Fpr8 => (1, 1),
    }
}

fn ensure_spill_stack_slots(ir_func: &mut IrMachFunction, spills: &[trust_cg_regalloc::SpillInfo]) {
    let Some(max_slot) = spills.iter().map(|spill| spill.slot.0 as usize).max() else {
        return;
    };

    while ir_func.stack_slots.len() <= max_slot {
        ir_func.stack_slots.push(IrStackSlot::new(8, 8));
    }

    for spill in spills {
        let slot_idx = spill.slot.0 as usize;
        assert!(
            !ir_func.stack_slots[slot_idx].is_runtime_sized(),
            "regalloc spill slot {} must not alias a runtime-sized stack slot",
            slot_idx
        );
        let (size, align) = spill_slot_shape(spill.vreg.class);
        ir_func.stack_slots[slot_idx] = IrStackSlot::new(size, align);
    }
}

fn rebuild_stack_slots_from_regalloc(
    ir_func: &mut IrMachFunction,
    ra_func: &trust_cg_regalloc::RegAllocFunction,
) {
    let Some(max_slot) = ra_func.stack_slots.keys().map(|slot| slot.0 as usize).max() else {
        return;
    };

    while ir_func.stack_slots.len() <= max_slot {
        ir_func.stack_slots.push(IrStackSlot::new(8, 8));
    }

    for (slot_id, ra_slot) in &ra_func.stack_slots {
        let slot = match ra_slot.allocation {
            StackSlotAllocationKind::Fixed => IrStackSlot::new(ra_slot.size, ra_slot.align),
            StackSlotAllocationKind::RuntimeSized { size_source } if ra_slot.size > 0 => {
                IrStackSlot::new_dynamic_with_unit(size_source, ra_slot.size, ra_slot.align)
            }
            StackSlotAllocationKind::RuntimeSized { size_source } => {
                IrStackSlot::new_dynamic(size_source, ra_slot.align)
            }
        };
        ir_func.stack_slots[slot_id.0 as usize] = slot;
    }
}

fn scratch_pool_for_class(class: RegClass) -> Result<[PReg; 2], PipelineError> {
    match class {
        RegClass::Gpr64 => Ok([X16, X17]),
        RegClass::Gpr32 | RegClass::System => Ok([W16, W17]),
        RegClass::Fpr128 => Ok([V16, V17]),
        RegClass::Fpr64 => Ok([D16, D17]),
        RegClass::Fpr32 => Ok([S16, S17]),
        RegClass::Fpr16 => Ok([H16, H17]),
        other => Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization does not yet support scratch class {other:?}"
        ))),
    }
}

fn operand_physical_regs(inst: &IrMachInst) -> Vec<PReg> {
    inst.operands
        .iter()
        .filter_map(|operand| match operand {
            IrOperand::PReg(reg) => Some(*reg),
            IrOperand::MemOp { base, .. } => Some(*base),
            _ => None,
        })
        .collect()
}

fn preg_overlaps_any(reg: PReg, regs: &[PReg]) -> bool {
    regs.iter().any(|&other| regs_overlap(reg, other))
}

fn available_scratch_for_class(
    class: RegClass,
    reserved: &[PReg],
    used: &[PReg],
) -> Result<Option<PReg>, PipelineError> {
    let pool = scratch_pool_for_class(class)?;
    Ok(pool.into_iter().find(|&scratch| {
        !preg_overlaps_any(scratch, reserved) && !preg_overlaps_any(scratch, used)
    }))
}

fn scratch_slot_index(preg: PReg) -> Option<usize> {
    match preg {
        p if p == X16 || p == W16 || p == V16 || p == D16 || p == S16 || p == H16 => Some(0),
        p if p == X17 || p == W17 || p == V17 || p == D17 || p == S17 || p == H17 => Some(1),
        _ => None,
    }
}

fn pair_value_scratch(class: RegClass, base_scratch: PReg) -> Result<PReg, PipelineError> {
    let pool = scratch_pool_for_class(class)?;
    pool.into_iter()
        .find(|scratch| !regs_overlap(*scratch, base_scratch))
        .ok_or_else(|| {
            PipelineError::RegAlloc(format!(
                "AArch64 spill materialization cannot find non-overlapping {class:?} pair scratch for base {base_scratch:?}"
            ))
        })
}

fn classify_operand_positions(inst: &IrMachInst) -> (Vec<usize>, Vec<usize>) {
    if has_explicit_atomic_operand_roles(inst.opcode)
        || opcode_has_explicit_writeback_operand_roles(inst.opcode)
    {
        return (
            aarch64_def_operand_positions(inst.opcode, inst.operands.len()),
            aarch64_use_operand_positions(inst.opcode, inst.operands.len()),
        );
    }

    if opcode_uses_all_operands_for_regalloc(inst.opcode, inst.flags) || inst.operands.is_empty() {
        (Vec::new(), (0..inst.operands.len()).collect())
    } else {
        (
            aarch64_def_operand_positions(inst.opcode, inst.operands.len()),
            aarch64_use_operand_positions(inst.opcode, inst.operands.len()),
        )
    }
}

pub(crate) fn aarch64_opcode_requires_lse(opcode: IrOpcode) -> bool {
    is_lse_rmw(opcode) || is_lse_cas(opcode)
}

pub(crate) fn aarch64_opcode_requires_dotprod(opcode: IrOpcode) -> bool {
    opcode == IrOpcode::NeonUdotV
}

/// FEAT_CRC32: the eight `CRC32{B,H,W,X}` / `CRC32C{B,H,W,X}` forms.
pub(crate) fn aarch64_opcode_requires_crc(opcode: IrOpcode) -> bool {
    matches!(
        opcode,
        IrOpcode::Crc32B
            | IrOpcode::Crc32H
            | IrOpcode::Crc32W
            | IrOpcode::Crc32X
            | IrOpcode::Crc32Cb
            | IrOpcode::Crc32Ch
            | IrOpcode::Crc32Cw
            | IrOpcode::Crc32Cx
    )
}

/// Whether one machine instruction uses an H register in an operation that
/// requires FEAT_FP16 scalar data processing.
///
/// Base AArch64 can transport half-precision bit patterns through scalar
/// loads/stores, the portable full-vector ORR copy alias, and H↔S/D FCVT.
/// Copy-lowered identity NOPs are non-encoding and therefore require no ISA
/// feature even though they retain their original H-register operands.
/// Other scalar H-register forms (arithmetic, compare, integer conversion, and
/// FMOV) require FEAT_FP16.
/// Checking actual register classes is necessary because those operations
/// share opcodes with their baseline S/D forms.
pub(crate) fn aarch64_inst_requires_fp16(inst: &IrMachInst) -> bool {
    let uses_fpr16 = inst.operands.iter().any(|operand| match operand {
        IrOperand::VReg(reg) => reg.class == RegClass::Fpr16,
        IrOperand::PReg(reg) => preg_class(*reg) == RegClass::Fpr16,
        _ => false,
    });
    if !uses_fpr16 {
        return false;
    }

    !matches!(
        inst.opcode,
        IrOpcode::Nop
            | IrOpcode::Copy
            | IrOpcode::NeonOrrV
            | IrOpcode::LdrRI
            | IrOpcode::StrRI
            | IrOpcode::LdrRO
            | IrOpcode::StrRO
            | IrOpcode::VolatileLdrRI
            | IrOpcode::VolatileStrRI
            | IrOpcode::FcvtHS
            | IrOpcode::FcvtHD
            | IrOpcode::FcvtSH
            | IrOpcode::FcvtDH
    )
}

fn aarch64_target_machine_contract_error(
    function: &str,
    error: impl std::fmt::Display,
) -> PipelineError {
    PipelineError::Aarch64TargetMachineContract {
        function: function.to_owned(),
        detail: error.to_string(),
    }
}

fn observe_aarch64_output_feature(
    function: &str,
    opcode: IrOpcode,
    feature: AArch64IsaFeature,
    target_machine: Option<&AArch64TargetMachine>,
    required: &mut OutputTargetFeatures<AArch64IsaFeature>,
) -> Result<(), PipelineError> {
    // The target machine is immutable for this walk. Once one instruction has
    // established and admitted a feature, later instructions in the same
    // family add no information and need no repeated domain/subset work.
    if required.requires(feature) {
        return Ok(());
    }
    *required = required
        .require(feature)
        .map_err(|error| aarch64_target_machine_contract_error(function, error))?;

    let Some(target_machine) = target_machine else {
        return Ok(());
    };
    if target_machine.admitted_features().admits(feature) {
        return Ok(());
    }

    let profile = AArch64IsaProfile::from(target_machine.admitted_features()).canonical_name();
    Err(match feature {
        AArch64IsaFeature::Lse => PipelineError::Aarch64LseNotAdmitted {
            function: function.to_owned(),
            opcode,
            profile,
        },
        AArch64IsaFeature::DotProd => PipelineError::Aarch64DotProdNotAdmitted {
            function: function.to_owned(),
            opcode,
            profile,
        },
        AArch64IsaFeature::Fp16 => PipelineError::Aarch64Fp16NotAdmitted {
            function: function.to_owned(),
            opcode,
            profile,
        },
        // No opcode-keyed rule currently REQUIRES LSE2, and that is deliberate
        // rather than an omission: LSE2 is an ATOMICITY RULE, not an instruction
        // set, so the opcode alone cannot say whether it applies. `LdpRI` is
        // emitted both as a 128-bit ATOMIC load (which relies on LSE2) and as
        // ordinary FRAME save/restore (which does not) — an
        // `aarch64_opcode_requires_lse2(opcode)` keyed on the opcode would demand
        // LSE2 of every prologue. The enforcement point is therefore the ISel
        // gate (`lse2_enabled`), which refuses BEFORE emission and knows which
        // use it is selecting. This arm exists so that a future
        // operand/flag-keyed requirement has a typed error to raise, and so the
        // feature domain stays exhaustively matched.
        AArch64IsaFeature::Lse2 => PipelineError::Aarch64Lse2NotAdmitted {
            function: function.to_owned(),
            opcode,
            profile,
        },
        AArch64IsaFeature::Aes
        | AArch64IsaFeature::Bf16
        | AArch64IsaFeature::Crc
        | AArch64IsaFeature::Dit
        | AArch64IsaFeature::Dpb
        | AArch64IsaFeature::Dpb2
        | AArch64IsaFeature::Fcma
        | AArch64IsaFeature::Fhm
        | AArch64IsaFeature::FlagM
        | AArch64IsaFeature::FlagM2
        | AArch64IsaFeature::Frintts
        | AArch64IsaFeature::I8mm
        | AArch64IsaFeature::Jsconv
        | AArch64IsaFeature::Rcpc
        | AArch64IsaFeature::Rcpc2
        | AArch64IsaFeature::Rdm
        | AArch64IsaFeature::Sb
        | AArch64IsaFeature::Sha2
        | AArch64IsaFeature::Sha3 => PipelineError::Aarch64FeatureNotAdmitted {
            function: function.to_owned(),
            opcode,
            feature: feature.name(),
            profile,
        },
    })
}

/// The optional ISA features one machine instruction requires, in a fixed
/// order: the single authority the output-feature scan and the raw JIT
/// install gate share, so the two cannot disagree about an instruction.
pub(crate) fn aarch64_inst_required_features(
    inst: &IrMachInst,
) -> impl Iterator<Item = AArch64IsaFeature> {
    [
        aarch64_opcode_requires_lse(inst.opcode).then_some(AArch64IsaFeature::Lse),
        aarch64_opcode_requires_dotprod(inst.opcode).then_some(AArch64IsaFeature::DotProd),
        aarch64_inst_requires_fp16(inst).then_some(AArch64IsaFeature::Fp16),
        aarch64_opcode_requires_crc(inst.opcode).then_some(AArch64IsaFeature::Crc),
    ]
    .into_iter()
    .flatten()
}

fn observe_aarch64_inst_isa_requirements(
    function: &str,
    inst: &IrMachInst,
    target_machine: Option<&AArch64TargetMachine>,
    required: &mut OutputTargetFeatures<AArch64IsaFeature>,
) -> Result<(), PipelineError> {
    for feature in aarch64_inst_required_features(inst) {
        observe_aarch64_output_feature(function, inst.opcode, feature, target_machine, required)?;
    }
    Ok(())
}

fn opcode_has_explicit_writeback_operand_roles(opcode: IrOpcode) -> bool {
    matches!(
        opcode,
        IrOpcode::NeonLd1Post
            | IrOpcode::NeonLdpQPost
            | IrOpcode::NeonSt1Post
            | IrOpcode::NeonStpQPost
            | IrOpcode::LdrPreIndex
            | IrOpcode::StrPreIndex
            | IrOpcode::LdrPostIndex
            | IrOpcode::StrPostIndex
            | IrOpcode::LdpPostIndex
            | IrOpcode::StpPreIndex
    )
}

fn opcode_uses_all_operands_for_regalloc(
    opcode: IrOpcode,
    flags: trust_cg_ir::inst::InstFlags,
) -> bool {
    if has_explicit_atomic_operand_roles(opcode)
        || opcode_has_explicit_writeback_operand_roles(opcode)
    {
        return false;
    }

    let is_store = flags.contains(trust_cg_ir::inst::InstFlags::WRITES_MEMORY);
    let is_branch = flags.contains(trust_cg_ir::inst::InstFlags::IS_BRANCH);
    let is_return = flags.contains(trust_cg_ir::inst::InstFlags::IS_RETURN);
    let is_call = flags.contains(trust_cg_ir::inst::InstFlags::IS_CALL);
    let is_cmp = matches!(opcode, IrOpcode::CmpRR | IrOpcode::CmpRI | IrOpcode::Fcmp);

    is_store || is_branch || is_return || is_call || is_cmp
}

/// Spill reload `LDR scratch, [slot]`, stamped
/// [`InstFlags::SPILL_SLOT_ACCESS`](trust_cg_ir::inst::InstFlags::SPILL_SLOT_ACCESS)
/// so the final-stream frame dataflow net checks its reaching spill store.
fn make_spill_load(
    scratch: PReg,
    slot: StackSlotId,
    source_loc: Option<trust_cg_ir::inst::SourceLoc>,
) -> IrMachInst {
    let mut load = IrMachInst::new(
        IrOpcode::LdrRI,
        vec![IrOperand::PReg(scratch), IrOperand::StackSlot(slot)],
    );
    load.flags
        .insert(trust_cg_ir::inst::InstFlags::SPILL_SLOT_ACCESS);
    load.source_loc = source_loc;
    load
}

/// Spill store `STR scratch, [slot]`, stamped
/// [`InstFlags::SPILL_SLOT_ACCESS`](trust_cg_ir::inst::InstFlags::SPILL_SLOT_ACCESS).
fn make_spill_store(
    scratch: PReg,
    slot: StackSlotId,
    source_loc: Option<trust_cg_ir::inst::SourceLoc>,
) -> IrMachInst {
    let mut store = IrMachInst::new(
        IrOpcode::StrRI,
        vec![IrOperand::PReg(scratch), IrOperand::StackSlot(slot)],
    );
    store
        .flags
        .insert(trust_cg_ir::inst::InstFlags::SPILL_SLOT_ACCESS);
    store.source_loc = source_loc;
    store
}

fn register_offset_index_scratch(index_class: RegClass) -> Result<(PReg, PReg), PipelineError> {
    match index_class {
        RegClass::Gpr64 => Ok((X17, X17)),
        RegClass::Gpr32 | RegClass::System => Ok((W17, X17)),
        other => Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization does not yet support register-offset index class {other:?}"
        ))),
    }
}

/// log2 of the memory access size for a register-offset load/store whose
/// transfer register (operand 0) has class `access_class`. This is the shift
/// amount the hardware applies when the register-offset S (scale-present) bit
/// is set, and it must equal what the non-spill `LdrRO`/`StrRO` encoder derives
/// from the same operand-0 class (`sf_from_operand` / `fp_size_from_inst` in
/// aarch64/encode.rs): 8-byte access -> 3, 4-byte -> 2, 16-byte -> 4, 2-byte
/// -> 1. Returns `None` (caller fails closed) for classes with no scaled
/// register-offset encoding.
fn register_offset_scale_log2(access_class: RegClass) -> Option<u32> {
    match access_class {
        // 8-byte accesses (encoder size = Double).
        RegClass::Gpr64 | RegClass::Fpr64 | RegClass::System => Some(3),
        // 4-byte accesses (encoder size = Word).
        RegClass::Gpr32 | RegClass::Fpr32 => Some(2),
        // 16-byte / 2-byte FP accesses.
        RegClass::Fpr128 => Some(4),
        RegClass::Fpr16 => Some(1),
        // Fpr8 has no register-offset encoding path here; fail closed.
        RegClass::Fpr8 => None,
    }
}

fn spilled_vreg_at(
    inst: &IrMachInst,
    pos: usize,
    spill_slots: &FxHashMap<VReg, StackSlotId>,
) -> Option<(VReg, StackSlotId)> {
    let Some(IrOperand::VReg(vreg)) = inst.operands.get(pos) else {
        return None;
    };
    spill_slot_for_vreg(*vreg, spill_slots).map(|slot| (*vreg, slot))
}

fn materialize_spilled_register_offset_mem(
    ir_func: &mut IrMachFunction,
    inst_id: InstId,
    inst_snapshot: &IrMachInst,
    use_spill_slots: &FxHashMap<VReg, StackSlotId>,
    def_spill_slots: &FxHashMap<VReg, StackSlotId>,
    new_block_insts: &mut Vec<InstId>,
    debug_info: &mut SpillMaterializationDebugInfo,
) -> Result<bool, PipelineError> {
    // Stores include the narrow register-offset siblings (STRB/STRH) the
    // ext_addr narrow-store fold emits, exactly mirroring the loads below.
    let is_store = matches!(
        inst_snapshot.opcode,
        IrOpcode::StrRO | IrOpcode::StrbRO | IrOpcode::StrhRO
    );
    // Loads include the narrow register-offset siblings (LDRB/LDRH) the
    // ext_addr fold emits. Their access WIDTH is fixed by the opcode (1/2
    // bytes), NOT the transfer class — so both the scale derivation and the
    // decomposed RI opcode below are opcode-driven for the narrow forms.
    let is_load = matches!(
        inst_snapshot.opcode,
        IrOpcode::LdrRO | IrOpcode::LdrbRO | IrOpcode::LdrhRO
    );
    if !is_store && !is_load {
        return Ok(false);
    }

    // Validate the scoped RO producer before either the all-spilled rewrite
    // or generic partial-spill scratch assignment can erase its raw intent.
    // The narrow contract validates physical roles as well as raw VReg classes;
    // full-width RO retains its existing mode and class admission below.
    let (ro_extend, ro_shifted) = if let Some(mode) =
        checked_narrow_register_offset_intent(inst_snapshot)?
    {
        mode
    } else {
        let mode = crate::aarch64::encode::register_offset_mode(inst_snapshot)
            .map_err(|error| PipelineError::RegAlloc(error.to_string()))?;
        for (position, operand) in inst_snapshot.operands[..3].iter().enumerate() {
            let IrOperand::VReg(vreg) = operand else {
                continue;
            };
            let supported = match position {
                0 => matches!(
                    vreg.class,
                    RegClass::Gpr32
                        | RegClass::Gpr64
                        | RegClass::Fpr16
                        | RegClass::Fpr32
                        | RegClass::Fpr64
                        | RegClass::Fpr128
                ),
                1 => vreg.class == RegClass::Gpr64,
                2 => matches!(vreg.class, RegClass::Gpr32 | RegClass::Gpr64),
                _ => unreachable!("three register-offset operands"),
            };
            if !supported {
                return Err(PipelineError::RegAlloc(format!(
                    "AArch64 spill materialization for {:?} does not support register-offset operand[{position}] class {:?}",
                    inst_snapshot.opcode, vreg.class
                )));
            }
        }
        mode
    };

    if inst_snapshot.operands.len() < 3 {
        return Ok(false);
    }

    let Some((base_vreg, base_slot)) = spilled_vreg_at(inst_snapshot, 1, use_spill_slots) else {
        return Ok(false);
    };
    let Some((index_vreg, index_slot)) = spilled_vreg_at(inst_snapshot, 2, use_spill_slots) else {
        return Ok(false);
    };

    let transfer_pos = 0;
    let transfer_spill_slots = if is_store {
        use_spill_slots
    } else {
        def_spill_slots
    };
    let Some((transfer_vreg, transfer_slot)) =
        spilled_vreg_at(inst_snapshot, transfer_pos, transfer_spill_slots)
    else {
        return Ok(false);
    };

    if base_vreg.class != RegClass::Gpr64 {
        return Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization for {:?} requires spilled base operand to be Gpr64, got {:?}",
            inst_snapshot.opcode, base_vreg.class
        )));
    }

    // Decode the register-offset addressing mode from operand[3]. Contract
    // (mirrors the LdrRO/StrRO encoder in aarch64/encode.rs and the ext_addr
    // emitter in trust-cg-opt): operand[3] is a packed immediate
    // `(option << 1) | S`, where `option` selects how the index register is
    // extended before being added to the base
    //   UXTW = 0b010, LSL/UXTX = 0b011, SXTW = 0b110, SXTX = 0b111
    // and `S` (scale-present) means the extended index is shifted left by
    // log2(access_size) — the access size being the width of the transfer
    // register (operand 0), or opcode-fixed for byte/halfword accesses.
    // An absent operand[3] is the default LSL/UXTX with
    // S=0 (i.e. `addr = base + index`).
    let ro_option = ro_extend as u32;

    // Fail closed on any option we do not implement with full confidence.
    // These four are the only encodings the register-offset lowering produces.
    if !matches!(ro_option, 0b010 | 0b011 | 0b110 | 0b111) {
        return Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization for {:?} does not support register-offset extend option 0b{ro_option:03b}",
            inst_snapshot.opcode
        )));
    }

    // The scale amount is log2(access_size). For the narrow forms the access
    // size is fixed by the opcode (LDRB=1 -> 0, LDRH=2 -> 1); for the full-width
    // forms it is derived from the transfer register class exactly as the
    // encoder derives the size field. This MUST match the encoder / ext_addr
    // emitter, otherwise the reconstructed effective address would diverge.
    let ro_scale: u32 = if ro_shifted {
        let log2 = match inst_snapshot.opcode {
            IrOpcode::LdrbRO | IrOpcode::StrbRO => Some(0),
            IrOpcode::LdrhRO | IrOpcode::StrhRO => Some(1),
            _ => register_offset_scale_log2(transfer_vreg.class),
        };
        log2.ok_or_else(|| {
            PipelineError::RegAlloc(format!(
                "AArch64 spill materialization for {:?} cannot derive a register-offset scale for transfer class {:?}",
                inst_snapshot.opcode, transfer_vreg.class
            ))
        })?
    } else {
        0
    };

    let source_loc = inst_snapshot.source_loc;
    let base_scratch = X16;
    let (index_load_scratch, index_addr_scratch) = register_offset_index_scratch(index_vreg.class)?;

    let load_base_id = ir_func.push_inst(make_spill_load(base_scratch, base_slot, source_loc));
    new_block_insts.push(load_base_id);

    let load_index_id =
        ir_func.push_inst(make_spill_load(index_load_scratch, index_slot, source_loc));
    new_block_insts.push(load_index_id);

    // Apply the index extend, then the scale, in the index scratch register so
    // the effective address computed below (base + index_addr_scratch) matches
    // the non-spill register-offset semantics exactly:
    //   addr = base + (extend(index) << scale)
    // The extend/shift operate on `index_addr_scratch` (the 64-bit X view of
    // the scratch the index was loaded into), so this is correct whether the
    // index arrived as a 32-bit (W17) or 64-bit (X17) load.
    match ro_option {
        // UXTW: zero-extend the low 32 bits of the index into 64 bits.
        0b010 => {
            let mut ext = IrMachInst::new(
                IrOpcode::Uxtw,
                vec![
                    IrOperand::PReg(index_addr_scratch),
                    IrOperand::PReg(index_addr_scratch),
                ],
            );
            ext.source_loc = source_loc;
            let ext_id = ir_func.push_inst(ext);
            new_block_insts.push(ext_id);
        }
        // SXTW: sign-extend the low 32 bits of the index into 64 bits.
        0b110 => {
            let mut ext = IrMachInst::new(
                IrOpcode::Sxtw,
                vec![
                    IrOperand::PReg(index_addr_scratch),
                    IrOperand::PReg(index_addr_scratch),
                ],
            );
            ext.source_loc = source_loc;
            let ext_id = ir_func.push_inst(ext);
            new_block_insts.push(ext_id);
        }
        // LSL/UXTX (0b011) and SXTX (0b111): the full 64-bit index is used
        // directly; the extend is the identity on a 64-bit value.
        _ => {}
    }

    if ro_scale > 0 {
        let mut shift = IrMachInst::new(
            IrOpcode::LslRI,
            vec![
                IrOperand::PReg(index_addr_scratch),
                IrOperand::PReg(index_addr_scratch),
                IrOperand::Imm(ro_scale as i64),
            ],
        );
        shift.source_loc = source_loc;
        let shift_id = ir_func.push_inst(shift);
        new_block_insts.push(shift_id);
    }

    if is_store {
        let addr_scratch = X17;
        let add_addr_id = ir_func.push_inst(IrMachInst::new(
            IrOpcode::AddRR,
            vec![
                IrOperand::PReg(addr_scratch),
                IrOperand::PReg(base_scratch),
                IrOperand::PReg(index_addr_scratch),
            ],
        ));
        new_block_insts.push(add_addr_id);

        let value_scratch = scratch_pool_for_class(transfer_vreg.class)?[0];
        let load_value_id =
            ir_func.push_inst(make_spill_load(value_scratch, transfer_slot, source_loc));
        new_block_insts.push(load_value_id);

        // Preserve the ACCESS WIDTH when decomposing to the immediate-offset
        // form, exactly as the load arm below does: a narrow register-offset
        // store must become the matching narrow immediate store (STRB/STRH),
        // never the full-width STR — otherwise it would write 4/8 bytes where
        // the program stores 1/2, smashing the neighbouring bytes.
        let ri_opcode = match inst_snapshot.opcode {
            IrOpcode::StrbRO => IrOpcode::StrbRI,
            IrOpcode::StrhRO => IrOpcode::StrhRI,
            _ => IrOpcode::StrRI,
        };
        let inst = &mut ir_func.insts[inst_id.0 as usize];
        inst.opcode = ri_opcode;
        inst.flags = ri_opcode.default_flags();
        inst.operands = vec![
            IrOperand::PReg(value_scratch),
            IrOperand::PReg(addr_scratch),
            IrOperand::Imm(0),
        ];
    } else {
        let addr_scratch = X16;
        let add_addr_id = ir_func.push_inst(IrMachInst::new(
            IrOpcode::AddRR,
            vec![
                IrOperand::PReg(addr_scratch),
                IrOperand::PReg(base_scratch),
                IrOperand::PReg(index_addr_scratch),
            ],
        ));
        new_block_insts.push(add_addr_id);

        let dst_scratch = scratch_pool_for_class(transfer_vreg.class)?[1];
        // Preserve the ACCESS WIDTH when decomposing to the immediate-offset
        // form: a narrow register-offset load must become the matching narrow
        // immediate load (LDRB/LDRH), never the full-width LDR — otherwise it
        // would read 4 bytes instead of 1/2.
        let ri_opcode = match inst_snapshot.opcode {
            IrOpcode::LdrbRO => IrOpcode::LdrbRI,
            IrOpcode::LdrhRO => IrOpcode::LdrhRI,
            _ => IrOpcode::LdrRI,
        };
        let inst = &mut ir_func.insts[inst_id.0 as usize];
        inst.opcode = ri_opcode;
        inst.flags = ri_opcode.default_flags();
        inst.operands = vec![
            IrOperand::PReg(dst_scratch),
            IrOperand::PReg(addr_scratch),
            IrOperand::Imm(0),
        ];

        let store_dst_id =
            ir_func.push_inst(make_spill_store(dst_scratch, transfer_slot, source_loc));
        new_block_insts.push(inst_id);
        new_block_insts.push(store_dst_id);
        debug_info.record_store(transfer_vreg, transfer_slot, store_dst_id);
        return Ok(true);
    }

    new_block_insts.push(inst_id);
    Ok(true)
}

fn materialize_spilled_store_pair(
    ir_func: &mut IrMachFunction,
    inst_snapshot: &IrMachInst,
    pair: crate::aarch64::encode::PairMemoryDescriptor,
    use_spill_slots: &FxHashMap<VReg, StackSlotId>,
    new_block_insts: &mut Vec<InstId>,
) -> Result<bool, PipelineError> {
    if inst_snapshot.opcode != IrOpcode::StpRI {
        return Ok(false);
    }

    let Some((value0_vreg, value0_slot)) = spilled_vreg_at(inst_snapshot, 0, use_spill_slots)
    else {
        return Ok(false);
    };
    let Some((value1_vreg, value1_slot)) = spilled_vreg_at(inst_snapshot, 1, use_spill_slots)
    else {
        return Ok(false);
    };
    let Some((base_vreg, base_slot)) = spilled_vreg_at(inst_snapshot, 2, use_spill_slots) else {
        return Ok(false);
    };

    if value0_vreg == value1_vreg || value0_vreg == base_vreg || value1_vreg == base_vreg {
        return Ok(false);
    }

    if value0_vreg.class != value1_vreg.class {
        return Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization for StpRI requires matching spilled value classes, got {:?} and {:?}",
            value0_vreg.class, value1_vreg.class
        )));
    }
    if base_vreg.class != RegClass::Gpr64 {
        return Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization for StpRI requires a spilled Gpr64 base, got {:?}",
            base_vreg.class
        )));
    }
    let value_stride = i64::from(pair.element_bytes);
    let base_scratch = X17;
    let value_scratch = pair_value_scratch(value0_vreg.class, base_scratch)?;

    let offset = pair.offset;

    let source_loc = inst_snapshot.source_loc;
    let load_base_id = ir_func.push_inst(make_spill_load(base_scratch, base_slot, source_loc));
    new_block_insts.push(load_base_id);

    if offset != 0 {
        let (opcode, magnitude) = if offset > 0 {
            (IrOpcode::AddRI, offset)
        } else {
            (IrOpcode::SubRI, -offset)
        };
        let adjust_id = push_inst_with_source(
            ir_func,
            opcode,
            vec![
                IrOperand::PReg(base_scratch),
                IrOperand::PReg(base_scratch),
                IrOperand::Imm(magnitude),
            ],
            source_loc,
        );
        new_block_insts.push(adjust_id);
    }

    let load_value0_id = ir_func.push_inst(make_spill_load(value_scratch, value0_slot, source_loc));
    new_block_insts.push(load_value0_id);
    let store_value0_id = push_inst_with_source(
        ir_func,
        IrOpcode::StrRI,
        vec![
            IrOperand::PReg(value_scratch),
            IrOperand::PReg(base_scratch),
            IrOperand::Imm(0),
        ],
        source_loc,
    );
    new_block_insts.push(store_value0_id);

    let load_value1_id = ir_func.push_inst(make_spill_load(value_scratch, value1_slot, source_loc));
    new_block_insts.push(load_value1_id);
    let store_value1_id = push_inst_with_source(
        ir_func,
        IrOpcode::StrRI,
        vec![
            IrOperand::PReg(value_scratch),
            IrOperand::PReg(base_scratch),
            IrOperand::Imm(value_stride),
        ],
        source_loc,
    );
    new_block_insts.push(store_value1_id);

    Ok(true)
}

fn materialize_spilled_load_pair(
    ir_func: &mut IrMachFunction,
    inst_snapshot: &IrMachInst,
    pair: crate::aarch64::encode::PairMemoryDescriptor,
    use_spill_slots: &FxHashMap<VReg, StackSlotId>,
    def_spill_slots: &FxHashMap<VReg, StackSlotId>,
    new_block_insts: &mut Vec<InstId>,
    debug_info: &mut SpillMaterializationDebugInfo,
) -> Result<bool, PipelineError> {
    if inst_snapshot.opcode != IrOpcode::LdpRI {
        return Ok(false);
    }

    let Some((dst0_vreg, dst0_slot)) = spilled_vreg_at(inst_snapshot, 0, def_spill_slots) else {
        return Ok(false);
    };
    let Some((dst1_vreg, dst1_slot)) = spilled_vreg_at(inst_snapshot, 1, def_spill_slots) else {
        return Ok(false);
    };

    if dst0_vreg == dst1_vreg {
        return Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization for LdpRI requires distinct spilled defs in {:?}",
            inst_snapshot
        )));
    }
    if dst0_vreg.class != dst1_vreg.class {
        return Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization for LdpRI requires matching spilled def classes, got {:?} and {:?}",
            dst0_vreg.class, dst1_vreg.class
        )));
    }
    let value_stride = i64::from(pair.element_bytes);
    let offset = pair.offset;

    // PHYSICAL-BASE PAIR (pr28982b loop-carried-pointer miscompile). When the
    // pair BASE is an allocated (non-spilled) register it stays live and needs
    // no reload, yet BOTH paired destinations are spilled. The generic multi-def
    // materialization path keeps both loaded values SIMULTANEOUSLY in the two
    // scratch registers (X16 AND X17) across their two spill stores; the
    // frame-index eliminator then materializes each far spill-slot address in
    // the OTHER scratch, overwriting the still-live second value. (In pr28982b
    // the odd loop-carried pointers result7,9,..,19 were stored as a stack
    // address instead of `input+k`, so every `*ptr` load read 0.) Split the
    // LdpRI into two INDEPENDENT single-value load + spill-store sequences that
    // hold each value in scratch slot 0 only, leaving scratch slot 1 FREE for
    // the eliminator's large-offset address materialization — so no live value
    // is ever clobbered.
    if let IrOperand::PReg(base_preg) = inst_snapshot.operands[2] {
        if preg_class(base_preg) != RegClass::Gpr64 {
            return Ok(false);
        }
        let value_scratch = scratch_pool_for_class(dst0_vreg.class)?[0];
        // The paired-def clobber only arises when the VALUE scratch registers
        // alias the GPR address scratch (X16/X17) that the frame-index
        // eliminator borrows to materialize a far spill-slot offset — i.e. the
        // GPR classes (value scratch X16/W16 & X17/W17). FP pairs load into
        // V/D/S/H 16/17, which never alias the GPR address scratch, so their
        // generic single-`ldp` materialization is already sound (and one fewer
        // instruction); leave it on the generic path untouched.
        if !regs_overlap(value_scratch, X16) && !regs_overlap(value_scratch, X17) {
            return Ok(false);
        }
        if regs_overlap(base_preg, value_scratch) {
            return Err(PipelineError::RegAlloc(format!(
                "AArch64 spill materialization for LdpRI: physical base {base_preg:?} aliases value scratch {value_scratch:?} in {inst_snapshot:?}"
            )));
        }
        let source_loc = inst_snapshot.source_loc;
        for (element_off, dst_vreg, dst_slot) in [
            (offset, dst0_vreg, dst0_slot),
            (offset + value_stride, dst1_vreg, dst1_slot),
        ] {
            // Load this element into the value scratch. A directly-encodable
            // element offset needs one LDR [base, #off]; otherwise compute
            // base+off into the scratch first (|off| is bounded by the pair's
            // imm7 reach plus one stride, so it always fits an ADD/SUB #imm12).
            if (-256..=4095).contains(&element_off) {
                let load_id = push_inst_with_source(
                    ir_func,
                    IrOpcode::LdrRI,
                    vec![
                        IrOperand::PReg(value_scratch),
                        IrOperand::PReg(base_preg),
                        IrOperand::Imm(element_off),
                    ],
                    source_loc,
                );
                new_block_insts.push(load_id);
            } else {
                let (opcode, magnitude) = if element_off >= 0 {
                    (IrOpcode::AddRI, element_off)
                } else {
                    (IrOpcode::SubRI, -element_off)
                };
                let addr_id = push_inst_with_source(
                    ir_func,
                    opcode,
                    vec![
                        IrOperand::PReg(value_scratch),
                        IrOperand::PReg(base_preg),
                        IrOperand::Imm(magnitude),
                    ],
                    source_loc,
                );
                new_block_insts.push(addr_id);
                let load_id = push_inst_with_source(
                    ir_func,
                    IrOpcode::LdrRI,
                    vec![
                        IrOperand::PReg(value_scratch),
                        IrOperand::PReg(value_scratch),
                        IrOperand::Imm(0),
                    ],
                    source_loc,
                );
                new_block_insts.push(load_id);
            }
            let store_id = ir_func.push_inst(make_spill_store(value_scratch, dst_slot, source_loc));
            new_block_insts.push(store_id);
            debug_info.record_store(dst_vreg, dst_slot, store_id);
        }
        return Ok(true);
    }

    // SPILLED-BASE PAIR: the base is itself spilled. Reload it around each
    // element so the store's far-offset address materialization (which clobbers
    // the base scratch) never loses a value.
    let Some((base_vreg, base_slot)) = spilled_vreg_at(inst_snapshot, 2, use_spill_slots) else {
        return Ok(false);
    };
    if dst0_vreg == base_vreg || dst1_vreg == base_vreg {
        return Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization for LdpRI requires distinct spilled defs/base in {:?}",
            inst_snapshot
        )));
    }
    if base_vreg.class != RegClass::Gpr64 {
        return Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization for LdpRI requires a spilled Gpr64 base, got {:?}",
            base_vreg.class
        )));
    }
    let base_scratch = X16;
    let dst_scratch = pair_value_scratch(dst0_vreg.class, base_scratch)?;

    let source_loc = inst_snapshot.source_loc;
    let load_base_id = ir_func.push_inst(make_spill_load(base_scratch, base_slot, source_loc));
    new_block_insts.push(load_base_id);

    if offset != 0 {
        let (opcode, magnitude) = if offset > 0 {
            (IrOpcode::AddRI, offset)
        } else {
            (IrOpcode::SubRI, -offset)
        };
        let adjust_id = push_inst_with_source(
            ir_func,
            opcode,
            vec![
                IrOperand::PReg(base_scratch),
                IrOperand::PReg(base_scratch),
                IrOperand::Imm(magnitude),
            ],
            source_loc,
        );
        new_block_insts.push(adjust_id);
    }

    let load_dst0_id = push_inst_with_source(
        ir_func,
        IrOpcode::LdrRI,
        vec![
            IrOperand::PReg(dst_scratch),
            IrOperand::PReg(base_scratch),
            IrOperand::Imm(0),
        ],
        source_loc,
    );
    new_block_insts.push(load_dst0_id);
    let store_dst0_id = ir_func.push_inst(make_spill_store(dst_scratch, dst0_slot, source_loc));
    new_block_insts.push(store_dst0_id);
    debug_info.record_store(dst0_vreg, dst0_slot, store_dst0_id);

    let reload_base_id = ir_func.push_inst(make_spill_load(base_scratch, base_slot, source_loc));
    new_block_insts.push(reload_base_id);
    if offset != 0 {
        let (opcode, magnitude) = if offset > 0 {
            (IrOpcode::AddRI, offset)
        } else {
            (IrOpcode::SubRI, -offset)
        };
        let readjust_id = push_inst_with_source(
            ir_func,
            opcode,
            vec![
                IrOperand::PReg(base_scratch),
                IrOperand::PReg(base_scratch),
                IrOperand::Imm(magnitude),
            ],
            source_loc,
        );
        new_block_insts.push(readjust_id);
    }

    let load_dst1_id = push_inst_with_source(
        ir_func,
        IrOpcode::LdrRI,
        vec![
            IrOperand::PReg(dst_scratch),
            IrOperand::PReg(base_scratch),
            IrOperand::Imm(value_stride),
        ],
        source_loc,
    );
    new_block_insts.push(load_dst1_id);
    let store_dst1_id = ir_func.push_inst(make_spill_store(dst_scratch, dst1_slot, source_loc));
    new_block_insts.push(store_dst1_id);
    debug_info.record_store(dst1_vreg, dst1_slot, store_dst1_id);

    Ok(true)
}

fn push_inst_with_source(
    ir_func: &mut IrMachFunction,
    opcode: IrOpcode,
    operands: Vec<IrOperand>,
    source_loc: Option<trust_cg_ir::inst::SourceLoc>,
) -> InstId {
    let mut inst = IrMachInst::new(opcode, operands);
    inst.source_loc = source_loc;
    ir_func.push_inst(inst)
}

fn project_scratch_for_result_width(
    scratch: PReg,
    result_class: RegClass,
) -> Result<PReg, PipelineError> {
    project_allocated_preg(scratch, result_class).ok_or_else(|| {
        PipelineError::RegAlloc(format!(
            "AArch64 spill materialization cannot project scratch {scratch:?} to {result_class:?}"
        ))
    })
}

fn materialize_spilled_multiply_accumulate(
    ir_func: &mut IrMachFunction,
    inst_id: InstId,
    inst_snapshot: &IrMachInst,
    use_spill_slots: &FxHashMap<VReg, StackSlotId>,
    def_spill_slots: &FxHashMap<VReg, StackSlotId>,
    new_block_insts: &mut Vec<InstId>,
    debug_info: &mut SpillMaterializationDebugInfo,
) -> Result<bool, PipelineError> {
    let combine_opcode = match inst_snapshot.opcode {
        IrOpcode::Madd => IrOpcode::AddRR,
        IrOpcode::Msub => IrOpcode::SubRR,
        _ => return Ok(false),
    };

    if inst_snapshot.operands.len() < 4 {
        return Ok(false);
    }

    let Some((lhs_vreg, lhs_slot)) = spilled_vreg_at(inst_snapshot, 1, use_spill_slots) else {
        return Ok(false);
    };
    let Some((rhs_vreg, rhs_slot)) = spilled_vreg_at(inst_snapshot, 2, use_spill_slots) else {
        return Ok(false);
    };
    let Some((acc_vreg, acc_slot)) = spilled_vreg_at(inst_snapshot, 3, use_spill_slots) else {
        return Ok(false);
    };

    let mut dst_spill = None;
    let (dst, result_class) = match inst_snapshot.operands[0] {
        IrOperand::PReg(preg) => (preg, preg_class(preg)),
        IrOperand::VReg(vreg) => {
            let Some(slot) = spill_slot_for_vreg(vreg, def_spill_slots) else {
                return Ok(false);
            };
            dst_spill = Some((vreg, slot));
            let [dst_scratch, _] = scratch_pool_for_class(vreg.class)?;
            (dst_scratch, vreg.class)
        }
        ref operand => {
            return Err(PipelineError::RegAlloc(format!(
                "AArch64 spill materialization for {:?} expected register destination, got {:?}",
                inst_snapshot.opcode, operand
            )));
        }
    };

    if !matches!(result_class, RegClass::Gpr32 | RegClass::Gpr64) {
        return Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization for {:?} requires GPR32/GPR64 result, got {:?}",
            inst_snapshot.opcode, result_class
        )));
    }

    let lhs_load_scratch = scratch_pool_for_class(lhs_vreg.class)?[0];
    let rhs_load_scratch = scratch_pool_for_class(rhs_vreg.class)?[1];
    let acc_load_scratch = scratch_pool_for_class(acc_vreg.class)?
        .into_iter()
        .rev()
        .find(|&scratch| {
            project_scratch_for_result_width(scratch, result_class)
                .is_ok_and(|projected| !regs_overlap(projected, dst))
        })
        .ok_or_else(|| {
            PipelineError::RegAlloc(format!(
                "AArch64 spill materialization for {:?} cannot find accumulator scratch avoiding destination {:?}",
                inst_snapshot.opcode, dst
            ))
        })?;
    let lhs_mul_scratch = project_scratch_for_result_width(lhs_load_scratch, result_class)?;
    let rhs_mul_scratch = project_scratch_for_result_width(rhs_load_scratch, result_class)?;
    let acc_combine_scratch = project_scratch_for_result_width(acc_load_scratch, result_class)?;

    let source_loc = inst_snapshot.source_loc;
    let load_lhs_id = ir_func.push_inst(make_spill_load(lhs_load_scratch, lhs_slot, source_loc));
    new_block_insts.push(load_lhs_id);

    let load_rhs_id = ir_func.push_inst(make_spill_load(rhs_load_scratch, rhs_slot, source_loc));
    new_block_insts.push(load_rhs_id);

    {
        let inst = &mut ir_func.insts[inst_id.0 as usize];
        inst.opcode = IrOpcode::MulRR;
        inst.flags = IrOpcode::MulRR.default_flags();
        inst.operands = vec![
            IrOperand::PReg(dst),
            IrOperand::PReg(lhs_mul_scratch),
            IrOperand::PReg(rhs_mul_scratch),
        ];
    }
    new_block_insts.push(inst_id);

    let load_acc_id = ir_func.push_inst(make_spill_load(acc_load_scratch, acc_slot, source_loc));
    new_block_insts.push(load_acc_id);

    let combine_operands = if combine_opcode == IrOpcode::AddRR {
        vec![
            IrOperand::PReg(dst),
            IrOperand::PReg(dst),
            IrOperand::PReg(acc_combine_scratch),
        ]
    } else {
        vec![
            IrOperand::PReg(dst),
            IrOperand::PReg(acc_combine_scratch),
            IrOperand::PReg(dst),
        ]
    };
    let combine_id = push_inst_with_source(ir_func, combine_opcode, combine_operands, source_loc);
    new_block_insts.push(combine_id);

    if let Some((vreg, slot)) = dst_spill {
        let store_id = ir_func.push_inst(make_spill_store(dst, slot, source_loc));
        new_block_insts.push(store_id);
        debug_info.record_store(vreg, slot, store_id);
    }

    Ok(true)
}

/// Materialize a scalar fused multiply-add (`FmaddRR`, `Fd = Fa + Fn*Fm`) whose
/// THREE source operands are all spilled to distinct slots.
///
/// The generic spill path draws reload scratch from the 2-register pool
/// (`D16`/`D17` and their width aliases, see [`scratch_pool_for_class`]). Three
/// DISTINCT spilled sources need three registers live simultaneously, and a
/// single-rounding FMADD cannot be split into `FMUL`+`FADD` without changing the
/// result (double rounding — a bit-level miscompile). So the generic path runs
/// out of scratch and fails. This handler recovers the third register from the
/// FMADD DESTINATION.
///
/// SOUNDNESS — the dest-reuse argument:
///   * `FmaddRR` writes `Rd` as a PURE def: it reads only `Rn`/`Rm`/`Ra` (the
///     addend is the separate operand `Ra`, NOT the prior `Rd`). It is
///     deliberately absent from `has_tied_def_use` — unlike the accumulating
///     `NeonFmla`/`NeonFmls`. So loading a source into `Rd` before the FMADD
///     destroys nothing the instruction still needs.
///   * The scratch registers `D16`/`D17` (and their `V`/`S`/`H` aliases) are
///     RESERVED — never present in `aarch64_allocatable_regs()`. Hence the
///     allocated destination preg can never BE a scratch register: the three
///     targets {scratch_n, scratch_m, dst} are pairwise distinct, so the three
///     reloads cannot clobber one another regardless of order. (A defensive
///     guard below fails closed should that reservation invariant ever change.)
///   * Engages ONLY when all three sources are spilled AND are three DISTINCT
///     vregs. That means every source operand is being reloaded — there is no
///     non-spilled source register that `dst` could alias and corrupt, so the
///     classic dest-reuse precondition ("dst read by no surviving source") holds
///     vacuously. With <=2 distinct spilled sources the generic 2-scratch path
///     already succeeds, so we defer to keep byte-identical output.
///
/// The rewrite (Fpr64 shown; class-general):
/// ```text
///   ldr   D16, [slot(Rn)]
///   ldr   D17, [slot(Rm)]
///   ldr   Rd,  [slot(Ra)]        ; Rd's old value is dead (pure def)
///   fmadd Rd,  D16, D17, Rd      ; Rd = Rd(Ra) + D16(Rn)*D17(Rm)
/// ```
///
/// A spilled-VReg destination (no physical home to borrow) is left to the
/// generic path, which fail-closes with the documented "ran out of scratch"
/// error: three distinct spilled sources plus a spilled def genuinely exceed the
/// scratch budget for a fused, un-splittable op.
fn materialize_spilled_fused_multiply_add(
    ir_func: &mut IrMachFunction,
    inst_id: InstId,
    inst_snapshot: &IrMachInst,
    use_spill_slots: &FxHashMap<VReg, StackSlotId>,
    new_block_insts: &mut Vec<InstId>,
) -> Result<bool, PipelineError> {
    if inst_snapshot.opcode != IrOpcode::FmaddRR {
        return Ok(false);
    }
    if inst_snapshot.operands.len() != 4 {
        return Ok(false);
    }

    // Destination must be a physical register we can borrow as the third
    // reload target. A spilled-VReg destination has no physical home to reuse.
    let IrOperand::PReg(dst) = inst_snapshot.operands[0] else {
        return Ok(false);
    };

    // All three sources (Rn, Rm, Ra at operand positions 1, 2, 3) must be
    // spilled — otherwise the generic 2-scratch path already suffices.
    let Some((n_vreg, n_slot)) = spilled_vreg_at(inst_snapshot, 1, use_spill_slots) else {
        return Ok(false);
    };
    let Some((m_vreg, m_slot)) = spilled_vreg_at(inst_snapshot, 2, use_spill_slots) else {
        return Ok(false);
    };
    let Some((a_vreg, a_slot)) = spilled_vreg_at(inst_snapshot, 3, use_spill_slots) else {
        return Ok(false);
    };

    // Engage ONLY when the pool is genuinely insufficient: three DISTINCT
    // spilled source vregs. A repeated vreg reuses one scratch (the generic
    // path's `assigned` map), leaving <=2 distinct sources it can satisfy — so
    // defer to it and stay byte-identical.
    if n_vreg == m_vreg || n_vreg == a_vreg || m_vreg == a_vreg {
        return Ok(false);
    }

    // FMADD operands share one FP width; the destination shares it too. Fail
    // closed on any class mismatch rather than emit a mixed-width reload.
    let class = n_vreg.class;
    if m_vreg.class != class || a_vreg.class != class {
        return Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization for FmaddRR requires matching source classes, got {:?}/{:?}/{:?}",
            n_vreg.class, m_vreg.class, a_vreg.class
        )));
    }
    if preg_class(dst) != class {
        return Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization for FmaddRR requires destination class {:?} to match source class {:?}",
            preg_class(dst),
            class
        )));
    }

    let [scratch_n, scratch_m] = scratch_pool_for_class(class)?;

    // Defensive soundness guard: the destination MUST NOT alias either scratch
    // register. This holds by construction (the scratch aliases are reserved out
    // of `aarch64_allocatable_regs()`), but assert it so a future change to the
    // reserved set fails closed instead of silently clobbering a reload.
    if regs_overlap(dst, scratch_n) || regs_overlap(dst, scratch_m) {
        return Err(PipelineError::RegAlloc(format!(
            "AArch64 spill materialization for FmaddRR: destination {dst:?} aliases a reserved scratch register ({scratch_n:?}/{scratch_m:?})"
        )));
    }

    let source_loc = inst_snapshot.source_loc;

    // Reload the two multiplicands into the scratch pool and the addend into the
    // (pure-def, now-dead) destination register. The three targets are pairwise
    // distinct, so load order is immaterial for correctness.
    let load_n = ir_func.push_inst(make_spill_load(scratch_n, n_slot, source_loc));
    new_block_insts.push(load_n);
    let load_m = ir_func.push_inst(make_spill_load(scratch_m, m_slot, source_loc));
    new_block_insts.push(load_m);
    let load_a = ir_func.push_inst(make_spill_load(dst, a_slot, source_loc));
    new_block_insts.push(load_a);

    {
        let inst = &mut ir_func.insts[inst_id.0 as usize];
        inst.operands = vec![
            IrOperand::PReg(dst),
            IrOperand::PReg(scratch_n),
            IrOperand::PReg(scratch_m),
            IrOperand::PReg(dst),
        ];
    }
    new_block_insts.push(inst_id);

    Ok(true)
}

#[cfg(test)]
fn materialize_spilled_operands(
    ir_func: &mut IrMachFunction,
    spills: &[trust_cg_regalloc::SpillInfo],
) -> Result<(), PipelineError> {
    let spill_slots: FxHashMap<VReg, StackSlotId> = spills
        .iter()
        .map(|spill| (spill.vreg, spill.slot))
        .collect();
    if spill_slots.is_empty() {
        return Ok(());
    }

    let mut sites: FxHashMap<InstId, SpillMaterializationSite> = FxHashMap::default();
    for block in &ir_func.blocks {
        for &inst_id in &block.insts {
            let inst = ir_func.inst(inst_id);
            let (def_positions, use_positions) = classify_operand_positions(inst);

            for &pos in &use_positions {
                let Some((vreg, slot)) = spilled_vreg_at(inst, pos, &spill_slots) else {
                    continue;
                };
                sites.entry(inst_id).or_default().uses.insert(vreg, slot);
            }

            for &pos in &def_positions {
                let Some((vreg, slot)) = spilled_vreg_at(inst, pos, &spill_slots) else {
                    continue;
                };
                sites.entry(inst_id).or_default().defs.insert(vreg, slot);
            }
        }
    }

    materialize_spilled_operands_at_sites(ir_func, &sites).map(|_| ())
}

/// True when a spilled-copy materialization site is a provable IDENTITY slot
/// round-trip that can be elided entirely (load + copy + store all dropped).
///
/// The shape: `Copy dst_vreg <- src_vreg` where BOTH operands are spilled and
/// the site binds the use and the def to the SAME stack slot `S` (the
/// coalesced-phi-web self-copy — commonly `dst_vreg == src_vreg`). The generic
/// materialization path would emit
///
/// ```text
///     ldr <scratch>, [S]     ; reload src
///     mov <scratch'>, <scratch>   ; the copy (often scratch' == scratch => nop)
///     str <scratch'>, [S]    ; spill dst
/// ```
///
/// SOUNDNESS (why eliding the whole site preserves semantics):
///  * The allocator's spill contract — validated on the regalloc-form function
///    (incl. the slot-initialization dominance gate) — guarantees `mem[S]`
///    holds `value(src_vreg)` at this program point: that is precisely the
///    contract the use-reload this site would otherwise emit relies on.
///  * The instruction's entire effect is `dst_vreg := src_vreg`, and dst's
///    spill contract is discharged by storing `value(dst_vreg)` to the SAME
///    slot `S`. Since `mem[S] == value(src_vreg) == value(dst_vreg)` already,
///    the store writes back exactly the bytes the load read: memory is
///    unchanged byte-for-byte (the class-equality check pins load width ==
///    store width, so this holds even under spill-slot reuse).
///  * The scratch registers the triple would have used are conjured by this
///    materialization per site and are never live outside it by construction,
///    so no program-visible register changes either.
///
/// FAIL-CLOSED: any deviation from the exact shape (extra site entries, class
/// mismatch, non-VReg operands, unexpected roles) falls through to the generic
/// materialization path unchanged. Kill switch: `TCG_SPILL_IDENT_OFF=1`
/// restores the byte-identical old behavior.
fn identity_spilled_copy_slot(
    inst: &IrMachInst,
    site: &SpillMaterializationSite,
) -> Option<StackSlotId> {
    if inst.opcode != IrOpcode::Copy || inst.operands.len() != 2 {
        return None;
    }
    let (IrOperand::VReg(dst), IrOperand::VReg(src)) = (&inst.operands[0], &inst.operands[1])
    else {
        return None;
    };
    // Same register class => same spill access width (identity is byte-exact).
    if dst.class != src.class {
        return None;
    }
    // Roles must be exactly [Def, Use] (defensive: this is Copy's contract).
    let (def_positions, use_positions) = classify_operand_positions(inst);
    if def_positions != [0] || use_positions != [1] {
        return None;
    }
    // The site must bind exactly this use and this def, to the same slot.
    if site.uses.len() != 1 || site.defs.len() != 1 {
        return None;
    }
    let use_slot = site.uses.get(src)?;
    let def_slot = site.defs.get(dst)?;
    (use_slot == def_slot).then_some(*use_slot)
}

fn spill_ident_elide_disabled() -> bool {
    std::env::var_os("TCG_SPILL_IDENT_OFF").is_some()
}

fn spill_peep_stats_enabled() -> bool {
    std::env::var_os("TCG_SPILL_PEEP_STATS").is_some()
}

/// General-register location bit (bit `n` for X/Wn, `n` in 0..=30) of `reg`;
/// SP, the zero registers and non-GPRs have none.
fn gpr_location_bit(reg: PReg) -> u32 {
    match preg_class(reg) {
        RegClass::Gpr32 | RegClass::Gpr64 => {
            let n = hw_encoding(reg);
            if n < 31 && reg != XZR && reg != WZR {
                1u32 << n
            } else {
                0
            }
        }
        _ => 0,
    }
}

/// Every general register a physical-liveness solve tracks (X0-X30).
const ALL_GPR_LOCATIONS: u32 = (1u32 << 31) - 1;

/// General registers `inst` may read, over-approximated: every register
/// operand except one both the allocator's view and the operand-role table
/// call a pure definition (so stores, branches, calls and compares read every
/// operand, and an operand the role table leaves unclassified counts as
/// read), every memory base and the implicit uses.
fn gpr_reads_over(inst: &IrMachInst) -> u32 {
    let (_, use_positions) = classify_operand_positions(inst);
    let mut reads: BTreeSet<usize> = use_positions.into_iter().collect();
    let mut role_defs = BTreeSet::new();
    trust_cg_opt::effects::aarch64_for_each_use_position(inst.opcode, inst.operands.len(), |pos| {
        reads.insert(pos);
    });
    trust_cg_opt::effects::aarch64_for_each_def_position(inst.opcode, inst.operands.len(), |pos| {
        role_defs.insert(pos);
    });
    let mut mask = 0u32;
    for (pos, operand) in inst.operands.iter().enumerate() {
        if let IrOperand::PReg(reg) = operand
            && (reads.contains(&pos) || !role_defs.contains(&pos))
        {
            mask |= gpr_location_bit(*reg);
        }
    }
    for operand in &inst.operands {
        if let IrOperand::MemOp { base, .. } = operand {
            mask |= gpr_location_bit(*base);
        }
    }
    for &reg in inst.implicit_uses {
        mask |= gpr_location_bit(reg);
    }
    mask
}

/// General registers `inst` certainly writes, under-approximated: a def
/// position in both the allocator's and the operand-role table's views, and
/// the implicit definitions (a call's clobbers and results).
fn gpr_writes_under(inst: &IrMachInst) -> u32 {
    let (def_positions, _) = classify_operand_positions(inst);
    let mut role_defs = BTreeSet::new();
    trust_cg_opt::effects::aarch64_for_each_def_position(inst.opcode, inst.operands.len(), |pos| {
        role_defs.insert(pos);
    });
    let mut mask = 0u32;
    for pos in def_positions {
        if role_defs.contains(&pos)
            && let Some(IrOperand::PReg(reg)) = inst.operands.get(pos)
        {
            mask |= gpr_location_bit(*reg);
        }
    }
    for &reg in inst.implicit_defs {
        mask |= gpr_location_bit(reg);
    }
    mask
}

/// General registers live immediately after each instruction in `pseudos`:
/// read on some path before being redefined.
///
/// A backward solve over the allocated, not yet spill-materialized stream,
/// along the successor lists plus the landing-pad edges of protected calls.
/// Spilled values are still virtual registers here, and every other spill
/// site materializes them only through the reserved X16/X17, so the physical
/// registers this sees are exactly the allocated values. Reads are
/// over-approximated and writes under-approximated ([`gpr_reads_over`],
/// [`gpr_writes_under`]), so a register reported dead is dead. An indirect
/// branch, a malformed successor or a missing instruction makes every
/// register live after every pseudo.
fn aarch64_gpr_live_after(
    ir_func: &IrMachFunction,
    pseudos: &BTreeSet<InstId>,
) -> HashMap<InstId, u32> {
    let all_live = || pseudos.iter().map(|&id| (id, ALL_GPR_LOCATIONS)).collect();
    let blocks = ir_func.blocks.len();
    let mut succs: Vec<Vec<usize>> = Vec::with_capacity(blocks);
    for block in &ir_func.blocks {
        let mut out = Vec::with_capacity(block.succs.len());
        for succ in &block.succs {
            let s = succ.0 as usize;
            if s >= blocks {
                return all_live();
            }
            out.push(s);
        }
        succs.push(out);
    }
    for call_site in &ir_func.eh_metadata.call_sites {
        if let Some(pad) = call_site.landing_pad_block {
            let (from, to) = (call_site.call_block.0 as usize, pad.0 as usize);
            if from >= blocks || to >= blocks {
                return all_live();
            }
            succs[from].push(to);
        }
    }
    let mut gen_kill = Vec::with_capacity(blocks);
    for block in &ir_func.blocks {
        let (mut generated, mut killed) = (0u32, 0u32);
        for &inst_id in block.insts.iter().rev() {
            let Some(inst) = ir_func.insts.get(inst_id.0 as usize) else {
                return all_live();
            };
            if inst.opcode == IrOpcode::Br {
                return all_live();
            }
            let writes = gpr_writes_under(inst);
            generated = (generated & !writes) | gpr_reads_over(inst);
            killed |= writes;
        }
        gen_kill.push((generated, killed));
    }
    let mut live_in = vec![0u32; blocks];
    let mut changed = true;
    while changed {
        changed = false;
        for block in (0..blocks).rev() {
            let out = succs[block]
                .iter()
                .fold(0u32, |acc, &succ| acc | live_in[succ]);
            let (generated, killed) = gen_kill[block];
            let value = generated | (out & !killed);
            if value != live_in[block] {
                live_in[block] = value;
                changed = true;
            }
        }
    }
    let mut after = HashMap::new();
    for (block_idx, block) in ir_func.blocks.iter().enumerate() {
        if !block.insts.iter().any(|id| pseudos.contains(id)) {
            continue;
        }
        let mut live = succs[block_idx]
            .iter()
            .fold(0u32, |acc, &succ| acc | live_in[succ]);
        for &inst_id in block.insts.iter().rev() {
            let Some(inst) = ir_func.insts.get(inst_id.0 as usize) else {
                return all_live();
            };
            if pseudos.contains(&inst_id) {
                after.insert(inst_id, live);
            }
            live = (live & !gpr_writes_under(inst)) | gpr_reads_over(inst);
        }
    }
    after
}

/// General registers a spilled LL/SC pseudo operand may borrow beyond the
/// reserved X16/X17: the allocatable GPRs, caller-saved temporaries first,
/// then argument registers, then callee-saved registers (frame lowering saves
/// and restores any callee-saved register the final stream writes).
fn llsc_borrowable_gprs() -> Vec<u8> {
    let mut numbers: Vec<u8> = trust_cg_regalloc::aarch64_allocatable_regs()
        .get(&RegClass::Gpr64)
        .map(|regs| regs.iter().map(|&reg| hw_encoding(reg)).collect())
        .unwrap_or_default();
    numbers.retain(|&n| n < 31 && n != 16 && n != 17);
    numbers.sort_by_key(|&n| (n >= 19, n < 8, n));
    numbers
}

/// The `class` view (X or W) of general register number `n`.
fn gpr_view(n: u8, class: RegClass) -> Result<PReg, PipelineError> {
    match class {
        RegClass::Gpr64 => Ok(PReg::new(u16::from(n))),
        RegClass::Gpr32 => Ok(PReg::new(u16::from(n) + 32)),
        other => Err(PipelineError::RegAlloc(format!(
            "[TCG-LLSC-SPILL-SCRATCH] an LL/SC pseudo operand of class {other:?} is not a \
             general register"
        ))),
    }
}

/// Per-function state of the whole-window LL/SC spill strategy.
struct LlscSpillContext {
    /// General registers live after each LL/SC pseudo with a spill site
    /// ([`aarch64_gpr_live_after`]), taken before any site is materialized.
    live_after: HashMap<InstId, u32>,
    /// Emergency 8-byte save slots, reused by every pseudo: each save/restore
    /// pair brackets one pseudo, so no two are live at once.
    emergency_slots: Vec<StackSlotId>,
    /// One past the largest stack-slot id any instruction or spill site of
    /// the function names; a new emergency slot never reuses one of them.
    slot_floor: usize,
}

impl LlscSpillContext {
    fn new(ir_func: &IrMachFunction, sites: &FxHashMap<InstId, SpillMaterializationSite>) -> Self {
        let pseudos: BTreeSet<InstId> = sites
            .iter()
            .filter(|(id, site)| {
                !site.is_empty()
                    && ir_func.insts.get(id.0 as usize).is_some_and(|inst| {
                        trust_cg_ir::llsc::LlscPseudo::of(inst.opcode).is_some()
                    })
            })
            .map(|(id, _)| *id)
            .collect();
        if pseudos.is_empty() {
            return Self {
                live_after: HashMap::new(),
                emergency_slots: Vec::new(),
                slot_floor: 0,
            };
        }
        let referenced = ir_func
            .insts
            .iter()
            .flat_map(|inst| inst.operands.iter())
            .filter_map(|operand| match operand {
                IrOperand::StackSlot(slot) => Some(slot.0 as usize + 1),
                _ => None,
            });
        let spilled = sites
            .values()
            .flat_map(|site| site.uses.values().chain(site.defs.values()))
            .map(|slot| slot.0 as usize + 1);
        Self {
            live_after: aarch64_gpr_live_after(ir_func, &pseudos),
            emergency_slots: Vec::new(),
            slot_floor: referenced.chain(spilled).max().unwrap_or(0),
        }
    }

    /// The first `count` emergency save slots, allocating any missing one.
    fn emergency_slots(
        &mut self,
        ir_func: &mut IrMachFunction,
        count: usize,
    ) -> Result<Vec<StackSlotId>, PipelineError> {
        while self.emergency_slots.len() < count {
            while ir_func.stack_slots.len() < self.slot_floor {
                ir_func.stack_slots.push(IrStackSlot::new(8, 8));
            }
            let id = u32::try_from(ir_func.stack_slots.len()).map_err(|_| {
                PipelineError::RegAlloc(
                    "[TCG-LLSC-SPILL-SCRATCH] emergency save slot exceeds the stack-slot id \
                     domain"
                        .to_string(),
                )
            })?;
            ir_func.stack_slots.push(IrStackSlot::new(8, 8));
            self.emergency_slots.push(StackSlotId(id));
        }
        Ok(self.emergency_slots.iter().take(count).copied().collect())
    }
}

/// The whole-window spill strategy for an opaque LL/SC pseudo.
///
/// The pseudo expands after frame lowering into a load-exclusive/store-
/// exclusive retry loop that re-reads every use after writing every def, so
/// each spilled operand needs its own register for the whole loop, distinct
/// from every other operand, and no spill access may sit inside the loop.
/// Every spilled operand is therefore materialized AROUND the single pseudo:
///
/// ```text
///   STR  Xb, [E_i]        ; save each borrowed register still live (flagged)
///   LDR  Ru, [slot_u]     ; reload each spilled use           (flagged)
///   <pseudo>              ; expands to the LL/SC loop later
///   STR  Rd, [slot_d]     ; spill each spilled def            (flagged)
///   LDR  Xb, [E_i]        ; restore each saved borrowed register (flagged)
/// ```
///
/// Spilled uses take X16/X17 first. Spilled defs never do: their spill
/// stores follow the pseudo, where a far-offset store borrows an IP scratch
/// for its address, and after the pseudo X16/X17 hold only dead use values.
/// Beyond X16/X17 an operand borrows an allocatable GPR that is not an
/// operand of the pseudo: one dead after the pseudo ([`aarch64_gpr_live_after`])
/// as is, otherwise a live one saved to an emergency 8-byte slot before the
/// reloads and restored after the spill stores. Every save, reload, spill
/// store and restore is a flagged spill access, so the frame dataflow net
/// checks each restore against its save and each reload against its spill
/// store. A live register is defined on every path to the pseudo (it is read
/// later with no redefinition in between), so saving it reads a defined
/// value. Returns `Ok(false)` when `inst` is not an LL/SC pseudo or has no
/// spilled operand. Running out of registers (impossible for the defined
/// pseudo layouts, at most eight register operands against 27 candidates)
/// fails closed with `[TCG-LLSC-SPILL-SCRATCH]`.
fn materialize_spilled_llsc_pseudo(
    ir_func: &mut IrMachFunction,
    inst_id: InstId,
    inst: &IrMachInst,
    site: &SpillMaterializationSite,
    context: &mut LlscSpillContext,
    new_block_insts: &mut Vec<InstId>,
    debug_info: &mut SpillMaterializationDebugInfo,
) -> Result<bool, PipelineError> {
    if trust_cg_ir::llsc::LlscPseudo::of(inst.opcode).is_none() {
        return Ok(false);
    }
    let (def_positions, use_positions) = classify_operand_positions(inst);
    // (position, vreg, slot, is_def) in use-then-def order.
    let mut spilled: Vec<(usize, VReg, StackSlotId, bool)> = Vec::new();
    for &pos in &use_positions {
        if let Some(IrOperand::VReg(vreg)) = inst.operands.get(pos)
            && let Some(slot) = spill_slot_for_vreg(*vreg, &site.uses)
        {
            spilled.push((pos, *vreg, slot, false));
        }
    }
    for &pos in &def_positions {
        if let Some(IrOperand::VReg(vreg)) = inst.operands.get(pos)
            && let Some(slot) = spill_slot_for_vreg(*vreg, &site.defs)
        {
            spilled.push((pos, *vreg, slot, true));
        }
    }
    if spilled.is_empty() {
        return Ok(false);
    }

    let mut reserved = 0u32;
    for reg in operand_physical_regs(inst)
        .into_iter()
        .chain(inst.implicit_uses.iter().copied())
        .chain(inst.implicit_defs.iter().copied())
    {
        reserved |= gpr_location_bit(reg);
    }
    let live_after = context
        .live_after
        .get(&inst_id)
        .copied()
        .unwrap_or(ALL_GPR_LOCATIONS);
    let borrowable = llsc_borrowable_gprs();
    // Register number per spilled vreg, and the live registers to save.
    let mut assigned: HashMap<VReg, u8> = HashMap::new();
    let mut taken = reserved;
    let mut saved: Vec<u8> = Vec::new();
    for &(_, vreg, _, is_def) in &spilled {
        if assigned.contains_key(&vreg) {
            continue;
        }
        let free = |n: u8| taken & (1u32 << n) == 0;
        let dedicated = (!is_def)
            .then(|| [16u8, 17u8].into_iter().find(|&n| free(n)))
            .flatten();
        let choice = dedicated
            .or_else(|| {
                borrowable
                    .iter()
                    .copied()
                    .find(|&n| free(n) && live_after & (1u32 << n) == 0)
            })
            .or_else(|| {
                let live = borrowable.iter().copied().find(|&n| free(n))?;
                saved.push(live);
                Some(live)
            });
        let Some(n) = choice else {
            return Err(PipelineError::RegAlloc(format!(
                "[TCG-LLSC-SPILL-SCRATCH] AArch64 spill materialization found no general \
                 register distinct from every operand of {inst:?} for spilled {vreg:?}"
            )));
        };
        taken |= 1u32 << n;
        assigned.insert(vreg, n);
    }

    let emergency_slots = context.emergency_slots(ir_func, saved.len())?;

    let register_of = |vreg: VReg| -> Result<PReg, PipelineError> {
        let n = assigned.get(&vreg).copied().ok_or_else(|| {
            PipelineError::RegAlloc(format!(
                "[TCG-LLSC-SPILL-SCRATCH] spilled {vreg:?} of {inst:?} has no register"
            ))
        })?;
        gpr_view(n, vreg.class)
    };
    let source_loc = inst.source_loc;
    for (&n, &slot) in saved.iter().zip(emergency_slots.iter()) {
        let save = ir_func.push_inst(make_spill_store(PReg::new(u16::from(n)), slot, source_loc));
        new_block_insts.push(save);
    }
    let mut reloaded = BTreeSet::new();
    for &(_, vreg, slot, is_def) in &spilled {
        if is_def || !reloaded.insert(vreg) {
            continue;
        }
        let load = ir_func.push_inst(make_spill_load(register_of(vreg)?, slot, source_loc));
        new_block_insts.push(load);
    }
    {
        let rewritten = &mut ir_func.insts[inst_id.0 as usize];
        for &(pos, vreg, _, _) in &spilled {
            rewritten.operands[pos] = IrOperand::PReg(register_of(vreg)?);
        }
    }
    new_block_insts.push(inst_id);
    let mut stored = BTreeSet::new();
    for &(_, vreg, slot, is_def) in &spilled {
        if !is_def || !stored.insert(vreg) {
            continue;
        }
        let store = ir_func.push_inst(make_spill_store(register_of(vreg)?, slot, source_loc));
        new_block_insts.push(store);
        debug_info.record_store(vreg, slot, store);
    }
    for (&n, &slot) in saved.iter().zip(emergency_slots.iter()).rev() {
        let restore = ir_func.push_inst(make_spill_load(PReg::new(u16::from(n)), slot, source_loc));
        new_block_insts.push(restore);
    }
    Ok(true)
}

fn materialize_spilled_operands_at_sites(
    ir_func: &mut IrMachFunction,
    sites: &FxHashMap<InstId, SpillMaterializationSite>,
) -> Result<SpillMaterializationDebugInfo, PipelineError> {
    let mut debug_info = SpillMaterializationDebugInfo::default();
    if sites.is_empty() {
        return Ok(debug_info);
    }

    let ident_elide_enabled = !spill_ident_elide_disabled();
    // Hoisted out of the per-instruction loop below. `spill_materialization_trace_enabled`
    // does an allocating `std::env::var` and the function name it filters on is fixed for
    // the whole call, so reading it per spill site was one `getenv` + `String` per
    // materialized instruction. Read once per call (not memoized) so an in-process flip
    // is still observed by the next call.
    let trace_materialization = spill_materialization_trace_enabled(&ir_func.name);
    let mut ident_elided = 0u32;
    // Physical liveness after every LL/SC pseudo with spilled operands, taken
    // before any site is materialized (the whole-window spill strategy may
    // borrow a register that is dead there).
    let mut llsc_context = LlscSpillContext::new(ir_func, sites);
    let num_blocks = ir_func.blocks.len();
    for block_idx in 0..num_blocks {
        let block_insts = std::mem::take(&mut ir_func.blocks[block_idx].insts);
        let mut new_block_insts = Vec::with_capacity(block_insts.len());

        for inst_id in block_insts {
            let Some(site) = sites.get(&inst_id) else {
                new_block_insts.push(inst_id);
                continue;
            };
            if site.is_empty() {
                new_block_insts.push(inst_id);
                continue;
            }

            let inst_snapshot = ir_func.insts[inst_id.0 as usize].clone();
            if trace_materialization {
                eprintln!(
                    "[trust_cg][spill-materialize] func={} block=bb{} inst=inst{} opcode={:?} operands={:?} uses={:?} defs={:?}",
                    ir_func.name,
                    block_idx,
                    inst_id.0,
                    inst_snapshot.opcode,
                    inst_snapshot.operands,
                    site.uses,
                    site.defs,
                );
            }
            // IDENTITY-SLOT-COPY ELISION: a spilled phi self-copy whose use and
            // def share one slot is a dead `ldr [S]; mov; str [S]` round-trip —
            // drop the whole site (see `identity_spilled_copy_slot` for the
            // soundness argument). Checked before every materialization helper
            // so no load/store for the site is ever created.
            if ident_elide_enabled && identity_spilled_copy_slot(&inst_snapshot, site).is_some() {
                let inst = &mut ir_func.insts[inst_id.0 as usize];
                inst.opcode = IrOpcode::Nop;
                inst.operands.clear();
                // Pseudo Nop: every encoder walk skips it (0 bytes emitted).
                inst.flags = trust_cg_ir::inst::InstFlags::IS_PSEUDO;
                new_block_insts.push(inst_id);
                ident_elided += 1;
                continue;
            }

            if materialize_spilled_llsc_pseudo(
                ir_func,
                inst_id,
                &inst_snapshot,
                site,
                &mut llsc_context,
                &mut new_block_insts,
                &mut debug_info,
            )? {
                continue;
            }

            // Validate original pair intent before either decomposition or
            // generic scratch assignment can erase bad classes, aliases,
            // operand tails or offsets. This is instruction-emission atomic,
            // not a promise to restore the outer block list after an error.
            let pair = checked_pair_memory_intent(&inst_snapshot)?;
            if let Some(pair) = pair {
                if materialize_spilled_store_pair(
                    ir_func,
                    &inst_snapshot,
                    pair,
                    &site.uses,
                    &mut new_block_insts,
                )? {
                    continue;
                }
                if materialize_spilled_load_pair(
                    ir_func,
                    &inst_snapshot,
                    pair,
                    &site.uses,
                    &site.defs,
                    &mut new_block_insts,
                    &mut debug_info,
                )? {
                    continue;
                }
            }
            if materialize_spilled_register_offset_mem(
                ir_func,
                inst_id,
                &inst_snapshot,
                &site.uses,
                &site.defs,
                &mut new_block_insts,
                &mut debug_info,
            )? {
                continue;
            }
            if materialize_spilled_multiply_accumulate(
                ir_func,
                inst_id,
                &inst_snapshot,
                &site.uses,
                &site.defs,
                &mut new_block_insts,
                &mut debug_info,
            )? {
                continue;
            }
            if materialize_spilled_fused_multiply_add(
                ir_func,
                inst_id,
                &inst_snapshot,
                &site.uses,
                &mut new_block_insts,
            )? {
                continue;
            }

            let (def_positions, use_positions) = classify_operand_positions(&inst_snapshot);
            let mut use_bindings: Vec<(usize, VReg, PReg, StackSlotId)> = Vec::new();
            let mut def_bindings: Vec<(usize, VReg, PReg, StackSlotId)> = Vec::new();
            let mut use_loads: Vec<(PReg, StackSlotId)> = Vec::new();

            let mut assigned: HashMap<VReg, PReg> = HashMap::new();
            let reserved_scratch_regs = operand_physical_regs(&inst_snapshot);
            let mut used_scratch_regs = Vec::new();

            for &pos in &use_positions {
                let IrOperand::VReg(vreg) = inst_snapshot.operands[pos] else {
                    continue;
                };
                let Some(slot) = spill_slot_for_vreg(vreg, &site.uses) else {
                    continue;
                };

                let scratch = if let Some(&preg) = assigned.get(&vreg) {
                    preg
                } else {
                    let Some(preg) = available_scratch_for_class(
                        vreg.class,
                        &reserved_scratch_regs,
                        &used_scratch_regs,
                    )?
                    else {
                        return Err(PipelineError::RegAlloc(format!(
                            "AArch64 spill materialization ran out of scratch registers in {:?}",
                            inst_snapshot
                        )));
                    };
                    assigned.insert(vreg, preg);
                    used_scratch_regs.push(preg);
                    use_loads.push((preg, slot));
                    preg
                };
                use_bindings.push((pos, vreg, scratch, slot));
            }

            let spilled_defs: Vec<_> = def_positions
                .iter()
                .filter_map(|&pos| {
                    let IrOperand::VReg(vreg) = inst_snapshot.operands[pos] else {
                        return None;
                    };
                    let slot = spill_slot_for_vreg(vreg, &site.defs)?;
                    Some((pos, vreg, slot))
                })
                .collect();
            let spilled_def_count = spilled_defs.len();

            for (pos, vreg, slot) in spilled_defs {
                let scratch = if let Some(&preg) = assigned.get(&vreg) {
                    preg
                } else if let Some(preg) = available_scratch_for_class(
                    vreg.class,
                    &reserved_scratch_regs,
                    &used_scratch_regs,
                )? {
                    assigned.insert(vreg, preg);
                    used_scratch_regs.push(preg);
                    preg
                } else if trust_cg_ir::llsc::is_exclusive_store(inst_snapshot.opcode) {
                    // Unlike an ordinary ALU destination, the exclusive-store
                    // status must not alias either input (W/X aliases count).
                    // Two input scratches are not a third status scratch.
                    // Never emit constrained-unpredictable bytes.
                    return Err(PipelineError::RegAlloc(format!(
                        "AArch64 spill materialization needs a distinct store-exclusive status scratch in {:?}",
                        inst_snapshot
                    )));
                } else if trust_cg_opt::effects::is_llsc_pseudo(inst_snapshot.opcode) {
                    // Backstop: `materialize_spilled_llsc_pseudo` handles every
                    // LL/SC pseudo with a spilled operand before this generic
                    // path. Every LL/SC pseudo def is re-written inside the
                    // retry loop while its uses are still re-read, so a def may
                    // never borrow a use's scratch. [TCG-LLSC-SPILL-SCRATCH]
                    return Err(PipelineError::RegAlloc(format!(
                        "[TCG-LLSC-SPILL-SCRATCH] AArch64 spill materialization has no scratch \
                         for an LL/SC pseudo def distinct from every use in {:?}",
                        inst_snapshot
                    )));
                } else if spilled_def_count == 1 {
                    let first_use = use_bindings.first().ok_or_else(|| {
                        PipelineError::RegAlloc(format!(
                            "missing spill scratch for def-only spill in {:?}",
                            inst_snapshot
                        ))
                    })?;
                    let slot_idx = scratch_slot_index(first_use.2).ok_or_else(|| {
                        PipelineError::RegAlloc(format!(
                            "unknown spill scratch register {:?} in {:?}",
                            first_use.2, inst_snapshot
                        ))
                    })?;
                    scratch_pool_for_class(vreg.class)?[slot_idx]
                } else {
                    return Err(PipelineError::RegAlloc(format!(
                        "AArch64 spill materialization ran out of scratch registers for multiple defs in {:?}",
                        inst_snapshot
                    )));
                };
                def_bindings.push((pos, vreg, scratch, slot));
            }

            if use_bindings.is_empty() && def_bindings.is_empty() {
                new_block_insts.push(inst_id);
                continue;
            }

            if matches!(
                inst_snapshot.opcode,
                IrOpcode::LdrRO
                    | IrOpcode::StrRO
                    | IrOpcode::LdrbRO
                    | IrOpcode::LdrhRO
                    | IrOpcode::StrbRO
                    | IrOpcode::StrhRO
            ) {
                use crate::aarch64::encoding_mem::RegExtend;
                let (extend, _) = crate::aarch64::encode::register_offset_mode(&inst_snapshot)
                    .map_err(|error| PipelineError::RegAlloc(error.to_string()))?;
                if matches!(extend, RegExtend::Lsl | RegExtend::Sxtx) {
                    for (position, vreg, scratch, slot) in &mut use_bindings {
                        if *position != 2 || vreg.class != RegClass::Gpr32 {
                            continue;
                        }
                        // The actual W reload zeroes the corresponding X
                        // upper half. Widen only this index use, never the
                        // reload, data/def binding, or an unspilled W operand.
                        if !use_loads.contains(&(*scratch, *slot)) {
                            return Err(PipelineError::RegAlloc(
                                "register-offset index widening requires its same-site W reload"
                                    .to_string(),
                            ));
                        }
                        *scratch = gpr32_to_gpr64(*scratch).ok_or_else(|| {
                            PipelineError::RegAlloc(
                                "register-offset Gpr32 index reload requires a W scratch"
                                    .to_string(),
                            )
                        })?;
                    }
                }
            }

            for (scratch, slot) in &use_loads {
                let load_id =
                    ir_func.push_inst(make_spill_load(*scratch, *slot, inst_snapshot.source_loc));
                new_block_insts.push(load_id);
            }

            {
                let inst = &mut ir_func.insts[inst_id.0 as usize];
                for (pos, _, scratch, _) in &use_bindings {
                    inst.operands[*pos] = IrOperand::PReg(*scratch);
                }
                for (pos, _, scratch, _) in &def_bindings {
                    inst.operands[*pos] = IrOperand::PReg(*scratch);
                }
            }
            new_block_insts.push(inst_id);

            if pair.is_some_and(|pair| {
                pair.load
                    && pair.mode != crate::aarch64::encode::PairMemoryMode::Offset
                    && matches!(
                        pair.data_class,
                        RegClass::Fpr32 | RegClass::Fpr64 | RegClass::Fpr128
                    )
            }) {
                // Keep the single writeback pair intact. Spill its updated
                // GPR base before FP results so a later far FP-slot address
                // may borrow that now-dead GPR. Storing the base itself can
                // use the other IP scratch; FP data never aliases either IP.
                // GPR pair spill ordering/capacity refusals are unchanged.
                def_bindings.sort_by_key(|(position, _, _, _)| *position != 2);
            }
            for (_, vreg, scratch, slot) in def_bindings {
                let store_id =
                    ir_func.push_inst(make_spill_store(scratch, slot, inst_snapshot.source_loc));
                new_block_insts.push(store_id);
                debug_info.record_store(vreg, slot, store_id);
            }
        }

        ir_func.blocks[block_idx].insts = new_block_insts;
    }

    if ident_elided > 0 && spill_peep_stats_enabled() {
        eprintln!(
            "[trust-cg-spill-peep] func={} ident_slot_copies_elided={}",
            ir_func.name, ident_elided
        );
    }

    Ok(debug_info)
}

/// Post-materialization redundant spill-slot reload elision (CSE over the CFG).
///
/// `materialize_spilled_operands_at_sites` conjures one reload per use SITE, so
/// several consecutive uses of one spilled value in a block re-load the same
/// untouched slot into the same scratch register (huffbench decode pays three
/// `ldr x16, [S]` in a row), and a spill store followed by a reload of the same
/// slot can be redundant when the store covered the full X/Q register. This
/// pass deletes a reload `LdrRI r, [S]` only when the complete X/Q state already
/// equals that load's post-state, including the upper bits cleared by W/H/S/D:
///
///  * a tracked fact `(S -> r)` is established by a previous spill reload
///    `LdrRI r, [S]`, or by a full-width X/Q spill store `StrRI r, [S]`;
///    W/H/S/D stores do not establish the upper-bit zeroing of a narrow load,
///    so they conservatively establish no forwarding fact, and
///  * no instruction between redefines `r` (explicit def positions per the
///    operand-role table, with sub-register overlap via `regs_overlap`), and
///  * no instruction between can write `mem[S]`, and
///  * the walk never crosses a call, return, indirect/trap terminator or any
///    instruction it cannot positively classify (facts are dropped there).
///
/// CROSS-BLOCK (the huffbench encode/decode residual). The tracker is a forward
/// MUST-dataflow over the post-RA CFG: `IN[B] = meet(OUT[P] for P in preds(B))`
/// with `meet` = keep only `(S -> r)` pairs on which every predecessor agrees
/// EXACTLY, `IN[entry] = {}`, and `OUT[B] = walk(B, IN[B])`. Optimistic
/// initialization (`OUT[B] = TOP`, the meet identity) is what lets a fact
/// generated in a loop header survive the body's back edge — huffbench's decode
/// insertion-sort reloads its spilled counter twice per outer iteration, once in
/// the header and once in the latch, with the inner loop in between (3 far-offset
/// instructions per reload). A single-predecessor rule cannot see that; the
/// fixpoint can. Soundness of the meet: a fact means "register `r` already has
/// the complete post-load X/Q state for `S`", so it may be assumed at a join
/// only if it holds on EVERY incoming edge — exactly what the intersection
/// computes. Any predecessor set that cannot be derived exactly makes the whole
/// function fall back to the block-local walk (see `cross_block_spill_facts`).
///
/// Facts flow along an edge only if the predecessor's terminator is a plain
/// direct local branch (`B`/`B.cond`/`CBZ`/`CBNZ`/`TBZ`/`TBNZ` with `Block`
/// operands and no register def); calls, returns, tail calls (`B <symbol>`),
/// indirect `Br` and every `Trap*` guard pseudo (which expand post-RA into
/// `MOVZ X16, #imm; CMP` — an IP-scratch clobber) drop them.
///
/// WHY USER STORES CANNOT WRITE A TRACKED SLOT (the alias proof): a slot is
/// tracked only if (a) it is a regalloc-created spill slot (`effective_spills`,
/// minted by `alloc_stack_slot` after all program-visible slots) AND (b) a
/// whole-function pre-scan shows EVERY reference to it is the exact 2-operand
/// spill access shape `LdrRI/StrRI [PReg, StackSlot]`. (b) proves the slot's
/// address is never materialized into any register (no address-of, no base+
/// offset form, no pair form), so no program pointer can name it; a
/// well-defined program's stores therefore cannot touch it (reaching it would
/// require out-of-bounds arithmetic from another object — UB, the standard
/// spill-slot no-alias assumption every production compiler makes).
///
/// SCRATCH-LIVENESS (the pr28982b X17-clobber class): deleting a reload
/// extends the scratch's live range backward to the PREVIOUS access of the
/// slot. The extension region is exactly the instructions between the two
/// accesses, and the tracker CLEARS all facts at every instruction that frame
/// lowering could expand with an IP-scratch borrow:
///
///  * any StackSlot-bearing instruction outside the tracked spill shapes,
///  * every spill STORE (its far-offset form borrows the other IP register for
///    the address), and
///  * every spill LOAD whose data register is not a GPR — an FPR reload cannot
///    host its own address arithmetic, so `frame.rs` borrows X16/X17 for it.
///
/// Therefore no instruction inside an extension region ever grows a scratch
/// borrow, and `frame.rs`'s own fail-closed IP-scratch liveness guard remains
/// the backstop for anything unforeseen (a wrong extension is a NAMED compile
/// error there, never a silent miscompile). That backstop is only a backstop if
/// it sees the same live ranges this pass creates, so `frame.rs` computes
/// X16/X17 liveness over the WHOLE function (`ip_scratch_block_live_out`); it
/// used to seed live-out-of-block = false on the "IP scratch never crosses a
/// block boundary" invariant, which cross-block elision retires.
///
/// Anything not positively classified clears all facts (fail-closed default).
///
/// THE CROSS-BLOCK SOLVE IS OPT-IN (`TCG_SPILL_RELOAD_CSE_XBLOCK=1`), because
/// it is a MEASURED WASH and shipping a wash into the default pipeline is
/// churn. Interleaved trimmed-median + min, best-of-15, vs clang 21 -O3:
///
/// | program           | block-local   | + cross-block | elides |
/// |-------------------|---------------|---------------|--------|
/// | huffbench         | 1.1713/1.1745 | 1.1724/1.1723 |  5->6  |
/// | McGill/exptree*   | 1.5322/1.5294 | 1.5265/1.5138 |  2->9  |
/// | Linpack/linpack-pc| 1.1436/1.1543 | 1.1403/1.1509 |  9->13 |
/// | Misc/ReedSolomon  | 1.1578/1.1594 | 1.1639/1.1663 |  4->8  |
///
/// (*exptree on an amplified input — its default input runs 4 ms, where the
/// spawn floor manufactured a fake -11%.) The ReedSolomon loss is NOT the
/// transform: with `TCG_NO_LOOP_HEAD_ALIGN=1` it inverts to 1.1585 -> 1.1549,
/// so removing four instructions moved a loop head across an alignment
/// boundary. It fires on 10 of the 65 importable SingleSource programs.
///
/// The block-local pass stays default-ON and is byte-identical with the
/// extension off (verified across all 65). Kill switch for the whole pass:
/// `TCG_SPILL_RELOAD_CSE_OFF=1`; bisect key `spill_reload_cse`
/// (TRUST_CG_DISABLE_PASSES).
fn elide_redundant_spill_slot_reloads(
    ir_func: &mut IrMachFunction,
    regalloc_spill_slots: &BTreeSet<StackSlotId>,
) -> u32 {
    elide_redundant_spill_slot_reloads_scoped(
        ir_func,
        regalloc_spill_slots,
        spill_reload_cse_xblock_enabled(),
    )
}

static SPILL_RELOAD_CSE_XBLOCK: std::sync::OnceLock<bool> = std::sync::OnceLock::new();

/// Install the CROSS-BLOCK spill/reload CSE solve from a TRACKED compiler option, once
/// (`-Ztrust-ir-cg-args=x86-spill-reload-cse-xblock`). DEFAULT OFF.
///
/// Until 2026-09-30 the only channel was `TCG_SPILL_RELOAD_CSE_XBLOCK`, which `trustc`
/// refuses before the backend loads, so the cross-block tier had never been measured through
/// the bridge.
///
/// ⚑ THE `x86-` IN THIS NAME IS A MISNOMER, and the reason is structural rather than
/// empirical. The only production caller of [`elide_redundant_spill_slot_reloads`] — the
/// sole reader of this flag — is `Pipeline::run_regalloc`, which allocates an
/// `IrMachFunction`: the AArch64 machine IR. The x86-64 path keeps `X86ISelFunction` as its
/// source of truth and never reaches that allocator, so on an x86-64 target this option
/// CANNOT change the emitted code, whatever it is set to. That is why the 2026-09-30 sweep
/// measured it changing 0 of 18 `beat-llvm` binaries
/// (`reports/perf/2026-09-30-remaining-optins-swept/`) — the null was a property of the
/// wiring, not evidence about the transform.
///
/// It was reached for because `h4_vec_dropper`'s gap had been attributed to post-RA spill
/// reloads. x86-64's own counterpart for that shape is
/// `x86_64::pipeline::elide_redundant_x86_spill_reloads`, which is DEFAULT-ON and ungated at
/// both pipeline call sites; any further x86 work on redundant reloads belongs there, in its
/// decline conditions, and not in this flag.
pub fn set_x86_spill_reload_cse_xblock_enabled(enabled: bool) -> bool {
    match SPILL_RELOAD_CSE_XBLOCK.set(enabled) {
        Ok(()) => true,
        Err(requested) => SPILL_RELOAD_CSE_XBLOCK.get() == Some(&requested),
    }
}

fn spill_reload_cse_xblock_enabled() -> bool {
    SPILL_RELOAD_CSE_XBLOCK.get().copied().unwrap_or(false)
        || std::env::var_os("TCG_SPILL_RELOAD_CSE_XBLOCK").is_some()
}

/// [`elide_redundant_spill_slot_reloads`] with the cross-block solve chosen
/// explicitly instead of read from the environment (the tests drive both modes
/// without touching process-global state).
fn elide_redundant_spill_slot_reloads_scoped(
    ir_func: &mut IrMachFunction,
    regalloc_spill_slots: &BTreeSet<StackSlotId>,
    cross_block: bool,
) -> u32 {
    use trust_cg_ir::inst::InstFlags;

    if regalloc_spill_slots.is_empty() || std::env::var_os("TCG_SPILL_RELOAD_CSE_OFF").is_some() {
        return 0;
    }

    // PRE-SCAN (address-escape proof): keep only slots whose EVERY reference
    // in the function is the exact 2-operand spill load/store shape.
    let mut trackable: BTreeSet<StackSlotId> = regalloc_spill_slots.clone();
    for block in &ir_func.blocks {
        for &inst_id in &block.insts {
            let inst = &ir_func.insts[inst_id.0 as usize];
            if spill_access_shape(inst).is_some() {
                continue;
            }
            for op in &inst.operands {
                if let IrOperand::StackSlot(slot) = op {
                    trackable.remove(slot);
                }
            }
        }
    }
    if trackable.is_empty() {
        return 0;
    }

    // Cross-block MUST-dataflow entry facts (empty for every block when the
    // extension is off or the CFG cannot be derived exactly).
    let entry_facts = cross_block
        .then(|| cross_block_spill_facts(ir_func, &trackable))
        .flatten();

    let mut removed = 0u32;
    for block_idx in 0..ir_func.blocks.len() {
        let empty = SpillFacts::new();
        let facts_in = entry_facts
            .as_ref()
            .and_then(|f| f.get(block_idx))
            .unwrap_or(&empty);
        let (_, redundant) = walk_block_spill_facts(ir_func, block_idx, facts_in, &trackable);
        if redundant.is_empty() {
            continue;
        }
        for &pos in &redundant {
            // The complete post-load X/Q state already holds. Nop the
            // body so any stale InstId reference stays harmless, then drop it
            // from the block.
            let inst_id = ir_func.blocks[block_idx].insts[pos];
            let inst = &mut ir_func.insts[inst_id.0 as usize];
            inst.opcode = IrOpcode::Nop;
            inst.operands.clear();
            inst.flags = InstFlags::IS_PSEUDO;
            removed += 1;
        }
        let drop: BTreeSet<usize> = redundant.into_iter().collect();
        let mut pos = 0usize;
        ir_func.blocks[block_idx].insts.retain(|_| {
            let keep = !drop.contains(&pos);
            pos += 1;
            keep
        });
    }

    if removed > 0 && spill_peep_stats_enabled() {
        eprintln!(
            "[trust-cg-spill-peep] func={} redundant_slot_reloads_elided={}",
            ir_func.name, removed
        );
    }

    removed
}

/// "The complete X/Q register state already equals a load of slot `S` into
/// `r`", including upper-bit clearing for W/H/S/D loads. At most one entry per
/// REGISTER as well as per slot: establishing a fact first drops every
/// overlapping-register fact. Scalable SVE state is outside this model.
type SpillFacts = BTreeMap<StackSlotId, PReg>;

/// The exact spill access shapes emitted by `make_spill_load` /
/// `make_spill_store`: `(is_load, data_reg, slot)`.
fn spill_access_shape(inst: &IrMachInst) -> Option<(bool, PReg, StackSlotId)> {
    let is_load = match inst.opcode {
        IrOpcode::LdrRI => true,
        IrOpcode::StrRI => false,
        _ => return None,
    };
    match inst.operands.as_slice() {
        [IrOperand::PReg(reg), IrOperand::StackSlot(slot)] => Some((is_load, *reg, *slot)),
        _ => None,
    }
}

/// NZCV-only side effects: safe to walk across (no GPR/FPR def, no memory).
fn spill_facts_compare_only(opcode: IrOpcode) -> bool {
    matches!(
        opcode,
        IrOpcode::CmpRR
            | IrOpcode::CmpRI
            | IrOpcode::CMPWrr
            | IrOpcode::CMPXrr
            | IrOpcode::CMPWri
            | IrOpcode::CMPXri
            | IrOpcode::Tst
            | IrOpcode::Fcmp
    )
}

/// Plain (non-volatile, non-writeback) user stores: write through program
/// pointers, which the address-escape pre-scan proves cannot name a tracked
/// slot; they define no register (their operands are all uses).
fn spill_facts_plain_user_store(opcode: IrOpcode) -> bool {
    matches!(
        opcode,
        IrOpcode::StrRI
            | IrOpcode::StrbRI
            | IrOpcode::StrhRI
            | IrOpcode::StrRO
            | IrOpcode::StrbRO
            | IrOpcode::StrhRO
    )
}

/// True iff `inst` is a plain DIRECT LOCAL branch across which slot->register
/// facts survive into the successor block: it transfers control inside this
/// function through `Block` operands, defines no register, touches no memory
/// and carries nothing frame-flavored.
///
/// Deliberately NOT fact-preserving (each drops every fact):
///  * `Bl`/`Blr`/`Ret` — calls clobber the caller-saved set, returns end the
///    live range;
///  * a tail-call `B <symbol>` — leaves the function (`Symbol`, not `Block`);
///  * indirect `Br` — its successor set lives in a jump table, and a computed
///    goto has none at all;
///  * every `Trap*` guard pseudo — `expand_trap_bounds_check_exact` rewrites
///    those post-RA into `MOVZ X16, #imm (+MOVK); CMP` and the overflow carrier
///    borrows X16 the same way, so walking one would silently step over an
///    IP-scratch clobber.
fn spill_facts_local_branch(inst: &IrMachInst) -> bool {
    use trust_cg_ir::inst::InstFlags;
    if !matches!(
        inst.opcode,
        IrOpcode::B
            | IrOpcode::BCond
            | IrOpcode::Bcc
            | IrOpcode::Cbz
            | IrOpcode::Cbnz
            | IrOpcode::Tbz
            | IrOpcode::Tbnz
    ) || inst.flags.contains(InstFlags::IS_CALL)
    {
        return false;
    }
    let mut has_block_target = false;
    for op in &inst.operands {
        match op {
            IrOperand::Block(_) => has_block_target = true,
            IrOperand::PReg(_) | IrOperand::Imm(_) | IrOperand::Special(_) => {}
            // Symbol (tail call), StackSlot/FrameIndex/MemOp (frame-flavored,
            // legalizable with a scratch borrow), VReg, anything else: no.
            _ => return false,
        }
    }
    // Nothing in this family writes a register; assert it rather than assume it
    // (a def would end a tracked register's live range mid-edge).
    let (def_positions, _) = classify_operand_positions(inst);
    has_block_target
        && def_positions.is_empty()
        && !inst.flags.contains(InstFlags::WRITES_MEMORY)
        && inst.implicit_defs.is_empty()
}

/// Walk one block's instruction stream from `facts_in`, returning the facts
/// that hold at the block's exit and the POSITIONS (indices into the block's
/// instruction list) of reloads that are provably redundant.
///
/// This is the single transfer function: the dataflow fixpoint and the final
/// rewrite both call it, so what the fixpoint proves is exactly what the
/// rewrite deletes. Deleting a redundant reload leaves the fact set unchanged
/// (the complete post-load X/Q state already holds), so the returned exit facts are
/// valid both before and after the rewrite. Monotone in `facts_in` — every rule
/// either clears unconditionally, drops facts by register overlap, or inserts a
/// fixed pair — which is what makes the optimistic fixpoint terminate.
fn walk_block_spill_facts(
    ir_func: &IrMachFunction,
    block_idx: usize,
    facts_in: &SpillFacts,
    trackable: &BTreeSet<StackSlotId>,
) -> (SpillFacts, Vec<usize>) {
    use trust_cg_ir::inst::InstFlags;

    let mut track = facts_in.clone();
    let mut redundant: Vec<usize> = Vec::new();
    let Some(block) = ir_func.blocks.get(block_idx) else {
        return (SpillFacts::new(), redundant);
    };

    for (pos, &inst_id) in block.insts.iter().enumerate() {
        let Some(inst) = ir_func.insts.get(inst_id.0 as usize) else {
            track.clear();
            continue;
        };

        if let Some((is_load, reg, slot)) = spill_access_shape(inst) {
            if !trackable.contains(&slot) {
                // Frame access to an unproven slot: address provenance and
                // far-offset scratch borrows unknown — full barrier.
                track.clear();
                continue;
            }
            if is_load {
                if track.get(&slot) == Some(&reg) {
                    // The complete post-load X/Q state holds, not just low bytes.
                    redundant.push(pos);
                    continue;
                }
                if !matches!(preg_class(reg), RegClass::Gpr32 | RegClass::Gpr64) {
                    // An FPR reload cannot host its own address arithmetic, so
                    // the far-offset form borrows X16/X17 — the same clobber a
                    // spill STORE pays. Drop everything, then record the fact.
                    track.clear();
                } else {
                    // A GPR reload's far-offset form materializes the address
                    // in the destination register itself (`load_dest_gpr`), so
                    // only that register's facts die.
                    track.retain(|_, held| !regs_overlap(*held, reg));
                }
                track.insert(slot, reg);
            } else {
                // Spill STORE: its far-offset lowering borrows the other IP
                // scratch for the address, so every other fact's register may
                // be clobbered at frame lowering — drop them all. The data
                // register is only read: W/H/S/D stores do not clear upper
                // X/Q bits as a subsequent narrow load would. Without separate
                // upper-bit provenance, only full-width X/Q stores establish
                // the complete post-load X/Q state.
                track.clear();
                if matches!(preg_class(reg), RegClass::Gpr64 | RegClass::Fpr128) {
                    track.insert(slot, reg);
                }
            }
            continue;
        }

        // Pseudo/alignment nops: no machine effect.
        if matches!(inst.opcode, IrOpcode::Nop | IrOpcode::AlignNop) {
            continue;
        }

        let flags = inst.flags;
        if flags.contains(InstFlags::IS_CALL)
            || flags.contains(InstFlags::IS_BRANCH)
            || flags.contains(InstFlags::IS_RETURN)
            || flags.contains(InstFlags::IS_TERMINATOR)
        {
            // A plain direct local branch transfers control without touching a
            // register or memory, so facts survive it (and, when the successor
            // has no other predecessor reaching it with different facts, the
            // edge itself). Everything else in the family fails closed.
            if !spill_facts_local_branch(inst) {
                track.clear();
            }
            continue;
        }

        // Operand sanity: only plain register/immediate/special/symbol
        // operands may pass. Anything frame-flavored (StackSlot in a
        // non-spill shape, FrameIndex, MemOp) can be expanded by frame
        // lowering with an IP-scratch borrow; unresolved VRegs and other
        // exotic operands mean this walk does not understand the
        // instruction — fail closed.
        let operands_understood = inst.operands.iter().all(|op| {
            matches!(
                op,
                IrOperand::PReg(_)
                    | IrOperand::Imm(_)
                    | IrOperand::FImm(_)
                    | IrOperand::Special(_)
                    | IrOperand::Symbol(_)
                    | IrOperand::ExactModuleSymbol(_)
            )
        });
        if !operands_understood {
            track.clear();
            continue;
        }

        // Side-effecting / memory-writing instructions: only the compare
        // family (NZCV-only) and plain user stores (cannot write a tracked
        // slot, define nothing) may pass; everything else fails closed.
        if (flags.contains(InstFlags::WRITES_MEMORY) || flags.contains(InstFlags::HAS_SIDE_EFFECTS))
            && !spill_facts_compare_only(inst.opcode)
            && !spill_facts_plain_user_store(inst.opcode)
        {
            track.clear();
            continue;
        }

        // Ordinary computational instruction (or an allowed store/compare):
        // drop facts whose register overlaps any explicit def.
        let (def_positions, _) = classify_operand_positions(inst);
        for &pos in &def_positions {
            if let Some(IrOperand::PReg(def_reg)) = inst.operands.get(pos) {
                track.retain(|_, held| !regs_overlap(*held, *def_reg));
            }
        }
        for def_reg in inst.implicit_defs.iter() {
            track.retain(|_, held| !regs_overlap(*held, *def_reg));
        }
    }

    (track, redundant)
}

/// Solve the cross-block MUST-dataflow and return each block's entry facts, or
/// `None` when the extension is off or the function's control flow cannot be
/// pinned down exactly (every caller then falls back to per-block empty entry
/// facts, i.e. the block-local pass).
///
/// `IN[entry] = {}`; `IN[B] = meet over preds` (an entry survives only if EVERY
/// predecessor's exit map carries the same slot -> register pair); `OUT[B] =
/// walk(B, IN[B])`. `OUT` starts at TOP (the meet identity, `None` below) so a
/// fact generated in a loop header and preserved around the back edge is
/// discovered — the pessimistic `{}` start can never introduce a loop-carried
/// fact, which is exactly the huffbench decode shape. TOP is only ever an
/// identity in the meet: a block whose predecessors are all still TOP is left
/// unevaluated, and at the fixpoint every entry-reachable block is concrete
/// (the entry is concrete and concreteness propagates along every edge).
///
/// FAIL-CLOSED CONDITIONS (whole function falls back to block-local):
///  * the caller did not ask for it (the solve is opt-in behind
///    `TCG_SPILL_RELOAD_CSE_XBLOCK=1` — see the measurement table on
///    `elide_redundant_spill_slot_reloads`);
///  * an indirect `Br` whose successors are not fully described by a jump table
///    in the same block (a computed goto's edges are underivable);
///  * a `Block` operand on a non-branch instruction (an address-of-block whose
///    edge the CFG derivation does not model);
///  * the iteration does not reach a fixpoint inside its budget.
fn cross_block_spill_facts(
    ir_func: &IrMachFunction,
    trackable: &BTreeSet<StackSlotId>,
) -> Option<Vec<SpillFacts>> {
    let n_blocks = ir_func.blocks.len();
    if n_blocks < 2 {
        return None;
    }

    // Underivable-edge guards. Both are whole-function: one unmodelled edge
    // anywhere could let a fact reach a block it does not hold in.
    for block in &ir_func.blocks {
        let insts = || {
            block
                .insts
                .iter()
                .map(|id| ir_func.insts.get(id.0 as usize))
        };
        if insts().any(|inst| inst.is_none()) {
            return None;
        }
        let jump_table_in_block = insts().flatten().any(|inst| {
            inst.operands
                .iter()
                .any(|op| op.as_jump_table_index().is_some())
        });
        for inst in insts().flatten() {
            if inst.opcode == IrOpcode::Br && !jump_table_in_block {
                return None;
            }
            let has_block_operand = inst
                .operands
                .iter()
                .any(|op| matches!(op, IrOperand::Block(_)));
            if has_block_operand && !inst.is_branch() && !inst.is_terminator() {
                return None;
            }
        }
    }

    // Predecessors from the canonical post-RA CFG authority (branch operands,
    // jump-table targets, EH landing pads and layout fallthrough), plus a
    // supplementary scan of blocks that are NOT in `block_order` so a branch
    // living in an unlaid-out block still counts as a predecessor.
    let mut preds: Vec<BTreeSet<usize>> = vec![BTreeSet::new(); n_blocks];
    for (from, to) in derive_ir_cfg_edges_from_branch_operands(ir_func) {
        let (from, to) = (from.0 as usize, to.0 as usize);
        if from >= n_blocks || to >= n_blocks {
            return None;
        }
        preds[to].insert(from);
    }
    let laid_out: BTreeSet<usize> = ir_func
        .block_order
        .iter()
        .map(|b| b.0 as usize)
        .collect::<BTreeSet<_>>();
    for (idx, block) in ir_func.blocks.iter().enumerate() {
        if laid_out.contains(&idx) {
            continue;
        }
        for &inst_id in &block.insts {
            let inst = ir_func.insts.get(inst_id.0 as usize)?;
            for op in &inst.operands {
                if let IrOperand::Block(target) = op {
                    let target = target.0 as usize;
                    if target >= n_blocks {
                        return None;
                    }
                    preds[target].insert(idx);
                }
            }
        }
    }

    let entry = ir_func.entry.0 as usize;
    if entry >= n_blocks {
        return None;
    }

    // Visit order: `block_order` first (a near-topological sweep, so most
    // functions converge in one pass), then any block missing from it.
    let mut order: Vec<usize> = Vec::with_capacity(n_blocks);
    let mut seen = vec![false; n_blocks];
    for &block_id in &ir_func.block_order {
        let idx = block_id.0 as usize;
        if idx < n_blocks && !seen[idx] {
            seen[idx] = true;
            order.push(idx);
        }
    }
    for (idx, visited) in seen.iter().enumerate() {
        if !visited {
            order.push(idx);
        }
    }

    // `None` = TOP (not yet evaluated / meet identity).
    let mut ins: Vec<Option<SpillFacts>> = vec![None; n_blocks];
    let mut outs: Vec<Option<SpillFacts>> = vec![None; n_blocks];

    // The lattice is finite and every sweep is monotonically decreasing, so a
    // fixpoint always exists; sweeping in near-topological order reaches it in
    // about (loop depth + 2) passes. The budget caps the compile-time cost and
    // fails the whole function closed if anything ever needs more.
    const SWEEP_BUDGET: usize = 32;
    let mut converged = false;
    for _ in 0..SWEEP_BUDGET {
        let mut changed = false;
        for &idx in &order {
            let new_in: Option<SpillFacts> = if idx == entry || preds[idx].is_empty() {
                // Entry, and any block whose predecessors are not derivable
                // (unreachable): nothing may be assumed.
                Some(SpillFacts::new())
            } else {
                let mut acc: Option<SpillFacts> = None;
                for &p in &preds[idx] {
                    let Some(pred_out) = outs[p].as_ref() else {
                        continue; // TOP: the meet identity.
                    };
                    acc = Some(match acc {
                        None => pred_out.clone(),
                        Some(cur) => cur
                            .into_iter()
                            .filter(|(slot, reg)| pred_out.get(slot) == Some(reg))
                            .collect(),
                    });
                }
                acc
            };
            if new_in != ins[idx] {
                ins[idx] = new_in;
                changed = true;
            }
            if let Some(facts_in) = ins[idx].as_ref() {
                let (exit, _) = walk_block_spill_facts(ir_func, idx, facts_in, trackable);
                if outs[idx].as_ref() != Some(&exit) {
                    outs[idx] = Some(exit);
                    changed = true;
                }
            }
        }
        if !changed {
            converged = true;
            break;
        }
    }
    if !converged {
        return None;
    }

    Some(
        ins.into_iter()
            .map(|f| f.unwrap_or_default())
            .collect::<Vec<_>>(),
    )
}

/// A pure-integer-immediate materialization recovered as a rematerialization
/// template for a spilled loop-invariant constant: `<op> <dst>, <imm...>` with
/// NO register inputs. Cloned at each spill reload site with `dst` set to the
/// reload's already-assigned scratch register, so a constant the allocator had
/// to spill is recomputed per use instead of reloaded from the frame.
#[derive(Debug, Clone)]
struct RematConstTemplate {
    /// The defining move opcode (`Movz`/`Movn`/`MovI`).
    opcode: IrOpcode,
    /// The defining instruction's operands EXCLUDING the destination register —
    /// verified by the classifier to be all integer immediates. Prepended with
    /// the reload's scratch `PReg` to rebuild the full instruction.
    imm_operands: Vec<IrOperand>,
}

/// Identify spilled vregs whose unique defining instruction is a **Free**
/// rematerialization candidate — a single pure-integer-immediate move with no
/// register inputs — and return a map from each such vreg's spill SLOT to its
/// rematerialization template.
///
/// This is the sound counterpart of the allocator-side `apply_rematerialization`
/// (see the note on `ra_config.enable_remat`): it runs in the pipeline where the
/// reload's scratch register is knowable, so the recomputed value can be placed
/// in a real physical register instead of leaking an unallocated vreg.
///
/// SCOPE — Free (pure integer immediate) only:
///   * `Movz` / `Movn` / `MovI` — the measured spilled-loop-constant win
///     (Bubblesort / fannkuch LCG constants reloaded every iteration).
///   * EXCLUDES `Movz`+`Movk` chains: a chain defines its vreg twice, so the
///     "exactly one non-reload def" test rejects it (cloning one half of a
///     multi-instruction constant would be a miscompile).
///   * EXCLUDES `Adrp` / address materialization: those carry a `Symbol`
///     operand, which the all-immediate-operands test rejects. A lone `adrp` is
///     only half of a PC-relative address, and re-sinking a hoisted address
///     into a loop would undo LICM — the exact case the allocator-side
///     deeper-loop guard protects. Restricting to pure immediates makes that
///     guard unnecessary here (there is no hoisted address to un-hoist, and
///     replacing an existing per-iteration reload with a per-iteration
///     recompute is never worse).
///   * EXCLUDES `Cheap` (one register input): proving the input register's
///     physical assignment is live and unchanged at every reload site is a
///     dataflow claim we do not make.
///   * EXCLUDES slots shared by more than one spilled vreg (spill-slot reuse):
///     rewriting every reload of such a slot into one vreg's constant would
///     corrupt the other vreg's reloads.
fn find_free_remat_spilled_constants(
    ir_func: &IrMachFunction,
    spills: &[trust_cg_regalloc::SpillInfo],
) -> HashMap<StackSlotId, RematConstTemplate> {
    let mut result = HashMap::new();
    if spills.is_empty() {
        return result;
    }

    // Slot -> the distinct spilled vregs assigned to it. A slot used by more
    // than one vreg (spill-slot reuse) is disqualified below.
    let mut slot_vregs: HashMap<StackSlotId, BTreeSet<VReg>> = HashMap::new();
    for spill in spills {
        slot_vregs.entry(spill.slot).or_default().insert(spill.vreg);
    }
    let spilled: FxHashMap<VReg, StackSlotId> = spills.iter().map(|s| (s.vreg, s.slot)).collect();

    // Count non-reload definitions of each spilled vreg and remember the def.
    // Only instructions reachable through a block are considered; a spilled
    // constant's real definition always is.
    let mut def_count: HashMap<VReg, u32> = HashMap::new();
    let mut def_inst: HashMap<VReg, InstId> = HashMap::new();
    for &block_id in &ir_func.block_order {
        let Some(block) = ir_func.blocks.get(block_id.0 as usize) else {
            continue;
        };
        for &inst_id in &block.insts {
            let Some(inst) = ir_func.insts.get(inst_id.0 as usize) else {
                continue;
            };
            let (def_positions, _) = classify_operand_positions(inst);
            for &pos in &def_positions {
                if let Some(IrOperand::VReg(v)) = inst.operands.get(pos)
                    && spilled.contains_key(v)
                {
                    *def_count.entry(*v).or_insert(0) += 1;
                    def_inst.insert(*v, inst_id);
                }
            }
        }
    }

    for (&vreg, &slot) in &spilled {
        // Slot must belong to exactly this one spilled vreg (no reuse sharing).
        if slot_vregs.get(&slot).map(|s| s.len()).unwrap_or(0) != 1 {
            continue;
        }
        // Exactly one definition of the vreg in the function.
        if def_count.get(&vreg).copied().unwrap_or(0) != 1 {
            continue;
        }
        let Some(&def_id) = def_inst.get(&vreg) else {
            continue;
        };
        let Some(inst) = ir_func.insts.get(def_id.0 as usize) else {
            continue;
        };
        // Free integer-immediate materialization only (single instruction).
        if !matches!(
            inst.opcode,
            IrOpcode::Movz | IrOpcode::Movn | IrOpcode::MovI
        ) {
            continue;
        }
        let (def_positions, use_positions) = classify_operand_positions(inst);
        // Exactly one def operand, and it is this vreg.
        if def_positions.len() != 1 {
            continue;
        }
        if inst
            .operands
            .get(def_positions[0])
            .and_then(|o| o.as_vreg())
            != Some(vreg)
        {
            continue;
        }
        // Every non-def operand must be a pure integer immediate: no register
        // input, no `Symbol`/adrp, no memory, no stack slot.
        let all_imm = use_positions
            .iter()
            .all(|&p| matches!(inst.operands.get(p), Some(IrOperand::Imm(_))));
        if !all_imm {
            continue;
        }
        // Build the template operands = everything except the destination,
        // preserving order. Defensive re-check that they are all immediates.
        let imm_operands: Vec<IrOperand> = inst
            .operands
            .iter()
            .enumerate()
            .filter(|(i, _)| *i != def_positions[0])
            .map(|(_, o)| o.clone())
            .collect();
        if imm_operands.is_empty() || !imm_operands.iter().all(|o| matches!(o, IrOperand::Imm(_))) {
            continue;
        }
        result.insert(
            slot,
            RematConstTemplate {
                opcode: inst.opcode,
                imm_operands,
            },
        );
    }
    result
}

/// Replace each spill RELOAD (`LdrRI <scratch>, [<slot>]`) of a Free-constant
/// spill slot with a rematerialization of that constant into the SAME scratch
/// register. The reload's scratch is already assigned by
/// [`materialize_spilled_operands_at_sites`], so the recomputed value lands in
/// exactly the register the consumer expects — this is the physical-register
/// step the allocator-side remat could not perform (it ran before scratch
/// assignment, leaving an unresolved vreg the encoder rejects).
///
/// Keyed by SLOT, so it fires uniformly for reloads emitted by ANY
/// materialization path (the general path, the multiply-accumulate helper,
/// etc.). Every slot in `remat` is a dedicated spill slot for a single Free
/// constant (`find_free_remat_spilled_constants` disqualifies shared slots), so
/// its ONLY `LdrRI` reads are reloads of that constant — rewriting them is
/// value-preserving. The one-time spill STORE to the slot is left in place (a
/// non-loop dead store); the per-iteration reload is what this removes.
///
/// Returns the number of reloads rematerialized.
fn remat_free_spilled_constant_reloads(
    ir_func: &mut IrMachFunction,
    remat: &HashMap<StackSlotId, RematConstTemplate>,
) -> u32 {
    if remat.is_empty() {
        return 0;
    }
    let mut count = 0u32;
    for inst in &mut ir_func.insts {
        if inst.opcode != IrOpcode::LdrRI || inst.operands.len() != 2 {
            continue;
        }
        let IrOperand::PReg(scratch) = inst.operands[0] else {
            continue;
        };
        let IrOperand::StackSlot(slot) = inst.operands[1] else {
            continue;
        };
        let Some(template) = remat.get(&slot) else {
            continue;
        };
        let source_loc = inst.source_loc;
        let mut operands = Vec::with_capacity(1 + template.imm_operands.len());
        operands.push(IrOperand::PReg(scratch));
        operands.extend(template.imm_operands.iter().cloned());
        let mut new_inst = IrMachInst::new(template.opcode, operands);
        new_inst.source_loc = source_loc;
        *inst = new_inst;
        count += 1;
    }
    count
}

fn spill_materialization_trace_enabled(function_name: &str) -> bool {
    match std::env::var("TRUST_CG_TRACE_SPILL_MATERIALIZATION") {
        Ok(filter) => filter == "1" || filter == "all" || function_name.contains(&filter),
        Err(_) => false,
    }
}

fn add_missing_spill_materialization_sites(
    ir_func: &IrMachFunction,
    sites: &mut FxHashMap<InstId, SpillMaterializationSite>,
    spills: &[trust_cg_regalloc::SpillInfo],
) {
    let spill_slots: FxHashMap<VReg, StackSlotId> = spills
        .iter()
        .map(|spill| (spill.vreg, spill.slot))
        .collect();
    if spill_slots.is_empty() {
        return;
    }

    for &block_id in &ir_func.block_order {
        let block = ir_func.block(block_id);
        for &inst_id in &block.insts {
            let inst = ir_func.inst(inst_id);
            let (def_positions, use_positions) = classify_operand_positions(inst);

            for &pos in &use_positions {
                let Some((vreg, slot)) = spilled_vreg_at(inst, pos, &spill_slots) else {
                    continue;
                };
                sites.entry(inst_id).or_default().uses.insert(vreg, slot);
            }

            for &pos in &def_positions {
                let Some((vreg, slot)) = spilled_vreg_at(inst, pos, &spill_slots) else {
                    continue;
                };
                sites.entry(inst_id).or_default().defs.insert(vreg, slot);
            }
        }
    }
}

fn spill_slot_for_vreg(
    vreg: VReg,
    spill_slots: &FxHashMap<VReg, StackSlotId>,
) -> Option<StackSlotId> {
    spill_slots.get(&vreg).copied()
}

fn is_regalloc_spill_pseudo(opcode: u16) -> bool {
    opcode == trust_cg_regalloc::spill::PSEUDO_SPILL_LOAD
        || opcode == trust_cg_regalloc::spill::PSEUDO_SPILL_STORE
}

fn is_regalloc_inserted_pseudo(opcode: u16) -> bool {
    is_regalloc_spill_pseudo(opcode)
        || opcode == trust_cg_regalloc::phi_elim::PSEUDO_COPY
        || opcode == trust_cg_regalloc::phi_elim::PSEUDO_JUMP
        || opcode == 0xFFFF
}

#[derive(Debug, Default)]
struct SpillMaterializationSite {
    uses: FxHashMap<VReg, StackSlotId>,
    defs: FxHashMap<VReg, StackSlotId>,
}

impl SpillMaterializationSite {
    fn is_empty(&self) -> bool {
        self.uses.is_empty() && self.defs.is_empty()
    }

    fn merge(&mut self, other: SpillMaterializationSite) {
        self.uses.extend(other.uses);
        self.defs.extend(other.defs);
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct SpillMaterializedStore {
    vreg: VReg,
    slot: StackSlotId,
    inst: InstId,
}

#[derive(Debug, Clone, Default)]
struct SpillMaterializationDebugInfo {
    stores: Vec<SpillMaterializedStore>,
}

impl SpillMaterializationDebugInfo {
    fn record_store(&mut self, vreg: VReg, slot: StackSlotId, inst: InstId) {
        self.stores
            .push(SpillMaterializedStore { vreg, slot, inst });
    }
}

fn regalloc_spill_pseudo_key(
    inst: &trust_cg_regalloc::machine_types::RegAllocInst,
) -> Option<(VReg, StackSlotId)> {
    use trust_cg_regalloc::machine_types::RegAllocOperand as RaOperand;

    let slot = inst.uses.iter().find_map(|operand| match operand {
        RaOperand::StackSlot(slot) => Some(*slot),
        _ => None,
    })?;

    if inst.opcode == trust_cg_regalloc::spill::PSEUDO_SPILL_LOAD {
        let vreg = inst.defs.iter().find_map(|operand| operand.as_vreg())?;
        return Some((vreg, slot));
    }

    if inst.opcode == trust_cg_regalloc::spill::PSEUDO_SPILL_STORE {
        let vreg = inst.uses.iter().find_map(|operand| operand.as_vreg())?;
        return Some((vreg, slot));
    }

    None
}

fn retained_spill_materialization_sites(
    ra_func: &trust_cg_regalloc::RegAllocFunction,
    spills: &[trust_cg_regalloc::SpillInfo],
) -> FxHashMap<usize, SpillMaterializationSite> {
    let valid_spills: BTreeSet<(VReg, StackSlotId)> = spills
        .iter()
        .map(|spill| (spill.vreg, spill.slot))
        .collect();
    if valid_spills.is_empty() {
        return FxHashMap::default();
    }

    let mut sites = FxHashMap::default();
    for block in &ra_func.blocks {
        let mut pending_loads = Vec::new();
        let mut last_materialized_inst = None;

        for inst_id in &block.insts {
            let Some(inst) = ra_func.insts.get(inst_id.0 as usize) else {
                continue;
            };

            if let Some((vreg, slot)) = regalloc_spill_pseudo_key(inst) {
                if !valid_spills.contains(&(vreg, slot)) {
                    continue;
                }

                if inst.opcode == trust_cg_regalloc::spill::PSEUDO_SPILL_LOAD {
                    pending_loads.push((vreg, slot));
                } else if let Some(target) = last_materialized_inst {
                    let site: &mut SpillMaterializationSite = sites.entry(target).or_default();
                    site.defs.insert(vreg, slot);
                }
                continue;
            }

            if !pending_loads.is_empty() {
                let site: &mut SpillMaterializationSite =
                    sites.entry(inst_id.0 as usize).or_default();
                for (vreg, slot) in pending_loads.drain(..) {
                    site.uses.insert(vreg, slot);
                }
            }
            last_materialized_inst = Some(inst_id.0 as usize);
        }
    }

    sites
}

fn remap_spill_materialization_sites(
    sites: FxHashMap<usize, SpillMaterializationSite>,
    inst_map: &[Option<InstId>],
) -> FxHashMap<InstId, SpillMaterializationSite> {
    let mut remapped = FxHashMap::default();
    for (old_inst_idx, site) in sites {
        let Some(Some(new_inst_id)) = inst_map.get(old_inst_idx) else {
            continue;
        };
        remapped
            .entry(*new_inst_id)
            .or_insert_with(SpillMaterializationSite::default)
            .merge(site);
    }
    remapped
}

fn effective_spills_from_materialization_sites(
    sites: &FxHashMap<InstId, SpillMaterializationSite>,
    spills: &[trust_cg_regalloc::SpillInfo],
) -> Vec<trust_cg_regalloc::SpillInfo> {
    let retained: BTreeSet<(VReg, StackSlotId)> = sites
        .values()
        .flat_map(|site| site.uses.iter().chain(site.defs.iter()))
        .map(|(vreg, slot)| (*vreg, *slot))
        .collect();

    if retained.is_empty() {
        return Vec::new();
    }

    let mut emitted = BTreeSet::new();
    spills
        .iter()
        .filter_map(|spill| {
            let key = (spill.vreg, spill.slot);
            if retained.contains(&key) && emitted.insert(key) {
                Some(spill.clone())
            } else {
                None
            }
        })
        .collect()
}

fn regalloc_operand_to_ir(
    operand: &trust_cg_regalloc::machine_types::RegAllocOperand,
) -> IrOperand {
    use trust_cg_regalloc::machine_types::RegAllocOperand as RaOperand;

    match operand {
        RaOperand::VReg(vreg) => IrOperand::VReg(*vreg),
        RaOperand::PReg(preg) => IrOperand::PReg(*preg),
        RaOperand::Imm(imm) => IrOperand::Imm(*imm),
        RaOperand::FImm(imm) => IrOperand::FImm(*imm),
        RaOperand::Block(block) => IrOperand::Block(*block),
        RaOperand::StackSlot(slot) => IrOperand::StackSlot(*slot),
    }
}

fn regalloc_opcode_to_ir(opcode: u16) -> Result<IrOpcode, PipelineError> {
    if opcode == trust_cg_regalloc::spill::PSEUDO_SPILL_LOAD {
        return Ok(IrOpcode::LdrRI);
    }
    if opcode == trust_cg_regalloc::spill::PSEUDO_SPILL_STORE {
        return Ok(IrOpcode::StrRI);
    }
    if opcode == IrOpcode::Copy as u16 {
        return Ok(IrOpcode::Copy);
    }
    if opcode == trust_cg_regalloc::phi_elim::PSEUDO_COPY {
        return Ok(IrOpcode::Copy);
    }
    if opcode == trust_cg_regalloc::phi_elim::PSEUDO_JUMP {
        return Ok(IrOpcode::B);
    }
    if opcode == 0xFFFF {
        return Ok(IrOpcode::Nop);
    }

    // The valid AArch64 opcode discriminant space is dense and 0-based. The
    // u16 round-trip (`ir_to_regalloc`'s `opcode as u16` -> this transmute)
    // happens entirely within one process, so both sides always agree on the
    // discriminants. These classes may reach register allocation:
    //   * every opcode up to `VolatileStrhRI`,
    //   * the call-like ELF `TlsDescCall`, which frame lowering expands into
    //     its four TLSDESC slots only after allocation, and
    //   * the opaque LL/SC pseudos (`trust_cg_ir::llsc::LlscPseudo`),
    //   * the appended scalar FP rounding instruction `FrintnRR`, and
    //   * the appended FEAT_CRC32 instructions `Crc32B` through `Crc32Cx`.
    // `AlignNop` (emission-time padding), the expanded TLSDESC slots and the
    // exclusives/CLREX that the LL/SC expansion emits are created only after
    // allocation, so their discriminants stay refused here. A newly appended
    // opcode that must reach allocation fails closed here for EVERY function
    // containing it until it is admitted explicitly (the LdrGottprel/TLSIE
    // lesson — caught by `e2e_aarch64_elf_tlsie`, which drives the full
    // prepare_function path).
    const MAX_ORDINARY_AARCH64_OPCODE: u16 = IrOpcode::VolatileStrhRI as u16;
    const LAST_AARCH64_OPCODE: u16 = IrOpcode::Crc32Cx as u16;
    if opcode > LAST_AARCH64_OPCODE {
        return Err(PipelineError::InvalidOperand(format!(
            "unknown regalloc opcode 0x{opcode:04x}"
        )));
    }

    // SAFETY: AArch64Opcode has a dense 0-based discriminant space whose last
    // variant is `Crc32Cx` (checked above), so every admitted value
    // names a real variant. The enum has more than 256 fieldless variants, so
    // its tag (and this transmute's source) is u16; the compiler rejects this
    // line (E0512) if the enum ever shrinks back below 257 variants — change
    // the source type back to u8 in that case.
    let candidate = unsafe { std::mem::transmute::<u16, IrOpcode>(opcode) };
    if opcode > MAX_ORDINARY_AARCH64_OPCODE
        && candidate != IrOpcode::FrintnRR
        && !aarch64_opcode_requires_crc(candidate)
        && candidate != IrOpcode::TlsDescCall
        && trust_cg_ir::llsc::LlscPseudo::of(candidate).is_none()
    {
        return Err(PipelineError::InvalidOperand(format!(
            "unknown regalloc opcode 0x{opcode:04x}"
        )));
    }
    Ok(candidate)
}

fn regalloc_explicit_operand_count(
    opcode: IrOpcode,
    def_count: usize,
    use_count: usize,
) -> Result<usize, PipelineError> {
    let max_operand_count = def_count.checked_add(use_count).ok_or_else(|| {
        PipelineError::InvalidOperand(format!(
            "{opcode:?} regalloc rebuild operand count overflow for {def_count} defs and {use_count} uses"
        ))
    })?;

    let mut matches = (0..=max_operand_count).filter(|&operand_count| {
        let roles = aarch64_operand_roles(opcode, operand_count);
        let role_def_count = roles
            .iter()
            .filter(|&&role| matches!(role, OperandRole::Def | OperandRole::DefUse))
            .count();
        let role_use_count = roles
            .iter()
            .filter(|&&role| matches!(role, OperandRole::Use | OperandRole::DefUse))
            .count();
        role_def_count == def_count && role_use_count == use_count
    });

    let Some(operand_count) = matches.next() else {
        return Err(PipelineError::InvalidOperand(format!(
            "{opcode:?} regalloc rebuild could not infer operand count from {def_count} defs and {use_count} uses"
        )));
    };

    if matches.next().is_some() {
        return Err(PipelineError::InvalidOperand(format!(
            "{opcode:?} regalloc rebuild inferred ambiguous operand count from {def_count} defs and {use_count} uses"
        )));
    }

    Ok(operand_count)
}

fn rebuild_operands_from_regalloc(
    opcode: IrOpcode,
    defs: &[trust_cg_regalloc::machine_types::RegAllocOperand],
    uses: &[trust_cg_regalloc::machine_types::RegAllocOperand],
) -> Result<Vec<IrOperand>, PipelineError> {
    let operand_count = regalloc_explicit_operand_count(opcode, defs.len(), uses.len())?;
    let roles = aarch64_operand_roles(opcode, operand_count);
    let mut def_iter = defs.iter();
    let mut use_iter = uses.iter();
    let mut operands = Vec::with_capacity(operand_count);

    for (idx, role) in roles.into_iter().enumerate() {
        match role {
            OperandRole::Def => {
                let operand = def_iter.next().ok_or_else(|| {
                    PipelineError::InvalidOperand(format!(
                        "{opcode:?} regalloc rebuild missing def for operand {idx}"
                    ))
                })?;
                operands.push(regalloc_operand_to_ir(operand));
            }
            OperandRole::Use => {
                let operand = use_iter.next().ok_or_else(|| {
                    PipelineError::InvalidOperand(format!(
                        "{opcode:?} regalloc rebuild missing use for operand {idx}"
                    ))
                })?;
                operands.push(regalloc_operand_to_ir(operand));
            }
            OperandRole::DefUse => {
                let def_operand = def_iter.next().ok_or_else(|| {
                    PipelineError::InvalidOperand(format!(
                        "{opcode:?} regalloc rebuild missing tied def for operand {idx}"
                    ))
                })?;
                let _use_operand = use_iter.next().ok_or_else(|| {
                    PipelineError::InvalidOperand(format!(
                        "{opcode:?} regalloc rebuild missing tied use for operand {idx}"
                    ))
                })?;
                operands.push(regalloc_operand_to_ir(def_operand));
            }
        }
    }

    if def_iter.next().is_some() || use_iter.next().is_some() {
        return Err(PipelineError::InvalidOperand(format!(
            "{opcode:?} regalloc rebuild left extra explicit operands from {} defs and {} uses",
            defs.len(),
            uses.len()
        )));
    }

    Ok(operands)
}

/// Regalloc sees these operands as `Imm(0)` placeholders; codegen still needs
/// the original relocation/frame metadata after the regalloc-side rebuild.
fn is_regalloc_opaque_operand(operand: &IrOperand) -> bool {
    matches!(
        operand,
        IrOperand::Symbol(_)
            | IrOperand::ExactModuleSymbol(_)
            | IrOperand::JumpTableIndex(_)
            | IrOperand::IncomingArg(_)
    )
}

fn regalloc_rebuilt_operand_matches_original(rebuilt: &IrOperand, original: &IrOperand) -> bool {
    if is_regalloc_opaque_operand(original) {
        return matches!(rebuilt, IrOperand::Imm(0));
    }

    match (rebuilt, original) {
        (IrOperand::VReg(rebuilt), IrOperand::VReg(original)) => rebuilt == original,
        (IrOperand::PReg(rebuilt), IrOperand::PReg(original)) => rebuilt == original,
        (IrOperand::PReg(preg), IrOperand::VReg(vreg))
        | (IrOperand::VReg(vreg), IrOperand::PReg(preg)) => {
            project_allocated_preg(*preg, vreg.class).is_some()
        }
        _ => rebuilt == original,
    }
}

fn regalloc_rebuilt_operands_match_original(operands: &[IrOperand], original: &IrMachInst) -> bool {
    operands.len() == original.operands.len()
        && operands
            .iter()
            .zip(&original.operands)
            .all(|(rebuilt, original)| regalloc_rebuilt_operand_matches_original(rebuilt, original))
}

/// LOOSE per-operand provenance match: like the strict rule, but a rebuilt VReg
/// may carry a DIFFERENT id than the original VReg as long as the register
/// class agrees. Live-range splitting renames a def/use to a fresh split-child
/// vreg (`split_interval` -> `alloc_vreg`), so a spilled split child reaches the
/// rebuild with an id the original stream never contained; identity then rests
/// on the non-register operands (stack slots, immediates, opaque placeholders),
/// which regalloc never rewrites. Physical registers stay EXACT — pregs are
/// pinned constraints, never renamed.
fn regalloc_rebuilt_operand_matches_original_loose(
    rebuilt: &IrOperand,
    original: &IrOperand,
) -> bool {
    if is_regalloc_opaque_operand(original) {
        return matches!(rebuilt, IrOperand::Imm(0));
    }

    match (rebuilt, original) {
        (IrOperand::VReg(rebuilt), IrOperand::VReg(original)) => rebuilt.class == original.class,
        (IrOperand::PReg(rebuilt), IrOperand::PReg(original)) => rebuilt == original,
        (IrOperand::PReg(preg), IrOperand::VReg(vreg))
        | (IrOperand::VReg(vreg), IrOperand::PReg(preg)) => {
            project_allocated_preg(*preg, vreg.class).is_some()
        }
        _ => rebuilt == original,
    }
}

fn regalloc_rebuilt_operands_match_original_loose(
    operands: &[IrOperand],
    original: &IrMachInst,
) -> bool {
    operands.len() == original.operands.len()
        && operands
            .iter()
            .zip(&original.operands)
            .all(|(rebuilt, original)| {
                regalloc_rebuilt_operand_matches_original_loose(rebuilt, original)
            })
}

fn match_regalloc_original_candidate<'a>(
    original_insts: &'a [IrMachInst],
    original_idx: usize,
    opcode: IrOpcode,
    operands: &[IrOperand],
) -> Result<(Option<&'a IrMachInst>, usize), PipelineError> {
    let mut matched = None;
    let mut matched_idx = original_idx;
    let mut matched_opaque = false;
    let mut saw_skipped_opaque = false;

    for (idx, candidate) in original_insts.iter().enumerate().skip(original_idx) {
        if candidate.opcode != opcode {
            continue;
        }

        let candidate_opaque = has_regalloc_opaque_operand(candidate);
        if regalloc_rebuilt_operands_match_original(operands, candidate) {
            if matched.is_some() {
                if matched_opaque || candidate_opaque {
                    return Err(PipelineError::InvalidOperand(format!(
                        "{opcode:?} regalloc rebuild found ambiguous opaque operand provenance"
                    )));
                }
                continue;
            }
            matched = Some(candidate);
            matched_idx = idx;
            matched_opaque = candidate_opaque;
        } else {
            saw_skipped_opaque |= candidate_opaque;
        }
    }

    if matched.is_none() && saw_skipped_opaque {
        // Strict matching found nothing, and an opaque candidate is still in
        // range, so declining to match could restore the wrong (or no)
        // relocation. Retry with the LOOSE rule: live-range splitting renames
        // vregs to fresh split-child ids (e.g. a spilled split child of an
        // `AddPCRel dst, sp, slot` frame-address def), which the strict
        // VReg-id-equality rule can never re-associate. The loose rule keys
        // identity on the non-register operands instead — accepted ONLY when
        // exactly one candidate matches, so an ambiguous provenance (two
        // opaque candidates of the same shape) still fails closed.
        let mut loose_matched = None;
        let mut loose_idx = original_idx;
        let mut loose_ambiguous = false;
        for (idx, candidate) in original_insts.iter().enumerate().skip(original_idx) {
            if candidate.opcode != opcode {
                continue;
            }
            if regalloc_rebuilt_operands_match_original_loose(operands, candidate) {
                if loose_matched.is_some() {
                    loose_ambiguous = true;
                    break;
                }
                loose_matched = Some(candidate);
                loose_idx = idx;
            }
        }
        if let Some(candidate) = loose_matched
            && !loose_ambiguous
        {
            return Ok((Some(candidate), loose_idx + 1));
        }
        // No (unambiguous) loose match either. That is only a problem when the
        // rebuilt instruction could actually be missing an opaque operand: the
        // regalloc blinding replaces Symbol/JumpTableIndex/IncomingArg with an
        // `Imm(0)` placeholder, so a rebuilt instruction with NO `Imm(0)`
        // operand provably needs no restoration — failing to find its original
        // costs only optional metadata (proof/source_loc), never a relocation.
        // Rematerialization reaches exactly this case: a remat CLONE of a
        // frame-address def (`AddPCRel dst, sp, slot`) appears late in the
        // stream after the cursor has consumed its original, while unrelated
        // Symbol-form candidates of the same opcode sit ahead of the cursor
        // (`saw_skipped_opaque`). The clone carries its full operands, so it is
        // safe to rebuild without provenance. Anything still holding an
        // `Imm(0)` placeholder stays fail-closed.
        if !rebuilt_may_need_opaque_provenance(operands) {
            return Ok((None, original_idx));
        }
        return Err(PipelineError::InvalidOperand(format!(
            "{opcode:?} regalloc rebuild could not match opaque operand provenance"
        )));
    }

    Ok((matched, matched.map_or(original_idx, |_| matched_idx + 1)))
}

/// True when a rebuilt instruction could be carrying a regalloc-blinded opaque
/// operand: the blinding writes `Imm(0)` placeholders (see
/// [`restore_regalloc_opaque_operands`]), so an instruction without any
/// `Imm(0)` operand cannot need opaque-provenance restoration. (A genuine zero
/// immediate also answers true — conservative: such instructions keep the
/// fail-closed provenance requirement.)
fn rebuilt_may_need_opaque_provenance(operands: &[IrOperand]) -> bool {
    operands
        .iter()
        .any(|operand| matches!(operand, IrOperand::Imm(0)))
}

fn indexed_regalloc_original_candidate<'a>(
    original_insts: &'a [IrMachInst],
    ra_inst_idx: usize,
    opcode: IrOpcode,
    operands: &[IrOperand],
) -> Result<Option<&'a IrMachInst>, PipelineError> {
    let Some(candidate) = original_insts.get(ra_inst_idx) else {
        return Ok(None);
    };

    if candidate.opcode != opcode {
        if has_regalloc_opaque_operand(candidate) && rebuilt_may_need_opaque_provenance(operands) {
            return Err(PipelineError::InvalidOperand(format!(
                "{opcode:?} regalloc rebuild changed opcode for indexed opaque operand provenance"
            )));
        }
        return Ok(None);
    }

    if regalloc_rebuilt_operands_match_original(operands, candidate) {
        return Ok(Some(candidate));
    }

    if has_regalloc_opaque_operand(candidate) && rebuilt_may_need_opaque_provenance(operands) {
        // Strict matching failed on an index-aligned opaque candidate. Arena
        // slots are index-stable across regalloc (the adapter converts the IR
        // insts 1:1 in order, spill/reload code is `func.insts.push`ed at the
        // arena END, and post-RA deletions tombstone to the 0xFFFF NOP rather
        // than compacting), so the candidate at this index IS this instruction
        // — the only ways its registers differ are the preg assignment
        // (already accepted by the strict rule) and a live-range SPLIT rename
        // to a fresh split-child vreg id (`split_interval` -> `alloc_vreg` ->
        // in-place `rewrite_vreg_operands`), which the strict VReg-id-equality
        // rule can never re-associate. Accept the candidate under the LOOSE
        // rule — register classes must agree and every non-register operand
        // must be identical — exactly the documented loose rule the SCAN
        // matcher already applies (and stronger here: the index pins the
        // candidate set to ONE, so there is no ambiguity to guard). Without
        // this, an -O2 register-pressure split of e.g. an `Adrp dst,
        // Symbol(..)` def fails the whole compile ("could not match indexed
        // opaque operand provenance" — the get_backtrace_style unwind-lane
        // fallback class). Anything that fails even the loose rule (an operand
        // COUNT or non-register operand change) still fails closed.
        if regalloc_rebuilt_operands_match_original_loose(operands, candidate) {
            return Ok(Some(candidate));
        }
        return Err(PipelineError::InvalidOperand(format!(
            "{opcode:?} regalloc rebuild could not match indexed opaque operand provenance \
             (rebuilt {operands:?} vs original {:?})",
            candidate.operands
        )));
    }

    Ok(None)
}

fn restore_regalloc_opaque_operands(operands: &mut [IrOperand], original: &IrMachInst) {
    for (idx, operand) in operands.iter_mut().enumerate() {
        if !matches!(operand, IrOperand::Imm(0)) {
            continue;
        }

        if let Some(
            original_operand @ (IrOperand::Symbol(_)
            | IrOperand::ExactModuleSymbol(_)
            | IrOperand::JumpTableIndex(_)
            | IrOperand::IncomingArg(_)),
        ) = original.operands.get(idx)
        {
            *operand = original_operand.clone();
        }
    }
}

fn has_regalloc_opaque_operand(inst: &IrMachInst) -> bool {
    inst.operands.iter().any(is_regalloc_opaque_operand)
}

#[cfg(test)]
fn rebuild_ir_from_regalloc(
    ir_func: &mut IrMachFunction,
    ra_func: &trust_cg_regalloc::RegAllocFunction,
) -> Result<(), PipelineError> {
    rebuild_ir_from_regalloc_with_map(ir_func, ra_func).map(|_| ())
}

fn rebuild_ir_from_regalloc_with_map(
    ir_func: &mut IrMachFunction,
    ra_func: &trust_cg_regalloc::RegAllocFunction,
) -> Result<Vec<Option<InstId>>, PipelineError> {
    validate_exact_aarch64_eh_call_identity(ir_func)?;
    // MOVE the instruction arena out rather than deep-cloning it.
    //
    // `MachInst` owns `operands: Vec<MachOperand>`, so `ir_func.insts.clone()`
    // was N heap allocations + N memcpys on entry and N frees on exit, for a
    // snapshot used strictly READ-ONLY (provenance matching and opaque-operand
    // restore) and then discarded. Nothing between here and the `ir_func.insts =
    // rebuilt_insts` below reads `ir_func` at all, so the arena can simply be
    // taken.
    //
    // Stage every recoverable instruction, block and exact EH identity remap
    // before commit. Restore the original arena on any precommit failure;
    // metadata and other owners remain unchanged. A bare `take` would leave
    // an empty arena on error. Emptiness cannot signal commit because a valid
    // rebuilt arena itself may be empty.
    let original_insts: Vec<IrMachInst> = std::mem::take(&mut ir_func.insts);
    let mut committed = false;
    let out = rebuild_ir_from_regalloc_body(ir_func, ra_func, &original_insts, &mut committed);
    if out.is_err() && !committed {
        ir_func.insts = original_insts;
    }
    out
}

fn rebuild_ir_from_regalloc_body(
    ir_func: &mut IrMachFunction,
    ra_func: &trust_cg_regalloc::RegAllocFunction,
    original_insts: &[IrMachInst],
    committed: &mut bool,
) -> Result<Vec<Option<InstId>>, PipelineError> {
    let mut rebuilt_insts = Vec::with_capacity(ra_func.insts.len());
    let mut inst_map: Vec<Option<InstId>> = Vec::with_capacity(ra_func.insts.len());
    let mut original_idx = 0usize;
    let protected =
        eh_call_identity::original_call_indices(&ir_func.eh_metadata.call_site_bindings);
    let malformed_eh = |detail: String| PipelineError::MalformedAarch64Eh {
        function: ir_func.name.clone(),
        detail: format!("invalid AArch64 EH metadata/layout: {detail}"),
    };

    for (ra_inst_idx, ra_inst) in ra_func.insts.iter().enumerate() {
        if is_regalloc_spill_pseudo(ra_inst.opcode) {
            inst_map.push(None);
            continue;
        }

        let opcode = regalloc_opcode_to_ir(ra_inst.opcode)?;
        let mut operands = if ra_inst.opcode == 0xFFFF {
            Vec::new()
        } else if opcode_uses_all_operands_for_regalloc(opcode, ra_inst.flags) {
            ra_inst
                .defs
                .iter()
                .chain(ra_inst.uses.iter())
                .map(regalloc_operand_to_ir)
                .collect()
        } else {
            rebuild_operands_from_regalloc(opcode, &ra_inst.defs, &ra_inst.uses)?
        };
        let original = if protected
            .as_ref()
            .is_some_and(|indices| indices.contains(&ra_inst_idx))
        {
            // The adapter issued this exact allocator slot from the original
            // arena slot. Operand transport is checked at this one slot;
            // protected calls never search for a replacement original.
            original_idx = original_idx.max(ra_inst_idx + 1);
            Some(
                eh_call_identity::protected_regalloc_original(
                    original_insts,
                    ra_inst_idx,
                    opcode,
                    &operands,
                )
                .map_err(malformed_eh)?,
            )
        } else if is_regalloc_inserted_pseudo(ra_inst.opcode) {
            None
        } else {
            let indexed = indexed_regalloc_original_candidate(
                original_insts,
                ra_inst_idx,
                opcode,
                &operands,
            )?;
            if let Some(original) = indexed {
                original_idx = original_idx.max(ra_inst_idx + 1);
                Some(original)
            } else {
                let (matched, next_original_idx) = match_regalloc_original_candidate(
                    original_insts,
                    original_idx,
                    opcode,
                    &operands,
                )?;
                original_idx = next_original_idx;
                matched
            }
        };
        if let Some(original) = original
            && original.opcode == opcode
        {
            restore_regalloc_opaque_operands(&mut operands, original);
        }
        let mut inst = IrMachInst::with_flags(opcode, operands, ra_inst.flags);
        if matches!(
            ra_inst.opcode,
            trust_cg_regalloc::spill::PSEUDO_SPILL_LOAD
                | trust_cg_regalloc::spill::PSEUDO_SPILL_STORE
        ) {
            // Allocator spill traffic keeps its provenance for the final-stream
            // frame dataflow net (see `InstFlags::SPILL_SLOT_ACCESS`).
            inst.flags
                .insert(trust_cg_ir::inst::InstFlags::SPILL_SLOT_ACCESS);
        }
        inst.implicit_defs = trust_cg_ir::inst::intern_pregs(&ra_inst.implicit_defs);
        inst.implicit_uses = trust_cg_ir::inst::intern_pregs(&ra_inst.implicit_uses);
        if let Some(original) = original {
            inst.proof = original.proof;
            inst.source_loc = original.source_loc;
        }
        inst_map.push(Some(InstId(rebuilt_insts.len() as u32)));
        rebuilt_insts.push(inst);
    }

    let mut rebuilt_blocks = Vec::with_capacity(ra_func.blocks.len());
    for block in &ra_func.blocks {
        let mut insts = Vec::with_capacity(block.insts.len());
        for old_id in &block.insts {
            let mapped = inst_map.get(old_id.0 as usize).ok_or_else(|| {
                PipelineError::InvalidOperand(format!(
                    "regalloc block references unknown instruction {}",
                    old_id.0
                ))
            })?;
            if let Some(new_id) = mapped {
                insts.push(*new_id);
            }
        }
        rebuilt_blocks.push(trust_cg_ir::function::MachBlock {
            insts,
            preds: block.preds.clone(),
            succs: block.succs.clone(),
            loop_depth: block.loop_depth,
        });
    }
    let remapped_bindings = eh_call_identity::remap_regalloc_bindings(
        &ir_func.eh_metadata.call_site_bindings,
        original_insts,
        ra_func,
        &inst_map,
        &rebuilt_insts,
        &rebuilt_blocks,
    )
    .map_err(malformed_eh)?;
    // All identity/block remaps are staged before either owner is published.
    // Failure above restores the original arena and leaves EH custody intact.
    *committed = true;
    ir_func.insts = rebuilt_insts;
    ir_func.eh_metadata.call_site_bindings = remapped_bindings;
    ir_func.blocks = rebuilt_blocks;
    ir_func.block_order = ra_func.block_order.clone();
    ir_func.entry = ra_func.entry_block;
    ir_func.next_vreg = ra_func.next_vreg;
    rebuild_stack_slots_from_regalloc(ir_func, ra_func);

    // NOTE (defect #5, fixed): dense switches that lower to a JumpTable used to
    // fail to encode at O2/O3 with "jump table target block has no byte offset",
    // because the jump-table case blocks are reachable only through the
    // data-driven indirect branch and the CFG round-trips
    // (`rebuild_ir_cfg_edges_from_branch_operands` here, and
    // `cfg_simplify::rebuild_cfg_edges` in the opt pipeline) rebuilt succ/pred
    // edges from explicit `Block` operands only, dropping the targets and then
    // pruning them from `block_order`. Both round-trips now seed the jump-table
    // successor edges from `jump_tables[idx].targets` (referenced by an
    // `Adr ..., JumpTableIndex(idx)` operand) before block order / reachability
    // is recomputed, so the targets stay in `block_order` at their natural
    // layout position. This also fixes the O0 liveness of values live across a
    // back-edge through a jump-table block (defect #6), since liveness propagates
    // through `succs`.

    Ok(inst_map)
}

fn ensure_no_unresolved_vregs(ir_func: &IrMachFunction, phase: &str) -> Result<(), PipelineError> {
    let mut unresolved = Vec::new();

    // Encoding walks the laid-out block stream, not every arena slot or block
    // shell. After CFG cleanup and regalloc-side rebuilding, unreachable
    // blocks can remain in the block arena but be absent from `block_order`;
    // those are not encoded and should not block codegen.
    for &block_id in &ir_func.block_order {
        let block = ir_func.block(block_id);
        for &inst_id in &block.insts {
            let inst = ir_func.inst(inst_id);
            for (operand_idx, operand) in inst.operands.iter().enumerate() {
                if let IrOperand::VReg(vreg) = operand {
                    unresolved.push((inst_id, operand_idx, inst.opcode, *vreg));
                }
            }
        }
    }

    if unresolved.is_empty() {
        return Ok(());
    }

    let preview = unresolved
        .iter()
        .take(8)
        .map(|(inst_id, operand_idx, opcode, vreg)| {
            format!(
                "inst {} {opcode:?} operand {operand_idx} -> {vreg:?}",
                inst_id.0
            )
        })
        .collect::<Vec<_>>()
        .join(", ");
    let suffix = if unresolved.len() > 8 {
        format!("; {} more", unresolved.len() - 8)
    } else {
        String::new()
    };

    Err(PipelineError::RegAlloc(format!(
        "unresolved virtual register(s) after {phase}: {preview}{suffix}"
    )))
}

// ---------------------------------------------------------------------------
// Proof annotation propagation
// ---------------------------------------------------------------------------

/// Convert an adapter-layer [`Proof`](trust_cg_lower::Proof) to the IR-layer
/// [`ProofAnnotation`](trust_cg_ir::ProofAnnotation).
///
/// Some proof variants carry extra metadata that is not represented in the
/// simpler IR annotation enum. Only proof kinds with an exact machine carrier
/// are converted here.
fn proof_to_annotation(proof: &trust_cg_lower::Proof) -> Option<trust_cg_ir::ProofAnnotation> {
    match proof {
        trust_cg_lower::Proof::NoOverflow { signed: true } => {
            Some(trust_cg_ir::ProofAnnotation::NoSignedOverflow)
        }
        trust_cg_lower::Proof::NoOverflow { signed: false } => {
            Some(trust_cg_ir::ProofAnnotation::NoUnsignedOverflow)
        }
        // Synthetic carrier-only seed: maps to the SAME overflow annotation as a genuine on-op
        // `NoOverflow`, so the carrier binder (`apply_guard_proof_annotations`) can stamp the
        // `TrapOverflowExact` carrier. Its distinguishing behaviour (exclusion from the general
        // value-proof loop, closing the over-elimination leak) is enforced in `select_proof_annotation`
        // at the Proof level, BEFORE this conversion — see that function.
        trust_cg_lower::Proof::CarrierNoOverflow { signed: true } => {
            Some(trust_cg_ir::ProofAnnotation::NoSignedOverflow)
        }
        trust_cg_lower::Proof::CarrierNoOverflow { signed: false } => {
            Some(trust_cg_ir::ProofAnnotation::NoUnsignedOverflow)
        }
        trust_cg_lower::Proof::ExactInBounds { .. } => Some(trust_cg_ir::ProofAnnotation::InBounds),
        trust_cg_lower::Proof::InBounds { .. } => None,
        trust_cg_lower::Proof::NotNull { .. } => Some(trust_cg_ir::ProofAnnotation::NotNull),
        trust_cg_lower::Proof::ValidBorrow { .. } => {
            Some(trust_cg_ir::ProofAnnotation::ValidBorrow)
        }
        trust_cg_lower::Proof::NonZeroDivisor { .. } => {
            Some(trust_cg_ir::ProofAnnotation::NonZeroDivisor)
        }
        trust_cg_lower::Proof::ValidShift { .. } => Some(trust_cg_ir::ProofAnnotation::ValidShift),
        trust_cg_lower::Proof::Pure => Some(trust_cg_ir::ProofAnnotation::Pure),
        trust_cg_lower::Proof::Associative => Some(trust_cg_ir::ProofAnnotation::Associative),
        trust_cg_lower::Proof::Commutative => Some(trust_cg_ir::ProofAnnotation::Commutative),
        trust_cg_lower::Proof::Idempotent => Some(trust_cg_ir::ProofAnnotation::Idempotent),
        // InRange has no direct annotation counterpart — the range info
        // cannot be expressed in the single-variant ProofAnnotation. We
        // skip it here; range-based opts use the full ProofContext.
        trust_cg_lower::Proof::InRange { .. } => None,
        // A declared refinement is a fact about a VALUE, not a producer safety claim about an
        // instruction, and it is deliberately NOT representable as a `ProofAnnotation`: stamping
        // one would let a type-level fact masquerade as an eliminable proof label on whatever
        // instruction happened to define the value. Its only consumer is the lattice, which
        // re-decides it against the exact guard it might discharge — see
        // `install_lattice_guard_authority`.
        trust_cg_lower::Proof::Refinement { .. } => None,
    }
}

fn proof_annotation_priority(annotation: trust_cg_ir::ProofAnnotation, opcode: IrOpcode) -> u8 {
    use trust_cg_ir::ProofAnnotation as Proof;

    match annotation {
        Proof::NoOverflow | Proof::NoSignedOverflow | Proof::NoUnsignedOverflow => match opcode {
            IrOpcode::AddsRR | IrOpcode::AddsRI | IrOpcode::SubsRR | IrOpcode::SubsRI => 100,
            _ => 80,
        },
        Proof::InBounds => match opcode {
            IrOpcode::TrapBoundsCheckExact => 100,
            _ => 80,
        },
        Proof::NonZeroDivisor => match opcode {
            // Self-contained carrier (production) ranks highest; legacy CmpRI pair retained.
            IrOpcode::TrapDivZeroIfZero => 100,
            IrOpcode::CmpRI => 90,
            _ => 80,
        },
        Proof::ValidShift => match opcode {
            // Self-contained carrier (production) ranks highest; legacy CmpRI/bare-trap retained.
            IrOpcode::TrapShiftRangeIfOOB => 100,
            IrOpcode::CmpRI | IrOpcode::TrapShiftRange => 90,
            _ => 80,
        },
        Proof::NotNull => match opcode {
            IrOpcode::TrapNullIfZero => 100,
            _ => 80,
        },
        Proof::ValidBorrow | Proof::Pure | Proof::PositiveRefCount => 70,
        Proof::Associative | Proof::Commutative | Proof::Idempotent => 10,
    }
}

fn requires_guard_binding(annotation: trust_cg_ir::ProofAnnotation) -> bool {
    matches!(
        annotation,
        trust_cg_ir::ProofAnnotation::InBounds
            | trust_cg_ir::ProofAnnotation::NotNull
            | trust_cg_ir::ProofAnnotation::NonZeroDivisor
            | trust_cg_ir::ProofAnnotation::ValidShift
    )
}

/// True for the overflow proof annotations the self-contained `TrapOverflowExact` carrier consumes.
///
/// Unlike [`requires_guard_binding`], these are NOT excluded from the general value-proof loop
/// (`select_proof_annotation`): the legacy entangled overflow path still annotates the flag-setting
/// ADDS/SUBS via that loop, EXACTLY as before. They are bound to the DECOUPLED carrier IN ADDITION,
/// by [`apply_guard_proof_annotations`], so adding the carrier never regresses the legacy path. The
/// two are not mutually exclusive: a decoupled carrier function has no ADDS for the general loop to
/// match, and the legacy ADDS function has no `TrapOverflowExact` for the guard binder to match.
fn binds_to_overflow_carrier(annotation: trust_cg_ir::ProofAnnotation) -> bool {
    matches!(
        annotation,
        trust_cg_ir::ProofAnnotation::NoSignedOverflow
            | trust_cg_ir::ProofAnnotation::NoUnsignedOverflow
    )
}

/// True for the SYNTHETIC carrier-only overflow seed (`Proof::CarrierNoOverflow`).
///
/// This is the leak-closing discriminator. The genuine on-op [`trust_cg_lower::Proof::NoOverflow`]
/// (keyed to an arithmetic op's OWN result) is NOT carrier-only and stays eligible for the general
/// value-proof loop, preserving legacy ADDS/SUBS→ADD/SUB overflow elimination. The synthetic seed
/// (keyed to a carrier's OPERAND vregs by `translate_overflow`) IS carrier-only and is excluded from
/// the general loop, so it can never be stamped onto an operand's defining instruction and authorize
/// deleting an unrelated operation's overflow check. The two produce the SAME `ProofAnnotation`, so
/// they cannot be distinguished post-conversion — the filter MUST operate at the `Proof` level here.
fn is_carrier_only_proof(proof: &trust_cg_lower::Proof) -> bool {
    matches!(proof, trust_cg_lower::Proof::CarrierNoOverflow { .. })
}

fn select_proof_annotation(
    proofs: &[trust_cg_lower::Proof],
    opcode: IrOpcode,
) -> Option<trust_cg_ir::ProofAnnotation> {
    proofs
        .iter()
        // Carrier-only seeds are consumed exclusively by the operand-sensitive carrier binder
        // (`apply_guard_proof_annotations`); they MUST NOT reach a value's defining instruction here.
        .filter(|proof| !is_carrier_only_proof(proof))
        .filter_map(proof_to_annotation)
        .filter(|annotation| !requires_guard_binding(*annotation))
        .max_by_key(|annotation| proof_annotation_priority(*annotation, opcode))
}

fn value_map_vreg(
    value: &trust_cg_lower::instructions::Value,
    value_map: &std::collections::HashMap<
        trust_cg_lower::instructions::Value,
        trust_cg_lower::isel::ISelOperand,
    >,
) -> Option<VReg> {
    match value_map.get(value) {
        Some(trust_cg_lower::isel::ISelOperand::VReg(vreg)) => Some(*vreg),
        _ => None,
    }
}

fn operand_vreg(inst: &IrMachInst, idx: usize) -> Option<VReg> {
    match inst.operands.get(idx) {
        Some(IrOperand::VReg(vreg)) => Some(*vreg),
        _ => None,
    }
}

fn operand_imm(inst: &IrMachInst, idx: usize) -> Option<i64> {
    match inst.operands.get(idx) {
        Some(IrOperand::Imm(imm)) => Some(*imm),
        _ => None,
    }
}

fn next_opcode(
    ir_func: &IrMachFunction,
    block_insts: &[trust_cg_ir::types::InstId],
    pos: usize,
) -> Option<IrOpcode> {
    block_insts
        .get(pos + 1)
        .map(|next_id| ir_func.inst(*next_id).opcode)
}

fn bcond_has_condition(inst: &IrMachInst, condition: trust_cg_ir::CondCode) -> bool {
    inst.opcode == IrOpcode::BCond
        && matches!(
            inst.operands.first(),
            Some(IrOperand::Imm(cond)) if *cond == i64::from(condition.encoding())
        )
}

fn next_is_bcond_with_condition(
    ir_func: &IrMachFunction,
    block_insts: &[trust_cg_ir::types::InstId],
    pos: usize,
    condition: trust_cg_ir::CondCode,
) -> bool {
    block_insts
        .get(pos + 1)
        .is_some_and(|next_id| bcond_has_condition(ir_func.inst(*next_id), condition))
}

fn proof_matches_guard_shape(
    ir_func: &IrMachFunction,
    block_insts: &[trust_cg_ir::types::InstId],
    pos: usize,
    vreg: VReg,
    proof: &trust_cg_lower::Proof,
    value_map: &std::collections::HashMap<
        trust_cg_lower::instructions::Value,
        trust_cg_lower::isel::ISelOperand,
    >,
) -> Option<trust_cg_ir::ProofAnnotation> {
    let inst = ir_func.inst(block_insts[pos]);
    match proof {
        trust_cg_lower::Proof::ExactInBounds { base, index, bound } => {
            let base_vreg = value_map_vreg(base, value_map)?;
            let index_vreg = value_map_vreg(index, value_map)?;
            if inst.opcode == IrOpcode::TrapBoundsCheckExact
                && operand_vreg(inst, 0) == Some(base_vreg)
                && operand_vreg(inst, 1) == Some(index_vreg)
                && operand_imm(inst, 2) == Some(*bound as i64)
            {
                Some(trust_cg_ir::ProofAnnotation::InBounds)
            } else {
                None
            }
        }
        trust_cg_lower::Proof::InBounds { .. } => None,
        trust_cg_lower::Proof::NotNull { .. } => match inst.opcode {
            IrOpcode::TrapNullIfZero if operand_vreg(inst, 0) == Some(vreg) => {
                Some(trust_cg_ir::ProofAnnotation::NotNull)
            }
            _ => None,
        },
        trust_cg_lower::Proof::NoOverflow { signed } => {
            // Production carrier: self-contained `TrapOverflowExact lhs, rhs, Imm(op_tag)`. The proof
            // binds only when (a) the carrier references the proven vreg as lhs OR rhs, AND (b) the
            // carrier's op-tag SIGNEDNESS matches the proof's `signed` flag. This signedness check is
            // soundness-critical: a signed-overflow proof must NEVER annotate an unsigned-overflow
            // carrier (and vice versa), since their overflow conditions differ. The legacy entangled
            // ADDS/SUBS path is NOT matched here — it flows through the unchanged value-proof
            // propagation onto the flag-setting ADDS/SUBS, exactly as before.
            if inst.opcode != IrOpcode::TrapOverflowExact {
                return None;
            }
            if operand_vreg(inst, 0) != Some(vreg) && operand_vreg(inst, 1) != Some(vreg) {
                return None;
            }
            let tag = operand_imm(inst, 2)?;
            let (op, _width) = trust_cg_ir::unpack_overflow_tag(tag)?;
            let op_is_signed = matches!(
                op,
                trust_cg_ir::OverflowOp::SignedAdd
                    | trust_cg_ir::OverflowOp::SignedSub
                    | trust_cg_ir::OverflowOp::SignedMul
            );
            if op_is_signed != *signed {
                return None;
            }
            Some(if *signed {
                trust_cg_ir::ProofAnnotation::NoSignedOverflow
            } else {
                trust_cg_ir::ProofAnnotation::NoUnsignedOverflow
            })
        }
        trust_cg_lower::Proof::CarrierNoOverflow { signed } => {
            // Synthetic carrier-only seed from the `Inst::Overflow` auto-rewrite. Binds EXACTLY like
            // the genuine `NoOverflow` arm above — operand-sensitive, signedness-checked — but is
            // sourced ONLY by `translate_overflow` seeding the carrier's operand vregs, and (unlike
            // `NoOverflow`) is excluded from the general value-proof loop by `select_proof_annotation`
            // so it can never leak onto an operand's defining ADDS/SUBS. The signedness check is
            // soundness-critical: a signed seed must NEVER annotate an unsigned carrier or vice versa.
            if inst.opcode != IrOpcode::TrapOverflowExact {
                return None;
            }
            if operand_vreg(inst, 0) != Some(vreg) && operand_vreg(inst, 1) != Some(vreg) {
                return None;
            }
            let tag = operand_imm(inst, 2)?;
            let (op, _width) = trust_cg_ir::unpack_overflow_tag(tag)?;
            let op_is_signed = matches!(
                op,
                trust_cg_ir::OverflowOp::SignedAdd
                    | trust_cg_ir::OverflowOp::SignedSub
                    | trust_cg_ir::OverflowOp::SignedMul
            );
            if op_is_signed != *signed {
                return None;
            }
            Some(if *signed {
                trust_cg_ir::ProofAnnotation::NoSignedOverflow
            } else {
                trust_cg_ir::ProofAnnotation::NoUnsignedOverflow
            })
        }
        trust_cg_lower::Proof::NonZeroDivisor { .. } => match inst.opcode {
            // Production carrier: self-contained `TrapDivZeroIfZero divisor` (the DivZero mirror of
            // the NotNull `TrapNullIfZero ptr` arm above). The proven-nonzero divisor IS the carrier's
            // operand 0, so the binding is operand-sensitive — never inferred from nearby shape.
            IrOpcode::TrapDivZeroIfZero if operand_vreg(inst, 0) == Some(vreg) => {
                Some(trust_cg_ir::ProofAnnotation::NonZeroDivisor)
            }
            // Legacy CmpRI+TrapDivZero pair (no longer emitted by the production ISel; retained).
            IrOpcode::CmpRI
                if operand_vreg(inst, 0) == Some(vreg)
                    && operand_imm(inst, 1) == Some(0)
                    && next_opcode(ir_func, block_insts, pos) == Some(IrOpcode::TrapDivZero) =>
            {
                Some(trust_cg_ir::ProofAnnotation::NonZeroDivisor)
            }
            _ => None,
        },
        trust_cg_lower::Proof::ValidShift { bitwidth, .. } => {
            let bitwidth = i64::from(*bitwidth);
            match inst.opcode {
                // Production carrier: self-contained `TrapShiftRangeIfOOB amount, Imm(bitwidth)` (the
                // ShiftRange mirror of the InBounds `TrapBoundsCheckExact` arm). The proven-in-range
                // amount IS operand 0 and the width IS operand 1 — operand-sensitive, never inferred.
                IrOpcode::TrapShiftRangeIfOOB
                    if operand_vreg(inst, 0) == Some(vreg)
                        && operand_imm(inst, 1) == Some(bitwidth) =>
                {
                    Some(trust_cg_ir::ProofAnnotation::ValidShift)
                }
                // Legacy CmpRI + (TrapShiftRange | B.HS) pair (no longer emitted; retained).
                IrOpcode::CmpRI
                    if operand_vreg(inst, 0) == Some(vreg)
                        && operand_imm(inst, 1) == Some(bitwidth)
                        && (next_opcode(ir_func, block_insts, pos)
                            == Some(IrOpcode::TrapShiftRange)
                            || next_is_bcond_with_condition(
                                ir_func,
                                block_insts,
                                pos,
                                trust_cg_ir::CondCode::HS,
                            )) =>
                {
                    Some(trust_cg_ir::ProofAnnotation::ValidShift)
                }
                _ => None,
            }
        }
        _ => None,
    }
}

fn apply_guard_proof_annotations(
    ir_func: &mut IrMachFunction,
    proof_ctx: &trust_cg_lower::ProofContext,
    value_map: &std::collections::HashMap<
        trust_cg_lower::instructions::Value,
        trust_cg_lower::isel::ISelOperand,
    >,
) {
    let mut bindings = Vec::new();
    for (value, proofs) in &proof_ctx.value_proofs {
        let Some(vreg) = value_map_vreg(value, value_map) else {
            continue;
        };
        for proof in proofs {
            // Guard-bound safety facts (bounds/null/div/shift) AND the overflow carrier proofs both
            // bind to operand-sensitive carriers here. A genuine on-op `NoOverflow` remains ALSO
            // eligible for the general value-proof loop (the legacy ADDS/SUBS path stays intact); the
            // SYNTHETIC `CarrierNoOverflow` seed is consumed ONLY here (it is excluded from the general
            // loop by `select_proof_annotation`), which is what closes the over-elimination leak.
            // Both map to `NoSignedOverflow`/`NoUnsignedOverflow`, so `binds_to_overflow_carrier`
            // admits each into the carrier binder.
            if proof_to_annotation(proof)
                .is_some_and(|a| requires_guard_binding(a) || binds_to_overflow_carrier(a))
            {
                bindings.push((value.0, vreg, proof.clone()));
            }
        }
    }
    bindings.sort_by_key(|(value, vreg, proof)| {
        let annotation_rank = match proof_to_annotation(proof) {
            Some(trust_cg_ir::ProofAnnotation::InBounds) => 0,
            Some(trust_cg_ir::ProofAnnotation::NotNull) => 1,
            Some(trust_cg_ir::ProofAnnotation::NonZeroDivisor) => 2,
            Some(trust_cg_ir::ProofAnnotation::ValidShift) => 3,
            _ => 4,
        };
        (*value, vreg.id, annotation_rank)
    });

    let block_insts: Vec<Vec<_>> = ir_func
        .blocks
        .iter()
        .map(|block| block.insts.clone())
        .collect();
    let mut annotations = Vec::new();
    for (_, vreg, proof) in bindings {
        for insts in &block_insts {
            for pos in 0..insts.len() {
                if let Some(annotation) =
                    proof_matches_guard_shape(ir_func, insts, pos, vreg, &proof, value_map)
                {
                    annotations.push((insts[pos], annotation));
                }
            }
        }
    }

    annotations.sort_by_key(|(inst_id, annotation)| {
        let annotation_rank = match annotation {
            trust_cg_ir::ProofAnnotation::InBounds => 0,
            trust_cg_ir::ProofAnnotation::NotNull => 1,
            trust_cg_ir::ProofAnnotation::NonZeroDivisor => 2,
            trust_cg_ir::ProofAnnotation::ValidShift => 3,
            _ => 4,
        };
        (inst_id.0, annotation_rank)
    });
    annotations.dedup();

    for (inst_id, annotation) in annotations {
        let inst = ir_func.inst_mut(inst_id);
        if inst.proof.is_none() {
            inst.proof = Some(annotation);
        }
    }
}

/// Whether the fail-closed guard policy is enforced.
///
/// This is deliberately unconditional.  `TRUST_CG_GUARD_KERNEL_GATE` used to select between the
/// kernel and a weaker label-only path; either spelling could therefore become a policy bypass.  The
/// production optimizer now always installs an empty-authority kernel gate until exact validator
/// replay is wired, so every carrier is kept and expanded to a runtime check.
pub(crate) fn guard_kernel_gate_enabled() -> bool {
    true
}

enum AArch64KernelGate {
    Empty,
    Lattice(trust_cg_lower::lattice_guard::LatticeGuardReplayAuthority),
}

/// Build the production AArch64 guard gate.
///
/// Producer-owned status, lineage, `ProofRef` labels and synthesized ids remain report metadata:
/// they contribute NOTHING here. Predicate implication alone cannot prove that a value satisfies
/// its declaration. The lattice authority requires a replayed RefinementType premise; until a
/// rechecker exists its public constructor returns an unavailable authority on every build.
///
/// Returning `Some` is load-bearing: `None` would select the legacy label-only optimizer.
fn build_guard_kernel_gate(
    ir_func: &mut IrMachFunction,
    isel_func: &trust_cg_lower::isel::ISelFunction,
    proof_ctx: Option<&trust_cg_lower::ProofContext>,
    _trust_ir_module: Option<&trust_ir::Module>,
) -> Option<AArch64KernelGate> {
    let Some(ctx) = proof_ctx else {
        return Some(AArch64KernelGate::Empty);
    };

    let authority =
        trust_cg_lower::lattice_guard::LatticeGuardReplayAuthority::replay_and_bind_aarch64(
            ir_func,
            isel_func.lattice_guard_bindings(),
            &ctx.refinement_env,
            &ctx.lattice_bounds_capabilities,
        );
    if !authority.is_enabled() {
        return Some(AArch64KernelGate::Empty);
    }

    // Stamp the dispatch annotation on exactly the replay-bound carriers. The opaque authority
    // still has to authorize and independently re-check each deletion in the proof pass.
    let bound: Vec<InstId> = authority.bound_inst_ids().collect();
    for inst_id in bound {
        let inst = ir_func.inst_mut(inst_id);
        if inst.proof.is_none() {
            inst.proof = Some(trust_cg_ir::ProofAnnotation::InBounds);
        }
    }
    Some(AArch64KernelGate::Lattice(authority))
}

/// Propagate proof annotations from the adapter's [`ProofContext`](trust_cg_lower::ProofContext)
/// onto machine instructions in the IR function.
///
/// Uses the ISel value map to resolve LIR Values to VRegs, then builds a
/// reverse map (VReg ID -> InstId) to locate the defining instruction for
/// each value and annotate it with the appropriate [`ProofAnnotation`].
///
/// Function-level proofs (Pure, Associative, etc.) are stored on the
/// [`MachFunction::function_proofs`] field.
fn apply_proof_annotations(
    ir_func: &mut IrMachFunction,
    proof_ctx: &trust_cg_lower::ProofContext,
    value_map: &std::collections::HashMap<
        trust_cg_lower::instructions::Value,
        trust_cg_lower::isel::ISelOperand,
    >,
) {
    // Build reverse map: VReg -> unique defining InstId. Use the shared
    // def/use classifier so first-operand uses such as CMP/STR/branches are
    // never mistaken for definitions. If a VReg has multiple defs, mark it
    // ambiguous and skip proof binding rather than guessing.
    let vreg_to_inst = vreg_defining_insts(ir_func);

    // The production caller invokes this helper only after acquiring exact replay authority.  Unit
    // tests call it directly to exercise the structural binding model.
    apply_guard_proof_annotations(ir_func, proof_ctx, value_map);

    // Propagate remaining per-value proofs onto defining instructions.
    for (value, proofs) in &proof_ctx.value_proofs {
        if let Some(vreg) = value_map_vreg(value, value_map)
            && let Some(Some(inst_id)) = vreg_to_inst.get(&vreg).copied()
        {
            let opcode = ir_func.inst(inst_id).opcode;
            if let Some(annotation) = select_proof_annotation(proofs, opcode) {
                let inst = ir_func.inst_mut(inst_id);
                // Only set if no annotation is already present (ISel may
                // have set one, and we do not want to overwrite).
                if inst.proof.is_none() {
                    inst.proof = Some(annotation);
                }
            }
        }
    }

    // Propagate function-level proofs onto MachFunction metadata.
    for proof in proof_ctx.function_proofs() {
        if let Some(annotation) = proof_to_annotation(proof) {
            ir_func.function_proofs.push(annotation);
        }
    }

    // Thread `noalias` pointer-parameter attributes onto the MachFunction so the
    // `neon-map` store vectorizer can prove store/load non-aliasing. The ISel
    // binds formal parameter `i` to `Value(i)`; resolve each noalias param index
    // through the value map to its machine vreg. Under-resolution is safe (the
    // pass BAILS); only proven-noalias params ever reach this list.
    for &param_index in &proof_ctx.noalias_param_indices {
        let value = trust_cg_lower::instructions::Value(param_index as u32);
        if let Some(vreg) = value_map_vreg(&value, value_map)
            && !ir_func.noalias_params.contains(&vreg.id)
        {
            ir_func.noalias_params.push(vreg.id);
        }
    }
}

fn vreg_defining_insts(
    ir_func: &IrMachFunction,
) -> std::collections::HashMap<VReg, Option<InstId>> {
    let mut vreg_to_inst: std::collections::HashMap<VReg, Option<InstId>> =
        std::collections::HashMap::new();
    for (idx, inst) in ir_func.insts.iter().enumerate() {
        let (def_positions, _) = classify_operand_positions(inst);
        for pos in def_positions {
            if let Some(IrOperand::VReg(vreg)) = inst.operands.get(pos) {
                vreg_to_inst
                    .entry(*vreg)
                    .and_modify(|slot| *slot = None)
                    .or_insert(Some(InstId(idx as u32)));
            }
        }
    }
    vreg_to_inst
}

fn proof_optimization_metadata_from_context(
    ir_func: &IrMachFunction,
    proof_ctx: &trust_cg_lower::ProofContext,
    value_map: &std::collections::HashMap<
        trust_cg_lower::instructions::Value,
        trust_cg_lower::isel::ISelOperand,
    >,
) -> trust_cg_opt::proof_opts::ProofOptimizationMetadata {
    let mut metadata = trust_cg_opt::proof_opts::ProofOptimizationMetadata::new();
    for (inst_id, facts) in
        proof_optimization_facts_by_inst_from_context(ir_func, proof_ctx, value_map)
    {
        metadata.set_inst_proof_facts(inst_id, facts);
    }

    metadata
}

fn proof_optimization_metadata_from_isel_facts(
    isel_func: &trust_cg_lower::isel::ISelFunction,
) -> trust_cg_opt::proof_opts::ProofOptimizationMetadata {
    let mut metadata = trust_cg_opt::proof_opts::ProofOptimizationMetadata::new();
    let mut next_inst_id = 0_u32;

    for block_ref in &isel_func.block_order {
        let Some(block) = isel_func.blocks.get(block_ref) else {
            continue;
        };
        for idx in 0..block.insts.len() {
            if let Some(facts) = block.proof_facts.get(idx)
                && !facts.is_empty()
            {
                metadata.set_inst_proof_facts(InstId(next_inst_id), facts.clone());
            }
            next_inst_id += 1;
        }
    }

    metadata
}

fn merge_proof_optimization_metadata(
    base: &mut trust_cg_opt::proof_opts::ProofOptimizationMetadata,
    extra: trust_cg_opt::proof_opts::ProofOptimizationMetadata,
) {
    for (inst_id, facts) in extra.proof_facts() {
        let mut merged = base.inst_proof_facts(*inst_id).to_vec();
        for fact in facts {
            if !merged.contains(fact) {
                merged.push(*fact);
            }
        }
        base.set_inst_proof_facts(*inst_id, merged);
    }
}

fn proof_optimization_facts_by_inst_from_context(
    ir_func: &IrMachFunction,
    proof_ctx: &trust_cg_lower::ProofContext,
    value_map: &std::collections::HashMap<
        trust_cg_lower::instructions::Value,
        trust_cg_lower::isel::ISelOperand,
    >,
) -> BTreeMap<InstId, Vec<trust_cg_ir::ProofFact>> {
    let vreg_to_inst = vreg_defining_insts(ir_func);
    let mut facts_by_inst: BTreeMap<InstId, Vec<trust_cg_ir::ProofFact>> = BTreeMap::new();
    let mut sorted_facts_by_inst: BTreeMap<InstId, Vec<trust_cg_ir::ProofFact>> = BTreeMap::new();
    let function_vectorization_facts: Vec<_> = proof_ctx
        .function_facts()
        .iter()
        .copied()
        .map(trust_cg_ir::ProofFact::from)
        .filter(is_vectorization_function_proof_fact)
        .collect();
    if !function_vectorization_facts.is_empty() {
        for idx in 0..ir_func.insts.len() {
            facts_by_inst
                .entry(InstId(idx as u32))
                .or_default()
                .extend(function_vectorization_facts.iter().copied());
        }
    }

    for (value, facts) in &proof_ctx.value_facts {
        let Some(vreg) = value_map_vreg(value, value_map) else {
            continue;
        };
        let ir_facts: Vec<trust_cg_ir::ProofFact> = facts
            .iter()
            .copied()
            .map(trust_cg_ir::ProofFact::from)
            .collect();
        if ir_facts.is_empty() {
            continue;
        }
        let aligned_facts: Vec<trust_cg_ir::ProofFact> = ir_facts
            .iter()
            .copied()
            .filter(|fact| matches!(fact, trust_cg_ir::ProofFact::Aligned(_)))
            .collect();
        let vectorization_facts: Vec<trust_cg_ir::ProofFact> = ir_facts
            .iter()
            .copied()
            .filter(is_vectorization_operand_proof_fact)
            .collect();

        let mut inst_ids = BTreeSet::new();
        if let Some(Some(inst_id)) = vreg_to_inst.get(&vreg).copied() {
            inst_ids.insert(inst_id);
        }

        for (idx, inst) in ir_func.insts.iter().enumerate() {
            let inst_id = InstId(idx as u32);
            if inst.proof.is_none() {
                if inst.operands.iter().any(
                    |operand| matches!(operand, IrOperand::VReg(operand_vreg) if *operand_vreg == vreg),
                ) && !vectorization_facts.is_empty()
                {
                    facts_by_inst
                        .entry(inst_id)
                        .or_default()
                        .extend(vectorization_facts.iter().copied());
                }
                let memory_aligned_facts = aligned_pair_memory_facts_for_base(
                    ir_func,
                    &vreg_to_inst,
                    inst,
                    vreg,
                    &aligned_facts,
                );
                if !memory_aligned_facts.is_empty() {
                    facts_by_inst
                        .entry(inst_id)
                        .or_default()
                        .extend(memory_aligned_facts);
                }
                continue;
            }
            if inst.operands.iter().any(
                |operand| matches!(operand, IrOperand::VReg(operand_vreg) if *operand_vreg == vreg),
            ) {
                inst_ids.insert(inst_id);
            }
            let memory_aligned_facts = aligned_pair_memory_facts_for_base(
                ir_func,
                &vreg_to_inst,
                inst,
                vreg,
                &aligned_facts,
            );
            if !memory_aligned_facts.is_empty() {
                facts_by_inst
                    .entry(inst_id)
                    .or_default()
                    .extend(memory_aligned_facts);
            }
        }

        for inst_id in inst_ids {
            facts_by_inst
                .entry(inst_id)
                .or_default()
                .extend(ir_facts.iter().copied());
        }
    }

    for (inst_id, mut facts) in facts_by_inst {
        facts.sort_by_key(|fact| {
            (
                fact.stable_name(),
                match fact {
                    trust_cg_ir::ProofFact::Aligned(bytes) => Some(*bytes),
                    trust_cg_ir::ProofFact::BoundedLoop(bound) => Some(*bound),
                    _ => None,
                },
                match fact {
                    trust_cg_ir::ProofFact::DivergenceClass(divergence) => Some(match divergence {
                        trust_cg_ir::ProofDivergence::Uniform => 0_u8,
                        trust_cg_ir::ProofDivergence::Low => 1,
                        trust_cg_ir::ProofDivergence::High => 2,
                    }),
                    _ => None,
                },
            )
        });
        facts.dedup();
        sorted_facts_by_inst.insert(inst_id, facts);
    }

    sorted_facts_by_inst
}

fn is_vectorization_function_proof_fact(fact: &trust_cg_ir::ProofFact) -> bool {
    matches!(
        fact,
        trust_cg_ir::ProofFact::BoundedLoop(_)
            | trust_cg_ir::ProofFact::Monotonic
            | trust_cg_ir::ProofFact::ParallelMap
    )
}

fn is_vectorization_operand_proof_fact(fact: &trust_cg_ir::ProofFact) -> bool {
    matches!(
        fact,
        trust_cg_ir::ProofFact::InBounds
            | trust_cg_ir::ProofFact::NoAlias
            | trust_cg_ir::ProofFact::BoundedLoop(_)
            | trust_cg_ir::ProofFact::Monotonic
            | trust_cg_ir::ProofFact::ParallelMap
    )
}

fn aligned_pair_memory_facts_for_base(
    ir_func: &IrMachFunction,
    vreg_to_inst: &std::collections::HashMap<VReg, Option<InstId>>,
    inst: &IrMachInst,
    vreg: VReg,
    aligned_facts: &[trust_cg_ir::ProofFact],
) -> Vec<trust_cg_ir::ProofFact> {
    let Some((base, offset)) = aligned_pair_scalar_base_vreg_and_offset(inst) else {
        return Vec::new();
    };
    let total_offset = if base == vreg {
        offset
    } else {
        let Some((add_base, add_offset)) =
            unique_gpr64_offset_base_and_offset(ir_func, vreg_to_inst, base)
        else {
            return Vec::new();
        };
        if add_base != vreg {
            return Vec::new();
        }
        let Some(total_offset) = add_offset.checked_add(offset) else {
            return Vec::new();
        };
        total_offset
    };

    aligned_facts
        .iter()
        .filter_map(|fact| match fact {
            trust_cg_ir::ProofFact::Aligned(bytes) if *bytes > 0 => {
                let derived = if total_offset == 0 {
                    *bytes
                } else {
                    gcd_u64(*bytes, total_offset.unsigned_abs())
                };
                (derived >= 16).then_some(trust_cg_ir::ProofFact::Aligned(derived))
            }
            _ => None,
        })
        .collect()
}

fn unique_gpr64_offset_base_and_offset(
    ir_func: &IrMachFunction,
    vreg_to_inst: &std::collections::HashMap<VReg, Option<InstId>>,
    temp: VReg,
) -> Option<(VReg, i64)> {
    unique_gpr64_addri_base_and_offset(ir_func, vreg_to_inst, temp)
        .or_else(|| unique_gpr64_madd_const_offset_base_and_offset(ir_func, vreg_to_inst, temp))
}

fn gcd_u64(mut lhs: u64, mut rhs: u64) -> u64 {
    while rhs != 0 {
        let next = lhs % rhs;
        lhs = rhs;
        rhs = next;
    }
    lhs
}

fn aligned_pair_scalar_base_vreg_and_offset(inst: &IrMachInst) -> Option<(VReg, i64)> {
    if !matches!(inst.opcode, IrOpcode::LdrRI | IrOpcode::StrRI) {
        return None;
    }
    let offset = match inst.operands.get(2) {
        Some(IrOperand::Imm(offset)) => *offset,
        None => 0,
        _ => return None,
    };
    match inst.operands.get(1) {
        Some(IrOperand::VReg(vreg)) if vreg.class == RegClass::Gpr64 => Some((*vreg, offset)),
        _ => None,
    }
}

fn unique_gpr64_addri_base_and_offset(
    ir_func: &IrMachFunction,
    vreg_to_inst: &std::collections::HashMap<VReg, Option<InstId>>,
    temp: VReg,
) -> Option<(VReg, i64)> {
    if temp.class != RegClass::Gpr64 {
        return None;
    }
    let Some(Some(def_id)) = vreg_to_inst.get(&temp).copied() else {
        return None;
    };
    let add = ir_func.insts.get(def_id.0 as usize)?;
    if add.opcode != IrOpcode::AddRI {
        return None;
    }

    match (
        add.operands.first(),
        add.operands.get(1),
        add.operands.get(2),
    ) {
        (Some(IrOperand::VReg(dst)), Some(IrOperand::VReg(base)), Some(IrOperand::Imm(offset)))
            if *dst == temp && dst.class == RegClass::Gpr64 && base.class == RegClass::Gpr64 =>
        {
            Some((*base, *offset))
        }
        _ => None,
    }
}

fn unique_gpr64_madd_const_offset_base_and_offset(
    ir_func: &IrMachFunction,
    vreg_to_inst: &std::collections::HashMap<VReg, Option<InstId>>,
    temp: VReg,
) -> Option<(VReg, i64)> {
    if temp.class != RegClass::Gpr64 {
        return None;
    }
    let Some(Some(def_id)) = vreg_to_inst.get(&temp).copied() else {
        return None;
    };
    let madd = ir_func.insts.get(def_id.0 as usize)?;
    if madd.opcode != IrOpcode::Madd {
        return None;
    }

    let (
        Some(IrOperand::VReg(dst)),
        Some(IrOperand::VReg(lhs)),
        Some(IrOperand::VReg(rhs)),
        Some(IrOperand::VReg(base)),
    ) = (
        madd.operands.first(),
        madd.operands.get(1),
        madd.operands.get(2),
        madd.operands.get(3),
    )
    else {
        return None;
    };
    if *dst != temp
        || dst.class != RegClass::Gpr64
        || lhs.class != RegClass::Gpr64
        || rhs.class != RegClass::Gpr64
        || base.class != RegClass::Gpr64
    {
        return None;
    }

    let lhs = unique_gpr64_movz_imm(ir_func, vreg_to_inst, *lhs)?;
    let rhs = unique_gpr64_movz_imm(ir_func, vreg_to_inst, *rhs)?;
    let offset = lhs.checked_mul(rhs)?;
    Some((*base, offset))
}

fn unique_gpr64_movz_imm(
    ir_func: &IrMachFunction,
    vreg_to_inst: &std::collections::HashMap<VReg, Option<InstId>>,
    temp: VReg,
) -> Option<i64> {
    if temp.class != RegClass::Gpr64 {
        return None;
    }
    let Some(Some(def_id)) = vreg_to_inst.get(&temp).copied() else {
        return None;
    };
    let movz = ir_func.insts.get(def_id.0 as usize)?;
    if movz.opcode != IrOpcode::Movz {
        return None;
    }

    let (dst, imm) = match movz.operands.as_slice() {
        [IrOperand::VReg(dst), IrOperand::Imm(imm)] => Some((dst, imm)),
        [IrOperand::VReg(dst), IrOperand::Imm(imm), IrOperand::Imm(0)] => Some((dst, imm)),
        _ => None,
    }?;
    (*dst == temp && dst.class == RegClass::Gpr64 && (0..=0xffff).contains(imm)).then_some(*imm)
}

// ---------------------------------------------------------------------------
// Copy lowering: pseudo Copy -> real MOVWrr/MOVXrr / FmovFprFpr
// ---------------------------------------------------------------------------

/// Retire an already-erased pure virtual copy without executable arena state.
/// Physical identities retain their established ABI/liveness marker path.
/// Stable lowering provenance is history, not a tombstone's proof credit.
fn retire_erased_copy(
    inst: &mut IrMachInst,
    function: &str,
    index: usize,
    next_vreg: u32,
) -> Result<(), PipelineError> {
    use trust_cg_ir::InstFlags;
    let class = |operand: &IrOperand| match operand {
        IrOperand::VReg(reg)
            if reg.id < next_vreg
                && matches!(
                    reg.class,
                    RegClass::Gpr32
                        | RegClass::Gpr64
                        | RegClass::Fpr16
                        | RegClass::Fpr32
                        | RegClass::Fpr64
                        | RegClass::Fpr128
                ) =>
        {
            Some(reg.class)
        }
        // SP/WSP cannot use the ORR move alias, and Fpr8/System have no
        // encodable Copy lowering. XZR/WZR retain their existing PReg form.
        IrOperand::PReg(reg) if matches!(reg.encoding(), 0..=30 | 32..=62 | 64..=161 | 165..=196) => {
            Some(preg_class(*reg))
        }
        _ => None,
    };
    let registers = match inst.operands.as_slice() {
        [dst @ IrOperand::VReg(_), src] => match (class(dst), class(src)) {
            (Some(dst_class), Some(src_class)) => {
                dst_class == src_class
                    // Copy selects its GPR width from the destination. Either
                    // valid GPR source alias is pure and unobservable when
                    // this destination is dead; retirement grants no credit.
                    // FP widths and cross-bank copies remain exact.
                    || (matches!(dst_class, RegClass::Gpr32 | RegClass::Gpr64)
                        && matches!(src_class, RegClass::Gpr32 | RegClass::Gpr64))
            }
            _ => false,
        },
        _ => false,
    };
    if inst.opcode != IrOpcode::Copy
        || !registers
        || !inst.implicit_defs.is_empty()
        || !inst.implicit_uses.is_empty()
        || !matches!(inst.flags, InstFlags::EMPTY | InstFlags::IS_PSEUDO)
    {
        return Err(PipelineError::Encoding(format!(
            "cannot erase noncanonical or effectful Copy in `{function}` (fail-closed): \
             arena_inst={index}, next_vreg={next_vreg}, operands={:?}, flags={:#06x}, \
             implicit_defs={:?}, implicit_uses={:?}, proof={:?}, source_loc={:?}",
            inst.operands,
            inst.flags.bits(),
            inst.implicit_defs,
            inst.implicit_uses,
            inst.proof,
            inst.source_loc,
        )));
    }
    *inst = IrMachInst::new(IrOpcode::Nop, Vec::new());
    Ok(())
}

#[cfg(test)]
#[path = "pipeline_copy_retirement_tests.rs"]
mod copy_retirement_tests;

/// Lower all pseudo `Copy` instructions to real move instructions.
///
/// After register allocation, the allocator inserts `Copy` pseudo-instructions
/// to move data between physical registers. These must be lowered to real
/// instructions before encoding, since the encoder skips pseudo-instructions.
///
/// **GPR copies** become `MOVWrr`/`MOVXrr`
/// (encoded as `ORR Wd, WZR, Wm` / `ORR Xd, XZR, Xm`).
/// **FPR copies** (scalar H/S/D *and* 128-bit Q/V) become `NeonOrrV dst, src,
/// src` (encoded as `ORR Vd.16B, Vn.16B, Vn.16B`, the architectural
/// `MOV Vd.16B, Vn.16B` full-width vector-copy alias).
///
/// Lowering scalar FP copies as the `.16B` ORR alias (rather than the FP-pipe
/// `FMOV Dd, Dn`) is a deliberate performance choice: on Apple M-series the
/// full-width ORR vector-move alias is rename-eliminated (zero latency), while
/// scalar `FMOV` occupies the FP pipe (~2 cycles) and chains regalloc phi-cycle
/// copies into loop-carried critical paths — the form clang emits for exactly
/// this reason. Scalar copies pass a trailing `Imm(1)` arrangement selector so
/// the encoder derives `Q=1` (`.16B`); without it the scalar dest class would
/// imply the `.8B` form, which is NOT move-eliminated. `Fpr128` copies keep the
/// 3-operand form (their dest class already implies `Q=1`).
///
/// `ORR Vd.16B, Vn.16B, Vn.16B` copies all 128 bits, so the source's
/// architecturally-undefined upper 64 bits are written into the dest's upper 64.
/// This is sound because only the low `<=64` bits are defined for the
/// `Fpr16/Fpr32/Fpr64` classes (every D-register vector — `<8 x i8>`,
/// `<4 x i16>`, `<2 x i32>` — lives in the low 64 bits) and nothing in the
/// backend reads a scalar FPR's upper 64 bits: a 128-bit read requires an
/// `Fpr128` vreg, which the allocator only satisfies from a full-width def. It
/// is also bit-preserving, so signalling-NaN payloads survive a copy chain.
///
/// Using the wrong move type is a correctness bug: `ORR Xd, XZR, Xm` operates
/// on GPR registers only and does NOT touch the FP register file.
///
/// Copies where source == destination are eliminated entirely (converted to Nop).
///
/// Fail-closed: a copy whose destination class has no encodable move form
/// (Fpr8, System) is a hard compile error. Leaving it as a pseudo would make
/// the encoder silently SKIP it (pseudos are not encoded) and converting it
/// blindly to a GPR `MovR` was exactly the FP loop-carried P0 miscompile.
pub fn lower_copies(ir_func: &mut IrMachFunction) -> Result<(), PipelineError> {
    let use_counts = reachable_vreg_use_counts(ir_func);

    for idx in 0..ir_func.insts.len() {
        if ir_func.insts[idx].opcode == IrOpcode::Copy && ir_func.insts[idx].operands.len() >= 2 {
            if let IrOperand::VReg(dst) = ir_func.insts[idx].operands[0] {
                if use_counts.get(&dst).copied().unwrap_or(0) == 0 {
                    let inst = &mut ir_func.insts[idx];
                    retire_erased_copy(inst, &ir_func.name, idx, ir_func.next_vreg)?;
                }
                // A live unresolved-VReg destination is caught right after
                // this pass by `ensure_no_unresolved_vregs` (fail-closed).
                continue;
            }

            let inst = &mut ir_func.insts[idx];
            #[cfg(debug_assertions)]
            if std::env::var("TRUST_CG_DEBUG_REGALLOC").is_ok()
                && !matches!(
                    (&inst.operands[0], &inst.operands[1]),
                    (IrOperand::PReg(_), IrOperand::PReg(_))
                )
            {
                eprintln!(
                    "  lower_copies saw non-preg copy operands: {:?}",
                    inst.operands
                );
            }

            // Copy operands: [dst, src]
            // Check if src == dst (redundant copy).
            let is_redundant = match (&inst.operands[0], &inst.operands[1]) {
                (IrOperand::PReg(a), IrOperand::PReg(b)) => a == b,
                _ => false,
            };
            if is_redundant {
                // Preserve the historical physical-identity marker, including
                // formal live-ins, hidden-X8 and call-argument ABI metadata.
                // It is not a canonical virtual-copy retirement or new credit.
                inst.opcode = IrOpcode::Nop;
            } else {
                inst.opcode = match &inst.operands[0] {
                    IrOperand::PReg(preg) => match preg_class(*preg) {
                        RegClass::Gpr32 => IrOpcode::MOVWrr,
                        RegClass::Gpr64 => IrOpcode::MOVXrr,
                        // Scalar FPR (H/S/D) and 128-bit (Q/V) copies both lower
                        // to the rename-eliminated `ORR Vd.16B, Vn.16B, Vn.16B`
                        // vector-move alias (`MOV Vd.16B, Vn.16B`), which Apple
                        // M-series executes at zero latency (a register rename),
                        // unlike the FP-pipe `FMOV Dd, Dn`. ORR needs the source
                        // operand twice. Scalar copies force the full-width `.16B`
                        // arrangement (Q=1) via a trailing `Imm(1)` selector —
                        // the `.8B` (Q=0) form the dest class would otherwise imply
                        // is NOT move-eliminated on M-series. Copying the source's
                        // (architecturally undefined) upper 64 bits into the dest
                        // is sound because only the low `<=64` bits are defined for
                        // the `Fpr16/Fpr32/Fpr64` classes and nothing in the backend
                        // reads a scalar FPR's upper 64 bits (a 128-bit read needs
                        // an `Fpr128` vreg, which carries a full-width def). It is
                        // also bit-preserving, so signalling-NaN payloads survive a
                        // copy chain unchanged. `Fpr128` already implies Q=1 from
                        // its dest class, so it keeps the 3-operand form.
                        class @ (RegClass::Fpr16
                        | RegClass::Fpr32
                        | RegClass::Fpr64
                        | RegClass::Fpr128) => {
                            let src = inst.operands[1].clone();
                            inst.operands.truncate(2);
                            inst.operands.push(src);
                            if class != RegClass::Fpr128 {
                                // Force `.16B` (Q=1); `neon_q_bit` reads this
                                // trailing Imm as the arrangement selector.
                                inst.operands.push(IrOperand::Imm(1));
                            }
                            IrOpcode::NeonOrrV
                        }
                        class @ (RegClass::Fpr8 | RegClass::System) => {
                            return Err(PipelineError::Encoding(format!(
                                "cannot lower Copy to {class:?} destination {preg:?} in `{}`: \
                                 no encodable register-move form (fail-closed)",
                                ir_func.name
                            )));
                        }
                    },
                    // Special GPR aliases: XZR/WZR discard destinations.
                    IrOperand::Special(
                        trust_cg_ir::regs::SpecialReg::XZR | trust_cg_ir::regs::SpecialReg::WZR,
                    ) => IrOpcode::MovR,
                    other => {
                        return Err(PipelineError::Encoding(format!(
                            "cannot lower Copy with non-register destination {other:?} in `{}` \
                             (fail-closed)",
                            ir_func.name
                        )));
                    }
                };
                // Clear the IS_PSEUDO flag so the encoder processes this as a
                // real instruction.
                inst.flags.remove(trust_cg_ir::inst::InstFlags::IS_PSEUDO);
            }
        }
    }

    Ok(())
}

/// Drop unused scalar register-formal copies while their destinations are
/// still virtual. The latency allocator can assign even an unused formal a
/// physical W register; waiting until lower_copies would then emit a dead
/// MOVWrr. A return theorem cannot credit that instruction (OD-35 C).
/// Keep live copies, all implicit clobbers, non-formal copies and non-GPR
/// materializations. Retain the NOP's ABI liveness metadata for later formals.
fn eliminate_dead_register_formal_copies(ir_func: &mut IrMachFunction) -> usize {
    use trust_cg_ir::provenance::{LoweringProvenance, SyntheticReason};
    let use_counts = reachable_vreg_use_counts(ir_func);
    let ids: Vec<_> = ir_func
        .block_order
        .iter()
        .flat_map(|block| &ir_func.blocks[block.0 as usize].insts)
        .copied()
        .collect();
    let mut removed = 0;
    for id in ids {
        let inst = ir_func.inst(id);
        let [IrOperand::VReg(dst), IrOperand::PReg(src)] = inst.operands.as_slice() else {
            continue;
        };
        if inst.opcode == IrOpcode::Copy
            && inst.flags == trust_cg_ir::InstFlags::IS_PSEUDO
            && inst.implicit_defs.is_empty()
            && matches!((dst.class, src.encoding()), (RegClass::Gpr32, 0..=7 | 32..=39) | (RegClass::Gpr64, 0..=7))
            && matches!(
                ir_func.inst_lowering_provenance(id),
                LoweringProvenance::Synthetic {
                    reason: SyntheticReason::FormalArguments
                }
            )
            && use_counts.get(dst).copied().unwrap_or(0) == 0
        {
            let inst = ir_func.inst_mut(id);
            inst.opcode = IrOpcode::Nop;
            // An inert tombstone has no explicit register operands. Keeping
            // the dead VReg would let allocation invent an unrelated PReg
            // pair in the NOP and obscure its independently checked inertness.
            inst.operands.clear();
            removed += 1;
        }
    }
    removed
}

/// Retire unused virtual literal definitions before a latency allocator gives
/// even dead values physical registers. Immediate folding can consume a
/// constant without emitting a register use; retaining that materialization
/// adds a real, unrelated instruction to the final stream. Admit only exact
/// pure literal schemas, with no implicit effects; do not use provenance as
/// permission to erase an instruction.
fn eliminate_dead_literal_materializations(ir_func: &mut IrMachFunction) -> usize {
    let uses = reachable_vreg_use_counts(ir_func);
    let mut removed = 0;
    for inst in &mut ir_func.insts {
        let Some(IrOperand::VReg(dst)) = inst.operands.first() else {
            continue;
        };
        let bits = match dst.class {
            RegClass::Gpr32 => 32,
            RegClass::Gpr64 => 64,
            _ => continue,
        };
        if inst.flags != trust_cg_ir::InstFlags::EMPTY
            || !inst.implicit_defs.is_empty()
            || !inst.implicit_uses.is_empty()
            || uses.get(dst).copied().unwrap_or(0) != 0
        {
            continue;
        }
        let literal = match (inst.opcode, inst.operands.as_slice()) {
            (IrOpcode::MovI, [IrOperand::VReg(_), IrOperand::Imm(_)]) => true,
            (IrOpcode::Movz | IrOpcode::Movn, [IrOperand::VReg(_), IrOperand::Imm(0..=65535)]) => {
                true
            }
            (
                IrOpcode::Movz | IrOpcode::Movn,
                [
                    IrOperand::VReg(_),
                    IrOperand::Imm(0..=65535),
                    IrOperand::Imm(shift),
                ],
            ) => (0..bits).contains(shift) && shift % 16 == 0,
            _ => false,
        };
        if literal {
            inst.opcode = IrOpcode::Nop;
            inst.flags = trust_cg_ir::InstFlags::IS_PSEUDO;
            inst.operands.clear();
            removed += 1;
        }
    }
    removed
}

/// Eliminate the redundant second copy of an adjacent two-copy round-trip
/// `Copy b <- a; Copy a <- b`.
///
/// After `Copy b <- a`, register `b` holds the value of `a`, so the immediately
/// following `Copy a <- b` is `a <- a` — a provable no-op. A genuine register
/// *swap* requires a scratch register (three copies: `t<-a; a<-b; b<-t`), so an
/// adjacent two-copy `b<-a; a<-b` is ALWAYS a redundant round-trip and removing
/// the second copy never changes program meaning.
///
/// Runs immediately before [`fixup_aarch64_call_arg_source_clobbers`], which
/// treats a call's argument-register setup as a *parallel* move. The register
/// allocator can emit such a round-trip when relocating a call result out of and
/// back into an argument register; read as a parallel swap, the fixup would
/// preserve a stale value and clobber a live argument. Dropping the redundant
/// copy first keeps the setup a faithful sequential assignment.
fn eliminate_redundant_copy_roundtrips(ir_func: &mut IrMachFunction) {
    let block_order = ir_func.block_order.clone();
    for block_id in block_order {
        let insts = ir_func.block(block_id).insts.clone();
        for window in insts.windows(2) {
            let (id0, id1) = (window[0], window[1]);
            let pair = {
                let first = ir_func.inst(id0);
                let second = ir_func.inst(id1);
                if first.opcode == IrOpcode::Copy && second.opcode == IrOpcode::Copy {
                    match (
                        first.operands.first(),
                        first.operands.get(1),
                        second.operands.first(),
                        second.operands.get(1),
                    ) {
                        (
                            Some(IrOperand::PReg(fd)),
                            Some(IrOperand::PReg(fs)),
                            Some(IrOperand::PReg(sd)),
                            Some(IrOperand::PReg(ss)),
                        ) => Some((*fd, *fs, *sd, *ss)),
                        _ => None,
                    }
                } else {
                    None
                }
            };
            // first: fd <- fs ; second: sd <- ss. Round-trip iff second is the
            // inverse of first (sd == fs, ss == fd) and it is not a self-copy.
            if let Some((fd, fs, sd, ss)) = pair
                && sd == fs
                && ss == fd
                && fd != fs
            {
                let second = ir_func.inst_mut(id1);
                second.opcode = IrOpcode::Nop;
                // If the second copy carries call-setup semantic provenance, the
                // sequential round-trip proof establishes that its destination
                // already contains the required value. Preserve that fact as
                // an exact identity marker; leaving the stale pre-elimination
                // source operand would make the final provenance malformed.
                if second.flags.is_call_arg_setup() {
                    second.operands[1] = IrOperand::PReg(sd);
                }
            }
        }
    }
}

// ---------------------------------------------------------------------------
// AArch64 call argument setup repair
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Aarch64CallArgSetupKind {
    Copy,
    Uxtw,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Aarch64CallArgSetup {
    inst_id: InstId,
    src: PReg,
    dst: PReg,
    kind: Aarch64CallArgSetupKind,
}

/// Make physical-register argument setup behave like a parallel move.
///
/// After register allocation, a call sequence can contain physical copies into
/// ABI argument registers immediately before a `BL`/`BLR`. Those copies are a
/// logical parallel assignment: all sources must be read before any destination
/// clobbers another source. A sequential lowering such as `X0 <- X1; X1 <- X0`
/// corrupts the second argument unless the original `X0` is preserved first.
///
/// This pass runs before pseudo `Copy` lowering. It keeps already-safe call
/// sequences unchanged and only inserts scratch preserves for sources that
/// would otherwise be overwritten by an earlier argument-register setup.
fn fixup_aarch64_call_arg_source_clobbers(
    ir_func: &mut IrMachFunction,
    abi_variant: AArch64AbiVariant,
) -> Result<(), PipelineError> {
    // Plan and apply on a clone so any late planning failure leaves the caller's
    // function byte-for-byte unchanged. In particular, no rewritten setup may
    // point at a scratch save that was never inserted.
    let mut repaired = ir_func.clone();
    fixup_aarch64_call_arg_source_clobbers_in_place(&mut repaired, abi_variant)?;
    *ir_func = repaired;
    Ok(())
}

fn fixup_aarch64_call_arg_source_clobbers_in_place(
    ir_func: &mut IrMachFunction,
    abi_variant: AArch64AbiVariant,
) -> Result<(), PipelineError> {
    let block_order = ir_func.block_order.clone();
    #[cfg(debug_assertions)]
    let debug = std::env::var("TRUST_CG_DEBUG_REGALLOC").is_ok();

    for block_id in block_order {
        let insts = ir_func.block(block_id).insts.clone();
        let mut insertions: Vec<(usize, Vec<InstId>)> = Vec::new();

        for (call_pos, &call_id) in insts.iter().enumerate() {
            let call_implicit_uses = {
                let call_inst = ir_func.inst(call_id);
                if !is_aarch64_call_boundary(call_inst) || call_inst.implicit_uses.is_empty() {
                    continue;
                }
                call_inst.implicit_uses.to_vec()
            };
            // One namespace for every exact parallel-move source cycle at this
            // call, so two preserved sources never reuse a scratch.
            let mut allocated_scratch = Vec::new();

            let setup_region = aarch64_call_arg_setups_in_current_region(
                ir_func,
                &insts,
                call_pos,
                &call_implicit_uses,
            )?;
            if let Some(group_start) = setup_region.first().map(|(pos, _)| *pos) {
                // Marked setups need not remain contiguous: spill
                // materialization may insert sequential reloads between them.
                // The semantic setup flag, not adjacency, determines membership
                // in this logical parallel assignment.
                let setups: Vec<Aarch64CallArgSetup> =
                    setup_region.into_iter().map(|(_, setup)| setup).collect();
                let setups = prune_redundant_aarch64_identity_arg_setups(setups);

                #[cfg(debug_assertions)]
                if debug {
                    eprintln!(
                        "  aarch64_call_arg_fixup block={:?} call={:?} implicit_uses={:?} setups={:?}",
                        block_id, call_id, call_implicit_uses, setups
                    );
                }

                let preserve_sources = aarch64_call_arg_sources_requiring_preserve(&setups);
                if !preserve_sources.is_empty() {
                    let protected = aarch64_call_arg_protected_regs(
                        ir_func,
                        ir_func.inst(call_id),
                        &insts[group_start..call_pos],
                    );
                    let mut preserves = Vec::new();

                    for source in preserve_sources {
                        let scratch = choose_aarch64_call_arg_scratch(
                            source,
                            &protected,
                            &allocated_scratch,
                        )
                        .ok_or_else(|| {
                            PipelineError::Aarch64CallArgRepair(format!(
                                "function `{}` block {:?} call {:?}: no {:?} scratch register can preserve parallel-move source {:?}",
                                ir_func.name,
                                block_id,
                                call_id,
                                preg_class(source),
                                source
                            ))
                        })?;
                        allocated_scratch.push(scratch);
                        preserves.push((source, scratch));
                    }

                    #[cfg(debug_assertions)]
                    if debug {
                        eprintln!(
                            "  aarch64_call_arg_fixup preserves for call {:?}: {:?}",
                            call_id, preserves
                        );
                    }

                    if !preserves.is_empty() {
                        let preserve_insts: Vec<_> = preserves
                            .iter()
                            .map(|&(source, scratch)| {
                                ir_func.push_inst(IrMachInst::new(
                                    IrOpcode::Copy,
                                    vec![IrOperand::PReg(scratch), IrOperand::PReg(source)],
                                ))
                            })
                            .collect();

                        for setup in setups {
                            if let Some((_, scratch)) =
                                preserves.iter().find(|&&(source, _)| source == setup.src)
                            {
                                rewrite_aarch64_call_arg_setup_source(
                                    ir_func.inst_mut(setup.inst_id),
                                    setup.kind,
                                    *scratch,
                                );
                            }
                        }

                        insertions.push((group_start, preserve_insts));
                    }
                }
            }

            // A non-setup definition of an ABI argument register can either be a
            // transient borrow or the actual value consumed by the call. The
            // liveness-gated repair rescues the safe cases (a live value across a
            // transient clobber -> preserve/restore) and leaves the establishing
            // cases alone (a dead incoming value the clobber legitimately supplies
            // -> no restore). Cases it cannot clear insert nothing, so a guessed
            // older value is never restored over a possibly real call argument;
            // the final `verify_aarch64_final_call_argument_sequence` gate below
            // still fails closed on any residual unresolved hazard.
            let dest_preserves =
                aarch64_call_arg_dest_preserves(ir_func, &insts, call_pos, &call_implicit_uses)?;
            let implicit_preserves = aarch64_call_arg_implicit_preserves(
                ir_func,
                &insts,
                call_pos,
                &call_implicit_uses,
                block_id == ir_func.entry,
                abi_variant,
            )?;
            for preserve in dest_preserves.into_iter().chain(implicit_preserves) {
                let preserve_inst = ir_func.push_inst(IrMachInst::new(
                    IrOpcode::Copy,
                    vec![
                        IrOperand::PReg(preserve.scratch),
                        IrOperand::PReg(preserve.arg_reg),
                    ],
                ));
                let restore_inst = ir_func.push_inst(IrMachInst::new(
                    IrOpcode::Copy,
                    vec![
                        IrOperand::PReg(preserve.arg_reg),
                        IrOperand::PReg(preserve.scratch),
                    ],
                ));
                insertions.push((preserve.insert_after_pos + 1, vec![preserve_inst]));
                insertions.push((call_pos, vec![restore_inst]));
            }
        }

        if insertions.is_empty() {
            continue;
        }

        let block = ir_func.block_mut(block_id);
        insertions.sort_by_key(|(insert_pos, _)| *insert_pos);
        for (insert_pos, inserted_insts) in insertions.into_iter().rev() {
            block.insts.splice(insert_pos..insert_pos, inserted_insts);
        }
    }

    Ok(())
}

/// Drop an identity setup whose destination was already established earlier
/// in the same contiguous argument group.
///
/// Post-RA coalescing deliberately retains a final `xN <- xN` as provenance
/// for the single-setup case. In a group such as `x1 <- x19; x0 <- x21;
/// x1 <- x1`, however, the identity reads the value just written by the first
/// setup; treating its source as the *pre-group* x1 value makes the
/// parallel-move repair preserve and restore stale data over the real x1
/// argument.
fn prune_redundant_aarch64_identity_arg_setups(
    setups: Vec<Aarch64CallArgSetup>,
) -> Vec<Aarch64CallArgSetup> {
    setups
        .iter()
        .enumerate()
        .filter_map(|(idx, setup)| {
            let redundant_identity = setup.dst == setup.src
                && setups[..idx]
                    .iter()
                    .any(|earlier| regs_overlap(earlier.dst, setup.dst));
            (!redundant_identity).then_some(*setup)
        })
        .collect()
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Aarch64CallArgDestPreserve {
    insert_after_pos: usize,
    arg_reg: PReg,
    scratch: PReg,
}

// Repair (not fail-closed): rescue a live argument-register value that a
// transient in-region clobber destroys, gated by liveness so a clobber that
// legitimately establishes the argument is left ALONE. This is the
// scalar-temp / num_objs / entry-alloca-addr defect family: where the parallel
// session's audit chose to fail closed on the ambiguous physical stream, the
// liveness gates below prove which of those streams are actually safe (the
// wp5/wp6/wp7 whole-program shapes) and either skip (dead incoming value) or
// preserve/restore (live value across a transient clobber). Cases NOT cleared
// by a gate still fall through: `dest_preserves`/`implicit_preserves` never
// insert a guessed restore, and the setup-parallel-move fail-closed paths and
// the final `verify_aarch64_final_call_argument_sequence` gate remain intact.
fn aarch64_call_arg_dest_preserves(
    ir_func: &IrMachFunction,
    insts: &[InstId],
    call_pos: usize,
    call_implicit_uses: &[PReg],
) -> Result<Vec<Aarch64CallArgDestPreserve>, PipelineError> {
    let setups =
        aarch64_call_arg_setups_in_current_region(ir_func, insts, call_pos, call_implicit_uses)?;
    let mut preserves = Vec::new();
    let mut allocated_scratch = Vec::new();

    for (setup_pos, setup) in setups.iter().copied() {
        let setup_is_overwritten_by_later_setup = setups.iter().any(|(other_pos, other_setup)| {
            *other_pos > setup_pos && regs_overlap(other_setup.dst, setup.dst)
        });
        if setup_is_overwritten_by_later_setup {
            continue;
        }

        let later_clobbers_arg = insts[setup_pos + 1..call_pos].iter().any(|&inst_id| {
            aarch64_inst_def_pregs(ir_func.inst(inst_id))
                .into_iter()
                .any(|defined| regs_overlap(defined, setup.dst))
        });
        if !later_clobbers_arg {
            continue;
        }

        // Liveness gate: only preserve+restore the setup's value if it is the
        // value the call actually needs in `setup.dst`. If a later instruction
        // writes `setup.dst` with a value that survives unread to the call, that
        // instruction establishes the argument and the setup's value is DEAD.
        // Restoring a dead value here would clobber the real argument (defect
        // #4b: a narrow value materialized by `uxth wN, wM` into a pre-colored
        // arg register was being overwritten by a spurious restore of an
        // unrelated dead value that the allocator had parked in the same reg).
        if !aarch64_call_arg_setup_value_reaches_call(
            ir_func, insts, setup_pos, call_pos, setup.dst,
        ) {
            continue;
        }

        let mut protected =
            aarch64_call_arg_region_protected_regs(ir_func, insts, setup_pos + 1, call_pos);
        push_unique_overlap(&mut protected, setup.dst);

        let Some(scratch) =
            choose_aarch64_call_arg_scratch(setup.dst, &protected, &allocated_scratch)
        else {
            continue;
        };
        allocated_scratch.push(scratch);
        preserves.push(Aarch64CallArgDestPreserve {
            insert_after_pos: setup_pos,
            arg_reg: setup.dst,
            scratch,
        });
    }

    Ok(preserves)
}

/// Decide whether the value written by the call-argument setup at `setup_pos`
/// (into `arg_reg`) is the value the call actually consumes from `arg_reg`.
///
/// The setup value reaches the call only if every intervening definition of
/// `arg_reg` between the setup and the call is *transient* — i.e. its result is
/// read by some instruction strictly before the call (a temporary borrow of the
/// physical register). If any intervening definition writes `arg_reg` with a
/// value that survives unread up to the call, that later definition establishes
/// the argument and the setup's value is dead. In the dead case we must NOT
/// preserve/restore the setup value, because restoring it would overwrite the
/// real argument the call expects (defect #4b).
fn aarch64_call_arg_setup_value_reaches_call(
    ir_func: &IrMachFunction,
    insts: &[InstId],
    setup_pos: usize,
    call_pos: usize,
    arg_reg: PReg,
) -> bool {
    // Walk forward through the region between the setup and the call. Track
    // whether `arg_reg` currently holds the setup's value. Each definition of
    // `arg_reg` either:
    //   - is consumed before the call (the surviving value is still the setup's
    //     value, so processing continues), or
    //   - survives unread to the call (the setup value is dead -> return false).
    for clobber_pos in (setup_pos + 1)..call_pos {
        let clobber_inst = ir_func.inst(insts[clobber_pos]);
        let defines_arg = aarch64_inst_def_pregs(clobber_inst)
            .into_iter()
            .any(|defined| regs_overlap(defined, arg_reg));
        if !defines_arg {
            continue;
        }

        // Is this clobbering definition's value read again before the call by a
        // non-call instruction? If so it is a transient temporary and the setup
        // value is the one the call needs (restore is required). If not, this
        // definition supplies the call's argument and the setup value is dead.
        let consumed_before_call = insts[(clobber_pos + 1)..call_pos].iter().any(|&later_id| {
            aarch64_inst_use_pregs(ir_func.inst(later_id))
                .into_iter()
                .any(|used| regs_overlap(used, arg_reg))
        });
        if !consumed_before_call {
            return false;
        }
    }

    true
}

fn aarch64_call_arg_region_protected_regs(
    ir_func: &IrMachFunction,
    insts: &[InstId],
    start_pos: usize,
    call_pos: usize,
) -> Vec<PReg> {
    let mut protected = Vec::new();

    for (pos, &inst_id) in insts.iter().enumerate().take(call_pos + 1).skip(start_pos) {
        let inst = ir_func.inst(inst_id);
        for preg in aarch64_inst_def_pregs(inst)
            .into_iter()
            .chain(aarch64_inst_use_pregs(inst))
        {
            push_unique_overlap(&mut protected, preg);
        }
        if pos < call_pos {
            for &preg in inst.implicit_defs {
                push_unique_overlap(&mut protected, preg);
            }
        }
        for &preg in inst.implicit_uses {
            push_unique_overlap(&mut protected, preg);
        }
    }

    protected
}

/// Preserve *implicit* argument registers — ABI arg registers the call reads
/// (`implicit_uses`) that are NOT established by any explicit setup copy/uxtw,
/// i.e. the allocator left their value "already in place" (typically a prior
/// call's result) — when that value is clobbered before the call.
///
/// `aarch64_call_arg_dest_preserves` only protects registers written by a
/// recognized *setup*. When an argument is the result of an earlier call it sits
/// in its ABI register with no setup; if the allocator then materializes another
/// argument's constant into that same register (`mov x0, #imm; mov x2, x0`) and
/// parks the original elsewhere without reloading it, the call runs with the
/// constant in place of the live pointer. This pass saves such a register's
/// value immediately before its first clobber and restores it immediately
/// before the call — gated by the liveness preconditions below so a clobber
/// that legitimately establishes the argument (a dead incoming value) is left
/// alone rather than rescued.
fn aarch64_call_arg_implicit_preserves(
    ir_func: &IrMachFunction,
    insts: &[InstId],
    call_pos: usize,
    call_implicit_uses: &[PReg],
    is_entry_block: bool,
    abi_variant: AArch64AbiVariant,
) -> Result<Vec<Aarch64CallArgDestPreserve>, PipelineError> {
    // Region in which the argument value is established/clobbered: from the most
    // recent prior call (exclusive) or block start, up to this call. Argument
    // values that are prior-call results live in this window.
    let region_start = {
        let mut s = call_pos;
        while s > 0 && !ir_func.inst(insts[s - 1]).is_call() {
            s -= 1;
        }
        s
    };

    // Registers that hold a LIVE incoming value at the top of the entry block:
    // exactly the formal-parameter ABI registers. Every other argument register
    // holds caller-supplied, unused garbage there. Only meaningful when the
    // region opens at the function entry (region_start == 0 in the entry block).
    let entry_formal_regs: Vec<PReg> = if is_entry_block && region_start == 0 {
        aarch64_formal_abi_source_regs(&ir_func.signature, abi_variant)
    } else {
        Vec::new()
    };

    let setups =
        aarch64_call_arg_setups_in_current_region(ir_func, insts, call_pos, call_implicit_uses)?;
    let mut preserves = Vec::new();
    let mut allocated_scratch = Vec::new();

    for &arg_reg in call_implicit_uses {
        // Skip registers an explicit setup already establishes — those are the
        // `dest_preserves` pass's responsibility.
        if setups.iter().any(|(_, s)| regs_overlap(s.dst, arg_reg)) {
            continue;
        }
        // First clobber of `arg_reg` within the region. With none, the register
        // still holds its incoming value at the call — nothing to do.
        let Some(first_clobber_pos) = (region_start..call_pos).find(|&pos| {
            aarch64_inst_def_pregs(ir_func.inst(insts[pos]))
                .into_iter()
                .any(|defined| regs_overlap(defined, arg_reg))
        }) else {
            continue;
        };
        if first_clobber_pos == 0 {
            continue;
        }
        // Liveness precondition (defect: alloca-address call argument at fn entry).
        // At the top of the entry block, the ONLY argument registers holding a
        // live incoming value are the formal-parameter ABI registers; every other
        // one holds dead, caller-supplied garbage. If `arg_reg` is not a formal-
        // parameter register, its region-entry value is dead and the in-region
        // clobber legitimately ESTABLISHES the argument (typically `sub xN,x29,#imm`
        // materializing a stack alloca address passed as this argument). Restoring
        // its dead entry value would pass null/garbage (the `grow_amortized`
        // SIGSEGV). Skip.
        if is_entry_block
            && region_start == 0
            && !entry_formal_regs
                .iter()
                .any(|&formal| regs_overlap(formal, arg_reg))
        {
            continue;
        }
        // Liveness precondition (defect: variadic ctor num_objs/scalar clobbered).
        // If the region opens right after a call that *clobbered* `arg_reg` as a
        // caller-saved scratch (in the call's `implicit_defs`) and `arg_reg` is NOT
        // that call's result register (hw-encoding 0), the region-entry value is
        // dead garbage — restoring it would overwrite the argument the in-region
        // instructions correctly established (e.g. `Movz w1,#1` for `num_objs`).
        // Skip.
        if region_start >= 1 {
            let opening = ir_func.inst(insts[region_start - 1]);
            let clobbered_by_opening_call = opening.is_call()
                && opening
                    .implicit_defs
                    .iter()
                    .any(|&d| regs_overlap(d, arg_reg));
            if clobbered_by_opening_call && hw_encoding(arg_reg) != 0 {
                continue;
            }
        }
        // Liveness precondition (defect: `&(fresh scalar temp)` argument clobber).
        // If some instruction in `[region_start, first_clobber_pos)` READS
        // `arg_reg`, that read is the entry value's last use (it was relocated/
        // consumed) and the entry value is DEAD by the clobber; the clobber then
        // legitimately ESTABLISHES the argument (`sub x0,x29,#imm` materializing
        // `&disc_temp` whose value a `str` also reads yet IS arg0). Skip.
        let entry_value_read_before_clobber =
            insts[region_start..first_clobber_pos].iter().any(|&id| {
                aarch64_inst_use_pregs(ir_func.inst(id))
                    .into_iter()
                    .any(|used| regs_overlap(used, arg_reg))
            });
        if entry_value_read_before_clobber {
            continue;
        }
        // The pre-clobber value must be the one the call needs (all clobbers
        // transient). `setup_pos = first_clobber_pos - 1` makes the first clobber
        // the first one inspected.
        if !aarch64_call_arg_setup_value_reaches_call(
            ir_func,
            insts,
            first_clobber_pos - 1,
            call_pos,
            arg_reg,
        ) {
            continue;
        }
        // Scratch must survive the clobber..call window and not alias any live reg.
        let mut protected =
            aarch64_call_arg_region_protected_regs(ir_func, insts, first_clobber_pos, call_pos);
        push_unique_overlap(&mut protected, arg_reg);
        let Some(scratch) =
            choose_aarch64_call_arg_scratch(arg_reg, &protected, &allocated_scratch)
        else {
            continue;
        };
        allocated_scratch.push(scratch);
        preserves.push(Aarch64CallArgDestPreserve {
            // Save copy lands at `insert_after_pos + 1` == `first_clobber_pos`,
            // i.e. immediately before the clobber, where `arg_reg` is still live.
            insert_after_pos: first_clobber_pos - 1,
            arg_reg,
            scratch,
        });
    }

    Ok(preserves)
}

fn aarch64_call_arg_setups_in_current_region(
    ir_func: &IrMachFunction,
    insts: &[InstId],
    call_pos: usize,
    call_implicit_uses: &[PReg],
) -> Result<Vec<(usize, Aarch64CallArgSetup)>, PipelineError> {
    let mut setups = Vec::new();
    let mut pos = call_pos;

    while pos > 0 {
        pos -= 1;
        let inst = ir_func.inst(insts[pos]);
        if is_aarch64_call_boundary(inst) || inst.flags.is_branch() || inst.flags.is_return() {
            break;
        }
        let classified = classify_aarch64_call_arg_setup(inst, call_implicit_uses);
        if inst.flags.is_call_arg_setup() && classified.is_none() {
            return Err(PipelineError::Aarch64CallArgRepair(format!(
                "function `{}` call {:?}: malformed semantic call-argument setup {:?} at position {pos}: opcode {:?}, operands {:?}; expected exactly one ABI argument definition and at least one physical source",
                ir_func.name, insts[call_pos], insts[pos], inst.opcode, inst.operands
            )));
        }
        if let Some(setup) = classified
            && call_implicit_uses
                .iter()
                .any(|&arg_reg| regs_overlap(arg_reg, setup.dst))
        {
            setups.push((
                pos,
                Aarch64CallArgSetup {
                    inst_id: insts[pos],
                    ..setup
                },
            ));
        }
    }

    setups.reverse();
    Ok(setups)
}

fn aarch64_inst_def_pregs(inst: &IrMachInst) -> Vec<PReg> {
    let mut defs: Vec<_> = classify_operand_positions(inst)
        .0
        .into_iter()
        .filter_map(|pos| match inst.operands.get(pos) {
            Some(IrOperand::PReg(preg)) => Some(*preg),
            _ => None,
        })
        .collect();
    for &preg in inst.implicit_defs {
        if !defs.contains(&preg) {
            defs.push(preg);
        }
    }
    defs
}

fn aarch64_inst_use_pregs(inst: &IrMachInst) -> Vec<PReg> {
    let mut uses: Vec<_> = classify_operand_positions(inst)
        .1
        .into_iter()
        .filter_map(|pos| match inst.operands.get(pos) {
            Some(IrOperand::PReg(preg)) => Some(*preg),
            _ => None,
        })
        .collect();
    for &preg in inst.implicit_uses {
        if !uses.contains(&preg) {
            uses.push(preg);
        }
    }
    uses
}

fn classify_aarch64_call_arg_setup(
    inst: &IrMachInst,
    call_implicit_uses: &[PReg],
) -> Option<Aarch64CallArgSetup> {
    if !inst.flags.is_call_arg_setup() {
        return None;
    }
    if inst.opcode == IrOpcode::Nop {
        let (Some(IrOperand::PReg(dst)), Some(IrOperand::PReg(src))) =
            (inst.operands.first(), inst.operands.get(1))
        else {
            return None;
        };
        return (regs_overlap(*dst, *src)
            && call_implicit_uses
                .iter()
                .any(|&arg| regs_overlap(arg, *dst)))
        .then_some(Aarch64CallArgSetup {
            inst_id: InstId(0),
            src: *src,
            dst: *dst,
            kind: Aarch64CallArgSetupKind::Copy,
        });
    }
    let matching_defs: Vec<_> = aarch64_inst_def_pregs(inst)
        .into_iter()
        .filter(|defined| {
            call_implicit_uses
                .iter()
                .any(|&arg| regs_overlap(arg, *defined))
        })
        .collect();
    let [dst] = matching_defs.as_slice() else {
        return None;
    };
    let src = aarch64_inst_use_pregs(inst).into_iter().next()?;
    Some(Aarch64CallArgSetup {
        inst_id: InstId(0),
        src,
        dst: *dst,
        kind: if inst.opcode == IrOpcode::Uxtw {
            Aarch64CallArgSetupKind::Uxtw
        } else {
            Aarch64CallArgSetupKind::Copy
        },
    })
}

fn classify_aarch64_final_call_arg_setup(
    inst: &IrMachInst,
    call_implicit_uses: &[PReg],
) -> Option<Aarch64CallArgSetup> {
    if !inst.flags.is_call_arg_setup() {
        return None;
    }
    // An identity copy becomes a non-encoding NOP during Copy lowering, but
    // its exact operands and provenance remain available here.
    if inst.opcode == IrOpcode::Nop {
        let (Some(IrOperand::PReg(dst)), Some(IrOperand::PReg(src))) =
            (inst.operands.first(), inst.operands.get(1))
        else {
            return None;
        };
        return (regs_overlap(*dst, *src)
            && call_implicit_uses
                .iter()
                .any(|&arg| regs_overlap(arg, *dst)))
        .then_some(Aarch64CallArgSetup {
            inst_id: InstId(0),
            src: *src,
            dst: *dst,
            kind: Aarch64CallArgSetupKind::Copy,
        });
    }

    let matching_defs: Vec<_> = aarch64_inst_def_pregs(inst)
        .into_iter()
        .filter(|defined| {
            call_implicit_uses
                .iter()
                .any(|&arg| regs_overlap(arg, *defined))
        })
        .collect();
    let [dst] = matching_defs.as_slice() else {
        return None;
    };
    let src = aarch64_inst_use_pregs(inst).into_iter().next()?;
    Some(Aarch64CallArgSetup {
        inst_id: InstId(0),
        src,
        dst: *dst,
        kind: if inst.opcode == IrOpcode::Uxtw {
            Aarch64CallArgSetupKind::Uxtw
        } else {
            Aarch64CallArgSetupKind::Copy
        },
    })
}

/// Independently re-check final physical call-argument setup immediately before
/// encoding. The repair runs during register allocation, but frame lowering,
/// pseudo expansion, layout, and branch relaxation all happen later. This gate
/// therefore consumes the exact final MOV/Uxtw operands and each call's exact
/// physical argument-register identities (`implicit_uses`) rather than trusting
/// that the earlier repair remained valid.
///
/// The input is one final emission sequence (a MachIR block, or the flattened
/// sequence produced by branch relaxation). No value identity is guessed: an
/// unresolved parallel-move source clobber or an ambiguous argument-register
/// clobber fails closed.
pub(crate) fn verify_aarch64_final_call_argument_sequence<'a>(
    function_name: &str,
    insts: impl IntoIterator<Item = &'a IrMachInst>,
) -> Result<(), PipelineError> {
    let insts: Vec<_> = insts.into_iter().collect();

    for (call_pos, call) in insts.iter().copied().enumerate() {
        if !is_aarch64_call_boundary(call) || call.implicit_uses.is_empty() {
            continue;
        }
        let call_args = call.implicit_uses;

        // `Copy` is a non-encoding pseudo. Crediting it as an argument setup at
        // this boundary would prove a write that the encoder silently omits.
        // The exact final stream must carry a real MOV/Uxtw form instead.
        if insts[..call_pos]
            .iter()
            .rev()
            .take_while(|inst| {
                !is_aarch64_call_boundary(inst)
                    && !inst.flags.is_branch()
                    && !inst.flags.is_return()
            })
            .any(|inst| {
                inst.opcode == IrOpcode::Copy
                    && aarch64_inst_def_pregs(inst)
                        .into_iter()
                        .any(|defined| call_args.iter().any(|&arg| regs_overlap(defined, arg)))
            })
        {
            return Err(PipelineError::Aarch64CallArgRepair(format!(
                "function `{function_name}` final call at instruction {call_pos}: \
                 unresolved Copy pseudo defines an ABI argument register; the \
                 encoder would omit the required setup"
            )));
        }

        // A final contiguous argument-move group has parallel semantics. Every
        // source must still be readable when its move executes. The early
        // repair rewrites clobbered sources to scratch registers; seeing one
        // here proves a later mutation invalidated or bypassed that repair.
        let mut region_start = call_pos;
        while region_start > 0 {
            let previous = insts[region_start - 1];
            if is_aarch64_call_boundary(previous)
                || previous.flags.is_branch()
                || previous.flags.is_return()
            {
                break;
            }
            region_start -= 1;
        }
        if let Some((offset, _)) =
            insts[region_start..call_pos]
                .iter()
                .enumerate()
                .find(|(_, inst)| {
                    inst.flags.is_call_arg_setup()
                        && classify_aarch64_final_call_arg_setup(inst, call_args).is_none()
                })
        {
            return Err(PipelineError::Aarch64CallArgRepair(format!(
                "function `{function_name}` final call at instruction {call_pos}: malformed semantic call-argument setup at instruction {}; expected exactly one ABI argument definition and at least one physical source",
                region_start + offset
            )));
        }
        let group: Vec<_> = insts[region_start..call_pos]
            .iter()
            .copied()
            .filter_map(|inst| classify_aarch64_final_call_arg_setup(inst, call_args))
            .collect();
        for (idx, setup) in group.iter().enumerate() {
            if let Some(previous) = group[..idx]
                .iter()
                .find(|previous| regs_overlap(previous.dst, setup.src))
            {
                return Err(PipelineError::Aarch64CallArgRepair(format!(
                    "function `{function_name}` final call at instruction {call_pos}: \
                     argument setup {:?} <- {:?} reads a source clobbered by earlier \
                     setup {:?} <- {:?}; final stream no longer preserves exact \
                     parallel-move source identity",
                    setup.dst, setup.src, previous.dst, previous.src
                )));
            }
        }

        verify_aarch64_final_call_argument_clobbers(function_name, &insts, call_pos, call_args)?;
    }

    Ok(())
}

fn verify_aarch64_final_call_argument_clobbers(
    function_name: &str,
    insts: &[&IrMachInst],
    call_pos: usize,
    call_args: &[PReg],
) -> Result<(), PipelineError> {
    let mut region_start = call_pos;
    while region_start > 0 {
        let previous = insts[region_start - 1];
        if is_aarch64_call_boundary(previous)
            || previous.flags.is_branch()
            || previous.flags.is_return()
        {
            break;
        }
        region_start -= 1;
    }

    let setups: Vec<_> = (region_start..call_pos)
        .filter_map(|pos| {
            classify_aarch64_final_call_arg_setup(insts[pos], call_args).map(|setup| (pos, setup))
        })
        .collect();

    // Explicitly established arguments: a later non-setup clobber that is also
    // consumed before the call is ambiguous in physical MachIR. It might be a
    // temporary, or it might intentionally replace the argument; encoding must
    // not guess which value the call was meant to consume.
    for (setup_index, (setup_pos, setup)) in setups.iter().copied().enumerate() {
        if setups[setup_index + 1..]
            .iter()
            .any(|(_, later)| regs_overlap(later.dst, setup.dst))
        {
            continue;
        }
        let first_later_clobber = (setup_pos + 1..call_pos).find(|&pos| {
            aarch64_inst_def_pregs(insts[pos])
                .into_iter()
                .any(|defined| regs_overlap(defined, setup.dst))
        });
        if let Some(first_later_clobber) = first_later_clobber
            && aarch64_final_call_arg_all_clobbers_are_read(
                insts,
                first_later_clobber,
                call_pos,
                setup.dst,
            )
        {
            return Err(PipelineError::Aarch64CallArgRepair(format!(
                "function `{function_name}` final call at instruction {call_pos}: \
                 argument {:?} is clobbered after its final setup and that clobber \
                 is read before the call; exact argument value is ambiguous",
                setup.dst
            )));
        }
    }

    // Arguments with no explicit final setup rely on an already-resident value.
    // Apply the same fail-closed rule to both explicit and implicit definitions.
    for &arg_reg in call_args {
        if setups
            .iter()
            .any(|(_, setup)| regs_overlap(setup.dst, arg_reg))
        {
            continue;
        }
        let first_clobber = (region_start..call_pos).find(|&pos| {
            aarch64_inst_def_pregs(insts[pos])
                .into_iter()
                .any(|defined| regs_overlap(defined, arg_reg))
        });
        if let Some(first_clobber) = first_clobber
            && aarch64_final_call_arg_all_clobbers_are_read(insts, first_clobber, call_pos, arg_reg)
        {
            return Err(PipelineError::Aarch64CallArgRepair(format!(
                "function `{function_name}` final call at instruction {call_pos}: \
                 implicit argument {:?} is clobbered and that clobber is read before \
                 the call; exact argument value is ambiguous",
                arg_reg
            )));
        }
    }

    Ok(())
}

fn aarch64_final_call_arg_all_clobbers_are_read(
    insts: &[&IrMachInst],
    scan_start: usize,
    call_pos: usize,
    arg_reg: PReg,
) -> bool {
    for clobber_pos in scan_start..call_pos {
        if !aarch64_inst_def_pregs(insts[clobber_pos])
            .into_iter()
            .any(|defined| regs_overlap(defined, arg_reg))
        {
            continue;
        }
        if !insts[clobber_pos + 1..call_pos].iter().any(|later| {
            aarch64_inst_use_pregs(later)
                .into_iter()
                .any(|used| regs_overlap(used, arg_reg))
        }) {
            return false;
        }
    }
    true
}

fn aarch64_call_arg_sources_requiring_preserve(setups: &[Aarch64CallArgSetup]) -> Vec<PReg> {
    let mut preserve = Vec::new();

    for (idx, setup) in setups.iter().enumerate() {
        let source_clobbered_before_use = setups[..idx]
            .iter()
            .any(|previous| regs_overlap(previous.dst, setup.src));
        if source_clobbered_before_use && !preserve.contains(&setup.src) {
            preserve.push(setup.src);
        }
    }

    preserve
}

fn aarch64_call_arg_protected_regs(
    ir_func: &IrMachFunction,
    call_inst: &IrMachInst,
    setup_region: &[InstId],
) -> Vec<PReg> {
    let mut protected = Vec::new();

    for operand in &call_inst.operands {
        if let IrOperand::PReg(reg) = operand {
            push_unique_overlap(&mut protected, *reg);
        }
    }
    for &reg in call_inst.implicit_uses {
        push_unique_overlap(&mut protected, reg);
    }
    // Preserves are inserted before the first marked setup and remain live
    // until every rewritten setup has consumed them.  Protect every physical
    // read and write in that whole interval, including unmarked spill reloads,
    // frame materialization, and other sequential instructions interleaved
    // between marked setups.  Merely protecting setup operands lets an
    // interleaved `mov x9, ...` overwrite the saved value (or lets the preserve
    // itself clobber a transient x9 value before its read).
    for &inst_id in setup_region {
        for reg in aarch64_inst_def_pregs(ir_func.inst(inst_id))
            .into_iter()
            .chain(aarch64_inst_use_pregs(ir_func.inst(inst_id)))
        {
            push_unique_overlap(&mut protected, reg);
        }
    }

    protected
}

fn choose_aarch64_call_arg_scratch(
    source: PReg,
    protected: &[PReg],
    allocated_scratch: &[PReg],
) -> Option<PReg> {
    let candidates = aarch64_call_arg_scratch_candidates(source)?;
    candidates.into_iter().find(|&candidate| {
        !protected.iter().any(|&reg| regs_overlap(reg, candidate))
            && !allocated_scratch
                .iter()
                .any(|&reg| regs_overlap(reg, candidate))
    })
}

fn aarch64_call_arg_scratch_candidates(source: PReg) -> Option<Vec<PReg>> {
    let class = preg_class(source);
    let candidates = match class {
        RegClass::Gpr64 => (9..=17).map(PReg::new).collect(),
        RegClass::Gpr32 => (9..=17).map(|idx| PReg::new(idx + 32)).collect(),
        RegClass::Fpr128 => (16..=31).map(|idx| PReg::new(idx + 64)).collect(),
        RegClass::Fpr64 => (16..=31).map(|idx| PReg::new(idx + 96)).collect(),
        RegClass::Fpr32 => (16..=31).map(|idx| PReg::new(idx + 128)).collect(),
        RegClass::Fpr16 => (16..=31).map(|idx| PReg::new(idx + 165)).collect(),
        RegClass::Fpr8 => (16..=31).map(|idx| PReg::new(idx + 197)).collect(),
        RegClass::System => return None,
    };
    Some(candidates)
}

fn rewrite_aarch64_call_arg_setup_source(
    inst: &mut IrMachInst,
    kind: Aarch64CallArgSetupKind,
    scratch: PReg,
) {
    match kind {
        Aarch64CallArgSetupKind::Copy | Aarch64CallArgSetupKind::Uxtw => {
            if let Some(operand) = inst.operands.get_mut(1) {
                *operand = IrOperand::PReg(scratch);
            }
        }
    }
}

fn push_unique_overlap(regs: &mut Vec<PReg>, reg: PReg) {
    if !regs.iter().any(|&existing| regs_overlap(existing, reg)) {
        regs.push(reg);
    }
}

fn aarch64_formal_abi_source_regs(
    signature: &IrSignature,
    abi_variant: AArch64AbiVariant,
) -> Vec<PReg> {
    let lower_param_types: Vec<LowerType> = signature
        .params
        .iter()
        .map(lower_type_from_ir_type)
        .collect();
    let param_locs = AppleAArch64ABI::classify_params_with(abi_variant, &lower_param_types);

    let mut sources = Vec::new();
    for (loc, ty) in param_locs.iter().zip(lower_param_types.iter()) {
        for preg in aarch64_abi_location_pregs(loc, ty) {
            push_unique_overlap(&mut sources, preg);
        }
    }
    sources
}

fn aarch64_required_return_pregs(signature: &IrSignature) -> Vec<PReg> {
    let lower_return_types: Vec<LowerType> = signature
        .returns
        .iter()
        .map(lower_type_from_ir_type)
        .collect();
    AppleAArch64ABI::required_return_pregs(&lower_return_types)
}

fn aarch64_preg_alias_set(regs: &[PReg]) -> Vec<PReg> {
    let mut aliases = Vec::new();
    for &preg in regs {
        push_unique_overlap(&mut aliases, preg);
    }
    aliases
}

fn aarch64_preg_alias_sets_equal(left: &[PReg], right: &[PReg]) -> bool {
    let left = aarch64_preg_alias_set(left);
    let right = aarch64_preg_alias_set(right);
    left.len() == right.len()
        && left
            .iter()
            .all(|&expected| right.iter().any(|&actual| regs_overlap(expected, actual)))
}

/// The entry block's reads of incoming ABI argument registers: each formal
/// copy in the leading run of formal argument materializations, paired with
/// the ABI register it reads.
///
/// Callers select these on the function BEFORE register allocation.
/// `lower_formal_arguments` emits every formal materialization ahead of the
/// entry block's selected body. Before allocation the body computes into
/// virtual registers and names a physical register only at an ABI boundary
/// (a call-argument or return-value write, which ends the run, or a call
/// result read after the call ended it), so within the run an explicit
/// physical ABI-register source can only be the incoming argument. After
/// allocation the body's copies name physical registers too: a stack formal
/// loaded into a dead incoming register and then forwarded by a call-argument
/// setup or a block-argument copy (`ldr x1, [incoming]; mov x9, x1`) has the
/// shape of a formal read of X1 behind a load that clobbered it. The selection
/// is therefore carried across allocation by instruction id
/// ([`remap_aarch64_formal_reads`]).
fn aarch64_entry_formal_reads(
    ir_func: &IrMachFunction,
    abi_variant: AArch64AbiVariant,
) -> Vec<(InstId, PReg)> {
    let abi_sources = aarch64_formal_abi_source_regs(&ir_func.signature, abi_variant);
    if abi_sources.is_empty() {
        return Vec::new();
    }

    let Some(entry_block) = ir_func.blocks.get(ir_func.entry.0 as usize) else {
        return Vec::new();
    };

    let mut reads = Vec::new();
    for &inst_id in &entry_block.insts {
        let Some(inst) = ir_func.insts.get(inst_id.0 as usize) else {
            continue;
        };

        if inst.opcode == IrOpcode::Copy
            && let Some(IrOperand::PReg(src)) = inst.operands.get(1)
            && let Some(&source) = abi_sources
                .iter()
                .find(|&&source| regs_overlap(source, *src))
        {
            reads.push((inst_id, source));
            continue;
        }

        if inst.opcode == IrOpcode::LdrRI
            && matches!(inst.operands.get(2), Some(IrOperand::IncomingArg(_)))
        {
            continue;
        }

        break;
    }

    reads
}

/// Move formal reads selected on the pre-allocation function onto the
/// function `rebuild_ir_from_regalloc_with_map` produced. The regalloc adapter
/// converts the arena 1:1 and never compacts it, so a pre-allocation id is the
/// regalloc index `inst_map` is keyed by. A read whose instruction did not
/// survive the rebuild is dropped.
fn remap_aarch64_formal_reads(
    reads: &[(InstId, PReg)],
    inst_map: &[Option<InstId>],
) -> Vec<(InstId, PReg)> {
    reads
        .iter()
        .filter_map(|&(id, source)| {
            inst_map
                .get(id.0 as usize)
                .copied()
                .flatten()
                .map(|rebuilt| (rebuilt, source))
        })
        .collect()
}

/// The ABI registers of `formal_reads` that the allocated entry block still
/// reads at the selected instruction.
fn aarch64_entry_formal_abi_source_regs(
    ir_func: &IrMachFunction,
    formal_reads: &[(InstId, PReg)],
) -> Vec<PReg> {
    let Some(entry_block) = ir_func.blocks.get(ir_func.entry.0 as usize) else {
        return Vec::new();
    };

    let mut sources = Vec::new();
    for &inst_id in &entry_block.insts {
        let Some(inst) = ir_func.insts.get(inst_id.0 as usize) else {
            continue;
        };
        for &(read_id, source) in formal_reads {
            if read_id == inst_id
                && !aarch64_inst_reads_unread_formal_sources(inst, &[source]).is_empty()
            {
                push_unique_overlap(&mut sources, source);
            }
        }
    }

    sources
}

fn aarch64_abi_location_pregs(loc: &ArgLocation, ty: &LowerType) -> Vec<PReg> {
    match loc {
        ArgLocation::Reg(preg) => vec![*preg],
        ArgLocation::RegPair(lo_preg, hi_preg) => vec![*lo_preg, *hi_preg],
        ArgLocation::RegSequence(regs) => regs.clone(),
        ArgLocation::Indirect { ptr_reg } => {
            let mut regs = vec![*ptr_reg];
            if ty.is_aggregate() && ty.bytes() <= 16 {
                regs.push(PReg::new(ptr_reg.encoding() + 1));
            }
            regs
        }
        ArgLocation::Ignore | ArgLocation::Stack { .. } => Vec::new(),
    }
}

fn remove_overlapping_preg(regs: &mut Vec<PReg>, reg: PReg) {
    regs.retain(|&candidate| !regs_overlap(candidate, reg));
}

fn aarch64_inst_reads_unread_formal_sources(inst: &IrMachInst, unread: &[PReg]) -> Vec<PReg> {
    let (_, use_positions) = classify_operand_positions(inst);
    let mut reads = Vec::new();

    for pos in use_positions {
        let Some(IrOperand::PReg(preg)) = inst.operands.get(pos) else {
            continue;
        };
        for &source in unread {
            if regs_overlap(source, *preg) {
                push_unique_overlap(&mut reads, source);
            }
        }
    }

    reads
}

/// Refuse an allocated entry block that is a branch target and still
/// materializes a formal argument: a surviving formal read from
/// `formal_reads`, or an `IncomingArg` operand (only formal lowering emits
/// one).
///
/// The incoming ABI registers and stack slots hold the arguments only on
/// function entry. Formal materializations at the top of a block that a back
/// edge re-enters run again on every iteration and overwrite the block
/// arguments the edge wrote. Instruction selection places the formals of such
/// a function in a block of their own ahead of the re-entered one
/// (`lower_formal_arguments_before_reentered_entry`); this backstop refuses
/// any allocated function where that did not happen. The hazard walk in
/// [`verify_aarch64_formal_entry_copy_hazards`] follows the entry block once,
/// straight from function entry, so it relies on this.
fn verify_aarch64_formal_entry_not_re_entered(
    ir_func: &IrMachFunction,
    formal_reads: &[(InstId, PReg)],
) -> Result<(), PipelineError> {
    let entry = ir_func.entry;
    let Some(entry_block) = ir_func.blocks.get(entry.0 as usize) else {
        return Ok(());
    };
    let Some(&inst_id) = entry_block.insts.iter().find(|&&inst_id| {
        formal_reads.iter().any(|&(read, _)| read == inst_id)
            || ir_func.insts.get(inst_id.0 as usize).is_some_and(|inst| {
                inst.operands
                    .iter()
                    .any(|operand| matches!(operand, IrOperand::IncomingArg(_)))
            })
    }) else {
        return Ok(());
    };
    // The edges the branches state, as the pipeline's own CFG rebuilds derive
    // them; recorded `preds` may lag a rewrite.
    let mut preds = Vec::new();
    for (from, to) in derive_ir_cfg_edges_from_branch_operands(ir_func) {
        if to == entry && !preds.contains(&from) {
            preds.push(from);
        }
    }
    if preds.is_empty() {
        return Ok(());
    }
    let opcode = ir_func
        .insts
        .get(inst_id.0 as usize)
        .map(|inst| inst.opcode);
    Err(PipelineError::Aarch64FormalArgCopyHazard(format!(
        "function={} entry block {} is a branch target (predecessors {:?}) and re-runs formal \
         argument materialization inst={} opcode={:?}",
        ir_func.name,
        entry.0,
        preds.iter().map(|block| block.0).collect::<Vec<_>>(),
        inst_id.0,
        opcode
    )))
}

/// Refuse an allocated entry block that overwrites an incoming ABI argument
/// register before its formal read (`formal_reads`, from
/// [`aarch64_entry_formal_reads`] on the pre-allocation function) has read it,
/// or that a back edge re-enters while it materializes formals
/// ([`verify_aarch64_formal_entry_not_re_entered`]).
fn verify_aarch64_formal_entry_copy_hazards(
    ir_func: &IrMachFunction,
    formal_reads: &[(InstId, PReg)],
) -> Result<(), PipelineError> {
    verify_aarch64_formal_entry_not_re_entered(ir_func, formal_reads)?;
    let mut unread = aarch64_entry_formal_abi_source_regs(ir_func, formal_reads);
    if unread.is_empty() {
        return Ok(());
    }

    let Some(entry_block) = ir_func.blocks.get(ir_func.entry.0 as usize) else {
        return Ok(());
    };

    for &inst_id in &entry_block.insts {
        if unread.is_empty() {
            break;
        }

        let Some(inst) = ir_func.insts.get(inst_id.0 as usize) else {
            continue;
        };
        let reads = aarch64_inst_reads_unread_formal_sources(inst, &unread);
        let (def_positions, _) = classify_operand_positions(inst);

        for pos in def_positions {
            let Some(IrOperand::PReg(dst)) = inst.operands.get(pos) else {
                continue;
            };
            if let Some(&source) = unread.iter().find(|&&source| {
                regs_overlap(source, *dst) && !reads.iter().any(|&read| regs_overlap(read, source))
            }) {
                return Err(PipelineError::Aarch64FormalArgCopyHazard(format!(
                    "function={} inst={} opcode={:?} dst={} aliases unread ABI source {}",
                    ir_func.name,
                    inst_id.0,
                    inst.opcode,
                    preg_name(*dst),
                    preg_name(source)
                )));
            }
        }

        for read in reads {
            remove_overlapping_preg(&mut unread, read);
        }
    }

    Ok(())
}

/// Drop pure dead defs whose destination stayed virtual after regalloc.
///
/// Linear-scan omits dead values from the allocation map. That is fine for
/// liveness, but the encoder cannot accept a post-regalloc instruction with a
/// still-virtual destination. For pure instructions, an unallocated def means
/// the value is dead, so the instruction can be converted to pseudo-Nop.
pub fn eliminate_dead_unallocated_defs(ir_func: &mut IrMachFunction) {
    let impure_flags = trust_cg_ir::inst::InstFlags::HAS_SIDE_EFFECTS
        .union(trust_cg_ir::inst::InstFlags::READS_MEMORY)
        .union(trust_cg_ir::inst::InstFlags::WRITES_MEMORY)
        .union(trust_cg_ir::inst::InstFlags::IS_CALL)
        .union(trust_cg_ir::inst::InstFlags::IS_BRANCH)
        .union(trust_cg_ir::inst::InstFlags::IS_RETURN)
        .union(trust_cg_ir::inst::InstFlags::IS_TERMINATOR)
        .union(trust_cg_ir::inst::InstFlags::IS_PHI);

    for inst in &mut ir_func.insts {
        if inst.is_pseudo() || !inst.opcode.produces_value() || inst.operands.is_empty() {
            continue;
        }

        let has_unallocated_dst = matches!(inst.operands.first(), Some(IrOperand::VReg(_)));
        if !has_unallocated_dst || !inst.flags.intersection(impure_flags).is_empty() {
            continue;
        }

        inst.opcode = IrOpcode::Nop;
        inst.flags = trust_cg_ir::inst::InstFlags::IS_PSEUDO;
        inst.operands.clear();
    }
}

fn reachable_vreg_use_counts(ir_func: &IrMachFunction) -> HashMap<VReg, usize> {
    let mut use_counts = HashMap::new();

    for &block_id in &ir_func.block_order {
        let block = ir_func.block(block_id);
        for &inst_id in &block.insts {
            let inst = ir_func.inst(inst_id);
            let (_, use_positions) = classify_operand_positions(inst);
            for pos in use_positions {
                if let Some(IrOperand::VReg(vreg)) = inst.operands.get(pos) {
                    *use_counts.entry(*vreg).or_insert(0) += 1;
                }
            }
        }
    }

    use_counts
}

fn dead_def_discard_register(vreg: VReg) -> Option<PReg> {
    match vreg.class {
        RegClass::Gpr64 => Some(XZR),
        RegClass::Gpr32 | RegClass::System => Some(WZR),
        // AArch64 has no architectural FP/SIMD zero register. V16/V17 and
        // every width alias are deliberately excluded from the allocator and
        // reserved for post-RA scratch use (see aarch64_allocatable_regs and
        // scratch_pool_for_class). A dead side-effecting load can therefore
        // target the first reserved alias without clobbering an allocated
        // value. Its result has no uses, so its lifetime ends at the load.
        RegClass::Fpr16 => Some(H16),
        RegClass::Fpr32 => Some(S16),
        RegClass::Fpr64 => Some(D16),
        RegClass::Fpr128 => Some(V16),
        _ => None,
    }
}

/// Preserve side-effecting dead definitions whose destination stayed virtual.
///
/// The allocator may omit a dead value from both the allocation map and spill
/// metadata. Pure dead defs are removed by `eliminate_dead_unallocated_defs`,
/// but memory reads cannot be dropped without changing fault behavior. Binding
/// their unused destination to XZR/WZR (GPR) or a reserved V16 width alias
/// (FP/SIMD) preserves the read while avoiding a clobber of any live allocated
/// register.
pub fn bind_dead_unallocated_defs_to_discard_registers(
    ir_func: &mut IrMachFunction,
) -> Result<(), PipelineError> {
    let use_counts = reachable_vreg_use_counts(ir_func);
    let inst_ids: Vec<InstId> = ir_func
        .blocks
        .iter()
        .flat_map(|block| block.insts.iter().copied())
        .collect();

    for inst_id in inst_ids {
        let inst = ir_func.inst(inst_id);
        let (def_positions, _) = classify_operand_positions(inst);
        if !inst.opcode.produces_value() || def_positions.is_empty() {
            continue;
        }

        for def_pos in def_positions {
            let Some(IrOperand::VReg(vreg)) = ir_func.inst(inst_id).operands.get(def_pos) else {
                continue;
            };
            if use_counts.get(vreg).copied().unwrap_or(0) != 0 {
                continue;
            }

            let Some(discard) = dead_def_discard_register(*vreg) else {
                let inst = ir_func.inst(inst_id);
                return Err(PipelineError::RegAlloc(format!(
                    "cannot bind dead unallocated def for {:?} class {:?} in {:?}",
                    inst.opcode, vreg.class, inst
                )));
            };
            ir_func.inst_mut(inst_id).operands[def_pos] = IrOperand::PReg(discard);
        }
    }

    Ok(())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RegAllocDebugDef {
    VReg(VReg),
    PReg(PReg),
}

#[derive(Debug, Clone, Default)]
struct RegAllocDebugSnapshot {
    allocation: BTreeMap<VReg, PReg>,
    spilled_vregs: BTreeSet<VReg>,
    spill_slots: BTreeMap<VReg, StackSlotId>,
    spill_stores: Vec<SpillMaterializedStore>,
    inst_map: Vec<Option<InstId>>,
    defs: BTreeMap<InstId, RegAllocDebugDef>,
}

#[derive(Debug, Clone)]
struct RegAllocOutcome {
    spill_slot_count: usize,
    post_ra_copies_coalesced: u32,
    debug_snapshot: RegAllocDebugSnapshot,
}

fn collect_regalloc_debug_defs(ir_func: &IrMachFunction) -> BTreeMap<InstId, RegAllocDebugDef> {
    ir_func
        .insts
        .iter()
        .enumerate()
        .filter_map(|(idx, inst)| {
            let (def_positions, _) = classify_operand_positions(inst);
            let [def_pos] = def_positions.as_slice() else {
                return None;
            };
            match inst.operands.get(*def_pos) {
                Some(IrOperand::VReg(vreg)) => {
                    Some((InstId(idx as u32), RegAllocDebugDef::VReg(*vreg)))
                }
                Some(IrOperand::PReg(preg)) => {
                    Some((InstId(idx as u32), RegAllocDebugDef::PReg(*preg)))
                }
                _ => None,
            }
        })
        .collect()
}

// ---------------------------------------------------------------------------
// Encoding: IR MachFunction -> machine code bytes
// ---------------------------------------------------------------------------

/// Resolve symbolic block references in branch instructions to byte offsets.
///
/// After register allocation and frame lowering, branch instructions may still
/// contain `Block(BlockId)` operands from the ISel. This pass computes the byte
/// offset of each block in the final layout and replaces Block operands with
/// immediate offsets (PC-relative, in instruction units).
///
/// Must be called after frame lowering (which may add instructions) and before
/// encoding (which needs concrete offsets).
///
/// A conditional branch whose target lies outside its encoding range
/// (`B.cond`/`CBZ`/`CBNZ` +/-1 MiB, `TBZ`/`TBNZ` +/-32 KiB) is first relaxed
/// in place by [`crate::relax::relax_out_of_range_branches`]; a function with
/// no such branch is resolved exactly as before.
pub fn resolve_branches(func: &mut IrMachFunction) -> Result<(), PipelineError> {
    validate_aarch64_mach_function(func)?;
    relax_aarch64_branches_and_local_addresses(func)?;
    resolve_branches_after_validation(func);
    Ok(())
}

/// Greppable tag for a branch-relaxation refusal.
pub const AARCH64_BRANCH_RELAX_TAG: &str = "[TCG-A64-BRANCH-RELAX]";

/// [`crate::relax::relax_out_of_range_branches`] as a pipeline step. Runs on
/// a validated function whose layout is final, before branch resolution.
fn relax_aarch64_out_of_range_branches(func: &mut IrMachFunction) -> Result<(), PipelineError> {
    crate::relax::relax_out_of_range_branches(func)
        .map(|_| ())
        .map_err(|error| {
            PipelineError::Encoding(format!(
                "{AARCH64_BRANCH_RELAX_TAG} fn `{}`: {error}",
                func.name
            ))
        })
}

/// X-OPCODES-P6: decide that `machine`, the final AArch64 stream prepared
/// from `source`, performs the same volatile accesses on every path (see
/// `trust_cg_verify::volatile_access_preservation` for the exact claim).
/// A violation, an unsized access or an undecidable (over-bound) pair fails
/// closed with [`PipelineError::VolatileAccessNotPreserved`].
pub(crate) fn check_aarch64_volatile_access_preservation(
    source: &trust_cg_lower::Function,
    machine: &IrMachFunction,
) -> Result<trust_cg_verify::volatile_access_preservation::VolatileTraceCertificate, PipelineError>
{
    use trust_cg_verify::volatile_access_preservation as vap;
    let reject = |detail: String| PipelineError::VolatileAccessNotPreserved {
        function: machine.name.clone(),
        detail,
    };
    let source_trace = vap::lir_volatile_trace(source).map_err(|e| reject(e.to_string()))?;
    let machine_trace = vap::aarch64_volatile_trace(machine).map_err(|e| reject(e.to_string()))?;
    match vap::check_volatile_trace_preservation(&source_trace, &machine_trace)
        .map_err(|e| reject(e.to_string()))?
    {
        vap::VolatileTraceOutcome::Preserved(certificate) => Ok(certificate),
        vap::VolatileTraceOutcome::Violated(violation) => Err(reject(violation.to_string())),
    }
}

/// Resolve branches after the public symbolic CFG authority boundary has
/// already passed and post-RA guard expansion may have inserted validated
/// intra-block immediate skip branches.
///
/// This is the final-emission entry: `block_order` and the instruction
/// stream are FINAL here, so it is also the single point where the loop-head
/// alignment pass, when opted in, inserts its `AlignNop` padding —
/// immediately BEFORE the offsets are computed, so every resolved
/// displacement already includes the padding. The pass is OFF by default
/// (opt-in `a64-loop-head-align` / `TCG_LOOP_HEAD_ALIGN=1`; see
/// [`crate::loop_align`]).
///
/// Branch relaxation runs on both sides of that padding: first, so the
/// alignment pass measures the code it will pad; again after it, because
/// padding can push a branch that was just in range out of it. Each run is a
/// no-op on a function with no out-of-range branch.
fn resolve_branches_after_authority(func: &mut IrMachFunction) -> Result<(), PipelineError> {
    // L10-P5: frame lowering, guard and LL/SC expansion and branch layout
    // allocate instructions, blocks and slots; relaxation below does too.
    admit_mach_ids(func, "branch resolution entry")?;
    validate_aarch64_mach_function_totality(func)?;
    relax_aarch64_out_of_range_branches(func)?;
    crate::loop_align::align_innermost_loop_heads_if_enabled(func);
    relax_aarch64_branches_and_local_addresses(func)?;
    resolve_branches_after_validation(func);
    Ok(())
}

/// The public resolver and production final-emission path use the same
/// instruction-growth fixed point before replacing symbolic branch targets.
fn relax_aarch64_branches_and_local_addresses(
    func: &mut IrMachFunction,
) -> Result<(), PipelineError> {
    // Address growth can push a branch (or another ADR) over its range.
    // Each growth round expands at least one original address once; no
    // source instruction is removed, so the original arena size bounds it.
    let mut remaining = func.insts.len();
    loop {
        relax_aarch64_out_of_range_branches(func)?;
        if !crate::aarch64::jump_table_address::expand(func)? {
            break;
        }
        remaining = remaining.checked_sub(1).ok_or_else(|| {
            PipelineError::Encoding("[TCG-A64-LOCAL-ADDRESS] layout growth did not converge".into())
        })?;
    }
    crate::aarch64::jump_table_address::refresh(func)?;
    Ok(())
}

fn resolve_branches_after_validation(func: &mut IrMachFunction) {
    // Phase 1: Compute the instruction-index offset of each block.
    // Walk blocks in layout order, counting non-pseudo instructions.
    let mut block_offsets: HashMap<BlockId, i64> = HashMap::new();
    let mut current_offset: i64 = 0;

    for &block_id in &func.block_order {
        block_offsets.insert(block_id, current_offset);
        let block = &func.blocks[block_id.0 as usize];
        for &inst_id in &block.insts {
            let inst = &func.insts[inst_id.0 as usize];
            if !inst.is_pseudo() {
                current_offset += 1; // Each instruction is 4 bytes = 1 instruction unit
            }
        }
    }

    // Phase 2: Walk all instructions and replace Block operands with offsets.
    // For each branch instruction, find the Block operand, look up its offset,
    // and replace it with the PC-relative offset (in instruction units).
    let mut inst_offset: i64 = 0;
    for &block_id in &func.block_order.clone() {
        let block = &func.blocks[block_id.0 as usize];
        let inst_ids: Vec<_> = block.insts.clone();
        for &inst_id in &inst_ids {
            let inst = &func.insts[inst_id.0 as usize];
            if inst.is_pseudo() {
                continue;
            }

            let is_branch = matches!(
                inst.opcode,
                IrOpcode::B
                    | IrOpcode::TailCall
                    | IrOpcode::BCond
                    | IrOpcode::Cbz
                    | IrOpcode::Cbnz
                    | IrOpcode::Tbz
                    | IrOpcode::Tbnz
            );

            if is_branch {
                // Find and resolve Block operands to PC-relative immediates.
                let new_operands: Vec<IrOperand> = inst
                    .operands
                    .iter()
                    .map(|op| {
                        if let IrOperand::Block(target_block) = op {
                            if let Some(&target_offset) = block_offsets.get(target_block) {
                                // PC-relative offset in instruction units
                                let rel_offset = target_offset - inst_offset;
                                IrOperand::Imm(rel_offset)
                            } else {
                                op.clone()
                            }
                        } else {
                            op.clone()
                        }
                    })
                    .collect();
                func.insts[inst_id.0 as usize].operands = new_operands;
            }

            inst_offset += 1;
        }
    }
}

/// Encode a single IR instruction into AArch64 machine code.
///
/// Delegates to the unified encoder in [`crate::aarch64::encode`] which
/// dispatches to the correct format-specific encoding function.
fn encode_ir_inst(inst: &IrMachInst) -> Result<u32, PipelineError> {
    crate::aarch64::encode::encode_instruction(inst)
        .map_err(|e| PipelineError::Encoding(e.to_string()))
}

/// Reject public code/fixup-only AArch64 boundaries that cannot return the
/// exact LSDA/personality/FDE sidecar. The EH-aware single/module object paths
/// call the private block-tracking encoder core directly and retain that data.
fn reject_aarch64_eh_sidecar_drop(
    func: &IrMachFunction,
    api: &'static str,
) -> Result<(), PipelineError> {
    // Preserve the stronger malformed-function diagnostic when the machine IR
    // is invalid; the sidecar guard is about valid EH input losing authority.
    validate_aarch64_mach_function_totality(func)?;
    if !func.eh_metadata.has_eh_info() {
        return Ok(());
    }
    Err(PipelineError::EhSidecarUnsupported {
        function: func.name.clone(),
        api,
        reason: "the return type carries only code/fixups and cannot return the exact LSDA, personality, and unwind-frame metadata; use an EH-aware object/module API instead (fail-closed)"
            .to_string(),
    })
}

/// Encode all instructions in a function to machine code bytes.
///
/// Walks blocks in layout order, encoding each non-pseudo instruction.
pub fn encode_function(func: &IrMachFunction) -> Result<Vec<u8>, PipelineError> {
    reject_aarch64_eh_sidecar_drop(func, "encode_function")?;
    let (code, _fixups, _block_offsets) = encode_function_with_fixups_and_blocks_impl(func, None)?;
    Ok(code)
}

/// Encode all instructions in a function to machine code bytes, collecting
/// fixups for cross-function references.
///
/// When a BL/B instruction has a [`Symbol`](IrOperand::Symbol) operand instead
/// of an immediate, the encoder emits a placeholder (`BL 0`) and records a
/// [`Fixup`](crate::macho::fixup::Fixup) with a `Branch26` relocation kind.
/// The caller (typically [`Pipeline::compile_module`]) resolves these fixups
/// into relocations for the linker.
///
/// Returns `(code_bytes, fixup_list)`.
pub fn encode_function_with_fixups(
    func: &IrMachFunction,
) -> Result<(Vec<u8>, crate::macho::fixup::FixupList), PipelineError> {
    encode_function_with_fixups_under(func, Aarch64IntegrityPolicy::Compatibility)
}

/// [`encode_function_with_fixups`] under an explicit integrity policy. A
/// proof-grade policy forces every final-stream net to Enforce and refuses
/// ambient late-layout controls; neither can be downgraded by environment.
fn encode_function_with_fixups_under(
    func: &IrMachFunction,
    integrity_policy: Aarch64IntegrityPolicy,
) -> Result<(Vec<u8>, crate::macho::fixup::FixupList), PipelineError> {
    reject_aarch64_eh_sidecar_drop(func, "encode_function_with_fixups")?;
    let (code, fixups, _block_offsets) =
        encode_function_with_fixups_and_blocks_impl_with_sites(func, None, None, integrity_policy)
            .map_err(|err| match err {
                PipelineError::Encoding(msg) => {
                    PipelineError::Encoding(format!("[encode_function_with_fixups] {msg}"))
                }
                other => other,
            })?;
    Ok((code, fixups))
}

/// Policy-aware raw JIT entry: the JIT encodes through its own pipeline's
/// integrity policy, which a verifying configuration makes proof-grade.
// The raw JIT encodes through the `_prechecked` variant; tests drive this form.
#[cfg_attr(not(test), allow(dead_code))]
pub(crate) fn encode_function_with_fixups_for_pipeline(
    pipeline: &Pipeline,
    func: &IrMachFunction,
) -> Result<(Vec<u8>, crate::macho::fixup::FixupList), PipelineError> {
    encode_function_with_fixups_under(func, pipeline.aarch64_integrity_policy)
}

/// [`encode_function_with_fixups_for_pipeline`] for a function that may carry
/// the final-stream check it passed in preparation (see
/// [`encode_function_with_fixups_and_blocks_impl_prechecked`]).
pub(crate) fn encode_function_with_fixups_for_pipeline_prechecked(
    pipeline: &Pipeline,
    func: &IrMachFunction,
    prechecked: Option<Aarch64FinalStreamCheck>,
) -> Result<(Vec<u8>, crate::macho::fixup::FixupList), PipelineError> {
    reject_aarch64_eh_sidecar_drop(func, "encode_function_with_fixups")?;
    let (code, fixups, _block_offsets) = encode_function_with_fixups_and_blocks_impl_prechecked(
        func,
        None,
        None,
        pipeline.aarch64_integrity_policy,
        prechecked,
    )
    .map_err(|err| match err {
        PipelineError::Encoding(msg) => {
            PipelineError::Encoding(format!("[encode_function_with_fixups] {msg}"))
        }
        other => other,
    })?;
    Ok((code, fixups))
}

/// Block-offset variant of [`encode_function_with_fixups_for_pipeline`].
///
/// Its production callers are the AArch64 raw-JIT paths, which are
/// `cfg(target_arch = "aarch64")`; the final-layout cross-check tests call it
/// on every host. Gated the same way so an x86-64 host build — where the
/// workspace's `-D warnings` turns an unused function into an error — does
/// not fail on a function it can never reach.
#[cfg(any(target_arch = "aarch64", test))]
pub(crate) fn encode_function_with_fixups_and_blocks_for_pipeline(
    pipeline: &Pipeline,
    func: &IrMachFunction,
) -> Result<
    (
        Vec<u8>,
        crate::macho::fixup::FixupList,
        HashMap<BlockId, u32>,
    ),
    PipelineError,
> {
    reject_aarch64_eh_sidecar_drop(func, "encode_function_with_fixups_and_blocks")?;
    encode_function_with_fixups_and_blocks_impl_with_sites(
        func,
        None,
        None,
        pipeline.aarch64_integrity_policy,
    )
}

/// Exact machine-instruction site that caused one symbolic AArch64 fixup.
///
/// This is deliberately an encoder-produced sidecar rather than a second walk
/// that guesses which instruction corresponds to a returned byte offset.  The
/// policy-qualified Core compiler uses it to bind every retained fixup back to
/// the final MachIR instruction and, through that instruction's lowering
/// provenance, to one exact LIR call occurrence.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct EncodedAarch64FixupSite {
    pub(crate) fixup_index: usize,
    pub(crate) block: BlockId,
    pub(crate) inst: InstId,
    pub(crate) offset: u32,
    pub(crate) opcode: IrOpcode,
    pub(crate) placeholder_word: u32,
}

/// The composed transition record's own check encode (L09-P3,
/// [`crate::composed_transition`]): the proof-grade encoder, which runs what
/// the record's encoding link claims (ENC-5 enforced with undecoded words
/// refused, the CFG-bound final-layout cross-check, the switch-dispatch
/// binding and the trap-expansion check), returning the code and its symbolic
/// fixup count. The final-stream structural nets (the post-RA recheck, the
/// reaching-definition and frame nets) are not part of that claim and already
/// ran on this stream in preparation, so this encode does not run them a
/// second time: their counters describe each preparation once. Its caller
/// runs it under [`crate::decode_check::without_telemetry`] for the same
/// reason: the ENC-5 counters and the decode census count the route's own
/// encode of the function, not this re-check.
pub(crate) fn encode_for_composed_transition(
    func: &IrMachFunction,
) -> Result<(Vec<u8>, usize), PipelineError> {
    reject_aarch64_eh_sidecar_drop(func, "encode_for_composed_transition")?;
    let (code, fixups, _block_offsets) = encode_function_with_fixups_and_blocks_impl_prechecked(
        func,
        None,
        None,
        Aarch64IntegrityPolicy::ProofGradeEnforce,
        Some(Aarch64FinalStreamCheck::resolve(
            Aarch64IntegrityPolicy::ProofGradeEnforce,
        )),
    )?;
    Ok((code, fixups.len()))
}

/// Encode a function while retaining the exact originating instruction for
/// every symbolic fixup.
///
/// Kept crate-private because the sidecar is a proof-boundary primitive for
/// the closed Core compiler, not a general relocation API or authority token.
#[cfg_attr(not(feature = "verify"), allow(dead_code))]
pub(crate) fn encode_function_with_fixups_and_sites(
    func: &IrMachFunction,
) -> Result<
    (
        Vec<u8>,
        crate::macho::fixup::FixupList,
        Vec<EncodedAarch64FixupSite>,
    ),
    PipelineError,
> {
    reject_aarch64_eh_sidecar_drop(func, "encode_function_with_fixups_and_sites")?;
    let mut sites = Vec::new();
    let (code, fixups, _block_offsets) = encode_function_with_fixups_and_blocks_impl_with_sites(
        func,
        None,
        Some(&mut sites),
        Aarch64IntegrityPolicy::ProofGradeEnforce,
    )
    .map_err(|err| match err {
        PipelineError::Encoding(msg) => {
            PipelineError::Encoding(format!("[encode_function_with_fixups_and_sites] {msg}"))
        }
        other => other,
    })?;
    if sites.len() != fixups.len() {
        return Err(PipelineError::Encoding(format!(
            "function {} encoded {} symbolic fixups but retained {} originating sites",
            func.name,
            fixups.len(),
            sites.len()
        )));
    }
    Ok((code, fixups, sites))
}

fn encode_module_function_with_fixups(
    func: &IrMachFunction,
    integrity_policy: Aarch64IntegrityPolicy,
) -> Result<(Vec<u8>, crate::macho::fixup::FixupList), PipelineError> {
    validate_aarch64_mach_function_totality(func)?;
    if let Some(cleaned) = rbit_return_prefix_copy_cleaned(func) {
        encode_function_with_fixups_under(&cleaned, integrity_policy)
    } else {
        encode_function_with_fixups_under(func, integrity_policy)
    }
}

/// Per-function exception-handling payload collected by the generic module
/// emitters during Phase-1 encoding, consumed by
/// [`Pipeline::emit_module_macho_with_unwind`].
struct ModuleFunctionEhData {
    /// Encoded code length in bytes (the compact-unwind / FDE range).
    code_len: u32,
    /// The resolved LSDA image and personality of a function carrying EH
    /// structure.
    lsda: Option<FunctionLsda>,
}

/// An EH function's resolved LSDA image and personality routine.
#[derive(Debug, Clone)]
struct FunctionLsda {
    /// LSDA bytes plus the typeinfo slots the object emitter must relocate.
    image: crate::exception_handling::LsdaImage,
    /// Personality routine as the frontend named it (see
    /// [`FunctionLsda::canonical_personality`]).
    personality: String,
}

impl FunctionLsda {
    /// Linker-level personality spelling (legacy Rust aliases normalized).
    fn canonical_personality(&self) -> &str {
        crate::exception_handling::canonical_personality_symbol(&self.personality)
    }
}

/// Whole-module unwind emission plan (sections + symbols created, relocations
/// pending until the symbol table is final).
struct ModuleUnwindPlan {
    /// Undefined `_<personality>` symbol id per personality routine an EH
    /// function names (canonical spelling -> id). Empty for a module with no
    /// EH function: its unwind entries describe frames only (walk-through),
    /// no pad ever dispatches, and adding an undefined personality would
    /// force every plain-C link to pull in a C++/Rust EH runtime it never
    /// calls. A module mixing `__gxx_personality_v0` and
    /// `rust_eh_personality` binds each function's entry to its own routine.
    personality_symbols: BTreeMap<String, crate::macho::SymbolId>,
    /// Per-function canonical personality (`None` for a non-EH function).
    personalities: Vec<Option<String>>,
    /// Per-function `_GCC_except_table_*` symbol id (real or filler LSDA).
    lsda_symbols: Vec<Option<crate::macho::SymbolId>>,
    /// 0-based `__gcc_except_tab` section index, once any LSDA is laid out.
    lsda_section: Option<usize>,
    /// Per-function byte offset of its LSDA within `__gcc_except_tab`.
    lsda_offsets: Vec<Option<u32>>,
    /// Distinct linker-level typeinfo symbols the LSDAs relocate against.
    /// The module symbol pass registers each as an undefined external (or
    /// resolves it to an in-module definition) before any final index is
    /// read.
    typeinfo_symbols: BTreeSet<String>,
    /// Per-function compact unwind encoding (from its frame layout).
    encodings: Vec<crate::frame::CompactUnwindEncoding>,
    /// DWARF-fallback FDE context, when any function needs it.
    dwarf: Option<ModuleUnwindDwarf>,
}

/// `__eh_frame` emission context for DWARF-fallback functions in a module.
struct ModuleUnwindDwarf {
    /// 0-based `__eh_frame` section index.
    eh_frame_section: usize,
    /// Local `EH_Frame` symbol id (subtractor base).
    eh_frame_symbol: crate::macho::SymbolId,
    /// CIE groups in section order: one zPLR CIE per personality named by a
    /// DWARF-fallback EH function, or a single zR CIE when no such function
    /// exists. Every FDE lives under the CIE of its function's personality.
    groups: Vec<ModuleUnwindDwarfGroup>,
}

/// One CIE and the FDEs under it within the module's `__eh_frame`.
struct ModuleUnwindDwarfGroup {
    /// The CIE+FDE builder (for group-relative relocation offset queries).
    cfi: crate::dwarf_cfi::DwarfCfiSection,
    /// Byte offset of this group's CIE within `__eh_frame`.
    base: u32,
    /// The canonical personality this group's zPLR CIE names; `None` for the
    /// zR walk-through CIE.
    personality: Option<String>,
    /// For each FDE (in add order), the index of its function.
    fde_functions: Vec<usize>,
}

/// Encode one function for the generic module emitters.
///
/// Non-EH functions take the exact pre-existing
/// [`encode_module_function_with_fixups`] path (byte-identical output). EH
/// functions take the block-tracking encode path so the post-layout LSDA
/// call-site/landing-pad byte offsets can be resolved (mirroring the proven
/// single-function `compile_function` sequence), returning the generated LSDA
/// bytes + personality alongside the code.
fn encode_module_function_with_fixups_and_eh(
    func: &IrMachFunction,
    integrity_policy: Aarch64IntegrityPolicy,
    eh_propagation: &EhPropagation,
) -> Result<
    (
        Vec<u8>,
        crate::macho::fixup::FixupList,
        Option<FunctionLsda>,
    ),
    PipelineError,
> {
    if !func.eh_metadata.has_eh_info() {
        let (code, fixups) = encode_module_function_with_fixups(func, integrity_policy)?;
        return Ok((code, fixups, None));
    }

    // EH functions need block byte offsets to resolve the LSDA call-site table
    // + landing-pad offsets. `resolve_eh_offsets` mutates the EH metadata, so
    // work on a clone (the module emitters borrow their inputs). The rbit
    // prefix-copy cleanup only applies to single-block functions and EH
    // functions always have >= 2 blocks, so skipping it here cannot change the
    // emitted bytes.
    let mut resolved = func.clone();
    let (code, fixups, block_offsets) = encode_function_with_fixups_and_blocks_impl_with_sites(
        &resolved,
        None,
        None,
        integrity_policy,
    )?;
    resolve_eh_offsets_with_propagation(&mut resolved, &block_offsets, code.len(), eh_propagation)?;
    let lsda = generate_lsda_for_function(&resolved)?.ok_or_else(|| {
        PipelineError::Unwind(format!(
            "EH function `{}` produced no LSDA despite carrying EH metadata",
            func.name
        ))
    })?;
    let personality = crate::exception_handling::required_personality_symbol(
        resolved.eh_metadata.personality.as_deref(),
    )
    .map_err(|error| PipelineError::MalformedAarch64Eh {
        function: resolved.name.clone(),
        detail: format!("invalid exception-handling personality: {error}"),
    })?
    .to_string();
    Ok((
        code,
        fixups,
        Some(FunctionLsda {
            image: lsda,
            personality,
        }),
    ))
}

/// EH-aware encoding for the in-memory JIT's unwind tables.
///
/// Returns the code, its fixups, the function's resolved LSDA image and its
/// canonical personality. The caller must publish the LSDA with an FDE that
/// covers exactly these code bytes and must bind (or refuse by name) every
/// typeinfo relocation the image carries; this sidecar is never dropped
/// silently.
pub(crate) fn encode_function_with_fixups_and_eh_sidecar(
    pipeline: &Pipeline,
    func: &IrMachFunction,
) -> Result<
    (
        Vec<u8>,
        crate::macho::fixup::FixupList,
        crate::exception_handling::LsdaImage,
        String,
    ),
    PipelineError,
> {
    validate_aarch64_mach_function_totality(func)?;
    if !func.eh_metadata.has_eh_info() {
        return Err(PipelineError::MalformedAarch64Function {
            function: func.name.clone(),
            detail: "EH sidecar encoding requested for a function without EH metadata".to_owned(),
        });
    }
    // The JIT's EH functions take the same final-layout integrity policy as
    // its plain functions (`encode_function_with_fixups_for_pipeline`).
    let (code, fixups, eh) = encode_module_function_with_fixups_and_eh(
        func,
        pipeline.aarch64_integrity_policy,
        &pipeline.eh_propagation,
    )?;
    let FunctionLsda { image, personality } =
        eh.ok_or_else(|| PipelineError::MalformedAarch64Function {
            function: func.name.clone(),
            detail: "EH function produced no LSDA sidecar".to_owned(),
        })?;
    Ok((
        code,
        fixups,
        image,
        crate::exception_handling::canonical_personality_symbol(&personality).to_owned(),
    ))
}

fn rbit_return_prefix_copy_cleaned(func: &IrMachFunction) -> Option<IrMachFunction> {
    if func.block_order.len() != 1 {
        return None;
    }

    let block_id = *func.block_order.first()?;
    let block = func.block(block_id);
    let mut idx = 0;
    while idx + 2 < block.insts.len() {
        let copy_id = block.insts[idx];
        let rbit_id = block.insts[idx + 1];
        let ret_id = block.insts[idx + 2];
        if is_redundant_rbit_return_prefix_copy(
            func.inst(copy_id),
            func.inst(rbit_id),
            func.inst(ret_id),
        ) {
            let mut cleaned = func.clone();
            cleaned.blocks[block_id.0 as usize].insts.remove(idx);
            return Some(cleaned);
        }
        idx += 1;
    }

    None
}

fn is_redundant_rbit_return_prefix_copy(
    copy: &IrMachInst,
    rbit: &IrMachInst,
    ret: &IrMachInst,
) -> bool {
    matches!(
        copy.opcode,
        IrOpcode::MovR | IrOpcode::MOVWrr | IrOpcode::MOVXrr
    ) && rbit.opcode == IrOpcode::Rbit
        && ret.is_return()
        && copy.operands.len() >= 2
        && rbit.operands.len() >= 2
        && copy.implicit_defs.is_empty()
        && copy.implicit_uses.is_empty()
        && rbit.operands.first().and_then(IrOperand::as_preg)
            == rbit.operands.get(1).and_then(IrOperand::as_preg)
        && rbit
            .operands
            .first()
            .and_then(IrOperand::as_preg)
            .is_some_and(|rbit_reg| preg_class(rbit_reg) == RegClass::Gpr32)
        && copy
            .operands
            .first()
            .and_then(IrOperand::as_preg)
            .zip(copy.operands.get(1).and_then(IrOperand::as_preg))
            .zip(rbit.operands.first().and_then(IrOperand::as_preg))
            .is_some_and(|((copy_dst, copy_src), rbit_reg)| {
                hw_encoding(copy_dst) == hw_encoding(copy_src)
                    && hw_encoding(copy_src) == hw_encoding(rbit_reg)
            })
}

/// Like [`encode_function_with_fixups_and_blocks`] but also records the final
/// byte offset of each emitted non-pseudo instruction in `provenance`.
pub fn encode_function_with_fixups_and_blocks_with_provenance(
    func: &IrMachFunction,
    provenance: &mut trust_cg_ir::ProvenanceMap,
) -> Result<
    (
        Vec<u8>,
        crate::macho::fixup::FixupList,
        HashMap<BlockId, u32>,
    ),
    PipelineError,
> {
    reject_aarch64_eh_sidecar_drop(
        func,
        "encode_function_with_fixups_and_blocks_with_provenance",
    )?;
    encode_function_with_fixups_and_blocks_impl(func, Some(provenance))
}

/// Like [`encode_function_with_fixups`] but also returns the byte offset at
/// which each basic block begins in the encoded code.
///
/// Used by the JIT's block-level profile hook path (`ProfileHookMode::
/// BlockCounts`, issue #364) to know where to splice per-block trampolines.
/// The returned offsets are the **pre-trampoline** offsets — i.e. where each
/// block's first instruction lives in the plain encoding. The caller is
/// responsible for shifting these offsets when inserting trampolines and for
/// re-patching any branches whose source/target block spacing changes.
pub fn encode_function_with_fixups_and_blocks(
    func: &IrMachFunction,
) -> Result<
    (
        Vec<u8>,
        crate::macho::fixup::FixupList,
        HashMap<BlockId, u32>,
    ),
    PipelineError,
> {
    reject_aarch64_eh_sidecar_drop(func, "encode_function_with_fixups_and_blocks")?;
    encode_function_with_fixups_and_blocks_impl(func, None)
}

#[derive(Debug, Clone, Copy)]
struct SymbolicAArch64FixupKind {
    kind: crate::macho::AArch64RelocKind,
    tls_model: Option<trust_cg_ir::TlsModel>,
}

/// Does `inst` (post-regalloc) write physical register `preg` — via an
/// explicit def-position operand or an implicit clobber (call defs)?
fn inst_writes_preg(inst: &trust_cg_ir::MachInst, preg: PReg) -> bool {
    if inst.implicit_defs.contains(&preg) {
        return true;
    }
    let mut writes = false;
    trust_cg_opt::effects::aarch64_for_each_def_position(inst.opcode, inst.operands.len(), |pos| {
        if inst.operands.get(pos).and_then(|op| op.as_preg()) == Some(preg) {
            writes = true;
        }
    });
    writes
}

/// Find the GOT/TLVP consumer that pairs a symbolic `ADRP dst, @sym`, scanning
/// FORWARD through the block along `dst`'s dataflow.
///
/// The consumer (`LdrGot`/`LdrTlvp` with base == `dst` and the same symbol) is
/// emitted adjacent to its ADRP by ISel, but the SCHEDULER may legally sink
/// unrelated instructions between them. The historical version of this scan
/// inspected only the IMMEDIATELY next non-pseudo instruction, so a scheduled
/// gap made the ADRP fall back to a DIRECT `PAGE21` while the distant LDR
/// still emitted `GOT_LOAD_PAGEOFF12` — a MIXED pair computing
/// `page(sym) + lo12(got_slot_of_sym)`, i.e. a wild load (the wp10-on-Linux
/// `std::panicking::set_hook` HOOK-pointer null-deref class; on Darwin the
/// same mix was masked by ld64's GOT-load relaxation for locally-defined
/// symbols, and on ELF by page-layout coincidence until the layout shifted).
///
/// The scan stops (no pairing) as soon as anything else writes `dst`: past
/// that point the ADRP's page value is dead, so a later `LdrGot` of the same
/// register belongs to a different ADRP.
fn paired_symbolic_adrp_reloc_kind(
    func: &IrMachFunction,
    block_insts: &[InstId],
    inst_index: usize,
    adrp_dst: PReg,
    symbol: &str,
) -> Option<SymbolicAArch64FixupKind> {
    for &next_id in block_insts.iter().skip(inst_index + 1) {
        let next = func.inst(next_id);
        if next.is_pseudo() {
            continue;
        }

        if matches!(
            next.opcode,
            IrOpcode::LdrGot | IrOpcode::LdrTlvp | IrOpcode::LdrGottprel | IrOpcode::LdrTlsdesc
        ) {
            let base_matches = next.operands.get(1).and_then(|op| op.as_preg()) == Some(adrp_dst);
            let symbol_matches = next.operands.get(2).and_then(|op| op.as_symbol()) == Some(symbol);
            if base_matches && symbol_matches {
                return Some(match next.opcode {
                    IrOpcode::LdrGot => SymbolicAArch64FixupKind {
                        kind: crate::macho::AArch64RelocKind::GotLoadPage21,
                        tls_model: None,
                    },
                    IrOpcode::LdrTlvp => SymbolicAArch64FixupKind {
                        kind: crate::macho::AArch64RelocKind::TlvpLoadPage21,
                        tls_model: Some(trust_cg_ir::TlsModel::Tlv),
                    },
                    IrOpcode::LdrGottprel => SymbolicAArch64FixupKind {
                        kind: crate::macho::AArch64RelocKind::ElfTlsieAdrGottprelPage21,
                        tls_model: Some(trust_cg_ir::TlsModel::InitialExec),
                    },
                    IrOpcode::LdrTlsdesc => SymbolicAArch64FixupKind {
                        kind: crate::macho::AArch64RelocKind::ElfTlsdescAdrPage21,
                        tls_model: Some(trust_cg_ir::TlsModel::GeneralDynamic),
                    },
                    _ => unreachable!(),
                });
            }
        }

        if inst_writes_preg(next, adrp_dst) {
            return None;
        }
    }

    None
}

/// Fail-closed pairing check for the LDR side of a GOT/TLVP sequence: scan
/// BACKWARD from the `LdrGot`/`LdrTlvp` at `inst_index` for the `ADRP` that
/// produces its base register, and require it to name the SAME symbol. If the
/// base register's def is not such an ADRP (or lies outside this block — e.g.
/// hoisted by a pass), the object would carry a GOT/TLVP page-offset
/// relocation whose page half is missing or direct: a silent wild load.
/// Reject the compile instead.
fn ldr_got_has_pairing_adrp(
    func: &IrMachFunction,
    block_insts: &[InstId],
    inst_index: usize,
    base: PReg,
    symbol: &str,
) -> bool {
    for &prev_id in block_insts.iter().take(inst_index).rev() {
        let prev = func.inst(prev_id);
        if prev.is_pseudo() {
            continue;
        }
        if prev.opcode == IrOpcode::Adrp
            && prev.operands.first().and_then(|op| op.as_preg()) == Some(base)
        {
            return prev.operands.get(1).and_then(|op| op.as_symbol()) == Some(symbol);
        }
        if inst_writes_preg(prev, base) {
            return false;
        }
    }
    false
}

/// Physical registers the AArch64 TLSDESC ABI fixes: x0 carries the descriptor
/// address in and the TP-relative offset out, x1 the resolver.
const TLSDESC_CALL_IMPLICIT_USES: &[PReg] = &[trust_cg_ir::regs::X0, trust_cg_ir::regs::X1];

/// Expand every call-like `TlsDescCall` into the four fixed TLSDESC slots:
///
/// ```text
/// ADRP x0, :tlsdesc:sym ; LDR x1, [x0, #:tlsdesc_lo12:sym]
/// ADD  x0, x0, #:tlsdesc_lo12:sym ; BLR x1  (.tlsdesccall sym)
/// ```
///
/// Runs at the end of frame lowering, after register allocation, scheduling
/// and prologue/epilogue insertion, so no pass can move, split or
/// reallocate the slots the static linker rewrites in place. The call keeps
/// its `InstId` (provenance, EH, implicit call clobbers) and becomes the BLR
/// slot. x0/x1 are free at the insertion point: `TlsDescCall` has no register
/// uses and clobbers both, so nothing is live in them across it.
fn expand_tlsdesc_call_sequences(func: &mut IrMachFunction) -> Result<(), PipelineError> {
    use trust_cg_ir::regs::{X0, X1};
    for block_index in 0..func.blocks.len() {
        let mut position = 0;
        while position < func.blocks[block_index].insts.len() {
            let inst_id = func.blocks[block_index].insts[position];
            if func.inst(inst_id).opcode != IrOpcode::TlsDescCall {
                position += 1;
                continue;
            }
            let symbol = match func.inst(inst_id).operands.as_slice() {
                [IrOperand::Symbol(symbol)] => symbol.clone(),
                other => {
                    return Err(PipelineError::Encoding(format!(
                        "TLSDESC call in function {} has operands {other:?}; expected one symbol",
                        func.name
                    )));
                }
            };
            let adrp = func.push_inst(IrMachInst::new(
                IrOpcode::Adrp,
                vec![IrOperand::PReg(X0), IrOperand::Symbol(symbol.clone())],
            ));
            let ldr = func.push_inst(IrMachInst::new(
                IrOpcode::LdrTlsdesc,
                vec![
                    IrOperand::PReg(X1),
                    IrOperand::PReg(X0),
                    IrOperand::Symbol(symbol.clone()),
                ],
            ));
            let add = func.push_inst(IrMachInst::new(
                IrOpcode::AddTlsdescLo12,
                vec![
                    IrOperand::PReg(X0),
                    IrOperand::PReg(X0),
                    IrOperand::Symbol(symbol.clone()),
                ],
            ));
            let call = func.inst_mut(inst_id);
            call.opcode = IrOpcode::BlrTlsdesc;
            call.flags = IrOpcode::BlrTlsdesc.default_flags();
            call.operands = vec![IrOperand::PReg(X1), IrOperand::Symbol(symbol)];
            call.implicit_uses = TLSDESC_CALL_IMPLICIT_USES;
            func.blocks[block_index]
                .insts
                .splice(position..position, [adrp, ldr, add]);
            position += 4;
        }
    }
    Ok(())
}

/// Fail-closed shape check for an expanded TLSDESC sequence, run when its
/// `BlrTlsdesc` slot is encoded. The three preceding real instructions of the
/// block must be exactly `ADRP x0, sym`, `LDR x1, [x0, sym]` and
/// `ADD x0, x0, sym`, and the call must be `BLR x1` for the same symbol. A
/// static linker relaxing the sequence to initial-exec or local-exec rewrites
/// these four slots in place with FIXED registers, so any other register,
/// order, symbol or interleaved instruction would compute a wrong address
/// after relaxation.
fn verify_tlsdesc_call_sequence(
    func: &IrMachFunction,
    block_insts: &[InstId],
    inst_index: usize,
) -> Result<String, PipelineError> {
    use trust_cg_ir::regs::{X0, X1};
    let fail = |detail: String| {
        PipelineError::Encoding(format!(
            "TLSDESC call sequence in function {} is malformed: {detail}; the static linker \
             rewrites the four slots in place, so the sequence must be exactly \
             ADRP x0 / LDR x1,[x0] / ADD x0,x0 / BLR x1 for one symbol (fail-closed)",
            func.name
        ))
    };
    let call = func.inst(block_insts[inst_index]);
    let symbol = match call.operands.as_slice() {
        [IrOperand::PReg(target), IrOperand::Symbol(symbol)] if *target == X1 => symbol.clone(),
        other => return Err(fail(format!("BLR slot operands {other:?}"))),
    };
    let mut previous = block_insts[..inst_index]
        .iter()
        .rev()
        .map(|&id| func.inst(id))
        .filter(|inst| !inst.is_pseudo());
    let symbol_operand = IrOperand::Symbol(symbol.clone());
    let expected = [
        (
            IrOpcode::AddTlsdescLo12,
            vec![
                IrOperand::PReg(X0),
                IrOperand::PReg(X0),
                symbol_operand.clone(),
            ],
        ),
        (
            IrOpcode::LdrTlsdesc,
            vec![
                IrOperand::PReg(X1),
                IrOperand::PReg(X0),
                symbol_operand.clone(),
            ],
        ),
        (IrOpcode::Adrp, vec![IrOperand::PReg(X0), symbol_operand]),
    ];
    for (opcode, operands) in expected {
        match previous.next() {
            Some(inst) if inst.opcode == opcode && inst.operands == operands => {}
            Some(inst) => {
                return Err(fail(format!(
                    "expected {opcode:?} {operands:?}, found {:?} {:?}",
                    inst.opcode, inst.operands
                )));
            }
            None => return Err(fail(format!("missing {opcode:?} before the BLR slot"))),
        }
    }
    Ok(symbol)
}

/// Re-pair GOT/TLVP page-offset loads whose feeding `ADRP` was separated
/// from them by SPILL/RELOAD (or any other post-ISel transform): insert a
/// fresh `ADRP base, @sym` immediately before the orphaned load.
///
/// WHY THIS IS REQUIRED FOR CORRECTNESS (not an optimization): the GOT-ness
/// of an `ADRP` is not represented in the machine IR — it is reconstructed
/// at encode time by in-block consumer pairing. When regalloc spills the
/// ADRP's result and reloads it in front of the `LdrGot`, the original ADRP
/// (whose remaining in-block consumer view no longer includes the load)
/// emits a DIRECT `PAGE21` while the load still emits `GOT_LOAD_PAGEOFF12`
/// — a mixed pair computing `page(sym) + lo12(got_slot)`: a wild load (the
/// `std::sys::fs::unix::try_statx` -O1/-O2 class). Rematerializing the page
/// value right before the load is unconditionally sound: `ADRP` is pure
/// (PC-relative page of a link-time constant), the destination register is
/// `base` itself, whose stale reloaded value dies here anyway, and the
/// encode-time forward scan then finds the adjacent load and emits the
/// correct GOT/TLVP page kind. The stale reload becomes dead but harmless.
fn repair_orphaned_got_page_pairs(func: &mut IrMachFunction) {
    let block_ids: Vec<BlockId> = func.block_order.clone();
    for block_id in block_ids {
        // (index in block insts, base preg, symbol) for each orphaned load.
        let mut repairs: Vec<(usize, PReg, String)> = Vec::new();
        {
            let insts = &func.blocks[block_id.0 as usize].insts;
            for (idx, &inst_id) in insts.iter().enumerate() {
                let inst = func.inst(inst_id);
                if !matches!(
                    inst.opcode,
                    IrOpcode::LdrGot
                        | IrOpcode::LdrTlvp
                        | IrOpcode::LdrGottprel
                        | IrOpcode::LdrTlsdesc
                ) {
                    continue;
                }
                let (Some(base), Some(symbol)) = (
                    inst.operands.get(1).and_then(|op| op.as_preg()),
                    inst.operands.get(2).and_then(|op| op.as_symbol()),
                ) else {
                    continue;
                };
                if !ldr_got_has_pairing_adrp(func, insts, idx, base, symbol) {
                    repairs.push((idx, base, symbol.to_string()));
                }
            }
        }
        // Insert in reverse so earlier indices stay valid.
        for (idx, base, symbol) in repairs.into_iter().rev() {
            let adrp = trust_cg_ir::MachInst::new(
                IrOpcode::Adrp,
                vec![
                    trust_cg_ir::MachOperand::PReg(base),
                    trust_cg_ir::MachOperand::Symbol(symbol),
                ],
            );
            let adrp_id = func.push_inst(adrp);
            func.blocks[block_id.0 as usize].insts.insert(idx, adrp_id);
        }
    }
}

/// The access size of a load/store the lo12 fusion may rewrite, or `None`.
/// Volatile accesses are never rewritten.
fn lo12_memory_access_size(inst: &trust_cg_ir::MachInst) -> Option<u32> {
    let rt = inst.operands.first()?.as_preg()?;
    match inst.opcode {
        IrOpcode::LdrbRI | IrOpcode::StrbRI | IrOpcode::LdrsbRI => Some(1),
        IrOpcode::LdrhRI | IrOpcode::StrhRI | IrOpcode::LdrshRI => Some(2),
        IrOpcode::LdrRI | IrOpcode::StrRI => match preg_class(rt) {
            RegClass::Gpr32 | RegClass::Fpr32 => Some(4),
            RegClass::Gpr64 | RegClass::Fpr64 => Some(8),
            RegClass::Fpr16 => Some(2),
            RegClass::Fpr128 => Some(16),
            _ => None,
        },
        _ => None,
    }
}

/// `(symbol, access size)` of a fused `LDR/STR Rt, [Xpage, #:lo12:sym]`:
/// operands exactly `[Rt, Xpage, Symbol(sym)]` on a fusible opcode.
fn lo12_memory_symbol_operand(inst: &trust_cg_ir::MachInst) -> Option<(&str, u32)> {
    match inst.operands.as_slice() {
        [
            IrOperand::PReg(_),
            IrOperand::PReg(_),
            IrOperand::Symbol(symbol),
        ] => Some((symbol.as_str(), lo12_memory_access_size(inst)?)),
        _ => None,
    }
}

fn same_gpr(a: PReg, b: PReg) -> bool {
    matches!(preg_class(a), RegClass::Gpr32 | RegClass::Gpr64)
        && matches!(preg_class(b), RegClass::Gpr32 | RegClass::Gpr64)
        && trust_cg_ir::aarch64_regs::hw_encoding(a) == trust_cg_ir::aarch64_regs::hw_encoding(b)
}

/// Whether `inst` reads general register `reg` (explicit use operands, memory
/// bases or implicit uses).
fn inst_reads_gpr(inst: &trust_cg_ir::MachInst, reg: PReg) -> bool {
    if inst.implicit_uses.iter().any(|used| same_gpr(*used, reg)) {
        return true;
    }
    let mut reads = false;
    trust_cg_opt::effects::aarch64_for_each_use_position(inst.opcode, inst.operands.len(), |pos| {
        match inst.operands.get(pos) {
            Some(IrOperand::PReg(used)) if same_gpr(*used, reg) => reads = true,
            Some(IrOperand::MemOp { base, .. }) if same_gpr(*base, reg) => reads = true,
            _ => {}
        }
    });
    // A memory operand in a def position still reads its base.
    reads
        || inst
            .operands
            .iter()
            .any(|operand| matches!(operand, IrOperand::MemOp { base, .. } if same_gpr(*base, reg)))
}

/// Whether `inst` writes general register `reg` (any view).
fn inst_writes_gpr(inst: &trust_cg_ir::MachInst, reg: PReg) -> bool {
    if inst
        .implicit_defs
        .iter()
        .any(|defined| same_gpr(*defined, reg))
    {
        return true;
    }
    let mut writes = false;
    trust_cg_opt::effects::aarch64_for_each_def_position(inst.opcode, inst.operands.len(), |pos| {
        if let Some(IrOperand::PReg(defined)) = inst.operands.get(pos)
            && same_gpr(*defined, reg)
        {
            writes = true;
        }
    });
    writes
}

/// Whether general register `reg` may be live on entry to any successor of
/// `block`: a single-register backward liveness solve over the laid-out CFG.
/// Any block ending in an indirect branch makes the answer conservatively
/// `true`.
fn gpr_live_out_of_block(func: &IrMachFunction, block: BlockId, reg: PReg) -> bool {
    let blocks = &func.block_order;
    let mut live_in: HashMap<BlockId, bool> = blocks.iter().map(|id| (*id, false)).collect();
    // Per block: does it read `reg` before writing it, and does it write it?
    let mut summary: HashMap<BlockId, (bool, bool)> = HashMap::new();
    for &id in blocks {
        let mut reads_first = false;
        let mut writes = false;
        for &inst_id in &func.block(id).insts {
            let inst = func.inst(inst_id);
            if matches!(inst.opcode, IrOpcode::Br) {
                return true;
            }
            if !writes && inst_reads_gpr(inst, reg) {
                reads_first = true;
            }
            if inst_writes_gpr(inst, reg) {
                writes = true;
            }
        }
        summary.insert(id, (reads_first, writes));
    }
    let mut changed = true;
    while changed {
        changed = false;
        for &id in blocks.iter().rev() {
            let (reads_first, writes) = summary[&id];
            let out = func
                .block(id)
                .succs
                .iter()
                .any(|succ| live_in.get(succ).copied().unwrap_or(true));
            let value = reads_first || (!writes && out);
            if value && !live_in[&id] {
                live_in.insert(id, true);
                changed = true;
            }
        }
    }
    func.block(block)
        .succs
        .iter()
        .any(|succ| live_in.get(succ).copied().unwrap_or(true))
}

/// Guaranteed address alignment of each data symbol an AArch64 ELF object
/// defines from `globals`: non-import, non-TLS, non-weak definitions with a
/// power-of-two alignment, which the ELF emitter places at that alignment in
/// a section aligned at least as strictly. A weak definition is excluded
/// because another object's definition may be chosen at link time.
pub fn elf_lo12_symbol_alignments(globals: &[ObjectGlobal]) -> BTreeMap<String, u64> {
    globals
        .iter()
        .filter(|global| {
            !global.is_import
                && !global.is_thread_local
                && !global.is_weak
                && global.align.is_power_of_two()
        })
        .map(|global| (global.name.clone(), u64::from(global.align)))
        .collect()
}

/// Fuse `ADRP Xp, sym; ADD Xa, Xp, #:lo12:sym; LDR/STR Rt, [Xa, #0]` into a
/// single-base `ADRP; LDR/STR Rt, [Xbase, #:lo12:sym]` (AArch64 ELF only).
///
/// The fused access carries an `R_AARCH64_LDST{8,16,32,64,128}_ABS_LO12_NC`
/// relocation, whose scaled field drops the low `log2(size)` bits of `S`. It
/// is therefore applied only when `alignments` guarantees `S` is a multiple of
/// the access size (a non-weak definition in this object, placed at its
/// declared power-of-two alignment); every other access keeps the ADD. Only
/// zero-offset accesses are fused: the page half carries no addend, so a
/// nonzero offset could cross into the next page.
///
/// Within one block the ADRP must be the last writer of `Xp` before the ADD,
/// nothing between the ADD and the access may read or write `Xa`, a store may
/// not store `Xa` itself, and `Xa` must be dead after the access (redefined by
/// it, redefined later in the block before any read, or not live out). The
/// access then addresses through `Xp` when `Xp` survives to it unchanged.
/// Otherwise, when the ADD is `Xp`'s only reader (nothing between the ADRP and
/// the ADD reads `Xp`, and `Xp` is dead after the ADD), the ADRP writes `Xa`
/// instead and the access addresses through `Xa`: the ADRP keeps its slot when
/// `Xa` is untouched between it and the ADD, and otherwise moves into the
/// ADD's slot, where the ADD wrote `Xa`. Functions with exception-handling
/// metadata are left unchanged. Returns the number of fused accesses.
pub(crate) fn fuse_elf_lo12_memory_accesses(
    func: &mut IrMachFunction,
    alignments: &BTreeMap<String, u64>,
) -> usize {
    if alignments.is_empty() || func.eh_metadata.has_eh_info() {
        return 0;
    }
    // A fusion can free a page register an earlier candidate needed (a later
    // ADRP retargeted away from it), so repeat until nothing changes. Each
    // round removes at least one ADD, which bounds the iteration.
    let mut fused = 0;
    loop {
        let mut round = 0;
        let block_ids: Vec<BlockId> = func.block_order.clone();
        for block_id in block_ids {
            let mut index = 0;
            while index < func.block(block_id).insts.len() {
                let insts = func.block(block_id).insts.clone();
                let Some(rewrite) =
                    lo12_fusion_candidate(func, block_id, &insts, index, alignments)
                else {
                    index += 1;
                    continue;
                };
                func.insts[insts[rewrite.consumer].0 as usize].operands = rewrite.operands;
                if let Lo12Page::Retarget { adrp, base } | Lo12Page::Sink { adrp, base } =
                    rewrite.page
                {
                    func.insts[insts[adrp].0 as usize].operands[0] = IrOperand::PReg(base);
                }
                let block = &mut func.blocks[block_id.0 as usize];
                if let Lo12Page::Sink { adrp, .. } = rewrite.page {
                    // The ADRP replaces the ADD; `adrp < index`, so the next
                    // unexamined instruction is again at `index`.
                    block.insts[index] = insts[adrp];
                    block.insts.remove(adrp);
                } else {
                    block.insts.remove(index);
                }
                round += 1;
            }
        }
        if round == 0 {
            return fused;
        }
        fused += round;
    }
}

/// One admitted lo12 fusion: the consumer's block index, its rewritten
/// operands and where the page register comes from.
struct Lo12Rewrite {
    consumer: usize,
    operands: Vec<IrOperand>,
    page: Lo12Page,
}

/// How a fused access obtains its page. `adrp` is the ADRP's block index and
/// `base` the address register it is redirected to write.
#[derive(Clone, Copy)]
enum Lo12Page {
    /// The ADRP's own destination survives to the access unchanged.
    Kept,
    /// The ADRP keeps its slot and writes `base` instead.
    Retarget { adrp: usize, base: PReg },
    /// The ADRP moves into the ADD's slot and writes `base` there.
    Sink { adrp: usize, base: PReg },
}

/// If the instruction at `index` is a fusible `ADD Xa, Xp, #:lo12:sym`,
/// describe the rewrite.
fn lo12_fusion_candidate(
    func: &IrMachFunction,
    block_id: BlockId,
    insts: &[InstId],
    index: usize,
    alignments: &BTreeMap<String, u64>,
) -> Option<Lo12Rewrite> {
    let add = func.inst(insts[index]);
    if add.opcode != IrOpcode::AddPCRel {
        return None;
    }
    let [
        IrOperand::PReg(xa),
        IrOperand::PReg(xp),
        IrOperand::Symbol(symbol),
    ] = add.operands.as_slice()
    else {
        return None;
    };
    let (xa, xp) = (*xa, *xp);
    if preg_class(xa) != RegClass::Gpr64 || preg_class(xp) != RegClass::Gpr64 {
        return None;
    }
    let alignment = *alignments.get(symbol)?;
    if !alignment.is_power_of_two() {
        return None;
    }
    // The page register's last writer before the ADD must be the same-symbol
    // ADRP in this block.
    let adrp = insts[..index]
        .iter()
        .rposition(|&prev_id| inst_writes_gpr(func.inst(prev_id), xp))?;
    let adrp_inst = func.inst(insts[adrp]);
    if adrp_inst.opcode != IrOpcode::Adrp
        || !matches!(adrp_inst.operands.as_slice(), [IrOperand::PReg(dst), IrOperand::Symbol(name)]
            if same_gpr(*dst, xp) && name == symbol)
    {
        return None;
    }

    let mut page_clobbered = false;
    for (offset, &candidate_id) in insts[index + 1..].iter().enumerate() {
        let consumer = index + 1 + offset;
        let candidate = func.inst(candidate_id);
        let size = lo12_memory_access_size(candidate);
        let zero_offset_base = match candidate.operands.as_slice() {
            [
                IrOperand::PReg(rt),
                IrOperand::PReg(base),
                IrOperand::Imm(0),
            ] => Some((*rt, *base)),
            [IrOperand::PReg(rt), IrOperand::MemOp { base, offset: 0 }] => Some((*rt, *base)),
            _ => None,
        };
        if let (Some(size), Some((rt, base))) = (size, zero_offset_base)
            && same_gpr(base, xa)
        {
            let is_store = matches!(
                candidate.opcode,
                IrOpcode::StrRI | IrOpcode::StrbRI | IrOpcode::StrhRI
            );
            if (is_store && same_gpr(rt, xa)) || u64::from(size) > alignment {
                return None;
            }
            let redefined_by_load = !is_store && same_gpr(rt, xa);
            if !redefined_by_load && !gpr_dead_after(func, block_id, insts, consumer, xa) {
                return None;
            }
            let fused = |base: PReg| {
                vec![
                    IrOperand::PReg(rt),
                    IrOperand::PReg(base),
                    IrOperand::Symbol(symbol.clone()),
                ]
            };
            if !page_clobbered {
                return Some(Lo12Rewrite {
                    consumer,
                    operands: fused(xp),
                    page: Lo12Page::Kept,
                });
            }
            // `Xp` is overwritten before the access: move the page into `Xa`
            // instead. Sound only when the ADD is `Xp`'s sole reader: nothing
            // between the ADRP and the ADD reads `Xp` (the ADRP is its last
            // writer, so nothing there writes it either), and `Xp` is dead
            // after the ADD.
            let between = &insts[adrp + 1..index];
            let sole_reader = between.iter().all(|&between_id| {
                let between = func.inst(between_id);
                !between.is_pseudo() && !inst_reads_gpr(between, xp)
            });
            if !sole_reader || !gpr_dead_after(func, block_id, insts, index, xp) {
                return None;
            }
            // With `Xa` untouched in between, the ADRP can write it from its
            // own slot. Otherwise it moves to the ADD's slot: every
            // instruction in between then still sees the `Xa` it saw before,
            // and `Xa` is written exactly where the ADD wrote it.
            let xa_untouched = between.iter().all(|&between_id| {
                let between = func.inst(between_id);
                !inst_reads_gpr(between, xa) && !inst_writes_gpr(between, xa)
            });
            let page = if xa_untouched {
                Lo12Page::Retarget { adrp, base: xa }
            } else {
                Lo12Page::Sink { adrp, base: xa }
            };
            return Some(Lo12Rewrite {
                consumer,
                operands: fused(xa),
                page,
            });
        }
        if candidate.is_pseudo()
            || candidate.is_branch()
            || candidate.is_return()
            || inst_reads_gpr(candidate, xa)
            || inst_writes_gpr(candidate, xa)
        {
            return None;
        }
        if inst_writes_gpr(candidate, xp) {
            page_clobbered = true;
        }
    }
    None
}

/// Whether `reg` is dead after the instruction at block index `at`.
fn gpr_dead_after(
    func: &IrMachFunction,
    block_id: BlockId,
    insts: &[InstId],
    at: usize,
    reg: PReg,
) -> bool {
    for &later_id in &insts[at + 1..] {
        let later = func.inst(later_id);
        if inst_reads_gpr(later, reg) {
            return false;
        }
        if inst_writes_gpr(later, reg) {
            return true;
        }
    }
    !gpr_live_out_of_block(func, block_id, reg)
}

/// Fail-closed pairing for a fused lo12 access: its base must be the page
/// written by a same-symbol `ADRP` in this block with no intervening writer.
fn verify_lo12_memory_page_pairing(
    func: &IrMachFunction,
    block_insts: &[InstId],
    inst_index: usize,
    base: PReg,
    symbol: &str,
) -> Result<(), PipelineError> {
    let paired = block_insts[..inst_index]
        .iter()
        .rev()
        .find_map(|&prev_id| {
            let prev = func.inst(prev_id);
            inst_writes_gpr(prev, base).then(|| {
                prev.opcode == IrOpcode::Adrp
                    && prev.operands.get(1).and_then(|op| op.as_symbol()) == Some(symbol)
            })
        })
        .unwrap_or(false);
    if paired {
        return Ok(());
    }
    Err(PipelineError::Encoding(format!(
        "lo12 memory access in function {} uses base register {base:?} for symbol '{symbol}' \
         without a pairing `ADRP {base:?}, @{symbol}` in the same block (fail-closed: the page \
         and lo12 halves must be paired)",
        func.name
    )))
}

fn verify_got_ldr_page_pairing(
    func: &IrMachFunction,
    block_insts: &[InstId],
    inst_index: usize,
    base: PReg,
    symbol: &str,
) -> Result<(), PipelineError> {
    if ldr_got_has_pairing_adrp(func, block_insts, inst_index, base, symbol) {
        return Ok(());
    }
    Err(PipelineError::Encoding(format!(
        "GOT/TLVP page-offset load in function {} uses base register {base:?} for symbol          '{symbol}' without a pairing `ADRP {base:?}, @{symbol}` in the same block; emitting          it would produce a mixed direct/GOT relocation pair (a wild load at run time).          Fail-closed: the page and page-offset halves must be paired.",
        func.name
    )))
}

/// Validate every arena index and block-bearing side table before an AArch64
/// whole-function pass may index or mutate the function. `blocks` is an arena:
/// CFG cleanup may unlink an unreachable block from `block_order` without
/// renumbering the arena. `block_order` is the executable/encoded domain, so it
/// must be closed under every semantic control-flow authority (branch operands,
/// CFG metadata, jump tables, and EH), but need not contain unreachable arena
/// shells. This totality check is also repeated at the lowest shared encoding
/// boundary; final semantic TV4 enforcement remains in
/// [`enforce_aarch64_post_regalloc`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AArch64CfgValidationStage {
    /// Symbolic branch operands are still available and CFG metadata is about
    /// to become regalloc/TV-5 authority. Require an exact semantic match.
    SymbolicAuthority,
    /// A known internal post-resolution funnel replaced Block operands with
    /// relative immediates after the symbolic-authority check already passed.
    ResolvedEncoding,
}

fn validate_aarch64_mach_function_impl(
    func: &IrMachFunction,
    cfg_stage: AArch64CfgValidationStage,
    target_machine: Option<&AArch64TargetMachine>,
) -> Result<OutputTargetFeatures<AArch64IsaFeature>, PipelineError> {
    let malformed = |detail: String| PipelineError::MalformedAarch64Function {
        function: func.name.clone(),
        detail,
    };
    trust_cg_verify::aarch64_jump_table_address::validate_expansions(func).map_err(malformed)?;
    let block_count = func.blocks.len();
    let valid_block = |block_id: BlockId| (block_id.0 as usize) < block_count;
    let required_return_pregs = aarch64_required_return_pregs(&func.signature);
    let mut required_features = OutputTargetFeatures::NONE;

    if func.eh_metadata.has_eh_info() {
        // The personality symbol is EH-sidecar content, not machine-function
        // structure, so it refuses with the exception-handling variant. (The
        // landing-pad / call-site layout checks below stay structural: they
        // catch a machine-code pass that dropped blocks out of lockstep with the
        // EH tables.)
        crate::exception_handling::required_personality_symbol(
            func.eh_metadata.personality.as_deref(),
        )
        .map_err(|error| PipelineError::MalformedAarch64Eh {
            function: func.name.clone(),
            detail: format!("invalid exception-handling personality: {error}"),
        })?;
    }

    if !valid_block(func.entry) {
        return Err(malformed(format!(
            "entry block {:?} is outside the {}-block arena",
            func.entry, block_count
        )));
    }
    let mut seen = BTreeSet::new();
    for &block_id in &func.block_order {
        if !valid_block(block_id) {
            return Err(malformed(format!(
                "block_order contains invalid block {:?}",
                block_id
            )));
        }
        if !seen.insert(block_id) {
            return Err(malformed(format!(
                "block_order duplicates block {:?}",
                block_id
            )));
        }
    }
    if func.block_order.first().copied() != Some(func.entry) {
        return Err(malformed(format!(
            "block_order must start with entry block {:?}, got {:?}",
            func.entry,
            func.block_order.first()
        )));
    }

    let mut linked_insts = BTreeSet::new();
    for (block_index, block) in func.blocks.iter().enumerate() {
        let block_id = BlockId(block_index as u32);
        for (&edge, edge_kind) in block
            .preds
            .iter()
            .map(|edge| (edge, "predecessor"))
            .chain(block.succs.iter().map(|edge| (edge, "successor")))
        {
            if !valid_block(edge) {
                return Err(malformed(format!(
                    "block {:?} has invalid {} target {:?}",
                    block_id, edge_kind, edge
                )));
            }
            if seen.contains(&block_id) && !seen.contains(&edge) {
                return Err(malformed(format!(
                    "laid-out block {:?} has {} target {:?} absent from block_order",
                    block_id, edge_kind, edge
                )));
            }
        }

        for &inst_id in &block.insts {
            let inst = func.insts.get(inst_id.0 as usize).ok_or_else(|| {
                malformed(format!(
                    "block {:?} references instruction {:?} outside the {}-instruction arena",
                    block_id,
                    inst_id,
                    func.insts.len()
                ))
            })?;
            if !linked_insts.insert(inst_id) {
                return Err(malformed(format!(
                    "instruction {:?} is linked from more than one block position",
                    inst_id
                )));
            }

            // This mandatory walk runs before optimization and again before
            // allocation. Final physical encoding cannot reconstruct virtual
            // classes or known aliases that those transformations erased.
            checked_pair_memory_intent(inst)
                .map_err(|error| malformed(format!("instruction {inst_id:?}: {error}")))?;
            checked_narrow_register_offset_intent(inst)
                .map_err(|error| malformed(format!("instruction {inst_id:?}: {error}")))?;

            // Capability derivation shares this already-mandatory structural
            // walk. Only laid-out blocks contribute emitted instructions;
            // unreachable arena shells are structurally checked but are not
            // machine-output requirements. Pipeline callers pass their
            // captured target machine so ordinary compilation does not pay for
            // a second whole-function scan.
            if seen.contains(&block_id) {
                observe_aarch64_inst_isa_requirements(
                    &func.name,
                    inst,
                    target_machine,
                    &mut required_features,
                )?;
            }

            if inst.opcode == IrOpcode::TailCall {
                let default_flags = IrOpcode::TailCall.default_flags();
                let exact_flags =
                    default_flags.union(trust_cg_ir::inst::InstFlags::EXACT_MODULE_CALL);
                if inst.flags != default_flags && inst.flags != exact_flags {
                    return Err(malformed(format!(
                        "tail-call instruction {:?} has non-canonical flags {:?}",
                        inst_id, inst.flags
                    )));
                }
                if !matches!(
                    inst.operands.as_slice(),
                    [IrOperand::Symbol(_) | IrOperand::Block(_) | IrOperand::Imm(_)]
                ) {
                    return Err(malformed(format!(
                        "tail-call instruction {:?} must carry exactly one direct target operand",
                        inst_id
                    )));
                }
            } else if inst.opcode == IrOpcode::B
                && (!inst.implicit_uses.is_empty()
                    || !inst.implicit_defs.is_empty()
                    || inst.flags.is_call())
            {
                return Err(malformed(format!(
                    "ordinary B instruction {:?} carries call-boundary metadata; use structural TailCall",
                    inst_id
                )));
            }

            if inst.opcode == IrOpcode::Ret
                && !aarch64_preg_alias_sets_equal(&required_return_pregs, inst.implicit_uses)
            {
                let expected: Vec<_> = aarch64_preg_alias_set(&required_return_pregs)
                    .into_iter()
                    .map(preg_name)
                    .collect();
                let actual: Vec<_> = aarch64_preg_alias_set(inst.implicit_uses)
                    .into_iter()
                    .map(preg_name)
                    .collect();
                return Err(malformed(format!(
                    "return instruction {:?} must carry exactly the ABI return-register implicit-use alias set {:?}, got {:?}; signature returns {:?}",
                    inst_id, expected, actual, func.signature.returns
                )));
            }

            // `is_branch()` is true for the `Trap*` guard pseudos as well, whose
            // `Imm` is a bounds limit / shift width / overflow op-tag rather than
            // a resolved code offset — see `AArch64Opcode::is_trap_pseudo`. The
            // x86-64 mirror of this check (x86_64/pipeline.rs) scopes itself to
            // `Jmp | Jcc` and so never had the false positive; this is the same
            // safety decision, and the two copies had drifted.
            if seen.contains(&block_id) && inst.is_branch() && !inst.opcode.is_trap_pseudo() {
                let has_block_target = inst
                    .operands
                    .iter()
                    .any(|operand| matches!(operand, IrOperand::Block(_)));
                let has_immediate = inst
                    .operands
                    .iter()
                    .any(|operand| matches!(operand, IrOperand::Imm(_)));
                if !has_block_target
                    && has_immediate
                    && cfg_stage == AArch64CfgValidationStage::SymbolicAuthority
                {
                    return Err(malformed(format!(
                        "branch instruction {:?} carries a resolved immediate before the symbolic CFG authority boundary",
                        inst_id
                    )));
                }
            }

            for (operand_index, operand) in inst.operands.iter().enumerate() {
                match operand {
                    IrOperand::Block(target) => {
                        if !valid_block(*target) {
                            return Err(malformed(format!(
                                "instruction {:?} operand {} has invalid block target {:?}",
                                inst_id, operand_index, target
                            )));
                        }
                        if seen.contains(&block_id) && !seen.contains(target) {
                            return Err(malformed(format!(
                                "laid-out block {:?} instruction {:?} operand {} targets {:?}, which is absent from block_order",
                                block_id, inst_id, operand_index, target
                            )));
                        }
                    }
                    IrOperand::StackSlot(slot) if slot.0 as usize >= func.stack_slots.len() => {
                        return Err(malformed(format!(
                            "instruction {:?} operand {} references stack slot {:?} outside the {}-slot arena",
                            inst_id,
                            operand_index,
                            slot,
                            func.stack_slots.len()
                        )));
                    }
                    IrOperand::JumpTableIndex(index)
                        if *index as usize >= func.jump_tables.len() =>
                    {
                        return Err(malformed(format!(
                            "instruction {:?} operand {} references jump table {} outside the {}-table arena",
                            inst_id,
                            operand_index,
                            index,
                            func.jump_tables.len()
                        )));
                    }
                    _ => {}
                }
            }
        }
    }

    if let Some(slot) = func.stack_protector_slot
        && slot.0 as usize >= func.stack_slots.len()
    {
        return Err(malformed(format!(
            "stack protector references slot {:?} outside the {}-slot arena",
            slot,
            func.stack_slots.len()
        )));
    }
    for (table_index, table) in func.jump_tables.iter().enumerate() {
        for &target in &table.targets {
            if !valid_block(target) {
                return Err(malformed(format!(
                    "jump table {} has invalid block target {:?}",
                    table_index, target
                )));
            }
            if !seen.contains(&target) {
                return Err(malformed(format!(
                    "jump table {} targets block {:?}, which is absent from block_order",
                    table_index, target
                )));
            }
        }
    }
    for landing_pad in &func.eh_metadata.landing_pads {
        if !valid_block(landing_pad.block) {
            return Err(malformed(format!(
                "exception landing pad has invalid block target {:?}",
                landing_pad.block
            )));
        }
        if !seen.contains(&landing_pad.block) {
            return Err(malformed(format!(
                "exception landing pad targets block {:?}, which is absent from block_order",
                landing_pad.block
            )));
        }
    }
    for call_site in &func.eh_metadata.call_sites {
        if !valid_block(call_site.call_block) {
            return Err(malformed(format!(
                "exception call site has invalid call block {:?}",
                call_site.call_block
            )));
        }
        if !seen.contains(&call_site.call_block) {
            return Err(malformed(format!(
                "exception call site uses block {:?}, which is absent from block_order",
                call_site.call_block
            )));
        }
        if let Some(target) = call_site.landing_pad_block
            && !valid_block(target)
        {
            return Err(malformed(format!(
                "exception call site has invalid landing-pad block {:?}",
                target
            )));
        }
        if let Some(target) = call_site.landing_pad_block
            && !seen.contains(&target)
        {
            return Err(malformed(format!(
                "exception call site targets landing-pad block {:?}, which is absent from block_order",
                target
            )));
        }
    }

    validate_exact_aarch64_eh_call_identity(func)?;

    if cfg_stage == AArch64CfgValidationStage::SymbolicAuthority {
        let expected_edges = derive_ir_cfg_edges_from_branch_operands(func);
        let mut expected_succs = vec![BTreeSet::new(); block_count];
        let mut expected_preds = vec![BTreeSet::new(); block_count];
        for (from, to) in expected_edges {
            if !seen.contains(&from) || !seen.contains(&to) {
                return Err(malformed(format!(
                    "semantic control edge {:?} -> {:?} escapes block_order",
                    from, to
                )));
            }
            expected_succs[from.0 as usize].insert(to);
            expected_preds[to.0 as usize].insert(from);
        }
        for &block_id in &func.block_order {
            let block_index = block_id.0 as usize;
            let block = &func.blocks[block_index];
            let actual_succs: BTreeSet<_> = block.succs.iter().copied().collect();
            if actual_succs.len() != block.succs.len() {
                return Err(malformed(format!(
                    "block {:?} contains duplicate successor metadata: {:?}",
                    block_id, block.succs
                )));
            }
            if actual_succs != expected_succs[block_index] {
                return Err(malformed(format!(
                    "block {:?} successor metadata {:?} does not match semantic control edges {:?}",
                    block_id, actual_succs, expected_succs[block_index]
                )));
            }

            let actual_preds: BTreeSet<_> = block.preds.iter().copied().collect();
            if actual_preds.len() != block.preds.len() {
                return Err(malformed(format!(
                    "block {:?} contains duplicate predecessor metadata: {:?}",
                    block_id, block.preds
                )));
            }
            if actual_preds != expected_preds[block_index] {
                return Err(malformed(format!(
                    "block {:?} predecessor metadata {:?} does not match reciprocal semantic edges {:?}",
                    block_id, actual_preds, expected_preds[block_index]
                )));
            }
        }
    }

    if let Some(target_machine) = target_machine {
        target_machine
            .validate_output_features(required_features)
            .map_err(|error| aarch64_target_machine_contract_error(&func.name, error))?;
    }

    Ok(required_features)
}

pub(crate) fn validate_aarch64_mach_function(func: &IrMachFunction) -> Result<(), PipelineError> {
    validate_aarch64_mach_function_impl(func, AArch64CfgValidationStage::SymbolicAuthority, None)
        .map(|_| ())
}

pub(crate) fn validate_aarch64_mach_function_totality(
    func: &IrMachFunction,
) -> Result<(), PipelineError> {
    validate_aarch64_mach_function_impl(func, AArch64CfgValidationStage::ResolvedEncoding, None)
        .map(|_| ())
}

pub(crate) fn enforce_aarch64_post_regalloc_resolved(
    func: &IrMachFunction,
) -> Result<(), PipelineError> {
    enforce_aarch64_post_regalloc_impl(
        func,
        AArch64CfgValidationStage::ResolvedEncoding,
        None,
        Aarch64IntegrityPolicy::Compatibility,
    )
    .map(|_| ())
}

/// The final-stream check one run of [`enforce_aarch64_post_regalloc_impl`]
/// performed: its integrity policy and the modes that policy resolved for the
/// two nets with a diagnostic override (the reaching-definition net and the
/// frame net; the structural recheck is always enforced). Everything else the
/// enforcement reads is the function itself, so two runs over the same
/// function under equal checks reach the same verdict.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct Aarch64FinalStreamCheck {
    policy: Aarch64IntegrityPolicy,
    reaching_def: trust_cg_verify::post_regalloc_recheck::PostRegallocRecheckMode,
    spill_slot: trust_cg_verify::post_regalloc_recheck::PostRegallocRecheckMode,
}

impl Aarch64FinalStreamCheck {
    /// The check `integrity_policy` selects now: a compatibility policy keeps
    /// each net's diagnostic override, a proof-grade policy forces both to
    /// Enforce.
    fn resolve(integrity_policy: Aarch64IntegrityPolicy) -> Self {
        use trust_cg_verify::post_ra_reaching_def as prd;
        use trust_cg_verify::post_ra_spill_slots as pss;
        use trust_cg_verify::post_regalloc_recheck::PostRegallocRecheckMode;
        let (reaching_def, spill_slot) = match integrity_policy {
            Aarch64IntegrityPolicy::Compatibility => {
                (prd::reaching_def_mode(), pss::spill_slot_mode())
            }
            Aarch64IntegrityPolicy::ProofGradeEnforce => (
                PostRegallocRecheckMode::Enforce,
                PostRegallocRecheckMode::Enforce,
            ),
        };
        Self {
            policy: integrity_policy,
            reaching_def,
            spill_slot,
        }
    }
}

fn enforce_aarch64_post_regalloc_impl(
    func: &IrMachFunction,
    cfg_stage: AArch64CfgValidationStage,
    target_machine: Option<&AArch64TargetMachine>,
    integrity_policy: Aarch64IntegrityPolicy,
) -> Result<OutputTargetFeatures<AArch64IsaFeature>, PipelineError> {
    enforce_aarch64_final_stream(
        func,
        cfg_stage,
        target_machine,
        Aarch64FinalStreamCheck::resolve(integrity_policy),
    )
}

/// [`enforce_aarch64_post_regalloc_impl`] under an already-resolved check.
fn enforce_aarch64_final_stream(
    func: &IrMachFunction,
    cfg_stage: AArch64CfgValidationStage,
    target_machine: Option<&AArch64TargetMachine>,
    check: Aarch64FinalStreamCheck,
) -> Result<OutputTargetFeatures<AArch64IsaFeature>, PipelineError> {
    use trust_cg_verify::post_ra_reaching_def as prd;
    use trust_cg_verify::post_ra_spill_slots as pss;
    use trust_cg_verify::post_regalloc_recheck as prr;

    // The verifier below indexes both arenas. Keep the total boundary check
    // first so malformed public input is always a typed error, never a panic.
    let required_features = validate_aarch64_mach_function_impl(func, cfg_stage, target_machine)?;
    if cfg_stage == AArch64CfgValidationStage::ResolvedEncoding
        && !func.blocks.iter().any(|block| {
            block.insts.iter().any(|inst_id| {
                func.insts.get(inst_id.0 as usize).is_some_and(|inst| {
                    inst.is_branch()
                        && !inst
                            .operands
                            .iter()
                            .any(|operand| matches!(operand, IrOperand::Block(_)))
                        && inst
                            .operands
                            .iter()
                            .any(|operand| matches!(operand, IrOperand::Imm(_)))
                })
            })
        })
    {
        // Public low-level encoders may still be handed a wholly symbolic
        // stream. Preserve exact CFG rejection there; totality-only validation
        // is reserved for streams that actually contain resolved/internal
        // immediate branches and are reconstructed below.
        validate_aarch64_mach_function_impl(
            func,
            AArch64CfgValidationStage::SymbolicAuthority,
            None,
        )?;
    }
    // Flagged spill accesses must have the one shape spill materialization
    // forms, so the frame dataflow net below models each of them.
    reject_aarch64_unformed_spill_shapes(func)?;
    // Exclusive windows before CFG reconstruction: a spill or other memory
    // access inside an expanded LL/SC loop breaks its template, and the
    // reconstruction would refuse the loop's branch without naming why.
    check_aarch64_exclusive_windows(func)?;
    let mut derived_cfg_func = None;
    if cfg_stage == AArch64CfgValidationStage::ResolvedEncoding {
        derived_cfg_func = Some(reconstruct_aarch64_resolved_cfg(func).map_err(|detail| {
            PipelineError::MalformedAarch64Function {
                function: func.name.clone(),
                detail,
            }
        })?);
    }
    let verified_func = derived_cfg_func.as_ref().unwrap_or(func);
    if derived_cfg_func.is_some() {
        // Windows that stay open across a block boundary follow the derived
        // successor lists, which resolved branch immediates alone define.
        check_aarch64_exclusive_windows(verified_func)?;
    }

    for &block_id in &verified_func.block_order {
        verify_aarch64_final_call_argument_sequence(
            &verified_func.name,
            verified_func
                .block(block_id)
                .insts
                .iter()
                .map(|&inst_id| verified_func.inst(inst_id)),
        )?;
    }

    let mode = prr::post_regalloc_recheck_mode(prr::AARCH64_POST_RA_RECHECK_DEFAULT);
    if let Some(violation) = prr::evaluate(verified_func, "aarch64", mode) {
        return Err(PipelineError::RegAlloc(format!(
            "[TCG-POST-RA-RECHECK] fn `{}` final AArch64 stream violation ({}): {}",
            verified_func.name,
            violation.kind.tag(),
            violation.detail
        )));
    }

    // TV-6 reaching-definition net: flag any post-RA physical
    // register read with no reaching definition on every path. Runs ALONGSIDE
    // the structural recheck above. Compatibility APIs retain their explicit
    // diagnostic environment override; proof-grade transitions force Enforce.
    let reaching_def_mode = check.reaching_def;
    if let Some(violation) = prd::evaluate(verified_func, reaching_def_mode) {
        return Err(PipelineError::RegAlloc(format!(
            "[TCG-A64-REACHING-DEF] fn `{}` final AArch64 stream reaching-def violation ({}): {}",
            verified_func.name,
            violation.kind.tag(),
            violation.detail
        )));
    }

    // TV-6 frame dataflow net: models the frame from the CFA and flags a
    // flagged spill reload that does not read exactly one spill store's bytes
    // on every path, a consumed call-clobbered register or caller callee-saved
    // value, and an exit whose SP, callee-saved registers, return address or
    // return lanes are not intact — the memory and frame companion to the
    // register reaching-def net above. Compatibility APIs retain their
    // diagnostic override; proof-grade transitions force Enforce.
    let spill_slot_mode = check.spill_slot;
    if let Some(violation) = pss::evaluate(verified_func, spill_slot_mode) {
        return Err(PipelineError::RegAlloc(format!(
            "[TCG-A64-SPILL-SLOT] fn `{}` final AArch64 stream spill-slot violation ({}): {}",
            verified_func.name,
            violation.kind.tag(),
            violation.detail
        )));
    }

    // U10 stack-limit net: a requested check must be present and verified
    // (or a certified elision) on every route. It has its own model, reads
    // no diagnostic override and never declines, so neither the integrity
    // policy nor the frame net's mode or caps can turn it off.
    if verified_func.stack_limit.is_some() {
        trust_cg_verify::aarch64_stack_limit::check(verified_func).map_err(|violation| {
            PipelineError::StackLimit {
                function: verified_func.name.clone(),
                reason: format!("final stream refused ({violation})"),
            }
        })?;
    }
    Ok(required_features)
}

fn encode_function_with_fixups_and_blocks_impl(
    func: &IrMachFunction,
    provenance: Option<&mut trust_cg_ir::ProvenanceMap>,
) -> Result<
    (
        Vec<u8>,
        crate::macho::fixup::FixupList,
        HashMap<BlockId, u32>,
    ),
    PipelineError,
> {
    encode_function_with_fixups_and_blocks_impl_with_sites(
        func,
        provenance,
        None,
        Aarch64IntegrityPolicy::Compatibility,
    )
}

/// A unit-test hook for the u32 AArch64 text-offset ceilings (the block,
/// instruction and jump-table offsets of the encoder and the LSDA code
/// length of [`resolve_eh_offsets`]), which only a function with 4 GiB of
/// code reaches. A unit test registers a synthetic prefix for a function
/// name, and each of those domain checks adds it to the offset or length it
/// checks for that function, as if that many bytes of code preceded the
/// function's first instruction. Only the checks see the prefix: nothing is
/// encoded at a shifted offset, and a length or offset that passes is the
/// physical one. It exists only in unit-test builds; every other build
/// checks the physical value ([`aarch64_text_domain_offset`]).
#[cfg(test)]
pub(crate) mod synthetic_text_prefix {
    use std::sync::Mutex;

    static PREFIXES: Mutex<Vec<(String, u64)>> = Mutex::new(Vec::new());

    /// Removes its function's prefix when dropped.
    pub(crate) struct Registration(String);

    impl Drop for Registration {
        fn drop(&mut self) {
            let mut prefixes = PREFIXES.lock().unwrap_or_else(|error| error.into_inner());
            prefixes.retain(|(function, _)| *function != self.0);
        }
    }

    /// Give `function` a synthetic prefix of `bytes` until the registration
    /// is dropped. The name should be unique to the test: the registry is
    /// shared by every thread.
    pub(crate) fn register(function: &str, bytes: u64) -> Registration {
        let mut prefixes = PREFIXES.lock().unwrap_or_else(|error| error.into_inner());
        prefixes.retain(|(name, _)| name != function);
        prefixes.push((function.to_string(), bytes));
        Registration(function.to_string())
    }

    /// The synthetic prefix of `function` (0 when none is registered).
    pub(crate) fn of(function: &str) -> u64 {
        let prefixes = PREFIXES.lock().unwrap_or_else(|error| error.into_inner());
        prefixes
            .iter()
            .find(|(name, _)| name == function)
            .map_or(0, |(_, bytes)| *bytes)
    }
}

/// The offset or length `physical` in `function`'s AArch64 text as the u32
/// relocation/LSDA domain checks see it: `physical` itself, plus a unit
/// test's synthetic prefix ([`synthetic_text_prefix`]) in unit-test builds.
fn aarch64_text_domain_offset(function: &str, physical: usize) -> u64 {
    let physical = u64::try_from(physical).unwrap_or(u64::MAX);
    #[cfg(test)]
    {
        physical.saturating_add(synthetic_text_prefix::of(function))
    }
    #[cfg(not(test))]
    {
        let _ = function;
        physical
    }
}

/// `physical`, an offset or length in `function`'s AArch64 text, as a u32
/// when the u32 relocation/LSDA domain holds it; otherwise the value the
/// domain check saw ([`aarch64_text_domain_offset`]), for the refusal.
fn aarch64_text_offset_u32(function: &str, physical: usize) -> Result<u32, u64> {
    let domain = aarch64_text_domain_offset(function, physical);
    match (u32::try_from(domain), u32::try_from(physical)) {
        (Ok(_), Ok(offset)) => Ok(offset),
        _ => Err(domain),
    }
}

fn encode_function_with_fixups_and_blocks_impl_with_sites(
    func: &IrMachFunction,
    provenance: Option<&mut trust_cg_ir::ProvenanceMap>,
    fixup_sites: Option<&mut Vec<EncodedAarch64FixupSite>>,
    integrity_policy: Aarch64IntegrityPolicy,
) -> Result<
    (
        Vec<u8>,
        crate::macho::fixup::FixupList,
        HashMap<BlockId, u32>,
    ),
    PipelineError,
> {
    encode_function_with_fixups_and_blocks_impl_prechecked(
        func,
        provenance,
        fixup_sites,
        integrity_policy,
        None,
    )
}

/// [`encode_function_with_fixups_and_blocks_impl_with_sites`] for a function
/// that may carry the final-stream check it already passed.
///
/// `prechecked` is `Some` only for a function a [`CheckedAarch64Function`]
/// owns: preparation ran [`enforce_aarch64_final_stream`] on exactly this
/// stream, at the resolved-encoding stage and WITH the target machine (a
/// superset of the checks this encoder runs), and the owner exposes no mutable
/// access. When that check equals the one this encode would run now (same
/// integrity policy, same resolved net modes), running it again would reach
/// the same verdict on the same bytes, so it is skipped; otherwise the stream
/// is checked as always.
fn encode_function_with_fixups_and_blocks_impl_prechecked(
    func: &IrMachFunction,
    mut provenance: Option<&mut trust_cg_ir::ProvenanceMap>,
    mut fixup_sites: Option<&mut Vec<EncodedAarch64FixupSite>>,
    integrity_policy: Aarch64IntegrityPolicy,
    prechecked: Option<Aarch64FinalStreamCheck>,
) -> Result<
    (
        Vec<u8>,
        crate::macho::fixup::FixupList,
        HashMap<BlockId, u32>,
    ),
    PipelineError,
> {
    use crate::macho::fixup::{Fixup, FixupList};
    use trust_cg_ir::inst::AArch64Opcode;

    let _phase = PhaseGuard::new(func, "encoding");
    if integrity_policy == Aarch64IntegrityPolicy::ProofGradeEnforce {
        refuse_aarch64_late_layout_controls(&func.name)?;
    }
    let check = Aarch64FinalStreamCheck::resolve(integrity_policy);
    if prechecked != Some(check) {
        enforce_aarch64_final_stream(
            func,
            AArch64CfgValidationStage::ResolvedEncoding,
            None,
            check,
        )?;
    }

    let mut code = Vec::new();
    let mut fixups = FixupList::new();

    // Track byte offsets of each block in the final layout, for jump
    // table patching. This is computed inline as we emit instructions.
    let mut block_byte_offsets: HashMap<BlockId, u32> = HashMap::new();
    // Pending Adr-for-jump-table fixups: (adr_byte_offset, jump_table_idx).
    let mut jt_adr_fixups: Vec<(u32, u32, bool)> = Vec::new();

    // ENC-5: record every emitted word + its intent for the independent
    // decode-check (run over the FINAL bytes just before return). Arms whose
    // word is patched later (linker relocations) record a hole so the
    // patched field's placeholder VALUE is not compared.
    let dc_mode = aarch64_decode_check_mode_for_integrity_policy(integrity_policy);
    #[cfg(all(test, feature = "verify"))]
    crate::decode_check::lane_probe::record(&func.name, || {
        crate::decode_check::lane_probe::Event::Encode {
            check: "ENC-5",
            mode: dc_mode,
        }
    });
    let mut dc_items: Vec<crate::decode_check::DecodeCheckItem<trust_cg_ir::inst::MachInst>> =
        Vec::new();
    let dc_push =
        |items: &mut Vec<crate::decode_check::DecodeCheckItem<trust_cg_ir::inst::MachInst>>,
         start: usize,
         intent: &trust_cg_ir::inst::MachInst,
         hole: Option<crate::decode_check::FixupHole>| {
            if dc_mode != crate::decode_check::DecodeCheckMode::Off {
                items.push(crate::decode_check::DecodeCheckItem {
                    intent: intent.clone(),
                    start,
                    end: start + 4,
                    hole,
                });
            }
        };

    // L04-P12: where each instruction of a recorded trap expansion lands, so
    // the expansion's emitted words can be judged as one unit below.
    let trap_members: BTreeSet<InstId> = func
        .trap_expansions
        .iter()
        .flat_map(|record| record.insts.iter().copied())
        .collect();
    let mut trap_offsets: HashMap<InstId, usize> = HashMap::new();

    for &block_id in &func.block_order {
        // Record the starting byte offset of this block for later jump-table
        // patching (case target blocks resolve against this map).
        let block_byte_offset =
            aarch64_text_offset_u32(&func.name, code.len()).map_err(|offset| {
                PipelineError::Encoding(format!(
                    "function {} block {:?} offset {} exceeds the u32 AArch64 relocation/LSDA domain",
                    func.name, block_id, offset
                ))
            })?;
        block_byte_offsets.insert(block_id, block_byte_offset);

        let block = func.block(block_id);
        for (inst_index, &inst_id) in block.insts.iter().enumerate() {
            if trap_members.contains(&inst_id) {
                trap_offsets.insert(inst_id, code.len());
            }
            let inst = func.inst(inst_id);
            // Fuse binding-shape validation with the existing unresolved-vreg
            // check; legacy instructions get no extra operand traversal.
            for (index, operand) in inst.operands.iter().enumerate() {
                if operand.as_exact_module_symbol().is_some() {
                    let register = |index: usize| {
                        inst.operands
                            .get(index)
                            .and_then(IrOperand::as_preg)
                            .is_some_and(|reg| {
                                preg_class(reg) == RegClass::Gpr64
                                    && trust_cg_ir::aarch64_regs::hw_encoding(reg) < 31
                            })
                    };
                    let supported = match (inst.opcode, index, inst.operands.len()) {
                        (AArch64Opcode::Adrp, 1, 2) => register(0),
                        (AArch64Opcode::AddPCRel, 2, 3) => register(0) && register(1),
                        _ => false,
                    };
                    if !supported {
                        return Err(PipelineError::Encoding(format!(
                            "exact module function symbol is unsupported at {:?} operand {index}",
                            inst.opcode
                        )));
                    }
                }
                if !inst.is_pseudo()
                    && let IrOperand::VReg(vreg) = operand
                {
                    return Err(PipelineError::Encoding(format!(
                        "unresolved vreg {} reached encode in function {} block {:?} inst {:?} operand {} opcode {:?} operands {:?}",
                        vreg.id, func.name, block_id, inst_id, index, inst.opcode, inst.operands
                    )));
                }
            }
            // Skip pseudo-instructions that should have been eliminated.
            if inst.is_pseudo() {
                continue;
            }

            let byte_offset =
                aarch64_text_offset_u32(&func.name, code.len()).map_err(|offset| {
                    PipelineError::Encoding(format!(
                        "function {} instruction {:?} offset {} exceeds the u32 AArch64 relocation/LSDA domain",
                        func.name, inst_id, offset
                    ))
                })?;

            // Check for BL/B with Symbol operand — needs a relocation fixup.
            let has_symbol_target = matches!(
                inst.opcode,
                AArch64Opcode::Bl | AArch64Opcode::BL | AArch64Opcode::B | AArch64Opcode::TailCall
            ) && inst.operands.first().is_some_and(|op| op.is_symbol());
            let adrp_symbol = if inst.opcode == AArch64Opcode::Adrp {
                inst.operands.get(1).and_then(|op| {
                    op.as_symbol()
                        .map(|name| (name, false))
                        .or_else(|| op.as_exact_module_symbol().map(|name| (name, true)))
                })
            } else {
                None
            };
            let pageoff_symbol = if matches!(
                inst.opcode,
                AArch64Opcode::AddPCRel
                    | AArch64Opcode::LdrGot
                    | AArch64Opcode::LdrTlvp
                    | AArch64Opcode::LdrGottprel
                    | AArch64Opcode::LdrTlsdesc
                    | AArch64Opcode::AddTprelHi12
                    | AArch64Opcode::AddTprelLo12
                    | AArch64Opcode::AddTlsdescLo12
            ) {
                inst.operands.get(2).and_then(|op| {
                    op.as_symbol()
                        .map(|name| (name, false))
                        .or_else(|| op.as_exact_module_symbol().map(|name| (name, true)))
                })
            } else {
                None
            };

            // Fused `LDR/STR Rt, [Xpage, #:lo12:sym]` (see
            // `fuse_elf_lo12_memory_accesses`): an ELF LDST lo12 fixup.
            let lo12_memory = lo12_memory_symbol_operand(inst);

            // Check for ADR with JumpTableIndex operand — emit placeholder,
            // patch the imm21 after we know the table byte offset.
            let adr_jt_idx = func.jump_table_at_address(inst_id);

            if has_symbol_target {
                // Emit BL/B with imm26=0 (placeholder — linker will patch via relocation).
                let op_bit = match inst.opcode {
                    AArch64Opcode::B | AArch64Opcode::TailCall => 0u32,
                    _ => 1u32, // Bl and BL are both BL
                };
                let placeholder = crate::aarch64::encoding::encode_uncond_branch(op_bit, 0);
                code.extend_from_slice(&placeholder.to_le_bytes());
                dc_push(
                    &mut dc_items,
                    byte_offset as usize,
                    inst,
                    Some(crate::decode_check::FixupHole {
                        offset_in_inst: 0,
                        width: 4,
                        kind: crate::decode_check::FixupHoleKind::Call,
                    }),
                );

                // Record a Branch26 fixup. The symbol name is stored in the fixup
                // target — the module-level emitter resolves it to a symbol index.
                let sym_name = inst.operands[0].as_symbol().ok_or_else(|| {
                    PipelineError::Encoding(format!(
                        "BL/B instruction at offset {} has non-symbol operand",
                        byte_offset
                    ))
                })?;
                let fixup = if inst
                    .flags
                    .contains(trust_cg_ir::inst::InstFlags::EXACT_MODULE_CALL)
                {
                    Fixup::branch_exact_sym(byte_offset, sym_name.to_string())
                } else {
                    Fixup::branch_sym(byte_offset, sym_name.to_string())
                };
                fixups.push(fixup);
                if let Some(sites) = fixup_sites.as_deref_mut() {
                    sites.push(EncodedAarch64FixupSite {
                        fixup_index: fixups.len() - 1,
                        block: block_id,
                        inst: inst_id,
                        offset: byte_offset,
                        opcode: inst.opcode,
                        placeholder_word: placeholder,
                    });
                }
            } else if let Some((sym_name, exact)) = adrp_symbol {
                let rd_preg = inst.operands[0].as_preg().ok_or_else(|| {
                    PipelineError::Encoding(format!(
                        "ADRP instruction at offset {} has no PReg destination",
                        byte_offset
                    ))
                })?;
                let rd = trust_cg_ir::aarch64_regs::hw_encoding(rd_preg);
                let placeholder = crate::aarch64::encoding_mem::encode_adrp(0, rd)
                    .map_err(|e| PipelineError::Encoding(e.to_string()))?;
                code.extend_from_slice(&placeholder.to_le_bytes());
                dc_push(
                    &mut dc_items,
                    byte_offset as usize,
                    inst,
                    Some(crate::decode_check::FixupHole {
                        offset_in_inst: 0,
                        width: 4,
                        kind: crate::decode_check::FixupHoleKind::GlobalRef,
                    }),
                );
                let paired_kind = (!exact)
                    .then(|| {
                        paired_symbolic_adrp_reloc_kind(
                            func,
                            &block.insts,
                            inst_index,
                            rd_preg,
                            sym_name,
                        )
                    })
                    .flatten()
                    .unwrap_or(SymbolicAArch64FixupKind {
                        kind: crate::macho::AArch64RelocKind::Page21,
                        tls_model: None,
                    });
                fixups.push(crate::macho::fixup::Fixup {
                    offset: byte_offset,
                    kind: paired_kind.kind,
                    tls_model: paired_kind.tls_model,
                    target: if exact {
                        crate::macho::FixupTarget::ExactNamedSymbol(sym_name.to_string())
                    } else {
                        crate::macho::FixupTarget::NamedSymbol(sym_name.to_string())
                    },
                    addend: 0,
                });
                if let Some(sites) = fixup_sites.as_deref_mut() {
                    sites.push(EncodedAarch64FixupSite {
                        fixup_index: fixups.len() - 1,
                        block: block_id,
                        inst: inst_id,
                        offset: byte_offset,
                        opcode: inst.opcode,
                        placeholder_word: placeholder,
                    });
                }
            } else if let Some((sym_name, exact)) = pageoff_symbol {
                let sf = if inst
                    .operands
                    .first()
                    .and_then(|op| op.as_preg())
                    .is_some_and(|preg| preg_class(preg) == RegClass::Gpr64)
                {
                    1
                } else {
                    0
                };
                let word = match inst.opcode {
                    AArch64Opcode::AddPCRel => crate::aarch64::encoding::encode_add_sub_imm(
                        sf,
                        0,
                        0,
                        0,
                        0,
                        trust_cg_ir::aarch64_regs::hw_encoding(
                            inst.operands[1].as_preg().ok_or_else(|| {
                                PipelineError::Encoding(format!(
                                    "ADD PC-relative instruction at offset {} has no PReg base",
                                    byte_offset
                                ))
                            })?,
                        ) as u32,
                        trust_cg_ir::aarch64_regs::hw_encoding(
                            inst.operands[0].as_preg().ok_or_else(|| {
                                PipelineError::Encoding(format!(
                                    "ADD PC-relative instruction at offset {} has no PReg destination",
                                    byte_offset
                                ))
                            })?,
                        ) as u32,
                    ),
                    // ELF local-exec TLS TPREL adds: `ADD Xd, Xn, #0 (, LSL
                    // #12)` placeholders; the linker patches imm12 via
                    // `R_AARCH64_TLSLE_ADD_TPREL_HI12` / `_LO12_NC`. The hi12
                    // half sets sh=1 (LSL #12), matching gcc/binutils
                    // local-exec codegen (0x91400000 / 0x91000000 skeletons).
                    // The TLSDESC descriptor-address add has the same
                    // `ADD Xd, Xn, #0` skeleton (sh=0), patched by
                    // `R_AARCH64_TLSDESC_ADD_LO12`.
                    AArch64Opcode::AddTprelHi12
                    | AArch64Opcode::AddTprelLo12
                    | AArch64Opcode::AddTlsdescLo12 => {
                        crate::aarch64::encoding::encode_add_sub_imm(
                            sf,
                            0,
                            0,
                            (inst.opcode == AArch64Opcode::AddTprelHi12) as u32,
                            0,
                            trust_cg_ir::aarch64_regs::hw_encoding(
                                inst.operands[1].as_preg().ok_or_else(|| {
                                    PipelineError::Encoding(format!(
                                        "ADD TPREL instruction at offset {} has no PReg base",
                                        byte_offset
                                    ))
                                })?,
                            ) as u32,
                            trust_cg_ir::aarch64_regs::hw_encoding(
                                inst.operands[0].as_preg().ok_or_else(|| {
                                    PipelineError::Encoding(format!(
                                        "ADD TPREL instruction at offset {} has no PReg destination",
                                        byte_offset
                                    ))
                                })?,
                            ) as u32,
                        )
                    }
                    AArch64Opcode::LdrGot
                    | AArch64Opcode::LdrTlvp
                    | AArch64Opcode::LdrGottprel
                    | AArch64Opcode::LdrTlsdesc => {
                        crate::aarch64::encoding::encode_load_store_ui(
                            0b11,
                            0,
                            0b01,
                            0,
                            trust_cg_ir::aarch64_regs::hw_encoding(
                                inst.operands[1].as_preg().ok_or_else(|| {
                                    PipelineError::Encoding(format!(
                                        "LDR symbolic instruction at offset {} has no PReg base",
                                        byte_offset
                                    ))
                                })?,
                            ) as u32,
                            trust_cg_ir::aarch64_regs::hw_encoding(
                                inst.operands[0].as_preg().ok_or_else(|| {
                                    PipelineError::Encoding(format!(
                                        "LDR symbolic instruction at offset {} has no PReg destination",
                                        byte_offset
                                    ))
                                })?,
                            ) as u32,
                        )
                    }
                    _ => unreachable!(),
                };
                code.extend_from_slice(&word.to_le_bytes());
                dc_push(
                    &mut dc_items,
                    byte_offset as usize,
                    inst,
                    Some(crate::decode_check::FixupHole {
                        offset_in_inst: 0,
                        width: 4,
                        kind: crate::decode_check::FixupHoleKind::GlobalRef,
                    }),
                );
                // Fail-closed pairing symmetry: a GOT/TLVP page-offset LDR
                // whose base is not fed by a same-symbol ADRP in this block
                // would emit a mixed direct/GOT relocation pair (wild load).
                if matches!(
                    inst.opcode,
                    AArch64Opcode::LdrGot
                        | AArch64Opcode::LdrTlvp
                        | AArch64Opcode::LdrGottprel
                        | AArch64Opcode::LdrTlsdesc
                ) {
                    let base_preg = inst.operands[1].as_preg().ok_or_else(|| {
                        PipelineError::Encoding(format!(
                            "LDR symbolic instruction at offset {} has no PReg base",
                            byte_offset
                        ))
                    })?;
                    verify_got_ldr_page_pairing(
                        func,
                        &block.insts,
                        inst_index,
                        base_preg,
                        sym_name,
                    )?;
                }
                let kind = match inst.opcode {
                    AArch64Opcode::AddPCRel => crate::macho::AArch64RelocKind::Pageoff12,
                    AArch64Opcode::LdrGot => crate::macho::AArch64RelocKind::GotLoadPageoff12,
                    AArch64Opcode::LdrTlvp => crate::macho::AArch64RelocKind::TlvpLoadPageoff12,
                    AArch64Opcode::LdrGottprel => {
                        crate::macho::AArch64RelocKind::ElfTlsieLd64GottprelLo12Nc
                    }
                    AArch64Opcode::AddTprelHi12 => {
                        crate::macho::AArch64RelocKind::ElfTlsleAddTprelHi12
                    }
                    AArch64Opcode::AddTprelLo12 => {
                        crate::macho::AArch64RelocKind::ElfTlsleAddTprelLo12Nc
                    }
                    AArch64Opcode::LdrTlsdesc => crate::macho::AArch64RelocKind::ElfTlsdescLd64Lo12,
                    AArch64Opcode::AddTlsdescLo12 => {
                        crate::macho::AArch64RelocKind::ElfTlsdescAddLo12
                    }
                    _ => unreachable!(),
                };
                let tls_model = match inst.opcode {
                    AArch64Opcode::LdrTlvp => Some(trust_cg_ir::TlsModel::Tlv),
                    AArch64Opcode::LdrGottprel => Some(trust_cg_ir::TlsModel::InitialExec),
                    AArch64Opcode::LdrTlsdesc | AArch64Opcode::AddTlsdescLo12 => {
                        Some(trust_cg_ir::TlsModel::GeneralDynamic)
                    }
                    AArch64Opcode::AddTprelHi12 | AArch64Opcode::AddTprelLo12 => {
                        Some(trust_cg_ir::TlsModel::LocalExec)
                    }
                    _ => None,
                };
                fixups.push(crate::macho::fixup::Fixup {
                    offset: byte_offset,
                    kind,
                    tls_model,
                    target: if exact {
                        crate::macho::FixupTarget::ExactNamedSymbol(sym_name.to_string())
                    } else {
                        crate::macho::FixupTarget::NamedSymbol(sym_name.to_string())
                    },
                    addend: 0,
                });
                if let Some(sites) = fixup_sites.as_deref_mut() {
                    sites.push(EncodedAarch64FixupSite {
                        fixup_index: fixups.len() - 1,
                        block: block_id,
                        inst: inst_id,
                        offset: byte_offset,
                        opcode: inst.opcode,
                        placeholder_word: word,
                    });
                }
            } else if inst.opcode == AArch64Opcode::BlrTlsdesc {
                // The resolver call of a TLSDESC sequence: an ordinary
                // `BLR x1` word (no relocated bits) annotated with
                // `R_AARCH64_TLSDESC_CALL` so the static linker can relax the
                // sequence. The full four-slot shape is verified first.
                let symbol = verify_tlsdesc_call_sequence(func, &block.insts, inst_index)?;
                let blr = IrMachInst::new(AArch64Opcode::Blr, vec![inst.operands[0].clone()]);
                let word = encode_ir_inst(&blr)?;
                code.extend_from_slice(&word.to_le_bytes());
                dc_push(&mut dc_items, byte_offset as usize, inst, None);
                fixups.push(crate::macho::fixup::Fixup {
                    offset: byte_offset,
                    kind: crate::macho::AArch64RelocKind::ElfTlsdescCall,
                    tls_model: Some(trust_cg_ir::TlsModel::GeneralDynamic),
                    target: crate::macho::FixupTarget::NamedSymbol(symbol),
                    addend: 0,
                });
                if let Some(sites) = fixup_sites.as_deref_mut() {
                    sites.push(EncodedAarch64FixupSite {
                        fixup_index: fixups.len() - 1,
                        block: block_id,
                        inst: inst_id,
                        offset: byte_offset,
                        opcode: inst.opcode,
                        placeholder_word: word,
                    });
                }
            } else if let Some((sym_name, access_size)) = lo12_memory {
                let base = inst.operands[1].as_preg().ok_or_else(|| {
                    PipelineError::Encoding(format!(
                        "lo12 memory access at offset {byte_offset} has no PReg base"
                    ))
                })?;
                verify_lo12_memory_page_pairing(func, &block.insts, inst_index, base, sym_name)?;
                let kind = crate::macho::AArch64RelocKind::elf_ldst_lo12_for_access_size(
                    access_size,
                )
                .ok_or_else(|| {
                    PipelineError::Encoding(format!(
                        "lo12 memory access at offset {byte_offset} has unsupported size {access_size}"
                    ))
                })?;
                // Encode the unsigned-offset form with a zero imm12 the
                // linker overwrites with the scaled low-12 bits of `S`.
                let mut placeholder_inst = inst.clone();
                placeholder_inst.operands[2] = IrOperand::Imm(0);
                let word = encode_ir_inst(&placeholder_inst)?;
                if (word >> 27) & 0b111 != 0b111
                    || (word >> 24) & 0b11 != 0b01
                    || (word >> 10) & 0xFFF != 0
                {
                    return Err(PipelineError::Encoding(format!(
                        "lo12 memory access at offset {byte_offset} did not encode as an unsigned-offset load/store with a zero imm12 ({word:#010x})"
                    )));
                }
                // The linker scales the LDST field by the relocation kind's
                // access size and the CPU by the word's own size/V/opc
                // fields; the two must agree or the access lands on another
                // address. Read the scale back from the encoded word.
                let word_scale =
                    if (word >> 26) & 1 == 1 && word >> 30 == 0 && (word >> 23) & 1 == 1 {
                        16
                    } else {
                        1u32 << (word >> 30)
                    };
                if word_scale != access_size {
                    return Err(PipelineError::Encoding(format!(
                        "lo12 memory access at offset {byte_offset} carries {kind:?} for a {access_size}-byte access, but the encoded word {word:#010x} scales its offset by {word_scale} (fail-closed: the relocation and the instruction must agree)"
                    )));
                }
                code.extend_from_slice(&word.to_le_bytes());
                dc_push(
                    &mut dc_items,
                    byte_offset as usize,
                    inst,
                    Some(crate::decode_check::FixupHole {
                        offset_in_inst: 0,
                        width: 4,
                        kind: crate::decode_check::FixupHoleKind::GlobalRef,
                    }),
                );
                fixups.push(crate::macho::fixup::Fixup {
                    offset: byte_offset,
                    kind,
                    tls_model: None,
                    target: crate::macho::FixupTarget::NamedSymbol(sym_name.to_string()),
                    addend: 0,
                });
                if let Some(sites) = fixup_sites.as_deref_mut() {
                    sites.push(EncodedAarch64FixupSite {
                        fixup_index: fixups.len() - 1,
                        block: block_id,
                        inst: inst_id,
                        offset: byte_offset,
                        opcode: inst.opcode,
                        placeholder_word: word,
                    });
                }
            } else if let Some(jt_idx) = adr_jt_idx {
                // Emit ADR with imm21=0 (placeholder); record fixup so we can
                // patch it after the jump table is appended below.
                let rd_preg = inst.operands[0].as_preg().ok_or_else(|| {
                    PipelineError::Encoding(format!(
                        "Adr instruction at offset {} has no PReg destination",
                        byte_offset
                    ))
                })?;
                let rd = trust_cg_ir::aarch64_regs::hw_encoding(rd_preg);
                let expanded = func.jump_table_address_expansions.contains_key(&inst_id);
                let placeholder = if expanded {
                    // The literal ADR/ADD pair is already final. Keep the
                    // table encounter but never patch the ADR back to an
                    // out-of-range full displacement or invent a relocation.
                    encode_ir_inst(inst)?
                } else {
                    crate::aarch64::encoding_mem::encode_adr(0, rd)
                        .map_err(|e| PipelineError::Encoding(e.to_string()))?
                };
                code.extend_from_slice(&placeholder.to_le_bytes());
                jt_adr_fixups.push((byte_offset, jt_idx, expanded));
                // The ADR word is patched in-function below, BEFORE the
                // decode-check runs, so its bytes are final — no hole.
                dc_push(&mut dc_items, byte_offset as usize, inst, None);
            } else {
                let word = encode_ir_inst(inst).map_err(|err| match err {
                    PipelineError::Encoding(msg) => PipelineError::Encoding(format!(
                        "{msg} in function {} block {:?} inst {:?} opcode {:?} operands {:?}",
                        func.name, block_id, inst_id, inst.opcode, inst.operands
                    )),
                    other => other,
                })?;
                code.extend_from_slice(&word.to_le_bytes());
                dc_push(&mut dc_items, byte_offset as usize, inst, None);
            }

            // This encoder is the authority behind EH's exact InstId -> byte
            // re-derivation: every non-pseudo AArch64 instruction must emit one
            // and only one fixed-width word before any trailing jump-table data.
            // Keep that contract executable so a future multiword expansion
            // fails closed instead of making LSDA ranges drift silently.
            let expected_end = usize::try_from(byte_offset)
                .ok()
                .and_then(|offset| offset.checked_add(4))
                .ok_or_else(|| {
                    PipelineError::Encoding(format!(
                        "function {} instruction {:?} encoded-end calculation overflow",
                        func.name, inst_id
                    ))
                })?;
            if code.len() != expected_end {
                return Err(PipelineError::Encoding(format!(
                    "function {} instruction {:?} emitted {} bytes; exact AArch64 layout requires 4",
                    func.name,
                    inst_id,
                    code.len().saturating_sub(byte_offset as usize)
                )));
            }

            if let Some(provenance) = provenance.as_deref_mut() {
                provenance.record_encoding(inst_id, byte_offset);
            }
        }
    }

    // Emit jump tables after the function body and patch the corresponding
    // ADR instructions.
    //
    // Layout: each table lives in the same __text section, placed right
    // after the function body. Entries are 32-bit signed offsets from the
    // table base to the case target block: `target_byte_offset -
    // table_base_byte_offset`. At runtime, the switch computes:
    //   x_base = table_base_addr (via ADR)
    //   x_off  = sign_extend_32(table[index])
    //   br     x_base + x_off
    for (adr_offset, jt_idx, expanded) in &jt_adr_fixups {
        let jt = func.jump_tables.get(*jt_idx as usize).ok_or_else(|| {
            PipelineError::Encoding(format!(
                "ADR at {:#x} references unknown jump table index {}",
                adr_offset, jt_idx
            ))
        })?;

        // The table is appended at the current end of the code buffer. Each
        // ADR may reference its own (possibly distinct) table; we allocate
        // one table per fixup in the order they appeared.
        //
        // Note: if two ADRs reference the same `jt_idx`, only the first
        // emission writes the table; subsequent ADRs still patch against
        // the same table_offset (see `placed_tables` map).
        let table_offset = aarch64_text_offset_u32(&func.name, code.len()).map_err(|offset| {
            PipelineError::Encoding(format!(
                "function {} jump-table offset {} exceeds the u32 AArch64 relocation domain",
                func.name, offset
            ))
        })?;

        // Patch the ADR imm21 with the byte offset from the ADR to the table.
        let pc_relative = table_offset as i64 - *adr_offset as i64;
        if !*expanded && !(-(1 << 20)..(1 << 20)).contains(&pc_relative) {
            return Err(PipelineError::Encoding(format!(
                "ADR->jump table offset {} does not fit in imm21",
                pc_relative
            )));
        }
        // Re-extract the destination register from the placeholder encoding:
        // bits[4:0] hold Rd. Simpler: decode the placeholder we already
        // wrote.
        let placeholder_bytes = &code[*adr_offset as usize..(*adr_offset as usize + 4)];
        let placeholder_word = u32::from_le_bytes([
            placeholder_bytes[0],
            placeholder_bytes[1],
            placeholder_bytes[2],
            placeholder_bytes[3],
        ]);
        let rd = (placeholder_word & 0x1F) as u8;
        if !*expanded {
            let patched = crate::aarch64::encoding_mem::encode_adr(pc_relative as i32, rd)
                .map_err(|e| PipelineError::Encoding(e.to_string()))?;
            code[*adr_offset as usize..(*adr_offset as usize + 4)]
                .copy_from_slice(&patched.to_le_bytes());
        }

        // Append the table entries: 32-bit signed offsets from the table
        // base to each target block.
        for target in &jt.targets {
            let target_offset = block_byte_offsets.get(target).copied().ok_or_else(|| {
                PipelineError::Encoding(format!(
                    "Jump table target block {:?} has no byte offset",
                    target
                ))
            })?;
            let entry =
                i32::try_from(target_offset as i64 - table_offset as i64).map_err(|_| {
                    PipelineError::Encoding("jump-table entry exceeds signed32 range".into())
                })?;
            code.extend_from_slice(&entry.to_le_bytes());
        }
    }

    // ENC-5: run the independent decode-check over the FINAL bytes (after
    // the in-function jump-table ADR patches; linker-patched words carry
    // holes). Enforce failures are fail-closed pipeline errors. The a64
    // default is ENFORCE (`a64_decode_check_mode`: any unset or unrecognized
    // `TCG_DECODE_CHECK_A64` enforces); `=warn`/`=off` or `TCG_NO_DECODE_CHECK`
    // relax it, and relaxing it is diagnostic policy, not evidence.
    // Proof-grade routes also refuse any emitted word ENC-5 did not decode
    // (an `Allowlisted` outcome); compatibility routes count it.
    crate::decode_check::run_decode_check_with_allowlist_policy(
        &crate::aarch64::decode_check::A64DecodeCheck,
        &dc_items,
        &code,
        dc_mode,
        match integrity_policy {
            Aarch64IntegrityPolicy::Compatibility => crate::decode_check::AllowlistPolicy::Count,
            Aarch64IntegrityPolicy::ProofGradeEnforce => {
                crate::decode_check::AllowlistPolicy::Refuse
            }
        },
    )
    .map_err(|err| PipelineError::Encoding(err.message))?;
    check_aarch64_trap_expansions(func, &trap_offsets, &code, dc_mode)?;
    // Diagnostic census of the emitted forms (`TCG_DECODE_CHECK_CENSUS_DIR`);
    // a no-op unless set, and it changes no byte or verdict.
    crate::aarch64::decode_census::record_a64_decode_census(
        &dc_items,
        &code,
        integrity_policy == Aarch64IntegrityPolicy::ProofGradeEnforce,
    );

    // Re-derive every branch, ADR, literal, jump-table and fixup offset from
    // the final layout and compare it with the encoded words. Proof-grade
    // routes additionally bind every encoded edge to the recorded CFG.
    crate::aarch64::layout_crosscheck::check_final_layout(
        func,
        &code,
        Some(&fixups),
        &block_byte_offsets,
        integrity_policy == Aarch64IntegrityPolicy::ProofGradeEnforce,
    )
    .map_err(|error| PipelineError::Aarch64LayoutCrossCheck {
        function: func.name.clone(),
        error,
    })?;

    // Bind every switch dispatch to the final bytes independently of the
    // encoder: each jump-table entry, the ADR/LDRSW/ADD/BR register chain,
    // the CMP/B.HI bounds check and SUB normalization, every compare whose
    // flags reach a B.cond, and every fused CBZ/CBNZ/TBZ/TBNZ. Every route
    // fails closed on a refusal.
    trust_cg_verify::aarch64_switch_binding::check_aarch64_switch_dispatch(func, &code).map_err(
        |error| PipelineError::Aarch64SwitchBinding {
            function: func.name.clone(),
            error,
        },
    )?;

    Ok((code, fixups, block_byte_offsets))
}

fn macho_symbol_name(name: &str) -> String {
    format!("_{}", name)
}

// Preserve the established pipeline paths for the runtime's exported symbols.
pub use crate::aot_profile::{PGO_COUNTER_ARRAY_SYMBOL, PGO_NSITES_SYMBOL};

/// Plan and commit AOT instrumentation without partial code/metadata on refusal.
fn inject_aot_block_counters(
    func: &mut IrMachFunction,
    sink: &Arc<std::sync::Mutex<trust_cg_opt::pgo::CounterMap>>,
) -> Result<(), PipelineError> {
    // The counter-index ceiling is the unsigned scaled imm12 offset of the
    // instrumentation's own LdrRI/StrRI, checked by `aot_profile::inject` before
    // any register allocation, encoding or object writing: a machine-code
    // instrumentation refusal. It used to be re-labelled
    // `Aarch64ObjectFieldTooLarge`, whose message ("AArch64 object field ...
    // cannot represent byte count 4096") named an object field and called the
    // counter INDEX a byte count, and whose variant classifies as the object
    // layer. It now keeps its own `AotProfileError`, whose message carries the
    // same "LdrRI/StrRI scaled offset ceiling" reason (AD-8).
    //
    // L10-P5: the injection numbers its registers and instructions from the
    // counters; a stale one is refused here by name rather than raised past
    // the live IDs by `aot_profile`'s own register range.
    admit_mach_ids(func, "AOT profile instrumentation entry")?;
    crate::aot_profile::inject(func, sink).map_err(PipelineError::AotProfile)
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ObjectGlobal {
    pub name: String,
    pub data: Vec<u8>,
    pub mutable: bool,
    /// Whether this global's symbol is EXTERNALLY visible (exported from the
    /// object) rather than module-local. Mirrors the trust-ir global's linkage:
    /// `External` / weak / link-once map to `true`; `Internal` / `Private` map to
    /// `false`. A `MonoItem::Static` defined under its own (`#[no_mangle]` or
    /// mangled) symbol needs `true` so a reader in another object / crate / C
    /// driver can resolve it via a data relocation; a private const-alloc copy
    /// (vtable / string literal) is `false`. The Mach-O emitters pass this as the
    /// symbol's `is_global` flag.
    pub is_external: bool,
    /// Relocatable pointer-sized elements embedded in this global's `data`.
    ///
    /// Each entry records that the 8 bytes of `data` starting at `offset` are a
    /// placeholder for the run-time address of `symbol` (a function or data
    /// global, defined-in-module or external) plus `addend`. The object writer
    /// turns each into a data-section absolute-pointer relocation
    /// (`X86_64_RELOC_UNSIGNED` on Mach-O, `R_X86_64_64` on ELF). This is the
    /// vtable / `static FNS: [fn(); N]` keystone: a global whose slots are
    /// symbol addresses the linker fills in. Empty for plain byte globals.
    /// On an AArch64 thread-local DEFINITION the slots relocate the
    /// initial-value template (each thread's copy starts with the fixed-up
    /// pointer): `ARM64_RELOC_UNSIGNED` in Mach-O `__DATA,__thread_data`,
    /// `R_AARCH64_ABS64` in ELF `.rela.tdata`. The x86-64 Mach-O emitter
    /// refuses a relocated template by name. On AArch64 no slot may name a
    /// thread-local (`[TCG-TLS-SLOT-TARGET]`).
    pub symbol_refs: Vec<GlobalSymbolRef>,
    /// Whether this global is thread-local. When `true` the AArch64 Mach-O
    /// emitter routes this global to the Darwin thread-local sections
    /// (`__thread_data` holds the initial-value template; `__thread_vars` holds
    /// the `tlv_descriptor` symbol a `#[thread_local]` read addresses via the
    /// `ARM64_RELOC_TLVP_LOAD_PAGE21`/`PAGEOFF12` relocations) instead of
    /// `__data`/`__const`. The specific dynamic TLS model is resolved earlier,
    /// during ISel (`TlsModel::Tlv`); object emission only needs the flag.
    /// The AArch64 ELF emitters place thread-local definitions in
    /// `.tdata`/`.tbss` with `STT_TLS` symbols; the x86-64 ELF emitter refuses
    /// every thread-local definition.
    pub is_thread_local: bool,
    /// Whether this global is an IMPORT — a reference to a symbol DEFINED in
    /// another object, not a definition emitted here. An import contributes no
    /// section bytes and no defining symbol; its only effect is that a fixup
    /// against its `name` resolves to an undefined-external symbol the linker
    /// satisfies from the defining object.
    ///
    /// This is the cross-object thread-local path: a `#[thread_local]` static is
    /// emitted (its `tlv_descriptor` defined) exactly once, in its own object;
    /// every OTHER object that READS it carries an import of that descriptor
    /// symbol so the `__text` TLVP relocation (`Opcode::TlsRef`) resolves to the
    /// single canonical descriptor rather than defining a duplicate (which would
    /// be a link-time duplicate-symbol error, or divergent per-object storage).
    /// An import is necessarily `is_external` and has empty `data`.
    pub is_import: bool,
    /// Whether this global's DEFINITION is WEAK (coalescable / overridable).
    ///
    /// Mirrors the trust-ir global's linkage: `Weak` / `LinkOnce` (link-once ODR)
    /// map to `true`; `External` / `Internal` / `Private` map to `false`. A weak
    /// defined symbol is emitted with the Mach-O `N_WEAK_DEF` (`n_desc` `0x0080`)
    /// flag / the ELF `STB_WEAK` binding, so that MULTIPLE objects each defining
    /// the same symbol COALESCE to one at link time instead of raising a
    /// duplicate-strong-definition error. This is the keystone of the
    /// cross-static `ptr::eq` fix: a promoted/merged immutable `static` referenced
    /// by another `static` is emitted ONCE as a canonical weak symbol that every
    /// reader imports (so all `&A` sites share one address), and any duplicate
    /// promotion of it coalesces rather than dup-strong-erroring.
    ///
    /// On an IMPORT (`is_import == true`) it marks a WEAK UNDEFINED reference
    /// (trust-ir `ExternalWeak`): the address reads as null when no object
    /// defines the symbol. Only the AArch64 ELF emitters spell that (`STB_WEAK`
    /// with `st_shndx == SHN_UNDEF`); every other object path refuses a weak
    /// import rather than emit it strong. A thread-local import is never weak.
    /// Weak necessarily implies `is_external` (a module-local symbol has
    /// nothing to coalesce against or to leave unresolved).
    pub is_weak: bool,
    /// Byte alignment of this global's storage, a power of two (>= 1).
    ///
    /// Taken from the trust-ir `Global.align` (an explicit `#[repr(align(N))]` /
    /// SIMD over-alignment request) when present, else derived from the global's
    /// type layout. The Mach-O / ELF global-section emitters align each global's
    /// section offset UP to this value and widen the owning section's alignment
    /// to the max seen, so an over-aligned static lands on a correctly-aligned
    /// address instead of being packed back-to-back at the section base.
    pub align: u32,
    /// trust-ir v41 `Global.visibility`, honored on a DEFINITION: Mach-O
    /// `N_PEXT` (private extern) for `Hidden`; ELF `STV_HIDDEN` /
    /// `STV_PROTECTED`. Mach-O has no protected visibility, so `Protected` is
    /// default there (as in LLVM's Mach-O lowering — two-level namespaces
    /// already make every symbol non-preemptible). On a LOCAL definition the
    /// flag is vacuous. On an IMPORT only the AArch64 ELF emitters spell it,
    /// as `STV_HIDDEN`/`STV_PROTECTED` on the undefined symbol (the linker
    /// then requires the definition in the output being linked, or resolves
    /// an absent weak one to 0); every other object path refuses a
    /// non-default import (validated). Its address still comes from the GOT,
    /// as for every undefined reference
    /// ([`trust_cg_lower::RelocationModel::symbol_address_is_got_indirect`]).
    pub visibility: trust_ir::Visibility,
    /// trust-ir v41 `Global.retained` (`#[used]`, LLVM's `@llvm.used`): the
    /// linker must keep this DEFINITION even with no reference to it, and
    /// nothing else. Mach-O: per-symbol `N_NO_DEAD_STRIP`. ELF: the
    /// definition gets a section of its own (`<implicit base>.<symbol>`, or
    /// its explicit name), flagged `SHF_GNU_RETAIN`, with the GNU OSABI, as
    /// LLVM places an `@llvm.used` global. `SHF_GNU_RETAIN` keeps a whole
    /// input section, so a retained global packed with others would keep
    /// them, and the undefined references their bytes hold, through
    /// `--gc-sections`.
    ///
    /// On an IMPORT (a declaration LLVM lists in `@llvm.used`) it has no
    /// bytes to retain. The AArch64 and x86-64 ELF emitters write nothing
    /// for it, as llc 22's
    /// ELF writer does (its `AsmPrinter` emits `@llvm.used` only as Mach-O's
    /// `.no_dead_strip`, and `SHF_GNU_RETAIN` marks only a definition's
    /// section): the import is an undefined symbol exactly when something
    /// references it or its visibility or weakness puts it in the table.
    /// The AArch64 Mach-O emitter, the JIT data image and the x86-64 Mach-O
    /// and COFF emitters refuse it (validated): llc's Mach-O writer gives
    /// every listed declaration an `N_NO_DEAD_STRIP` undefined symbol and
    /// its COFF writer a `/INCLUDE:` directive, referenced or not, which
    /// those emitters do not write. (The RISC-V path, which emits no module
    /// data, writes nothing for an unreferenced one, as llc's ELF writer.)
    pub retained: bool,
    /// trust-ir v41 `Global.section`: the explicit output section this
    /// DEFINITION must land in (`None` = placement by mutability/initializer).
    ///
    /// The AArch64 ELF emitters honor a validated name with flags derived
    /// from the section's kind and the global's mutability/TLS, including
    /// `.init_array`/`.fini_array`/`.preinit_array` constructor tables; the
    /// AArch64 Mach-O emitter honors a valid `segment,section` pair
    /// (including `__DATA,__mod_init_func`). Every name an emitter cannot
    /// honor is refused with a named `[TCG-SECTION-*]` diagnostic
    /// ([`crate::object_sections`]); the x86-64 emitters refuse every explicit
    /// section. An IMPORT must be `None` (validated): it places no bytes here.
    pub section: Option<String>,
    /// Whether this weak DEFINITION is a COMDAT (trust-ir `LinkOnce`,
    /// `LinkOnceOdr` or `WeakOdr` linkage): on AArch64 ELF it is placed in its
    /// own section inside a `GRP_COMDAT` group whose signature is the symbol,
    /// so the linker keeps ONE copy of its storage, not only of its symbol.
    /// A zero-fill COMDAT definition's section is `SHT_NOBITS` (`.bss.X`,
    /// `.tbss.X`) and takes no file bytes.
    /// Mach-O has no section groups; `N_WEAK_DEF` coalescing is its
    /// equivalent and already applies through [`Self::is_weak`]. Requires
    /// `is_weak` (validated).
    pub comdat: bool,
}

impl ObjectGlobal {
    /// Whether every address of this global must come from the GOT under
    /// `relocation_model`, by the one address predicate
    /// ([`trust_cg_lower::RelocationModel::symbol_address_is_got_indirect`]):
    /// an import (an undefined reference, GOT-indirect whatever its binding),
    /// or a definition another module may preempt. The AArch64 ELF `pic`
    /// backstop refuses a PC-relative page reference to such a global.
    #[must_use]
    pub const fn binds_outside_object_under(
        &self,
        relocation_model: trust_cg_lower::RelocationModel,
    ) -> bool {
        let binding = if self.is_import {
            trust_cg_lower::SymbolBinding::Undefined { weak: self.is_weak }
        } else if self.is_external {
            trust_cg_lower::SymbolBinding::Defined(trust_cg_lower::DefinitionBinding::Global)
        } else {
            trust_cg_lower::SymbolBinding::Defined(trust_cg_lower::DefinitionBinding::Local)
        };
        relocation_model.symbol_address_is_got_indirect(binding, self.visibility)
    }
}

/// The ELF `STV_*` value for a trust-ir visibility.
pub(crate) const fn elf_symbol_visibility(visibility: trust_ir::Visibility) -> u8 {
    use crate::elf::constants::{STV_DEFAULT, STV_HIDDEN, STV_PROTECTED};
    match visibility {
        trust_ir::Visibility::Default => STV_DEFAULT,
        trust_ir::Visibility::Hidden => STV_HIDDEN,
        trust_ir::Visibility::Protected => STV_PROTECTED,
    }
}

/// `SHF_GNU_RETAIN` for the own section of a `retained` definition, else 0.
/// Only a section holding that one definition may carry it: the ELF
/// emitters never pack a retained global with another
/// ([`ObjectGlobal::retained`]).
pub(crate) const fn elf_retain_flag(global: &ObjectGlobal) -> u64 {
    if global.retained {
        crate::elf::constants::SHF_GNU_RETAIN
    } else {
        0
    }
}

/// A relocatable pointer element inside an [`ObjectGlobal`]'s data.
///
/// See [`ObjectGlobal::symbol_refs`]. The `offset` is relative to the start of
/// the owning global's `data` (the writer adds the global's offset within its
/// emitted section to get the section-relative relocation offset).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct GlobalSymbolRef {
    /// Byte offset of the 8-byte pointer slot within the global's `data`.
    pub offset: u64,
    /// Unmangled name of the target symbol (function or data global).
    pub symbol: String,
    /// Constant byte offset added to the resolved symbol address.
    pub addend: i64,
}

/// Validate the public AArch64 object-global surface before any section writer
/// performs offset arithmetic or mutates an object.
///
/// `module_object_globals` produces these invariants, but the `Pipeline` APIs
/// also accept hand-built `ObjectGlobal` values. Invalid pointer slots used to
/// reach an unchecked slice write in the Mach-O data emitter; reject them as a
/// recoverable pipeline error instead of panicking or emitting ambiguous bytes.
/// A well-formed slot whose target is a declared thread-local is refused too
/// ([`reject_aarch64_pointer_slots_naming_thread_locals`]).
pub(crate) fn validate_aarch64_object_globals(
    globals: &[ObjectGlobal],
) -> Result<(), PipelineError> {
    validate_aarch64_object_globals_with(globals, false)
}

/// [`validate_aarch64_object_globals`] for an object path that is `elf`: the
/// AArch64 ELF emitters write a data import's hidden or protected
/// visibility on its undefined symbol ([`elf_undefined_symbol`]) and, as
/// llc's ELF writer, nothing for an import's `retained` flag
/// ([`ObjectGlobal::retained`]). Mach-O and the JIT data image do neither,
/// and refuse both.
pub(crate) fn validate_aarch64_object_globals_with(
    globals: &[ObjectGlobal],
    elf: bool,
) -> Result<(), PipelineError> {
    const POINTER_SIZE: u64 = 8;
    let mut names = BTreeSet::new();
    for global in globals {
        if global.name.is_empty() {
            return Err(PipelineError::ObjectEmission(
                "AArch64 object global has an empty symbol name (fail-closed)".to_string(),
            ));
        }
        if !names.insert(global.name.as_str()) {
            return Err(PipelineError::ObjectEmission(format!(
                "AArch64 object contains duplicate global symbol `{}` (fail-closed)",
                global.name
            )));
        }
        if global.align == 0 || !global.align.is_power_of_two() {
            return Err(PipelineError::ObjectEmission(format!(
                "AArch64 object global `{}` has invalid alignment {} (expected a non-zero power of two; fail-closed)",
                global.name, global.align
            )));
        }
        if global.is_import
            && (!global.is_external || !global.data.is_empty() || !global.symbol_refs.is_empty())
        {
            return Err(PipelineError::ObjectEmission(format!(
                "AArch64 object global `{}` is an import but carries local bytes, pointer slots, or non-external linkage (fail-closed)",
                global.name
            )));
        }
        if global.is_weak && !global.is_external {
            return Err(PipelineError::ObjectEmission(format!(
                "AArch64 object global `{}` has invalid weak linkage (weak requires an external definition or reference; fail-closed)",
                global.name
            )));
        }
        if global.is_weak && global.is_import && global.is_thread_local {
            return Err(PipelineError::ObjectEmission(format!(
                "AArch64 object global `{}` is a weak thread-local import; no object path emits a weak undefined TLS reference (fail-closed)",
                global.name
            )));
        }
        if global.is_import && global.visibility != trust_ir::Visibility::Default && !elf {
            return Err(PipelineError::ObjectEmission(format!(
                "AArch64 object global `{}` is an import with visibility `{}`; only the ELF emitters spell visibility on an undefined data symbol (fail-closed)",
                global.name, global.visibility
            )));
        }
        if global.is_import && global.retained && !elf {
            return Err(PipelineError::ObjectEmission(format!(
                "AArch64 object global `{}` is an import marked retained (LLVM's `@llvm.used` lists the declaration); only the ELF emitters admit one, writing nothing for the flag as llc's ELF writer does, while llc's Mach-O writer gives it an `N_NO_DEAD_STRIP` undefined symbol, referenced or not, which no other object path writes (fail-closed)",
                global.name
            )));
        }
        if global.is_import
            && let Some(section) = &global.section
        {
            return Err(PipelineError::ExplicitSectionUnsupported {
                global: global.name.clone(),
                section: section.clone(),
                format: "object",
                code: crate::object_sections::SectionRefusal::Import,
                reason: "an import places no bytes in this object".to_string(),
            });
        }
        if global.comdat && !global.is_weak {
            return Err(PipelineError::ObjectEmission(format!(
                "AArch64 object global `{}` is a COMDAT definition without weak linkage (a COMDAT requires an external weak definition; fail-closed)",
                global.name
            )));
        }

        let mut slot_offsets = BTreeSet::new();
        for symbol_ref in &global.symbol_refs {
            if symbol_ref.symbol.is_empty() {
                return Err(PipelineError::ObjectEmission(format!(
                    "AArch64 object global `{}` has a pointer slot with an empty target symbol (fail-closed)",
                    global.name
                )));
            }
            if !slot_offsets.insert(symbol_ref.offset) {
                return Err(PipelineError::ObjectEmission(format!(
                    "AArch64 object global `{}` has duplicate pointer relocations at byte offset {} (fail-closed)",
                    global.name, symbol_ref.offset
                )));
            }
            let end = symbol_ref.offset.checked_add(POINTER_SIZE).ok_or_else(|| {
                PipelineError::ObjectEmission(format!(
                    "AArch64 object global `{}` pointer slot offset {} overflows (fail-closed)",
                    global.name, symbol_ref.offset
                ))
            })?;
            if end > global.data.len() as u64 {
                return Err(PipelineError::ObjectEmission(format!(
                    "AArch64 object global `{}` pointer slot [{}..{}) exceeds its {} initializer bytes (fail-closed)",
                    global.name,
                    symbol_ref.offset,
                    end,
                    global.data.len()
                )));
            }
        }
    }
    reject_aarch64_pointer_slots_naming_thread_locals(globals)
}

/// Refuse a pointer slot whose TARGET is a thread-local this module declares
/// (a definition or an import), whether the slot lives in ordinary data or in
/// a thread-local's own initial-value template.
///
/// A thread-local has no single link-time address, so no object format can
/// relocate `&tls` into data: on ELF an `R_AARCH64_ABS64` against an
/// `STT_TLS` symbol resolves to the variable's offset in its TLS block, and on
/// Mach-O `_X` names the TLV descriptor, not any thread's storage. C rejects
/// the same initializer (`&tls` is not an address constant). For DATA slots
/// this is the one decision point for every AArch64 object emitter, the
/// relocation inventory and the JIT data image, all of which validate through
/// [`validate_aarch64_object_globals`]. A slot naming a symbol this module does
/// not declare is still emitted against an untyped undefined symbol.
///
/// Function bodies are not checked here: a trust-ir body `SymbolAddr` naming
/// a thread-local is refused earlier, in the trust-ir adapter
/// (`[TCG-TLS-SYMBOL-ADDR]`), but a lower-IR `GlobalRef`/`ExternRef` handed
/// to this API that names a thread-local object global is not refused.
fn reject_aarch64_pointer_slots_naming_thread_locals(
    globals: &[ObjectGlobal],
) -> Result<(), PipelineError> {
    let thread_locals: BTreeSet<&str> = globals
        .iter()
        .filter(|global| global.is_thread_local)
        .map(|global| global.name.as_str())
        .collect();
    if thread_locals.is_empty() {
        return Ok(());
    }
    for global in globals {
        if let Some(symbol_ref) = global
            .symbol_refs
            .iter()
            .find(|symbol_ref| thread_locals.contains(symbol_ref.symbol.as_str()))
        {
            let holder = if global.is_thread_local {
                "thread-local initial-value template"
            } else {
                "data"
            };
            return Err(PipelineError::ObjectEmission(format!(
                "[TCG-TLS-SLOT-TARGET] AArch64 object global `{}` ({holder}) has a pointer slot at byte offset {} naming thread-local `{}`; a thread-local has no link-time address (an ELF R_AARCH64_ABS64 against an STT_TLS symbol yields its TLS-block offset, a Mach-O `_{}` names its TLV descriptor), so the slot is refused (fail-closed)",
                global.name, symbol_ref.offset, symbol_ref.symbol, symbol_ref.symbol
            )));
        }
    }
    Ok(())
}

/// One defined-global symbol row produced by [`add_elf_global_sections`]:
/// where the global's bytes were placed and how its symbol must be emitted.
struct ElfGlobalSymbolRow {
    name: String,
    /// 1-based section header index the global was placed in.
    section: u16,
    /// Byte offset of the global within that section.
    offset: u64,
    /// Symbol size in bytes (the global's data length).
    size: u64,
    /// `STB_WEAK` coalescable definition (vs `STB_GLOBAL`/local strong).
    is_weak: bool,
    /// Thread-local (`.tdata` or `.tbss` resident): the symbol must be
    /// `STT_TLS` (its value is an offset in its TLS section, not an address).
    is_tls: bool,
    /// trust-ir `External`/`Weak`/`LinkOnce` linkage: the symbol lives in the
    /// GLOBAL partition (resolvable from other objects). `Internal`/`Private`
    /// globals MUST be `STB_LOCAL`: every module carries its own copy of
    /// content-hashed internals (`str.<hash>`, `vtable.<hash>`), and emitting
    /// them `STB_GLOBAL` makes any two modules sharing a hash collide with
    /// "multiple definition" at static link (the ELF analogue of the Mach-O
    /// emitter honoring `ObjectGlobal::is_external`).
    is_external: bool,
    /// `STV_*` visibility (trust-ir v41 `Global.visibility`).
    visibility: u8,
    /// The COMDAT group this definition's own section belongs to; its
    /// signature is bound to this row's symbol once the symbol is added
    /// ([`add_elf_global_row_symbol`]).
    comdat_group: Option<crate::elf::ElfSectionGroupId>,
}

/// The names of thread-local IMPORTS (initializer-less cross-object TLS
/// references). They contribute no section bytes; each must be emitted as an
/// UNDEFINED `STT_TLS` symbol so the local-exec TPREL relocations against it
/// resolve to the defining object's TLS block at static link (an undefined
/// `STT_NOTYPE` symbol would be a TLS-vs-non-TLS symbol-kind mismatch).
fn elf_tls_import_names(globals: &[ObjectGlobal]) -> Vec<String> {
    globals
        .iter()
        .filter(|global| global.is_thread_local && global.is_import)
        .map(|global| global.name.clone())
        .collect()
}

fn add_elf_global_sections(
    writer: &mut crate::elf::ElfWriter,
    globals: &[ObjectGlobal],
) -> Result<Vec<ElfGlobalSymbolRow>, PipelineError> {
    use crate::elf::constants::SHT_NOBITS;
    use crate::object_sections::ElfImplicitSection;

    let mut symbols = Vec::new();
    // Explicit-section, COMDAT and retained definitions get their sections
    // below (`add_elf_placed_global_sections`); the implicit sections keep
    // the rest, none of them retained, so no shared section is
    // `SHF_GNU_RETAIN`.
    // IMPORTS (initializer-less cross-object references, TLS or data) define
    // no bytes here: placing one would emit a zero-size DEFINITION that
    // collides with (or shadows) the real definition in another object.
    // They resolve through undefined symbols instead (mirrors the Mach-O
    // emitter's import exclusion).
    let implicit = |global: &&ObjectGlobal| {
        global.section.is_none() && !global.comdat && !global.retained && !global.is_import
    };

    // Lay out a set of globals in one section, aligning EACH global's offset
    // up to its own declared alignment (an over-aligned static must land on a
    // correctly-aligned offset, not be packed back-to-back), and return the
    // per-global offsets, the section size, and the strictest alignment (which
    // the section header must carry so the loader honors the over-alignment).
    fn layout_elf_globals(
        globals: &[&ObjectGlobal],
        minimum_alignment: u32,
    ) -> (Vec<u64>, u64, u32) {
        let mut size = 0u64;
        let mut offsets = Vec::with_capacity(globals.len());
        let mut max_align = minimum_alignment;
        for global in globals {
            let align = u64::from(global.align.max(minimum_alignment));
            max_align = max_align.max(global.align);
            size = size.next_multiple_of(align);
            offsets.push(size);
            size += global.data.len() as u64;
        }
        (offsets, size, max_align)
    }

    // One shared section per implicit class ([`ElfImplicitSection`], the
    // decision the COMDAT arm uses too): `.data`, zero-fill `.bss`
    // (SHT_NOBITS, which the loader zero-fills), `.rodata`, `.data.rel.ro`,
    // `.tdata` and zero-fill `.tbss`, which the static linker places after
    // `.tdata` inside PT_TLS and the TLS runtime zero-fills for every thread.
    // TLS can be over-aligned just like ordinary data: each template keeps
    // its declared alignment and the section its strictest one, which the
    // static linker propagates to PT_TLS. TLS sections retain the historical
    // 16-byte floor for small templates.
    for class in ElfImplicitSection::ORDER {
        let members: Vec<&ObjectGlobal> = globals
            .iter()
            .filter(implicit)
            .filter(|global| ElfImplicitSection::of(global) == class)
            .collect();
        if members.is_empty() {
            continue;
        }
        let name = class.base();
        let minimum_alignment = if class.tls() { 16 } else { 1 };
        let (offsets, size, max_align) = layout_elf_globals(&members, minimum_alignment);
        let flags = class.sh_flags();
        let section = if class.sh_type() == SHT_NOBITS {
            // Zero-fill is a length: the writer never materialises it.
            writer.add_nobits_section(name, size, flags, u64::from(max_align))?
        } else {
            // Initialized content lives in host memory. A section this host
            // cannot address is refused here, never truncated or panicked on.
            let byte_len = usize::try_from(size).map_err(|_| {
                PipelineError::ObjectEmission(format!(
                    "ELF {name} section of {size} bytes exceeds this host's address space"
                ))
            })?;
            let mut data = vec![0u8; byte_len];
            for (global, &offset) in members.iter().zip(&offsets) {
                let start = offset as usize;
                data[start..start + global.data.len()].copy_from_slice(&global.data);
            }
            writer.add_section(name, &data, class.sh_type(), flags, u64::from(max_align))?
        };
        for (global, offset) in members.iter().zip(offsets) {
            symbols.push(ElfGlobalSymbolRow {
                name: global.name.clone(),
                section,
                offset,
                size: global.data.len() as u64,
                is_weak: global.is_weak,
                is_tls: class.tls(),
                is_external: global.is_external,
                visibility: elf_symbol_visibility(global.visibility),
                comdat_group: None,
            });
        }
    }

    add_elf_placed_global_sections(writer, globals, &mut symbols)?;
    Ok(symbols)
}

/// Pack `members` into one section body, aligning each global's offset up to
/// its own declared alignment (floored at `minimum_alignment`), and return the
/// bytes, per-member offsets, and the strictest alignment the section header
/// must carry.
fn pack_placed_elf_globals(
    members: &[&ObjectGlobal],
    minimum_alignment: u32,
) -> (Vec<u8>, Vec<u64>, u32) {
    let mut data = Vec::new();
    let mut offsets = Vec::with_capacity(members.len());
    let mut max_align = minimum_alignment.max(1);
    for global in members {
        let align = global.align.max(minimum_alignment).max(1) as usize;
        max_align = max_align.max(align as u32);
        let padding = (align - (data.len() % align)) % align;
        data.resize(data.len() + padding, 0);
        offsets.push(data.len() as u64);
        data.extend_from_slice(&global.data);
    }
    (data, offsets, max_align)
}

fn elf_section_refusal(
    global: &ObjectGlobal,
    section: &str,
    (code, reason): crate::object_sections::Refusal,
) -> PipelineError {
    PipelineError::ExplicitSectionUnsupported {
        global: global.name.clone(),
        section: section.to_string(),
        format: "ELF",
        code,
        reason,
    }
}

/// Where every explicit-section, COMDAT and retained data definition goes on
/// ELF (trust-ir v41 `Global.section`; `LinkOnce`/`LinkOnceOdr`/`WeakOdr`
/// linkage; `Global.retained`): the one classification
/// ([`crate::object_sections::classify_elf_section`], the implicit
/// own-section names, the reserved names `[TCG-SECTION-RESERVED]` among
/// them) that the ELF emitters and the relocation inventory both apply, so
/// the inventory cannot accept a placement the emitter refuses.
///
/// * Explicit, neither COMDAT nor retained: every global naming the same
///   section shares ONE section of that name, packed in declaration order
///   with each member's alignment; its type/flags/entsize come from
///   [`crate::object_sections::classify_elf_section`] and must agree across
///   members ([`crate::object_sections::SectionRefusal::FlagConflict`]
///   otherwise). A constructor table (`.init_array`, ...) is an
///   `SHT_INIT_ARRAY`-class section whose slots the caller relocates with
///   `R_AARCH64_ABS64` (the ordinary pointer-slot path). A zero-fill name
///   (`.bss*`, `.tbss*`, `.sbss*`, `.lbss*`) holding only all-zero,
///   relocation-free members is `SHT_NOBITS`.
/// * COMDAT or retained: each definition gets its OWN section — its
///   explicit name, or `<implicit base>.<symbol>` from
///   [`crate::object_sections::ElfImplicitSection`] (`.data.X`, `.bss.X`,
///   `.rodata.X`, `.data.rel.ro.X`, `.tdata.X`, `.tbss.X`). A COMDAT one is
///   inside a `GRP_COMDAT` group whose signature is its symbol, so
///   duplicate copies across objects are discarded whole by the linker. A
///   retained one is `SHF_GNU_RETAIN`, which keeps exactly that definition
///   through `--gc-sections`; an explicit name it shares with other globals
///   is a second section of that name (llc's unique section), so the
///   members that are not retained stay collectable. A zero-fill
///   definition's own section is `SHT_NOBITS` and takes no file bytes. A
///   symbol that would move `<base>.<symbol>` into another linker placement
///   rule (a mutable `rel.ro` makes `.data.rel.ro`) is refused by name
///   ([`crate::object_sections::ElfImplicitSection::unique_section`]).
///
/// The placed sections are emitted in the order llc 22 creates them (its
/// `AsmPrinter` emits the globals in module order and creates each section
/// at the first global it holds): a shared section where its first member
/// is declared, a COMDAT or retained definition's own section where that
/// definition is declared. The linker concatenates same-named input
/// sections in that order, so a constructor table's run order and a
/// `__start_`/`__stop_` walk follow llc's whichever of the three kinds the
/// members are, wherever llc keeps module order. It does not where its
/// `GlobalMerge` pass runs (O3, and O1-O2 for globals a `minsize` function
/// uses): that pass first combines the unlisted dso-local mutable members
/// one function uses together into one object emitted after the section's
/// other members, which this backend never does. The implicit sections
/// ([`add_elf_global_sections`]) come before every placed one; an explicit
/// section named like one of them
/// (`.data`, `.bss`, ...) is a second input section of that name after it,
/// where llc places both kinds of member in one section in module order.
/// That reorders only addresses inside one output section, which neither a
/// constructor table nor a `__start_`/`__stop_` walk (no implicit name is a
/// C identifier) reads.
struct ElfPlacedGlobalPlan<'a> {
    sections: Vec<ElfPlacedSection<'a>>,
}

/// One section of an [`ElfPlacedGlobalPlan`].
enum ElfPlacedSection<'a> {
    /// An explicit section shared by members that are neither COMDAT nor
    /// retained, in declaration order; never `SHF_GNU_RETAIN`.
    Shared(
        &'a str,
        crate::object_sections::ElfExplicitSection,
        Vec<&'a ObjectGlobal>,
    ),
    /// A COMDAT or retained definition's own section: grouped when COMDAT,
    /// `SHF_GNU_RETAIN` when retained.
    Own(
        &'a ObjectGlobal,
        String,
        crate::object_sections::ElfExplicitSection,
    ),
}

/// The own section of a COMDAT or retained definition: its explicit name,
/// or `<implicit base>.<symbol>`.
fn plan_elf_own_section(
    global: &ObjectGlobal,
) -> Result<(String, crate::object_sections::ElfExplicitSection), PipelineError> {
    use crate::object_sections::{ElfImplicitSection, classify_elf_section};
    match global.section.as_deref() {
        Some(name) => Ok((
            name.to_string(),
            classify_elf_section(global, name)
                .map_err(|refusal| elf_section_refusal(global, name, refusal))?,
        )),
        None => {
            let name = ElfImplicitSection::unique_section_name(global);
            let class = ElfImplicitSection::unique_section(global).map_err(|(code, reason)| {
                PipelineError::ExplicitSectionUnsupported {
                    global: global.name.clone(),
                    section: name.clone(),
                    format: if global.comdat {
                        "implicit ELF COMDAT"
                    } else {
                        "implicit ELF retained"
                    },
                    code,
                    reason,
                }
            })?;
            Ok((name, class))
        }
    }
}

fn plan_elf_placed_global_sections(
    globals: &[ObjectGlobal],
) -> Result<ElfPlacedGlobalPlan<'_>, PipelineError> {
    use crate::object_sections::{SectionRefusal, classify_elf_section};

    let mut plan = ElfPlacedGlobalPlan {
        sections: Vec::new(),
    };
    for global in globals.iter().filter(|global| !global.is_import) {
        if global.comdat || global.retained {
            let (name, class) = plan_elf_own_section(global)?;
            plan.sections
                .push(ElfPlacedSection::Own(global, name, class));
            continue;
        }
        let Some(name) = global.section.as_deref() else {
            continue;
        };
        let class = classify_elf_section(global, name)
            .map_err(|refusal| elf_section_refusal(global, name, refusal))?;
        match plan.sections.iter_mut().find_map(|section| match section {
            ElfPlacedSection::Shared(existing, first_class, members) if *existing == name => {
                Some((first_class, members))
            }
            _ => None,
        }) {
            Some((first_class, members)) => {
                if *first_class != class {
                    return Err(elf_section_refusal(
                        global,
                        name,
                        (
                            SectionRefusal::FlagConflict,
                            format!(
                                "it derives section type {:#x} / flags {:#x} but `{}` in the same section derives {:#x} / {:#x}",
                                class.sh_type,
                                class.sh_flags,
                                members[0].name,
                                first_class.sh_type,
                                first_class.sh_flags
                            ),
                        ),
                    ));
                }
                members.push(global);
            }
            None => plan
                .sections
                .push(ElfPlacedSection::Shared(name, class, vec![global])),
        }
    }
    Ok(plan)
}

fn add_elf_placed_global_sections(
    writer: &mut crate::elf::ElfWriter,
    globals: &[ObjectGlobal],
    symbols: &mut Vec<ElfGlobalSymbolRow>,
) -> Result<(), PipelineError> {
    let mut row = |global: &ObjectGlobal,
                   section: u16,
                   offset: u64,
                   tls: bool,
                   comdat_group: Option<crate::elf::ElfSectionGroupId>| {
        symbols.push(ElfGlobalSymbolRow {
            name: global.name.clone(),
            section,
            offset,
            size: global.data.len() as u64,
            is_weak: global.is_weak,
            is_tls: tls,
            is_external: global.is_external,
            visibility: elf_symbol_visibility(global.visibility),
            comdat_group,
        });
    };

    let plan = plan_elf_placed_global_sections(globals)?;
    for placed in &plan.sections {
        match placed {
            ElfPlacedSection::Shared(name, class, members) => {
                let (section, offsets) =
                    add_placed_elf_section(writer, None, name, class, members)?;
                for (global, offset) in members.iter().zip(offsets) {
                    row(global, section, offset, class.tls, None);
                }
            }
            ElfPlacedSection::Own(global, name, class) => {
                // A COMDAT group's signature is this definition's symbol,
                // bound through the checked symbol API when the emitter adds
                // the row's symbol.
                let group = global.comdat.then(|| writer.add_comdat_group());
                let (section, _) = add_placed_elf_section(writer, group, name, class, &[global])?;
                row(global, section, 0, class.tls, group);
            }
        }
    }
    Ok(())
}

/// Pack `members` into one placed section of `class` and add it, as a member
/// of COMDAT `group` when one is given. Returns the section header index and
/// each member's offset. A retained member must be alone in its section
/// ([`ObjectGlobal::retained`]), which then carries `SHF_GNU_RETAIN`.
///
/// A `SHT_NOBITS` class takes no file bytes: the writer records the packed
/// size, alignment and flags, and the loader or TLS runtime supplies zeros.
/// Classification admits only all-zero, relocation-free members to NOBITS;
/// a nonzero packed byte is refused here as well, ahead of the reparse gate.
fn add_placed_elf_section(
    writer: &mut crate::elf::ElfWriter,
    group: Option<crate::elf::ElfSectionGroupId>,
    name: &str,
    class: &crate::object_sections::ElfExplicitSection,
    members: &[&ObjectGlobal],
) -> Result<(u16, Vec<u64>), PipelineError> {
    let (data, offsets, max_align) = pack_placed_elf_globals(members, class.min_align);
    if class.sh_type == crate::elf::constants::SHT_NOBITS && data.iter().any(|&byte| byte != 0) {
        return Err(PipelineError::ObjectEmission(format!(
            "ELF zero-fill section `{name}` would hold nonzero bytes; SHT_NOBITS has no file bytes to carry them (fail-closed)"
        )));
    }
    let retain = match members {
        [only] => elf_retain_flag(only),
        _ => {
            if let Some(retained) = members.iter().find(|member| member.retained) {
                return Err(PipelineError::ObjectEmission(format!(
                    "ELF section `{name}` would pack retained global `{}` with {} other global(s); SHF_GNU_RETAIN would keep them all through --gc-sections (fail-closed)",
                    retained.name,
                    members.len() - 1
                )));
            }
            0
        }
    };
    let flags = class.sh_flags | retain;
    let align = u64::from(max_align);
    let section = match group {
        Some(group) => writer.add_group_member_section(
            group,
            name,
            &data,
            class.sh_type,
            flags,
            align,
            class.entsize,
        )?,
        None => writer.add_section_with_entsize(
            name,
            &data,
            class.sh_type,
            flags,
            align,
            class.entsize,
        )?,
    };
    Ok((section, offsets))
}

fn add_elf_global_object_symbols(
    writer: &mut crate::elf::ElfWriter,
    globals: &[ObjectGlobal],
) -> Result<Vec<String>, PipelineError> {
    let rows = add_elf_global_sections(writer, globals)?;
    let mut names = Vec::with_capacity(rows.len());
    for row in rows {
        // A weak DEFINITION gets STB_WEAK so duplicate definitions across
        // objects coalesce instead of dup-strong-erroring; an Internal/
        // Private one is STB_LOCAL (content-hashed per-module internals
        // must not collide across objects at static link).
        add_elf_global_row_symbol(writer, &row)?;
        names.push(row.name);
    }
    Ok(names)
}

/// Add one placed global's symbol through the checked symbol API and, when
/// the global's section is a COMDAT group member, bind the group's signature
/// to that symbol.
fn add_elf_global_row_symbol(
    writer: &mut crate::elf::ElfWriter,
    row: &ElfGlobalSymbolRow,
) -> Result<crate::elf::ElfSymbolId, PipelineError> {
    let id = writer.add_checked_symbol(elf_global_row_symbol(row))?;
    if let Some(group) = row.comdat_group {
        writer.bind_comdat_group_signature(group, id)?;
    }
    Ok(id)
}

/// Emit immutable module globals into `__TEXT,__const` (`S_REGULAR`, 8-byte
/// aligned), NOT `__cstring`/`S_CSTRING_LITERALS`.
///
/// CORRECTNESS: `S_CSTRING_LITERALS` tells the linker the section holds
/// NUL-terminated C strings, which `ld` deduplicates and merges on NUL
/// boundaries. For arbitrary binary data (e.g. an 8-byte integer with embedded
/// zero bytes) that merging reads only up to the first NUL and coalesces the
/// remainder with adjacent literals — a SILENT MISCOMPILE of every immutable
/// global read (an 8-byte `static N: u64` would link to the bytes of some other
/// string literal). `__TEXT,__const` with `S_REGULAR` keeps the exact bytes and
/// 8-byte alignment, so an ADRP/ADD (`ARM64_RELOC_PAGE21`/`PAGEOFF12`) addressing
/// the symbol reads back the correct value. This mirrors the x86-64 emitter,
/// which places immutable globals in `__TEXT,__const` (`S_REGULAR`) — see
/// `x86_64::pipeline::emit_module_macho`.
fn add_global_const_section(
    writer: &mut crate::macho::MachOWriter,
    globals: &[&ObjectGlobal],
) -> Result<Vec<(String, crate::macho::SymbolId)>, PipelineError> {
    add_global_const_section_named(
        writer,
        globals,
        b"__TEXT",
        b"__const",
        crate::macho::constants::S_REGULAR,
    )
}

/// [`add_global_const_section`] into an explicit `segname,sectname` with
/// explicit section `flags` (trust-ir v41 `Global.section` on Mach-O).
fn add_global_const_section_named(
    writer: &mut crate::macho::MachOWriter,
    globals: &[&ObjectGlobal],
    segname: &[u8],
    sectname: &[u8],
    flags: u32,
) -> Result<Vec<(String, crate::macho::SymbolId)>, PipelineError> {
    if globals.is_empty() {
        return Ok(Vec::new());
    }

    let mut data = Vec::new();
    let mut offsets = Vec::new();
    offsets.try_reserve_exact(globals.len()).map_err(|error| {
        PipelineError::ObjectEmission(format!(
            "AArch64 immutable-global offset-table allocation failed: {error}"
        ))
    })?;
    // The section's own alignment must cover the strictest per-global alignment
    // (a `#[repr(align(64))]` static needs a 64-aligned section so the loader
    // places its first byte on a 64-aligned address).
    let mut max_align: u32 = 1;
    for global in globals {
        // Align each global up to its OWN declared alignment within the section
        // so an ADRP/ADD pair lands on a correctly-aligned slot.
        let align = global.align.max(1) as usize;
        max_align = max_align.max(global.align.max(1));
        let padding = (align - (data.len() % align)) % align;
        let padded_len = checked_aarch64_size_sum(
            &global.name,
            "immutable-global section alignment",
            data.len(),
            padding,
        )?;
        let final_len = checked_aarch64_size_sum(
            &global.name,
            "immutable-global section byte length",
            padded_len,
            global.data.len(),
        )?;
        data.try_reserve(padding + global.data.len())
            .map_err(|error| {
                PipelineError::ObjectEmission(format!(
                    "AArch64 immutable-global section allocation for `{}` failed: {error}",
                    global.name
                ))
            })?;
        data.resize(padded_len, 0);
        offsets.push(checked_aarch64_object_u64(
            &global.name,
            "immutable-global section offset",
            data.len(),
        )?);
        data.extend_from_slice(&global.data);
        debug_assert_eq!(data.len(), final_len);
    }

    let section_index =
        writer.add_custom_section(sectname, segname, &data, max_align.trailing_zeros(), flags);
    let section_ordinal = section_index + 1;

    Ok(globals
        .iter()
        .zip(offsets)
        .map(|(global, offset)| {
            let name = macho_symbol_name(&global.name);
            // A weak DEFINITION coalesces across objects (`N_WEAK_DEF`); a strong
            // one is a plain external/local def. Externally-visible globals (e.g.
            // a `#[no_mangle]` / exported `static`) must be GLOBAL symbols so other
            // objects resolve them; private const-alloc copies stay local.
            // Weak definition, visibility (`N_PEXT` for hidden), and `#[used]`
            // retention (`N_NO_DEAD_STRIP`) all ride the same nlist entry.
            let symbol_id = writer.add_defined_symbol_with_attrs(
                &name,
                section_ordinal,
                offset,
                global.is_external,
                global.is_weak,
                global.visibility,
                global.retained,
            )?;
            Ok((global.name.clone(), symbol_id))
        })
        .collect::<Result<Vec<_>, crate::macho::MachOWriteError>>()?)
}

/// A data-section symbol-address relocation (`ARM64_RELOC_UNSIGNED`, 8-byte
/// absolute pointer) deferred until every module symbol exists, so its target's
/// final nlist index is known. This is the AArch64/Mach-O analogue of the
/// x86-64 emitter's `data_reloc_work` (`X86_64_RELOC_UNSIGNED`) — it is what
/// places a function/data address inside a vtable slot or a `static FNS:
/// [fn(); N]` element. The declared addend, zero included, is written into
/// the 8-byte section slot before emission (an `ARM64_RELOC_UNSIGNED` adds the
/// resolved symbol address to the in-place value, mirroring clang and the
/// x86-64 path), so placeholder bytes cannot become an undeclared addend.
pub(crate) struct PendingDataReloc {
    /// 0-based index of the data section (`__DATA,__data`, `__DATA,__const`,
    /// an explicit data section, or the `__DATA,__thread_data` TLS template
    /// section) the slot lives in.
    pub(crate) section_index: usize,
    /// Byte offset of the relocated 8-byte slot within that section.
    pub(crate) offset: u32,
    /// Unmangled target symbol name (a function or data global, in-module or an
    /// undefined external the linker resolves).
    pub(crate) symbol: String,
}

fn add_global_data_section(
    writer: &mut crate::macho::MachOWriter,
    globals: &[&ObjectGlobal],
) -> Result<(Vec<(String, crate::macho::SymbolId)>, Vec<PendingDataReloc>), PipelineError> {
    add_global_data_section_named(
        writer,
        globals,
        b"__DATA",
        b"__data",
        crate::macho::constants::S_REGULAR,
        1,
    )
}

/// Emit relocated immutable globals (vtables, `static FNS: [fn(); N]`) into
/// `__DATA,__const` (`S_REGULAR`), whose pointer slots become
/// `ARM64_RELOC_UNSIGNED` relocations exactly as in `__DATA,__data`.
///
/// ld64 and the in-repo linker place `__DATA,__const` in the `SG_READ_ONLY`
/// `__DATA_CONST` segment, which dyld write-protects after applying its
/// fixups: a store to one of these globals faults, as a store to ELF
/// `.data.rel.ro` does under `PT_GNU_RELRO`.
fn add_global_data_const_section(
    writer: &mut crate::macho::MachOWriter,
    globals: &[&ObjectGlobal],
) -> Result<(Vec<(String, crate::macho::SymbolId)>, Vec<PendingDataReloc>), PipelineError> {
    add_global_data_section_named(
        writer,
        globals,
        b"__DATA",
        b"__const",
        crate::macho::constants::S_REGULAR,
        1,
    )
}

/// [`add_global_data_section`] into an explicit `segname,sectname` with
/// explicit section `flags` and a minimum alignment (trust-ir v41
/// `Global.section` on Mach-O, including an `S_MOD_INIT_FUNC_POINTERS`
/// constructor table whose slots become `ARM64_RELOC_UNSIGNED` pointers).
fn add_global_data_section_named(
    writer: &mut crate::macho::MachOWriter,
    globals: &[&ObjectGlobal],
    segname: &[u8],
    sectname: &[u8],
    flags: u32,
    minimum_alignment: u32,
) -> Result<(Vec<(String, crate::macho::SymbolId)>, Vec<PendingDataReloc>), PipelineError> {
    if globals.is_empty() {
        return Ok((Vec::new(), Vec::new()));
    }

    let mut data = Vec::new();
    let mut offsets = Vec::new();
    offsets.try_reserve_exact(globals.len()).map_err(|error| {
        PipelineError::ObjectEmission(format!(
            "AArch64 mutable-global offset-table allocation failed: {error}"
        ))
    })?;
    // Symbol-address slots to relocate, collected as (section-relative offset,
    // target symbol). The section index is known only after `add_custom_section`.
    let mut reloc_slots: Vec<(u32, String)> = Vec::new();
    // The section's own alignment must cover the strictest per-global alignment.
    let mut max_align: u32 = minimum_alignment.max(1);
    for global in globals {
        // Align each global up to its OWN declared alignment (an atomic /
        // over-aligned static must land on a correctly-aligned address, not be
        // packed back-to-back after the preceding global).
        let align = global.align.max(minimum_alignment).max(1) as usize;
        max_align = max_align.max(align as u32);
        let padding = (align - (data.len() % align)) % align;
        let aligned_start = checked_aarch64_size_sum(
            &global.name,
            "mutable-global section alignment",
            data.len(),
            padding,
        )?;
        data.try_reserve(padding).map_err(|error| {
            PipelineError::ObjectEmission(format!(
                "AArch64 mutable-global section alignment padding for `{}` failed: {error}",
                global.name
            ))
        })?;
        data.resize(aligned_start, 0);
        // Section-relative offset of this global (captured AFTER alignment
        // padding but BEFORE the extend, so the reloc-slot math and the
        // offset-table entry agree).
        let global_offset = data.len() as u64;
        let final_len = checked_aarch64_size_sum(
            &global.name,
            "mutable-global section byte length",
            data.len(),
            global.data.len(),
        )?;
        data.try_reserve(global.data.len()).map_err(|error| {
            PipelineError::ObjectEmission(format!(
                "AArch64 mutable-global section allocation for `{}` failed: {error}",
                global.name
            ))
        })?;
        offsets.push(checked_aarch64_object_u64(
            &global.name,
            "mutable-global section offset",
            data.len(),
        )?);
        data.extend_from_slice(&global.data);
        debug_assert_eq!(data.len(), final_len);
        // Write the declared implicit addend into the 8-byte slot now (while
        // we still own the section bytes), then record the slot for an
        // `ARM64_RELOC_UNSIGNED`. The relocation ADDS the resolved address to
        // the in-place value, so the write is unconditional: a declared zero
        // addend must erase any nonzero placeholder bytes a producer of this
        // public `ObjectGlobal` left in the slot. An out-of-range slot fails
        // closed instead of panicking or patching a neighbour.
        for sref in &global.symbol_refs {
            let bytes = sref.addend.to_le_bytes();
            let slot = usize::try_from(sref.offset)
                .ok()
                .and_then(|offset| offset.checked_add(global_offset as usize))
                .filter(|slot| {
                    slot.checked_add(bytes.len())
                        .is_some_and(|end| end <= final_len)
                });
            let Some(slot) = slot else {
                return Err(PipelineError::ObjectEmission(format!(
                    "AArch64 Mach-O pointer slot at offset {} of `{}` exceeds its \
                     {}-byte initializer (fail-closed)",
                    sref.offset,
                    global.name,
                    global.data.len()
                )));
            };
            data[slot..slot + bytes.len()].copy_from_slice(&bytes);
            reloc_slots.push((
                checked_aarch64_object_u32(&global.name, "mutable-global relocation offset", slot)?,
                sref.symbol.clone(),
            ));
        }
    }

    let section_index =
        writer.add_custom_section(sectname, segname, &data, max_align.trailing_zeros(), flags);
    let section_ordinal = section_index + 1;

    let pending = reloc_slots
        .into_iter()
        .map(|(offset, symbol)| PendingDataReloc {
            section_index,
            offset,
            symbol,
        })
        .collect();

    let symbols = globals
        .iter()
        .zip(offsets)
        .map(|(global, offset)| {
            let name = macho_symbol_name(&global.name);
            // A weak DEFINITION coalesces across objects (`N_WEAK_DEF`).
            // Externally-visible globals must be GLOBAL symbols (see the
            // immutable-section emitter above).
            // Weak definition, visibility (`N_PEXT` for hidden), and `#[used]`
            // retention (`N_NO_DEAD_STRIP`) all ride the same nlist entry.
            let symbol_id = writer.add_defined_symbol_with_attrs(
                &name,
                section_ordinal,
                offset,
                global.is_external,
                global.is_weak,
                global.visibility,
                global.retained,
            )?;
            Ok((global.name.clone(), symbol_id))
        })
        .collect::<Result<Vec<_>, crate::macho::MachOWriteError>>()?;
    Ok((symbols, pending))
}

/// A descriptor-slot relocation deferred until all symbols are added, so the
/// `relocation_info.r_symbolnum` can use the FINAL nlist index.
///
/// `pub(crate)` so the x86-64 Mach-O emitter (`x86_64::pipeline::emit_module_macho`)
/// can consume the same deferred relocations and emit them as
/// `X86_64_RELOC_UNSIGNED` (the AArch64 caller emits `ARM64_RELOC_UNSIGNED`);
/// the descriptor section/symbol layout is arch-neutral and shared.
pub(crate) struct PendingTlsReloc {
    /// 0-based index of the `__thread_vars` section the descriptor lives in.
    pub(crate) section_index: usize,
    /// Byte offset of the relocated 8-byte slot within `__thread_vars`.
    pub(crate) offset: u32,
    /// Insertion-time symbol id of the referenced symbol.
    pub(crate) symbol_id: crate::macho::SymbolId,
}

const AARCH64_DARWIN_TLV_POINTER_SIZE: usize = 8;
const AARCH64_DARWIN_TLV_DESCRIPTOR_SIZE: usize = 3 * AARCH64_DARWIN_TLV_POINTER_SIZE;
const AARCH64_DARWIN_TLV_INIT_POINTER_OFFSET: usize = 2 * AARCH64_DARWIN_TLV_POINTER_SIZE;

/// Validate every count-derived Darwin TLV size and the largest descriptor
/// relocation before allocating section storage. Mach-O's non-scattered
/// `r_address` is signed, so bit 31 must stay clear even though our in-memory
/// relocation offset is a `u32`.
fn checked_aarch64_tls_layout(global_count: usize) -> Result<(usize, usize), PipelineError> {
    let descriptor_byte_len = checked_aarch64_capacity(
        "<module>",
        "Darwin TLV descriptor table byte length",
        global_count,
        AARCH64_DARWIN_TLV_DESCRIPTOR_SIZE,
    )?;
    let pending_relocation_capacity = checked_aarch64_capacity(
        "<module>",
        "Darwin TLV pending relocation count",
        global_count,
        2,
    )?;

    if global_count != 0 {
        let last_descriptor_offset = checked_aarch64_capacity(
            "<module>",
            "Darwin TLV last descriptor offset",
            global_count - 1,
            AARCH64_DARWIN_TLV_DESCRIPTOR_SIZE,
        )?;
        let max_relocation_offset = checked_aarch64_size_sum(
            "<module>",
            "Darwin TLV maximum relocation offset",
            last_descriptor_offset,
            AARCH64_DARWIN_TLV_INIT_POINTER_OFFSET,
        )?;
        let max_relocation_offset = checked_aarch64_object_u32(
            "<module>",
            "Darwin TLV maximum relocation offset",
            max_relocation_offset,
        )?;
        checked_aarch64_macho_relocation_offset(
            "<module>",
            "Darwin TLV maximum relocation offset",
            max_relocation_offset,
        )?;
    }

    Ok((descriptor_byte_len, pending_relocation_capacity))
}

/// Emit the Darwin TLV sections for the thread-local globals and register their
/// symbols.
///
/// For each thread-local global `X` with initial value bytes `init`, this lays
/// out (mirroring clang `-O1` / `<mach-o/loader.h>` TLV conventions):
///
/// - `__DATA,__thread_data` (`S_THREAD_LOCAL_REGULAR`): the per-thread initial
///   value template `X$tlv$init`. A local symbol points at it.
/// - `__DATA,__thread_vars` (`S_THREAD_LOCAL_VARIABLES`): the 3-word
///   `tlv_descriptor` `{ thunk = __tlv_bootstrap, key = 0, offset = X$tlv$init }`.
///   The symbol `X` (the one a `#[thread_local]` read addresses through the TLVP
///   relocations) points at the descriptor. Two `ARM64_RELOC_UNSIGNED` (8-byte)
///   relocations fill word 0 (`__tlv_bootstrap`, an undefined dyld import) and
///   word 2 (`X$tlv$init`).
///
/// Returns `(name -> descriptor SymbolId)` for the `X` symbols (so TLVP fixups in
/// `__text` resolve to them) and the list of deferred descriptor relocations,
/// emitted by the caller once every symbol's final nlist index is known.
///
/// `pub(crate)` and arch-neutral: the descriptor byte layout (3 pointer-width
/// words `{ __tlv_bootstrap, 0, X$tlv$init }`), the `__DATA,__thread_data` /
/// `__DATA,__thread_vars` sections and their `S_THREAD_LOCAL_*` flags, and the
/// `_X` / `_X$tlv$init` symbol names are identical on AArch64 and x86-64 Darwin.
/// Only the two internal descriptor pointer relocations differ by arch
/// (`ARM64_RELOC_UNSIGNED` vs `X86_64_RELOC_UNSIGNED`), so this returns them as
/// arch-agnostic `PendingTlsReloc`s for the caller to emit.
pub(crate) fn add_tls_global_sections(
    writer: &mut crate::macho::MachOWriter,
    tls_globals: &[&ObjectGlobal],
) -> Result<(Vec<(String, crate::macho::SymbolId)>, Vec<PendingTlsReloc>), PipelineError> {
    let (descriptor_symbols, pending, template_relocs) =
        add_tls_global_sections_with_template_relocs(writer, tls_globals)?;
    // Only the AArch64 Mach-O module emitter consumes template slot
    // relocations. Every other caller (the x86-64 Mach-O emitter) has no
    // `__thread_data` relocation path, so a relocated template must not reach
    // it as a silently constant slot.
    if let Some(reloc) = template_relocs.first() {
        return Err(PipelineError::TargetObjectUnsupported {
            target: "x86_64-apple-darwin".to_string(),
            format: "Mach-O".to_string(),
            reason: format!(
                "thread-local initial-value template slot at __thread_data+{:#x} names `{}`; this emitter has no TLS template relocation path (fail-closed)",
                reloc.offset, reloc.symbol
            ),
        });
    }
    Ok((descriptor_symbols, pending))
}

/// [`add_tls_global_sections`] that also returns the `__thread_data`
/// initial-value-template slot relocations.
///
/// A thread-local whose template embeds symbol addresses (`__thread void *p
/// = &x;`, a per-thread function-pointer or vtable slot) records one
/// `ARM64_RELOC_UNSIGNED` per [`GlobalSymbolRef`] against the template bytes
/// in `__DATA,__thread_data`, exactly as a `__DATA,__data` pointer slot does;
/// any non-zero addend is baked into the slot. ld64 and the in-repo linker
/// turn each into a dyld rebase/bind of the template, and dyld's TLV thunk
/// copies the fixed-up template into every thread's storage, so each thread
/// starts with the relocated pointer. The caller emits the returned slots
/// once every symbol has its final nlist index (with the other
/// [`PendingDataReloc`]s).
pub(crate) fn add_tls_global_sections_with_template_relocs(
    writer: &mut crate::macho::MachOWriter,
    tls_globals: &[&ObjectGlobal],
) -> Result<
    (
        Vec<(String, crate::macho::SymbolId)>,
        Vec<PendingTlsReloc>,
        Vec<PendingDataReloc>,
    ),
    PipelineError,
> {
    use crate::macho::constants::{S_THREAD_LOCAL_REGULAR, S_THREAD_LOCAL_VARIABLES};

    if tls_globals.is_empty() {
        return Ok((Vec::new(), Vec::new(), Vec::new()));
    }
    // Template pointer slots to relocate, as (section-relative offset, target
    // symbol); the `__thread_data` section index is known only after
    // `add_custom_section`.
    let mut template_slots: Vec<(u32, String)> = Vec::new();

    let (descriptor_byte_len, pending_relocation_capacity) =
        checked_aarch64_tls_layout(tls_globals.len())?;

    // --- __thread_data: the initial-value templates. ---
    let mut data_bytes: Vec<u8> = Vec::new();
    let mut init_offsets: Vec<u64> = Vec::new();
    init_offsets
        .try_reserve_exact(tls_globals.len())
        .map_err(|error| {
            PipelineError::ObjectEmission(format!(
                "AArch64 Darwin TLV initializer offset-table allocation failed: {error}"
            ))
        })?;
    for global in tls_globals {
        // Natural-align each template to the next power of two of its size,
        // capped at the pointer width, so an aligned load of the variable through
        // the resolved address is well-formed. (1 -> 1, 2 -> 2, 3/4 -> 4, 5..8 -> 8.)
        let size = global.data.len().max(1);
        let align = if size >= AARCH64_DARWIN_TLV_POINTER_SIZE {
            AARCH64_DARWIN_TLV_POINTER_SIZE
        } else {
            size.next_power_of_two()
        };
        let padding = (align - (data_bytes.len() % align)) % align;
        let padded_len = checked_aarch64_size_sum(
            &global.name,
            "Darwin TLV initializer alignment",
            data_bytes.len(),
            padding,
        )?;
        let final_len = checked_aarch64_size_sum(
            &global.name,
            "Darwin TLV initializer section byte length",
            padded_len,
            global.data.len(),
        )?;
        data_bytes
            .try_reserve(padding + global.data.len())
            .map_err(|error| {
                PipelineError::ObjectEmission(format!(
                    "AArch64 Darwin TLV initializer allocation for `{}` failed: {error}",
                    global.name
                ))
            })?;
        data_bytes.resize(padded_len, 0);
        init_offsets.push(checked_aarch64_object_u64(
            &global.name,
            "Darwin TLV initializer offset",
            data_bytes.len(),
        )?);
        let template_start = data_bytes.len();
        data_bytes.extend_from_slice(&global.data);
        debug_assert_eq!(data_bytes.len(), final_len);
        // Bake any non-zero addend into the 8-byte template slot now (the
        // slot bounds were validated by `validate_aarch64_object_globals`),
        // then record the slot for an `ARM64_RELOC_UNSIGNED` against the
        // template section.
        for sref in &global.symbol_refs {
            let slot_offset = usize::try_from(sref.offset).map_err(|_| {
                PipelineError::ObjectEmission(format!(
                    "AArch64 Darwin TLV template pointer slot offset {} of `{}` exceeds the address space (fail-closed)",
                    sref.offset, global.name
                ))
            })?;
            let slot = checked_aarch64_size_sum(
                &global.name,
                "Darwin TLV template pointer slot offset",
                template_start,
                slot_offset,
            )?;
            let slot_end = checked_aarch64_size_sum(
                &global.name,
                "Darwin TLV template pointer slot end",
                slot,
                AARCH64_DARWIN_TLV_POINTER_SIZE,
            )?;
            let bytes = data_bytes.get_mut(slot..slot_end).ok_or_else(|| {
                PipelineError::ObjectEmission(format!(
                    "AArch64 Darwin TLV template pointer slot [{slot}..{slot_end}) of `{}` exceeds the template section (fail-closed)",
                    global.name
                ))
            })?;
            // Unconditional: `ARM64_RELOC_UNSIGNED` adds the resolved address
            // to the in-place value, so a declared zero addend must erase any
            // placeholder bytes left in the template slot.
            bytes.copy_from_slice(&sref.addend.to_le_bytes());
            let relocation_offset = checked_aarch64_macho_relocation_offset(
                &global.name,
                "Darwin TLV template pointer relocation offset",
                checked_aarch64_object_u32(
                    &global.name,
                    "Darwin TLV template pointer relocation offset",
                    slot,
                )?,
            )?;
            template_slots.push((relocation_offset, sref.symbol.clone()));
        }
    }
    let thread_data_index = writer.add_custom_section(
        b"__thread_data",
        b"__DATA",
        &data_bytes,
        3, // 2^3 = 8-byte section alignment (covers any <= ptr-width template)
        S_THREAD_LOCAL_REGULAR,
    );
    let thread_data_ordinal = thread_data_index + 1;
    let template_relocs: Vec<PendingDataReloc> = template_slots
        .into_iter()
        .map(|(offset, symbol)| PendingDataReloc {
            section_index: thread_data_index,
            offset,
            symbol,
        })
        .collect();

    // Local `X$tlv$init` symbols pointing into __thread_data.
    let init_symbol_ids: Vec<crate::macho::SymbolId> = tls_globals
        .iter()
        .zip(&init_offsets)
        .map(|(global, &offset)| {
            let name = format!("_{}$tlv$init", global.name);
            // The init template is a private local symbol (clang emits it local).
            writer.add_symbol(&name, thread_data_ordinal, offset, false)
        })
        .collect::<Result<Vec<_>, crate::macho::MachOWriteError>>()?;

    // --- __thread_vars: the tlv_descriptor slots, pointer-aligned. ---
    // All descriptor words are placeholder zeros; the linker fills the thunk and
    // init-template pointers via the UNSIGNED relocations recorded below.
    let mut descriptors = Vec::new();
    descriptors
        .try_reserve_exact(descriptor_byte_len)
        .map_err(|error| {
            PipelineError::ObjectEmission(format!(
                "AArch64 Darwin TLV descriptor-table allocation failed: {error}"
            ))
        })?;
    descriptors.resize(descriptor_byte_len, 0);
    let thread_vars_index = writer.add_custom_section(
        b"__thread_vars",
        b"__DATA",
        &descriptors,
        3, // 2^3 = 8-byte (clang uses 2^0, but 8 is safe and natural for ptrs)
        S_THREAD_LOCAL_VARIABLES,
    );
    let thread_vars_ordinal = thread_vars_index + 1;

    // The shared dyld bootstrap thunk — an undefined external import.
    let tlv_bootstrap_id = writer.add_symbol("__tlv_bootstrap", 0, 0, true)?;

    let mut descriptor_symbols: Vec<(String, crate::macho::SymbolId)> = Vec::new();
    descriptor_symbols
        .try_reserve_exact(tls_globals.len())
        .map_err(|error| {
            PipelineError::ObjectEmission(format!(
                "AArch64 Darwin TLV descriptor-symbol allocation failed: {error}"
            ))
        })?;
    let mut pending = Vec::new();
    pending
        .try_reserve_exact(pending_relocation_capacity)
        .map_err(|error| {
            PipelineError::ObjectEmission(format!(
                "AArch64 Darwin TLV relocation-table allocation failed: {error}"
            ))
        })?;
    for (i, global) in tls_globals.iter().enumerate() {
        let desc_offset = checked_aarch64_capacity(
            &global.name,
            "Darwin TLV descriptor offset",
            i,
            AARCH64_DARWIN_TLV_DESCRIPTOR_SIZE,
        )?;
        let desc_symbol_offset = checked_aarch64_object_u64(
            &global.name,
            "Darwin TLV descriptor symbol offset",
            desc_offset,
        )?;
        let thunk_relocation_offset = checked_aarch64_macho_relocation_offset(
            &global.name,
            "Darwin TLV bootstrap relocation offset",
            checked_aarch64_object_u32(
                &global.name,
                "Darwin TLV bootstrap relocation offset",
                desc_offset,
            )?,
        )?;
        let init_relocation_offset = checked_aarch64_size_sum(
            &global.name,
            "Darwin TLV initializer relocation offset",
            desc_offset,
            AARCH64_DARWIN_TLV_INIT_POINTER_OFFSET,
        )?;
        let init_relocation_offset = checked_aarch64_macho_relocation_offset(
            &global.name,
            "Darwin TLV initializer relocation offset",
            checked_aarch64_object_u32(
                &global.name,
                "Darwin TLV initializer relocation offset",
                init_relocation_offset,
            )?,
        )?;
        // The variable symbol `X` names the descriptor slot. A weak thread-local
        // definition coalesces its descriptor across objects (`N_WEAK_DEF`).
        let desc_name = macho_symbol_name(&global.name);
        let desc_symbol_id = writer.add_defined_symbol_with_attrs(
            &desc_name,
            thread_vars_ordinal,
            desc_symbol_offset,
            global.is_external,
            global.is_weak,
            global.visibility,
            global.retained,
        )?;
        descriptor_symbols.push((global.name.clone(), desc_symbol_id));

        // Word 0 (offset desc_offset): thunk = __tlv_bootstrap.
        pending.push(PendingTlsReloc {
            section_index: thread_vars_index,
            offset: thunk_relocation_offset,
            symbol_id: tlv_bootstrap_id,
        });
        // Word 2 (offset desc_offset + 16): offset = X$tlv$init.
        pending.push(PendingTlsReloc {
            section_index: thread_vars_index,
            offset: init_relocation_offset,
            symbol_id: init_symbol_ids[i],
        });
    }

    Ok((descriptor_symbols, pending, template_relocs))
}

/// Linkage class of one function DEFINITION's object symbol.
///
/// This is the function-side analogue of [`ObjectGlobal::is_external`] and
/// [`ObjectGlobal::is_weak`], and trust-ir linkage maps onto it exactly as it
/// maps onto those fields (see [`FunctionSymbolBinding::for_trust_ir_definition`]).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]
pub enum FunctionSymbolLinkage {
    /// Visible to the linker outside this object (Mach-O `N_EXT`, ELF
    /// `STB_GLOBAL`).
    #[default]
    Global,
    /// Defined but not exported (Mach-O: no `N_EXT`, ELF `STB_LOCAL`).
    Local,
    /// A coalescable, overridable definition (ELF `STB_WEAK`, global
    /// partition; Mach-O `N_EXT | N_WEAK_DEF`): a strong definition elsewhere
    /// wins at static link and duplicate weak definitions coalesce. A
    /// default-visibility Mach-O weak definition is also coalesced by dyld
    /// across images, so the AArch64 Mach-O AOT access model addresses it
    /// through the GOT and ld64 routes calls to it through a stub.
    Weak,
}

/// How a whole-module emission should bind one function's DEFINING symbol:
/// its [`FunctionSymbolLinkage`] plus its visibility.
///
/// It matters because a codegen unit's internal helpers are content-hashed:
/// emitting them `STB_GLOBAL` / `N_EXT` makes any two objects that share a hash
/// collide with "duplicate symbol" at static link; a weak or link-once
/// definition emitted strong cannot coalesce or be overridden; and a hidden
/// definition emitted default-visible enters a shared object's export surface.
///
/// ELF spells every combination: `STB_GLOBAL`/`STB_LOCAL`/`STB_WEAK` with
/// `STV_DEFAULT`/`STV_HIDDEN`/`STV_PROTECTED`. Mach-O spells `Global` and
/// `Local`, `Weak` as `N_WEAK_DEF`, hidden as `N_PEXT` and protected as
/// default (as for data globals, and as in LLVM). Visibility is vacuous on a
/// `Local` definition, so [`Self::new`] normalizes it to default there.
///
/// A binding is a SYMBOL-TABLE attribute only. It must never change one byte of
/// the text section, nor any function's offset within it.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]
pub struct FunctionSymbolBinding {
    linkage: FunctionSymbolLinkage,
    visibility: trust_ir::Visibility,
}

impl FunctionSymbolBinding {
    /// `STB_GLOBAL` + `STV_DEFAULT` / `N_EXT`: the default, and what an empty
    /// binding vector means.
    pub const GLOBAL: Self =
        Self::new(FunctionSymbolLinkage::Global, trust_ir::Visibility::Default);
    /// `STB_LOCAL` / no `N_EXT`.
    pub const LOCAL: Self = Self::new(FunctionSymbolLinkage::Local, trust_ir::Visibility::Default);
    /// External for static linking, never exported from a linked image: ELF
    /// `STB_GLOBAL` + `STV_HIDDEN`, Mach-O `N_EXT | N_PEXT`. This is rustc's
    /// `External` linkage + `Hidden` visibility quadrant.
    pub const HIDDEN: Self = Self::new(FunctionSymbolLinkage::Global, trust_ir::Visibility::Hidden);
    /// ELF `STB_WEAK` + `STV_DEFAULT`.
    pub const WEAK: Self = Self::new(FunctionSymbolLinkage::Weak, trust_ir::Visibility::Default);

    /// A binding with `linkage` and `visibility`. Visibility on a `Local`
    /// definition is vacuous and is normalized to default.
    pub const fn new(linkage: FunctionSymbolLinkage, visibility: trust_ir::Visibility) -> Self {
        let visibility = match linkage {
            FunctionSymbolLinkage::Local => trust_ir::Visibility::Default,
            FunctionSymbolLinkage::Global | FunctionSymbolLinkage::Weak => visibility,
        };
        Self {
            linkage,
            visibility,
        }
    }

    /// The binding a trust-ir function DEFINITION with `linkage` and v45
    /// `visibility` requires, or why none exists.
    ///
    /// Linkage is classified exhaustively, exactly like
    /// `module_object_globals` classifies global linkage: `External` is
    /// global; `Weak`/`LinkOnce` and their v41 ODR twins are weak;
    /// `Internal`/`Private` are local; `AvailableExternally` and
    /// `ExternalWeak` are never definitions here. Visibility is carried on a
    /// global or weak binding. On a local one it is refused rather than
    /// normalized away: trust-ir calls `Hidden`/`Protected` with
    /// `Internal`/`Private` contradictory, and [`Self::new`] would silently
    /// drop it.
    pub const fn for_trust_ir_definition(
        linkage: trust_ir::Linkage,
        visibility: trust_ir::Visibility,
    ) -> Result<Self, &'static str> {
        let class = match linkage {
            trust_ir::Linkage::External => FunctionSymbolLinkage::Global,
            trust_ir::Linkage::Weak
            | trust_ir::Linkage::LinkOnce
            | trust_ir::Linkage::WeakOdr
            | trust_ir::Linkage::LinkOnceOdr => FunctionSymbolLinkage::Weak,
            // The module-local arm: exactly trust-ir's proved
            // `Linkage::is_module_local` (pinned by the compiler's
            // `module_local_census_classification_matches_the_elf_local_binding`);
            // kept an arm so the map stays exhaustive.
            trust_ir::Linkage::Internal | trust_ir::Linkage::Private => {
                FunctionSymbolLinkage::Local
            }
            trust_ir::Linkage::AvailableExternally | trust_ir::Linkage::ExternalWeak => {
                return Err("its linkage is declaration-only");
            }
        };
        if matches!(class, FunctionSymbolLinkage::Local)
            && !matches!(visibility, trust_ir::Visibility::Default)
        {
            return Err(
                "a local (`internal`/`private`) definition with non-default visibility is contradictory",
            );
        }
        Ok(Self::new(class, visibility))
    }

    /// Whether a trust-ir function DEFINITION with `linkage` is a COMDAT
    /// definition: exactly the one-definition-rule forms (`LinkOnceOdr`,
    /// `WeakOdr`), whose copies are equivalent, so the copy the linker keeps
    /// agrees with any call the optimizer inlined or folded here.
    ///
    /// The interposable `Weak`/`LinkOnce` forms are NOT: they stay plain
    /// `STB_WEAK` definitions in `.text` (see [`Self::for_trust_ir_definition`])
    /// and the compiler keeps their bodies out of the module inliner and the
    /// structural purity inference, because another object's definition may
    /// replace them at link time.
    pub const fn trust_ir_definition_is_comdat(linkage: trust_ir::Linkage) -> bool {
        matches!(
            linkage,
            trust_ir::Linkage::LinkOnceOdr | trust_ir::Linkage::WeakOdr
        )
    }

    /// The symbol's linkage class.
    pub const fn linkage(self) -> FunctionSymbolLinkage {
        self.linkage
    }

    /// The symbol's visibility (always default for a `Local` binding).
    pub const fn visibility(self) -> trust_ir::Visibility {
        self.visibility
    }

    /// The binding class the preemption predicate reads: `STB_LOCAL` or
    /// not.
    pub const fn definition_binding(self) -> trust_cg_lower::DefinitionBinding {
        match self.linkage {
            FunctionSymbolLinkage::Local => trust_cg_lower::DefinitionBinding::Local,
            FunctionSymbolLinkage::Global | FunctionSymbolLinkage::Weak => {
                trust_cg_lower::DefinitionBinding::Global
            }
        }
    }

    /// Whether another module may preempt a definition with this binding
    /// under `relocation_model`
    /// ([`trust_cg_lower::RelocationModel::definition_is_preemptible`]).
    pub const fn is_preemptible_under(
        self,
        relocation_model: trust_cg_lower::RelocationModel,
    ) -> bool {
        relocation_model.definition_is_preemptible(self.definition_binding(), self.visibility)
    }
}

/// Object-symbol linkage that module emission cannot recover from fixups.
///
/// Fixups name their targets only, so these facts must arrive separately:
/// how each DEFINED function binds ([`FunctionSymbolBinding`], 1:1 with the
/// emitted functions when non-empty), which UNDEFINED function references
/// are weak (trust-ir `ExternalWeak`: an `STB_WEAK` undefined symbol that
/// resolves to null when no definition is linked), and which undefined
/// function references carry a non-default visibility (trust-ir v45
/// `Function.visibility` on a declaration). A weak DATA reference travels
/// on its [`ObjectGlobal`] (`is_import && is_weak`). The default value is
/// the legacy emission: every definition global, every reference strong and
/// default-visibility, every function in the default text section, and an
/// undefined symbol only for a name something in the object references.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct ModuleSymbolLinkage {
    function_bindings: Vec<FunctionSymbolBinding>,
    weak_undefined_functions: BTreeSet<String>,
    undefined_function_visibility: BTreeMap<String, trust_ir::Visibility>,
    comdat_functions: BTreeSet<String>,
    explicit_function_sections: BTreeMap<String, String>,
    declared_undefined_symbols: BTreeSet<String>,
}

impl ModuleSymbolLinkage {
    /// Bindings 1:1 with the emitted functions (or empty for all-global) plus
    /// the names of undefined function references that must be weak. No
    /// function is a COMDAT definition until
    /// [`Self::with_comdat_functions`] names it.
    pub fn new(
        function_bindings: Vec<FunctionSymbolBinding>,
        weak_undefined_functions: BTreeSet<String>,
    ) -> Self {
        Self {
            function_bindings,
            weak_undefined_functions,
            undefined_function_visibility: BTreeMap::new(),
            comdat_functions: BTreeSet::new(),
            explicit_function_sections: BTreeMap::new(),
            declared_undefined_symbols: BTreeSet::new(),
        }
    }

    /// Name the DECLARATIONS whose undefined symbol the AArch64 ELF emitters
    /// write whether or not anything in the object references them, as
    /// llc 22 does (its `AsmPrinter` states a declaration's linkage and
    /// visibility on the symbol): an `extern_weak` declaration and a
    /// declaration with a non-default visibility. Such a symbol changes the
    /// link without a reference: a hidden or protected one keeps the
    /// definition another input supplies out of the dynamic symbol table
    /// (and GNU ld refuses the link when nothing defines it), and the output
    /// records a weak reference. Each name must be an undefined reference
    /// the plan already binds (a weak or visible function declaration, or a
    /// data import), never a definition in the object (validated at
    /// emission). The Mach-O module emitter refuses a non-empty set (it also
    /// refuses every weak or visible reference).
    #[must_use]
    pub fn with_declared_undefined_symbols(
        mut self,
        declared_undefined_symbols: BTreeSet<String>,
    ) -> Self {
        self.declared_undefined_symbols = declared_undefined_symbols;
        self
    }

    /// Declarations written as undefined symbols even when unreferenced.
    pub fn declared_undefined_symbols(&self) -> &BTreeSet<String> {
        &self.declared_undefined_symbols
    }

    /// Per-function definition bindings (empty means all global).
    pub fn function_bindings(&self) -> &[FunctionSymbolBinding] {
        &self.function_bindings
    }

    /// Undefined function references emitted weak.
    pub fn weak_undefined_functions(&self) -> &BTreeSet<String> {
        &self.weak_undefined_functions
    }

    /// Name the visibility of UNDEFINED function references (trust-ir v45
    /// `Function.visibility` on a codegen declaration), keyed by symbol. On
    /// AArch64 ELF each named reference's undefined symbol carries
    /// `STV_HIDDEN`/`STV_PROTECTED` (`STV_DEFAULT` for an explicit
    /// `Default`), so the linker requires its definition in the output being
    /// linked, or resolves a weak one to 0. The relocation-model backstop
    /// refuses a PC-relative page reference to a named reference under every
    /// model: its address must come from the GOT. A name must not also be
    /// defined in the object or name a data global (validated at emission);
    /// Mach-O refuses any non-default entry.
    #[must_use]
    pub fn with_undefined_function_visibility(
        mut self,
        undefined_function_visibility: BTreeMap<String, trust_ir::Visibility>,
    ) -> Self {
        self.undefined_function_visibility = undefined_function_visibility;
        self
    }

    /// Undefined function references with a stated visibility, by symbol.
    pub fn undefined_function_visibility(&self) -> &BTreeMap<String, trust_ir::Visibility> {
        &self.undefined_function_visibility
    }

    /// Name the DEFINED functions that are COMDAT definitions (see
    /// [`FunctionSymbolBinding::trust_ir_definition_is_comdat`]). On AArch64
    /// ELF each is placed alone in a `.text.<symbol>` section inside a
    /// `GRP_COMDAT` group signed by its symbol, so the linker keeps one copy
    /// of its CODE, not only of its symbol. Every such function must be bound
    /// [`FunctionSymbolLinkage::Weak`] (validated at emission); Mach-O has no
    /// section groups and refuses a non-empty set.
    #[must_use]
    pub fn with_comdat_functions(mut self, comdat_functions: BTreeSet<String>) -> Self {
        self.comdat_functions = comdat_functions;
        self
    }

    /// Defined functions placed in their own COMDAT group.
    pub fn comdat_functions(&self) -> &BTreeSet<String> {
        &self.comdat_functions
    }

    /// Name the explicit output section of DEFINED functions (trust-ir v45
    /// `Function.section`), keyed by function name. On AArch64 ELF each named
    /// function's body lands in an `SHF_ALLOC|SHF_EXECINSTR` section of that
    /// name: functions that share a name share one section, a COMDAT function
    /// gets its own grouped section of that name, and `.text` is the shared
    /// default text section (which `-ffunction-sections` does not split). The
    /// name is validated at emission
    /// ([`crate::object_sections::classify_elf_function_section`]); Mach-O
    /// refuses a non-empty map.
    #[must_use]
    pub fn with_explicit_function_sections(
        mut self,
        explicit_function_sections: BTreeMap<String, String>,
    ) -> Self {
        self.explicit_function_sections = explicit_function_sections;
        self
    }

    /// Defined functions with an explicit output section, by function name.
    pub fn explicit_function_sections(&self) -> &BTreeMap<String, String> {
        &self.explicit_function_sections
    }
}

/// The ELF emitters' validated view of a [`ModuleSymbolLinkage`]: the
/// function bindings, every undefined name that must be `STB_WEAK` (weak
/// function references and weak data imports), and the visibility of each
/// undefined function reference that states one.
struct ElfModuleSymbolPlan<'a> {
    function_bindings: &'a [FunctionSymbolBinding],
    weak_undefined: BTreeSet<&'a str>,
    /// Validated undefined function reference visibility, by symbol.
    undefined_visibility: BTreeMap<&'a str, trust_ir::Visibility>,
    /// Validated non-default data import visibility, by symbol.
    undefined_data_visibility: BTreeMap<&'a str, trust_ir::Visibility>,
    /// Defined functions placed alone in a COMDAT-grouped text section.
    comdat_functions: BTreeSet<&'a str>,
    /// Validated explicit function sections, by function name.
    explicit_sections: BTreeMap<&'a str, &'a str>,
    /// Validated declarations written as undefined symbols even when
    /// nothing in the object references them
    /// ([`ModuleSymbolLinkage::with_declared_undefined_symbols`]).
    declared_undefined: BTreeSet<&'a str>,
}

impl<'a> ElfModuleSymbolPlan<'a> {
    /// Every definition global, every reference strong.
    fn legacy() -> Self {
        Self {
            function_bindings: &[],
            weak_undefined: BTreeSet::new(),
            undefined_visibility: BTreeMap::new(),
            undefined_data_visibility: BTreeMap::new(),
            comdat_functions: BTreeSet::new(),
            explicit_sections: BTreeMap::new(),
            declared_undefined: BTreeSet::new(),
        }
    }

    /// Validate `linkage` against the object's definitions. A weak undefined
    /// name that is also defined here, or that also names a data global, has
    /// no single meaning and is refused.
    fn new(
        linkage: &'a ModuleSymbolLinkage,
        func_offsets: &[(String, u64)],
        globals: &'a [ObjectGlobal],
    ) -> Result<Self, PipelineError> {
        let function_bindings = linkage.function_bindings();
        if !function_bindings.is_empty() && function_bindings.len() != func_offsets.len() {
            return Err(PipelineError::ObjectEmission(format!(
                "ELF module emission received {} symbol binding(s) for {} function(s); a \
                 binding vector must be empty or 1:1 with the functions (fail-closed)",
                function_bindings.len(),
                func_offsets.len()
            )));
        }
        let defined_functions: BTreeSet<&str> =
            func_offsets.iter().map(|(name, _)| name.as_str()).collect();
        let mut weak_undefined = BTreeSet::new();
        for name in linkage.weak_undefined_functions() {
            if name.is_empty() {
                return Err(PipelineError::ObjectEmission(
                    "ELF weak undefined function reference has an empty name (fail-closed)"
                        .to_string(),
                ));
            }
            if defined_functions.contains(name.as_str()) {
                return Err(PipelineError::ObjectEmission(format!(
                    "ELF weak undefined function reference `{name}` is also defined in this \
                     object (fail-closed)"
                )));
            }
            if globals.iter().any(|global| global.name == *name) {
                return Err(PipelineError::ObjectEmission(format!(
                    "ELF weak undefined function reference `{name}` also names a data global \
                     (fail-closed)"
                )));
            }
            weak_undefined.insert(name.as_str());
        }
        for global in globals
            .iter()
            .filter(|global| global.is_import && global.is_weak)
        {
            if defined_functions.contains(global.name.as_str()) {
                return Err(PipelineError::ObjectEmission(format!(
                    "ELF weak undefined data reference `{}` is also defined as a function in \
                     this object (fail-closed)",
                    global.name
                )));
            }
            weak_undefined.insert(global.name.as_str());
        }
        // A declaration's visibility belongs to an undefined FUNCTION
        // reference: a name defined here has its visibility on its binding,
        // and a data import's is its `ObjectGlobal`'s (collected below).
        let mut undefined_visibility = BTreeMap::new();
        for (name, visibility) in linkage.undefined_function_visibility() {
            if name.is_empty() {
                return Err(PipelineError::ObjectEmission(
                    "ELF undefined function reference visibility names an empty symbol \
                     (fail-closed)"
                        .to_string(),
                ));
            }
            if defined_functions.contains(name.as_str()) {
                return Err(PipelineError::ObjectEmission(format!(
                    "ELF undefined function reference `{name}` (visibility {visibility}) is also \
                     defined in this object (fail-closed)"
                )));
            }
            if globals.iter().any(|global| global.name == *name) {
                return Err(PipelineError::ObjectEmission(format!(
                    "ELF undefined function reference `{name}` (visibility {visibility}) also \
                     names a data global (fail-closed)"
                )));
            }
            undefined_visibility.insert(name.as_str(), *visibility);
        }
        // A data import's stated visibility belongs to its undefined symbol
        // the same way. A name this object also defines as a function has no
        // single meaning.
        let mut undefined_data_visibility = BTreeMap::new();
        for global in globals
            .iter()
            .filter(|global| global.is_import && global.visibility != trust_ir::Visibility::Default)
        {
            if defined_functions.contains(global.name.as_str()) {
                return Err(PipelineError::ObjectEmission(format!(
                    "ELF undefined data reference `{}` (visibility {}) is also defined as a \
                     function in this object (fail-closed)",
                    global.name, global.visibility
                )));
            }
            undefined_data_visibility.insert(global.name.as_str(), global.visibility);
        }
        // A COMDAT function is a WEAK definition in this object: its group is
        // signed by its symbol, and a strong or local signature would defeat
        // (or misname) the one-copy rule.
        let mut comdat_functions = BTreeSet::new();
        for name in linkage.comdat_functions() {
            let Some(index) = func_offsets
                .iter()
                .position(|(function, _)| function == name)
            else {
                return Err(PipelineError::ObjectEmission(format!(
                    "ELF COMDAT function `{name}` is not defined in this object (fail-closed)"
                )));
            };
            let binding =
                function_symbol_binding_at(function_bindings, index, func_offsets.len(), name)?;
            if binding.linkage() != FunctionSymbolLinkage::Weak {
                return Err(PipelineError::ObjectEmission(format!(
                    "ELF COMDAT function `{name}` is bound {:?}; a COMDAT definition must be \
                     weak (fail-closed)",
                    binding.linkage()
                )));
            }
            comdat_functions.insert(name.as_str());
        }
        // An explicit function section names a function defined here, is an
        // executable ELF name, and is not also a data global's section (the
        // linker would merge code and data into one output section).
        let mut explicit_sections = BTreeMap::new();
        for (function, section) in linkage.explicit_function_sections() {
            let refuse = |code, reason: String| PipelineError::ExplicitFunctionSectionUnsupported {
                function: function.clone(),
                section: section.clone(),
                format: "ELF",
                code,
                reason,
            };
            if !defined_functions.contains(function.as_str()) {
                return Err(refuse(
                    crate::object_sections::SectionRefusal::Import,
                    "the function is not defined in this object".to_string(),
                ));
            }
            crate::object_sections::classify_elf_function_section(section)
                .map_err(|(code, reason)| refuse(code, reason))?;
            if section == ".text" && comdat_functions.contains(function.as_str()) {
                return Err(refuse(
                    crate::object_sections::SectionRefusal::ReservedName,
                    "a COMDAT function is alone in its own grouped section, and `.text` names the shared default text section".to_string(),
                ));
            }
            if let Some(global) = globals
                .iter()
                .find(|global| !global.is_import && global.section.as_deref() == Some(section))
            {
                return Err(refuse(
                    crate::object_sections::SectionRefusal::FlagConflict,
                    format!(
                        "data global `{}` is placed in the same section; code and data cannot share one ELF section's flags",
                        global.name
                    ),
                ));
            }
            explicit_sections.insert(function.as_str(), section.as_str());
        }
        // A declaration written even when unreferenced is an undefined
        // reference this plan already binds: a weak or visible function
        // declaration, or a data import, and never a name defined here.
        let mut declared_undefined = BTreeSet::new();
        for name in linkage.declared_undefined_symbols() {
            let data_import = globals
                .iter()
                .find(|global| global.name == *name)
                .map(|global| global.is_import);
            let bound = match data_import {
                Some(is_import) => is_import && !defined_functions.contains(name.as_str()),
                None => {
                    !defined_functions.contains(name.as_str())
                        && (weak_undefined.contains(name.as_str())
                            || undefined_visibility.contains_key(name.as_str()))
                }
            };
            if !bound {
                return Err(PipelineError::ObjectEmission(format!(
                    "ELF declared undefined symbol `{name}` is not a weak or visible function \
                     declaration or a data import of this object (fail-closed)"
                )));
            }
            declared_undefined.insert(name.as_str());
        }
        Ok(Self {
            function_bindings,
            weak_undefined,
            undefined_visibility,
            undefined_data_visibility,
            comdat_functions,
            explicit_sections,
            declared_undefined,
        })
    }

    /// The declarations the object writes as undefined symbols although
    /// nothing in it may reference them, in name order, without those
    /// `known` already names.
    fn unreferenced_declarations<'k>(
        &'k self,
        known: &'k BTreeSet<String>,
    ) -> impl Iterator<Item = &'a str> + 'k {
        self.declared_undefined
            .iter()
            .copied()
            .filter(move |name| !known.contains(*name))
    }

    /// How the object names undefined `name` (a symbol it does not define):
    /// weak or strong, with its stated visibility (a function declaration's
    /// or a data import's; default otherwise).
    fn undefined_reference(
        &self,
        name: &str,
    ) -> (trust_cg_lower::SymbolBinding, trust_ir::Visibility) {
        (
            trust_cg_lower::SymbolBinding::Undefined {
                weak: self.weak_undefined.contains(name),
            },
            self.undefined_visibility
                .get(name)
                .or_else(|| self.undefined_data_visibility.get(name))
                .copied()
                .unwrap_or_default(),
        )
    }
}

/// Mach-O module emission spells function `Local`/`Global`/`Weak`/hidden
/// definition bindings (`N_WEAK_DEF` for weak) and spells a COMDAT function as
/// the weak definition it must be bound as (Mach-O has no section groups;
/// ld64 keeps one copy of each `N_WEAK_DEF` atom because every object sets
/// `MH_SUBSECTIONS_VIA_SYMBOLS`). It does not spell a weak undefined reference
/// (`N_WEAK_REF`) or a hidden or protected undefined reference: refuse either
/// before any byte is emitted rather than emit it strong or default-visible.
fn reject_macho_weak_symbol_linkage(
    target_triple: &str,
    functions: &[IrMachFunction],
    linkage: &ModuleSymbolLinkage,
    globals: &[ObjectGlobal],
) -> Result<(), PipelineError> {
    let refuse = |reason: String| PipelineError::TargetObjectUnsupported {
        target: target_triple.to_string(),
        format: "Mach-O".to_string(),
        reason,
    };
    if let Some(name) = linkage.weak_undefined_functions().first() {
        return Err(refuse(format!(
            "weak undefined function reference `{name}`: the Mach-O module emitter does not \
             emit N_WEAK_REF references (fail-closed)"
        )));
    }
    if let Some((name, visibility)) = linkage
        .undefined_function_visibility()
        .iter()
        .find(|(_, visibility)| **visibility != trust_ir::Visibility::Default)
    {
        return Err(refuse(format!(
            "undefined function reference `{name}` states visibility `{visibility}`: the Mach-O \
             module emitter spells no visibility on an undefined symbol (fail-closed)"
        )));
    }
    if let Some((function, section)) = linkage.explicit_function_sections().first_key_value() {
        return Err(PipelineError::ExplicitFunctionSectionUnsupported {
            function: function.clone(),
            section: section.clone(),
            format: "Mach-O",
            code: crate::object_sections::SectionRefusal::TargetUnsupported,
            reason:
                "the Mach-O module emitter places every function in `__TEXT,__text`; it has no \
                     per-function `segment,section` placement"
                    .to_string(),
        });
    }
    for name in linkage.comdat_functions() {
        let Some(index) = functions.iter().position(|function| &function.name == name) else {
            return Err(refuse(format!(
                "COMDAT function `{name}` is not defined in this object (fail-closed)"
            )));
        };
        let binding =
            function_symbol_binding_at(linkage.function_bindings(), index, functions.len(), name)?;
        if binding.linkage() != FunctionSymbolLinkage::Weak {
            return Err(refuse(format!(
                "COMDAT function `{name}` is bound {:?}; Mach-O has no section groups, so a \
                 COMDAT definition must be an N_WEAK_DEF definition (fail-closed)",
                binding.linkage()
            )));
        }
    }
    if let Some(global) = globals
        .iter()
        .find(|global| global.is_import && global.is_weak)
    {
        return Err(refuse(format!(
            "weak undefined data reference `{}`: the Mach-O module emitter does not emit \
             N_WEAK_REF references (fail-closed)",
            global.name
        )));
    }
    // `Compiler::compile` names only weak or visible declarations, which
    // Mach-O refuses anyway (above, and a data import's visibility in
    // `validate_aarch64_object_globals_with`); a set built through the
    // public API must not be dropped silently either.
    if let Some(name) = linkage.declared_undefined_symbols().first() {
        return Err(refuse(format!(
            "declaration `{name}` is to be written as an undefined symbol whether or not anything \
             references it: the Mach-O module emitter writes an undefined symbol only for a name \
             the object references (fail-closed)"
        )));
    }
    Ok(())
}

/// The binding for `index`, defaulting to [`FunctionSymbolBinding::GLOBAL`].
///
/// An EMPTY `bindings` slice means "every definition is global", which is what
/// keeps every pre-existing caller byte-identical.
///
/// A NON-empty slice must be 1:1 with the module's functions. A length mismatch
/// is a caller bug that silently mis-binds symbols — every binding past the
/// short point slides onto the wrong definition — so it FAILS CLOSED instead of
/// defaulting. Defaulting is the dangerous choice precisely because it is
/// invisible: the object still emits, and the damage surfaces at static link as
/// a duplicate or missing symbol far from the mis-sized vector that caused it.
fn function_symbol_binding_at(
    bindings: &[FunctionSymbolBinding],
    index: usize,
    function_count: usize,
    function_name: &str,
) -> Result<FunctionSymbolBinding, PipelineError> {
    if bindings.is_empty() {
        return Ok(FunctionSymbolBinding::GLOBAL);
    }
    if bindings.len() != function_count {
        return Err(PipelineError::ObjectEmission(format!(
            "function symbol-binding vector has {} entries for a {function_count}-function \
             module (fail-closed: a mis-indexed binding would mark the wrong definition local)",
            bindings.len()
        )));
    }
    bindings.get(index).copied().ok_or_else(|| {
        PipelineError::ObjectEmission(format!(
            "no symbol binding recorded for function `{function_name}` at index {index}"
        ))
    })
}

/// Whether `name` is a symbol this ELF object defines `STB_LOCAL`: a function
/// whose planned binding is local, or a non-external, non-import data row.
/// Such a symbol is invisible to other objects, so any indirection the
/// emitter synthesizes for it (the `DW.ref` personality slot) must be
/// object-local too.
fn elf_symbol_binds_locally_in_object(
    name: &str,
    func_offsets: &[(String, u64)],
    plan: &ElfModuleSymbolPlan<'_>,
    globals: &[ObjectGlobal],
) -> Result<bool, PipelineError> {
    let count = func_offsets.len();
    for (index, (function, _)) in func_offsets.iter().enumerate() {
        if function == name {
            let binding =
                function_symbol_binding_at(plan.function_bindings, index, count, function)?;
            return Ok(binding.linkage() == FunctionSymbolLinkage::Local);
        }
    }
    Ok(globals
        .iter()
        .any(|global| global.name == name && !global.is_external && !global.is_import))
}

/// Where one function's machine code landed inside the emitted text section.
///
/// `offset` and `len` are both relative to, and measured in, the combined text
/// section: `offset` is the function's first byte AFTER any inter-function
/// alignment padding, and `len` is its ENCODED body length, excluding trailing
/// padding. That is deliberately not the ELF `st_size` a linker would compute
/// from consecutive symbol offsets (which includes padding) — a consumer
/// cross-checks `len` against the bytes of that function emitted ALONE, and a
/// single-function object's whole text section is exactly its encoded body.
///
/// `name` is the IR-level function name, NOT the object-file symbol: Mach-O
/// prefixes every symbol with `_`, and consumers look extents up by the
/// unprefixed name.
///
/// On AArch64 ELF with the function-sections policy (or an ODR COMDAT
/// function) the object moves bodies into `.text.<symbol>` sections and
/// re-packs the rest; extents still describe the COMBINED stream, so a
/// consumer must locate each body through its symbol, not at `offset` in
/// `.text`. The body bytes themselves are unchanged by the split.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TextFunctionExtent {
    /// IR-level function name, without any object-format symbol prefix.
    pub name: String,
    /// First byte of the function within the combined text section.
    pub offset: u64,
    /// Encoded body length in bytes, excluding inter-function padding.
    pub len: u64,
}

/// A whole-module object plus the text layout the emitter actually produced.
///
/// The layout is reported rather than re-derived because a consumer that wants
/// to prove the shipped bytes are the bytes it verified must compare against
/// what the emitter DID, not against an independent guess at what it should
/// have done.
#[derive(Debug, Clone)]
pub struct ModuleEmission {
    /// The complete object file.
    pub object: Vec<u8>,
    /// One entry per emitted function, in emission order.
    pub text_extents: Vec<TextFunctionExtent>,
}

/// A whole-module AArch64 emission paired with its validated ISA requirements.
///
/// Construction stays private so safe callers cannot accidentally associate
/// requirements derived from one module with another module's bytes. Use the
/// evidence-returning [`Pipeline`] emission APIs to obtain this value.
#[derive(Debug, Clone)]
pub struct AArch64ModuleEmission {
    emission: ModuleEmission,
    machine_code: AArch64MachineCodeEvidence,
}

impl AArch64ModuleEmission {
    fn new(emission: ModuleEmission, machine_code: AArch64MachineCodeEvidence) -> Self {
        Self {
            emission,
            machine_code,
        }
    }

    /// Object bytes and exact per-function text layout produced by the emitter.
    pub const fn emission(&self) -> &ModuleEmission {
        &self.emission
    }

    /// Validated union of optional ISA features required by the module.
    pub const fn machine_code(&self) -> AArch64MachineCodeEvidence {
        self.machine_code
    }

    /// Consume the evidence-bearing result and return its legacy emission.
    pub fn into_emission(self) -> ModuleEmission {
        self.emission
    }

    /// Consume the result into its object/layout and target-feature evidence.
    pub fn into_parts(self) -> (ModuleEmission, AArch64MachineCodeEvidence) {
        (self.emission, self.machine_code)
    }
}

/// Mach-O keeps two deliberately disjoint symbol namespaces.
///
/// Ordinary references use ABI-decorated names (`foo` -> `_foo`). Exact calls
/// use the raw TrustIR/LIR function name and can only select a definition in
/// this object. Mixing raw and decorated aliases in one map makes `{foo,_foo}`
/// order-dependent: the raw `_foo` key can overwrite `foo`'s decorated alias.
struct MachOSymbolIndexMaps {
    ordinary_by_abi_name: HashMap<String, u32>,
    exact_function_by_raw_name: HashMap<String, u32>,
}

struct MachOSymbolIdMaps {
    ordinary_by_abi_name: HashMap<String, crate::macho::SymbolId>,
    exact_function_by_raw_name: HashMap<String, crate::macho::SymbolId>,
}

/// One explicit Mach-O section and the indices (into the module's globals) of
/// the definitions placed in it, in declaration order.
struct MachOPlacedSection {
    class: crate::object_sections::MachOExplicitSection,
    members: Vec<usize>,
}

/// The Mach-O explicit-section plan for a module's globals.
struct MachOPlacementPlan {
    sections: Vec<MachOPlacedSection>,
    /// Globals whose explicit section IS the implicit `__DATA,__data`.
    implicit_data: Vec<String>,
    /// Globals whose explicit section IS the implicit `__TEXT,__const`.
    implicit_const: Vec<String>,
    /// Globals whose explicit section IS the implicit `__DATA,__const` (the
    /// read-only-after-fixup home of relocated immutable globals).
    implicit_data_const: Vec<String>,
}

/// Resolve every explicit Mach-O section request (trust-ir v41
/// `Global.section`) through [`crate::object_sections::classify_macho_section`]
/// and group the members of each `segment,section`. Members of one section
/// must derive identical flags and placement
/// ([`crate::object_sections::SectionRefusal::FlagConflict`] otherwise).
fn plan_macho_explicit_sections(
    globals: &[ObjectGlobal],
) -> Result<MachOPlacementPlan, PipelineError> {
    use crate::object_sections::{SectionRefusal, classify_macho_section};

    let refusal =
        |global: &ObjectGlobal, name: &str, (code, reason): crate::object_sections::Refusal| {
            PipelineError::ExplicitSectionUnsupported {
                global: global.name.clone(),
                section: name.to_string(),
                format: "Mach-O",
                code,
                reason,
            }
        };
    let mut plan = MachOPlacementPlan {
        sections: Vec::new(),
        implicit_data: Vec::new(),
        implicit_const: Vec::new(),
        implicit_data_const: Vec::new(),
    };
    for (index, global) in globals.iter().enumerate() {
        let Some(name) = global.section.as_deref() else {
            continue;
        };
        if global.is_import {
            continue; // refused by `validate_aarch64_object_globals`
        }
        let class = classify_macho_section(global, name)
            .map_err(|failure| refusal(global, name, failure))?;
        let implicit_alias = match (class.segname.as_str(), class.sectname.as_str()) {
            ("__DATA", "__data") => Some(&mut plan.implicit_data),
            ("__TEXT", "__const") => Some(&mut plan.implicit_const),
            ("__DATA", "__const") => Some(&mut plan.implicit_data_const),
            _ => None,
        };
        if let Some(alias) = implicit_alias {
            if class.flags != crate::macho::constants::S_REGULAR {
                return Err(refusal(
                    global,
                    name,
                    (
                        SectionRefusal::FlagConflict,
                        "the emitter's own section of this name is S_REGULAR without attributes"
                            .to_string(),
                    ),
                ));
            }
            alias.push(global.name.clone());
            continue;
        }
        match plan.sections.iter_mut().find(|section| {
            section.class.segname == class.segname && section.class.sectname == class.sectname
        }) {
            Some(section) => {
                if section.class != class {
                    return Err(refusal(
                        global,
                        name,
                        (
                            SectionRefusal::FlagConflict,
                            format!(
                                "it derives flags {:#x} but `{}` in the same section derives {:#x}",
                                class.flags, globals[section.members[0]].name, section.class.flags
                            ),
                        ),
                    ));
                }
                section.members.push(index);
            }
            None => plan.sections.push(MachOPlacedSection {
                class,
                members: vec![index],
            }),
        }
    }
    Ok(plan)
}

fn add_module_symbols_for_fixups(
    writer: &mut crate::macho::MachOWriter,
    func_offsets: &[(String, u64)],
    globals: &[ObjectGlobal],
    fixups: &crate::macho::fixup::FixupList,
    // 1:1 with `func_offsets` when non-empty; empty means "all global".
    bindings: &[FunctionSymbolBinding],
    // Linker-level names data outside `__text` relocates against (typed-catch
    // typeinfo symbols in `__gcc_except_tab`): resolved to an in-module
    // definition or registered as undefined externals here, so the symbol
    // table is final before any nlist index is read.
    extra_undefined_names: &BTreeSet<String>,
) -> Result<MachOSymbolIndexMaps, PipelineError> {
    use crate::macho::FixupTarget;

    if let Some(global) = globals
        .iter()
        .find(|global| global.is_import && global.is_weak)
    {
        return Err(PipelineError::ObjectEmission(format!(
            "Mach-O module import `{}` is a weak undefined reference, which this emitter \
             does not spell (fail-closed)",
            global.name
        )));
    }

    let mut ordinary_symbol_ids = Vec::new();
    let mut exact_function_symbol_ids = Vec::new();
    let mut known_abi_names = BTreeSet::new();
    let defined_functions: BTreeSet<&str> =
        func_offsets.iter().map(|(name, _)| name.as_str()).collect();

    // Thread-local globals route to the Darwin TLV sections, not __data/__const.
    // An IMPORT (a cross-object reference to a descriptor defined elsewhere) is
    // EXCLUDED here: it defines no descriptor / template, so its `__text` TLVP
    // fixup falls through to the undefined-external path below and the linker
    // resolves it to the single canonical descriptor in the defining object.
    let tls_globals: Vec<&ObjectGlobal> = globals
        .iter()
        .filter(|global| global.is_thread_local && !global.is_import)
        .collect();
    // A non-TLS DATA IMPORT (initializer-less external global — see compiler.rs
    // `is_import`) defines no bytes here; it is a reference to a `static` DEFINED
    // in another object. It must be EXCLUDED from the __data/__const definition
    // lists (exactly like the TLS-import exclusion above) — otherwise it is
    // emitted as a 0-byte symbol DEFINITION and collides with the real
    // definition at link time (`duplicate symbol`). Its GOT reference
    // (`ExternRef` -> @GOTPAGE) falls through to the undefined-external path and
    // the linker resolves it to the defining object.
    // A global carrying symbol-address relocations (a vtable, a `static FNS:
    // [fn(); N]`) cannot live in `__TEXT,__const`: an `ARM64_RELOC_UNSIGNED`
    // cannot be applied there (the text segment is read-only / code-signed and
    // dyld does not rebase it). A MUTABLE one lives in `__DATA,__data`. An
    // IMMUTABLE one is written only by dyld's fixups, so it lives in
    // `__DATA,__const`, exactly where clang puts it: ld64 (and the in-repo
    // linker) place that section in the `SG_READ_ONLY` `__DATA_CONST` segment,
    // which dyld write-protects once its fixups are applied. That is the Mach-O
    // equivalent of ELF `.data.rel.ro` inside `PT_GNU_RELRO`. Plain
    // relocation-free globals keep their mutable(`__data`)/immutable
    // (`__TEXT,__const`) placement.
    let relocated_immutable =
        |global: &&ObjectGlobal| !global.mutable && !global.symbol_refs.is_empty();
    // Explicit sections (trust-ir v41 `Global.section`) are resolved first; a
    // request that names the implicit `__DATA,__data` / `__DATA,__const` /
    // `__TEXT,__const` section with no extra attributes joins it rather than
    // duplicating it (a mutable `__DATA,__const` request is refused by
    // `classify_macho_section`).
    let placed = plan_macho_explicit_sections(globals)?;
    let implicit = |global: &&ObjectGlobal| {
        placed
            .implicit_data
            .iter()
            .chain(&placed.implicit_const)
            .chain(&placed.implicit_data_const)
            .any(|name| *name == global.name)
            || global.section.is_none()
    };
    let explicit_data = |global: &&ObjectGlobal| placed.implicit_data.contains(&global.name);
    let explicit_data_const =
        |global: &&ObjectGlobal| placed.implicit_data_const.contains(&global.name);
    let defined_ordinary = |global: &&ObjectGlobal| !global.is_thread_local && !global.is_import;
    let mutable_globals: Vec<&ObjectGlobal> = globals
        .iter()
        .filter(implicit)
        .filter(|global| {
            defined_ordinary(global)
                && !explicit_data_const(global)
                && (global.mutable || explicit_data(global))
        })
        .collect();
    let relocated_const_globals: Vec<&ObjectGlobal> = globals
        .iter()
        .filter(implicit)
        .filter(|global| {
            defined_ordinary(global)
                && !global.mutable
                && !explicit_data(global)
                && (relocated_immutable(global) || explicit_data_const(global))
        })
        .collect();
    let immutable_globals: Vec<&ObjectGlobal> = globals
        .iter()
        .filter(implicit)
        .filter(|global| {
            defined_ordinary(global)
                && !global.mutable
                && !relocated_immutable(global)
                && !explicit_data(global)
                && !explicit_data_const(global)
        })
        .collect();
    let (data_symbols, mut pending_data_relocs) =
        add_global_data_section(writer, &mutable_globals)?;
    let (data_const_symbols, data_const_relocs) =
        add_global_data_const_section(writer, &relocated_const_globals)?;
    pending_data_relocs.extend(data_const_relocs);
    let mut placed_symbols = Vec::new();
    for section in &placed.sections {
        let members: Vec<&ObjectGlobal> = section
            .members
            .iter()
            .map(|&index| &globals[index])
            .collect();
        match section.class.placement {
            crate::object_sections::MachOPlacement::Data => {
                let (symbols, relocs) = add_global_data_section_named(
                    writer,
                    &members,
                    section.class.segname.as_bytes(),
                    section.class.sectname.as_bytes(),
                    section.class.flags,
                    section.class.min_align,
                )?;
                placed_symbols.extend(symbols);
                pending_data_relocs.extend(relocs);
            }
            crate::object_sections::MachOPlacement::Const => {
                placed_symbols.extend(add_global_const_section_named(
                    writer,
                    &members,
                    section.class.segname.as_bytes(),
                    section.class.sectname.as_bytes(),
                    section.class.flags,
                )?);
            }
        }
    }
    for (name, symbol_id) in data_symbols
        .into_iter()
        .chain(data_const_symbols)
        .chain(add_global_const_section(writer, &immutable_globals)?)
        .chain(placed_symbols)
    {
        let symbol_name = macho_symbol_name(&name);
        ordinary_symbol_ids.push((symbol_name.clone(), symbol_id));
        known_abi_names.insert(symbol_name);
    }

    // TLV descriptor sections + their descriptor symbols (so __text TLVP fixups
    // resolve to `_X`). The descriptor relocations are emitted after all symbols
    // exist, so their `r_symbolnum` can use the final nlist order. A template
    // whose bytes embed symbol addresses adds `__thread_data` pointer slots to
    // the deferred data relocations below (registering any undefined target).
    let (tls_descriptor_symbols, pending_tls_relocs, tls_template_relocs) =
        add_tls_global_sections_with_template_relocs(writer, &tls_globals)?;
    pending_data_relocs.extend(tls_template_relocs);
    for (name, symbol_id) in tls_descriptor_symbols {
        let symbol_name = macho_symbol_name(&name);
        ordinary_symbol_ids.push((symbol_name.clone(), symbol_id));
        known_abi_names.insert(symbol_name);
    }

    for (index, (name, offset)) in func_offsets.iter().enumerate() {
        let symbol_name = macho_symbol_name(name);
        // The ONLY place a function's binding is honoured on the Mach-O path.
        // `Local` clears `N_EXT`, which is what makes an Internal-linkage
        // definition invisible outside this object while its intra-object
        // callers still resolve. Hidden keeps `N_EXT` and adds `N_PEXT`
        // (private extern): external for static linking, demoted to a local by
        // the final link. Protected has no Mach-O spelling and is default, as
        // for data globals. `Weak` adds `N_WEAK_DEF` (with `N_PEXT` when
        // hidden). The Mach-O writer recomputes the locals-first nlist
        // partition itself.
        let binding = function_symbol_binding_at(bindings, index, func_offsets.len(), name)?;
        let symbol_id = match (binding.linkage(), binding.visibility()) {
            (FunctionSymbolLinkage::Local, _) => {
                writer.add_symbol(&symbol_name, 1, *offset, false)?
            }
            (FunctionSymbolLinkage::Global, trust_ir::Visibility::Hidden) => {
                writer.add_private_extern_symbol(&symbol_name, 1, *offset)?
            }
            (
                FunctionSymbolLinkage::Global,
                trust_ir::Visibility::Default | trust_ir::Visibility::Protected,
            ) => writer.add_symbol(&symbol_name, 1, *offset, true)?,
            (FunctionSymbolLinkage::Weak, visibility) => writer.add_defined_symbol_with_attrs(
                &symbol_name,
                1,
                *offset,
                true,
                true,
                visibility,
                false,
            )?,
        };
        ordinary_symbol_ids.push((symbol_name.clone(), symbol_id));
        exact_function_symbol_ids.push((name.clone(), symbol_id));
        known_abi_names.insert(symbol_name);
    }

    let mut undefined_names = BTreeSet::new();
    for fixup in fixups.iter() {
        match &fixup.target {
            FixupTarget::NamedSymbol(name) => {
                let symbol_name = macho_symbol_name(name);
                if !known_abi_names.contains(&symbol_name) {
                    undefined_names.insert(name.clone());
                }
            }
            FixupTarget::ExactNamedSymbol(name) if !defined_functions.contains(name.as_str()) => {
                return Err(PipelineError::ObjectEmission(format!(
                    "exact module call targets missing AArch64 function `{name}`"
                )));
            }
            _ => {}
        }
    }
    // A data-section symbol-address slot (vtable / `static FNS` element) may
    // target a symbol that no `__text` fixup references — e.g. an external
    // function whose address is only ever taken in data. Register it as an
    // undefined external too, so the relocation below resolves rather than
    // failing closed.
    for reloc in &pending_data_relocs {
        let symbol_name = macho_symbol_name(&reloc.symbol);
        if !known_abi_names.contains(&symbol_name) {
            undefined_names.insert(reloc.symbol.clone());
        }
    }
    for name in extra_undefined_names {
        if !known_abi_names.contains(&macho_symbol_name(name)) {
            undefined_names.insert(name.clone());
        }
    }

    for name in undefined_names {
        let symbol_name = macho_symbol_name(&name);
        let symbol_id = writer.add_symbol(&symbol_name, 0, 0, true)?;
        ordinary_symbol_ids.push((symbol_name.clone(), symbol_id));
        known_abi_names.insert(symbol_name);
    }

    // Now that every symbol exists, emit the deferred `__thread_vars` descriptor
    // relocations (thunk + init-template pointers) using final nlist indices.
    for reloc in pending_tls_relocs {
        let final_index = writer.final_symbol_index(reloc.symbol_id)?.ok_or_else(|| {
            PipelineError::ObjectEmission(
                "TLV descriptor relocation symbol missing before emission".to_string(),
            )
        })?;
        writer.add_relocation(
            reloc.section_index,
            crate::macho::reloc::Relocation::unsigned_ptr(reloc.offset, final_index),
        )?;
    }

    // Emit the deferred data-section symbol-address relocations
    // (`ARM64_RELOC_UNSIGNED`, 8-byte absolute pointers) using final nlist
    // indices — the same "all symbols first, then relocations" ordering the TLS
    // descriptors above use. The target was registered as an in-module
    // definition (function or data global) or as an undefined external above, so
    // its insertion-time id is present in `ordinary_symbol_ids`.
    if !pending_data_relocs.is_empty() {
        let abi_name_to_symbol_id: HashMap<&str, crate::macho::SymbolId> = ordinary_symbol_ids
            .iter()
            .map(|(name, id)| (name.as_str(), *id))
            .collect();
        for reloc in &pending_data_relocs {
            let symbol_id = abi_name_to_symbol_id
                .get(macho_symbol_name(&reloc.symbol).as_str())
                .copied()
                .ok_or_else(|| {
                    PipelineError::ObjectEmission(format!(
                        "data-relocation target {:?} was not registered",
                        reloc.symbol
                    ))
                })?;
            let final_index = writer.final_symbol_index(symbol_id)?.ok_or_else(|| {
                PipelineError::ObjectEmission(format!(
                    "data-relocation target {:?} has no final nlist index",
                    reloc.symbol
                ))
            })?;
            writer.add_relocation(
                reloc.section_index,
                crate::macho::reloc::Relocation::unsigned_ptr(reloc.offset, final_index),
            )?;
        }
    }

    let mut finalize = |entries: Vec<(String, crate::macho::SymbolId)>,
                        namespace: &str|
     -> Result<HashMap<String, u32>, PipelineError> {
        let mut indices = HashMap::with_capacity(entries.len());
        for (name, symbol_id) in entries {
            let final_index = writer.final_symbol_index(symbol_id)?.ok_or_else(|| {
                PipelineError::ObjectEmission(
                    "symbol missing before Mach-O fixup resolution".to_string(),
                )
            })?;
            if let Some(previous) = indices.insert(name.clone(), final_index)
                && previous != final_index
            {
                return Err(PipelineError::ObjectEmission(format!(
                    "ambiguous Mach-O {namespace} symbol key `{name}` resolves to both nlist indices {previous} and {final_index}"
                )));
            }
        }
        Ok(indices)
    };

    Ok(MachOSymbolIndexMaps {
        ordinary_by_abi_name: finalize(ordinary_symbol_ids, "ABI")?,
        exact_function_by_raw_name: finalize(exact_function_symbol_ids, "exact function")?,
    })
}

/// True when the configured target triple targets a Linux-flavored ELF host.
///
/// trust-cg-codegen historically emitted Mach-O regardless of triple, which made
/// every cross-platform build implicitly host-only. Linux triples now route
/// through the ELF writer so `tcargo trust` artifacts for Linux are real ELF
/// `.o` files (verifiable with `file`/`readelf`).
pub(crate) fn target_triple_uses_elf(triple: &str) -> bool {
    triple.contains("-linux-")
        || triple.ends_with("-linux")
        || triple.contains("-freebsd")
        || triple.contains("-netbsd")
        || triple.contains("-openbsd")
        || triple.contains("-illumos")
        || triple.contains("-solaris")
}

fn target_triple_arch(triple: &str) -> &str {
    triple.split('-').next().unwrap_or("")
}

fn target_triple_is_aarch64(triple: &str) -> bool {
    matches!(target_triple_arch(triple), "aarch64" | "arm64")
}

pub(crate) fn target_triple_uses_macho(triple: &str) -> bool {
    triple.contains("-apple-") || triple.ends_with("-darwin")
}

fn target_triple_allows_aarch64_red_zone(triple: &str) -> bool {
    // Only Apple arm64 guarantees a below-SP red zone. Linux AAPCS64 has none,
    // so an ELF target must always allocate its frame before stores even when
    // the function is a tiny leaf. An empty or unrecognized triple never
    // reaches frame lowering (`Pipeline::resolved_aarch64_abi` refuses it) and
    // gets no red zone here either.
    target_triple_uses_macho(triple) && !target_triple_uses_elf(triple)
}

/// The C-runtime stack-guard ABI a stack-protected AArch64 function uses.
///
/// Both admitted ABIs read the process guard word through a GOT slot for the
/// C-level symbol `__stack_chk_guard` and call `__stack_chk_fail` on a
/// mismatch; they differ only in object format (Mach-O symbols carry the
/// leading underscore) and in which runtime defines the symbols.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StackProtectorTargetAbi {
    /// Apple AArch64 Mach-O: libSystem defines `___stack_chk_guard` and
    /// `___stack_chk_fail`; references use `ARM64_RELOC_GOT_LOAD_PAGE21` /
    /// `_PAGEOFF12` and `ARM64_RELOC_BRANCH26`.
    AppleMachO,
    /// AArch64 Linux ELF with a global-guard C runtime (glibc exports
    /// `__stack_chk_guard` from the dynamic loader, musl from libc; both
    /// export `__stack_chk_fail`). References use `R_AARCH64_ADR_GOT_PAGE` /
    /// `R_AARCH64_LD64_GOT_LO12_NC` and `R_AARCH64_CALL26`, so the guard never
    /// needs a copy relocation in a non-PIE executable.
    LinuxElfGlobalGuard,
}

/// Select the stack-guard ABI for `target_triple`, or refuse by name.
///
/// An empty triple names no object format and is refused, as in ABI
/// selection, rather than defaulting to Mach-O. Android is refused because
/// bionic keeps the guard in a thread-pointer slot rather than in
/// `__stack_chk_guard`; the BSD, illumos and Solaris ELF runtimes are
/// refused until their guard symbols are qualified. A refusal names the
/// target and its object format, and is raised as the frame-lowering refusal
/// it is ([`PipelineError::FrameLowering`]): the canary prologue/epilogue is a
/// frame-lowering sequence, and no object writer has run when this refuses
/// (trust-core AD-8 / E0.3 types every refusal by the layer that raises it).
pub fn stack_protector_target_abi(
    target_triple: &str,
) -> Result<StackProtectorTargetAbi, PipelineError> {
    let triple = target_triple.trim();
    let refuse = |format: &str, detail: &str| {
        let target = if triple.is_empty() { "unknown" } else { triple };
        PipelineError::FrameLowering(crate::lower::LowerError::FrameLowering(format!(
            "stack canary lowering supports only AArch64 Apple Mach-O and AArch64 Linux ELF with a global __stack_chk_guard; {detail} (target `{target}`, {format})"
        )))
    };
    if triple.is_empty() {
        return Err(refuse(
            "native object format",
            "an empty triple names no object format",
        ));
    }
    let format = if target_triple_uses_elf(triple) {
        "ELF"
    } else if target_triple_uses_macho(triple) {
        "Mach-O"
    } else {
        "native object format"
    };
    if !target_triple_is_aarch64(triple) {
        return Err(refuse(
            format,
            "this pipeline emits AArch64 code and the triple names another architecture",
        ));
    }
    if target_triple_uses_elf(triple) {
        let is_linux = triple.contains("-linux-") || triple.ends_with("-linux");
        if !is_linux {
            return Err(refuse(
                format,
                "this ELF operating system's guard symbol ABI is not qualified",
            ));
        }
        if triple.contains("android") {
            return Err(refuse(
                format,
                "Android bionic keeps the guard in a thread-pointer slot, which is not implemented",
            ));
        }
        return Ok(StackProtectorTargetAbi::LinuxElfGlobalGuard);
    }
    if target_triple_uses_macho(triple) {
        return Ok(StackProtectorTargetAbi::AppleMachO);
    }
    Err(refuse(
        format,
        "the triple names no supported object format",
    ))
}

fn reject_unsupported_aarch64_object_format(target_triple: &str) -> Result<(), PipelineError> {
    // An empty triple names no object format; it is refused with the same
    // typed diagnostic as ABI selection rather than defaulting to Mach-O.
    // Every explicit triple is an authority claim: this pipeline emits
    // little-endian AArch64 instructions, so it must never label those bytes
    // as x86, RISC-V, or big-endian AArch64.
    if target_triple.is_empty() {
        return Err(PipelineError::TargetAbiUnresolved(
            trust_cg_lower::abi::AArch64AbiTargetError::Empty,
        ));
    }

    if !target_triple_is_aarch64(target_triple) {
        return Err(PipelineError::TargetObjectUnsupported {
            target: target_triple.to_string(),
            format: "native object format".to_string(),
            reason: "the AArch64 pipeline emits only little-endian AArch64 machine code; non-AArch64 and aarch64_be triples require their architecture-specific pipeline (fail-closed)".to_string(),
        });
    }

    if target_triple_uses_elf(target_triple) || target_triple_uses_macho(target_triple) {
        return Ok(());
    }

    Err(PipelineError::TargetObjectUnsupported {
        target: target_triple.to_string(),
        format: "native object format".to_string(),
        reason: "AArch64 object emission is supported only for explicit ELF or Apple Mach-O target triples; unknown or unsupported AArch64 triples must fail closed before Mach-O emission".to_string(),
    })
}

/// What the AArch64 ELF text layout needs to know about one function beyond
/// its offset in the combined text stream.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct ElfFunctionFacts<'a> {
    /// Encoded body length, excluding any inter-function padding after it.
    pub(crate) code_len: u64,
    /// Required start alignment (log2 bytes) of the body.
    pub(crate) align_log2: u8,
    /// The function is a COMDAT definition
    /// ([`ModuleSymbolLinkage::comdat_functions`]): it gets its OWN
    /// `.text.<symbol>` section (or its explicit section) inside a
    /// `GRP_COMDAT` group signed by its (weak) symbol, so the linker keeps
    /// exactly one copy of the code.
    pub(crate) comdat: bool,
    /// The function's explicit output section (trust-ir v45
    /// `Function.section`, validated by [`ElfModuleSymbolPlan::new`]), or
    /// `None` for the default placement.
    pub(crate) section: Option<&'a str>,
}

/// The function-level object policy for one AArch64 ELF emission.
#[derive(Debug, Clone, Copy)]
pub(crate) struct ElfTextOptions<'a> {
    /// Every function without an explicit section in its own
    /// `.text.<symbol>` section (`-ffunction-sections`).
    pub(crate) function_sections: bool,
    /// 1:1 with the emitted functions, or EMPTY: every function in one
    /// `.text` (the legacy layout, and the only one allowed without facts).
    pub(crate) functions: &'a [ElfFunctionFacts<'a>],
}

/// One planned AArch64 ELF text section.
#[derive(Debug, Clone, PartialEq, Eq)]
struct ElfTextSection {
    name: String,
    code: Vec<u8>,
    /// `sh_addralign` in bytes.
    align: u64,
    /// The section is the only member of a COMDAT group whose signature is
    /// its function's symbol (bound once that symbol exists).
    comdat: bool,
}

/// Where one function landed in the planned text sections.
#[derive(Debug, Clone, PartialEq, Eq)]
struct ElfTextFunction {
    name: String,
    /// Index into [`ElfTextPlan::sections`].
    section: usize,
    /// Byte offset of the body within that section.
    offset: u64,
    /// `st_size`: up to the next function in the same section (padding
    /// included, the historical convention) or the body length when alone.
    size: u64,
    /// Offset of the body in the COMBINED text stream the fixups index.
    combined_offset: u64,
    /// Bytes of the combined stream that belong to this function (its body,
    /// or body plus trailing padding in the legacy single-section layout).
    combined_len: u64,
}

/// The AArch64 ELF text layout: which section each function lands in.
///
/// Every function is encoded independently and reaches other functions only
/// through named-symbol relocations, so moving a body between sections only
/// requires keeping its start alignment — which each section preserves.
/// The layout decides SECTIONS only; every symbol's binding comes from the
/// module's [`ElfModuleSymbolPlan`].
#[derive(Debug, Clone, PartialEq, Eq)]
struct ElfTextPlan {
    sections: Vec<ElfTextSection>,
    functions: Vec<ElfTextFunction>,
    /// The historical single-`.text` layout: section 0 IS the combined
    /// stream, so every combined offset maps to itself.
    legacy: bool,
}

/// The planned text section of one function.
#[derive(Debug, Clone, PartialEq, Eq)]
enum ElfTextPlacement<'a> {
    /// The shared default `.text`.
    Packed,
    /// A named section shared by every non-COMDAT function naming it.
    Shared(&'a str),
    /// A section of its own, grouped as a COMDAT when `comdat`.
    Own { name: String, comdat: bool },
}

/// Where `facts` places function `name` under `options`.
///
/// An explicit `.text` is the shared default section, which
/// `-ffunction-sections` does not split; any other explicit name is shared by
/// the non-COMDAT functions naming it. A COMDAT function is alone in its own
/// grouped section: its explicit name, else `.text.<symbol>`. Without an
/// explicit name, `-ffunction-sections` gives a function `.text.<symbol>`.
fn elf_text_placement<'a>(
    name: &str,
    fact: &ElfFunctionFacts<'a>,
    function_sections: bool,
) -> Result<ElfTextPlacement<'a>, PipelineError> {
    Ok(match (fact.section, fact.comdat) {
        (Some(".text"), true) => {
            return Err(PipelineError::ObjectEmission(format!(
                "ELF text layout: COMDAT function `{name}` names the shared `.text`, but a \
                 COMDAT function needs a grouped section of its own (fail-closed)"
            )));
        }
        (Some(".text"), false) => ElfTextPlacement::Packed,
        (Some(section), false) => ElfTextPlacement::Shared(section),
        (Some(section), true) => ElfTextPlacement::Own {
            name: section.to_string(),
            comdat: true,
        },
        (None, comdat) if comdat || function_sections => ElfTextPlacement::Own {
            name: format!(".text.{name}"),
            comdat,
        },
        (None, _) => ElfTextPlacement::Packed,
    })
}

/// Plan the AArch64 ELF text sections for a combined text stream.
///
/// Without function sections, a COMDAT function or an explicit section other
/// than `.text` this is exactly the historical layout: one `.text` holding
/// `combined_code` byte for byte. Otherwise each function lands where
/// [`elf_text_placement`] puts it: bodies in a section of their own are
/// copied out with their own alignment, and the functions sharing `.text` or
/// an explicit section are re-packed into it in function order with NOP
/// padding up to each body's alignment.
fn plan_elf_text(
    machine: crate::elf::ElfMachine,
    combined_code: &[u8],
    func_offsets: &[(String, u64)],
    text_align_log2: u8,
    options: ElfTextOptions<'_>,
) -> Result<ElfTextPlan, PipelineError> {
    let facts = options.functions;
    if !facts.is_empty() && facts.len() != func_offsets.len() {
        return Err(PipelineError::ObjectEmission(format!(
            "ELF text layout received facts for {} of {} functions (fail-closed)",
            facts.len(),
            func_offsets.len()
        )));
    }
    let placements = facts
        .iter()
        .zip(func_offsets)
        .map(|(fact, (name, _))| elf_text_placement(name, fact, options.function_sections))
        .collect::<Result<Vec<_>, _>>()?;
    let total = combined_code.len() as u64;
    let legacy_end = |index: usize| func_offsets.get(index + 1).map_or(total, |(_, next)| *next);
    let split = (facts.is_empty() && options.function_sections)
        || placements
            .iter()
            .any(|placement| *placement != ElfTextPlacement::Packed);
    if !split {
        let functions = func_offsets
            .iter()
            .enumerate()
            .map(|(index, (name, offset))| {
                let end = legacy_end(index);
                ElfTextFunction {
                    name: name.clone(),
                    section: 0,
                    offset: *offset,
                    size: end.saturating_sub(*offset),
                    combined_offset: *offset,
                    combined_len: end.saturating_sub(*offset),
                }
            })
            .collect();
        return Ok(ElfTextPlan {
            sections: vec![ElfTextSection {
                name: ".text".to_string(),
                code: combined_code.to_vec(),
                align: elf_text_align_bytes(machine, text_align_log2),
                comdat: false,
            }],
            functions,
            legacy: true,
        });
    }
    if machine != crate::elf::ElfMachine::AArch64 {
        // Re-packing pads with AArch64 NOP words.
        return Err(PipelineError::ObjectEmission(format!(
            "ELF function sections, explicit function sections and COMDAT text are laid out \
             for AArch64 only, not {machine:?} (fail-closed)"
        )));
    }
    if facts.is_empty() {
        return Err(PipelineError::ObjectEmission(
            "ELF function sections need each function's encoded length and alignment; \
             this emission path supplied none (fail-closed)"
                .to_string(),
        ));
    }

    let body = |index: usize| -> Result<&[u8], PipelineError> {
        let (name, offset) = &func_offsets[index];
        let end = offset
            .checked_add(facts[index].code_len)
            .filter(|end| *end <= legacy_end(index))
            .ok_or_else(|| {
                PipelineError::ObjectEmission(format!(
                    "ELF text layout: `{name}` body [{offset}, +{}) overruns its slot in the \
                     combined text (fail-closed)",
                    facts[index].code_len
                ))
            })?;
        Ok(&combined_code[*offset as usize..end as usize])
    };
    let body_align = |index: usize| elf_text_align_bytes(machine, facts[index].align_log2);

    let mut sections = Vec::new();
    let mut functions: Vec<Option<ElfTextFunction>> = vec![None; func_offsets.len()];

    // Pack `members` (function indices, ascending) into one new section
    // `name`, each body at its own alignment behind NOP padding; each
    // symbol's size runs to the next member (padding included).
    let pack = |name: &str,
                members: &[usize],
                sections: &mut Vec<ElfTextSection>,
                functions: &mut [Option<ElfTextFunction>]|
     -> Result<(), PipelineError> {
        let section = sections.len();
        let mut code = Vec::new();
        let mut align = elf_text_align_bytes(machine, 2);
        let mut starts = Vec::with_capacity(members.len());
        for &index in members {
            let body_align_bytes = body_align(index);
            align = align.max(body_align_bytes);
            while !(code.len() as u64).is_multiple_of(body_align_bytes) {
                code.extend_from_slice(&AARCH64_NOP_WORD);
            }
            starts.push(code.len() as u64);
            code.extend_from_slice(body(index)?);
        }
        let end = code.len() as u64;
        for (slot, &index) in members.iter().enumerate() {
            let next = starts.get(slot + 1).copied().unwrap_or(end);
            functions[index] = Some(ElfTextFunction {
                name: func_offsets[index].0.clone(),
                section,
                offset: starts[slot],
                size: next - starts[slot],
                combined_offset: func_offsets[index].1,
                combined_len: facts[index].code_len,
            });
        }
        sections.push(ElfTextSection {
            name: name.to_string(),
            code,
            align,
            comdat: false,
        });
        Ok(())
    };

    // Shared `.text` first for the functions that stay packed.
    let packed: Vec<usize> = (0..func_offsets.len())
        .filter(|&index| placements[index] == ElfTextPlacement::Packed)
        .collect();
    if !packed.is_empty() {
        pack(".text", &packed, &mut sections, &mut functions)?;
    }
    // Then every other section in function order; a shared explicit section
    // is created at its first member and holds all of its members.
    let mut shared_placed = BTreeSet::new();
    for index in 0..func_offsets.len() {
        match &placements[index] {
            ElfTextPlacement::Packed => {}
            ElfTextPlacement::Shared(name) => {
                if shared_placed.insert(*name) {
                    let members: Vec<usize> = (index..func_offsets.len())
                        .filter(|&member| placements[member] == ElfTextPlacement::Shared(name))
                        .collect();
                    pack(name, &members, &mut sections, &mut functions)?;
                }
            }
            ElfTextPlacement::Own { name, comdat } => {
                let code = body(index)?.to_vec();
                functions[index] = Some(ElfTextFunction {
                    name: func_offsets[index].0.clone(),
                    section: sections.len(),
                    offset: 0,
                    size: code.len() as u64,
                    combined_offset: func_offsets[index].1,
                    combined_len: facts[index].code_len,
                });
                sections.push(ElfTextSection {
                    name: name.clone(),
                    code,
                    align: body_align(index),
                    comdat: *comdat,
                });
            }
        }
    }
    // The placements partition the index range, so every slot is filled; a
    // gap would be a planner bug and fails closed.
    let functions = functions
        .into_iter()
        .collect::<Option<Vec<_>>>()
        .ok_or_else(|| {
            PipelineError::ObjectEmission(
                "ELF text layout left a function unplaced (fail-closed)".to_string(),
            )
        })?;
    Ok(ElfTextPlan {
        sections,
        functions,
        legacy: false,
    })
}

impl ElfTextPlan {
    /// The (plan section, section-relative offset) of a combined-stream
    /// fixup offset: the function whose body contains it, shifted by where
    /// that body landed. A fixup outside every body fails closed.
    fn place(&self, combined_offset: u64) -> Result<(usize, u64), PipelineError> {
        if self.legacy {
            if combined_offset >= self.sections[0].code.len() as u64 {
                return Err(PipelineError::ObjectEmission(format!(
                    "ELF text relocation at offset {combined_offset:#x} lies outside the \
                     {}-byte .text (fail-closed)",
                    self.sections[0].code.len()
                )));
            }
            return Ok((0, combined_offset));
        }
        let index = self
            .functions
            .partition_point(|function| function.combined_offset <= combined_offset);
        let function = index
            .checked_sub(1)
            .and_then(|index| self.functions.get(index))
            .filter(|function| combined_offset - function.combined_offset < function.combined_len)
            .ok_or_else(|| {
                PipelineError::ObjectEmission(format!(
                    "ELF text relocation at combined offset {combined_offset:#x} lies outside \
                     every function body (fail-closed)"
                ))
            })?;
        Ok((
            function.section,
            function.offset + (combined_offset - function.combined_offset),
        ))
    }
}

/// The writer-side placement of an [`ElfTextPlan`]: each plan section's
/// 1-based section header index and, for a COMDAT section, the group whose
/// signature [`add_elf_function_symbols`] binds to the function's symbol.
struct ElfTextSections {
    shndx: Vec<u16>,
    groups: Vec<Option<crate::elf::ElfSectionGroupId>>,
}

/// Add the planned text sections (each COMDAT one preceded by its group).
fn add_elf_text_sections(
    writer: &mut crate::elf::ElfWriter,
    plan: &ElfTextPlan,
) -> Result<ElfTextSections, PipelineError> {
    use crate::elf::constants::{SHF_ALLOC, SHF_EXECINSTR, SHT_PROGBITS};
    let mut placed = ElfTextSections {
        shndx: Vec::with_capacity(plan.sections.len()),
        groups: Vec::with_capacity(plan.sections.len()),
    };
    for section in &plan.sections {
        if section.comdat {
            let group = writer.add_comdat_group();
            placed.shndx.push(writer.add_group_member_section(
                group,
                &section.name,
                &section.code,
                SHT_PROGBITS,
                SHF_ALLOC | SHF_EXECINSTR,
                section.align,
                0,
            )?);
            placed.groups.push(Some(group));
        } else {
            placed.shndx.push(writer.add_section(
                &section.name,
                &section.code,
                SHT_PROGBITS,
                SHF_ALLOC | SHF_EXECINSTR,
                section.align,
            )?);
            placed.groups.push(None);
        }
    }
    Ok(placed)
}

/// Emit an ELF `.o` with the planned text sections and one `STT_FUNC` symbol
/// per function at its planned section and offset, bound as `plan` directs.
fn emit_elf_with_function_symbols(
    machine: crate::elf::ElfMachine,
    text: &ElfTextPlan,
    globals: &[ObjectGlobal],
    plan: &ElfModuleSymbolPlan<'_>,
    debug: Option<&crate::dwarf_info::DwarfSectionImage>,
) -> Result<Vec<u8>, PipelineError> {
    use crate::elf::ElfWriter;

    let mut writer = ElfWriter::new(machine);
    let text_sections = add_elf_text_sections(&mut writer, text)?;
    let mut known_names: BTreeSet<String> = add_elf_global_object_symbols(&mut writer, globals)?
        .into_iter()
        .collect();
    // No text relocation names a symbol in this object; the checked API still
    // validates every function symbol's range and binding. Only the DWARF
    // anchors below read final indices.
    known_names.extend(
        add_elf_function_symbols(&mut writer, text, &text_sections, plan)?
            .into_iter()
            .map(|(name, _)| name),
    );
    // Nothing references a symbol here, but the weak and visible
    // declarations are still written, as llc writes them.
    let declared: Vec<&str> = plan.unreferenced_declarations(&known_names).collect();
    for name in declared {
        writer.add_checked_symbol(elf_undefined_symbol(
            name,
            crate::elf::constants::STT_NOTYPE,
            plan,
        ))?;
    }
    let debug = attach_elf_debug_sections(&mut writer, debug, text, &text_sections, None)?;
    relocate_elf_debug_sections(&mut writer, debug.as_ref())?;
    finish_elf_object(writer)
}

/// DWARF sections placed in an AArch64 ELF object, with the anchor symbols
/// their relocations name.
struct ElfDebugAttachment {
    sections: crate::elf::ElfDwarfSections,
    anchors: crate::elf::ElfDwarfAnchors,
}

/// Refuse `-g` for an AArch64 ELF text layout that splits functions across
/// sections.
///
/// The DWARF image describes every function at its offset in the COMBINED
/// text stream against one text base: a single compile-unit `low_pc`, code
/// addresses relocated against one `.text` anchor and DWARF4 `.debug_loc`
/// ranges taken from that base. That is exact only for the legacy
/// single-`.text` layout. Function sections (`-ffunction-sections`), COMDAT
/// function text and explicit function sections (trust-ir v45
/// `Function.section`) place bodies in sections other than `.text`, which
/// would need per-section address relocations, one line sequence per section
/// and `DW_AT_ranges`; until those exist the combination fails closed rather
/// than describe code against the wrong section.
fn reject_elf_debug_with_split_text(
    target_triple: &str,
    text: &ElfTextPlan,
    debug: Option<&crate::dwarf_info::DwarfSectionImage>,
) -> Result<(), PipelineError> {
    if debug.is_some() && !text.legacy {
        return Err(PipelineError::TargetObjectUnsupported {
            target: target_triple.to_string(),
            format: "ELF".to_string(),
            reason: "DWARF debug sections (-g) describe every function against one `.text` \
                     section; function sections, COMDAT function text and explicit function \
                     sections place bodies in other sections, which the DWARF emitter does \
                     not yet describe (fail-closed)"
                .to_string(),
        });
    }
    Ok(())
}

/// Place `debug` after every section the emitter has already added and add
/// its local `STT_SECTION` anchors through the checked symbol API. Call it
/// before the emitter reads any final symbol index; `text_anchor` reuses the
/// emitter's own `.text` section symbol when it has one. Only the legacy
/// single-`.text` layout carries DWARF (the planners run
/// [`reject_elf_debug_with_split_text`] first).
fn attach_elf_debug_sections(
    writer: &mut crate::elf::ElfWriter,
    debug: Option<&crate::dwarf_info::DwarfSectionImage>,
    text: &ElfTextPlan,
    text_sections: &ElfTextSections,
    text_anchor: Option<crate::elf::ElfSymbolId>,
) -> Result<Option<ElfDebugAttachment>, PipelineError> {
    let Some(image) = debug else {
        return Ok(None);
    };
    let text_shndx = match (text.legacy, text_sections.shndx.as_slice()) {
        (true, [text_shndx]) => *text_shndx,
        _ => {
            return Err(PipelineError::DebugInfoInput(format!(
                "DWARF sections need the single-`.text` ELF layout; the text plan has {} \
                 section(s) (fail-closed)",
                text_sections.shndx.len()
            )));
        }
    };
    let sections = crate::elf::ElfDwarfSections::add_sections(writer, image, text_shndx)?;
    let anchors = sections.add_anchor_symbols(writer, text_anchor)?;
    Ok(Some(ElfDebugAttachment { sections, anchors }))
}

/// Add the `R_AARCH64_ABS64` / `R_AARCH64_ABS32` records of an attached DWARF
/// image once the symbol table is complete.
fn relocate_elf_debug_sections(
    writer: &mut crate::elf::ElfWriter,
    attachment: Option<&ElfDebugAttachment>,
) -> Result<(), PipelineError> {
    let Some(attachment) = attachment else {
        return Ok(());
    };
    let indices = attachment.anchors.final_indices(writer)?;
    attachment.sections.add_relocations(writer, &indices)?;
    Ok(())
}

/// Finish and serialize an ELF object emitted by this pipeline.
///
/// Every ELF emitter here ends through this funnel, so every object carries
/// the empty `.note.GNU-stack` marker (GNU convention: `SHT_PROGBITS`, flags
/// 0), added after all other user sections. With it the static linker emits
/// a non-executable `PT_GNU_STACK` without relying on `-z noexecstack`.
/// trust-cg emits no BTI landing pads and no PAC instructions, so no
/// `.note.gnu.property` / `GNU_PROPERTY_AARCH64_FEATURE_1_AND` note is
/// emitted: claiming either feature would be false.
///
/// Serialization runs the shared ELF reparse gate, which independently
/// re-parses the emitted bytes against intent and (at the default Enforce)
/// fails the write closed on any mismatch — the per-object binding half of
/// the relocation inventory's Certified composition (mirrors the x86-64 ELF
/// arm). That includes every COMDAT group's members, `SHF_GROUP` flags and
/// signature symbol.
fn finish_elf_object(mut writer: crate::elf::ElfWriter) -> Result<Vec<u8>, PipelineError> {
    writer.add_note_gnu_stack();
    writer
        .write_checked()
        .map_err(|e| PipelineError::ElfReparse(e.to_string()))
}

/// The `STT_FUNC` symbol for one function bound as `binding`: `STB_LOCAL`,
/// `STB_GLOBAL` or `STB_WEAK`, with its `STV_*` visibility.
fn elf_function_symbol(
    name: &str,
    section: u16,
    offset: u64,
    size: u64,
    binding: FunctionSymbolBinding,
) -> crate::elf::ElfSymbol {
    crate::elf::ElfSymbol {
        name: name.to_string(),
        section,
        value: offset,
        size,
        is_global: binding.linkage() != FunctionSymbolLinkage::Local,
        sym_type: crate::elf::constants::STT_FUNC,
        is_weak: binding.linkage() == FunctionSymbolLinkage::Weak,
        visibility: elf_symbol_visibility(binding.visibility()),
    }
}

/// Add one `STT_FUNC` symbol per function through the checked symbol API,
/// at its planned section and offset and bound as `plan` directs, bind each
/// COMDAT text group's signature to its function's symbol, and return each
/// handle in emission order.
///
/// In the legacy layout `st_size` runs to the next function's start (or the
/// end of `.text`), so it includes inter-function alignment padding.
fn add_elf_function_symbols(
    writer: &mut crate::elf::ElfWriter,
    text: &ElfTextPlan,
    sections: &ElfTextSections,
    plan: &ElfModuleSymbolPlan<'_>,
) -> Result<Vec<(String, crate::elf::ElfSymbolId)>, PipelineError> {
    let count = text.functions.len();
    let mut symbols = Vec::with_capacity(count);
    for (index, function) in text.functions.iter().enumerate() {
        let binding =
            function_symbol_binding_at(plan.function_bindings, index, count, &function.name)?;
        let id = writer.add_checked_symbol(elf_function_symbol(
            &function.name,
            sections.shndx[function.section],
            function.offset,
            function.size,
            binding,
        ))?;
        if let Some(group) = sections.groups[function.section] {
            writer.bind_comdat_group_signature(group, id)?;
        }
        symbols.push((function.name.clone(), id));
    }
    Ok(symbols)
}

/// The symbol for one placed data global. An Internal/Private row is
/// `STB_LOCAL`/`STV_DEFAULT`; an external row carries its weak flag and
/// visibility.
fn elf_global_row_symbol(row: &ElfGlobalSymbolRow) -> crate::elf::ElfSymbol {
    use crate::elf::constants::{STT_OBJECT, STT_TLS, STV_DEFAULT};
    crate::elf::ElfSymbol {
        name: row.name.clone(),
        section: row.section,
        value: row.offset,
        size: row.size,
        is_global: row.is_external,
        sym_type: if row.is_tls { STT_TLS } else { STT_OBJECT },
        is_weak: row.is_external && row.is_weak,
        visibility: if row.is_external {
            row.visibility
        } else {
            STV_DEFAULT
        },
    }
}

/// Whether `fixup` reaches its thread-local through a TLS descriptor: the
/// general- and local-dynamic models, which the ELF emitters spell as the
/// four `R_AARCH64_TLSDESC_*` relocations (a shared object's TLS access).
fn fixup_uses_tls_descriptor(fixup: &crate::macho::fixup::Fixup) -> bool {
    matches!(
        fixup.tls_model,
        Some(trust_cg_ir::TlsModel::GeneralDynamic | trust_cg_ir::TlsModel::LocalDynamic)
    )
}

/// The name of the object-local anchor
/// [`add_elf_hidden_tls_descriptor_anchors`] gives thread-local `name`.
fn elf_hidden_tls_anchor_name(name: &str) -> String {
    format!(".Ltls.{name}")
}

/// Object-local `STT_TLS` anchors for the STRONG HIDDEN thread-local
/// definitions that a TLS-descriptor fixup names, by definition name.
///
/// Each anchor is an `STB_LOCAL` symbol at its definition's own section,
/// offset and size, like GCC's section anchor (`.LANCHOR<n>`, which GCC 13.3
/// uses for hidden thread-locals at `-O1` and above). The descriptor
/// relocations name the anchor instead of the global symbol, so a shared
/// object's `R_AARCH64_TLSDESC` names symbol 0 with the variable's offset as
/// its addend with every linker. Against the global hidden symbol, GNU ld and
/// LLD do the same, but gold keeps the symbol in `.dynsym` as `TLS LOCAL
/// HIDDEN` and names it in the dynamic relocation (not exported, and resolved
/// to the library's own block, as with GCC at `-O0`).
///
/// Only a strong definition is anchored. A weak one (plain weak or a COMDAT)
/// may be replaced at static link by another object's definition, which only
/// a reference by the symbol follows. A protected definition is exported
/// anyway and keeps its symbol, as GCC's does; a default one is preemptible.
/// Executable models (local-exec, initial-exec) never name a dynamic symbol
/// for a hidden definition and keep the symbol.
fn add_elf_hidden_tls_descriptor_anchors(
    writer: &mut crate::elf::ElfWriter,
    rows: &[ElfGlobalSymbolRow],
    fixups: &crate::macho::fixup::FixupList,
) -> Result<Vec<(String, crate::elf::ElfSymbolId)>, PipelineError> {
    use crate::elf::constants::{STT_TLS, STV_DEFAULT, STV_HIDDEN};
    use crate::macho::FixupTarget;
    let descriptor_targets: BTreeSet<&str> = fixups
        .iter()
        .filter(|fixup| fixup_uses_tls_descriptor(fixup))
        .filter_map(|fixup| match &fixup.target {
            FixupTarget::NamedSymbol(name) => Some(name.as_str()),
            _ => None,
        })
        .collect();
    let mut anchors = Vec::new();
    for row in rows.iter().filter(|row| {
        row.is_tls
            && row.is_external
            && !row.is_weak
            && row.visibility == STV_HIDDEN
            && descriptor_targets.contains(row.name.as_str())
    }) {
        let id = writer.add_checked_symbol(crate::elf::ElfSymbol {
            name: elf_hidden_tls_anchor_name(&row.name),
            section: row.section,
            value: row.offset,
            size: row.size,
            is_global: false,
            sym_type: STT_TLS,
            is_weak: false,
            visibility: STV_DEFAULT,
        })?;
        anchors.push((row.name.clone(), id));
    }
    Ok(anchors)
}

/// The `.symtab` index a text relocation for `fixup` against `name` names:
/// the thread-local's object-local anchor for a TLS-descriptor fixup that has
/// one ([`add_elf_hidden_tls_descriptor_anchors`]), else `name`'s symbol.
fn elf_fixup_symbol_index(
    fixup: &crate::macho::fixup::Fixup,
    name: &str,
    symbol_indices: &HashMap<String, u32>,
    tls_anchor_indices: &HashMap<String, u32>,
) -> u32 {
    fixup_uses_tls_descriptor(fixup)
        .then(|| tls_anchor_indices.get(name).copied())
        .flatten()
        .or_else(|| symbol_indices.get(name).copied())
        .expect("named fixup target should have an ELF symbol")
}

/// The hidden thread-local anchors of one AArch64 ELF module object
/// ([`add_elf_hidden_tls_descriptor_anchors`]), by definition name.
/// [`add_aarch64_elf_reference_symbols`] returns one and
/// [`add_aarch64_elf_text_relocations`] takes one, so an emitter that relocates
/// its text through that pass has to pass it anchors, and both relocating
/// module emitters get theirs from the same reference pass. The type does not
/// stop other code in this module from building one; the Pipeline-route and
/// `Compiler::compile` anchor rows check both emitters' objects.
struct ElfTlsDescriptorAnchors(Vec<(String, crate::elf::ElfSymbolId)>);

/// The symbols both relocating AArch64 ELF module emitters
/// ([`emit_aarch64_elf_with_supported_fixups`] and
/// [`emit_aarch64_elf_module_with_unwind`]) add to `writer` and
/// `symbol_ids` after their defined symbols and thread-local imports: an
/// undefined `STT_NOTYPE` symbol ([`elf_undefined_symbol`]) for every name
/// that a text fixup, a data pointer slot or the CIE `personality` reaches,
/// and for every weak or visible declaration the plan writes unreferenced
/// ([`ModuleSymbolLinkage::with_declared_undefined_symbols`]), that
/// `known_names` does not define, in name order, then the hidden
/// thread-local anchors. Every fixup's relocation kind is checked first; an
/// exact module call target must be one of `func_offsets` (`emitter` names
/// the object in that refusal) and any other non-named target is refused.
#[allow(clippy::too_many_arguments)]
fn add_aarch64_elf_reference_symbols(
    writer: &mut crate::elf::ElfWriter,
    target_triple: &str,
    combined_code: &[u8],
    func_offsets: &[(String, u64)],
    globals: &[ObjectGlobal],
    global_symbol_rows: &[ElfGlobalSymbolRow],
    fixups: &crate::macho::fixup::FixupList,
    plan: &ElfModuleSymbolPlan<'_>,
    known_names: &BTreeSet<String>,
    personality: Option<&str>,
    emitter: &str,
    symbol_ids: &mut Vec<(String, crate::elf::ElfSymbolId)>,
) -> Result<ElfTlsDescriptorAnchors, PipelineError> {
    use crate::macho::FixupTarget;

    let mut undefined_names = BTreeSet::new();
    let defined_functions: BTreeSet<&str> =
        func_offsets.iter().map(|(name, _)| name.as_str()).collect();
    for fixup in fixups.iter() {
        aarch64_elf_reloc_kind(target_triple, combined_code, fixup)?;
        match &fixup.target {
            FixupTarget::NamedSymbol(name) => {
                if !known_names.contains(name) {
                    undefined_names.insert(name.clone());
                }
            }
            FixupTarget::ExactNamedSymbol(name) => {
                if !defined_functions.contains(name.as_str()) {
                    return Err(PipelineError::ObjectEmission(format!(
                        "exact module call targets missing {emitter} function `{name}`"
                    )));
                }
            }
            other => {
                return Err(PipelineError::TargetObjectUnsupported {
                    target: target_triple.to_string(),
                    format: "ELF".to_string(),
                    reason: format!(
                        "AArch64 ELF relocation requires a named symbol target; got {other:?}"
                    ),
                });
            }
        }
    }
    // The CIE personality reference (defined here or extern).
    if let Some(personality) = personality
        && !known_names.contains(personality)
    {
        undefined_names.insert(personality.to_string());
    }
    // Symbol-address slots inside global data (vtables / fn-pointer tables)
    // may target functions or globals defined elsewhere.
    for global in globals {
        for sref in &global.symbol_refs {
            if !known_names.contains(&sref.symbol) {
                undefined_names.insert(sref.symbol.clone());
            }
        }
    }
    // Weak and visible declarations are written whether or not anything
    // above references them, as llc writes them.
    undefined_names.extend(
        plan.unreferenced_declarations(known_names)
            .map(str::to_string),
    );
    for name in undefined_names {
        let symbol = elf_undefined_symbol(&name, crate::elf::constants::STT_NOTYPE, plan);
        let id = writer.add_checked_symbol(symbol)?;
        symbol_ids.push((name, id));
    }
    add_elf_hidden_tls_descriptor_anchors(writer, global_symbol_rows, fixups)
        .map(ElfTlsDescriptorAnchors)
}

/// The `.text` relocations of both relocating AArch64 ELF module emitters,
/// added once the symbol table is complete: one per fixup, in the text
/// section holding its function's body, naming its target's symbol in
/// `symbol_indices`, or the target's object-local anchor for a
/// TLS-descriptor fixup that has one ([`elf_fixup_symbol_index`]).
#[allow(clippy::too_many_arguments)]
fn add_aarch64_elf_text_relocations(
    writer: &mut crate::elf::ElfWriter,
    target_triple: &str,
    combined_code: &[u8],
    fixups: &crate::macho::fixup::FixupList,
    text: &ElfTextPlan,
    text_sections: &ElfTextSections,
    symbol_indices: &HashMap<String, u32>,
    tls_anchors: &ElfTlsDescriptorAnchors,
) -> Result<(), PipelineError> {
    use crate::elf::Elf64Rela;
    use crate::macho::FixupTarget;

    let tls_anchor_indices = final_elf_symbol_indices(writer, &tls_anchors.0)?;
    for fixup in fixups.iter() {
        let name = match &fixup.target {
            FixupTarget::NamedSymbol(name) | FixupTarget::ExactNamedSymbol(name) => name,
            other => {
                return Err(PipelineError::TargetObjectUnsupported {
                    target: target_triple.to_string(),
                    format: "ELF".to_string(),
                    reason: format!(
                        "AArch64 ELF relocation requires a named symbol target; got {other:?}"
                    ),
                });
            }
        };
        let symbol_index = elf_fixup_symbol_index(fixup, name, symbol_indices, &tls_anchor_indices);
        let reloc_kind = aarch64_elf_reloc_kind(target_triple, combined_code, fixup)?;
        // A fixup lands in the text section holding its function's body.
        let (section, offset) = text.place(u64::from(fixup.offset))?;
        writer.add_relocation(
            usize::from(text_sections.shndx[section]) - 1,
            Elf64Rela::aarch64(offset, symbol_index, reloc_kind, fixup.addend),
        );
    }
    Ok(())
}

/// An undefined reference: `STB_WEAK` when `plan` names it weak (resolving to
/// null when nothing defines it), else `STB_GLOBAL`, with the visibility
/// `plan` states for it (`STV_DEFAULT` otherwise).
fn elf_undefined_symbol(
    name: &str,
    sym_type: u8,
    plan: &ElfModuleSymbolPlan<'_>,
) -> crate::elf::ElfSymbol {
    let (binding, visibility) = plan.undefined_reference(name);
    crate::elf::ElfSymbol {
        name: name.to_string(),
        section: 0,
        value: 0,
        size: 0,
        is_global: true,
        sym_type,
        is_weak: matches!(
            binding,
            trust_cg_lower::SymbolBinding::Undefined { weak: true }
        ),
        visibility: elf_symbol_visibility(visibility),
    }
}

/// Resolve every named handle to its final `.symtab` index, after the whole
/// table exists. Later entries for the same name overwrite earlier ones,
/// exactly as the name map always has.
fn final_elf_symbol_indices(
    writer: &mut crate::elf::ElfWriter,
    symbols: &[(String, crate::elf::ElfSymbolId)],
) -> Result<HashMap<String, u32>, PipelineError> {
    let mut indices = HashMap::with_capacity(symbols.len());
    for (name, id) in symbols {
        indices.insert(name.clone(), writer.final_symbol_index(*id)?);
    }
    Ok(indices)
}

fn aarch64_elf_branch_reloc_kind(
    target_triple: &str,
    combined_code: &[u8],
    offset: u32,
) -> Result<crate::elf::AArch64RelocType, PipelineError> {
    let offset = offset as usize;
    let Some(bytes) = combined_code.get(offset..offset + 4) else {
        return Err(PipelineError::TargetObjectUnsupported {
            target: target_triple.to_string(),
            format: "ELF".to_string(),
            reason: format!("AArch64 branch fixup offset {offset:#x} is outside .text"),
        });
    };
    let word = u32::from_le_bytes([bytes[0], bytes[1], bytes[2], bytes[3]]);
    match word & 0xfc00_0000 {
        0x9400_0000 => Ok(crate::elf::AArch64RelocType::Call26),
        0x1400_0000 => Ok(crate::elf::AArch64RelocType::Jump26),
        _ => Err(PipelineError::TargetObjectUnsupported {
            target: target_triple.to_string(),
            format: "ELF".to_string(),
            reason: format!(
                "AArch64 Branch26 fixup at {offset:#x} does not point at a B/BL placeholder"
            ),
        }),
    }
}

fn aarch64_elf_reloc_kind(
    target_triple: &str,
    combined_code: &[u8],
    fixup: &crate::macho::fixup::Fixup,
) -> Result<crate::elf::AArch64RelocType, PipelineError> {
    use crate::macho::AArch64RelocKind;

    // The ELF local-exec (TLSLE) and initial-exec (TLSIE) TLS fixups are the
    // ONLY TLS-provenance fixups this emitter accepts, and each is only valid
    // with exactly its own model (the ISel sequence it was emitted from:
    // `MRS; ADD hi12; ADD lo12_nc` for LocalExec, `ADRP :gottprel:;
    // LDR #:gottprel_lo12:; MRS; ADD` for InitialExec). Everything else with
    // a TLS model — in particular the Darwin TLV descriptor fixups — stays
    // fail-closed: Darwin TLV descriptors cannot be mapped to ELF TLS
    // relocations, and TLS-provenance fixups must never be emitted as
    // non-TLS relocations.
    match (fixup.kind, fixup.tls_model) {
        (AArch64RelocKind::ElfTlsleAddTprelHi12, Some(trust_cg_ir::TlsModel::LocalExec)) => {
            return Ok(crate::elf::AArch64RelocType::TlsleAddTprelHi12);
        }
        (AArch64RelocKind::ElfTlsleAddTprelLo12Nc, Some(trust_cg_ir::TlsModel::LocalExec)) => {
            return Ok(crate::elf::AArch64RelocType::TlsleAddTprelLo12Nc);
        }
        (AArch64RelocKind::ElfTlsieAdrGottprelPage21, Some(trust_cg_ir::TlsModel::InitialExec)) => {
            return Ok(crate::elf::AArch64RelocType::TlsieAdrGottprelPage21);
        }
        (
            AArch64RelocKind::ElfTlsieLd64GottprelLo12Nc,
            Some(trust_cg_ir::TlsModel::InitialExec),
        ) => return Ok(crate::elf::AArch64RelocType::TlsieLd64GottprelLo12Nc),
        (
            AArch64RelocKind::ElfTlsleAddTprelHi12 | AArch64RelocKind::ElfTlsleAddTprelLo12Nc,
            model,
        ) => {
            return Err(PipelineError::TargetObjectUnsupported {
                target: target_triple.to_string(),
                format: "ELF".to_string(),
                reason: format!(
                    "AArch64 ELF TLS local-exec fixup {:?} carries model {model:?}; it must carry Some(LocalExec) (fail-closed: TLS relocation model and fixup kind must agree)",
                    fixup.kind
                ),
            });
        }
        (AArch64RelocKind::ElfTlsdescAdrPage21, Some(trust_cg_ir::TlsModel::GeneralDynamic)) => {
            return Ok(crate::elf::AArch64RelocType::TlsdescAdrPage21);
        }
        (AArch64RelocKind::ElfTlsdescLd64Lo12, Some(trust_cg_ir::TlsModel::GeneralDynamic)) => {
            return Ok(crate::elf::AArch64RelocType::TlsdescLd64Lo12);
        }
        (AArch64RelocKind::ElfTlsdescAddLo12, Some(trust_cg_ir::TlsModel::GeneralDynamic)) => {
            return Ok(crate::elf::AArch64RelocType::TlsdescAddLo12);
        }
        (AArch64RelocKind::ElfTlsdescCall, Some(trust_cg_ir::TlsModel::GeneralDynamic)) => {
            return Ok(crate::elf::AArch64RelocType::TlsdescCall);
        }
        (
            AArch64RelocKind::ElfTlsdescAdrPage21
            | AArch64RelocKind::ElfTlsdescLd64Lo12
            | AArch64RelocKind::ElfTlsdescAddLo12
            | AArch64RelocKind::ElfTlsdescCall,
            model,
        ) => {
            return Err(PipelineError::TargetObjectUnsupported {
                target: target_triple.to_string(),
                format: "ELF".to_string(),
                reason: format!(
                    "AArch64 ELF TLS descriptor fixup {:?} carries model {model:?}; it must carry Some(GeneralDynamic) (fail-closed: TLS relocation model and fixup kind must agree)",
                    fixup.kind
                ),
            });
        }
        (
            AArch64RelocKind::ElfTlsieAdrGottprelPage21
            | AArch64RelocKind::ElfTlsieLd64GottprelLo12Nc,
            model,
        ) => {
            return Err(PipelineError::TargetObjectUnsupported {
                target: target_triple.to_string(),
                format: "ELF".to_string(),
                reason: format!(
                    "AArch64 ELF TLS initial-exec fixup {:?} carries model {model:?}; it must carry Some(InitialExec) (fail-closed: TLS relocation model and fixup kind must agree)",
                    fixup.kind
                ),
            });
        }
        (kind, Some(tls_model)) => {
            return Err(PipelineError::TargetObjectUnsupported {
                target: target_triple.to_string(),
                format: "ELF".to_string(),
                reason: format!(
                    "AArch64 ELF relocation emission does not yet support TLS/TLVP fixup {kind:?} with model Some({tls_model:?}); Darwin TLV descriptors cannot be mapped to ELF TLS relocations, and TLS-provenance fixups require a dedicated ELF TLS relocation model and must not be emitted as non-TLS relocations"
                ),
            });
        }
        (_, None) => {}
    }

    match fixup.kind {
        AArch64RelocKind::Unsigned => Ok(crate::elf::AArch64RelocType::Abs64),
        AArch64RelocKind::Branch26 => {
            aarch64_elf_branch_reloc_kind(target_triple, combined_code, fixup.offset)
        }
        AArch64RelocKind::Page21 => Ok(crate::elf::AArch64RelocType::AdrPrelPgHi21),
        AArch64RelocKind::Pageoff12 => Ok(crate::elf::AArch64RelocType::AddAbsLo12Nc),
        AArch64RelocKind::GotLoadPage21 => Ok(crate::elf::AArch64RelocType::AdrGotPage),
        AArch64RelocKind::GotLoadPageoff12 => Ok(crate::elf::AArch64RelocType::Ld64GotLo12Nc),
        AArch64RelocKind::ElfLdst8AbsLo12Nc => Ok(crate::elf::AArch64RelocType::Ldst8AbsLo12Nc),
        AArch64RelocKind::ElfLdst16AbsLo12Nc => Ok(crate::elf::AArch64RelocType::Ldst16AbsLo12Nc),
        AArch64RelocKind::ElfLdst32AbsLo12Nc => Ok(crate::elf::AArch64RelocType::Ldst32AbsLo12Nc),
        AArch64RelocKind::ElfLdst64AbsLo12Nc => Ok(crate::elf::AArch64RelocType::Ldst64AbsLo12Nc),
        AArch64RelocKind::ElfLdst128AbsLo12Nc => Ok(crate::elf::AArch64RelocType::Ldst128AbsLo12Nc),
        AArch64RelocKind::TlvpLoadPage21 | AArch64RelocKind::TlvpLoadPageoff12 => {
            Err(PipelineError::TargetObjectUnsupported {
                target: target_triple.to_string(),
                format: "ELF".to_string(),
                reason: format!(
                    "AArch64 ELF relocation emission does not yet support TLS/TLVP fixup {:?} with model {:?}; Darwin TLV descriptors cannot be mapped to ELF TLS relocations",
                    fixup.kind, fixup.tls_model
                ),
            })
        }
        other => Err(PipelineError::TargetObjectUnsupported {
            target: target_triple.to_string(),
            format: "ELF".to_string(),
            reason: format!("AArch64 ELF relocation emission does not yet support fixup {other:?}"),
        }),
    }
}

/// Map a raw ELF `r_type` value (parsed back OUT of an emitted object) to its
/// proof-inventory row. The inverse direction of
/// [`aarch64_elf_object_relocation_kind`], used by the ARTIFACT-LEVEL digest
/// cross-check: any relocation record found in the object bytes that the
/// mirrored inventory did not anticipate maps to a kind the inventory lacks
/// (unknown values land on `AArch64ElfOther`) and fails the digest closed.
#[cfg(feature = "verify")]
pub(crate) fn aarch64_elf_kind_from_r_type(r_type: u32) -> trust_cg_verify::ObjectRelocationKind {
    use crate::elf::constants as c;
    use trust_cg_verify::ObjectRelocationKind as O;
    match r_type {
        c::R_AARCH64_ABS64 => O::AArch64ElfAbs64,
        c::R_AARCH64_PREL32 => O::AArch64ElfPrel32,
        c::R_AARCH64_ADR_PREL_PG_HI21 => O::AArch64ElfAdrPrelPgHi21,
        c::R_AARCH64_ADD_ABS_LO12_NC => O::AArch64ElfAddAbsLo12Nc,
        c::R_AARCH64_JUMP26 => O::AArch64ElfJump26,
        c::R_AARCH64_CALL26 => O::AArch64ElfCall26,
        c::R_AARCH64_ADR_GOT_PAGE => O::AArch64ElfAdrGotPage,
        c::R_AARCH64_LD64_GOT_LO12_NC => O::AArch64ElfLd64GotLo12Nc,
        c::R_AARCH64_LDST8_ABS_LO12_NC => O::AArch64ElfLdst8AbsLo12Nc,
        c::R_AARCH64_LDST16_ABS_LO12_NC => O::AArch64ElfLdst16AbsLo12Nc,
        c::R_AARCH64_LDST32_ABS_LO12_NC => O::AArch64ElfLdst32AbsLo12Nc,
        c::R_AARCH64_LDST64_ABS_LO12_NC => O::AArch64ElfLdst64AbsLo12Nc,
        c::R_AARCH64_LDST128_ABS_LO12_NC => O::AArch64ElfLdst128AbsLo12Nc,
        c::R_AARCH64_TLSIE_ADR_GOTTPREL_PAGE21 => O::AArch64ElfTlsieAdrGottprelPage21,
        c::R_AARCH64_TLSIE_LD64_GOTTPREL_LO12_NC => O::AArch64ElfTlsieLd64GottprelLo12Nc,
        c::R_AARCH64_TLSLE_ADD_TPREL_HI12 => O::AArch64ElfTlsleAddTprelHi12,
        c::R_AARCH64_TLSLE_ADD_TPREL_LO12 => O::AArch64ElfTlsleAddTprelLo12,
        c::R_AARCH64_TLSLE_ADD_TPREL_LO12_NC => O::AArch64ElfTlsleAddTprelLo12Nc,
        c::R_AARCH64_TLSDESC_ADR_PAGE21 => O::AArch64ElfTlsdescAdrPage21,
        c::R_AARCH64_TLSDESC_LD64_LO12 => O::AArch64ElfTlsdescLd64Lo12,
        c::R_AARCH64_TLSDESC_ADD_LO12 => O::AArch64ElfTlsdescAddLo12,
        c::R_AARCH64_TLSDESC_CALL => O::AArch64ElfTlsdescCall,
        other => O::AArch64ElfOther(other),
    }
}

#[cfg(feature = "verify")]
fn aarch64_elf_object_relocation_kind(
    reloc: crate::elf::AArch64RelocType,
) -> trust_cg_verify::ObjectRelocationKind {
    match reloc {
        crate::elf::AArch64RelocType::Abs64 => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfAbs64
        }
        crate::elf::AArch64RelocType::Call26 => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfCall26
        }
        crate::elf::AArch64RelocType::Jump26 => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfJump26
        }
        crate::elf::AArch64RelocType::AdrPrelPgHi21 => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfAdrPrelPgHi21
        }
        crate::elf::AArch64RelocType::AddAbsLo12Nc => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfAddAbsLo12Nc
        }
        crate::elf::AArch64RelocType::AdrGotPage => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfAdrGotPage
        }
        crate::elf::AArch64RelocType::Ld64GotLo12Nc => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfLd64GotLo12Nc
        }
        crate::elf::AArch64RelocType::Ldst8AbsLo12Nc => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfLdst8AbsLo12Nc
        }
        crate::elf::AArch64RelocType::Ldst16AbsLo12Nc => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfLdst16AbsLo12Nc
        }
        crate::elf::AArch64RelocType::Ldst32AbsLo12Nc => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfLdst32AbsLo12Nc
        }
        crate::elf::AArch64RelocType::Ldst64AbsLo12Nc => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfLdst64AbsLo12Nc
        }
        crate::elf::AArch64RelocType::Ldst128AbsLo12Nc => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfLdst128AbsLo12Nc
        }
        crate::elf::AArch64RelocType::TlsieAdrGottprelPage21 => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfTlsieAdrGottprelPage21
        }
        crate::elf::AArch64RelocType::TlsieLd64GottprelLo12Nc => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfTlsieLd64GottprelLo12Nc
        }
        crate::elf::AArch64RelocType::TlsleAddTprelHi12 => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfTlsleAddTprelHi12
        }
        crate::elf::AArch64RelocType::TlsleAddTprelLo12 => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfTlsleAddTprelLo12
        }
        crate::elf::AArch64RelocType::TlsleAddTprelLo12Nc => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfTlsleAddTprelLo12Nc
        }
        crate::elf::AArch64RelocType::TlsdescAdrPage21 => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfTlsdescAdrPage21
        }
        crate::elf::AArch64RelocType::TlsdescLd64Lo12 => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfTlsdescLd64Lo12
        }
        crate::elf::AArch64RelocType::TlsdescAddLo12 => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfTlsdescAddLo12
        }
        crate::elf::AArch64RelocType::TlsdescCall => {
            trust_cg_verify::ObjectRelocationKind::AArch64ElfTlsdescCall
        }
        other => trust_cg_verify::ObjectRelocationKind::AArch64ElfOther(other as u32),
    }
}

/// What one AArch64 ELF unwind-table relocation record relocates.
#[cfg(feature = "verify")]
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AArch64ElfUnwindRelocationRole {
    /// The zPLR CIE's personality field (`DW_EH_PE_indirect|pcrel|sdata4`):
    /// the PC-relative address of the `DW.ref.<personality>` slot, which the
    /// personality decoder then reads indirectly.
    CiePersonality,
    /// The `DW_EH_PE_pcrel|sdata4` pc-begin field of `function`'s FDE.
    FdePcBegin {
        /// IR-level function name.
        function: String,
    },
    /// The `DW_EH_PE_pcrel|sdata4` LSDA pointer in the augmentation data of
    /// `function`'s FDE, addressing its LSDA in `.gcc_except_table`.
    FdeLsda {
        /// IR-level function name.
        function: String,
    },
    /// The 8-byte `DW.ref.<personality>` slot's content: the personality
    /// routine's absolute address.
    PersonalitySlot,
}

/// How an unwind row names a section, independently of the object's section
/// numbering: never by a name two sections could share.
#[cfg(feature = "verify")]
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum AArch64ElfSectionIdentity {
    /// The one section of this name, which the object must contain exactly
    /// once (`.eh_frame`, `.gcc_except_table`: names the ELF emitters own and
    /// refuse for data, `[TCG-SECTION-RESERVED]`).
    Unique(String),
    /// The section in which the one non-section symbol of this name is
    /// defined: a function's text section (bodies of several COMDAT
    /// functions can land in same-named sections), or the
    /// `DW.ref.<personality>` slot's own section.
    Defining(String),
}

/// The symbol an unwind row's `ELF64_R_SYM` must name.
#[cfg(feature = "verify")]
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum AArch64ElfRelocationSymbol {
    /// The one non-section symbol of this name.
    Named(String),
    /// An `STT_SECTION` symbol anchoring the identified section.
    SectionAnchor(AArch64ElfSectionIdentity),
}

/// One unwind-table relocation row of the AArch64 ELF relocation inventory:
/// the record the module emitter is expected to write, and what it
/// relocates.
///
/// The inventory derives these rows from the same personality choice,
/// `.gcc_except_table` layout, `.eh_frame` CFI and text placement the emitter
/// reads, but decides on its own which rows exist and what each one names;
/// [`crosscheck_aarch64_elf_unwind_relocation_rows`] compares them with an
/// emitted object, resolving every section and symbol to its index there.
#[cfg(feature = "verify")]
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AArch64ElfUnwindRelocationRow {
    /// What the record relocates.
    pub role: AArch64ElfUnwindRelocationRole,
    /// The section the record patches (its `.rela` section's `sh_info`).
    pub section: AArch64ElfSectionIdentity,
    /// `r_offset` within that section.
    pub offset: u64,
    /// `ELF64_R_TYPE(r_info)`.
    pub r_type: u32,
    /// The symbol `ELF64_R_SYM(r_info)` names.
    pub symbol: AArch64ElfRelocationSymbol,
    /// `r_addend`.
    pub addend: i64,
}

#[cfg(feature = "verify")]
impl AArch64ElfUnwindRelocationRow {
    /// The proof-inventory kind of this row.
    pub fn inventory_kind(&self) -> trust_cg_verify::ObjectRelocationKind {
        aarch64_elf_kind_from_r_type(self.r_type)
    }

    /// The value the linker writes into the field (AArch64 ELF psABI).
    pub fn formula(&self) -> &'static str {
        match self.r_type {
            crate::elf::constants::R_AARCH64_PREL32 => "S + A - P",
            crate::elf::constants::R_AARCH64_ABS64 => "S + A",
            _ => "unmodeled",
        }
    }

    /// Whether this row exists only because the module carries
    /// exception-handling structure (every row but an FDE pc-begin).
    pub fn is_exception_table_row(&self) -> bool {
        !matches!(self.role, AArch64ElfUnwindRelocationRole::FdePcBegin { .. })
    }
}

/// The target of one relocation record, by index in its object.
#[cfg(feature = "verify")]
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum AArch64ElfRelocationTarget {
    /// An `STT_SECTION` symbol, by the section header index it anchors.
    Section(usize),
    /// Any other symbol, by its symbol table index.
    Symbol(usize),
}

/// One relocation record keyed by indices of its object: the patched
/// section's header index, `r_offset`, type, target and `r_addend`.
#[cfg(feature = "verify")]
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct AArch64ElfRelocationKey {
    /// Header index of the patched section.
    pub section: usize,
    /// `r_offset`.
    pub offset: u64,
    /// `ELF64_R_TYPE(r_info)`.
    pub r_type: u32,
    /// What `ELF64_R_SYM(r_info)` names.
    pub target: AArch64ElfRelocationTarget,
    /// `r_addend`.
    pub addend: i64,
}

/// The mirrored unwind rows resolved into one emitted object, beside the
/// object's own unwind-table records.
#[cfg(feature = "verify")]
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AArch64ElfUnwindRelocationKeys {
    /// Every mirrored row, resolved to indices of the object, sorted.
    pub mirrored: Vec<AArch64ElfRelocationKey>,
    /// Every record of the object that patches `.eh_frame` or a section a
    /// mirrored row patches, sorted.
    pub emitted: Vec<AArch64ElfRelocationKey>,
}

/// A module's relocation inventory report, with the AArch64 ELF
/// unwind-table rows it counted.
#[cfg(feature = "verify")]
#[derive(Debug, Clone)]
pub struct ModuleRelocationInventory {
    /// The proof-inventory report over every row the object will carry.
    pub report: trust_cg_verify::ObjectRelocationInventoryReport,
    /// The `.eh_frame` and `DW.ref` slot rows, in the order the emitter
    /// writes them. Empty for Mach-O and for an ELF module emitted without
    /// unwind tables (frame layouts not supplied).
    pub elf_unwind_rows: Vec<AArch64ElfUnwindRelocationRow>,
    /// The unwind tables the object will carry whose content is trusted
    /// rather than proven (trusted base TB-12): the `.eh_frame` CFI of every
    /// ELF FDE, or the Mach-O compact-unwind entries and DWARF-fallback FDEs.
    /// Their relocation rows are inventoried; which frame state each PC range
    /// restores is not proved. `None` without unwind tables. The
    /// relocation-inventory certificate repeats it.
    pub trusted_unwind_tables: Option<String>,
}

#[cfg(feature = "verify")]
impl ModuleRelocationInventory {
    /// The report alone, for a caller that does not keep the unwind rows.
    ///
    /// Exception-table rows are already `Unverified` in every inventory
    /// report ([`mark_exception_table_rows_unverified`]), so an EH module's
    /// report is never promotable, with or without its rows.
    pub fn into_report_without_rows(self) -> trust_cg_verify::ObjectRelocationInventoryReport {
        self.report
    }
}

/// Report the entries at `indices` of `report` `Unverified` as
/// exception-table rows: the relocation is modeled, but the table it points
/// into (an LSDA, a personality reference, an unwind entry registering them)
/// carries no proof obligation (trusted base TB-12), and a certified object
/// never contains exception tables (`CompileError::ExceptionTablesUnproved`).
/// The one rule every object inventory (AArch64 and x86-64) applies.
#[cfg(feature = "verify")]
pub(crate) fn mark_exception_table_entries_unverified(
    report: &mut trust_cg_verify::ObjectRelocationInventoryReport,
    indices: impl IntoIterator<Item = usize>,
) {
    for index in indices {
        if let Some(entry) = report.entries.get_mut(index) {
            entry.status = trust_cg_verify::RelocationInventoryStatus::Unverified;
            entry.detail = "exception-table row: exception tables carry no proof obligation \
                            (trusted base TB-12), so a certified object never contains them \
                            ([TCG-EH-UNPROVED])"
                .to_string();
        }
    }
}

/// [`mark_exception_table_entries_unverified`] for the AArch64 ELF unwind
/// rows: every row but an FDE pc-begin (the CIE personality, FDE LSDA and
/// `DW.ref` slot rows). The unwind rows are the last `rows.len()` entries of
/// the report, in order.
#[cfg(feature = "verify")]
fn mark_exception_table_rows_unverified(
    report: &mut trust_cg_verify::ObjectRelocationInventoryReport,
    rows: &[AArch64ElfUnwindRelocationRow],
) {
    let first = report.entries.len().saturating_sub(rows.len());
    mark_exception_table_entries_unverified(
        report,
        rows.iter()
            .enumerate()
            .filter(|(_, row)| row.is_exception_table_row())
            .map(|(offset, _)| first + offset),
    );
}

/// The trusted-unwind disclosure of an AArch64 ELF object: its `.eh_frame`
/// FDEs, one per function. `None` without FDEs.
#[cfg(feature = "verify")]
pub(crate) fn aarch64_elf_unwind_trust_disclosure(
    rows: &[AArch64ElfUnwindRelocationRow],
) -> Option<String> {
    let frames = rows
        .iter()
        .filter(|row| !row.is_exception_table_row())
        .count();
    (frames > 0).then(|| {
        format!(
            "unwind CFI of {frames} .eh_frame FDE(s) (trusted base TB-12: decode round trip \
             and native tests, no proof obligation)"
        )
    })
}

/// The trusted-unwind disclosure of an AArch64 Mach-O object: one
/// `__LD,__compact_unwind` entry per function, `dwarf_fallbacks` of them with
/// a DWARF-fallback `__eh_frame` FDE. `None` without compact-unwind entries.
#[cfg(feature = "verify")]
pub(crate) fn aarch64_macho_unwind_trust_disclosure(
    functions: usize,
    dwarf_fallbacks: usize,
) -> Option<String> {
    (functions > 0).then(|| {
        format!(
            "compact unwind of {functions} function(s), {dwarf_fallbacks} with a \
             DWARF-fallback __eh_frame FDE (trusted base TB-12: encoder checks and native \
             tests, no proof obligation)"
        )
    })
}

/// Refuse exception-handling metadata whose object form the AArch64 ELF
/// relocation inventory does not enumerate. A positive catch type index is a
/// typed catch: its type-table entry would be a typeinfo reference needing a
/// relocation in `.gcc_except_table`. Only the catch-all index 0 (a NULL
/// entry), cleanup, and the empty Rust filter have no typeinfo relocation.
#[cfg(feature = "verify")]
fn reject_unenumerated_aarch64_elf_eh_metadata(func: &IrMachFunction) -> Result<(), PipelineError> {
    for pad in &func.eh_metadata.landing_pads {
        if trust_cg_lower::function::validate_rust_eh_empty_filter(
            &pad.catch_type_indices,
            pad.is_cleanup,
            func.eh_metadata.personality.as_deref().unwrap_or(""),
        )
        .map_err(|detail| PipelineError::EhSidecarUnsupported {
            function: func.name.clone(),
            api: "module_relocation_inventory_report",
            reason: detail.to_owned(),
        })? {
            continue;
        }
        if let Some(&index) = pad.catch_type_indices.iter().find(|&&index| index != 0) {
            return Err(PipelineError::EhSidecarUnsupported {
                function: func.name.clone(),
                api: "module_relocation_inventory_report",
                reason: format!(
                    "landing pad {:?} catches type index {index}: a typed catch needs a \
                     typeinfo relocation in `.gcc_except_table`, which this inventory does \
                     not enumerate (only catch-all index 0 and cleanup are) (fail-closed)",
                    pad.block
                ),
            });
        }
    }
    Ok(())
}

/// Check that one serialized LSDA carries no field that would need a
/// relocation: the AArch64 ELF module emitter writes none into
/// `.gcc_except_table`, so the inventory enumerates none.
///
/// The Itanium LSDA layout is read here independently of
/// `exception_handling.rs`. The LPStart encoding must be `DW_EH_PE_omit`
/// (landing pads are relative to the function start; no pointer). Call-site
/// fields must be function-relative `uleb128` or `udata4` values. Every
/// negative action must be the terminal filter -1, bound to an empty list
/// at TType base. Other exception specifications are refused. Every positive
/// filter must index a 4-byte NULL entry of an `indirect|pcrel|sdata4` type
/// table: a catch-all, which the personality matches without reading a
/// typeinfo pointer. A non-NULL entry is a typed catch's typeinfo reference.
#[cfg(feature = "verify")]
fn aarch64_elf_lsda_needs_no_relocation(lsda: &[u8]) -> Result<(), String> {
    const OMIT: u8 = 0xff;
    const ULEB128: u8 = 0x01;
    const UDATA4: u8 = 0x03;
    const INDIRECT_PCREL_SDATA4: u8 = 0x9b;
    fn byte(lsda: &[u8], at: &mut usize) -> Result<u8, String> {
        let value = lsda
            .get(*at)
            .copied()
            .ok_or_else(|| format!("truncated at byte {at}"))?;
        *at += 1;
        Ok(value)
    }
    fn uleb(lsda: &[u8], at: &mut usize) -> Result<u64, String> {
        let (mut value, mut shift) = (0u64, 0u32);
        loop {
            let next = byte(lsda, at)?;
            if shift > 63 {
                return Err(format!("ULEB128 ending at byte {at} exceeds 64 bits"));
            }
            value |= u64::from(next & 0x7f) << shift;
            if next & 0x80 == 0 {
                return Ok(value);
            }
            shift += 7;
        }
    }
    fn sleb(lsda: &[u8], at: &mut usize) -> Result<i64, String> {
        let (mut value, mut shift) = (0i64, 0u32);
        loop {
            let next = byte(lsda, at)?;
            if shift > 63 {
                return Err(format!("SLEB128 ending at byte {at} exceeds 64 bits"));
            }
            value |= i64::from(next & 0x7f) << shift;
            shift += 7;
            if next & 0x80 == 0 {
                if shift < 64 && next & 0x40 != 0 {
                    value |= -1i64 << shift;
                }
                return Ok(value);
            }
        }
    }
    let offset =
        |value: u64| usize::try_from(value).map_err(|_| "offset exceeds usize".to_string());

    let mut at = 0usize;
    let lpstart = byte(lsda, &mut at)?;
    if lpstart != OMIT {
        return Err(format!(
            "LPStart encoding {lpstart:#04x} is not DW_EH_PE_omit, so the LSDA would carry an \
             LPStart pointer needing a relocation"
        ));
    }
    let type_table_base = match byte(lsda, &mut at)? {
        OMIT => None,
        INDIRECT_PCREL_SDATA4 => {
            let distance = offset(uleb(lsda, &mut at)?)?;
            let base = at
                .checked_add(distance)
                .filter(|base| *base <= lsda.len())
                .ok_or_else(|| {
                    format!("type-table base {distance} bytes past byte {at} is out of bounds")
                })?;
            Some(base)
        }
        other => {
            return Err(format!(
                "TType encoding {other:#04x} is neither DW_EH_PE_omit nor \
                 indirect|pcrel|sdata4"
            ));
        }
    };
    let call_site_encoding = byte(lsda, &mut at)?;
    if call_site_encoding != ULEB128 && call_site_encoding != UDATA4 {
        return Err(format!(
            "call-site encoding {call_site_encoding:#04x} is not a function-relative \
             uleb128/udata4 value"
        ));
    }
    let table_len = offset(uleb(lsda, &mut at)?)?;
    let action_table = at
        .checked_add(table_len)
        .filter(|end| *end <= lsda.len())
        .ok_or_else(|| {
            format!("call-site table of {table_len} bytes at byte {at} is out of bounds")
        })?;
    let call_site_field = |at: &mut usize| -> Result<u64, String> {
        if call_site_encoding == ULEB128 {
            return uleb(lsda, at);
        }
        let field = lsda
            .get(*at..*at + 4)
            .ok_or_else(|| format!("truncated udata4 call-site field at byte {at}"))?;
        *at += 4;
        Ok(u64::from(u32::from_le_bytes(
            field.try_into().expect("four-byte slice"),
        )))
    };
    let mut max_filter = 0i64;
    while at < action_table {
        for _ in 0..3 {
            call_site_field(&mut at)?;
        }
        let action = uleb(lsda, &mut at)?;
        if at > action_table {
            return Err(format!(
                "call-site record crosses the table end at byte {action_table}"
            ));
        }
        if action == 0 {
            continue;
        }
        let mut record = action_table
            .checked_add(offset(action - 1)?)
            .ok_or_else(|| "action offset overflows".to_string())?;
        let mut steps = 0usize;
        loop {
            steps += 1;
            if steps > lsda.len() {
                return Err("an action chain does not terminate".to_string());
            }
            let mut cursor = record;
            let filter = sleb(lsda, &mut cursor)?;
            max_filter = max_filter.max(filter);
            let displacement_at = cursor;
            let displacement = sleb(lsda, &mut cursor)?;
            if filter < 0 {
                let bound_empty_list = type_table_base
                    .is_some_and(|base| base >= cursor && lsda.get(base) == Some(&0));
                if filter != -1 || displacement != 0 || !bound_empty_list {
                    return Err(format!(
                        "the action record at byte {record} has an unbound or nonempty \
                         exception-specification filter {filter}"
                    ));
                }
            }
            if displacement == 0 {
                break;
            }
            record = i64::try_from(displacement_at)
                .ok()
                .and_then(|base| base.checked_add(displacement))
                .and_then(|next| usize::try_from(next).ok())
                .filter(|next| *next >= action_table && *next < lsda.len())
                .ok_or_else(|| {
                    format!("the action displacement {displacement} at byte {displacement_at} leaves the action table")
                })?;
        }
    }
    if at != action_table {
        return Err(format!(
            "the call-site table ends at byte {at}, not at its declared end {action_table}"
        ));
    }
    if max_filter > 0 {
        let base = type_table_base.ok_or_else(|| {
            format!("type filter {max_filter} indexes a type table the LSDA does not have")
        })?;
        let entries = usize::try_from(max_filter)
            .ok()
            .filter(|entries| *entries <= lsda.len() / 4)
            .ok_or_else(|| format!("type filter {max_filter} indexes past the LSDA"))?;
        for index in 1..=entries {
            let end = base.checked_sub((index - 1) * 4);
            let entry = end
                .and_then(|end| end.checked_sub(4).map(|start| (start, end)))
                .filter(|(start, _)| *start >= action_table)
                .and_then(|(start, end)| lsda.get(start..end))
                .ok_or_else(|| format!("type-table entry {index} is out of bounds"))?;
            if entry != [0u8; 4] {
                return Err(format!(
                    "type-table entry {index} is a typeinfo reference {entry:02x?} (a typed \
                     catch), which would need a relocation"
                ));
            }
        }
    }
    Ok(())
}

/// Resolve the inventory's mirrored unwind rows into an emitted AArch64 ELF
/// object, and read the object's own unwind-table records, both keyed by
/// section and symbol INDEX.
///
/// The object is read with the ELF reparse gate's independent reader
/// ([`crate::elf::reparse::read_object_records`]), not the writer's state. A
/// row's [`AArch64ElfSectionIdentity`] resolves to exactly one section header
/// (a `Unique` name must occur once, a `Defining` symbol must be the one
/// non-section symbol of its name, defined in a section); anything ambiguous
/// or missing is an error. The emitted side is every record patching the
/// object's `.eh_frame`, the section of any defined symbol an `.eh_frame`
/// record names (the `DW.ref` slot the CIE points at), or a section some
/// mirrored row patches. The slot is found through the CIE's relocation and
/// its symbol, never by a section-name prefix, so a data global in a section
/// named like a slot is not read as one.
#[cfg(feature = "verify")]
pub fn aarch64_elf_unwind_relocation_keys(
    object: &[u8],
    rows: &[AArch64ElfUnwindRelocationRow],
) -> Result<AArch64ElfUnwindRelocationKeys, String> {
    use std::collections::BTreeSet;

    let records =
        crate::elf::reparse::read_object_records(object).map_err(|error| error.to_string())?;
    if records.machine != crate::elf::constants::EM_AARCH64 {
        return Err(format!("e_machine {} is not EM_AARCH64", records.machine));
    }
    let is_section_symbol = |symbol: &crate::elf::reparse::ElfSymbolRecord| {
        symbol.symbol_type == crate::elf::constants::STT_SECTION
    };
    let named_symbol = |name: &str| -> Result<usize, String> {
        let mut found = records
            .symbols
            .iter()
            .enumerate()
            .skip(1)
            .filter(|(_, symbol)| !is_section_symbol(symbol) && symbol.name == name)
            .map(|(index, _)| index);
        match (found.next(), found.next()) {
            (Some(index), None) => Ok(index),
            (None, _) => Err(format!("no symbol named `{name}`")),
            (Some(_), Some(_)) => Err(format!("more than one symbol is named `{name}`")),
        }
    };
    let resolve_section = |identity: &AArch64ElfSectionIdentity| -> Result<usize, String> {
        match identity {
            AArch64ElfSectionIdentity::Unique(name) => {
                let mut found = records
                    .sections
                    .iter()
                    .enumerate()
                    .filter(|(_, section)| section.name == *name)
                    .map(|(index, _)| index);
                match (found.next(), found.next()) {
                    (Some(index), None) => Ok(index),
                    (None, _) => Err(format!("no section named `{name}`")),
                    (Some(_), Some(_)) => Err(format!("more than one section is named `{name}`")),
                }
            }
            AArch64ElfSectionIdentity::Defining(name) => {
                let symbol = &records.symbols[named_symbol(name)?];
                let index = usize::from(symbol.section_index);
                if index == 0 || index >= records.sections.len() {
                    return Err(format!(
                        "symbol `{name}` is not defined in a section (st_shndx {index})"
                    ));
                }
                Ok(index)
            }
        }
    };

    let mut mirrored = Vec::with_capacity(rows.len());
    let mut patched = BTreeSet::new();
    for row in rows {
        let section = resolve_section(&row.section)?;
        patched.insert(section);
        let target = match &row.symbol {
            AArch64ElfRelocationSymbol::Named(name) => {
                AArch64ElfRelocationTarget::Symbol(named_symbol(name)?)
            }
            AArch64ElfRelocationSymbol::SectionAnchor(identity) => {
                AArch64ElfRelocationTarget::Section(resolve_section(identity)?)
            }
        };
        mirrored.push(AArch64ElfRelocationKey {
            section,
            offset: row.offset,
            r_type: row.r_type,
            target,
            addend: row.addend,
        });
    }
    // The object's `.eh_frame` is read whether or not a row names it: an
    // unwind table the mirror did not expect must not pass unread. So is the
    // section of every defined non-section symbol an `.eh_frame` record
    // names — the personality slot the CIE points at — found through the
    // CIE's own relocation, not through a section name.
    match resolve_section(&AArch64ElfSectionIdentity::Unique(".eh_frame".to_string())) {
        Ok(eh_frame) => {
            patched.insert(eh_frame);
            for relocation in records
                .relocations
                .iter()
                .filter(|relocation| relocation.target_section == eh_frame)
            {
                let index = relocation.record.symbol_index as usize;
                let symbol = records
                    .symbols
                    .get(index)
                    .ok_or_else(|| format!("symbol index {index} is out of range"))?;
                let defined = usize::from(symbol.section_index);
                if !is_section_symbol(symbol) && defined != 0 && defined < records.sections.len() {
                    patched.insert(defined);
                }
            }
        }
        Err(problem) if problem.starts_with("no section") => {}
        Err(problem) => return Err(problem),
    }

    let mut emitted = Vec::new();
    for relocation in &records.relocations {
        if !patched.contains(&relocation.target_section) {
            continue;
        }
        let index = relocation.record.symbol_index as usize;
        let symbol = records
            .symbols
            .get(index)
            .ok_or_else(|| format!("symbol index {index} is out of range"))?;
        let target = if is_section_symbol(symbol) {
            AArch64ElfRelocationTarget::Section(usize::from(symbol.section_index))
        } else {
            AArch64ElfRelocationTarget::Symbol(index)
        };
        emitted.push(AArch64ElfRelocationKey {
            section: relocation.target_section,
            offset: relocation.record.r_offset,
            r_type: relocation.record.reloc_type,
            target,
            addend: relocation.record.r_addend,
        });
    }
    mirrored.sort_unstable();
    emitted.sort_unstable();
    Ok(AArch64ElfUnwindRelocationKeys { mirrored, emitted })
}

/// Require an emitted AArch64 ELF object's unwind-table relocation records
/// to equal the relocation inventory's mirrored rows exactly, as multisets
/// of (patched section, offset, type, target, addend) keyed by index
/// ([`aarch64_elf_unwind_relocation_keys`]): a record the mirror did not name,
/// a mirrored row the object lacks, or a row that cannot be resolved
/// unambiguously fails closed.
#[cfg(feature = "verify")]
pub fn crosscheck_aarch64_elf_unwind_relocation_rows(
    object: &[u8],
    rows: &[AArch64ElfUnwindRelocationRow],
) -> Result<(), PipelineError> {
    let keys = aarch64_elf_unwind_relocation_keys(object, rows).map_err(|problem| {
        PipelineError::RelocationInventoryDigest(format!(
            "the emitted object's unwind-table relocations could not be matched to the \
             inventory's mirrored rows: {problem}"
        ))
    })?;
    if keys.mirrored == keys.emitted {
        return Ok(());
    }
    let mut unexpected = keys.emitted.clone();
    let mut missing = Vec::new();
    for row in &keys.mirrored {
        match unexpected.iter().position(|record| record == row) {
            Some(index) => {
                unexpected.remove(index);
            }
            None => missing.push(*row),
        }
    }
    Err(PipelineError::RelocationInventoryDigest(format!(
        "the object's unwind-table relocations differ from the inventory's mirrored rows: \
         emitted but not inventoried {unexpected:?}; inventoried but not emitted {missing:?}; \
         a relocation outside the mirrored inventory must never ship"
    )))
}

#[cfg(feature = "verify")]
fn aarch64_elf_relocation_inventory_report(
    object_name: impl Into<String>,
    target_triple: &str,
    combined_code: &[u8],
    fixups: &crate::macho::fixup::FixupList,
    additional_rows: impl IntoIterator<Item = trust_cg_verify::ObjectRelocationKind>,
) -> Result<trust_cg_verify::ObjectRelocationInventoryReport, PipelineError> {
    let mut emitted = Vec::new();
    for fixup in fixups.iter() {
        let reloc = aarch64_elf_reloc_kind(target_triple, combined_code, fixup)?;
        emitted.push(aarch64_elf_object_relocation_kind(reloc));
    }
    emitted.extend(additional_rows);
    // The Certified composition, AArch64 ELF lane (mirroring the x86-64 ELF
    // arm in `x86_64/pipeline.rs`): registry rows cite the standing
    // solver-backed value proofs (`trust_cg_verify::aarch64_elf_reloc_proofs`,
    // registered with negative controls in the proof database); the BINDING
    // half is the shared ELF reparse gate, which the checked-write funnel
    // runs at Enforce over the exact bytes of every emitted object (a record
    // mismatch fails the write closed). If the gate is downgraded
    // (`TCG_NO_ELF_REPARSE` / warn / off), the binding is absent and every
    // row reports Unverified — promotion re-fails closed. The four EMITTED
    // TLSLE/TLSIE kinds are registry rows citing their own value lane
    // (`aarch64_elf_tls_reloc_proofs`); the never-emitted checked non-NC
    // TPREL_LO12 stays outside the registry (fail-closed) per its doc.
    let registry = trust_cg_verify::ObjectRelocationProofRegistry::aarch64_elf_production();
    let binding = if crate::elf::reparse::elf_reparse_mode()
        == crate::elf::reparse::ElfReparseMode::Enforce
    {
        trust_cg_verify::ObjectProofBinding::ElfReparseEnforced
    } else {
        trust_cg_verify::ObjectProofBinding::Unbound
    };
    Ok(
        trust_cg_verify::ObjectRelocationInventoryReport::from_emitted_kinds_with_registry_and_binding(
            object_name,
            emitted,
            &registry,
            binding,
        ),
    )
}

/// Map an emitted AArch64 Mach-O relocation kind to its proof-inventory row.
///
/// Each emitted `relocation_info` row is named so the proof-promotion gate can
/// decide coverage. Naming a row is not Certified authority: a named kind is
/// covered only through the production registry's value-proof lanes plus the
/// ENC-9 reparse binding, and a raw type with no lane maps to
/// `AArch64MachOOther`, which never promotes.
#[cfg(feature = "verify")]
fn aarch64_macho_object_relocation_kind(
    kind: crate::macho::AArch64RelocKind,
) -> trust_cg_verify::ObjectRelocationKind {
    use crate::macho::AArch64RelocKind as K;
    use trust_cg_verify::ObjectRelocationKind as O;
    match kind {
        K::Page21 => O::AArch64MachOPage21,
        K::Pageoff12 => O::AArch64MachOPageoff12,
        K::GotLoadPage21 => O::AArch64MachOGotLoadPage21,
        K::GotLoadPageoff12 => O::AArch64MachOGotLoadPageoff12,
        K::Branch26 => O::AArch64MachOBranch26,
        K::Unsigned => O::AArch64MachOUnsigned,
        K::Subtractor => O::AArch64MachOSubtractor,
        K::TlvpLoadPage21 => O::AArch64MachOTlvpLoadPage21,
        K::TlvpLoadPageoff12 => O::AArch64MachOTlvpLoadPageoff12,
        other => O::AArch64MachOOther(other as u8),
    }
}

/// Build the object-relocation proof inventory for an AArch64 Mach-O object.
///
/// Walks the emitted symbolic fixups, names each as its `relocation_info` row,
/// and checks coverage against the production registry, whose rows cite the
/// standing solver-backed value-proof lanes
/// (`aarch64_macho_data/call/tlvp_reloc_proofs`, registered with negative
/// controls in the proof database and discharged by the strict proof gate).
/// The BINDING half of the Certified composition is the ENC-9 Mach-O reparse
/// gate, which the writer runs UNCONDITIONALLY at Enforce over the exact bytes
/// of every emitted object (a record mismatch fails the write closed, so a
/// promoted-but-unreparsed object cannot exist). If the gate is downgraded
/// (`TCG_NO_MACHO_REPARSE` / warn / off), the binding is absent and every row
/// reports Unverified — promotion re-fails closed (the `54762bc4` invariant).
/// An `ARM64_RELOC_ADDEND` prefix record is never a row of its own: the
/// resolver emits it only in front of the BRANCH26/PAGE21/PAGEOFF12 record it
/// modifies, and the artifact digest folds it into that row
/// ([`crosscheck_aarch64_macho_relocation_inventory_digest`]).
#[cfg(feature = "verify")]
fn aarch64_macho_relocation_inventory_report(
    object_name: impl Into<String>,
    fixups: &crate::macho::fixup::FixupList,
    additional_rows: impl IntoIterator<Item = trust_cg_verify::ObjectRelocationKind>,
) -> trust_cg_verify::ObjectRelocationInventoryReport {
    let mut emitted: Vec<trust_cg_verify::ObjectRelocationKind> = fixups
        .iter()
        .map(|fixup| aarch64_macho_object_relocation_kind(fixup.kind))
        .collect();
    emitted.extend(additional_rows);
    let registry = trust_cg_verify::ObjectRelocationProofRegistry::aarch64_macho_production();
    let binding = if crate::macho::reparse::macho_reparse_mode()
        == crate::macho::reparse::MachoReparseMode::Enforce
    {
        trust_cg_verify::ObjectProofBinding::MachOReparseEnforced
    } else {
        trust_cg_verify::ObjectProofBinding::Unbound
    };
    trust_cg_verify::ObjectRelocationInventoryReport::from_emitted_kinds_with_registry_and_binding(
        object_name,
        emitted,
        &registry,
        binding,
    )
}

/// The inventory row of a raw AArch64 Mach-O `r_type`, the artifact-side twin
/// of [`aarch64_macho_object_relocation_kind`] (the two agree on every emitter
/// kind); a value outside the named rows lands on `AArch64MachOOther`, which no
/// proof lane covers.
#[cfg(feature = "verify")]
pub(crate) fn aarch64_macho_kind_from_r_type(r_type: u8) -> trust_cg_verify::ObjectRelocationKind {
    use trust_cg_verify::ObjectRelocationKind as O;
    match r_type {
        0 => O::AArch64MachOUnsigned,
        1 => O::AArch64MachOSubtractor,
        2 => O::AArch64MachOBranch26,
        3 => O::AArch64MachOPage21,
        4 => O::AArch64MachOPageoff12,
        5 => O::AArch64MachOGotLoadPage21,
        6 => O::AArch64MachOGotLoadPageoff12,
        8 => O::AArch64MachOTlvpLoadPage21,
        9 => O::AArch64MachOTlvpLoadPageoff12,
        other => O::AArch64MachOOther(other),
    }
}

/// The record shape (`r_pcrel`, `r_length`) that the registered value-proof
/// lane of each AArch64 Mach-O kind models: the lane headers of
/// `trust_cg_verify::aarch64_macho_{data,call,tlvp}_reloc_proofs`, whose
/// `*_wrong_pcrel_*` negative controls refute any other `r_pcrel`. `None` for
/// a kind with no lane: it never earns credit, so there is no shape to bind.
#[cfg(feature = "verify")]
fn aarch64_macho_modeled_record_shape(
    kind: trust_cg_verify::ObjectRelocationKind,
) -> Option<(bool, u8)> {
    use trust_cg_verify::ObjectRelocationKind as O;
    match kind {
        O::AArch64MachOBranch26
        | O::AArch64MachOPage21
        | O::AArch64MachOGotLoadPage21
        | O::AArch64MachOTlvpLoadPage21 => Some((true, 2)),
        O::AArch64MachOPageoff12
        | O::AArch64MachOGotLoadPageoff12
        | O::AArch64MachOTlvpLoadPageoff12 => Some((false, 2)),
        O::AArch64MachOUnsigned | O::AArch64MachOSubtractor => Some((false, 3)),
        _ => None,
    }
}

/// ARTIFACT-LEVEL relocation digest for AArch64 Mach-O, the sibling of the ELF
/// `crosscheck_elf_relocation_inventory_digest` in `compiler.rs`.
///
/// The Mach-O inventory is built by MIRRORING emitter bookkeeping, and the
/// ENC-9 reparse gate proves only bytes == writer intent, so a writer-side row
/// the mirror never anticipated would pass both while shipping uninventoried.
/// This parses every relocation record back OUT of the object bytes (the
/// independent `macho::reparse` reader, which also requires an ARM64
/// `cputype`) and requires their kind multiset to equal the inventory rows, in
/// EITHER direction. Per record it also binds the proof credit to the
/// semantics the lanes model, refusing otherwise:
///
/// * every lane-covered kind must carry the `r_pcrel`/`r_length` its lane
///   models ([`aarch64_macho_modeled_record_shape`]): a pc-relative UNSIGNED
///   or a 4-byte SUBTRACTOR is not the row the proof discharged;
/// * `ARM64_RELOC_SUBTRACTOR` must be immediately followed (same section, same
///   `r_address`) by its `ARM64_RELOC_UNSIGNED` minuend: the data lane proves
///   the PAIR, never a lone subtrahend;
/// * `ARM64_RELOC_ADDEND` is a prefix record (non-extern, `r_pcrel=0`,
///   `r_length=2`) carrying the addend of the record after it, so it is folded
///   into that row and is not an inventory row itself. It is refused unless
///   the next record in the same section sits at the same address and is one
///   of the BRANCH26/PAGE21/PAGEOFF12 kinds the resolver pairs it with.
///
/// A raw type with no lane maps to `AArch64MachOOther`, which the inventory
/// must then name too and which never promotes. The comparison is by kind, not
/// by section, address or target: a row the emitter moves or retargets while
/// keeping its kind is not detected here.
#[cfg(feature = "verify")]
pub(crate) fn crosscheck_aarch64_macho_relocation_inventory_digest(
    object_bytes: &[u8],
    inventory_kinds: &[trust_cg_verify::ObjectRelocationKind],
) -> Result<(), PipelineError> {
    use crate::macho::AArch64RelocKind as K;
    use trust_cg_verify::ObjectRelocationKind as O;
    let refuse = |section: &str, message: String| {
        Err(PipelineError::RelocationInventoryDigest(format!(
            "{section}: {message}; the relocation inventory digest fails closed"
        )))
    };
    let sections =
        crate::macho::reparse::relocation_records(crate::macho::MachOTarget::AArch64, object_bytes)
            .map_err(|e| {
                PipelineError::RelocationInventoryDigest(format!(
                    "emitted Mach-O object failed relocation digest parse: {e}"
                ))
            })?;
    let mut artifact = Vec::new();
    for (section, records) in &sections {
        for (index, record) in records.iter().enumerate() {
            let partner = records
                .get(index + 1)
                .filter(|next| next.r_address == record.r_address);
            if record.r_type == K::Addend as u8 {
                if record.r_extern || record.r_pcrel || record.r_length != 2 {
                    return refuse(
                        section,
                        format!(
                            "ARM64_RELOC_ADDEND at {:#x} has r_extern={} r_pcrel={} r_length={}, \
                             not the non-extern 4-byte prefix record",
                            record.r_address, record.r_extern, record.r_pcrel, record.r_length
                        ),
                    );
                }
                let prefixable = [K::Branch26 as u8, K::Page21 as u8, K::Pageoff12 as u8];
                if !partner.is_some_and(|next| prefixable.contains(&next.r_type)) {
                    return refuse(
                        section,
                        format!(
                            "ARM64_RELOC_ADDEND at {:#x} is not immediately followed by the \
                             BRANCH26/PAGE21/PAGEOFF12 record it modifies",
                            record.r_address
                        ),
                    );
                }
                continue;
            }
            let kind = aarch64_macho_kind_from_r_type(record.r_type);
            if let Some((pcrel, length)) = aarch64_macho_modeled_record_shape(kind)
                && (record.r_pcrel != pcrel || record.r_length != length)
            {
                return refuse(
                    section,
                    format!(
                        "{kind} at {:#x} has r_pcrel={} r_length={} but its value-proof lane \
                         models r_pcrel={pcrel} r_length={length}",
                        record.r_address, record.r_pcrel, record.r_length
                    ),
                );
            }
            if kind == O::AArch64MachOSubtractor
                && !partner.is_some_and(|next| next.r_type == K::Unsigned as u8)
            {
                return refuse(
                    section,
                    format!(
                        "ARM64_RELOC_SUBTRACTOR at {:#x} is not immediately followed by its \
                         ARM64_RELOC_UNSIGNED minuend at the same address",
                        record.r_address
                    ),
                );
            }
            artifact.push(kind);
        }
    }
    artifact.sort_unstable();
    let mut inventory = inventory_kinds.to_vec();
    inventory.sort_unstable();
    if artifact != inventory {
        return Err(PipelineError::RelocationInventoryDigest(format!(
            "Mach-O object carries {artifact:?} but the proof inventory names {inventory:?}; \
             a relocation outside the mirrored inventory must never ship"
        )));
    }
    Ok(())
}

/// Relocate pointer slots using the final locals-first ELF symbol indices.
/// Shared by emitters with and without unwind metadata.
///
/// Every slot becomes one `R_AARCH64_ABS64` (addend in `r_addend`) in the
/// `.rela.*` section of the holder's own section. For a thread-local that is
/// its `.tdata` (or explicit `.tdata.*` / COMDAT `.tdata.X`) initial-value
/// template: the static or dynamic linker relocates the template image once,
/// and the TLS runtime copies the relocated image into each thread's block,
/// exactly as for C `__thread void *p = &x;`. A slot's target is never a
/// thread-local (refused by `validate_aarch64_object_globals`).
fn add_aarch64_elf_global_relocations(
    writer: &mut crate::elf::ElfWriter,
    globals: &[ObjectGlobal],
    global_symbol_rows: &[ElfGlobalSymbolRow],
    symbol_indices: &HashMap<String, u32>,
) -> Result<(), PipelineError> {
    use crate::elf::Elf64Rela;
    if globals.iter().any(|global| !global.symbol_refs.is_empty()) {
        let global_rows: HashMap<&str, (u16, u64)> = global_symbol_rows
            .iter()
            .map(|row| (row.name.as_str(), (row.section, row.offset)))
            .collect();
        for global in globals {
            if global.symbol_refs.is_empty() {
                continue;
            }
            let (section_shndx, base_offset) = global_rows
                .get(global.name.as_str())
                .copied()
                .ok_or_else(|| {
                    PipelineError::ObjectEmission(format!(
                        "ELF data relocation: global `{}` has symbol-address slots but \
                         was not placed in a data section (fail-closed)",
                        global.name
                    ))
                })?;
            for sref in &global.symbol_refs {
                let symbol_index = symbol_indices
                    .get(&sref.symbol)
                    .copied()
                    .expect("symbol-ref target added to the ELF symbol table above");
                writer.add_relocation(
                    (section_shndx - 1) as usize,
                    Elf64Rela::aarch64(
                        base_offset.checked_add(sref.offset).ok_or_else(|| {
                            PipelineError::ObjectEmission(
                                "ELF data relocation offset overflow".into(),
                            )
                        })?,
                        symbol_index,
                        crate::elf::AArch64RelocType::Abs64,
                        sref.addend,
                    ),
                );
            }
        }
    }
    Ok(())
}

/// Refuse a text relocation whose displacement this object's own layout
/// already fixes outside the psABI window of its ELF relocation kind.
///
/// Only a fixup against a function defined in the same combined text section
/// has a known displacement: `target + addend - site` for `CALL26`/`JUMP26`.
/// For a direct `ADRP` to such a function the page delta also depends on the
/// section's placement modulo 4 KiB, so the check admits only displacements
/// that fit for every placement (one page of margin at each end). Targets in
/// other sections or objects, and GOT slots, are placed by the linker, whose
/// own overflow check (or range-extension veneer, for the branch kinds)
/// decides them.
pub(crate) fn check_aarch64_intra_object_relocation_windows(
    target_triple: &str,
    combined_code: &[u8],
    func_offsets: &[(String, u64)],
    fixups: &crate::macho::fixup::FixupList,
) -> Result<(), PipelineError> {
    use crate::macho::FixupTarget;

    if fixups.is_empty() {
        return Ok(());
    }
    let defined: HashMap<&str, u64> = func_offsets
        .iter()
        .map(|(name, offset)| (name.as_str(), *offset))
        .collect();
    for fixup in fixups.iter() {
        let name = match &fixup.target {
            FixupTarget::NamedSymbol(name) | FixupTarget::ExactNamedSymbol(name) => name,
            _ => continue,
        };
        let Some(&target) = defined.get(name.as_str()) else {
            continue;
        };
        let (relocation, page_margin) = match fixup.kind {
            crate::macho::AArch64RelocKind::Branch26 => (
                aarch64_elf_branch_reloc_kind(target_triple, combined_code, fixup.offset)?,
                0,
            ),
            crate::macho::AArch64RelocKind::Page21 => {
                (crate::elf::AArch64RelocType::AdrPrelPgHi21, 4096)
            }
            _ => continue,
        };
        let Some(window) = relocation.displacement_window() else {
            continue;
        };
        let displacement = i128::from(target) + i128::from(fixup.addend) - i128::from(fixup.offset);
        let admitted = i128::from(window.min) + page_margin..=i128::from(window.max) - page_margin;
        if !admitted.contains(&displacement) {
            return Err(PipelineError::RelocationWindowExceeded {
                relocation: relocation.psabi_name(),
                symbol: name.clone(),
                site: u64::from(fixup.offset),
                displacement: i64::try_from(displacement).unwrap_or(i64::MAX),
                min: window.min,
                max: window.max,
            });
        }
    }
    Ok(())
}

/// Refuse a local-exec TLS access whose `R_AARCH64_TLSLE_ADD_TPREL_HI12`
/// value this object already puts above the psABI window `0 <= X < 2^24`.
///
/// `X = TPREL(S + A)`. On AArch64 (TLS variant 1) the executable's TLS block
/// starts `align_up(16, p_align)` bytes above the thread pointer, and a
/// thread-local this object defines lies at least `o` bytes into the block,
/// `o` being its offset in this object's TLS section (TLS from other objects
/// placed before it only adds to that), so `X >= 16 + o + A`; for an
/// imported thread-local `o` is taken as 0. When
/// that lower bound already exceeds the window, every link overflows, and
/// the object is refused by name instead. A bound inside the window is left
/// to the static linker's check of the linked value (GNU ld 2.42, gold and
/// LLD 22 all refuse `X = 2^24`). `_LO12_NC` has no check: its high part is
/// the `HI12` one.
fn check_aarch64_local_exec_tls_windows(
    rows: &[ElfGlobalSymbolRow],
    fixups: &crate::macho::fixup::FixupList,
) -> Result<(), PipelineError> {
    use crate::elf::AArch64RelocType;
    use crate::macho::{AArch64RelocKind, FixupTarget};

    let Some(window) = AArch64RelocType::TlsleAddTprelHi12.displacement_window() else {
        unreachable!("TLSLE_ADD_TPREL_HI12 is a checked relocation");
    };
    for fixup in fixups.iter() {
        if fixup.kind != AArch64RelocKind::ElfTlsleAddTprelHi12 {
            continue;
        }
        let (FixupTarget::NamedSymbol(symbol) | FixupTarget::ExactNamedSymbol(symbol)) =
            &fixup.target
        else {
            // A non-named target is refused by the emitter's own pass.
            continue;
        };
        let offset = rows
            .iter()
            .find(|row| row.is_tls && row.name == *symbol)
            .map_or(0, |row| row.offset);
        let minimum = i128::from(crate::elf::reloc::AARCH64_TLS_TCB_BYTES)
            + i128::from(offset)
            + i128::from(fixup.addend);
        if minimum > i128::from(window.max) {
            return Err(PipelineError::LocalExecTlsWindowExceeded {
                symbol: symbol.clone(),
                site: u64::from(fixup.offset),
                offset,
                addend: fixup.addend,
                minimum,
                max: window.max,
            });
        }
    }
    Ok(())
}

fn emit_aarch64_elf_with_supported_fixups(
    target_triple: &str,
    combined_code: &[u8],
    func_offsets: &[(String, u64)],
    globals: &[ObjectGlobal],
    fixups: &crate::macho::fixup::FixupList,
    text: &ElfTextPlan,
    plan: &ElfModuleSymbolPlan<'_>,
    debug: Option<&crate::dwarf_info::DwarfSectionImage>,
) -> Result<Vec<u8>, PipelineError> {
    use crate::elf::ElfWriter;

    check_aarch64_intra_object_relocation_windows(
        target_triple,
        combined_code,
        func_offsets,
        fixups,
    )?;

    let mut writer = ElfWriter::new(crate::elf::ElfMachine::AArch64);
    let text_sections = add_elf_text_sections(&mut writer, text)?;

    // Every symbol goes through the checked API and relocation indices are
    // read only once the table is complete (`final_symbol_index` then freezes
    // it), so the writer's locals-first partition cannot shift an index
    // whatever binding a function carries. Insertion order is the historical
    // one (local data, functions, external data, TLS imports, undefined), so an
    // all-global module serializes byte-identically.
    let global_symbol_rows = add_elf_global_sections(&mut writer, globals)?;
    check_aarch64_local_exec_tls_windows(&global_symbol_rows, fixups)?;
    let mut symbol_ids = Vec::new();
    for row in global_symbol_rows.iter().filter(|row| !row.is_external) {
        let id = add_elf_global_row_symbol(&mut writer, row)?;
        symbol_ids.push((row.name.clone(), id));
    }
    symbol_ids.extend(add_elf_function_symbols(
        &mut writer,
        text,
        &text_sections,
        plan,
    )?);
    for row in global_symbol_rows.iter().filter(|row| row.is_external) {
        // A weak DEFINITION gets STB_WEAK so duplicate definitions across objects
        // coalesce instead of dup-strong-erroring; a strong one stays STB_GLOBAL.
        let id = add_elf_global_row_symbol(&mut writer, row)?;
        symbol_ids.push((row.name.clone(), id));
    }
    let mut known_names: BTreeSet<String> =
        symbol_ids.iter().map(|(name, _)| name.clone()).collect();

    // Thread-local IMPORTS: undefined STT_TLS symbols (a TLS relocation
    // against a non-TLS undefined symbol is a link-time kind mismatch), added
    // BEFORE the generic undefined pass so the TPREL fixups bind to these.
    for name in elf_tls_import_names(globals) {
        if known_names.insert(name.clone()) {
            let symbol = elf_undefined_symbol(&name, crate::elf::constants::STT_TLS, plan);
            let id = writer.add_checked_symbol(symbol)?;
            symbol_ids.push((name, id));
        }
    }

    let tls_anchors = add_aarch64_elf_reference_symbols(
        &mut writer,
        target_triple,
        combined_code,
        func_offsets,
        globals,
        &global_symbol_rows,
        fixups,
        plan,
        &known_names,
        None,
        "AArch64 ELF",
        &mut symbol_ids,
    )?;
    let debug = attach_elf_debug_sections(&mut writer, debug, text, &text_sections, None)?;
    let symbol_indices = final_elf_symbol_indices(&mut writer, &symbol_ids)?;
    add_aarch64_elf_text_relocations(
        &mut writer,
        target_triple,
        combined_code,
        fixups,
        text,
        &text_sections,
        &symbol_indices,
        &tls_anchors,
    )?;

    add_aarch64_elf_global_relocations(&mut writer, globals, &global_symbol_rows, &symbol_indices)?;
    relocate_elf_debug_sections(&mut writer, debug.as_ref())?;

    finish_elf_object(writer)
}

/// Refuse an AArch64 object whose relocations contradict its relocation
/// model.
///
/// This is the object-level backstop behind the adapter's access-model
/// selection (Pipeline API callers hand in machine code directly). It reads
/// the one address predicate
/// ([`trust_cg_lower::RelocationModel::symbol_address_is_got_indirect`])
/// from the object symbols the emitter is about to write: each function
/// definition's binding (`plan.function_bindings`, empty meaning all
/// `STB_GLOBAL`/`STV_DEFAULT`, else 1:1 with `function_names`), each data
/// row's [`ObjectGlobal`], and each undefined reference (`plan`).
///
/// * `pie`/`pic` are implemented only for ELF; any other object format
///   refuses them rather than emit code for a link contract it does not model.
/// * Under every model an ELF PC-relative page reference
///   (`R_AARCH64_ADR_PREL_PG_HI21` / `R_AARCH64_ADD_ABS_LO12_NC`) to an
///   undefined reference the plan DESCRIBES is refused, as the predicate
///   says for every undefined reference: a weak one (absent, it must read 0,
///   which only its GOT slot yields), and a function declaration or a data
///   import with a stated visibility (its definition may be a GNU IFUNC,
///   whose canonical address only a GOT slot holds in a PIE, a static PIE or
///   a shared object; a data declaration may name one too).
/// * Under `pic` a PC-relative page reference to any symbol the predicate
///   makes GOT-indirect is refused: a default-visibility global or weak
///   function or data definition, and every undefined symbol. It would
///   bypass a preempting definition, and the static linker refuses it for
///   `-shared`.
/// * Under `static`/`pie` an undefined symbol the plan does not describe (a
///   default-visibility strong one) is not checked: it may be data, which an
///   executable's link resolves PC-relatively through a copy relocation.
///
/// Calls (`CALL26`/`JUMP26`) stay legal: the linker routes a preemptible
/// target through the PLT and an IFUNC through its IPLT stub. Exact
/// module-function targets name local definitions by contract and are
/// exempt. Under `pic` the executable-only TLS models (local-exec,
/// initial-exec) are refused; a shared object uses TLS descriptors.
fn reject_aarch64_object_relocation_model_violations(
    relocation_model: trust_cg_lower::RelocationModel,
    target_triple: &str,
    function_names: &[String],
    plan: &ElfModuleSymbolPlan<'_>,
    globals: &[ObjectGlobal],
    fixups: &crate::macho::fixup::FixupList,
) -> Result<(), PipelineError> {
    use crate::macho::{AArch64RelocKind, FixupTarget};

    if !target_triple_uses_elf(target_triple) {
        if relocation_model == trust_cg_lower::RelocationModel::Static {
            return Ok(());
        }
        return Err(PipelineError::TargetObjectUnsupported {
            target: target_triple.to_string(),
            format: "native object format".to_string(),
            reason: format!(
                "relocation model `{relocation_model}` is implemented only for AArch64 ELF objects (fail-closed)"
            ),
        });
    }
    let function_bindings = plan.function_bindings;
    if !function_bindings.is_empty() && function_bindings.len() != function_names.len() {
        return Err(PipelineError::ObjectEmission(format!(
            "relocation-model check received {} symbol binding(s) for {} function(s); a \
             binding vector must be empty or 1:1 with the functions (fail-closed)",
            function_bindings.len(),
            function_names.len()
        )));
    }
    let shared_object = relocation_model.definitions_are_preemptible();
    // The adapter chose GOT or PC-relative access with the same predicate;
    // this re-reads it from the symbols the emitter is about to write.
    let weak_undefined: BTreeSet<&str> = plan
        .weak_undefined
        .iter()
        .copied()
        .chain(
            globals
                .iter()
                .filter(|global| global.is_import && global.is_weak)
                .map(|global| global.name.as_str()),
        )
        .collect();
    let got_indirect = |name: &str| -> Result<(bool, &'static str), PipelineError> {
        if let Some(index) = function_names.iter().position(|function| function == name) {
            let binding =
                function_symbol_binding_at(function_bindings, index, function_names.len(), name)?;
            return Ok((
                binding.is_preemptible_under(relocation_model),
                "a preemptible function definition",
            ));
        }
        if let Some(global) = globals.iter().find(|global| global.name == name) {
            let what = if global.is_import {
                "an undefined symbol"
            } else {
                "a preemptible data definition"
            };
            return Ok((global.binds_outside_object_under(relocation_model), what));
        }
        let (binding, visibility) = plan.undefined_reference(name);
        Ok((
            relocation_model.symbol_address_is_got_indirect(binding, visibility),
            "an undefined symbol",
        ))
    };
    for fixup in fixups.iter() {
        let name = match &fixup.target {
            FixupTarget::NamedSymbol(name) => name.as_str(),
            FixupTarget::ExactNamedSymbol(_) => continue,
            other if shared_object => {
                return Err(PipelineError::TargetObjectUnsupported {
                    target: target_triple.to_string(),
                    format: "ELF".to_string(),
                    reason: format!(
                        "AArch64 ELF relocation requires a named symbol target; got {other:?}"
                    ),
                });
            }
            // The emitter refuses a non-named target itself.
            _ => continue,
        };
        if shared_object
            && let Some(
                model @ (trust_cg_ir::TlsModel::LocalExec | trust_cg_ir::TlsModel::InitialExec),
            ) = fixup.tls_model
        {
            return Err(PipelineError::TargetObjectUnsupported {
                target: target_triple.to_string(),
                format: "ELF".to_string(),
                reason: format!(
                    "relocation model `{relocation_model}` compiles a shared object, but fixup {:?} against `{name}` uses the executable-only TLS model {model:?}; a shared object reaches thread-locals through TLS descriptors (fail-closed)",
                    fixup.kind
                ),
            });
        }
        if !matches!(
            fixup.kind,
            AArch64RelocKind::Page21 | AArch64RelocKind::Pageoff12
        ) {
            continue;
        }
        if weak_undefined.contains(name) {
            return Err(PipelineError::TargetObjectUnsupported {
                target: target_triple.to_string(),
                format: "ELF".to_string(),
                reason: format!(
                    "fixup {:?} addresses `{name}`, a weak undefined symbol, PC-relatively under relocation model `{relocation_model}`; absent, it must read as 0, which only its GOT slot yields (fail-closed)",
                    fixup.kind
                ),
            });
        }
        if let Some(visibility) = plan.undefined_visibility.get(name) {
            return Err(PipelineError::TargetObjectUnsupported {
                target: target_triple.to_string(),
                format: "ELF".to_string(),
                reason: format!(
                    "fixup {:?} addresses `{name}`, a declared function (visibility {visibility}), PC-relatively under relocation model `{relocation_model}`; its definition may be a GNU IFUNC, whose canonical address only its GOT slot holds (fail-closed)",
                    fixup.kind
                ),
            });
        }
        if let Some(visibility) = plan.undefined_data_visibility.get(name) {
            return Err(PipelineError::TargetObjectUnsupported {
                target: target_triple.to_string(),
                format: "ELF".to_string(),
                reason: format!(
                    "fixup {:?} addresses `{name}`, a data import (visibility {visibility}), PC-relatively under relocation model `{relocation_model}`; the symbol it names may be a GNU IFUNC function, whose canonical address only its GOT slot holds (fail-closed)",
                    fixup.kind
                ),
            });
        }
        if !shared_object {
            continue;
        }
        let (got_indirect, what) = got_indirect(name)?;
        if got_indirect {
            return Err(PipelineError::TargetObjectUnsupported {
                target: target_triple.to_string(),
                format: "ELF".to_string(),
                reason: format!(
                    "relocation model `{relocation_model}` compiles a shared object, but fixup {:?} addresses `{name}`, {what}, PC-relatively; its address must be loaded from the GOT (fail-closed)",
                    fixup.kind
                ),
            });
        }
    }
    Ok(())
}

fn emit_target_elf_or_reject_fixups(
    target_triple: &str,
    fixups: &crate::macho::fixup::FixupList,
    combined_code: &[u8],
    func_offsets: &[(String, u64)],
    globals: &[ObjectGlobal],
    text_align_log2: u8,
    plan: &ElfModuleSymbolPlan<'_>,
    text: ElfTextOptions<'_>,
    debug: Option<&crate::dwarf_info::DwarfSectionImage>,
) -> Result<Option<Vec<u8>>, PipelineError> {
    reject_unsupported_aarch64_object_format(target_triple)?;
    if !target_triple_uses_elf(target_triple) {
        return Ok(None);
    }

    // The caller has passed the AArch64 target gate above. Do not derive the
    // ELF e_machine from an arbitrary triple: the bytes in `combined_code` are
    // unconditionally little-endian AArch64.
    let machine = crate::elf::ElfMachine::AArch64;
    let text = plan_elf_text(machine, combined_code, func_offsets, text_align_log2, text)?;
    reject_elf_debug_with_split_text(target_triple, &text, debug)?;

    if !fixups.is_empty() || globals.iter().any(|global| !global.symbol_refs.is_empty()) {
        return emit_aarch64_elf_with_supported_fixups(
            target_triple,
            combined_code,
            func_offsets,
            globals,
            fixups,
            &text,
            plan,
            debug,
        )
        .map(Some);
    }

    emit_elf_with_function_symbols(machine, &text, globals, plan, debug).map(Some)
}

/// Emit an AArch64 ELF object with whole-module `.eh_frame` unwind tables
/// (and `.gcc_except_table` LSDAs for exception-handling functions).
///
/// This is the ELF analogue of [`Pipeline::emit_module_macho_with_unwind`]
/// ([TCG-EH-A64-BATCH] / the FUZZ-7 [TCG-EH-WALK] class): when ANY function in
/// a linked image raises a panic, the unwinder must be able to WALK every
/// trust-cg frame between the throw and the handler. ELF has no compact-unwind
/// section, so EVERY function gets a DWARF FDE:
///
/// * a frame-based function (`layout.uses_frame_pointer`) gets the standard
///   prologue-describing CFI ([`DwarfFde::from_layout`] — the same generator
///   the proven Mach-O DWARF fallback uses);
/// * a zero-frame leaf gets an EMPTY-instruction FDE: the CIE's initial
///   `DW_CFA_def_cfa SP, 0` is exact for its whole body and X30 keeps the
///   return address (`REG_UNSAVED` default rule);
/// * an EH function's REAL LSDA lands in `.gcc_except_table`, referenced from
///   its FDE augmentation; when the module carries EH the shared CIE is zPLR,
///   and every non-EH function gets a synthetic ALL-FILLER LSDA (one
///   `landing_pad == 0` region covering `[0, code_len)`) — the personality's
///   "no handler here, continue unwinding" answer, mirroring the audited
///   Mach-O filler policy (it can only tell the unwinder to KEEP WALKING).
///
/// Pointer scheme (GNU/Linux `.eh_frame` convention): all record pointers are
/// 4-byte PC-relative fields resolved by `R_AARCH64_PREL32` relocations —
/// FDE pc-begin (`pcrel|sdata4`) against the local `STT_SECTION` anchor of
/// the function's text section (+ its offset there), LSDA (`pcrel|sdata4`)
/// against the local `.gcc_except_table` anchor (+ the LSDA's offset), and
/// the CIE personality (`indirect|pcrel|sdata4`) against the
/// `DW.ref.<personality>` slot, an 8-byte cell whose own `R_AARCH64_ABS64`
/// holds the personality's address (see
/// [`crate::dwarf_cfi::DwarfCie::aarch64_elf_with_eh`]). No mid-object
/// `.eh_frame` terminator is emitted (crtend.o owns it), matching GNU
/// toolchain relocatable objects. The relocation inventory mirrors these
/// rows (`Pipeline::aarch64_elf_module_unwind_relocation_rows`).
///
/// Behavior gates (all fail closed, never silent):
/// * not an ELF triple → `Ok(None)` (caller falls through to Mach-O);
/// * module has EH but a function is missing its frame layout → error (an
///   undescribed frame would stop phase-1 unwinding dead);
/// * no EH and layouts incomplete → emission without unwind metadata
///   via [`emit_target_elf_or_reject_fixups`] (layout-less API callers).
fn emit_aarch64_elf_module_with_unwind(
    target_triple: &str,
    combined_code: &[u8],
    func_offsets: &[(String, u64)],
    globals: &[ObjectGlobal],
    fixups: &crate::macho::fixup::FixupList,
    func_eh: &[ModuleFunctionEhData],
    frame_layouts: &[Option<crate::frame::FrameLayout>],
    text_align_log2: u8,
    plan: &ElfModuleSymbolPlan<'_>,
    text: ElfTextOptions<'_>,
    debug: Option<&crate::dwarf_info::DwarfSectionImage>,
) -> Result<Option<Vec<u8>>, PipelineError> {
    use crate::elf::constants::{SHF_ALLOC, SHT_PROGBITS, STT_SECTION};
    use crate::elf::{Elf64Rela, ElfWriter};

    reject_unsupported_aarch64_object_format(target_triple)?;
    if !target_triple_uses_elf(target_triple) {
        return Ok(None);
    }
    // Thread-locals are supported (`.tdata`/`.tbss` definitions, undefined
    // STT_TLS imports, LE/IE/TLSDESC text fixups). Symbol-address slots are
    // relocated with `R_AARCH64_ABS64` into the holder's own section — a
    // `.tdata` initial-value template included (the ELF analogue of the
    // Mach-O `ARM64_RELOC_UNSIGNED` path). A slot naming a thread-local was
    // refused by `validate_aarch64_object_globals`.

    let module_has_eh = func_eh.iter().any(|f| f.lsda.is_some());
    let layouts_complete = !func_eh.is_empty()
        && (0..func_eh.len()).all(|i| frame_layouts.get(i).is_some_and(|l| l.is_some()));

    if module_has_eh && !layouts_complete {
        let missing = func_offsets
            .iter()
            .enumerate()
            .find(|(i, _)| frame_layouts.get(*i).is_none_or(|l| l.is_none()))
            .map(|(_, (name, _))| name.clone())
            .unwrap_or_default();
        return Err(PipelineError::Unwind(format!(
            "ELF module carries exception-handling structure, so EVERY function \
             needs an .eh_frame FDE (a frame without one stops unwinding at \
             phase 1 — skipped cleanup Drops at run time), but no frame layout \
             was provided for `{missing}`. Thread per-function frame layouts \
             via compile_module_with_globals_and_layouts (fail-closed)."
        )));
    }
    if !layouts_complete {
        // Layout-less callers use the same data relocations without
        // inventing a frame layout we do not have.
        return emit_target_elf_or_reject_fixups(
            target_triple,
            fixups,
            combined_code,
            func_offsets,
            globals,
            text_align_log2,
            plan,
            text,
            debug,
        );
    }
    let text = plan_elf_text(
        crate::elf::ElfMachine::AArch64,
        combined_code,
        func_offsets,
        text_align_log2,
        text,
    )?;
    reject_elf_debug_with_split_text(target_triple, &text, debug)?;

    // The personality, `.gcc_except_table` layout and `.eh_frame` CFI come
    // from the helpers the relocation inventory's mirror
    // (`Pipeline::aarch64_elf_module_unwind_relocation_rows`) also reads, so
    // the two cannot lay the tables out differently; which relocation rows
    // exist is decided separately below and in the mirror.
    let personality = aarch64_elf_module_personality(func_eh)?;
    let (lsda_data, lsda_offsets) = aarch64_elf_module_lsda_table(
        target_triple,
        func_eh,
        func_offsets,
        module_has_eh,
        personality,
    )?;
    let cfi = aarch64_elf_module_cfi(func_eh, func_offsets, frame_layouts, module_has_eh)?;

    // ----- Assemble the object ----------------------------------------------
    let mut writer = ElfWriter::new(crate::elf::ElfMachine::AArch64);
    // Text first: in the legacy layout `.text` is user section 0 / shndx 1.
    let text_sections = add_elf_text_sections(&mut writer, &text)?;

    let global_symbol_rows = add_elf_global_sections(&mut writer, globals)?;
    check_aarch64_local_exec_tls_windows(&global_symbol_rows, fixups)?;

    let except_table_shndx: Option<u16> = if lsda_data.is_empty() {
        None
    } else {
        Some(writer.add_section(".gcc_except_table", &lsda_data, SHT_PROGBITS, SHF_ALLOC, 4)?)
    };
    // ENC-EHDC, the same fail-closed gate as the x86-64 emitters: the
    // independent decoder must read the full serialization (terminator
    // included, PC-begin/LSDA/personality fields still at their intent value
    // 0) back to the CIE/FDE intent before any byte is emitted. GNU objects
    // carry no per-object terminator (crtend.o owns it), so it is stripped
    // only after the check.
    let mut eh_frame_bytes = cfi.to_bytes();
    crate::dwarf_cfi_decode_check::verify_eh_frame_roundtrip(&cfi, &eh_frame_bytes)?;
    strip_verified_eh_frame_terminator(&mut eh_frame_bytes)?;
    let eh_frame_shndx =
        writer.add_section(".eh_frame", &eh_frame_bytes, SHT_PROGBITS, SHF_ALLOC, 8)?;
    let eh_frame_user_idx = (eh_frame_shndx - 1) as usize;

    // The GCC-shaped indirect personality slot: an 8-byte writable cell the
    // CIE's `DW_EH_PE_indirect|pcrel|sdata4` personality field points at,
    // holding the personality's absolute address (`R_AARCH64_ABS64`, a
    // dynamic reloc under PIE). For an external personality it is, as GCC
    // emits it, a WEAK HIDDEN definition in its own section inside a
    // `GRP_COMDAT` group signed by the slot symbol: every object's copy
    // coalesces to one cell at link, the linker keeps one copy of its bytes,
    // and the slot binds inside the output being linked. Hidden, the `.eh_frame`
    // `R_AARCH64_PREL32` naming it is a link-time constant in a shared object
    // (GNU ld and LLD refuse one against a default-visibility weak symbol,
    // which may bind externally) and the slot never enters `.dynsym`. A
    // personality this object defines `STB_LOCAL` (a module-local function or
    // data row) gets an object-local slot instead, outside any group, as GCC
    // gives a `static` personality a private constant: a shared weak slot
    // would let the linker keep another object's cell, so this object's
    // frames would run that object's personality.
    let personality_binds_locally = personality
        .map(|personality| {
            elf_symbol_binds_locally_in_object(personality, func_offsets, plan, globals)
        })
        .transpose()?
        .unwrap_or(false);
    let dw_ref_section_and_name: Option<(u16, String, Option<crate::elf::ElfSectionGroupId>)> =
        if module_has_eh {
            let personality = personality.expect("module_has_eh implies a personality");
            let name = format!(".data.DW.ref.{personality}");
            let flags = crate::elf::constants::SHF_ALLOC | crate::elf::constants::SHF_WRITE;
            let (shndx, group) = if personality_binds_locally {
                (
                    writer.add_section(&name, &[0u8; 8], SHT_PROGBITS, flags, 8)?,
                    None,
                )
            } else {
                let group = writer.add_comdat_group();
                let shndx = writer.add_group_member_section(
                    group,
                    &name,
                    &[0u8; 8],
                    SHT_PROGBITS,
                    flags,
                    8,
                    0,
                )?;
                (shndx, Some(group))
            };
            Some((shndx, format!("DW.ref.{personality}"), group))
        } else {
            None
        };

    // ----- Symbols -----------------------------------------------------------
    // Every symbol goes through the checked API and every index is resolved
    // only after the table is complete (`final_symbol_index` then freezes it),
    // so the writer's locals-first partition cannot shift a relocation index
    // whatever binding a function carries. Insertion order is the historical
    // one, so an all-global module serializes byte-identically.
    // An FDE describes this object's actual body, not a preemptible public
    // function with the same name. PREL32 against STB_GLOBAL/STV_DEFAULT is
    // invalid in a shared object; a local section plus the exact body offset
    // also preserves unwind identity if that public symbol is interposed.
    // One local STT_SECTION anchor per text section, in plan order: in the
    // legacy layout this is exactly the historical `.text` anchor.
    let text_anchors = text
        .sections
        .iter()
        .zip(&text_sections.shndx)
        .map(|(section, &shndx)| {
            writer.add_checked_symbol(crate::elf::ElfSymbol {
                name: section.name.clone(),
                section: shndx,
                value: 0,
                size: 0,
                is_global: false,
                sym_type: STT_SECTION,
                is_weak: false,
                visibility: crate::elf::constants::STV_DEFAULT,
            })
        })
        .collect::<Result<Vec<_>, _>>()?;
    let except_anchor = except_table_shndx
        .map(|shndx| {
            writer.add_checked_symbol(crate::elf::ElfSymbol {
                name: String::new(),
                section: shndx,
                value: 0,
                size: 0,
                is_global: false,
                sym_type: STT_SECTION,
                is_weak: false,
                visibility: crate::elf::constants::STV_DEFAULT,
            })
        })
        .transpose()?;

    let mut symbol_ids = Vec::new();
    // Internal/Private (STB_LOCAL) global definitions. STB_LOCAL is required
    // for correctness, not taste: every module carries its own copy of
    // content-hashed internals (`str.<hash>` / `vtable.<hash>`), and
    // STB_GLOBAL copies collide across objects at static link.
    for row in global_symbol_rows.iter().filter(|row| !row.is_external) {
        let id = add_elf_global_row_symbol(&mut writer, row)?;
        symbol_ids.push((row.name.clone(), id));
    }
    symbol_ids.extend(add_elf_function_symbols(
        &mut writer,
        &text,
        &text_sections,
        plan,
    )?);
    for row in global_symbol_rows.iter().filter(|row| row.is_external) {
        let id = add_elf_global_row_symbol(&mut writer, row)?;
        symbol_ids.push((row.name.clone(), id));
    }
    let mut known_names: BTreeSet<String> =
        symbol_ids.iter().map(|(name, _)| name.clone()).collect();

    // Thread-local IMPORTS: undefined STT_TLS symbols (a TLS relocation
    // against a non-TLS undefined symbol is a link-time kind mismatch), added
    // BEFORE the generic undefined pass so the TPREL fixups bind to these.
    for name in elf_tls_import_names(globals) {
        if known_names.insert(name.clone()) {
            let symbol = elf_undefined_symbol(&name, crate::elf::constants::STT_TLS, plan);
            let id = writer.add_checked_symbol(symbol)?;
            symbol_ids.push((name, id));
        }
    }

    check_aarch64_intra_object_relocation_windows(
        target_triple,
        combined_code,
        func_offsets,
        fixups,
    )?;

    // Undefined externs referenced by text fixups, data slots and the CIE
    // personality, then the hidden thread-local anchors, exactly as the
    // no-unwind emitter adds them.
    let tls_anchors = add_aarch64_elf_reference_symbols(
        &mut writer,
        target_triple,
        combined_code,
        func_offsets,
        globals,
        &global_symbol_rows,
        fixups,
        plan,
        &known_names,
        personality,
        "unwind-enabled AArch64 ELF",
        &mut symbol_ids,
    )?;

    // The `DW.ref.<personality>` slot symbol: weak and hidden, and the
    // signature of the slot's COMDAT group, for an external personality;
    // `STB_LOCAL` for one this object defines locally.
    let dw_ref_id = dw_ref_section_and_name
        .as_ref()
        .map(|(shndx, name, group)| -> Result<_, PipelineError> {
            let id = writer.add_checked_symbol(crate::elf::ElfSymbol {
                name: name.clone(),
                section: *shndx,
                value: 0,
                size: 8,
                is_global: !personality_binds_locally,
                sym_type: crate::elf::constants::STT_OBJECT,
                is_weak: !personality_binds_locally,
                visibility: if personality_binds_locally {
                    crate::elf::constants::STV_DEFAULT
                } else {
                    crate::elf::constants::STV_HIDDEN
                },
            })?;
            if let Some(group) = group {
                writer.bind_comdat_group_signature(*group, id)?;
            }
            Ok(id)
        })
        .transpose()?;

    // DWARF sections and their anchors go last, reusing the FDE `.text`
    // anchor (the only text anchor in the single-`.text` layout DWARF
    // requires), so every earlier section and symbol index is unchanged.
    let debug = attach_elf_debug_sections(
        &mut writer,
        debug,
        &text,
        &text_sections,
        text_anchors.first().copied(),
    )?;

    // The table is complete: resolve (and freeze) every index.
    let text_anchor_indices = text_anchors
        .iter()
        .map(|&id| writer.final_symbol_index(id))
        .collect::<Result<Vec<_>, _>>()?;
    let except_anchor_index = except_anchor
        .map(|id| writer.final_symbol_index(id))
        .transpose()?;
    let dw_ref_symbol = dw_ref_id
        .map(|id| writer.final_symbol_index(id))
        .transpose()?;
    let symbol_indices = final_elf_symbol_indices(&mut writer, &symbol_ids)?;

    // ----- Relocations --------------------------------------------------------
    // `.text`: the branch/page fixups, exactly as the no-unwind emitter.
    add_aarch64_elf_text_relocations(
        &mut writer,
        target_triple,
        combined_code,
        fixups,
        &text,
        &text_sections,
        &symbol_indices,
        &tls_anchors,
    )?;

    add_aarch64_elf_global_relocations(&mut writer, globals, &global_symbol_rows, &symbol_indices)?;

    // `.eh_frame`: PREL32 pc-begin per FDE (local `.text` + body offset),
    // PREL32 LSDA per FDE (against the `.gcc_except_table` anchor + offset),
    // PREL32 CIE personality (against the `DW.ref.<personality>` slot).
    //
    // ORDER MATTERS: GNU ld's `.eh_frame` parser walks the section once with
    // a monotonically advancing relocation cursor, so `.rela.eh_frame` MUST
    // be sorted by ascending `r_offset` ("error in <obj>(.eh_frame); no
    // .eh_frame_hdr table will be created" otherwise — and without the
    // `PT_GNU_EH_FRAME` search table the unwinder finds no FDEs at run
    // time). Section layout is CIE (personality field) then FDEs in add
    // order, and within an FDE pc-begin precedes the LSDA field, so emitting
    // personality → per-FDE (pc-begin, LSDA) yields ascending offsets.
    if module_has_eh {
        if let Some(personality_offset) = cfi.cie_personality_relocation_offset() {
            let dw_ref_symbol = dw_ref_symbol.ok_or_else(|| {
                PipelineError::Unwind(
                    "ELF module unwind emission: zPLR CIE without a DW.ref personality \
                     slot (fail-closed)"
                        .to_string(),
                )
            })?;
            writer.add_relocation(
                eh_frame_user_idx,
                Elf64Rela::aarch64(
                    personality_offset as u64,
                    dw_ref_symbol,
                    crate::elf::AArch64RelocType::Prel32,
                    0,
                ),
            );
        } else {
            return Err(PipelineError::Unwind(
                "ELF module unwind emission: EH module CIE has no personality field \
                 (fail-closed)"
                    .to_string(),
            ));
        }
    }
    let pc_begin_offsets = cfi.fde_pc_begin_relocation_offsets();
    let lsda_field_offsets = cfi.fde_lsda_relocation_offsets();
    if module_has_eh && lsda_field_offsets.len() != pc_begin_offsets.len() {
        return Err(PipelineError::Unwind(format!(
            "ELF module unwind emission: {} FDEs but {} LSDA fields under a zPLR CIE \
             (fail-closed)",
            pc_begin_offsets.len(),
            lsda_field_offsets.len()
        )));
    }
    for (i, pc_begin_offset) in pc_begin_offsets.into_iter().enumerate() {
        // pc-begin = the local anchor of the function's own text section plus
        // the body's offset in it.
        let placed = &text.functions[i];
        let function_offset = i64::try_from(placed.offset).map_err(|_| {
            PipelineError::Unwind(format!(
                "ELF FDE for `{}` has an unrepresentable text relocation addend {}",
                placed.name, placed.offset,
            ))
        })?;
        writer.add_relocation(
            eh_frame_user_idx,
            Elf64Rela::aarch64(
                pc_begin_offset as u64,
                text_anchor_indices[placed.section],
                crate::elf::AArch64RelocType::Prel32,
                function_offset,
            ),
        );
        if module_has_eh {
            let anchor = except_anchor_index.ok_or_else(|| {
                PipelineError::Unwind(
                    "ELF module unwind emission: EH module produced no .gcc_except_table \
                     anchor symbol (fail-closed)"
                        .to_string(),
                )
            })?;
            let lsda_offset = lsda_offsets[i].ok_or_else(|| {
                PipelineError::Unwind(format!(
                    "ELF module unwind emission: FDE for `{}` has an LSDA slot but no \
                     LSDA bytes were laid out (fail-closed)",
                    func_offsets[i].0
                ))
            })?;
            writer.add_relocation(
                eh_frame_user_idx,
                Elf64Rela::aarch64(
                    lsda_field_offsets[i] as u64,
                    anchor,
                    crate::elf::AArch64RelocType::Prel32,
                    lsda_offset,
                ),
            );
        }
    }

    // The DW.ref slot's own content relocation: the 8-byte cell holds the
    // personality's absolute address (dynamic RELATIVE reloc under PIE).
    if let Some((dw_ref_shndx, _, _)) = &dw_ref_section_and_name {
        let personality_name = personality.expect("dw_ref implies personality");
        let personality_symbol = symbol_indices
            .get(personality_name)
            .copied()
            .expect("personality symbol added above");
        writer.add_relocation(
            (*dw_ref_shndx - 1) as usize,
            Elf64Rela::aarch64(
                0,
                personality_symbol,
                crate::elf::AArch64RelocType::Abs64,
                0,
            ),
        );
    }
    relocate_elf_debug_sections(&mut writer, debug.as_ref())?;

    finish_elf_object(writer).map(Some)
}

/// The one personality routine an AArch64 ELF module's shared zPLR CIE names,
/// or `None` for a module without an EH function.
///
/// Every LSDA-carrying function's personality is canonicalized; more than one
/// distinct routine is refused: the ELF emitter has one shared CIE and one
/// `DW.ref` slot, while the Mach-O planner emits one CIE group per
/// personality. Shared by [`emit_aarch64_elf_module_with_unwind`] and the
/// relocation inventory's mirror.
fn aarch64_elf_module_personality(
    func_eh: &[ModuleFunctionEhData],
) -> Result<Option<&str>, PipelineError> {
    let mut personalities: Vec<&str> = func_eh
        .iter()
        .filter_map(|f| f.lsda.as_ref().map(FunctionLsda::canonical_personality))
        .collect();
    personalities.sort_unstable();
    personalities.dedup();
    match personalities.as_slice() {
        [] => Ok(None),
        [single] => Ok(Some(*single)),
        multiple => Err(PipelineError::Unwind(format!(
            "ELF module unwind emission supports one personality routine per \
             module (single shared CIE); found {multiple:?}; per-personality CIEs \
             are emitted for Mach-O only (fail-closed)"
        ))),
    }
}

/// The AArch64 ELF module's `.gcc_except_table` bytes and each function's
/// LSDA offset in it (`None` for every function of a module without EH).
///
/// An EH module gives every function an LSDA, because every FDE under its
/// zPLR CIE carries an LSDA field: the function's own LSDA, or a synthetic
/// ALL-FILLER one (one `landing_pad == 0` region covering `[0, code_len)`)
/// that can only tell the personality to keep unwinding. Each LSDA starts
/// 4-byte aligned. A typed catch is refused by name: its TType slot needs a
/// `DW.ref.<typeinfo>` slot plus a `PREL32` into `.gcc_except_table`, which
/// this emitter does not write, and an unrelocated slot would read as a
/// catch-all. Shared by [`emit_aarch64_elf_module_with_unwind`] and the
/// relocation inventory's mirror.
fn aarch64_elf_module_lsda_table(
    target_triple: &str,
    func_eh: &[ModuleFunctionEhData],
    func_offsets: &[(String, u64)],
    module_has_eh: bool,
    personality: Option<&str>,
) -> Result<(Vec<u8>, Vec<Option<i64>>), PipelineError> {
    use crate::exception_handling::generate_lsda_from_pads;

    let mut lsda_data: Vec<u8> = Vec::new();
    let mut lsda_offsets: Vec<Option<i64>> = vec![None; func_eh.len()];
    if module_has_eh {
        for (i, f) in func_eh.iter().enumerate() {
            let bytes: Vec<u8> = match &f.lsda {
                Some(lsda) => {
                    if let Some(reloc) = lsda.image.typeinfo_relocations.first() {
                        return Err(PipelineError::TargetObjectUnsupported {
                            target: target_triple.to_string(),
                            format: "ELF".to_string(),
                            reason: format!(
                                "function `{}` catches a typed exception (typeinfo `{}`), but \
                                 the AArch64 ELF emitter carries no `.gcc_except_table` \
                                 typeinfo relocation; typed catches are Mach-O-only \
                                 [TCG-EH-TTYPE] (fail-closed)",
                                func_offsets[i].0, reloc.symbol
                            ),
                        });
                    }
                    lsda.image.bytes.clone()
                }
                None => {
                    let personality = personality.ok_or_else(|| {
                        PipelineError::Unwind(format!(
                            "synthetic filler LSDA for ELF module function {} needs a \
                             personality routine but the module has none (fail-closed)",
                            func_offsets[i].0
                        ))
                    })?;
                    generate_lsda_from_pads(personality, &[], &[(0, f.code_len, 0)]).map_err(
                        |error| {
                            PipelineError::Unwind(format!(
                                "synthetic filler LSDA for ELF module function {} is \
                                 invalid: {error}",
                                func_offsets[i].0
                            ))
                        },
                    )?
                }
            };
            while !lsda_data.len().is_multiple_of(4) {
                lsda_data.push(0);
            }
            lsda_offsets[i] = Some(checked_aarch64_object_u32(
                &func_offsets[i].0,
                "ELF LSDA section offset",
                lsda_data.len(),
            )? as i64);
            lsda_data.extend_from_slice(&bytes);
        }
    }
    Ok((lsda_data, lsda_offsets))
}

/// The AArch64 ELF module's `.eh_frame` CFI: one CIE (zPLR for an EH module,
/// zR otherwise) and one FDE per function, in function order.
///
/// A frame-based function gets the prologue-describing CFI
/// ([`crate::dwarf_cfi::DwarfFde::from_layout`]); a zero-frame leaf gets an
/// EMPTY-instruction FDE, since the CIE's initial CFA = SP + 0 rule is exact
/// for its whole body and X30 (unmodified) holds the return address. Under a
/// zPLR CIE every FDE carries an LSDA field. A missing frame layout is
/// refused. Shared by [`emit_aarch64_elf_module_with_unwind`] and the
/// relocation inventory's mirror.
fn aarch64_elf_module_cfi(
    func_eh: &[ModuleFunctionEhData],
    func_offsets: &[(String, u64)],
    frame_layouts: &[Option<crate::frame::FrameLayout>],
    module_has_eh: bool,
) -> Result<crate::dwarf_cfi::DwarfCfiSection, PipelineError> {
    use crate::dwarf_cfi::{DwarfCfiSection, DwarfFde};

    let mut cfi = if module_has_eh {
        DwarfCfiSection::new_aarch64_elf_with_eh()
    } else {
        DwarfCfiSection::new_aarch64_elf()
    };
    for (i, f) in func_eh.iter().enumerate() {
        let layout = frame_layouts
            .get(i)
            .and_then(Option::as_ref)
            .ok_or_else(|| {
                PipelineError::Unwind(format!(
                    "ELF module unwind emission: no frame layout for `{}`, so its FDE \
                     cannot be built (fail-closed)",
                    func_offsets
                        .get(i)
                        .map_or("<unknown>", |(name, _)| name.as_str())
                ))
            })?;
        let mut fde = if layout.uses_frame_pointer {
            DwarfFde::from_layout(layout, 0, f.code_len, 0)
        } else {
            DwarfFde {
                function_offset: 0,
                function_length: f.code_len,
                symbol_index: 0,
                instructions: Vec::new(),
                lsda_pointer: None,
            }
        };
        if module_has_eh {
            fde = fde.with_lsda();
        }
        cfi.add_fde(fde);
    }
    Ok(cfi)
}

/// Remove the 4-byte zero terminator that [`crate::dwarf_cfi::DwarfCfiSection::to_bytes`]
/// appends, after the decode-check has verified it. Object files must not
/// carry it: GNU `ld` owns the final terminator (crtend.o) and ld64 rejects a
/// zero-length record as "empty CIE".
///
/// Shared by the AArch64 ELF and x86-64 ELF module unwind emitters.
pub(crate) fn strip_verified_eh_frame_terminator(
    eh_frame: &mut Vec<u8>,
) -> Result<(), PipelineError> {
    if eh_frame.len() < 4 || eh_frame[eh_frame.len() - 4..] != [0, 0, 0, 0] {
        return Err(PipelineError::EhFrameDecodeCheck(
            crate::dwarf_cfi_decode_check::EhFrameDecodeError {
                message: "verified eh_frame serialization does not end with its zero terminator"
                    .to_string(),
            },
        ));
    }
    eh_frame.truncate(eh_frame.len() - 4);
    Ok(())
}

/// The instruction list the module encoder emits for `func`.
///
/// [`encode_module_function_with_fixups`] drops a redundant copy in front of
/// an `RBIT` return (`rbit_return_prefix_copy_cleaned`). Every DWARF byte
/// offset of a module function (line rows, parameter and variable ranges) is
/// counted over this list, so none can drift past the dropped instruction or
/// beyond the function's encoded bytes. A range bounded by the dropped copy has
/// no layout position and is omitted.
fn module_function_as_encoded(func: &IrMachFunction) -> std::borrow::Cow<'_, IrMachFunction> {
    match rbit_return_prefix_copy_cleaned(func) {
        Some(cleaned) => std::borrow::Cow::Owned(cleaned),
        None => std::borrow::Cow::Borrowed(func),
    }
}

/// What a whole-module DWARF description says about each function's
/// parameters and variables.
#[derive(Debug, Clone, Copy)]
enum ModuleDebugVariables<'a> {
    /// Subprograms and line rows only: the legacy module entry points receive
    /// no register-debug provenance and describe no parameter or variable.
    LinesOnly,
    /// Parameters and variables too, as a single-function object describes
    /// them, from each function's register-debug provenance (1:1 with the
    /// functions; `None` for a function prepared without one).
    WithProvenance(&'a [Option<&'a trust_cg_ir::ProvenanceMap>]),
}

/// Move one function's parameter and variable locations, built over its own
/// bytes from offset 0, onto its text offset `low_pc` in a whole-module
/// object. Every location-list range moves; a single-expression location
/// carries no address.
///
/// DWARF emission refuses a range that does not lie inside its function's
/// `[low_pc, low_pc + size)`
/// ([`crate::dwarf_info::DwarfEmitError::AddressOutOfFunction`]). A range
/// left function-relative in a function placed past offset 0 is therefore
/// refused only when it starts below that function's `low_pc`, as every
/// entry-range parameter location does. An unshifted range that happens to
/// land inside the function's code is NOT refused by emission: it would be
/// described `low_pc` bytes early, and only the tests' `llvm-objdump`
/// location checker and the gdb module leg catch that.
fn rebase_function_debug_locations(
    function: &str,
    params: &mut [crate::dwarf_info::FunctionParam],
    variables: &mut [crate::dwarf_info::VariableDebugInfo],
    low_pc: u64,
) -> Result<(), PipelineError> {
    let locations = params
        .iter_mut()
        .map(|param| &mut param.location)
        .chain(variables.iter_mut().map(|var| &mut var.location));
    for location in locations {
        let crate::dwarf_info::VariableLocation::LocationList(entries) = location else {
            continue;
        };
        for entry in entries {
            entry.low_pc = entry.low_pc.checked_add(low_pc).ok_or_else(|| {
                aarch64_object_field_too_large(
                    function,
                    "DWARF location-list address",
                    u128::from(entry.low_pc) + u128::from(low_pc),
                    u128::from(u64::MAX),
                )
            })?;
        }
    }
    Ok(())
}

impl Pipeline {
    /// DWARF description of a whole-module object: one `DW_TAG_subprogram`
    /// per function at its text offset, with line rows from each
    /// instruction's own `source_loc` shifted by that offset. With
    /// [`ModuleDebugVariables::WithProvenance`] each subprogram also carries
    /// the parameters and variables [`Self::function_debug_locations`]
    /// describes for a single-function object, built over the instruction
    /// list the module encoder emitted and rebased onto the function's text
    /// offset. Mach-O and ELF module objects share it; `linkage_prefix` is the
    /// object-format symbol prefix (`_` for Mach-O, empty for ELF).
    fn module_debug_info(
        &self,
        functions: &[IrMachFunction],
        func_offsets: &[(String, u64)],
        func_eh: &[ModuleFunctionEhData],
        frame_layouts: &[Option<crate::frame::FrameLayout>],
        linkage_prefix: &str,
        variables: ModuleDebugVariables<'_>,
    ) -> Result<crate::dwarf_info::DwarfDebugInfo, PipelineError> {
        use crate::dwarf_info::{DwarfDebugInfo, FunctionDebugInfo, SourceLanguage};

        if func_offsets.len() != functions.len() || func_eh.len() != functions.len() {
            return Err(PipelineError::DebugInfoInput(format!(
                "module DWARF emission received {} function(s), {} text offset(s) and {} \
                 code length(s); they must be 1:1 (fail-closed)",
                functions.len(),
                func_offsets.len(),
                func_eh.len()
            )));
        }
        if let ModuleDebugVariables::WithProvenance(provenance) = variables
            && provenance.len() != functions.len()
        {
            return Err(PipelineError::DebugInfoInput(format!(
                "module DWARF emission received {} debug provenance slot(s) for {} \
                 function(s); they must be 1:1 (fail-closed)",
                provenance.len(),
                functions.len()
            )));
        }

        // Compilation-unit source file: the first function carrying a real
        // stamped path (module `files` table via adapter debug_meta); the
        // adapter always leaves a synthetic `<module>.rs` fallback.
        let cu_source_file = functions
            .iter()
            .find_map(|f| f.debug_meta.source_file.clone())
            .unwrap_or_else(|| "unknown.rs".to_string());

        let mut debug_info = DwarfDebugInfo::new(&cu_source_file, ".", SourceLanguage::Rust);
        debug_info.add_standard_types();

        for (index, ((func, (name, low_pc)), eh)) in
            functions.iter().zip(func_offsets).zip(func_eh).enumerate()
        {
            if *name != func.name {
                return Err(PipelineError::DebugInfoInput(format!(
                    "module DWARF emission found text offset for `{name}` in the slot of `{}` \
                     (fail-closed)",
                    func.name
                )));
            }
            let encoded = module_function_as_encoded(func);
            let mut line_entries = build_source_line_entries(&encoded, None);
            for entry in &mut line_entries {
                entry.address = entry.address.checked_add(*low_pc).ok_or_else(|| {
                    aarch64_object_field_too_large(
                        &func.name,
                        "DWARF line-row address",
                        u128::from(entry.address) + u128::from(*low_pc),
                        u128::from(u64::MAX),
                    )
                })?;
            }
            let (params, variables) = match variables {
                ModuleDebugVariables::LinesOnly => (vec![], vec![]),
                ModuleDebugVariables::WithProvenance(provenance) => {
                    let (mut params, mut variables) = self.function_debug_locations(
                        &encoded,
                        eh.code_len,
                        frame_layouts.get(index).and_then(Option::as_ref),
                        provenance[index],
                    )?;
                    rebase_function_debug_locations(
                        &func.name,
                        &mut params,
                        &mut variables,
                        *low_pc,
                    )?;
                    (params, variables)
                }
            };
            let decl_line = if func.debug_meta.decl_line > 0 {
                func.debug_meta.decl_line as u16
            } else {
                1
            };
            // A function with line rows reports them in its own source file:
            // a whole-module object can hold functions of several files (a
            // rustc codegen unit spans every module of a crate). A function
            // without rows keeps file 1, as before.
            let decl_file = match func.debug_meta.source_file.as_deref() {
                Some(file) if !line_entries.is_empty() => debug_info.file_index(file)?,
                _ => 1,
            };
            let (name, linkage_name) = subprogram_names(
                &func.debug_meta,
                &func.name,
                format!("{linkage_prefix}{}", func.name),
            );
            debug_info.add_function(FunctionDebugInfo {
                name,
                linkage_name,
                low_pc: *low_pc,
                size: eh.code_len,
                params,
                variables,
                scopes: vec![],
                line_entries,
                decl_file,
                decl_line,
            });
        }
        Ok(debug_info)
    }
}

/// The DWARF subprogram's `DW_AT_name` and the linkage name recorded beside
/// it ([`FunctionDebugInfo::linkage_name`]).
///
/// A function whose producer named it (`FunctionDebugMeta::display_name`,
/// from trust-ir `Function::display_path`) is described by that name, and its
/// object symbol is not recorded: the symbol may be a producer-private
/// spelling (the rustc bridge's CGU-local `__trust_cg_private.*` names),
/// which a debugger would otherwise show in place of the source name. Every
/// other function keeps its symbol as the name and `linkage_name` beside it.
fn subprogram_names(
    debug_meta: &trust_cg_ir::function::FunctionDebugMeta,
    symbol: &str,
    linkage_name: String,
) -> (String, Option<String>) {
    match &debug_meta.display_name {
        Some(display_name) => (display_name.clone(), None),
        None => (symbol.to_string(), Some(linkage_name)),
    }
}

#[allow(clippy::too_many_arguments)]
fn emit_single_function_target_elf_if_needed(
    target_triple: &str,
    func_name: &str,
    code: &[u8],
    fixups: &crate::macho::fixup::FixupList,
    lsda: Option<(&crate::exception_handling::LsdaImage, &str)>,
    frame_layout: Option<&crate::frame::FrameLayout>,
    text_align_log2: u8,
    function_sections: bool,
    debug: Option<&crate::dwarf_info::DwarfSectionImage>,
) -> Result<Option<Vec<u8>>, PipelineError> {
    reject_unsupported_aarch64_object_format(target_triple)?;
    if !target_triple_uses_elf(target_triple) {
        return Ok(None);
    }

    let code_len = checked_aarch64_object_u32(func_name, "encoded code length", code.len())?;
    let func_offsets = [(func_name.to_string(), 0)];
    let func_eh = [ModuleFunctionEhData {
        code_len,
        lsda: lsda.map(|(image, personality)| FunctionLsda {
            image: image.clone(),
            personality: personality.to_string(),
        }),
    }];
    let frame_layouts = [frame_layout.cloned()];
    let facts = [ElfFunctionFacts {
        code_len: u64::from(code_len),
        align_log2: text_align_log2,
        comdat: false,
        section: None,
    }];
    emit_aarch64_elf_module_with_unwind(
        target_triple,
        code,
        &func_offsets,
        &[],
        fixups,
        &func_eh,
        &frame_layouts,
        text_align_log2,
        &ElfModuleSymbolPlan::legacy(),
        ElfTextOptions {
            function_sections,
            functions: &facts,
        },
        debug,
    )
}

fn add_single_function_symbol_ids_for_fixups(
    writer: &mut crate::macho::MachOWriter,
    func_name: &str,
    function_symbol_id: crate::macho::SymbolId,
    fixups: &crate::macho::fixup::FixupList,
    // Undefined externals already registered by the caller (typed-catch
    // typeinfo symbols), keyed by Mach-O name, so a fixup naming one of them
    // reuses that symbol instead of minting a duplicate nlist entry.
    preregistered: &HashMap<String, crate::macho::SymbolId>,
) -> Result<MachOSymbolIdMaps, PipelineError> {
    use crate::macho::FixupTarget;

    let mut ordinary_by_abi_name = HashMap::new();
    let mut exact_function_by_raw_name = HashMap::new();
    let mut known_abi_names = BTreeSet::new();
    let symbol_name = macho_symbol_name(func_name);
    ordinary_by_abi_name.insert(symbol_name.clone(), function_symbol_id);
    exact_function_by_raw_name.insert(func_name.to_string(), function_symbol_id);
    known_abi_names.insert(symbol_name);
    for (abi_name, symbol_id) in preregistered {
        ordinary_by_abi_name.insert(abi_name.clone(), *symbol_id);
        known_abi_names.insert(abi_name.clone());
    }

    let mut undefined_names = BTreeSet::new();
    for fixup in fixups.iter() {
        match &fixup.target {
            FixupTarget::NamedSymbol(name) => {
                let symbol_name = macho_symbol_name(name);
                if !known_abi_names.contains(&symbol_name) {
                    undefined_names.insert(name.clone());
                }
            }
            FixupTarget::ExactNamedSymbol(name) if name != func_name => {
                return Err(PipelineError::ObjectEmission(format!(
                    "single-function object cannot resolve exact module call to `{name}` from `{func_name}`"
                )));
            }
            _ => {}
        }
    }

    for name in undefined_names {
        let symbol_name = macho_symbol_name(&name);
        let symbol_id = writer.add_symbol(&symbol_name, 0, 0, true)?;
        ordinary_by_abi_name.insert(symbol_name, symbol_id);
    }

    Ok(MachOSymbolIdMaps {
        ordinary_by_abi_name,
        exact_function_by_raw_name,
    })
}

fn final_macho_symbol_index(
    writer: &mut crate::macho::MachOWriter,
    symbol_id: crate::macho::SymbolId,
    context: &str,
) -> Result<u32, PipelineError> {
    writer.final_symbol_index(symbol_id)?.ok_or_else(|| {
        PipelineError::ObjectEmission(format!(
            "Mach-O symbol id {symbol_id} missing before {context}"
        ))
    })
}

// ---------------------------------------------------------------------------
// LSDA generation from EH metadata
// ---------------------------------------------------------------------------

/// Resolve the post-layout byte offsets in a function's exception-handling
/// metadata, using the block byte offsets and total code length from encoding.
///
/// ISel forwards the EH structure (`Invoke` / `LandingPad`) and exact selected
/// call identities into `MachFunction.eh_metadata`, but the byte fields
/// (`LandingPadEntry.offset`, `EhCallSiteEntry.start_offset` / `length`) are
/// left at 0 because the layout is not yet known. This pass fills them once
/// block layout + branch resolution + encoding have produced `block_offsets`:
///
/// * a landing pad's `offset` becomes its exact block byte offset;
/// * a modern Invoke record binds its exact selected call ID; a legacy
///   block-only record still requires exactly one eligible `Bl`/`BL`/`Blr`/`BLR`;
/// * the protected range is exactly that fixed-width instruction's four bytes;
/// * every other byte gets a disjoint `landing_pad == None` filler entry.
///
/// Must run AFTER `resolve_branches` + encoding and BEFORE
/// `generate_lsda_for_function`. Missing, stale, ambiguous, overlapping, or
/// sentinel-colliding metadata fails closed instead of silently widening a
/// handler to unrelated instructions.
///
/// This is [`resolve_eh_offsets_with_propagation`] under
/// [`EhPropagation::Filler`].
pub fn resolve_eh_offsets(
    func: &mut IrMachFunction,
    block_offsets: &HashMap<BlockId, u32>,
    code_len: usize,
) -> Result<(), PipelineError> {
    resolve_eh_offsets_with_propagation(func, block_offsets, code_len, &EhPropagation::Filler)
}

/// How an AArch64 LSDA call-site table treats the bytes outside the explicit
/// `Invoke` handler ranges of an exception-handling function.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub enum EhPropagation {
    /// Cover every other byte with a `landing_pad == None` filler entry, so
    /// an exception searching through any call of this frame continues to
    /// the caller (and a cleanup pad's `_Unwind_Resume` re-consult does too).
    #[default]
    Filler,
    /// The function is a frame no exception may propagate out of
    /// (`CompilerConfig::eh_frames_cannot_unwind`): LLVM's `nounwind`
    /// function. Its table applies the REGION RULE of LLVM's
    /// `EHStreamer::computeCallSiteTable` for such a function to THIS
    /// backend's instruction stream; it is not a handlers-only table. The
    /// explicit handler ranges are listed, and so is a `landing_pad == None`
    /// ("keep unwinding") entry for each REGION outside them (function start
    /// to the first handler, between consecutive handlers, the last handler
    /// to the end) that contains a call which may unwind by LLVM's rule
    /// ([`aarch64_call_may_unwind`]): any indirect call, and any direct call
    /// whose callee symbol is not in `nounwind_callees`. A region whose every
    /// call names a `nounwind` callee is left out, so the Rust personality
    /// reports a phase-one search reaching it as `_URC_FATAL_PHASE1_ERROR`
    /// instead of continuing to an outer handler.
    ///
    /// The rule is LLVM's; the calls a region holds are not, so this does NOT
    /// reproduce LLVM's coverage in general. Where LLVM's region holds a call
    /// that may unwind and this backend's does not, the region is covered under
    /// LLVM and a gap here: a search LLVM continues fails phase one here, so
    /// the process aborts earlier, never later. Measured on a 56-program
    /// variant corpus at O0-O3 against LLVM (1076 runs), relative to the
    /// full-coverage filler this policy replaces: 22 programs (186 runs) newly
    /// diverge, every one aborting in phase one where LLVM reaches the
    /// termination pad (123 runs) or unwinds through this frame (63 runs: 21
    /// caught, 21 uncaught, 21 nested-cleanup terminations). The causes: LLVM
    /// inlines a helper that holds an indirect call where this backend calls
    /// the helper directly (10 programs, 81 runs); LLVM's cold, noreturn or
    /// branch block placement puts the call in another region (5, 51); LLVM
    /// calls `memcpy` / `memcmp` for a copy or compare this backend expands
    /// inline (6, 36); LLVM turns self-recursion into a loop where this backend
    /// keeps the self-call (1, 18). The same corpus has 27 programs (234 runs)
    /// where the filler diverged and this table matches, 75 of those runs ones
    /// where the filler kept unwinding through this frame (25 of them caught)
    /// while LLVM aborts in phase one, and 8 programs (78 runs) that diverge
    /// under both policies alike: in 66 runs LLVM devirtualises an indirect
    /// call into a direct `nounwind` one, or lays a loop, cold or tail region
    /// out differently, so LLVM's region is the gap and this backend's search
    /// continues to a termination pad (an abort with the "cannot unwind" hook)
    /// where LLVM fails phase one; in 12 only an unrelated panic message
    /// differs. Closing the class needs either a model of LLVM's inlining,
    /// libcall and block-placement decisions, or a per-call unwind contract
    /// carried in TrustIR (the v53 `Inst::CallCannotUnwind` /
    /// `Inst::CallIndirectCannotUnwind` boundary, refused by every lane today)
    /// whose own boundary the backend enforces at each call site instead of
    /// deriving coverage from a region's calls.
    ///
    /// A call the frontend or this backend creates itself, with no MIR call
    /// behind it, is recorded per callee and per level as LLVM's table has
    /// the same program point: in `nounwind_callees` wherever LLVM may inline,
    /// expand, fold, narrow or delete the operation, so its region is a gap,
    /// and left out only where LLVM certainly emits a libcall for it (an
    /// `ExternalSymbol`, which `callToNoUnwindFunction` treats as may-unwind),
    /// so it is covered. The bridge records its `__trustcg_*` helpers, its
    /// memory libcalls and its array fills by their measured size rules
    /// (`rustc_codegen_trust_cg`'s `trustcg_helper_call_is_nounwind` and the
    /// per-site rules beside it), and the libm and compiler-rt routines,
    /// including the ones this backend calls for a 128-bit division or
    /// remainder, a float remainder and a 128-bit integer <-> float conversion
    /// (`rustc_codegen_trust_cg`'s `created_call_unwind`): covered at O0
    /// unless nothing reads the result (LLVM deletes such an operation even at
    /// O0), and above O0 only where every operand comes from a `black_box` and
    /// the result reaches one within the same invoke-free stretch, so that
    /// LLVM can neither fold, expand, narrow nor delete the call nor move it
    /// to another region; a byte-uniform fill above 512 bytes stays covered
    /// above O0 only when its address reaches a `black_box` right after it.
    /// [`backend_expansion_nounwind_callees`] adds this backend's own
    /// `__divti3` / `__udivti3` (an `i128` checked multiply) and
    /// `__sincos_stret`. A thread-local access's resolver call (the Darwin TLV
    /// thunk, the ELF TLS descriptor call) never unwinds and is a `nounwind`
    /// call at every level ([`aarch64_call_may_unwind`]). The bridge also
    /// lowers a call through a `fn` pointer or a vtable whose target the MIR
    /// states as the direct call LLVM makes, and gives a frame with no foreign
    /// edge of its own the table LLVM's gets by inlining a callee that holds a
    /// terminate pad (that call becomes an invoke with a terminate pad). No
    /// call of such a frame becomes a tail call either: a tail branch would
    /// leave the frame before the callee runs, and its table would never be
    /// consulted (`OptimizationPipeline::without_tail_calls`). Where LLVM's
    /// choice turns on what neither backend can see, the rules record the
    /// callee, so the search fails phase one here at most earlier than
    /// LLVM's. The measured state, the earlier aborts this costs and the
    /// shapes still open (a `fn` pointer or trait object a helper returns,
    /// resolved by LLVM's inlining; a terminate pad LLVM inlines from a closure
    /// or a wrapper returning an aggregate) are in docs/decision-record.md
    /// OD-58, "Remaining work".
    ///
    /// Not modeled: LLVM also extends an invoke's entry across a following
    /// region without such a call when the next invoke has the same landing
    /// pad and action. rustc gives every foreign call in a nounwind body its
    /// own landing pad, so LLVM never merges there (measured on the stage-1
    /// trustc: two invokes around a direct `nounwind` call keep two entries
    /// and the gap); this table never merges either.
    ///
    /// Modeled only under `rust_eh_personality`, for a function with at
    /// least one explicit handler, no `_Unwind_Resume` and no tail exit;
    /// anything else is refused.
    NounwindFrame {
        /// Callee symbols the frontend states cannot unwind: the callees
        /// LLVM would treat as `nounwind` (rustc gives a declaration that
        /// attribute exactly when its `FnAbi::can_unwind` is false; LLVM
        /// infers it for a library function such as `memcmp` only above
        /// O0). Every other direct callee is treated as one that may unwind.
        nounwind_callees: Arc<BTreeSet<String>>,
    },
}

/// Whether the encoded AArch64 instruction `inst` is a call that may unwind
/// by LLVM's call-site rule (`EHStreamer::callToNoUnwindFunction`), or `None`
/// when it is not a call.
///
/// LLVM decides from the callee's DECLARATION, never from the call site: a
/// direct call cannot unwind only when its single function operand is
/// declared `nounwind` (here: named in `nounwind_callees`). Every indirect
/// call may unwind, a `nounwind` call site included, because an indirect call
/// has no callee declaration to read. A direct call with no symbol operand or
/// with more than one is treated as one that may unwind, as LLVM treats a
/// call with more than one function operand. A tail call follows the same
/// rule (LLVM's `TCRETURN` is a call).
///
/// A thread-local access's resolver call is the exception: the Darwin TLV
/// descriptor's thunk (`Blr` stamped `CANNOT_UNWIND_CALL` by instruction
/// selection) and the ELF TLS descriptor call (`TlsDescCall` /
/// `BlrTlsdesc`) are treated as calls that cannot unwind at every level. The
/// routines never raise. LLVM's own TLV call is an indirect `BLR` too, which
/// its table treats as may-unwind, but above O0 LLVM folds a read of a
/// thread-local nothing writes (`#[thread_local] static mut T: u64 = 11`,
/// read after a callback: measured at O1-O3) and deletes a read nothing uses,
/// leaving no call; this backend cannot see either. Treating the call as
/// `nounwind` makes such a region a gap, as LLVM's is; where LLVM keeps the
/// access (O0, or a thread-local the crate writes) the search fails phase one
/// here earlier than LLVM's (OD-58), never later.
pub fn aarch64_call_may_unwind(
    inst: &IrMachInst,
    nounwind_callees: &BTreeSet<String>,
) -> Option<bool> {
    let direct = match inst.opcode {
        IrOpcode::Bl | IrOpcode::BL | IrOpcode::TailCall => true,
        IrOpcode::TlsDescCall | IrOpcode::BlrTlsdesc => return Some(false),
        IrOpcode::Blr | IrOpcode::BLR
            if inst
                .flags
                .contains(trust_cg_ir::InstFlags::CANNOT_UNWIND_CALL) =>
        {
            return Some(false);
        }
        IrOpcode::Blr | IrOpcode::BLR => false,
        _ if inst.is_call() => false,
        _ => return None,
    };
    if !direct {
        return Some(true);
    }
    let mut callees = inst.operands.iter().filter_map(|operand| match operand {
        IrOperand::Symbol(symbol) | IrOperand::ExactModuleSymbol(symbol) => Some(symbol),
        _ => None,
    });
    let declared_nounwind = match (callees.next(), callees.next()) {
        (Some(callee), None) => nounwind_callees.contains(callee),
        _ => false,
    };
    Some(!declared_nounwind)
}

/// The frontend's `nounwind` callees (`frontend`, the
/// `CompilerConfig::eh_nounwind_callees` of a module compile) plus the runtime
/// routines this backend calls on its own for an operation of `module` where
/// LLVM has no call, so that [`EhPropagation::NounwindFrame`] leaves a region
/// whose other calls are `nounwind` the gap LLVM's is. Each routine calls
/// nothing that unwinds.
///
/// * The adapter expands an `i128` / `u128` checked multiply (`Inst::Overflow`,
///   `MulOverflow`) for AArch64 with a guarded division of the low product: a
///   `__divti3` / `__udivti3` call. LLVM expands the same operation inline
///   (measured O0-O3: `checked_mul` / `overflowing_mul` leave no call). (Its
///   x86-64 expansion is division-free since OD-224 and calls nothing; this
///   table serves only the AArch64 route, the one non-unwinding frames are
///   modelled on: `CompilerConfig::eh_frames_cannot_unwind` is refused
///   elsewhere.) A user `i128` division
///   in the same function is a call LLVM makes only where it can know nothing
///   about the operands (it expands a constant divisor and narrows
///   zero-extended operands); where it does, the region is a gap here and the
///   search fails phase one earlier than LLVM's (OD-58).
/// * The Darwin `sincos-merge` pass replaces a same-argument `sin` + `cos` pair
///   with one `__sincos_stret` call. When the frontend records both as
///   `nounwind` (LLVM folds them, as for a constant argument), the merged call
///   is recorded too. LLVM's own merge of a runtime pair is a libcall that may
///   unwind, so a function that also has a runtime pair aborts earlier there.
pub fn backend_expansion_nounwind_callees(
    module: &trust_ir::Module,
    frontend: &BTreeSet<String>,
) -> BTreeSet<String> {
    use trust_cg_lower::runtime_calls::RuntimeSymbol;
    let mut callees = frontend.clone();
    for node in module
        .functions
        .iter()
        .flat_map(|function| &function.blocks)
        .flat_map(|block| &block.body)
    {
        if let trust_ir::Inst::Overflow {
            op: trust_ir::OverflowOp::MulOverflow,
            ty,
            ..
        } = &node.inst
        {
            match ty {
                trust_ir::Ty::I128 => callees.insert(RuntimeSymbol::Divti3.name().to_owned()),
                trust_ir::Ty::U128 => callees.insert(RuntimeSymbol::Udivti3.name().to_owned()),
                _ => false,
            };
        }
    }
    if frontend.contains("sin") && frontend.contains("cos") {
        callees.insert(RuntimeSymbol::SincosStret.name().to_owned());
    }
    callees
}

/// [`resolve_eh_offsets`] with an explicit treatment of the bytes outside the
/// function's explicit handler ranges (see [`EhPropagation`]).
pub fn resolve_eh_offsets_with_propagation(
    func: &mut IrMachFunction,
    block_offsets: &HashMap<BlockId, u32>,
    code_len: usize,
    propagation: &EhPropagation,
) -> Result<(), PipelineError> {
    if !func.eh_metadata.has_eh_info() {
        return Ok(());
    }

    use trust_cg_ir::function::EhCallSiteEntry;

    let malformed = |detail: String| PipelineError::MalformedAarch64Eh {
        function: func.name.clone(),
        detail: format!("invalid AArch64 EH metadata/layout: {detail}"),
    };
    let exact_calls = eh_call_identity::exact_calls(func).map_err(malformed)?;
    let code_len = aarch64_text_offset_u32(&func.name, code_len).map_err(|length| {
        malformed(format!(
            "encoded code length {length} exceeds the u32 LSDA offset domain"
        ))
    })?;
    if code_len == 0 {
        return Err(malformed(
            "non-empty EH metadata on an empty encoded function".to_string(),
        ));
    }
    if code_len % 4 != 0 {
        return Err(malformed(format!(
            "encoded code length {code_len} is not AArch64 instruction/data aligned"
        )));
    }

    // Authenticate the encoder's block map and derive exact final instruction
    // identities/offsets from the same fixed-width stream it encoded. The RA
    // rebuild explicitly remaps selected IDs; subsequent edits are append-only.
    let mut laid_out_blocks = BTreeSet::new();
    let mut encoded_inst_offsets: HashMap<InstId, u32> = HashMap::new();
    let mut eh_edges =
        trust_cg_ir::function::EhEdgeCensus::for_handlers(&func.eh_metadata.call_sites);
    let mut body_end = 0u32;
    for &block_id in &func.block_order {
        if !laid_out_blocks.insert(block_id) {
            return Err(malformed(format!(
                "block_order contains duplicate block {block_id:?}"
            )));
        }
        let block = func
            .blocks
            .get(block_id.0 as usize)
            .ok_or_else(|| malformed(format!("block_order names missing block {block_id:?}")))?;
        eh_edges.observe_block(block_id, block);
        let encoded_block_start = block_offsets
            .get(&block_id)
            .copied()
            .ok_or_else(|| malformed(format!("block {block_id:?} has no final encoded offset")))?;
        if encoded_block_start != body_end {
            return Err(malformed(format!(
                "block {block_id:?} encoder offset {encoded_block_start} does not match re-derived final offset {body_end}"
            )));
        }
        for &inst_id in &block.insts {
            let inst = func.insts.get(inst_id.0 as usize).ok_or_else(|| {
                malformed(format!(
                    "block {block_id:?} names missing instruction {inst_id:?}"
                ))
            })?;
            if inst.is_pseudo() {
                continue;
            }
            if encoded_inst_offsets.insert(inst_id, body_end).is_some() {
                return Err(malformed(format!(
                    "encoded instruction {inst_id:?} appears in multiple layout positions"
                )));
            }
            body_end = body_end
                .checked_add(4)
                .ok_or_else(|| malformed("encoded instruction offsets overflow u32".to_string()))?;
        }
    }
    if block_offsets.len() != laid_out_blocks.len()
        || block_offsets
            .keys()
            .any(|block| !laid_out_blocks.contains(block))
    {
        return Err(malformed(
            "encoder block-offset map does not exactly match block_order".to_string(),
        ));
    }
    if body_end > code_len {
        return Err(malformed(format!(
            "re-derived instruction body length {body_end} exceeds encoded length {code_len}"
        )));
    }

    // Resolve and authenticate landing-pad offsets. Zero is the LSDA sentinel
    // for "no handler" and therefore cannot identify a semantic landing pad.
    let mut landing_pad_offsets = HashMap::new();
    for lp in &mut func.eh_metadata.landing_pads {
        if landing_pad_offsets.contains_key(&lp.block) {
            return Err(malformed(format!(
                "duplicate landing-pad record for block {:?}",
                lp.block
            )));
        }
        if !laid_out_blocks.contains(&lp.block) {
            return Err(malformed(format!(
                "landing-pad block {:?} is absent from block_order",
                lp.block
            )));
        }
        let offset = block_offsets.get(&lp.block).copied().ok_or_else(|| {
            malformed(format!(
                "landing-pad block {:?} has no final encoded offset",
                lp.block
            ))
        })?;
        let has_real_instruction = func.blocks.get(lp.block.0 as usize).is_some_and(|block| {
            block.insts.iter().any(|inst_id| {
                func.insts
                    .get(inst_id.0 as usize)
                    .is_some_and(|inst| !inst.is_pseudo())
            })
        });
        if offset == 0 {
            return Err(malformed(format!(
                "landing-pad block {:?} resolves to offset 0, reserved by the LSDA as no-handler",
                lp.block
            )));
        }
        if offset >= body_end || !has_real_instruction {
            return Err(malformed(format!(
                "landing-pad block {:?} at offset {offset} has no encoded instruction body",
                lp.block
            )));
        }
        if lp.offset != 0 && lp.offset != offset {
            return Err(malformed(format!(
                "landing-pad block {:?} carries stale offset {}, final layout requires {offset}",
                lp.block, lp.offset
            )));
        }
        lp.offset = offset;
        landing_pad_offsets.insert(lp.block, offset);
    }

    // Ensure the call-site table covers the ENTIRE function `[0, code_len)`.
    //
    // The Itanium personality (`__gxx_personality_v0`, libcxxabi
    // `scan_eh_table`) requires the call-site entries to be sorted, non-
    // overlapping, and — critically — to cover every PC that can be "in flight"
    // during unwinding. If it is consulted at a PC that falls in a GAP between
    // entries (or past the last entry), it does NOT continue unwinding: it calls
    // `std::terminate()` (cxa_personality.cpp lines 908-913 and 918-920).
    //
    // A CATCH-only landing pad never re-enters the unwinder (it claims the
    // exception and returns normally), so a single throwing-call region is
    // enough for it. But a CLEANUP pad runs `_Unwind_Resume(exn)`, which RE-
    // CONSULTS this same function's personality at the resume `Bl`'s PC. That PC
    // lies inside the landing-pad block — NOT inside any throwing-call region —
    // so without full coverage the personality terminates instead of stepping
    // out to the enclosing handler. Clang emits filler `landingPad == 0`
    // call-site entries over the non-throwing regions for exactly this reason.
    //
    // Canonicalize away any prior no-handler entries (including fillers from a
    // previous resolution), then bind every semantic handler record to one
    // exact final call instruction. A no-handler record is semantically
    // equivalent to filler; action chains are derived exclusively from its
    // referenced landing-pad descriptor by the checked LSDA builder.
    let original_call_sites = func.eh_metadata.call_sites.clone();
    let mut protected_blocks = BTreeSet::new();
    let mut protected_calls = BTreeSet::new();
    let mut explicit = Vec::new();
    for cs in original_call_sites {
        let Some(landing_pad_block) = cs.landing_pad_block else {
            continue;
        };
        if !protected_blocks.insert(cs.call_block) {
            return Err(malformed(format!(
                "EH call block {:?} has multiple handler records; block-granular metadata is ambiguous",
                cs.call_block
            )));
        }
        if !landing_pad_offsets.contains_key(&landing_pad_block) {
            return Err(malformed(format!(
                "EH call block {:?} targets block {landing_pad_block:?}, which has no landing-pad descriptor",
                cs.call_block
            )));
        }
        let block = func
            .blocks
            .get(cs.call_block.0 as usize)
            .filter(|_| laid_out_blocks.contains(&cs.call_block))
            .ok_or_else(|| {
                malformed(format!(
                    "EH call block {:?} is missing or absent from block_order",
                    cs.call_block
                ))
            })?;
        let (successor_count, predecessor_count) =
            eh_edges.counts(cs.call_block, landing_pad_block);
        if successor_count != 1 || predecessor_count != 1 {
            return Err(malformed(format!(
                "exceptional edge {:?} -> {landing_pad_block:?} is not exactly reciprocal (successors={successor_count}, predecessors={predecessor_count})",
                cs.call_block
            )));
        }
        let call_id = if let Some(exact) = &exact_calls {
            *exact.get(&cs.call_block).ok_or_else(|| {
                malformed(format!(
                    "EH call block {:?} is missing its exact selected Invoke binding",
                    cs.call_block
                ))
            })?
        } else {
            let calls: Vec<InstId> = block
                .insts
                .iter()
                .copied()
                .filter(|&inst_id| {
                    func.insts.get(inst_id.0 as usize).is_some_and(|inst| {
                        matches!(
                            inst.opcode,
                            IrOpcode::Bl | IrOpcode::BL | IrOpcode::Blr | IrOpcode::BLR
                        )
                    })
                })
                .collect();
            let [call] = calls.as_slice() else {
                return Err(malformed(format!(
                    "EH call block {:?} contains {} eligible BL/BLR calls; exactly one is required by block-granular metadata",
                    cs.call_block,
                    calls.len()
                )));
            };
            *call
        };
        let start = encoded_inst_offsets.get(&call_id).copied().ok_or_else(|| {
            malformed(format!(
                "protected call {call_id:?} has no exact final-encoding offset"
            ))
        })?;
        let end = start
            .checked_add(4)
            .ok_or_else(|| malformed(format!("protected call {call_id:?} range overflows u32")))?;
        if end > body_end || end > code_len {
            return Err(malformed(format!(
                "protected call {call_id:?} range [{start},{end}) escapes instruction body [0,{body_end}) or code [0,{code_len})"
            )));
        }
        if (cs.start_offset != 0 || cs.length != 0) && (cs.start_offset != start || cs.length != 4)
        {
            return Err(malformed(format!(
                "protected call {call_id:?} carries stale range [{},{}), final encoding requires [{start},{end})",
                cs.start_offset,
                cs.start_offset.saturating_add(cs.length)
            )));
        }
        protected_calls.insert(call_id);
        explicit.push(EhCallSiteEntry {
            call_block: cs.call_block,
            start_offset: start,
            length: 4,
            landing_pad_block: Some(landing_pad_block),
        });
    }

    explicit.sort_by_key(|cs| cs.start_offset);
    // Under the nounwind-frame policy, the final offsets of every encoded call
    // outside the protected calls that may unwind by LLVM's rule. A region
    // between protected ranges needs a propagation entry iff it holds one;
    // under the filler policy every region gets one.
    let unwinding_call_offsets = match propagation {
        EhPropagation::Filler => None,
        EhPropagation::NounwindFrame { nounwind_callees } => {
            require_nounwind_frame(func, explicit.len()).map_err(malformed)?;
            let mut offsets = Vec::new();
            for (inst_id, &offset) in &encoded_inst_offsets {
                if protected_calls.contains(inst_id) {
                    continue;
                }
                let inst = func.insts.get(inst_id.0 as usize).ok_or_else(|| {
                    malformed(format!("encoded instruction {inst_id:?} is missing"))
                })?;
                if aarch64_call_may_unwind(inst, nounwind_callees) == Some(true) {
                    offsets.push(offset);
                }
            }
            offsets.sort_unstable();
            Some(offsets)
        }
    };
    let region_propagates = |start: u32, end: u32| {
        unwinding_call_offsets.as_ref().is_none_or(|offsets| {
            let first = offsets.partition_point(|&offset| offset < start);
            offsets.get(first).is_some_and(|&offset| offset < end)
        })
    };
    let filler_block = explicit
        .first()
        .map(|cs| cs.call_block)
        .or_else(|| func.block_order.first().copied())
        .ok_or_else(|| malformed("EH function has no laid-out block".to_string()))?;
    let mut resolved_call_sites = Vec::new();
    let mut cursor = 0u32;
    for cs in explicit {
        let start = cs.start_offset;
        let end = start + cs.length;
        if start < cursor {
            return Err(malformed(format!(
                "protected call ranges overlap at byte {start}"
            )));
        }
        if start > cursor && region_propagates(cursor, start) {
            resolved_call_sites.push(EhCallSiteEntry {
                call_block: filler_block,
                start_offset: cursor,
                length: start - cursor,
                landing_pad_block: None,
            });
        }
        resolved_call_sites.push(cs);
        cursor = end;
    }
    if cursor < code_len && region_propagates(cursor, code_len) {
        resolved_call_sites.push(EhCallSiteEntry {
            call_block: filler_block,
            start_offset: cursor,
            length: code_len - cursor,
            landing_pad_block: None,
        });
    }
    func.eh_metadata.call_sites = resolved_call_sites;
    Ok(())
}

/// The preconditions under which [`EhPropagation::NounwindFrame`] is the
/// modeled non-unwinding frame, checked before any filler is withheld.
///
/// * The personality is `rust_eh_personality`, whose phase-one search
///   reports a call site absent from the table as `_URC_FATAL_PHASE1_ERROR`
///   (core's DWARF EH reader: an IP not in the table is a nounwind call).
///   Another personality's treatment of a gap is not modeled here.
/// * At least one explicit `Invoke` handler exists. A frame with metadata but
///   no handler would emit an LSDA that may reject a call, where LLVM emits
///   none for a `nounwind` function without landing pads.
/// * No `_Unwind_Resume` call: resuming is propagating out of this frame,
///   which a non-unwinding frame must never do; the source must end such a
///   cleanup in its own termination instead.
/// * No tail exit: it removes this frame before the callee runs and thus
///   bypasses this table. Check the final stream even though optimization
///   preserves required call frames; later expansion must honor it too.
fn require_nounwind_frame(func: &IrMachFunction, handlers: usize) -> Result<(), String> {
    const RUST_PERSONALITY: &str = "rust_eh_personality";
    if func.eh_metadata.personality.as_deref() != Some(RUST_PERSONALITY) {
        return Err(format!(
            "a non-unwinding exception frame is modeled only under `{RUST_PERSONALITY}`, \
             found {:?} [TCG-EH-NOUNWIND-FRAME]",
            func.eh_metadata.personality
        ));
    }
    if handlers == 0 {
        return Err(
            "a non-unwinding exception frame carries exception metadata but no explicit \
             handler range [TCG-EH-NOUNWIND-FRAME]"
                .to_string(),
        );
    }
    for block in &func.block_order {
        for id in &func.block(*block).insts {
            let inst = func.inst(*id);
            let symbolic_exit = inst.opcode == IrOpcode::B
                && inst.operands.iter().any(|operand| {
                    matches!(
                        operand,
                        IrOperand::Symbol(_) | IrOperand::ExactModuleSymbol(_)
                    )
                });
            if inst.opcode == IrOpcode::TailCall || symbolic_exit {
                return Err(format!(
                    "a non-unwinding exception frame contains tail exit {id:?} ({:?}), \
                     which bypasses its exception table [TCG-EH-NOUNWIND-FRAME]",
                    inst.opcode
                ));
            }
        }
    }
    let resume = trust_cg_lower::runtime_calls::RuntimeSymbol::UnwindResume.name();
    let resumes = func
        .block_order
        .iter()
        .filter_map(|block| func.blocks.get(block.0 as usize))
        .flat_map(|block| block.insts.iter())
        .filter_map(|inst| func.insts.get(inst.0 as usize))
        .any(|inst| {
            matches!(inst.opcode, IrOpcode::Bl | IrOpcode::BL)
                && inst.operands.iter().any(|operand| {
                    matches!(operand, trust_cg_ir::MachOperand::Symbol(symbol) if symbol == resume)
                })
        });
    if resumes {
        return Err(format!(
            "a non-unwinding exception frame calls `{resume}`, which propagates the exception \
             out of a frame that must stop it [TCG-EH-NOUNWIND-FRAME]"
        ));
    }
    Ok(())
}

/// Generate the LSDA image from a function's exception handling metadata.
///
/// Bridges `trust_cg_ir::ExceptionHandlingMetadata` to the codegen-level
/// `exception_handling::ExceptionTable` and serializes it to the binary
/// LSDA format. Typed catches bind through `eh_metadata.eh_type_table`
/// (entry `k - 1` is the typeinfo symbol of catch type index `k`) and come
/// back as [`crate::exception_handling::LsdaTypeInfoRelocation`]s the object
/// emitter must bind. Returns `None` if the function has no EH info.
///
/// This must be called after code layout (so block byte offsets are known)
/// and before Mach-O emission (so the LSDA bytes can be placed in the
/// `__gcc_except_tab` section).
/// Modern call custody is checked against the actual machine owner here too;
/// an LSDA image alone does not attest final byte ranges or native execution.
/// Native emission must first resolve and authenticate the encoded layout.
pub fn generate_lsda_for_function(
    func: &IrMachFunction,
) -> Result<Option<crate::exception_handling::LsdaImage>, PipelineError> {
    validate_exact_aarch64_eh_call_identity(func)?;
    let eh = &func.eh_metadata;
    if !eh.has_eh_info() {
        return Ok(None);
    }

    use crate::exception_handling::{LandingPadDesc, generate_lsda_image_from_pads};

    let personality = crate::exception_handling::required_personality_symbol(
        eh.personality.as_deref(),
    )
    .map_err(|error| PipelineError::MalformedAarch64Eh {
        function: func.name.clone(),
        detail: format!("invalid exception-handling personality: {error}"),
    })?;

    // Convert IR-level landing pad entries to codegen-level descriptors while
    // retaining an exact block->offset authority for call-site references.
    // A duplicate block or stale reference must not silently become the LSDA
    // no-handler sentinel.
    let mut landing_pad_offset_by_block = HashMap::new();
    let mut landing_pad_descs = Vec::with_capacity(eh.landing_pads.len());
    for lp in &eh.landing_pads {
        if landing_pad_offset_by_block
            .insert(lp.block, lp.offset)
            .is_some()
        {
            return Err(PipelineError::MalformedAarch64Eh {
                function: func.name.clone(),
                detail: format!(
                    "invalid resolved exception table: duplicate landing-pad block {:?}",
                    lp.block
                ),
            });
        }
        landing_pad_descs.push(LandingPadDesc {
            landing_pad_offset: lp.offset,
            catch_type_indices: lp.catch_type_indices.clone(),
            is_cleanup: lp.is_cleanup,
        });
    }

    // Convert call site entries to (start, length, lp_offset) tuples.
    let mut call_site_ranges = Vec::with_capacity(eh.call_sites.len());
    for (index, cs) in eh.call_sites.iter().enumerate() {
        let lp_offset = match cs.landing_pad_block {
            Some(block) => landing_pad_offset_by_block.get(&block).copied().ok_or_else(|| {
                PipelineError::MalformedAarch64Eh {
                    function: func.name.clone(),
                    detail: format!(
                        "invalid resolved exception table: call-site {index} references missing landing-pad block {block:?}"
                    ),
                }
            })?,
            None => 0,
        };
        call_site_ranges.push((cs.start_offset, cs.length, lp_offset));
    }

    let image = generate_lsda_image_from_pads(
        personality,
        &landing_pad_descs,
        &call_site_ranges,
        &eh.eh_type_table,
    )
    .map_err(|error| PipelineError::MalformedAarch64Eh {
        function: func.name.clone(),
        detail: format!("invalid resolved exception table: {error}"),
    })?;
    Ok(Some(image))
}

// ---------------------------------------------------------------------------
// Pipeline — main entry point
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Aarch64DirectCallAdmission {
    Compatibility,
    SealedCore,
}

/// Controls correctness nets whose compatibility APIs retain explicit
/// diagnostic environment overrides.
///
/// Proof-authoritative ownership transitions must select `ProofGradeEnforce`
/// directly. A stable process environment is not proof authority: stabilizing
/// an `off` or `warn` override would otherwise preserve the downgrade rather
/// than close it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Aarch64IntegrityPolicy {
    Compatibility,
    ProofGradeEnforce,
}

impl Aarch64DirectCallAdmission {
    const fn integrity_policy(self) -> Aarch64IntegrityPolicy {
        match self {
            Self::Compatibility => Aarch64IntegrityPolicy::Compatibility,
            Self::SealedCore => Aarch64IntegrityPolicy::ProofGradeEnforce,
        }
    }
}

/// Ambient controls that change AArch64 late-layout bytes after the final
/// structural validators: loop-head alignment (`crate::loop_align`) and
/// post-RA post-index formation (`crate::post_index_late`). None is part of
/// the explicit compile policy, so proof-grade routes refuse them instead of
/// letting an unkeyed environment variable steer published bytes. Diagnostic
/// trace/dump switches that do not change bytes are not listed. Ordinary
/// routes keep them; their presence already makes artifact reuse ineligible.
pub const AARCH64_LATE_LAYOUT_CONTROLS: &[&str] = &[
    "TCG_LOOP_HEAD_ALIGN",
    "TCG_NO_LOOP_HEAD_ALIGN",
    "TCG_LOOP_ALIGN_NO_PAD",
    "TCG_LOOP_ALIGN_NO_FUNC_PLACEMENT",
    "TCG_LOOP_ALIGN_NO_SEAM_GATE",
    "TCG_LOOP_ALIGN_SEAM_SPAN",
    "TCG_LOOP_ALIGN_MAX_SKIP",
    "TCG_LOOP_ALIGN_IN_CYCLE_PAD",
    "TCG_LOOP_ALIGN_NO_FORFEIT_PIN",
    "TCG_LOOP_ALIGN_NO_CYCLE_CHECK",
    "TCG_PIL_MAX",
    "TCG_NO_POST_INDEX_LATE",
];

/// Refuse any [`AARCH64_LATE_LAYOUT_CONTROLS`] entry, including an empty value
/// (the legacy switches test presence). `loop_align` and `post_index_late`
/// read these controls from the process environment directly, so a
/// thread-local removal override cannot hide one: the refusal consults the
/// process environment as well as this thread's override view.
fn refuse_aarch64_late_layout_controls(function: &str) -> Result<(), PipelineError> {
    match AARCH64_LATE_LAYOUT_CONTROLS.iter().find(|control| {
        std::env::var_os(control).is_some() || trust_cg_process_env::var_os(control).is_some()
    }) {
        Some(control) => Err(PipelineError::AmbientLateLayoutControl {
            function: function.to_owned(),
            control,
        }),
        None => Ok(()),
    }
}

/// ENC-5 for trap expansions (L04-P12): every recorded expansion
/// (`MachFunction::trap_expansions`) must be in the final stream whole and
/// contiguous, and its emitted words must trap exactly when its carrier's
/// condition holds (`trust_cg_verify::aarch64_trap_expansion`, decided in
/// process: testing-grade evidence, not a certificate); a recorded carrier
/// outside that model is refused by name. The per-word arms of ENC-5 still
/// decode each word against its own intent. An expansion removed whole (its
/// block was dropped) is not judged. `warn` logs a violation and `off` skips
/// the check, like the rest of ENC-5.
fn check_aarch64_trap_expansions(
    func: &IrMachFunction,
    offsets: &HashMap<InstId, usize>,
    code: &[u8],
    mode: crate::decode_check::DecodeCheckMode,
) -> Result<(), PipelineError> {
    use crate::decode_check::DecodeCheckMode;
    if mode == DecodeCheckMode::Off {
        return Ok(());
    }
    for record in &func.trap_expansions {
        let placed: Vec<Option<usize>> = record
            .insts
            .iter()
            .map(|id| offsets.get(id).copied())
            .collect();
        if placed.iter().all(Option::is_none) {
            continue;
        }
        let words: Option<Vec<u32>> = placed
            .iter()
            .map(|start| {
                let start = (*start)?;
                let bytes: [u8; 4] = code.get(start..start + 4)?.try_into().ok()?;
                Some(u32::from_le_bytes(bytes))
            })
            .collect();
        let starts: Vec<usize> = placed.iter().flatten().copied().collect();
        let detail = match words {
            None => Some("only part of the expansion is in the final stream".to_string()),
            Some(_) if starts.windows(2).any(|pair| pair[1] != pair[0] + 4) => Some(format!(
                "the expansion's words are not contiguous (offsets {starts:?})"
            )),
            Some(words) => trust_cg_verify::aarch64_trap_expansion::check_emitted_trap_expansion(
                &record.carrier,
                &words,
            )
            .err(),
        };
        if let Some(detail) = detail {
            let message = format!(
                "ENC-5 trap expansion of {:?} in `{}`: {detail}",
                record.carrier.opcode, func.name
            );
            match mode {
                DecodeCheckMode::Enforce => return Err(PipelineError::Encoding(message)),
                DecodeCheckMode::Warn => eprintln!("decode-check WARN: {message}"),
                DecodeCheckMode::Off => {}
            }
        }
    }
    Ok(())
}

fn aarch64_decode_check_mode_for_integrity_policy(
    integrity_policy: Aarch64IntegrityPolicy,
) -> crate::decode_check::DecodeCheckMode {
    match integrity_policy {
        Aarch64IntegrityPolicy::Compatibility => {
            crate::aarch64::decode_check::a64_decode_check_mode()
        }
        Aarch64IntegrityPolicy::ProofGradeEnforce => crate::decode_check::DecodeCheckMode::Enforce,
    }
}

/// The Trust Codegen compilation pipeline.
///
/// Orchestrates all phases from trust_ir input through to Mach-O .o emission.
pub struct Pipeline {
    pub config: PipelineConfig,
    /// Resolved machine-code capability contract. Kept out of the public
    /// configuration record so adding a target capability cannot break every
    /// downstream `PipelineConfig { .. }` literal.
    aarch64_target_machine: AArch64TargetMachine,
    /// Compiler-owned policy for the RAW ISel TV-3 boundary, independent of
    /// optional later verification and ambient rollout controls.
    raw_dataflow_policy: Aarch64DataflowIntegrityPolicy,
    profile_use: Option<trust_cg_opt::pgo::ProfData>,
    /// AOT PGO profile-generate sink. When `Some`, `prepare_function_*`
    /// injects per-block counter increments (against the module-level
    /// `__tcg_pgo_counters` array) between verification and register
    /// allocation, and records every `CounterSite` here. `None` (the default)
    /// leaves the pipeline byte-identical to a build without this feature.
    profile_generate_sink: Option<Arc<std::sync::Mutex<trust_cg_opt::pgo::CounterMap>>>,
    certified_pass_execution: bool,
    /// Requested per-pass validation ([`Self::with_pass_validation`]);
    /// `None` takes `TRUST_CG_PASS_VALIDATION` or the diagnostic default.
    /// [`Self::pass_validation_config`] resolves it against the proof-grade
    /// floor.
    pass_validation: Option<trust_cg_opt::PassValidationConfig>,
    /// Requested composed transition records
    /// ([`Self::with_composed_transitions`]); `None` takes
    /// `TRUST_CG_COMPOSED_TRANSITION` or off.
    /// [`Self::composed_transition_policy`] resolves it against the
    /// proof-grade floor.
    composed_transitions: Option<crate::composed_transition::ComposedTransitionPolicy>,
    /// AArch64 ELF only: guaranteed address alignment of each symbol this
    /// object defines (non-weak, non-TLS data), which admits fusing
    /// `ADRP+ADD+LDR/STR` into `ADRP+LDR/STR #:lo12:` (see
    /// [`fuse_elf_lo12_memory_accesses`]). `None` keeps every ADD.
    elf_lo12_symbol_alignments: Option<Arc<BTreeMap<String, u64>>>,
    /// Object-layout policy: every function in its own `.text.<symbol>`
    /// section on the AArch64 ELF path ([`Self::with_function_sections`]).
    /// Kept out of [`PipelineConfig`] for the same literal-compatibility
    /// reason as the target machine above.
    function_sections: bool,
    /// Exception-table policy ([`Self::with_eh_frames_cannot_unwind`]): the
    /// full-coverage propagation filler, or LLVM's region rule for a function
    /// that cannot unwind (a propagation entry only for a region holding a
    /// call that may unwind). Kept out of [`PipelineConfig`] for the same
    /// literal-compatibility reason as the fields above.
    pub(crate) eh_propagation: EhPropagation,
    /// Final-stream integrity policy for every AArch64 encode this pipeline
    /// performs ([`Self::with_proof_grade_aarch64_publication`]).
    aarch64_integrity_policy: Aarch64IntegrityPolicy,
    #[cfg_attr(not(feature = "verify"), allow(dead_code))]
    cegis_cache: Arc<dyn trust_cg_opt::CacheBackend>,
    #[cfg(not(feature = "verify"))]
    cegis_warning_emitted: AtomicBool,
    #[cfg(all(test, feature = "verify"))]
    cegis_test_incomplete_after_first_commit: bool,
}

fn trust_cg_pass_disabled(name: &str) -> bool {
    crate::env_lock::var("TRUST_CG_DISABLE_PASSES")
        .unwrap_or_default()
        .split(',')
        .any(|disabled| disabled.trim() == name)
}

/// Opt-in counterpart to [`trust_cg_pass_disabled`]: true iff `name` appears in
/// `TRUST_CG_ENABLE_PASSES`. Used for sound-but-default-off transforms.
fn trust_cg_pass_enabled(name: &str) -> bool {
    std::env::var("TRUST_CG_ENABLE_PASSES")
        .unwrap_or_default()
        .split(',')
        .any(|enabled| enabled.trim() == name)
}

fn trust_cg_time_pipeline_enabled() -> bool {
    // Cached once: this is polled ~10x per function (per phase). Reading the env
    // a single time turns the default (timing OFF) hot path into a cheap atomic
    // load instead of two env syscalls per phase per function.
    use std::sync::OnceLock;
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| {
        std::env::var_os("TRUST_CG_TIME_PIPELINE").is_some()
            || std::env::var_os("TRUST_CG_TIME_PASSES").is_some()
    })
}

fn ir_function_shape(func: &IrMachFunction) -> (usize, usize) {
    let blocks = func.block_order.len();
    let insts = func
        .block_order
        .iter()
        .map(|&block_id| func.block(block_id).insts.len())
        .sum();
    (blocks, insts)
}

fn dwarf_standard_type_index(ty: DebugBaseType) -> usize {
    match ty {
        DebugBaseType::I8 => 0,
        DebugBaseType::I16 => 1,
        DebugBaseType::I32 => 2,
        DebugBaseType::I64 | DebugBaseType::I128 => 3,
        DebugBaseType::F32 => 4,
        DebugBaseType::F64 => 5,
        DebugBaseType::Bool => 6,
        DebugBaseType::U8 => 7,
        DebugBaseType::U16 => 8,
        DebugBaseType::U32 => 9,
        DebugBaseType::U64 | DebugBaseType::U128 | DebugBaseType::Ptr => 10,
    }
}

fn debug_base_type_for_ir_type(ty: &trust_cg_ir::Type) -> DebugBaseType {
    match ty {
        trust_cg_ir::Type::I8 => DebugBaseType::I8,
        trust_cg_ir::Type::I16 => DebugBaseType::I16,
        trust_cg_ir::Type::I32 => DebugBaseType::I32,
        trust_cg_ir::Type::I64 | trust_cg_ir::Type::I128 => DebugBaseType::I64,
        // DWARF-v1's fixed base-type table has no vector DIE. This is a
        // debug-description-only 128-bit-width fallback; ABI, regalloc, and
        // lowering retain V128 through `lower_type_from_ir_type` below.
        trust_cg_ir::Type::V128 => DebugBaseType::I128,
        // The same debug-only fallback retains the 64-bit carrier width.
        trust_cg_ir::Type::V64 => DebugBaseType::I64,
        trust_cg_ir::Type::F32 => DebugBaseType::F32,
        trust_cg_ir::Type::F64 => DebugBaseType::F64,
        trust_cg_ir::Type::B1 => DebugBaseType::Bool,
        trust_cg_ir::Type::Ptr => DebugBaseType::Ptr,
        trust_cg_ir::Type::F16
        | trust_cg_ir::Type::Struct(_)
        | trust_cg_ir::Type::Array(_, _)
        | trust_cg_ir::Type::Enum { .. } => DebugBaseType::I64,
    }
}

fn dwarf_type_index_for_ir_type(ty: &trust_cg_ir::Type) -> usize {
    dwarf_standard_type_index(debug_base_type_for_ir_type(ty))
}

fn lower_type_from_ir_type(ty: &trust_cg_ir::Type) -> LowerType {
    match ty {
        trust_cg_ir::Type::I8 => LowerType::I8,
        trust_cg_ir::Type::I16 => LowerType::I16,
        trust_cg_ir::Type::I32 => LowerType::I32,
        trust_cg_ir::Type::I64 | trust_cg_ir::Type::Ptr => LowerType::I64,
        trust_cg_ir::Type::I128 => LowerType::I128,
        trust_cg_ir::Type::V128 => LowerType::V128,
        trust_cg_ir::Type::V64 => LowerType::V64,
        trust_cg_ir::Type::F16 => LowerType::F16,
        trust_cg_ir::Type::F32 => LowerType::F32,
        trust_cg_ir::Type::F64 => LowerType::F64,
        trust_cg_ir::Type::B1 => LowerType::B1,
        trust_cg_ir::Type::Struct(fields) => {
            LowerType::Struct(fields.iter().map(lower_type_from_ir_type).collect())
        }
        trust_cg_ir::Type::Array(elem, count) => {
            LowerType::Array(Box::new(lower_type_from_ir_type(elem)), *count)
        }
        trust_cg_ir::Type::Enum {
            tag_width,
            variants,
        } => LowerType::Enum {
            tag_width: *tag_width,
            variants: variants
                .iter()
                .map(|fields| fields.iter().map(lower_type_from_ir_type).collect())
                .collect(),
        },
    }
}

fn dwarf_register_number(preg: PReg) -> u64 {
    let preg = match preg_class(preg) {
        RegClass::Gpr32 | RegClass::System => gpr32_to_gpr64(preg).unwrap_or(preg),
        _ => preg,
    };
    u64::from(preg.encoding())
}

fn dwarf_param_location(
    loc: &ArgLocation,
    frame_layout: Option<&crate::frame::FrameLayout>,
) -> crate::dwarf_info::VariableLocation {
    match loc {
        ArgLocation::Ignore => crate::dwarf_info::VariableLocation::LocationList(Vec::new()),
        ArgLocation::Reg(preg) | ArgLocation::Indirect { ptr_reg: preg } => {
            crate::dwarf_info::VariableLocation::Register(dwarf_register_number(*preg))
        }
        ArgLocation::RegSequence(regs) => regs
            .first()
            .map_or(crate::dwarf_info::VariableLocation::Register(0), |preg| {
                crate::dwarf_info::VariableLocation::Register(dwarf_register_number(*preg))
            }),
        ArgLocation::RegPair(lo_preg, _) => {
            crate::dwarf_info::VariableLocation::Register(dwarf_register_number(*lo_preg))
        }
        // An incoming stack argument lives at `entry SP + offset`, and entry
        // SP is the CFA. The prologue leaves X29 at `CFA - 16` (FP/LR pair at
        // the top of the callee-saved area, whatever its size), so the frame
        // base offset is `16 + offset`. A frameless function keeps SP at its
        // entry value, so the argument is SP-relative there. Without a frame
        // layout neither is known, so no location is claimed.
        ArgLocation::Stack { offset, .. } => match frame_layout {
            Some(layout) if layout.uses_frame_pointer => {
                crate::dwarf_info::VariableLocation::FrameOffset(AARCH64_FP_TO_CFA + *offset)
            }
            Some(_) => crate::dwarf_info::VariableLocation::RegOffset(AARCH64_DWARF_SP, *offset),
            None => crate::dwarf_info::VariableLocation::LocationList(Vec::new()),
        },
    }
}

/// Bytes from the frame pointer to the CFA once the prologue has set X29:
/// the FP/LR pair sits at the top of the callee-saved area.
const AARCH64_FP_TO_CFA: i64 = 16;

/// DWARF register number of the AArch64 stack pointer.
const AARCH64_DWARF_SP: u64 = 31;

/// DWARF register number of the AArch64 frame pointer (X29).
const AARCH64_DWARF_FP: u64 = 29;

/// Encoded byte ranges `[start, end)` of `ir_func` in which X29 holds this
/// frame's frame pointer, the frame base every `DW_OP_fbreg` location uses.
///
/// X29 becomes the frame pointer after the prologue instruction that sets it
/// from SP. Inside a block it stays so until an instruction writes X29 again
/// (an epilogue reload); that instruction still executes with the old value,
/// so it ends the range inclusively. A later block in layout order is reached
/// only by a branch from frame-pointer code, so it starts valid again. A
/// function that never sets X29 from SP (a frameless leaf) has no range.
fn frame_pointer_valid_ranges(ir_func: &IrMachFunction) -> Vec<(u32, u32)> {
    let sets_fp_from_sp = |inst: &IrMachInst| {
        inst_clobbers_dwarf_register(inst, AARCH64_DWARF_FP)
            && inst.operands.iter().any(|operand| {
                matches!(
                    operand,
                    IrOperand::Special(trust_cg_ir::regs::SpecialReg::SP)
                )
            })
    };
    let mut ranges = Vec::new();
    let mut established = false;
    let mut offset = 0u32;
    for block_id in &ir_func.block_order {
        let block = &ir_func.blocks[block_id.0 as usize];
        let mut open = established.then_some(offset);
        for &inst_id in &block.insts {
            let inst = &ir_func.insts[inst_id.0 as usize];
            if inst.is_pseudo() {
                continue;
            }
            let end = offset.saturating_add(4);
            if !established {
                if sets_fp_from_sp(inst) {
                    established = true;
                    open = Some(end);
                }
            } else if inst_clobbers_dwarf_register(inst, AARCH64_DWARF_FP)
                && let Some(start) = open.take()
            {
                ranges.push((start, end));
            }
            offset = end;
        }
        if let Some(start) = open
            && start < offset
        {
            ranges.push((start, offset));
        }
    }
    ranges
}

/// Restrict every frame-base-relative (`DW_OP_fbreg`) location to the code
/// where X29 is the frame pointer. Outside those ranges the expression would
/// address the caller's frame, so the value is described as unavailable
/// there instead. A single-expression `FrameOffset` becomes a location list
/// over exactly those ranges; register and constant locations are unchanged.
fn clip_frame_base_location(
    location: crate::dwarf_info::VariableLocation,
    fp_ranges: &[(u32, u32)],
) -> Result<crate::dwarf_info::VariableLocation, PipelineError> {
    use crate::dwarf_info::{LocationListEntry, VariableLocation};
    const DW_OP_FBREG: u8 = 0x91;

    let clip = |entry: &LocationListEntry| -> Vec<LocationListEntry> {
        let start = entry.low_pc;
        let end = entry.low_pc + u64::from(entry.size);
        fp_ranges
            .iter()
            .filter_map(|&(lo, hi)| {
                let lo = start.max(u64::from(lo));
                let hi = end.min(u64::from(hi));
                (lo < hi).then(|| LocationListEntry {
                    low_pc: lo,
                    size: (hi - lo) as u32,
                    expression: entry.expression.clone(),
                })
            })
            .collect()
    };
    Ok(match location {
        VariableLocation::FrameOffset(_) => {
            let expression = crate::dwarf_info::try_encode_location_expr(&location)?;
            VariableLocation::LocationList(
                fp_ranges
                    .iter()
                    .filter(|(lo, hi)| lo < hi)
                    .map(|&(lo, hi)| LocationListEntry {
                        low_pc: u64::from(lo),
                        size: hi - lo,
                        expression: expression.clone(),
                    })
                    .collect(),
            )
        }
        VariableLocation::LocationList(entries) => {
            let mut clipped = Vec::with_capacity(entries.len());
            for entry in &entries {
                if entry.expression.first() == Some(&DW_OP_FBREG) {
                    clipped.extend(clip(entry));
                } else {
                    clipped.push(entry.clone());
                }
            }
            clipped.sort_by_key(|entry| (entry.low_pc, entry.size));
            VariableLocation::LocationList(clipped)
        }
        other => other,
    })
}

fn operand_aliases_dwarf_register(operand: &IrOperand, dwarf_reg: u64) -> bool {
    let IrOperand::PReg(preg) = operand else {
        return false;
    };

    if matches!(*preg, XZR | WZR) {
        return false;
    }

    dwarf_register_number(*preg) == dwarf_reg
}

fn call_clobbers_dwarf_register(dwarf_reg: u64) -> bool {
    trust_cg_regalloc::aarch64_caller_saved_regs()
        .into_iter()
        .any(|preg| dwarf_register_number(preg) == dwarf_reg)
}

fn inst_clobbers_dwarf_register(inst: &IrMachInst, dwarf_reg: u64) -> bool {
    if inst.flags.contains(trust_cg_ir::inst::InstFlags::IS_CALL)
        && call_clobbers_dwarf_register(dwarf_reg)
    {
        return true;
    }

    let (def_positions, _) = classify_operand_positions(inst);
    def_positions.iter().any(|&pos| {
        inst.operands
            .get(pos)
            .is_some_and(|operand| operand_aliases_dwarf_register(operand, dwarf_reg))
    })
}

fn encoded_instruction_offsets(ir_func: &IrMachFunction) -> Vec<(InstId, u32)> {
    let mut offsets = Vec::new();
    let mut offset = 0u32;
    for block_id in &ir_func.block_order {
        let block = &ir_func.blocks[block_id.0 as usize];
        for &inst_id in &block.insts {
            let inst = &ir_func.insts[inst_id.0 as usize];
            if inst.is_pseudo() {
                continue;
            }
            offsets.push((inst_id, offset));
            offset = offset.saturating_add(4);
        }
    }
    offsets
}

fn entry_register_range_size(
    ir_func: &IrMachFunction,
    dwarf_reg: u64,
    code_size: u32,
) -> Option<u32> {
    if code_size == 0 {
        return None;
    }

    let mut body_size = 0u32;
    for (inst_id, offset) in encoded_instruction_offsets(ir_func) {
        body_size = offset.saturating_add(4);
        let inst = &ir_func.insts[inst_id.0 as usize];
        if inst_clobbers_dwarf_register(inst, dwarf_reg) {
            return (offset > 0).then_some(offset.min(code_size));
        }
    }

    let size = body_size.min(code_size);
    (size > 0).then_some(size)
}

fn bounded_dwarf_param_location(
    ir_func: &IrMachFunction,
    loc: &ArgLocation,
    frame_layout: Option<&crate::frame::FrameLayout>,
    code_size: u32,
) -> crate::dwarf_info::VariableLocation {
    match loc {
        ArgLocation::Reg(preg) => {
            let dwarf_reg = dwarf_register_number(*preg);
            let Some(size) = entry_register_range_size(ir_func, dwarf_reg, code_size) else {
                return crate::dwarf_info::VariableLocation::LocationList(Vec::new());
            };
            crate::dwarf_info::VariableLocation::location_list(
                0,
                size,
                crate::dwarf_info::VariableLocation::Register(dwarf_reg),
            )
        }
        _ => dwarf_param_location(loc, frame_layout),
    }
}

fn alloca_debug_stack_slot_from_provenance_var(
    ir_func: &IrMachFunction,
    var_id: TrustIrVarId,
) -> Option<StackSlotId> {
    if var_id.0 & !DEBUG_PROVENANCE_VAR_INDEX_MASK != ALLOCA_DEBUG_PROVENANCE_VAR_TAG {
        return None;
    }
    let slot = var_id.0 & DEBUG_PROVENANCE_VAR_INDEX_MASK;
    let slot_id = StackSlotId(slot);
    ir_func
        .stack_slots
        .get(slot_id.0 as usize)
        .and_then(|stack_slot| stack_slot.fixed_size())
        .map(|_| slot_id)
}

fn const_value_debug_trust_ir_origin_from_provenance_var(
    var_id: TrustIrVarId,
) -> Option<trust_cg_ir::TrustIrInstId> {
    if var_id.0 & !DEBUG_PROVENANCE_VAR_INDEX_MASK != CONST_VALUE_DEBUG_PROVENANCE_VAR_TAG {
        return None;
    }
    Some(trust_cg_ir::TrustIrInstId(
        var_id.0 & DEBUG_PROVENANCE_VAR_INDEX_MASK,
    ))
}

fn value_debug_trust_ir_origin_from_provenance_var(
    var_id: TrustIrVarId,
) -> Option<trust_cg_ir::TrustIrInstId> {
    if var_id.0 & !DEBUG_PROVENANCE_VAR_INDEX_MASK != VALUE_DEBUG_PROVENANCE_VAR_TAG {
        return None;
    }
    Some(trust_cg_ir::TrustIrInstId(
        var_id.0 & DEBUG_PROVENANCE_VAR_INDEX_MASK,
    ))
}

fn debug_value_binding_vregs(
    input: &trust_cg_lower::Function,
    value_map: Option<
        &HashMap<trust_cg_lower::instructions::Value, trust_cg_lower::isel::ISelOperand>,
    >,
) -> BTreeMap<TrustIrVarId, VReg> {
    let Some(value_map) = value_map else {
        return BTreeMap::new();
    };

    input
        .debug_value_bindings
        .iter()
        .filter_map(|binding| match value_map.get(&binding.value) {
            Some(trust_cg_lower::isel::ISelOperand::VReg(vreg)) => Some((binding.var_id, *vreg)),
            _ => None,
        })
        .collect()
}

fn debug_base_type_bit_width(ty: DebugBaseType) -> u16 {
    match ty {
        DebugBaseType::Bool => 1,
        DebugBaseType::I8 | DebugBaseType::U8 => 8,
        DebugBaseType::I16 | DebugBaseType::U16 => 16,
        DebugBaseType::I32 | DebugBaseType::U32 | DebugBaseType::F32 => 32,
        DebugBaseType::I64 | DebugBaseType::U64 | DebugBaseType::F64 | DebugBaseType::Ptr => 64,
        DebugBaseType::I128 | DebugBaseType::U128 => 128,
    }
}

fn const_debug_value_mask(bit_width: u16) -> Option<u128> {
    match bit_width {
        0 => None,
        width if width <= 64 => Some((1u128 << width) - 1),
        _ => None,
    }
}

fn imm16_operand(inst: &IrMachInst, index: usize) -> Option<u128> {
    let imm = inst.operands.get(index)?.as_imm()?;
    (0..=0xffff).contains(&imm).then_some(imm as u128)
}

fn mov_shift_operand(inst: &IrMachInst) -> Option<u32> {
    let shift = match inst.operands.as_slice() {
        [_, _] => 0,
        [_, _, IrOperand::Imm(shift)] => *shift,
        _ => return None,
    };
    matches!(shift, 0 | 16 | 32 | 48).then_some(shift as u32)
}

fn inst_position(ir_func: &IrMachFunction, inst_id: InstId) -> Option<usize> {
    let mut position = 0usize;
    for block_id in &ir_func.block_order {
        let block = ir_func.blocks.get(block_id.0 as usize)?;
        for &candidate in &block.insts {
            if candidate == inst_id {
                return Some(position);
            }
            position = position.saturating_add(1);
        }
    }
    None
}

fn const_value_from_materialization_chain(
    ir_func: &IrMachFunction,
    origin_insts: &[InstId],
    bit_width: u16,
) -> Option<(InstId, u128)> {
    let mask = const_debug_value_mask(bit_width)?;
    let mut ordered: Vec<(usize, InstId)> = origin_insts
        .iter()
        .copied()
        .filter_map(|inst_id| inst_position(ir_func, inst_id).map(|position| (position, inst_id)))
        .collect();
    ordered.sort_by_key(|(position, _)| *position);

    for (seed_position, seed_id) in ordered.iter().copied() {
        let seed = ir_func.insts.get(seed_id.0 as usize)?;
        let Some(dst) = seed.operands.first() else {
            continue;
        };
        let mut value = match seed.opcode {
            IrOpcode::MovI => {
                if seed.operands.len() != 2 {
                    return None;
                }
                let imm = u64::try_from(seed.operands.get(1)?.as_imm()?).ok()?;
                u128::from(imm) & mask
            }
            IrOpcode::Movz => {
                let imm = imm16_operand(seed, 1)?;
                let shift = mov_shift_operand(seed)?;
                if shift != 0 || shift >= u32::from(bit_width) {
                    return None;
                }
                (imm << shift) & mask
            }
            IrOpcode::Movn => {
                let imm = imm16_operand(seed, 1)?;
                let shift = mov_shift_operand(seed)?;
                if shift != 0 || shift >= u32::from(bit_width) {
                    return None;
                }
                (!(imm << shift)) & mask
            }
            _ => continue,
        };

        for (position, inst_id) in ordered.iter().copied() {
            if position <= seed_position {
                continue;
            }
            let inst = ir_func.insts.get(inst_id.0 as usize)?;
            if inst.opcode != IrOpcode::Movk || inst.operands.first() != Some(dst) {
                continue;
            }
            let imm = imm16_operand(inst, 1)?;
            let shift = mov_shift_operand(inst)?;
            if shift >= u32::from(bit_width) {
                return None;
            }
            let field_mask = (0xffffu128 << shift) & mask;
            value = (value & !field_mask) | ((imm << shift) & mask);
        }

        return Some((seed_id, value & mask));
    }

    None
}

fn emitted_function_inst_range(ir_func: &IrMachFunction) -> Option<(InstId, InstId)> {
    let start = ir_func.block_order.iter().find_map(|block_id| {
        ir_func
            .blocks
            .get(block_id.0 as usize)
            .and_then(|block| block.insts.first().copied())
    })?;
    let end = InstId(u32::try_from(ir_func.insts.len()).unwrap_or(u32::MAX));
    (start < end).then_some((start, end))
}

fn seed_stack_alloca_debug_provenance(
    ir_func: &IrMachFunction,
    provenance: &mut Option<trust_cg_ir::ProvenanceMap>,
) -> Result<(), PipelineError> {
    let Some((start, end)) = emitted_function_inst_range(ir_func) else {
        return Ok(());
    };

    let declarations: Vec<_> = ir_func
        .debug_meta
        .local_variables
        .iter()
        .filter_map(|local| {
            let DebugVariableStorage::ProvenanceVar(var_id) = local.storage else {
                return None;
            };
            let slot = alloca_debug_stack_slot_from_provenance_var(ir_func, var_id)?;
            let already_declared = provenance
                .as_ref()
                .is_some_and(|map| !map.var_live_ranges(var_id).is_empty());
            (!already_declared).then_some((
                var_id,
                VarLocation::new(var_id, start, end, LocationExpr::Stack(slot)),
            ))
        })
        .collect();

    if declarations.is_empty() {
        return Ok(());
    }

    let provenance = provenance.get_or_insert_with(trust_cg_ir::ProvenanceMap::new);
    for (var_id, loc) in declarations {
        if provenance.var_live_ranges(var_id).is_empty() {
            declare_debug_var(provenance, var_id, loc)?;
        }
    }
    Ok(())
}

fn declare_debug_var(
    provenance: &mut trust_cg_ir::ProvenanceMap,
    var_id: TrustIrVarId,
    loc: VarLocation,
) -> Result<(), PipelineError> {
    provenance.declare_var(var_id, loc).map_err(|err| {
        PipelineError::DebugProvenance(format!(
            "failed to declare debug variable {var_id:?}: {err:?}"
        ))
    })
}

fn register_debug_value_preg(snapshot: &RegAllocDebugSnapshot, inst_id: InstId) -> Option<PReg> {
    match snapshot.defs.get(&inst_id).copied()? {
        RegAllocDebugDef::VReg(vreg) => {
            if snapshot.spilled_vregs.contains(&vreg) {
                return None;
            }
            allocated_preg_for_vreg(vreg, &snapshot.allocation)
        }
        RegAllocDebugDef::PReg(preg) => Some(preg),
    }
    .filter(|preg| *preg != XZR && *preg != WZR)
}

fn active_single_origin_inst(
    provenance: &trust_cg_ir::ProvenanceMap,
    snapshot: &RegAllocDebugSnapshot,
    origin: trust_cg_ir::TrustIrInstId,
) -> Option<InstId> {
    let origin_insts = provenance.get_mach_insts(origin)?;
    let [origin_inst] = origin_insts else {
        return None;
    };
    if !provenance
        .get_entry(*origin_inst)
        .is_some_and(|entry| entry.is_active())
    {
        return None;
    }
    snapshot
        .inst_map
        .get(origin_inst.0 as usize)
        .copied()
        .flatten()
}

fn active_origin_insts(
    provenance: &trust_cg_ir::ProvenanceMap,
    snapshot: &RegAllocDebugSnapshot,
    origin: trust_cg_ir::TrustIrInstId,
) -> Vec<InstId> {
    let Some(origin_insts) = provenance.get_mach_insts(origin) else {
        return Vec::new();
    };

    origin_insts
        .iter()
        .copied()
        .filter(|inst| {
            provenance
                .get_entry(*inst)
                .is_some_and(|entry| entry.is_active())
        })
        .filter_map(|inst| snapshot.inst_map.get(inst.0 as usize).copied().flatten())
        .collect()
}

fn function_end_inst(ir_func: &IrMachFunction) -> InstId {
    InstId(u32::try_from(ir_func.insts.len()).unwrap_or(u32::MAX))
}

fn next_layout_inst_or_end(ir_func: &IrMachFunction, inst_id: InstId) -> Option<InstId> {
    let mut seen_inst = false;
    for block_id in &ir_func.block_order {
        let block = ir_func.blocks.get(block_id.0 as usize)?;
        for &candidate in &block.insts {
            if seen_inst {
                return Some(candidate);
            }
            seen_inst = candidate == inst_id;
        }
    }
    seen_inst.then_some(function_end_inst(ir_func))
}

fn previous_non_pseudo_layout_inst(ir_func: &IrMachFunction, inst_id: InstId) -> Option<InstId> {
    let mut previous = None;
    for block_id in &ir_func.block_order {
        let block = ir_func.blocks.get(block_id.0 as usize)?;
        for &candidate in &block.insts {
            if candidate == inst_id {
                return previous;
            }
            if !ir_func.inst(candidate).is_pseudo() {
                previous = Some(candidate);
            }
        }
    }
    None
}

fn unique_spilled_vreg_for_slot(
    snapshot: &RegAllocDebugSnapshot,
    slot: StackSlotId,
) -> Option<VReg> {
    let mut owner = None;
    for (&vreg, &candidate_slot) in &snapshot.spill_slots {
        if candidate_slot != slot {
            continue;
        }
        if owner.replace(vreg).is_some() {
            return None;
        }
    }
    owner
}

fn spilled_debug_value_slot(
    snapshot: &RegAllocDebugSnapshot,
    inst_id: InstId,
) -> Option<(VReg, StackSlotId)> {
    let RegAllocDebugDef::VReg(vreg) = snapshot.defs.get(&inst_id).copied()? else {
        return None;
    };
    spilled_debug_value_slot_for_vreg(snapshot, vreg)
}

fn spilled_debug_value_slot_for_vreg(
    snapshot: &RegAllocDebugSnapshot,
    vreg: VReg,
) -> Option<(VReg, StackSlotId)> {
    if !matches!(vreg.class, RegClass::Gpr32 | RegClass::Gpr64) {
        return None;
    }
    if !snapshot.spilled_vregs.contains(&vreg)
        || allocated_preg_for_vreg(vreg, &snapshot.allocation).is_some()
    {
        return None;
    }
    let slot = snapshot.spill_slots.get(&vreg).copied()?;
    (unique_spilled_vreg_for_slot(snapshot, slot)? == vreg).then_some((vreg, slot))
}

fn materialized_spill_store_after_origin(
    ir_func: &IrMachFunction,
    snapshot: &RegAllocDebugSnapshot,
    vreg: VReg,
    slot: StackSlotId,
    origin_inst: InstId,
) -> Option<InstId> {
    let origin_position = inst_position(ir_func, origin_inst)?;
    snapshot
        .spill_stores
        .iter()
        .filter(|store| store.vreg == vreg && store.slot == slot)
        .filter_map(|store| {
            let position = inst_position(ir_func, store.inst)?;
            (position > origin_position).then_some((position, store.inst))
        })
        .min_by_key(|(position, _)| *position)
        .map(|(_, inst)| inst)
}

fn first_spill_store_to_slot_after(
    ir_func: &IrMachFunction,
    snapshot: &RegAllocDebugSnapshot,
    slot: StackSlotId,
    after_inst: InstId,
) -> Option<InstId> {
    let after_position = inst_position(ir_func, after_inst)?;
    snapshot
        .spill_stores
        .iter()
        .filter(|store| store.slot == slot && store.inst != after_inst)
        .filter_map(|store| {
            let position = inst_position(ir_func, store.inst)?;
            (position > after_position).then_some((position, store.inst))
        })
        .min_by_key(|(position, _)| *position)
        .map(|(_, inst)| inst)
}

fn first_materialized_spill_store(
    ir_func: &IrMachFunction,
    snapshot: &RegAllocDebugSnapshot,
    vreg: VReg,
    slot: StackSlotId,
) -> Option<InstId> {
    snapshot
        .spill_stores
        .iter()
        .filter(|store| store.vreg == vreg && store.slot == slot)
        .filter_map(|store| {
            inst_position(ir_func, store.inst).map(|position| (position, store.inst))
        })
        .min_by_key(|(position, _)| *position)
        .map(|(_, inst)| inst)
}

fn spill_debug_value_stack_range(
    ir_func: &IrMachFunction,
    snapshot: &RegAllocDebugSnapshot,
    origin_inst: InstId,
) -> Option<(InstId, InstId, InstId, StackSlotId)> {
    let (vreg, slot) = spilled_debug_value_slot(snapshot, origin_inst)?;
    spill_debug_value_stack_range_for_vreg(ir_func, snapshot, origin_inst, vreg, slot)
}

fn spill_debug_value_stack_range_for_vreg(
    ir_func: &IrMachFunction,
    snapshot: &RegAllocDebugSnapshot,
    origin_inst: InstId,
    vreg: VReg,
    slot: StackSlotId,
) -> Option<(InstId, InstId, InstId, StackSlotId)> {
    if ir_func.block_order.len() != 1 {
        return None;
    }
    let store = materialized_spill_store_after_origin(ir_func, snapshot, vreg, slot, origin_inst)?;
    let start = next_layout_inst_or_end(ir_func, store)?;
    let materializing_store = previous_non_pseudo_layout_inst(ir_func, start)?;
    let end = first_spill_store_to_slot_after(ir_func, snapshot, slot, store)
        .unwrap_or_else(|| function_end_inst(ir_func));
    register_debug_value_position_range(ir_func, start, end)?;
    Some((materializing_store, start, end, slot))
}

fn bound_spill_debug_value_stack_range(
    ir_func: &IrMachFunction,
    snapshot: &RegAllocDebugSnapshot,
    vreg: VReg,
    slot: StackSlotId,
) -> Option<(InstId, InstId, InstId, StackSlotId)> {
    if ir_func.block_order.len() != 1 {
        return None;
    }
    let store = first_materialized_spill_store(ir_func, snapshot, vreg, slot)?;
    let start = next_layout_inst_or_end(ir_func, store)?;
    let materializing_store = previous_non_pseudo_layout_inst(ir_func, start)?;
    let end = first_spill_store_to_slot_after(ir_func, snapshot, slot, store)
        .unwrap_or_else(|| function_end_inst(ir_func));
    register_debug_value_position_range(ir_func, start, end)?;
    Some((materializing_store, start, end, slot))
}

fn inst_defines_overlapping_preg(inst: &IrMachInst, preg: PReg) -> bool {
    let (def_positions, _) = classify_operand_positions(inst);
    def_positions.iter().any(|&pos| {
        matches!(
            inst.operands.get(pos),
            Some(IrOperand::PReg(def)) if regs_overlap(*def, preg)
        )
    }) || inst
        .implicit_defs
        .iter()
        .any(|&def| regs_overlap(def, preg))
}

fn register_debug_value_end(ir_func: &IrMachFunction, start: InstId, preg: PReg) -> Option<InstId> {
    if ir_func.block_order.len() != 1 {
        return None;
    }

    let mut seen_start = false;
    for &block_id in &ir_func.block_order {
        let block = ir_func.blocks.get(block_id.0 as usize)?;
        for &inst_id in &block.insts {
            if !seen_start {
                seen_start = inst_id == start;
                continue;
            }
            let inst = ir_func.insts.get(inst_id.0 as usize)?;
            if !inst.is_pseudo() && inst_defines_overlapping_preg(inst, preg) {
                return Some(inst_id);
            }
        }
    }

    seen_start.then_some(InstId(
        u32::try_from(ir_func.insts.len()).unwrap_or(u32::MAX),
    ))
}

fn register_debug_value_position_range(
    ir_func: &IrMachFunction,
    start: InstId,
    end: InstId,
) -> Option<(usize, usize)> {
    // `ProvenanceMap::declare_var` validates half-open ranges on the RAW
    // instruction IDs (`start < end` in arena-id order), while `start`/`end`
    // here are discovered in LAYOUT order. Post-RA layout can place an
    // early-arena-id instruction after a later one (e.g. a frame-address
    // materialization created during stack rewriting but appended late in
    // the block), so a range that is well-formed in layout positions can
    // still be inverted in raw IDs. Such a range is unrepresentable under
    // the provenance contract: drop it — the variable simply gets no DWARF
    // location, which is strictly better than `declare_var` fail-closing
    // the whole compilation with `InvalidRange`.
    if start >= end {
        return None;
    }
    let start_position = inst_position(ir_func, start)?;
    let end_position = if end.0 as usize >= ir_func.insts.len() {
        ir_func
            .block_order
            .iter()
            .filter_map(|block_id| ir_func.blocks.get(block_id.0 as usize))
            .map(|block| block.insts.len())
            .sum()
    } else {
        inst_position(ir_func, end)?
    };
    (start_position < end_position).then_some((start_position, end_position))
}

fn seed_spilled_value_debug_provenance(
    ir_func: &IrMachFunction,
    provenance: &mut Option<trust_cg_ir::ProvenanceMap>,
    snapshot: &RegAllocDebugSnapshot,
    debug_value_bindings: &BTreeMap<TrustIrVarId, VReg>,
) -> Result<(), PipelineError> {
    let Some(existing_provenance) = provenance.as_ref() else {
        return Ok(());
    };
    let declarations: Vec<_> = ir_func
        .debug_meta
        .local_variables
        .iter()
        .filter_map(|local| {
            if debug_base_type_bit_width(local.ty) > 64 {
                return None;
            }
            let DebugVariableStorage::ProvenanceVar(var_id) = local.storage else {
                return None;
            };
            let origin = value_debug_trust_ir_origin_from_provenance_var(var_id)?;
            if !existing_provenance.var_live_ranges(var_id).is_empty() {
                return None;
            }
            let mut ranges = Vec::new();
            let mut seen = BTreeSet::new();
            let active_origin_insts = active_origin_insts(existing_provenance, snapshot, origin);
            if let Some(bound_vreg) = debug_value_bindings.get(&var_id).copied()
                && matches!(bound_vreg.class, RegClass::Gpr32 | RegClass::Gpr64)
                && snapshot.spilled_vregs.contains(&bound_vreg)
                && allocated_preg_for_vreg(bound_vreg, &snapshot.allocation).is_none()
                && let Some(bound_slot) = snapshot.spill_slots.get(&bound_vreg).copied()
            {
                for origin_inst in &active_origin_insts {
                    let Some((store, start, end, slot)) = spill_debug_value_stack_range_for_vreg(
                        ir_func,
                        snapshot,
                        *origin_inst,
                        bound_vreg,
                        bound_slot,
                    ) else {
                        continue;
                    };
                    if seen.insert((start, end, slot)) {
                        ranges.push((
                            Some((*origin_inst, store)),
                            VarLocation::new(var_id, start, end, LocationExpr::Stack(slot)),
                        ));
                    }
                }
                if ranges.is_empty()
                    && let Some((store, start, end, slot)) = bound_spill_debug_value_stack_range(
                        ir_func, snapshot, bound_vreg, bound_slot,
                    )
                    && seen.insert((start, end, slot))
                {
                    let clone_edge = active_origin_insts
                        .first()
                        .copied()
                        .map(|origin_inst| (origin_inst, store));
                    ranges.push((
                        clone_edge,
                        VarLocation::new(var_id, start, end, LocationExpr::Stack(slot)),
                    ));
                }
            }
            if ranges.is_empty() {
                for origin_inst in active_origin_insts {
                    let Some((store, start, end, slot)) =
                        spill_debug_value_stack_range(ir_func, snapshot, origin_inst)
                    else {
                        continue;
                    };
                    if seen.insert((start, end, slot)) {
                        ranges.push((
                            Some((origin_inst, store)),
                            VarLocation::new(var_id, start, end, LocationExpr::Stack(slot)),
                        ));
                    }
                }
            }
            (!ranges.is_empty()).then_some((var_id, ranges))
        })
        .collect();

    if declarations.is_empty() {
        return Ok(());
    }

    let provenance = provenance.get_or_insert_with(trust_cg_ir::ProvenanceMap::new);
    for (var_id, ranges) in declarations {
        if provenance.var_live_ranges(var_id).is_empty() {
            for (clone_edge, loc) in ranges {
                if let Some((origin_inst, store)) = clone_edge {
                    provenance.record_clone(
                        origin_inst,
                        store,
                        trust_cg_ir::PassId::new("codegen-debug-spill-materialization"),
                    );
                }
                declare_debug_var(provenance, var_id, loc)?;
            }
        }
    }
    Ok(())
}

fn seed_register_value_debug_provenance(
    ir_func: &IrMachFunction,
    provenance: &mut Option<trust_cg_ir::ProvenanceMap>,
    snapshot: &RegAllocDebugSnapshot,
) -> Result<(), PipelineError> {
    let Some(existing_provenance) = provenance.as_ref() else {
        return Ok(());
    };
    let declarations: Vec<_> = ir_func
        .debug_meta
        .local_variables
        .iter()
        .filter_map(|local| {
            if debug_base_type_bit_width(local.ty) > 64 {
                return None;
            }
            let DebugVariableStorage::ProvenanceVar(var_id) = local.storage else {
                return None;
            };
            let origin = value_debug_trust_ir_origin_from_provenance_var(var_id)?;
            if !existing_provenance.var_live_ranges(var_id).is_empty() {
                return None;
            }
            let start = active_single_origin_inst(existing_provenance, snapshot, origin)?;
            let inst = ir_func.insts.get(start.0 as usize)?;
            if inst.is_pseudo() {
                return None;
            }
            let preg = register_debug_value_preg(snapshot, start)?;
            let end = register_debug_value_end(ir_func, start, preg)?;
            register_debug_value_position_range(ir_func, start, end)?;
            Some((
                var_id,
                VarLocation::new(var_id, start, end, LocationExpr::Reg(preg)),
            ))
        })
        .collect();

    if declarations.is_empty() {
        return Ok(());
    }

    let provenance = provenance.get_or_insert_with(trust_cg_ir::ProvenanceMap::new);
    for (var_id, loc) in declarations {
        if provenance.var_live_ranges(var_id).is_empty() {
            declare_debug_var(provenance, var_id, loc)?;
        }
    }
    Ok(())
}

fn seed_constant_value_debug_provenance(
    ir_func: &IrMachFunction,
    provenance: &mut Option<trust_cg_ir::ProvenanceMap>,
) -> Result<(), PipelineError> {
    let Some(existing_provenance) = provenance.as_ref() else {
        return Ok(());
    };
    let function_end = InstId(u32::try_from(ir_func.insts.len()).unwrap_or(u32::MAX));
    let declarations: Vec<_> = ir_func
        .debug_meta
        .local_variables
        .iter()
        .filter_map(|local| {
            let DebugVariableStorage::ProvenanceVar(var_id) = local.storage else {
                return None;
            };
            let origin = const_value_debug_trust_ir_origin_from_provenance_var(var_id)?;
            if !existing_provenance.var_live_ranges(var_id).is_empty() {
                return None;
            }
            let bit_width = debug_base_type_bit_width(local.ty);
            let (start, value) = const_value_from_materialization_chain(
                ir_func,
                existing_provenance.get_mach_insts(origin)?,
                bit_width,
            )?;
            (start < function_end).then_some((
                var_id,
                VarLocation::new(
                    var_id,
                    start,
                    function_end,
                    LocationExpr::Const { value, bit_width },
                ),
            ))
        })
        .collect();

    if declarations.is_empty() {
        return Ok(());
    }

    let provenance = provenance.get_or_insert_with(trust_cg_ir::ProvenanceMap::new);
    for (var_id, loc) in declarations {
        if provenance.var_live_ranges(var_id).is_empty() {
            declare_debug_var(provenance, var_id, loc)?;
        }
    }
    Ok(())
}

fn provenance_debug_variable_location(
    adapter: Option<&crate::debug_provenance::DebugProvenanceAdapter<'_>>,
    var_id: trust_cg_ir::provenance::TrustIrVarId,
) -> crate::dwarf_info::VariableLocation {
    let entries = adapter
        .map(|adapter| adapter.location_list_entries(var_id))
        .unwrap_or_default();

    crate::dwarf_info::VariableLocation::LocationList(entries)
}

fn build_debug_variables(
    ir_func: &IrMachFunction,
    debug_meta: &trust_cg_ir::function::FunctionDebugMeta,
    frame_layout: Option<&crate::frame::FrameLayout>,
    code_size: u32,
    provenance: Option<&trust_cg_ir::ProvenanceMap>,
) -> Vec<crate::dwarf_info::VariableDebugInfo> {
    let stack_slot_offsets = frame_layout
        .map(|layout| crate::frame::stack_slot_frame_offsets(ir_func, layout))
        .unwrap_or_default();
    let debug_provenance_locals = debug_meta.local_variables.iter().filter_map(|local| {
        let DebugVariableStorage::ProvenanceVar(var_id) = local.storage else {
            return None;
        };
        Some(crate::debug_provenance::DebugProvenanceLocal::new(
            var_id,
            debug_base_type_bit_width(local.ty),
            alloca_debug_stack_slot_from_provenance_var(ir_func, var_id),
        ))
    });
    let debug_provenance_adapter = provenance.map(|provenance| {
        crate::debug_provenance::DebugProvenanceAdapter::new(
            ir_func,
            provenance,
            &stack_slot_offsets,
            code_size,
            debug_provenance_locals,
        )
    });
    let mut claimed_source_slots = BTreeSet::new();
    for local in &debug_meta.local_variables {
        if let DebugVariableStorage::ProvenanceVar(var_id) = local.storage
            && let Some(slot) = alloca_debug_stack_slot_from_provenance_var(ir_func, var_id)
        {
            claimed_source_slots.insert(slot.0 as usize);
        }
    }
    let mut variables: Vec<crate::dwarf_info::VariableDebugInfo> = debug_meta
        .local_variables
        .iter()
        .filter_map(|local| match local.storage {
            DebugVariableStorage::StackSlot(slot) => {
                let slot_idx = slot as usize;
                let ir_slot = ir_func.stack_slots.get(slot_idx)?;
                ir_slot.fixed_size()?;
                let frame_offset = stack_slot_offsets.get(slot_idx).copied().flatten()?;
                claimed_source_slots.insert(slot_idx);
                let frame_location =
                    crate::dwarf_info::VariableLocation::FrameOffset(i64::from(frame_offset));
                Some(crate::dwarf_info::VariableDebugInfo {
                    name: local.name.clone(),
                    type_index: dwarf_standard_type_index(local.ty),
                    location: crate::dwarf_info::VariableLocation::location_list(
                        0,
                        code_size,
                        frame_location,
                    ),
                })
            }
            DebugVariableStorage::ConstantInt(value) => {
                Some(crate::dwarf_info::VariableDebugInfo {
                    name: local.name.clone(),
                    type_index: dwarf_standard_type_index(local.ty),
                    location: crate::dwarf_info::VariableLocation::ConstantInt(value),
                })
            }
            DebugVariableStorage::ProvenanceVar(var_id) => {
                Some(crate::dwarf_info::VariableDebugInfo {
                    name: local.name.clone(),
                    type_index: dwarf_standard_type_index(local.ty),
                    location: provenance_debug_variable_location(
                        debug_provenance_adapter.as_ref(),
                        var_id,
                    ),
                })
            }
        })
        .collect();

    variables.extend(
        ir_func
            .stack_slots
            .iter()
            .enumerate()
            .filter_map(|(i, slot)| {
                if claimed_source_slots.contains(&i) {
                    return None;
                }
                let size = slot.fixed_size()?;
                let frame_offset = stack_slot_offsets.get(i).copied().flatten()?;
                if size == 0 {
                    return None;
                }
                // Map slot size to a base type index.
                let type_index = match size {
                    1 => 0, // i8
                    2 => 1, // i16
                    4 => 2, // i32
                    8 => 3, // i64
                    _ => 3, // default i64
                };
                Some(crate::dwarf_info::VariableDebugInfo {
                    name: format!("local_{}", i),
                    type_index,
                    location: crate::dwarf_info::VariableLocation::FrameOffset(i64::from(
                        frame_offset,
                    )),
                })
            }),
    );

    variables
}

/// Buffered sink for `[trust-cg-time-pipeline]` records.
///
/// WHY THIS IS BUFFERED: phases NEST — `optimization` brackets
/// `opt-pass-manager`, `cegis-superopt` and `codegen-scheduler`. An `eprintln!`
/// per event is an unbuffered write syscall, and every inner event's syscall
/// lands INSIDE the outer phase's measured region. The profiler was charging
/// its own I/O to the phase it was measuring.
///
/// Measured before this change: `TRUST_CG_TIME_PIPELINE=1` cost **+10.1ms on a
/// 152ms compile** (h2_vec_grow) and +3.1ms on p1_xorshift, and it manufactured
/// an apparent ~2-3ms of "unattributed work inside optimization" that was
/// simply the nested prints. A profiler that distorts what it measures by 6.6%
/// cannot be used to chase a 25ms gap.
///
/// Records are accumulated per thread and flushed when the thread ends, so the
/// measured region pays a `String` push instead of a syscall.
struct PipelinePhaseLog {
    lines: Vec<String>,
}

impl PipelinePhaseLog {
    fn flush(&mut self) {
        if self.lines.is_empty() {
            return;
        }
        use std::io::Write;
        let stderr = std::io::stderr();
        let mut out = stderr.lock();
        for line in self.lines.drain(..) {
            let _ = writeln!(out, "{line}");
        }
        let _ = out.flush();
    }
}

impl Drop for PipelinePhaseLog {
    fn drop(&mut self) {
        self.flush();
    }
}

thread_local! {
    static PIPELINE_PHASE_LOG: std::cell::RefCell<PipelinePhaseLog> =
        const { std::cell::RefCell::new(PipelinePhaseLog { lines: Vec::new() }) };
}

fn pipeline_phase_record(line: String) {
    PIPELINE_PHASE_LOG.with(|log| log.borrow_mut().lines.push(line));
}

/// Flush optimization-pass and pipeline timings accumulated by the calling
/// thread.
///
/// Reusable compiler worker threads call this at a task boundary because their
/// thread-local destructors do not run until the process exits.
#[doc(hidden)]
pub fn flush_current_thread_timing_logs() {
    trust_cg_opt::pass_manager::flush_current_thread_pass_time_log();
    if trust_cg_time_pipeline_enabled() {
        PIPELINE_PHASE_LOG.with(|log| log.borrow_mut().flush());
    }
}

/// RAII phase timer: records on scope EXIT.
///
/// The explicit start/end pair cannot wrap a body full of `?` early returns,
/// which is exactly the shape of encoding and the post-RA recheck — and those
/// were the largest untimed blocks left. Measured budget before this: our
/// instrumented stages accounted for only ~36-39% of trust-cg's own codegen
/// time, so most of the gap was in code no phase timer reached.
struct PhaseGuard<'a> {
    func: &'a IrMachFunction,
    phase: &'static str,
    start: Option<Instant>,
}

impl<'a> PhaseGuard<'a> {
    fn new(func: &'a IrMachFunction, phase: &'static str) -> Self {
        Self {
            func,
            phase,
            start: if trust_cg_time_pipeline_enabled() {
                Some(Instant::now())
            } else {
                None
            },
        }
    }
}

impl Drop for PhaseGuard<'_> {
    fn drop(&mut self) {
        let Some(start) = self.start else {
            return;
        };
        // Clock first; the shape walk and the record are instrumentation.
        let elapsed_us = start.elapsed().as_micros();
        let (blocks, insts) = ir_function_shape(self.func);
        let phase = self.phase;
        pipeline_phase_record(format!(
            "[trust-cg-time-pipeline] end func={} phase={phase} elapsed_us={elapsed_us} \
             blocks={blocks} insts={insts}",
            self.func.name
        ));
    }
}

fn log_pipeline_phase_start(func: &IrMachFunction, phase: &str) -> Option<Instant> {
    if !trust_cg_time_pipeline_enabled() {
        return None;
    }
    // No `ir_function_shape` here: it walks the whole function, and the END
    // record already reports the shape (the post-phase one, which is the
    // meaningful figure anyway). Doing it on both events walked every function
    // twice per phase, inside the enclosing phase's measured region.
    pipeline_phase_record(format!(
        "[trust-cg-time-pipeline] start func={} phase={phase}",
        func.name
    ));
    Some(Instant::now())
}

fn log_pipeline_phase_end(func: &IrMachFunction, phase: &str, start: Option<Instant>) {
    let Some(start) = start else {
        return;
    };
    // Read the clock FIRST: everything below is instrumentation, and charging
    // it to this phase is the bug this buffering exists to remove.
    let elapsed_us = start.elapsed().as_micros();
    let (blocks, insts) = ir_function_shape(func);
    pipeline_phase_record(format!(
        "[trust-cg-time-pipeline] end func={} phase={phase} elapsed_us={elapsed_us} \
         blocks={blocks} insts={insts}",
        func.name
    ));
}

fn build_aarch64_target_machine(
    target: TargetSpec,
    profile: AArch64IsaProfile,
) -> AArch64TargetMachine {
    // The ceiling always contains the profile: an explicit profile is itself
    // a statement of what this target has.
    let ceiling = AArch64IsaProfile::function_feature_ceiling(target)
        .as_set()
        .union(profile.admitted_target_features().as_set())
        .enabled()
        .fold(
            crate::target::AdmittedTargetFeatures::NONE,
            crate::target::AdmittedTargetFeatures::with_aarch64_feature,
        );
    TargetMachine::try_new_with_function_ceiling(target, profile.into(), ceiling).expect(
        "Pipeline must pair an AArch64 target identity with the static AArch64 feature domain",
    )
}

impl Pipeline {
    /// Create a new pipeline with the given configuration.
    ///
    /// Construction is infallible, but the target is not defaulted: an empty
    /// or unrecognized `config.target_triple` resolves to an unknown AArch64
    /// target with the baseline ISA profile, and every target-dependent entry
    /// (instruction selection, register-allocation fix-up, frame lowering,
    /// debug info, object emission) then refuses with
    /// [`PipelineError::TargetAbiUnresolved`] or
    /// [`PipelineError::TargetObjectUnsupported`]. Name the target explicitly
    /// ([`PipelineConfig::for_target`], or [`PipelineConfig::for_host_aarch64`]
    /// for in-process code whose target is by definition the host).
    pub fn new(config: PipelineConfig) -> Self {
        let parsed = TargetSpec::parse(&config.target_triple)
            .ok()
            .filter(|target| target.architecture == Target::Aarch64);
        let (aarch64_target, aarch64_isa_profile) = (
            parsed.unwrap_or_else(|| TargetSpec::unknown_for_architecture(Target::Aarch64)),
            parsed
                .map(AArch64IsaProfile::for_aot_target)
                .unwrap_or(AArch64IsaProfile::BASELINE),
        );
        Self {
            config,
            aarch64_target_machine: build_aarch64_target_machine(
                aarch64_target,
                aarch64_isa_profile,
            ),
            raw_dataflow_policy: Aarch64DataflowIntegrityPolicy::Ambient {
                audit_default_warn: false,
            },
            profile_use: None,
            profile_generate_sink: None,
            certified_pass_execution: false,
            pass_validation: None,
            composed_transitions: None,
            elf_lo12_symbol_alignments: None,
            function_sections: false,
            eh_propagation: EhPropagation::Filler,
            aarch64_integrity_policy: Aarch64IntegrityPolicy::Compatibility,
            #[cfg(feature = "verify")]
            cegis_cache: trust_cg_verify::SharedCegisCache::default_arc(),
            #[cfg(not(feature = "verify"))]
            cegis_cache: Arc::new(trust_cg_opt::InMemoryCache::new()),
            #[cfg(not(feature = "verify"))]
            cegis_warning_emitted: AtomicBool::new(false),
            #[cfg(all(test, feature = "verify"))]
            cegis_test_incomplete_after_first_commit: false,
        }
    }

    #[cfg(all(test, feature = "verify"))]
    fn with_cegis_test_incomplete_after_first_commit(mut self) -> Self {
        self.cegis_test_incomplete_after_first_commit = true;
        self
    }

    /// Resolved AArch64 ISA profile governing this pipeline's emitted bytes.
    ///
    /// Artifact owners should bind [`AArch64IsaProfile::feature_bits`] into their
    /// cache/provenance identity rather than re-deriving target capabilities.
    pub const fn aarch64_isa_profile(&self) -> AArch64IsaProfile {
        AArch64IsaProfile::from_admitted_target_features(
            self.aarch64_target_machine.admitted_features(),
        )
    }

    /// Immutable target identity and typed optional-ISA admission captured by
    /// this AArch64 pipeline.
    pub const fn aarch64_target_machine(&self) -> &AArch64TargetMachine {
        &self.aarch64_target_machine
    }

    /// Bind the already-resolved AArch64 capability profile used by lowering,
    /// optimization, encoding, publication, and artifact identity.
    ///
    /// This is deliberately an additive builder rather than a public config
    /// field: target-feature growth does not create source breaks for generic
    /// compiler clients. Explicit generic/unrecognized targets, and an empty
    /// target, fail closed.
    pub fn with_aarch64_isa_profile(mut self, profile: AArch64IsaProfile) -> Self {
        self.aarch64_target_machine =
            build_aarch64_target_machine(*self.aarch64_target_machine.identity(), profile);
        self
    }

    /// The Mach-O `LC_BUILD_VERSION` for `config.target_triple`: the macOS
    /// platform with the triple's deployment target (`aarch64-apple-macos12.0`)
    /// or the historical 14.0 default for an unversioned Apple triple. Any
    /// other Apple platform and a malformed or too-old version are refused
    /// ([`PipelineError::MachODeploymentTarget`]). The environment is not
    /// read here: drivers capture `MACOSX_DEPLOYMENT_TARGET` into the triple.
    pub fn macho_build_version(
        &self,
    ) -> Result<crate::apple_deployment::MachOBuildVersion, PipelineError> {
        Ok(
            crate::apple_deployment::MachOBuildVersion::for_target_triple(
                &self.config.target_triple,
            )?,
        )
    }

    /// The AArch64 calling convention selected by `config.target_triple`.
    ///
    /// This is the single ABI authority for instruction selection, the
    /// post-allocation formal-copy check, frame lowering and debug-info
    /// parameter locations. An empty or unrecognized triple is a typed refusal
    /// ([`PipelineError::TargetAbiUnresolved`]); it never falls back to
    /// DarwinPCS.
    pub fn resolved_aarch64_abi(&self) -> Result<AArch64AbiVariant, PipelineError> {
        AArch64AbiVariant::from_target_triple(&self.config.target_triple)
            .map_err(PipelineError::TargetAbiUnresolved)
    }

    /// Bind `ir_func`'s stack-limit requirement to the source `input`'s
    /// (custody: the requirement comes from the source, so a cleared or
    /// altered machine-level field is refused) and return the net's
    /// certificate for a requesting function.
    fn certify_aarch64_stack_limit(
        &self,
        input: &trust_cg_lower::Function,
        ir_func: &IrMachFunction,
    ) -> Result<Option<trust_cg_verify::aarch64_stack_limit::StackLimitCertificate>, PipelineError>
    {
        let expected = self.resolve_aarch64_stack_limit(input)?;
        if ir_func.stack_limit != expected {
            return Err(PipelineError::StackLimit {
                function: input.name.clone(),
                reason: format!(
                    "the machine function's requirement {:?} differs from the source's {expected:?}",
                    ir_func.stack_limit
                ),
            });
        }
        let Some(expected) = expected else {
            return Ok(None);
        };
        trust_cg_verify::aarch64_stack_limit::check_against(ir_func, &expected)
            .map(Some)
            .map_err(|violation| PipelineError::StackLimit {
                function: input.name.clone(),
                reason: format!("final stream refused ({violation})"),
            })
    }

    /// Resolve `input`'s U10 stack-limit request to the X register signature
    /// lowering assigns its parameter, with the same classification
    /// instruction selection uses for the function's own formals.
    ///
    /// Refused unless the parameter lands in exactly one of X0-X7 (not on the
    /// stack, not a register pair) and the function has no hidden `sret`
    /// parameter, which would move the classification.
    fn resolve_aarch64_stack_limit(
        &self,
        input: &trust_cg_lower::Function,
    ) -> Result<Option<trust_cg_ir::MachStackLimit>, PipelineError> {
        let Some(request) = &input.stack_limit else {
            return Ok(None);
        };
        let refuse = |reason: String| PipelineError::StackLimit {
            function: input.name.clone(),
            reason,
        };
        if input.abi_sret_param.is_some() {
            return Err(refuse(
                "a function with a hidden sret parameter cannot request a stack limit in v1"
                    .to_string(),
            ));
        }
        let param = usize::from(request.param);
        if input.signature.params.get(param) != Some(&trust_cg_lower::types::Type::I64) {
            return Err(refuse(format!(
                "limit parameter {param} is not one 64-bit integer parameter"
            )));
        }
        let variant = self.resolved_aarch64_abi()?;
        let locations = trust_cg_lower::abi::AppleAArch64ABI::classify_params_with(
            variant,
            &input.signature.params,
        );
        let limit_reg = match locations.get(param) {
            Some(trust_cg_lower::abi::ArgLocation::Reg(reg))
                if trust_cg_ir::regs::preg_class(*reg) == trust_cg_ir::regs::RegClass::Gpr64
                    && reg.hw_enc() < 8 =>
            {
                *reg
            }
            other => {
                return Err(refuse(format!(
                    "limit parameter {param} is passed in {other:?}, not in one of X0-X7"
                )));
            }
        };
        let mut arg_regs = Vec::new();
        for location in &locations {
            match location {
                trust_cg_lower::abi::ArgLocation::Reg(reg)
                | trust_cg_lower::abi::ArgLocation::Indirect { ptr_reg: reg } => {
                    arg_regs.push(*reg)
                }
                trust_cg_lower::abi::ArgLocation::RegPair(low, high) => {
                    arg_regs.extend([*low, *high]);
                }
                trust_cg_lower::abi::ArgLocation::RegSequence(regs) => {
                    arg_regs.extend(regs.iter().copied());
                }
                trust_cg_lower::abi::ArgLocation::Ignore
                | trust_cg_lower::abi::ArgLocation::Stack { .. } => {}
            }
        }
        Ok(Some(trust_cg_ir::MachStackLimit {
            request: request.clone(),
            limit_reg,
            arg_regs,
        }))
    }

    /// Encode every AArch64 function this pipeline publishes at proof grade:
    /// the final-stream reaching-definition, spill-slot and decode nets are
    /// forced to Enforce regardless of `TCG_AARCH64_POST_RA_REACHING_DEF`,
    /// `TCG_AARCH64_POST_RA_SPILL_SLOTS`, `TCG_DECODE_CHECK` or
    /// `TCG_NO_DECODE_CHECK`; any [`AARCH64_LATE_LAYOUT_CONTROLS`] entry is a
    /// typed refusal ([`PipelineError::AmbientLateLayoutControl`]); and the
    /// final-layout cross-check also binds every encoded edge to the recorded
    /// CFG. Proof-required and verifying compiler/JIT routes select this. The
    /// default remains the compatibility policy, whose nets are enforce by
    /// default but keep their diagnostic environment downgrades.
    pub fn with_proof_grade_aarch64_publication(mut self) -> Self {
        self.aarch64_integrity_policy = Aarch64IntegrityPolicy::ProofGradeEnforce;
        self
    }

    /// Select [`Self::with_proof_grade_aarch64_publication`] when `enabled`;
    /// otherwise keep the current policy. Selection is never downgraded.
    pub fn with_proof_grade_aarch64_publication_if(self, enabled: bool) -> Self {
        if enabled {
            self.with_proof_grade_aarch64_publication()
        } else {
            self
        }
    }

    /// Whether [`Self::with_proof_grade_aarch64_publication`] is selected.
    pub fn proof_grade_aarch64_publication(&self) -> bool {
        self.aarch64_integrity_policy == Aarch64IntegrityPolicy::ProofGradeEnforce
    }

    /// The ENC-5 backing of the AArch64 bytes this pipeline encodes: enforced
    /// under proof-grade publication, otherwise whatever
    /// `TCG_DECODE_CHECK_A64`/`TCG_NO_DECODE_CHECK` select. It is the mode
    /// the encode resolves (`aarch64_decode_check_mode_for_integrity_policy`),
    /// read here under the same environment; certificates that cite ENC-5
    /// take it (`compiler::unverified_instruction_certificate`).
    #[cfg(feature = "verify")]
    pub(crate) fn aarch64_decode_check_backing(&self) -> crate::decode_check::DecodeCheckBacking {
        crate::decode_check::DecodeCheckBacking::from_mode(
            aarch64_decode_check_mode_for_integrity_policy(self.aarch64_integrity_policy),
        )
    }

    /// [`Self::aarch64_decode_check_backing`] of a pipeline built with
    /// [`Self::with_proof_grade_aarch64_publication_if`]`(proof_grade)` from
    /// the default (compatibility) policy.
    #[cfg(feature = "verify")]
    pub(crate) fn aarch64_decode_check_backing_if_proof_grade(
        proof_grade: bool,
    ) -> crate::decode_check::DecodeCheckBacking {
        crate::decode_check::DecodeCheckBacking::from_mode(
            aarch64_decode_check_mode_for_integrity_policy(if proof_grade {
                Aarch64IntegrityPolicy::ProofGradeEnforce
            } else {
                Aarch64IntegrityPolicy::Compatibility
            }),
        )
    }

    /// Select the function-sections object policy: on the AArch64 ELF path
    /// every function is emitted into its own `.text.<symbol>` section (and
    /// its FDE anchors that section), so `ld --gc-sections` can drop unused
    /// functions individually. Mach-O ignores it (ld64 dead-strips at atom
    /// granularity). Default `false`: one `.text`, byte-identical to before.
    pub fn with_function_sections(mut self, enabled: bool) -> Self {
        self.function_sections = enabled;
        self
    }

    /// Whether the function-sections object policy is selected.
    pub fn function_sections(&self) -> bool {
        self.function_sections
    }

    /// Select the non-unwinding exception-frame policy
    /// (`CompilerConfig::eh_frames_cannot_unwind`) with the callee symbols
    /// known not to unwind (`CompilerConfig::eh_nounwind_callees`): every
    /// exception-handling function this pipeline encodes is a frame no
    /// exception may propagate out of, and its LSDA applies the region rule
    /// of LLVM's table for such a function to this backend's calls
    /// ([`EhPropagation::NounwindFrame`], which records where that coverage
    /// differs from LLVM's). `None` (the default) keeps the full-coverage
    /// propagation filler, byte-identical to before.
    pub fn with_eh_frames_cannot_unwind(
        mut self,
        nounwind_callees: Option<Arc<BTreeSet<String>>>,
    ) -> Self {
        self.eh_propagation = match nounwind_callees {
            Some(nounwind_callees) => EhPropagation::NounwindFrame { nounwind_callees },
            None => EhPropagation::Filler,
        };
        self
    }

    /// The exception-table propagation policy this pipeline applies.
    pub fn eh_propagation(&self) -> &EhPropagation {
        &self.eh_propagation
    }

    pub(crate) fn with_raw_dataflow_policy(
        mut self,
        policy: Aarch64DataflowIntegrityPolicy,
    ) -> Self {
        self.raw_dataflow_policy = policy;
        self
    }

    /// The raw pre-optimization dataflow-integrity policy this pipeline will
    /// apply. Exposed so admission-layering regressions can be pinned without
    /// compiling a function: the policy is what decides whether a
    /// `[TCG-REGALLOC-063]` boundary violation refuses the compile, and it
    /// must never be a function of whether proof certificates are emitted.
    #[cfg(test)]
    pub(crate) fn raw_dataflow_policy(&self) -> Aarch64DataflowIntegrityPolicy {
        self.raw_dataflow_policy
    }

    /// Resolve an LIR function's stated target features (trust-ir
    /// `FuncAttrs.target_features`) to its own optional-feature admission.
    ///
    /// Every name must be one this backend models (`[TCG-TARGET-FEATURE]`,
    /// refused by name otherwise) and every feature must lie within the
    /// target's function ceiling. An attribute-free function resolves to the
    /// empty set and compiles exactly under the profile.
    pub fn resolve_aarch64_function_target_features(
        &self,
        input: &trust_cg_lower::Function,
    ) -> Result<TargetFeatureSet<AArch64IsaFeature>, PipelineError> {
        let features = trust_cg_ir::aarch64_function_target_features(
            input.target_features.iter().map(String::as_str),
        )
        .map_err(|feature| PipelineError::Aarch64FunctionTargetFeature {
            function: input.name.clone(),
            feature: feature.to_owned(),
            reason: "not an AArch64 target feature this backend models".to_owned(),
        })?;
        self.aarch64_target_machine
            .for_function(features)
            .map_err(|error| {
                let missing = features
                    .difference(self.aarch64_target_machine.function_ceiling().as_set())
                    .enabled()
                    .map(AArch64IsaFeature::name)
                    .next()
                    .unwrap_or_default();
                PipelineError::Aarch64FunctionTargetFeature {
                    function: input.name.clone(),
                    feature: missing.to_owned(),
                    reason: error.to_string(),
                }
            })?;
        Ok(features)
    }

    /// The target machine `func` compiles under: the pipeline profile plus
    /// the function's own target features
    /// ([`IrMachFunction::function_target_features`]).
    fn aarch64_function_target_machine(
        &self,
        func: &IrMachFunction,
    ) -> Result<AArch64TargetMachine, PipelineError> {
        self.aarch64_target_machine
            .for_function(func.function_target_features)
            .map_err(|error| aarch64_target_machine_contract_error(&func.name, error))
    }

    fn aarch64_required_features(
        &self,
        func: &IrMachFunction,
    ) -> Result<OutputTargetFeatures<AArch64IsaFeature>, PipelineError> {
        let target_machine = self.aarch64_function_target_machine(func)?;
        let mut required_features = OutputTargetFeatures::NONE;
        for &block_id in &func.block_order {
            for &inst_id in &func.block(block_id).insts {
                observe_aarch64_inst_isa_requirements(
                    &func.name,
                    func.inst(inst_id),
                    Some(&target_machine),
                    &mut required_features,
                )?;
            }
        }
        target_machine
            .validate_output_features(required_features)
            .map_err(|error| aarch64_target_machine_contract_error(&func.name, error))?;
        Ok(required_features)
    }

    /// Module evidence: every function's output features, admitted by the
    /// profile plus the union of the functions' own target features (the
    /// profile alone when no function states any).
    fn aarch64_module_machine_code_evidence(
        &self,
        functions: &[IrMachFunction],
    ) -> Result<AArch64MachineCodeEvidence, PipelineError> {
        let mut required_features = OutputTargetFeatures::NONE;
        let mut function_features = TargetFeatureSet::EMPTY;
        for func in functions {
            required_features = required_features.union(self.aarch64_required_features(func)?);
            function_features = function_features.union(func.function_target_features);
        }
        let module_machine = self
            .aarch64_target_machine
            .for_function(function_features)
            .map_err(|error| aarch64_target_machine_contract_error("<module>", error))?;
        AArch64MachineCodeEvidence::try_new(&module_machine, required_features)
            .map_err(|error| aarch64_target_machine_contract_error("<module>", error))
    }

    /// Validate structure and optional-ISA admission in the same mandatory
    /// instruction walk. This is the normal compilation boundary; the
    /// scan-only helper remains for module emitters that consume already
    /// validated/prepared functions through legacy APIs.
    fn validate_aarch64_mach_function_for_profile(
        &self,
        func: &IrMachFunction,
    ) -> Result<OutputTargetFeatures<AArch64IsaFeature>, PipelineError> {
        validate_aarch64_mach_function_impl(
            func,
            AArch64CfgValidationStage::SymbolicAuthority,
            Some(&self.aarch64_function_target_machine(func)?),
        )
    }

    /// Report what proof evidence this pipeline configuration actually
    /// produces, and what it relies on rather than checks.
    ///
    /// This is the honest answer for the fast JIT route, which does not build
    /// a compile-service artifact and therefore has nowhere else to carry an
    /// evidence field. A pipeline configured with `verify: false` and
    /// [`DispatchVerifyMode::Off`] — the flagship consumer's configuration —
    /// reports
    /// [`ProofEvidenceVerdict::MissingEvidence`](crate::jit_contract::ProofEvidenceVerdict::MissingEvidence)
    /// at [`EvidenceStrength::NotRun`](crate::jit_contract::EvidenceStrength::NotRun),
    /// so "nothing ran" is a fact the consumer can read rather than an absence
    /// it has to infer.
    ///
    /// Reporting only: calling this runs no verifier and changes no behaviour.
    pub fn proof_evidence(&self) -> crate::jit_contract::ProofEvidenceSummary {
        crate::proof_evidence::route_evidence(
            crate::proof_evidence::ROUTE_EVIDENCE_VERIFIER,
            self.route_facts(),
            &crate::proof_evidence::evidence_environment(),
        )
    }

    /// What this pipeline's configuration actually runs.
    pub fn route_facts(&self) -> crate::proof_evidence::RouteFacts {
        crate::proof_evidence::RouteFacts {
            instruction_verification_ran: self.config.verify,
            dispatch_verification_ran: self.config.verify_dispatch != DispatchVerifyMode::Off,
            // The pipeline emits certificates only when the function verifier
            // runs; there is no separate certificate knob on this route.
            proof_certificates_emitted: self.config.verify,
            evidence_report_present: false,
            manifest_pin_accepted: false,
        }
    }

    /// Attach a decoded `.profdata` artifact for profile-use mode.
    pub fn with_profile_use(mut self, profile: trust_cg_opt::pgo::ProfData) -> Self {
        self.profile_use = Some(profile);
        self
    }

    /// Admit the AArch64 ELF `ADRP+LDR/STR #:lo12:` fusion for symbols this
    /// object defines at a guaranteed alignment (see
    /// [`elf_lo12_symbol_alignments`]). Other targets ignore it.
    pub fn with_elf_lo12_symbol_alignments(mut self, alignments: BTreeMap<String, u64>) -> Self {
        self.elf_lo12_symbol_alignments = Some(Arc::new(alignments));
        self
    }

    /// Attach an AOT PGO counter-site sink, enabling profile-generate mode:
    /// every prepared function gets one counter increment per basic block
    /// (indexing the module-level `__tcg_pgo_counters` u64 array), and the
    /// `(function, block_id, counter_index)` triples land in `sink` so the
    /// caller can emit the sites sidecar and size the counter array global.
    /// Applies to LIR and pre-built machine-IR preparation/compilation alike.
    /// Injection is after optimization/verification and before allocation.
    /// Its admission errors leave the function/map unchanged at that phase;
    /// this does not roll back earlier or later compilation phases.
    pub fn with_profile_generate_sink(
        mut self,
        sink: Arc<std::sync::Mutex<trust_cg_opt::pgo::CounterMap>>,
    ) -> Self {
        self.profile_generate_sink = Some(sink);
        self
    }

    fn inject_profile_counters(&self, function: &mut IrMachFunction) -> Result<(), PipelineError> {
        if let Some(sink) = &self.profile_generate_sink {
            inject_aot_block_counters(function, sink)?;
        }
        Ok(())
    }

    /// Enable the non-default certified const-fold/DCE opt pass execution
    /// slice for this pipeline.
    pub fn with_certified_pass_execution(mut self) -> Self {
        self.certified_pass_execution = true;
        self
    }

    /// Request a per-pass validation configuration
    /// ([`trust_cg_opt::pass_validation`]) for this pipeline's optimizer and
    /// scheduler runs. It replaces the environment control and the
    /// diagnostic default, but cannot lower a proof-grade or certified
    /// pipeline below [`trust_cg_opt::PassValidationPolicy::Enforce`].
    pub fn with_pass_validation(mut self, config: trust_cg_opt::PassValidationConfig) -> Self {
        self.pass_validation = Some(config);
        self
    }

    /// Build composed transition records under `policy`
    /// ([`crate::composed_transition`]); proof-grade publication and the
    /// sealed Core require them whatever is asked.
    pub fn with_composed_transitions(
        mut self,
        policy: crate::composed_transition::ComposedTransitionPolicy,
    ) -> Self {
        self.composed_transitions = Some(policy);
        self
    }

    /// The composed transition policy of an ordinary preparation: the
    /// requested one ([`Self::with_composed_transitions`]), else
    /// `TRUST_CG_COMPOSED_TRANSITION` (`off`, `record`, `require`), else off;
    /// raised to `require` under proof-grade publication. A sealed Core
    /// preparation always requires them.
    pub fn composed_transition_policy(
        &self,
    ) -> crate::composed_transition::ComposedTransitionPolicy {
        use crate::composed_transition::ComposedTransitionPolicy;
        let requested = self
            .composed_transitions
            .or_else(ComposedTransitionPolicy::from_environment)
            .unwrap_or_default();
        if self.aarch64_integrity_policy == Aarch64IntegrityPolicy::ProofGradeEnforce {
            requested.strongest(ComposedTransitionPolicy::Require)
        } else {
            requested
        }
    }

    /// [`Self::composed_transition_policy`] for a preparation under
    /// `admission`.
    fn composed_transition_policy_for(
        &self,
        admission: Aarch64DirectCallAdmission,
    ) -> crate::composed_transition::ComposedTransitionPolicy {
        use crate::composed_transition::ComposedTransitionPolicy;
        let policy = self.composed_transition_policy();
        if admission == Aarch64DirectCallAdmission::SealedCore {
            policy.strongest(ComposedTransitionPolicy::Require)
        } else {
            policy
        }
    }

    /// The validation one function's optimizer and post-allocation
    /// comparison run under: the pipeline's
    /// ([`Self::pass_validation_config`]), widened while `composition`
    /// records a chain to at least the dedicated scope (so the
    /// post-allocation comparison runs) under at least the diagnostic policy,
    /// or `enforce` when the chain is required, with the optimizer recording
    /// pass transitions.
    fn composed_optimization_validation(
        &self,
        composition: &crate::composed_transition::Session,
    ) -> OptimizationValidation {
        use crate::composed_transition::ComposedTransitionPolicy;
        use trust_cg_opt::{PassValidationPolicy, PassValidationScope};
        let mut config = self.pass_validation_config();
        let transitions = composition.transition_digest();
        if transitions.is_some() {
            config.policy = config.policy.strongest(match composition.policy() {
                ComposedTransitionPolicy::Require => PassValidationPolicy::Enforce,
                _ => PassValidationPolicy::Diagnostic,
            });
            config.scope = config.scope.widest(PassValidationScope::Dedicated);
        }
        OptimizationValidation {
            config,
            transitions,
        }
    }

    /// The validation of a preparation that records no composed transition.
    fn optimization_validation(&self) -> OptimizationValidation {
        OptimizationValidation {
            config: self.pass_validation_config(),
            transitions: None,
        }
    }

    /// The per-pass validation this pipeline runs with.
    ///
    /// The requested configuration ([`Self::with_pass_validation`]), else
    /// `TRUST_CG_PASS_VALIDATION` (`off`, `diagnostic`, `enforce`,
    /// `require-coverage`; any other value selects `enforce`) with
    /// `TRUST_CG_PASS_VALIDATION_SCOPE` (`schedulers`, `dedicated` or
    /// `all`), else the diagnostic default. A proof-grade publication pipeline and a certified
    /// pass-execution pipeline enforce at least
    /// [`trust_cg_opt::PassValidationPolicy::Enforce`]: a failed validation
    /// refuses their compile, whatever was requested.
    pub fn pass_validation_config(&self) -> trust_cg_opt::PassValidationConfig {
        use trust_cg_opt::{PassValidationConfig, PassValidationPolicy, PassValidationScope};
        let mut config = self.pass_validation.unwrap_or_else(|| {
            let mut config = PassValidationConfig::diagnostic();
            if let Ok(policy) = crate::env_lock::var("TRUST_CG_PASS_VALIDATION") {
                config.policy =
                    PassValidationPolicy::parse(&policy).unwrap_or(PassValidationPolicy::Enforce);
            }
            if let Ok(scope) = crate::env_lock::var("TRUST_CG_PASS_VALIDATION_SCOPE")
                && let Some(scope) = PassValidationScope::parse(&scope)
            {
                config.scope = scope;
            }
            config
        });
        if self.certified_pass_execution
            || self.aarch64_integrity_policy == Aarch64IntegrityPolicy::ProofGradeEnforce
        {
            config.policy = config.policy.strongest(PassValidationPolicy::Enforce);
            config.scope = config.scope.widest(PassValidationScope::Dedicated);
        }
        config
    }

    /// Create a pipeline with default O2 configuration and NO target.
    ///
    /// Every target-dependent entry of the returned pipeline refuses with
    /// [`PipelineError::TargetAbiUnresolved`] until a target is named.
    #[deprecated(
        note = "names no target; use Pipeline::new(PipelineConfig::for_target(triple)) or PipelineConfig::for_host_aarch64()"
    )]
    pub fn default_o2() -> Self {
        Self::new(PipelineConfig::default())
    }

    fn pass_disabled(&self, name: &str) -> bool {
        self.config
            .disabled_passes_override
            .as_deref()
            .map(|disabled| disabled.split(',').any(|disabled| disabled.trim() == name))
            .unwrap_or_else(|| trust_cg_pass_disabled(name))
    }

    /// Run the bounded fsym trust-ir preflight for one function.
    ///
    /// FAIL-CLOSED: if the scan reports a deref-coverage gap (a dropped
    /// dereference obligation — the #49 fail-open class), this returns
    /// `Err(PipelineError::FsymCoverageGap)` so the gap fails the compile,
    /// mirroring the CLI gate on `report.has_coverage_error()`. A coverage gap
    /// must not be swallowed as advisory metrics. (The verify-off branch returns
    /// a Skip summary and has no report, so it cannot have a coverage gap.)
    fn run_fsym_trust_ir_preflight(
        &self,
        module: &trust_ir::Module,
        trust_ir_func: &trust_ir::Function,
    ) -> Result<Option<FsymTrustIrPipelineSummary>, PipelineError> {
        if !self.config.enable_fsym_trust_ir_preflight {
            return Ok(None);
        }

        #[cfg(feature = "verify")]
        {
            // Scan THIS function in its full module: the module supplies each
            // direct callee's declared name, linkage and signature (a call to
            // `memset` is a bulk memory access, a pointer handed to an
            // external callee an unsummarized effect). A module stripped to
            // this one function would leave every callee unresolved.
            let report =
                trust_cg_verify::fsym_trust_ir::scan_function_in_module(module, trust_ir_func);
            let has_coverage_error = report.has_coverage_error();
            let summary =
                fsym_trust_ir_summary_from_report(&module.name, &trust_ir_func.name, report);
            // Fail closed on a deref-coverage gap for THIS function. A
            // module-level coverage error that is not for this function would
            // not appear in `summary.coverage_errors`; in practice the scan is
            // single-function here, so the two coincide, but gate on the
            // function-scoped detail so the error message is precise.
            if has_coverage_error && summary.coverage_error_count > 0 {
                return Err(PipelineError::FsymCoverageGap(
                    summary.coverage_errors.join("; "),
                ));
            }
            // Defensive: if the report flagged a coverage error but none mapped
            // to this function name, still fail closed rather than swallow it.
            if has_coverage_error {
                return Err(PipelineError::FsymCoverageGap(format!(
                    "deref-coverage gap reported by fsym scan of function `{}`",
                    trust_ir_func.name
                )));
            }
            Ok(Some(summary))
        }

        #[cfg(not(feature = "verify"))]
        {
            Ok(Some(FsymTrustIrPipelineSummary {
                module_name: module.name.clone(),
                function_name: trust_ir_func.name.clone(),
                scanned: false,
                warning_count: 1,
                skipped: Some(FsymTrustIrPipelineSkip {
                    reason: "verify-feature-disabled".to_string(),
                    detail:
                        "bounded trust_ir fsym preflight requires trust-cg-codegen `verify` feature"
                            .to_string(),
                }),
                ..Default::default()
            }))
        }
    }

    #[cfg(not(feature = "verify"))]
    fn warn_cegis_superopt_ignored(&self) {
        if !self.cegis_warning_emitted.swap(true, Ordering::Relaxed) {
            eprintln!(
                "trust-cg: warning: --cegis-superopt=N ignored: binary built without `verify` feature"
            );
        }
    }

    #[cfg_attr(not(feature = "verify"), allow(dead_code))]
    fn cegis_opt_level(&self) -> u8 {
        match self.config.opt_level {
            OptLevel::O0 => 0,
            OptLevel::O1 => 1,
            OptLevel::O2 => 2,
            OptLevel::O3 => 3,
        }
    }

    /// Run the CEGIS superopt pass on a function when configured.
    ///
    /// Returns the per-run pass statistics when the pass actually executed.
    /// Returns `None` when the pass is disabled or unavailable.
    pub fn run_cegis_superopt(&self, func: &mut IrMachFunction) -> Option<CegisPassStats> {
        self.run_cegis_superopt_with_outcome(func)
            .map(|run| run.stats)
    }

    /// Run CEGIS and retain its typed completion state alongside statistics.
    ///
    /// Unlike the legacy stats-only API, this lets compiler services reject an
    /// incomplete wall-clock search instead of confusing rollback with an
    /// ordinary no-op.
    pub fn run_cegis_superopt_with_outcome(
        &self,
        func: &mut IrMachFunction,
    ) -> Option<CegisPassRun> {
        #[cfg(feature = "verify")]
        {
            let budget_sec = self.config.cegis_superopt_budget_sec?;
            if budget_sec == 0 {
                return None;
            }

            let pass =
                trust_cg_verify::CegisSuperoptPass::new(trust_cg_verify::CegisSuperoptConfig {
                    budget_sec,
                    per_query_ms: 5_000,
                    target_triple: self.config.target_triple.clone(),
                    cpu: String::new(),
                    features: Vec::new(),
                    opt_level: self.cegis_opt_level(),
                    search_schedule:
                        trust_cg_verify::CegisSearchScheduleIdentity::current_execution(),
                    cache: Some(self.cegis_cache.clone()),
                    trace: None,
                });
            #[cfg(all(test, feature = "verify"))]
            let mut pass = if self.cegis_test_incomplete_after_first_commit {
                pass.with_test_hooks(trust_cg_verify::cegis_pass::CegisSuperoptTestHooks {
                    verifier_result: Some(trust_cg_verify::CegisResult::Equivalent {
                        proof_hash: 0x486,
                        iterations: 1,
                    }),
                    ..Default::default()
                })
                .with_test_incomplete_after_first_commit()
            } else {
                pass
            };
            #[cfg(not(all(test, feature = "verify")))]
            let mut pass = pass;

            let outcome = pass.run_with_outcome(func);
            Some(CegisPassRun {
                outcome,
                stats: pass.stats().clone(),
            })
        }

        #[cfg(not(feature = "verify"))]
        {
            let _ = func;
            if self.config.cegis_superopt_budget_sec.is_some() {
                self.warn_cegis_superopt_ignored();
            }
            None
        }
    }

    fn run_cegis_superopt_checked(
        &self,
        func: &mut IrMachFunction,
    ) -> Result<Option<CegisPassStats>, PipelineError> {
        let function = func.name.clone();
        let Some(run) = self.run_cegis_superopt_with_outcome(func) else {
            return Ok(None);
        };
        if let Some(completion) = run.outcome.incomplete_reason() {
            return Err(PipelineError::CegisIncomplete {
                function,
                completion,
                ay_refusal: trust_cg_verify::ay_bridge::solver_refusal_note(),
            });
        }
        Ok(Some(run.stats))
    }

    /// AArch64 fall-through branch-layout optimization (EXEC-SPEED).
    ///
    /// Runs at `-O2`/`-O3` immediately before [`resolve_branches`], the only
    /// point where `block_order` is final and consumed verbatim by the branch
    /// resolver and encoder. Reorders blocks so a loop body falls through from
    /// its header and elides unconditional branches to the layout-next block.
    /// Fail-closed on EH/jump-table/indirect-branch functions (see
    /// [`crate::layout::aarch64_layout_fallthrough_and_elide`]). Kill switch:
    /// `TRUST_CG_DISABLE_PASSES=branch_layout`.
    ///
    /// No pass validator covers this post-allocation step. Under an active
    /// pass-validation policy a run that changed the function is recorded as
    /// uncovered (`branch-layout`) in `summary` when the caller keeps one,
    /// and refuses the compile under `require-coverage` either way.
    fn apply_aarch64_branch_layout(
        &self,
        func: &mut IrMachFunction,
        summary: Option<&mut trust_cg_opt::PassValidationSummary>,
    ) -> Result<(), PipelineError> {
        if !self.reorder_and_elide_aarch64_branches(func) {
            return Ok(());
        }
        let config = self.pass_validation_config();
        if !config.policy.is_active() {
            return Ok(());
        }
        let mut local = trust_cg_opt::PassValidationSummary::new(config);
        trust_cg_opt::pass_validation::record_unvalidated_change(
            config,
            "branch-layout",
            func,
            &mut local,
        );
        if let Some(summary) = summary {
            summary.merge(&local);
        }
        Self::enforce_pass_validation(func, config, &local)
    }

    /// L10-P1: capture `func`, the function entering register allocation,
    /// for the post-allocation value-flow comparisons
    /// ([`crate::post_ra_value_flow`]). Captures nothing when the
    /// pass-validation policy is `off`.
    fn begin_post_ra_value_flow(
        &self,
        func: &IrMachFunction,
    ) -> crate::post_ra_value_flow::Session {
        self.begin_post_ra_value_flow_with(self.pass_validation_config(), func)
    }

    /// [`Self::begin_post_ra_value_flow`] under `config`.
    fn begin_post_ra_value_flow_with(
        &self,
        config: trust_cg_opt::PassValidationConfig,
        func: &IrMachFunction,
    ) -> crate::post_ra_value_flow::Session {
        // X18 is the platform register on Apple targets (DarwinPCS); the ELF
        // targets this backend emits never allocate it either, but the ABI
        // does not reserve it there.
        let reserved_x18 = !target_triple_uses_elf(&self.config.target_triple);
        crate::post_ra_value_flow::Session::begin(config, func, reserved_x18)
    }

    /// L10-P1: compare `func` with the session's captured function at
    /// `stage` (`layout` is the frame layout for the frame/layout stage),
    /// fold the verdict into `summary` when the caller keeps one, report it
    /// under the diagnostic policy and refuse a non-validated stage under a
    /// refusing policy ([`PipelineError::PassValidationFailed`] naming the
    /// stage).
    fn check_post_ra_value_flow(
        &self,
        session: &mut crate::post_ra_value_flow::Session,
        stage: trust_cg_verify::post_ra_value_flow::Stage,
        func: &IrMachFunction,
        layout: Option<&crate::frame::FrameLayout>,
        summary: Option<&mut trust_cg_opt::PassValidationSummary>,
    ) -> Result<(), PipelineError> {
        self.check_post_ra_value_flow_composed(session, stage, func, layout, summary, None)
    }

    /// [`Self::check_post_ra_value_flow`], also recording the comparison as
    /// a post-allocation link of `composition`'s chain (L09-P3) before any
    /// refusal: the window ends at `func` and carries the comparison's
    /// verdict, or `not-run` when the final window ran no comparison.
    fn check_post_ra_value_flow_composed(
        &self,
        session: &mut crate::post_ra_value_flow::Session,
        stage: trust_cg_verify::post_ra_value_flow::Stage,
        func: &IrMachFunction,
        layout: Option<&crate::frame::FrameLayout>,
        summary: Option<&mut trust_cg_opt::PassValidationSummary>,
        composition: Option<&mut crate::composed_transition::Session>,
    ) -> Result<(), PipelineError> {
        let _phase = PhaseGuard::new(func, stage.as_str());
        let local = session.check(stage, func, layout);
        if let Some(composition) = composition {
            match &local {
                Some(local) => {
                    let verdict = local
                        .failures
                        .first()
                        .map(|record| record.verdict.clone())
                        .or_else(|| {
                            (local.validated() > 0)
                                .then_some(trust_cg_opt::ValidationVerdict::Validated)
                        });
                    let name = local
                        .passes
                        .first()
                        .map_or(stage.as_str(), |counts| counts.pass_name.as_str());
                    composition.post_allocation(name, func, verdict.as_ref());
                }
                None if stage == trust_cg_verify::post_ra_value_flow::Stage::FrameLayout => {
                    composition.post_allocation(stage.as_str(), func, None);
                }
                None => {}
            }
        }
        let Some(local) = local else {
            return Ok(());
        };
        let config = session.config;
        Self::warn_pass_validation_failures(func, config, &local);
        if let Some(summary) = summary {
            summary.merge(&local);
        }
        Self::enforce_pass_validation(func, config, &local)
    }

    /// The branch-layout rewrite itself ([`Self::apply_aarch64_branch_layout`]);
    /// returns whether it changed the function (a block moved, a jump
    /// elided or a loop rotated).
    fn reorder_and_elide_aarch64_branches(&self, func: &mut IrMachFunction) -> bool {
        if matches!(self.config.opt_level, OptLevel::O2 | OptLevel::O3)
            && !self.pass_disabled("branch_layout")
        {
            let order = func.block_order.clone();
            // Bottom-test loop rotation is DEFAULT-OFF. It is sound (see
            // `layout::rotate_top_tested_loops`) but measured *slower* than the
            // top-tested reorder+elide on the target reduction kernels: the
            // rotation puts the loop compare on the induction-variable critical
            // path, whereas the top-test uses the already-available value and
            // pays only a predicted-not-taken exit branch. Kept opt-in (like the
            // x86 branch-layout `fallthrough_rule`) via
            // `TRUST_CG_ENABLE_PASSES=branch_layout_rotate` for A/B experiments.
            let rotate = trust_cg_pass_enabled("branch_layout_rotate");
            let laid_out = crate::layout::aarch64_layout_fallthrough_and_elide(func, rotate);
            // Layout-independent branch-to-next elision. The reorder pass above
            // fails closed as a WHOLE on already-rotated loops (a conditional
            // back-edge) and on EH/jump-table functions, yet a rotated loop
            // still carries a redundant `b <next>` at its body→latch seam — a
            // taken branch to the very next instruction, present in EVERY
            // rotated scalar loop. This pure elision removes it WITHOUT any
            // reorder (sound on all those shapes; see
            // `layout::aarch64_elide_branch_to_next`). It is a no-op when the
            // reorder pass already ran and elided.
            let elided = crate::layout::aarch64_elide_branch_to_next(func);
            laid_out || elided || func.block_order != order
        } else {
            false
        }
    }

    /// Re-derive final AArch64 stream structure after every post-RA rewrite.
    /// The structural gate is unconditionally enforced. The additional
    /// reaching-def and spill-slot nets follow the supplied integrity policy;
    /// proof-grade callers force both to Enforce.
    fn recheck_aarch64_post_regalloc(
        &self,
        func: &IrMachFunction,
    ) -> Result<AArch64MachineCodeEvidence, PipelineError> {
        self.recheck_aarch64_post_regalloc_with_policy(func, Aarch64IntegrityPolicy::Compatibility)
    }

    fn recheck_aarch64_post_regalloc_with_policy(
        &self,
        func: &IrMachFunction,
        integrity_policy: Aarch64IntegrityPolicy,
    ) -> Result<AArch64MachineCodeEvidence, PipelineError> {
        self.recheck_aarch64_post_regalloc_checked(func, integrity_policy)
            .map(|(evidence, _check)| evidence)
    }

    /// [`Self::recheck_aarch64_post_regalloc_with_policy`], also returning
    /// the final-stream check it ran and passed.
    fn recheck_aarch64_post_regalloc_checked(
        &self,
        func: &IrMachFunction,
        integrity_policy: Aarch64IntegrityPolicy,
    ) -> Result<(AArch64MachineCodeEvidence, Aarch64FinalStreamCheck), PipelineError> {
        let _phase = PhaseGuard::new(func, "post-ra-recheck");
        let check = Aarch64FinalStreamCheck::resolve(integrity_policy);
        let target_machine = self.aarch64_function_target_machine(func)?;
        let required_features = enforce_aarch64_final_stream(
            func,
            AArch64CfgValidationStage::ResolvedEncoding,
            Some(&target_machine),
            check,
        )?;
        let evidence = AArch64MachineCodeEvidence::try_new(&target_machine, required_features)
            .map_err(|error| aarch64_target_machine_contract_error(&func.name, error))?;
        Ok((evidence, check))
    }

    /// Compile a trust_ir function through the full pipeline, producing target
    /// object bytes.
    ///
    /// This is the main entry point. It takes a `trust_cg_lower::Function` (trust_ir)
    /// and returns the bytes of a valid .o file for the configured target triple.
    pub fn compile_function(
        &self,
        input: &trust_cg_lower::Function,
    ) -> Result<Vec<u8>, PipelineError> {
        reject_unsupported_aarch64_object_format(&self.config.target_triple)?;
        // Phase 1: Instruction Selection (no proof context in single-function path)
        let (isel_func, value_map) = self.run_isel(input, None)?;
        let debug_value_bindings = debug_value_binding_vregs(input, value_map.as_ref());
        let mut provenance = provenance_from_isel_trust_ir_origins(&isel_func);
        let trust_ir_source_locs = trust_ir_source_locs_from_input(input);

        // Phase 2: Convert ISel output to shared IR (issue #73 consolidation:
        // conversion logic now lives in ISelFunction::to_ir_func()), behind
        // the L10-P5 identity admission.
        let mut ir_func = isel_func
            .try_to_ir_func()
            .map_err(PipelineError::MachIdAdmission)?;
        ir_func.debug_meta = input.debug_meta.clone();
        ir_func.stack_protector = input.stack_protector;
        ir_func.stack_limit = self.resolve_aarch64_stack_limit(input)?;
        check_raw_aarch64_dataflow_integrity(&ir_func, input, self.raw_dataflow_policy)?;

        // Edge-connectivity check (non-fatal).
        //
        // This was originally `debug_assert!(total_succs > 0, ..)` but that
        // fired on legal trust_ir whose non-entry blocks all terminate with
        // `Return` (no `Br`/`CondBr` edges). After DCE such blocks are
        // harmless — register allocation, frame lowering, and encoding all
        // operate per-block and do not require inter-block connectivity.
        // Tripping the assert prevented the pipeline from being a total
        // function over valid trust_ir (#447: panic-fuzz totality). We keep the
        // shape of the check as a no-op sentinel for future debugging.
        #[cfg(debug_assertions)]
        {
            let has_branches = ir_func.blocks.len() > 1;
            if has_branches {
                let _total_succs: usize = ir_func.blocks.iter().map(|b| b.succs.len()).sum();
                let _total_preds: usize = ir_func.blocks.iter().map(|b| b.preds.len()).sum();
                // Tolerated: _total_succs == 0 or _total_preds == 0 is a legal
                // (if unusual) multi-block shape — see issue #447.
            }
        }

        // This standalone route has no exact Trust-IR obligation/replay binding.  ISel facts remain
        // available on `isel_func` for diagnostics, but none may authorize a behavior-changing pass.
        let proof_optimization_metadata = None;

        // Sentinel S1: snapshot guard carriers at birth (before optimization) into a per-function
        // ledger keyed by the arch-neutral Certified-Elimination Kernel. Shadow only.
        //
        // Skipped entirely when `TRUST_CG_GUARD_SHADOW` is off (the default): the
        // snapshot is a full instruction walk plus a per-carrier ledger record whose
        // ONLY consumer is `finalize_and_observe`, which returns `()` and whose every
        // branch is an `eprintln!` behind the same gate. One env read per function
        // replaces two whole-function walks per function. Uncached on purpose so an
        // in-process flip is observed by the next compile.
        let guard_shadow = crate::guard_ledger::shadow_logging_enabled();
        let guard_observation =
            guard_shadow.then(|| crate::guard_ledger::observe_carrier_births(&ir_func));

        // Phase 3: Optimization
        self.run_optimization_with_proof_metadata_checked(
            &mut ir_func,
            proof_optimization_metadata,
            provenance.as_mut(),
        )?;
        // Sentinel S1: reconcile the snapshot against the optimized function (mark eliminated vs
        // trapped), run the shadow kernel, and check guard-count conservation. Zero behavior
        // change: never fails the compile, output gated by TRUST_CG_GUARD_SHADOW.
        if let Some(guard_observation) = guard_observation {
            crate::guard_ledger::finalize_and_observe(guard_observation, &ir_func);
        }

        // Phase 3.5: Verification (optional — gated by config.verify)
        self.run_verification(&ir_func)?;

        self.inject_profile_counters(&mut ir_func)?;

        // L10-P1: capture the function entering register allocation.
        let mut value_flow = self.begin_post_ra_value_flow(&ir_func);

        // Phase 4-6: Register Allocation
        let regalloc = self.run_regalloc(&mut ir_func)?;

        // Phase 6.5: Lower pseudo Copy instructions to real moves.
        lower_copies(&mut ir_func)?;
        eliminate_dead_unallocated_defs(&mut ir_func);
        bind_dead_unallocated_defs_to_discard_registers(&mut ir_func)?;
        ensure_no_unresolved_vregs(&ir_func, "regalloc/copy lowering")?;
        self.check_post_ra_value_flow(
            &mut value_flow,
            trust_cg_verify::post_ra_value_flow::Stage::Allocation,
            &ir_func,
            None,
            None,
        )?;

        // Phase 7: Frame Lowering
        let frame_layout = self.run_frame_lowering_for_source(
            &mut ir_func,
            Some(input),
            Aarch64DirectCallAdmission::Compatibility,
        )?;

        // Phase 7.25: Expand proof-only guards before branch resolution.
        crate::lower::expand_trap_bounds_check_exact(&mut ir_func);
        crate::lower::expand_trap_null_if_zero(&mut ir_func);
        crate::lower::expand_trap_div_zero_if_zero(&mut ir_func);
        crate::lower::expand_trap_shift_range_if_oob(&mut ir_func);
        crate::lower::expand_trap_overflow_exact(&mut ir_func);
        expand_aarch64_llsc_atomics(&mut ir_func)?;

        // Phase 7.4: Fall-through branch layout (O2/O3) — reorder blocks for
        // fall-through and elide redundant jumps. Must run right before
        // resolve_branches so `block_order` is final and consumed verbatim.
        self.apply_aarch64_branch_layout(&mut ir_func, None)?;

        // Phase 7.5: Branch Resolution — resolve symbolic Block operands to
        // PC-relative byte offsets before encoding.
        resolve_branches_after_authority(&mut ir_func)?;
        self.recheck_aarch64_post_regalloc(&ir_func)?;
        self.check_post_ra_value_flow(
            &mut value_flow,
            trust_cg_verify::post_ra_value_flow::Stage::FrameLayout,
            &ir_func,
            Some(&frame_layout),
            None,
        )?;
        self.certify_aarch64_stack_limit(input, &ir_func)?;
        // X-OPCODES-P6: this one-shot object route (`compile_to_object`) makes
        // the same volatile access preservation decision as every preparation.
        check_aarch64_volatile_access_preservation(input, &ir_func)?;
        seed_spilled_value_debug_provenance(
            &ir_func,
            &mut provenance,
            &regalloc.debug_snapshot,
            &debug_value_bindings,
        )?;
        seed_register_value_debug_provenance(&ir_func, &mut provenance, &regalloc.debug_snapshot)?;
        seed_constant_value_debug_provenance(&ir_func, &mut provenance)?;
        seed_stack_alloca_debug_provenance(&ir_func, &mut provenance)?;

        // Phase 8: Encoding
        let (code, fixups, eh_block_offsets) = if let Some(provenance) = provenance.as_mut() {
            let (code, fixups, block_offsets) = if ir_func.eh_metadata.has_eh_info() {
                // EH-aware owner: keep exact block offsets for LSDA resolution
                // while threading provenance through the private encoder core.
                encode_function_with_fixups_and_blocks_impl_with_sites(
                    &ir_func,
                    Some(provenance),
                    None,
                    self.aarch64_integrity_policy,
                )?
            } else {
                reject_aarch64_eh_sidecar_drop(
                    &ir_func,
                    "encode_function_with_fixups_and_blocks_with_provenance",
                )?;
                encode_function_with_fixups_and_blocks_impl_with_sites(
                    &ir_func,
                    Some(provenance),
                    None,
                    self.aarch64_integrity_policy,
                )?
            };
            provenance.build_transitive();
            (code, fixups, Some(block_offsets))
        } else if ir_func.eh_metadata.has_eh_info() {
            // EH functions need block byte offsets to resolve the LSDA call-site
            // table + landing-pad offsets, so take the block-tracking encode path
            // even without provenance.
            let (code, fixups, block_offsets) =
                encode_function_with_fixups_and_blocks_impl_with_sites(
                    &ir_func,
                    None,
                    None,
                    self.aarch64_integrity_policy,
                )?;
            (code, fixups, Some(block_offsets))
        } else {
            let (code, fixups) =
                encode_function_with_fixups_under(&ir_func, self.aarch64_integrity_policy)?;
            (code, fixups, None)
        };

        reject_unsupported_aarch64_object_format(&self.config.target_triple)?;

        // Phase 8.5: LSDA Generation — resolve the post-layout EH byte offsets
        // from the block offsets just computed, then generate the
        // Language-Specific Data Area (call sites, landing pads, type table).
        if let Some(block_offsets) = &eh_block_offsets {
            resolve_eh_offsets_with_propagation(
                &mut ir_func,
                block_offsets,
                code.len(),
                &self.eh_propagation,
            )?;
        }
        let lsda = generate_lsda_for_function(&ir_func)?;

        // ELF target: emit with `.eh_frame` (and `.gcc_except_table` when the
        // function carries EH structure) — the LSDA above is required input,
        // so this fork sits after Phase 8.5 (Mach-O flow unchanged).
        // A single-function object binds its function `STB_GLOBAL`; a
        // non-ELF format refuses `pie`/`pic` here rather than ignore them.
        reject_aarch64_object_relocation_model_violations(
            self.config.relocation_model,
            &self.config.target_triple,
            std::slice::from_ref(&ir_func.name),
            &ElfModuleSymbolPlan::legacy(),
            &[],
            &fixups,
        )?;
        if target_triple_uses_elf(&self.config.target_triple) {
            let personality = if lsda.is_some() {
                Some(
                    crate::exception_handling::required_personality_symbol(
                        ir_func.eh_metadata.personality.as_deref(),
                    )
                    .map_err(|error| PipelineError::MalformedAarch64Eh {
                        function: ir_func.name.clone(),
                        detail: format!("invalid exception-handling personality: {error}"),
                    })?,
                )
            } else {
                None
            };
            let debug = self.elf_single_function_debug_image(
                &ir_func,
                &code,
                &frame_layout,
                provenance
                    .as_ref()
                    .map(|provenance| (provenance, &trust_ir_source_locs)),
            )?;
            if let Some(obj_bytes) = emit_single_function_target_elf_if_needed(
                &self.config.target_triple,
                &ir_func.name,
                &code,
                &fixups,
                lsda.as_ref().zip(personality),
                Some(&frame_layout),
                ir_func.text_align_log2,
                self.function_sections,
                debug.as_ref(),
            )? {
                return Ok(obj_bytes);
            }
        }

        // Phase 9: Mach-O Emission (with compact unwind + LSDA)
        let debug_provenance = provenance
            .as_ref()
            .map(|provenance| (provenance, &trust_ir_source_locs));
        let obj_bytes = self.emit_macho(
            &ir_func,
            &code,
            Some(&frame_layout),
            lsda.as_ref(),
            debug_provenance,
            Some(&fixups),
        )?;

        Ok(obj_bytes)
    }

    /// Compile a pre-built IR function (skipping ISel).
    ///
    /// Useful when you already have an `IrMachFunction` and want to run
    /// the remaining phases (opt, regalloc, frame, encode, emit).
    pub fn compile_ir_function(
        &self,
        ir_func: &mut IrMachFunction,
    ) -> Result<Vec<u8>, PipelineError> {
        self.compile_ir_function_with_stats(ir_func)
            .map(|(obj_bytes, _stats)| obj_bytes)
    }

    /// Compile a pre-built IR function and return optimization pass stats.
    ///
    /// This is used by the high-level compiler to attach certified pass-chain
    /// evidence from the real optimization path without changing the legacy
    /// `compile_ir_function` return type.
    pub fn compile_ir_function_with_stats(
        &self,
        ir_func: &mut IrMachFunction,
    ) -> Result<(Vec<u8>, trust_cg_opt::PassStats), PipelineError> {
        reject_unsupported_aarch64_object_format(&self.config.target_triple)?;
        self.validate_aarch64_mach_function_for_profile(ir_func)?;

        // Phase 3: Optimization
        let mut optimization_stats = self.run_optimization_checked(ir_func)?;

        // Phase 3.5: Verification (optional — gated by config.verify)
        self.run_verification(ir_func)?;

        self.inject_profile_counters(ir_func)?;

        // L10-P1: capture the function entering register allocation.
        let mut value_flow = self.begin_post_ra_value_flow(ir_func);

        // Phase 4-6: Register Allocation
        let _regalloc = self.run_regalloc(ir_func)?;

        // Phase 6.5: Lower pseudo Copy instructions to real moves.
        lower_copies(ir_func)?;
        eliminate_dead_unallocated_defs(ir_func);
        bind_dead_unallocated_defs_to_discard_registers(ir_func)?;
        ensure_no_unresolved_vregs(ir_func, "regalloc/copy lowering")?;
        self.check_post_ra_value_flow(
            &mut value_flow,
            trust_cg_verify::post_ra_value_flow::Stage::Allocation,
            ir_func,
            None,
            Some(&mut optimization_stats.pass_validation),
        )?;

        // Phase 7: Frame Lowering
        let frame_layout = self.run_frame_lowering(ir_func)?;

        // Phase 7.25: Expand proof-only guards before branch resolution.
        crate::lower::expand_trap_bounds_check_exact(ir_func);
        crate::lower::expand_trap_null_if_zero(ir_func);
        crate::lower::expand_trap_div_zero_if_zero(ir_func);
        crate::lower::expand_trap_shift_range_if_oob(ir_func);
        crate::lower::expand_trap_overflow_exact(ir_func);
        expand_aarch64_llsc_atomics(ir_func)?;

        // Phase 7.4: Fall-through branch layout (O2/O3).
        self.apply_aarch64_branch_layout(ir_func, Some(&mut optimization_stats.pass_validation))?;

        // Phase 7.5: Branch Resolution
        resolve_branches_after_authority(ir_func)?;
        self.recheck_aarch64_post_regalloc(ir_func)?;
        self.check_post_ra_value_flow(
            &mut value_flow,
            trust_cg_verify::post_ra_value_flow::Stage::FrameLayout,
            ir_func,
            Some(&frame_layout),
            Some(&mut optimization_stats.pass_validation),
        )?;

        // Phase 8: Encoding. EH functions need block byte offsets to resolve
        // the LSDA, so take the block-tracking encode path when EH is present.
        let (code, fixups, eh_block_offsets) = if ir_func.eh_metadata.has_eh_info() {
            let (code, fixups, block_offsets) =
                encode_function_with_fixups_and_blocks_impl_with_sites(
                    ir_func,
                    None,
                    None,
                    self.aarch64_integrity_policy,
                )?;
            (code, fixups, Some(block_offsets))
        } else {
            let (code, fixups) =
                encode_function_with_fixups_under(ir_func, self.aarch64_integrity_policy)?;
            (code, fixups, None)
        };

        reject_unsupported_aarch64_object_format(&self.config.target_triple)?;

        // Phase 8.5: LSDA Generation — resolve EH byte offsets, then build LSDA.
        if let Some(block_offsets) = &eh_block_offsets {
            resolve_eh_offsets_with_propagation(
                ir_func,
                block_offsets,
                code.len(),
                &self.eh_propagation,
            )?;
        }
        let lsda = generate_lsda_for_function(ir_func)?;

        // ELF target: emit with `.eh_frame` (and `.gcc_except_table` when the
        // function carries EH structure) — the LSDA above is required input,
        // so this fork sits after Phase 8.5 (Mach-O flow unchanged).
        // A single-function object binds its function `STB_GLOBAL`; a
        // non-ELF format refuses `pie`/`pic` here rather than ignore them.
        reject_aarch64_object_relocation_model_violations(
            self.config.relocation_model,
            &self.config.target_triple,
            std::slice::from_ref(&ir_func.name),
            &ElfModuleSymbolPlan::legacy(),
            &[],
            &fixups,
        )?;
        if target_triple_uses_elf(&self.config.target_triple) {
            let personality = if lsda.is_some() {
                Some(
                    crate::exception_handling::required_personality_symbol(
                        ir_func.eh_metadata.personality.as_deref(),
                    )
                    .map_err(|error| PipelineError::MalformedAarch64Eh {
                        function: ir_func.name.clone(),
                        detail: format!("invalid exception-handling personality: {error}"),
                    })?,
                )
            } else {
                None
            };
            let debug =
                self.elf_single_function_debug_image(ir_func, &code, &frame_layout, None)?;
            if let Some(obj_bytes) = emit_single_function_target_elf_if_needed(
                &self.config.target_triple,
                &ir_func.name,
                &code,
                &fixups,
                lsda.as_ref().zip(personality),
                Some(&frame_layout),
                ir_func.text_align_log2,
                self.function_sections,
                debug.as_ref(),
            )? {
                return Ok((obj_bytes, optimization_stats));
            }
        }

        // Phase 9: Mach-O Emission (with compact unwind + LSDA)
        let obj_bytes = self.emit_macho(
            ir_func,
            &code,
            Some(&frame_layout),
            lsda.as_ref(),
            None,
            Some(&fixups),
        )?;

        Ok((obj_bytes, optimization_stats))
    }

    /// Prepare a trust_ir function through phases 1-7.5 (ISel through branch
    /// resolution) without encoding or Mach-O emission.
    ///
    /// The returned `IrMachFunction` is ready to be passed to
    /// [`compile_module`](Self::compile_module) alongside other prepared
    /// functions. This enables multi-function compilation where cross-function
    /// BL instructions are resolved via BRANCH26 relocations.
    pub fn prepare_function(
        &self,
        input: &trust_cg_lower::Function,
    ) -> Result<IrMachFunction, PipelineError> {
        self.prepare_function_with_proofs(input, None)
    }

    /// Like [`prepare_function`](Self::prepare_function) but also propagates
    /// trust_ir proof annotations from the adapter's [`ProofContext`](trust_cg_lower::ProofContext)
    /// onto the machine instructions and function metadata.
    ///
    /// Proof annotations enable proof-consuming optimizations (proof_opts pass)
    /// that eliminate runtime safety checks verified by ay.
    pub fn prepare_function_with_proofs(
        &self,
        input: &trust_cg_lower::Function,
        proof_ctx: Option<&trust_cg_lower::ProofContext>,
    ) -> Result<IrMachFunction, PipelineError> {
        let (ir_func, _metrics) = self.prepare_function_with_metrics(input, proof_ctx)?;
        Ok(ir_func)
    }

    /// Batch variant of [`prepare_function_with_proofs`](Self::prepare_function_with_proofs)
    /// that prepares many functions across a bounded Rayon worker pool,
    /// returning one result per input in **input order** (`results[i]`
    /// corresponds to `inputs[i]`).
    ///
    /// This mirrors [`compile_module_parallel`](Self::compile_module_parallel):
    /// it fans the *existing* per-function `prepare` across cores. The serial
    /// ISel+regalloc phase has no batch API of its own, so multi-function
    /// modules (e.g. a model-checker's successor kernel + invariant checks +
    /// liveness) otherwise pay that cost serially.
    ///
    /// ## Determinism / soundness
    ///
    /// Ordinary preparation uses per-function machine state and collects
    /// results in input order. Optional CEGIS uses its separately bound cache.
    /// A profile-generation sink is also shared mutable state: counter indices
    /// affect emitted bytes, and result ordering cannot order their reservation.
    /// With a sink attached, this API prepares serially in input order, after
    /// validating the same execution budget. Independently concurrent API calls
    /// still reserve disjoint groups, but their inter-call order is unspecified.
    ///
    /// Falls back to a serial loop (the same per-function call) when there are
    /// fewer than two work items or the host parallelism cap is one, so the
    /// same per-function preparation path is used in every case. A failed batch
    /// does not roll back earlier per-function results or counter records.
    pub fn prepare_functions_parallel(
        &self,
        inputs: &[(trust_cg_lower::Function, trust_cg_lower::ProofContext)],
    ) -> Vec<Result<IrMachFunction, PipelineError>> {
        self.prepare_functions_parallel_with_metrics(inputs)
            .into_iter()
            .map(|result| result.map(|(func, _metrics)| func))
            .collect()
    }

    /// Batch variant of [`prepare_function_with_metrics`](Self::prepare_function_with_metrics).
    ///
    /// Results remain in input order and retain each function's final typed
    /// AArch64 machine-code evidence. This lets manual batch consumers publish
    /// the same target/required-feature facts as single-function callers
    /// without rescanning the prepared stream. Profile-generation batches use
    /// the ordered serial policy described above.
    /// [`prepare_functions_parallel`](Self::prepare_functions_parallel)
    /// delegates here and drops only the metrics for source compatibility.
    pub fn prepare_functions_parallel_with_metrics(
        &self,
        inputs: &[(trust_cg_lower::Function, trust_cg_lower::ProofContext)],
    ) -> Vec<Result<(IrMachFunction, PreparationMetrics), PipelineError>> {
        self.prepare_inputs_in_order(inputs, |pipeline, func, proof_ctx| {
            pipeline.prepare_function_with_metrics(func, Some(proof_ctx))
        })
    }

    /// [`Self::prepare_functions_parallel_with_metrics`], returning each
    /// function sealed with the final-stream check it passed (see
    /// [`Self::prepare_function_checked`]). Input order, and the same
    /// serial/parallel choice and preparation environment.
    pub fn prepare_functions_parallel_checked(
        &self,
        inputs: &[(trust_cg_lower::Function, trust_cg_lower::ProofContext)],
    ) -> Vec<Result<(CheckedAarch64Function, PreparationMetrics), PipelineError>> {
        self.prepare_inputs_in_order(inputs, |pipeline, func, proof_ctx| {
            pipeline.prepare_function_checked(func, Some(proof_ctx))
        })
    }

    /// Run `prepare` over `inputs`, serially or on a bounded worker pool,
    /// returning the results in input order (the parallel path is
    /// byte-identical to the serial loop).
    fn prepare_inputs_in_order<T: Send>(
        &self,
        inputs: &[(trust_cg_lower::Function, trust_cg_lower::ProofContext)],
        prepare: impl Fn(
            &Self,
            &trust_cg_lower::Function,
            &trust_cg_lower::ProofContext,
        ) -> Result<T, PipelineError>
        + Sync,
    ) -> Vec<Result<T, PipelineError>> {
        let prepare_serially = || {
            inputs
                .iter()
                .map(|(func, proof_ctx)| prepare(self, func, proof_ctx))
                .collect()
        };

        let worker_count = match crate::resource_limits::worker_count_for_items(inputs.len()) {
            Ok(workers) => workers,
            Err(error) => {
                return inputs
                    .iter()
                    .map(|_| Err(PipelineError::ResourceBudget(error)))
                    .collect();
            }
        };
        if self.profile_generate_sink.is_some() {
            // The metadata lock prevents overlaps, not completion-order-dependent
            // slot assignment. Keep module-wide profile indices in input order.
            return prepare_serially();
        }
        let Some(worker_count) = worker_count else {
            // Not enough work to justify parallel overhead — run serially in
            // input order (byte-identical to the parallel success path).
            return prepare_serially();
        };

        let pool = match crate::resource_limits::build_rayon_pool(worker_count) {
            Ok(pool) => pool,
            // Pool construction failed: degrade to a deterministic serial pass
            // rather than failing the whole batch. Same observable output.
            Err(_) => return prepare_serially(),
        };

        // `par_iter().map().collect::<Vec<_>>()` preserves input order, so
        // `results[i]` corresponds to `inputs[i]`. Each closure invocation
        // operates on its own input/machine state. The shared profiling sink
        // cannot reach this branch; optional CEGIS cache ownership is separate.
        use rayon::prelude::*;
        let preparation_environment =
            trust_cg_process_env::EnvOverrideSnapshot::capture_current_thread();
        pool.install(|| {
            inputs
                .par_iter()
                .map(|(func, proof_ctx)| {
                    preparation_environment.run(|| prepare(self, func, proof_ctx))
                })
                .collect()
        })
    }

    /// [`Self::prepare_function_with_metrics_and_trust_ir_module`], returning
    /// the prepared function sealed with the final-stream check its
    /// preparation ran and passed (see [`Self::prepare_function_checked`]).
    pub fn prepare_function_checked_with_trust_ir_module(
        &self,
        input: &trust_cg_lower::Function,
        proof_ctx: Option<&trust_cg_lower::ProofContext>,
        trust_ir_module: &trust_ir::Module,
        trust_ir_func: &trust_ir::Function,
    ) -> Result<(CheckedAarch64Function, PreparationMetrics), PipelineError> {
        let (function, mut metrics, provenance, check) = self
            .prepare_function_with_metrics_provenance_and_check(
                input,
                proof_ctx,
                Some(PreparationTrustIrSource::Diagnostic(
                    trust_ir_module,
                    trust_ir_func,
                )),
                Aarch64DirectCallAdmission::Compatibility,
            )?;
        self.retain_debug_provenance(&mut metrics, provenance);
        Ok((CheckedAarch64Function { function, check }, metrics))
    }

    /// [`Self::prepare_function_with_metrics`], returning the prepared
    /// function sealed with the final-stream check its preparation ran and
    /// passed. A [`JitCompiler`](crate::jit::JitCompiler) encoding it through
    /// `compile_raw_checked` does not run that identical check a second time;
    /// the function, the metrics and every emitted byte are the same.
    pub fn prepare_function_checked(
        &self,
        input: &trust_cg_lower::Function,
        proof_ctx: Option<&trust_cg_lower::ProofContext>,
    ) -> Result<(CheckedAarch64Function, PreparationMetrics), PipelineError> {
        let (function, mut metrics, provenance, check) = self
            .prepare_function_with_metrics_provenance_and_check(
                input,
                proof_ctx,
                None,
                Aarch64DirectCallAdmission::Compatibility,
            )?;
        self.retain_debug_provenance(&mut metrics, provenance);
        Ok((CheckedAarch64Function { function, check }, metrics))
    }

    /// Like [`prepare_function_with_proofs`](Self::prepare_function_with_proofs)
    /// but also records per-phase timings and register-allocation spill-slot
    /// counts for downstream observability.
    pub fn prepare_function_with_metrics(
        &self,
        input: &trust_cg_lower::Function,
        proof_ctx: Option<&trust_cg_lower::ProofContext>,
    ) -> Result<(IrMachFunction, PreparationMetrics), PipelineError> {
        let (ir_func, mut metrics, provenance) = self
            .prepare_function_with_metrics_and_provenance(
                input,
                proof_ctx,
                None,
                Aarch64DirectCallAdmission::Compatibility,
            )?;
        self.retain_debug_provenance(&mut metrics, provenance);
        Ok((ir_func, metrics))
    }

    /// Like [`prepare_function_with_metrics`](Self::prepare_function_with_metrics),
    /// but also returns the post-optimization trust_ir-to-MachIR provenance map
    /// when the input carried trust_ir origins.
    ///
    /// The returned map has not been encoded yet, so binary-offset queries are
    /// populated only after the caller encodes with
    /// [`encode_function_with_fixups_and_blocks_with_provenance`] and calls
    /// [`trust_cg_ir::ProvenanceMap::build_transitive`].
    pub fn prepare_function_with_metrics_and_provenance_map(
        &self,
        input: &trust_cg_lower::Function,
        proof_ctx: Option<&trust_cg_lower::ProofContext>,
    ) -> Result<
        (
            IrMachFunction,
            PreparationMetrics,
            Option<trust_cg_ir::ProvenanceMap>,
        ),
        PipelineError,
    > {
        self.prepare_function_with_metrics_and_provenance(
            input,
            proof_ctx,
            None,
            Aarch64DirectCallAdmission::Compatibility,
        )
    }

    /// Like [`prepare_function_with_metrics`](Self::prepare_function_with_metrics),
    /// retaining the older trust_ir-aware call shape for callers that have the
    /// source function handy. Proof-citation provenance now comes from the
    /// lowered function's explicit trust_ir-origin sidecar.
    pub fn prepare_function_with_metrics_and_trust_ir_provenance(
        &self,
        input: &trust_cg_lower::Function,
        proof_ctx: Option<&trust_cg_lower::ProofContext>,
        trust_ir_func: &trust_ir::Function,
    ) -> Result<(IrMachFunction, PreparationMetrics), PipelineError> {
        // Without the module the signature (and so `is_vararg`) is not
        // visible here; the byval attribute is, and is refused by name.
        trust_cg_lower::reject_byval_params(trust_ir_func).map_err(PipelineError::IrLowering)?;
        let (ir_func, mut metrics, provenance) = self
            .prepare_function_with_metrics_and_provenance(
                input,
                proof_ctx,
                None,
                Aarch64DirectCallAdmission::Compatibility,
            )?;
        self.retain_debug_provenance(&mut metrics, provenance);
        Ok((ir_func, metrics))
    }

    /// Like [`prepare_function_with_metrics_and_trust_ir_provenance`](Self::prepare_function_with_metrics_and_trust_ir_provenance),
    /// but retains the trust_ir module context needed by bounded fsym diagnostics.
    pub fn prepare_function_with_metrics_and_trust_ir_module(
        &self,
        input: &trust_cg_lower::Function,
        proof_ctx: Option<&trust_cg_lower::ProofContext>,
        trust_ir_module: &trust_ir::Module,
        trust_ir_func: &trust_ir::Function,
    ) -> Result<(IrMachFunction, PreparationMetrics), PipelineError> {
        let (ir_func, mut metrics, provenance) = self
            .prepare_function_with_metrics_and_provenance(
                input,
                proof_ctx,
                Some(PreparationTrustIrSource::Diagnostic(
                    trust_ir_module,
                    trust_ir_func,
                )),
                Aarch64DirectCallAdmission::Compatibility,
            )?;
        self.retain_debug_provenance(&mut metrics, provenance);
        Ok((ir_func, metrics))
    }

    /// Prepare one function for the authenticated Core compiler while keeping
    /// catalog-bound native calls alive until its exact post-encoding
    /// occurrence check.
    #[cfg_attr(not(feature = "verify"), allow(dead_code))]
    pub(crate) fn prepare_function_with_metrics_for_sealed_core(
        &self,
        input: &trust_cg_lower::Function,
        proof_ctx: Option<&trust_cg_lower::ProofContext>,
        trust_ir_module: &trust_ir::Module,
        function_ordinal: usize,
    ) -> Result<(IrMachFunction, PreparationMetrics), PipelineError> {
        let (ir_func, mut metrics, provenance) = self
            .prepare_function_with_metrics_and_provenance(
                input,
                proof_ctx,
                Some(PreparationTrustIrSource::SealedCore(
                    trust_ir_module,
                    function_ordinal,
                )),
                Aarch64DirectCallAdmission::SealedCore,
            )?;
        self.retain_debug_provenance(&mut metrics, provenance);
        Ok((ir_func, metrics))
    }

    /// Run the ordinary sealed-Core selector and the SAME arena conversion,
    /// retaining its aggregate-result coordinates before optimization. The
    /// caller must own and replay the sealed Core catalog and source bindings.
    /// This diagnostic transition produces no bytes or storage/provider proof.
    pub(crate) fn select_aggregate_transports_for_sealed_core(
        &self,
        input: &trust_cg_lower::Function,
        proof_ctx: &trust_cg_lower::ProofContext,
    ) -> Result<
        (
            trust_cg_lower::isel::ISelFunction,
            IrMachFunction,
            Vec<trust_cg_lower::aggregate_call_transport::MappedAggregateMaterialization>,
        ),
        PipelineError,
    > {
        let (selected, _) = self.run_isel_with_call_admission(
            input,
            Some(proof_ctx),
            Aarch64DirectCallAdmission::SealedCore,
        )?;
        let (machine, mapped) = selected
            .try_to_ir_func_with_aggregate_materializations()
            .map_err(|error| PipelineError::ISel(error.to_string()))?;
        Ok((selected, machine, mapped))
    }

    /// Keep a prepared function's register-debug provenance in its metrics
    /// when this pipeline emits debug information (`-g`), for
    /// [`compile_module_emission_with_debug_provenance`](Self::compile_module_emission_with_debug_provenance).
    /// Without `-g` nothing reads it, so it is dropped here as before.
    fn retain_debug_provenance(
        &self,
        metrics: &mut PreparationMetrics,
        provenance: Option<trust_cg_ir::ProvenanceMap>,
    ) {
        if self.config.emit_debug {
            metrics.debug_provenance = provenance;
        }
    }

    fn prepare_function_with_metrics_and_provenance(
        &self,
        input: &trust_cg_lower::Function,
        proof_ctx: Option<&trust_cg_lower::ProofContext>,
        source_context: Option<PreparationTrustIrSource<'_>>,
        direct_call_admission: Aarch64DirectCallAdmission,
    ) -> Result<
        (
            IrMachFunction,
            PreparationMetrics,
            Option<trust_cg_ir::ProvenanceMap>,
        ),
        PipelineError,
    > {
        self.prepare_function_with_metrics_provenance_and_check(
            input,
            proof_ctx,
            source_context,
            direct_call_admission,
        )
        .map(|(func, metrics, provenance, _check)| (func, metrics, provenance))
    }

    /// [`Self::prepare_function_with_metrics_and_provenance`], also returning
    /// the final-stream check the finished function passed.
    fn prepare_function_with_metrics_provenance_and_check(
        &self,
        input: &trust_cg_lower::Function,
        proof_ctx: Option<&trust_cg_lower::ProofContext>,
        source_context: Option<PreparationTrustIrSource<'_>>,
        direct_call_admission: Aarch64DirectCallAdmission,
    ) -> Result<
        (
            IrMachFunction,
            PreparationMetrics,
            Option<trust_cg_ir::ProvenanceMap>,
            Aarch64FinalStreamCheck,
        ),
        PipelineError,
    > {
        let mut metrics = PreparationMetrics::default();

        let sealed_source = match source_context {
            Some(PreparationTrustIrSource::SealedCore(module, ordinal)) => Some((module, ordinal)),
            _ => None,
        };
        if (direct_call_admission == Aarch64DirectCallAdmission::SealedCore)
            != sealed_source.is_some()
        {
            return Err(PipelineError::AffineLoweringRejected {
                function: input.name.clone(),
                reason: trust_cg_verify::aarch64_affine_lowering::TrustIrAffineLoweringError::InvalidTrustIr(
                    "sealed Core preparation requires an exact module-owned source".into(),
                ),
            });
        }
        let trust_ir_source = match source_context {
            Some(PreparationTrustIrSource::Diagnostic(module, function)) => {
                Some((module, function))
            }
            Some(PreparationTrustIrSource::SealedCore(module, ordinal)) => {
                let function = module.functions.get(ordinal).ok_or_else(|| {
                    PipelineError::AffineLoweringRejected {
                        function: input.name.clone(),
                        reason: trust_cg_verify::aarch64_affine_lowering::TrustIrAffineLoweringError::InvalidTrustIr(
                            format!("missing module function ordinal {ordinal}"),
                        ),
                    }
                })?;
                Some((module, function))
            }
            None => None,
        };

        if let Some((trust_ir_module, trust_ir_func)) = trust_ir_source {
            // The LIR signature cannot express a variadic definition or a byval
            // parameter, so instruction selection would lower either with the
            // fixed/plain-pointer ABI. When the source function is attached,
            // refuse them with the adapter's named diagnostics.
            trust_cg_lower::reject_variadic_definition(trust_ir_func, trust_ir_module)
                .and_then(|()| trust_cg_lower::reject_byval_params(trust_ir_func))
                .map_err(PipelineError::IrLowering)?;
            // Fail-closed: a deref-coverage gap (#49 class) propagates as
            // PipelineError::FsymCoverageGap rather than being swallowed into
            // advisory metrics.
            metrics.fsym_trust_ir_summary =
                self.run_fsym_trust_ir_preflight(trust_ir_module, trust_ir_func)?;
        }

        // Phase 1: Instruction Selection
        let isel_timer = if trust_cg_time_pipeline_enabled() {
            eprintln!(
                "[trust-cg-time-pipeline] start func={} phase=isel",
                input.name
            );
            Some(Instant::now())
        } else {
            None
        };
        let isel_start = Instant::now();
        let (isel_func, value_map) =
            self.run_isel_with_call_admission(input, proof_ctx, direct_call_admission)?;
        let debug_value_bindings = debug_value_binding_vregs(input, value_map.as_ref());
        metrics.timings.isel = Some(isel_start.elapsed());
        if let Some(start) = isel_timer {
            eprintln!(
                "[trust-cg-time-pipeline] end func={} phase=isel elapsed_us={}",
                input.name,
                start.elapsed().as_micros()
            );
        }

        // Phase 2: Convert ISel output to shared IR
        let mut provenance = provenance_from_isel_trust_ir_origins(&isel_func);
        let mut ir_func = isel_func
            .try_to_ir_func()
            .map_err(PipelineError::MachIdAdmission)?;
        ir_func.debug_meta = input.debug_meta.clone();
        ir_func.stack_protector = input.stack_protector;
        ir_func.stack_limit = self.resolve_aarch64_stack_limit(input)?;

        // TV-3 is a RAW lowering-integrity check, not an optimization invariant.
        // Bind its observation to this exact input before any mutating pass.
        // Sealed Core must enforce even if a future caller omits the builder.
        let raw_policy = if direct_call_admission == Aarch64DirectCallAdmission::SealedCore {
            Aarch64DataflowIntegrityPolicy::ProofGradeEnforce
        } else {
            self.raw_dataflow_policy
        };
        metrics.pre_optimization_dataflow_integrity = Some(check_raw_aarch64_dataflow_integrity(
            &ir_func, input, raw_policy,
        )?);

        // L09-P3: the composed transition record starts at the raw selection.
        let mut composition = crate::composed_transition::Session::begin(
            self.composed_transition_policy_for(direct_call_admission),
            &input.name,
        );
        if let Some((module, ordinal)) = sealed_source {
            // Check actual raw selection in the existing streaming Core path.
            // No value_map/provenance claim is trusted, no second ISel runs,
            // and no full function clone is retained. Only summary counts
            // survive: the borrowed checked-triple owner ends before mutation.
            // The composed record keeps the interfaces it was checked at.
            let checked = check_core_affine_lowering(module, ordinal, input, &ir_func)?;
            composition.legalization(
                match &checked {
                    PreOptimizationAffineLowering::Checked(_) => {
                        crate::composed_transition::Legalization::Checked { module, ordinal }
                    }
                    PreOptimizationAffineLowering::UnsupportedSource { reason } => {
                        crate::composed_transition::Legalization::NotCovered(format!(
                            "unsupported affine TrustIR: {reason}"
                        ))
                    }
                },
                input,
                &ir_func,
            );
            metrics.pre_optimization_affine_lowering = Some(checked);
        } else if composition.policy() != crate::composed_transition::ComposedTransitionPolicy::Off
        {
            composition.legalization(
                composed_legalization(trust_ir_source, input, &ir_func),
                input,
                &ir_func,
            );
        }

        // Phase 2.5: Propagate proof annotations from ProofContext onto MachInsts.
        //
        // The adapter's ProofContext maps LIR Values to proof annotations.
        // The ISel's value_map maps LIR Values to VRegs/operands.
        // We build a VReg->InstId reverse map from the IR function, then
        // annotate defining instructions with proof annotations.
        if trust_cg_lower::guard_evidence::validator_guard_replay_authority_available()
            && let (Some(ctx), Some(vmap)) = (proof_ctx, &value_map)
        {
            apply_proof_annotations(&mut ir_func, ctx, vmap);
        }

        // Edge-connectivity check (non-fatal).
        //
        // This was originally `debug_assert!(total_succs > 0, ..)` but that
        // fired on legal trust_ir whose non-entry blocks all terminate with
        // `Return` (no `Br`/`CondBr` edges). After DCE such blocks are
        // harmless — register allocation, frame lowering, and encoding all
        // operate per-block and do not require inter-block connectivity.
        // Tripping the assert prevented the pipeline from being a total
        // function over valid trust_ir (#447: panic-fuzz totality). We keep the
        // shape of the check as a no-op sentinel for future debugging.
        #[cfg(debug_assertions)]
        {
            let has_branches = ir_func.blocks.len() > 1;
            if has_branches {
                let _total_succs: usize = ir_func.blocks.iter().map(|b| b.succs.len()).sum();
                let _total_preds: usize = ir_func.blocks.iter().map(|b| b.preds.len()).sum();
                // Tolerated: _total_succs == 0 or _total_preds == 0 is a legal
                // (if unusual) multi-block shape — see issue #447.
            }
        }

        // ProofFact sidecars (NoAlias, Aligned, NoUndef, ranges, and related facts) are as
        // producer-constructible as the single proof annotation field.  Keep them in ISel and the
        // ProofContext for reporting, but do not feed them to behavior-changing optimization passes
        // until exact replay authority is available.
        let proof_optimization_metadata =
            if trust_cg_lower::guard_evidence::validator_guard_replay_authority_available() {
                let mut metadata = proof_optimization_metadata_from_isel_facts(&isel_func);
                if let (Some(ctx), Some(vmap)) = (proof_ctx, &value_map) {
                    merge_proof_optimization_metadata(
                        &mut metadata,
                        proof_optimization_metadata_from_context(&ir_func, ctx, vmap),
                    );
                }
                (!metadata.proof_facts().is_empty()).then_some(metadata)
            } else {
                None
            };

        // Phase 2.75: always install the empty-authority production guard gate.  Status/lineage and
        // annotations remain report metadata; none can authorize deletion without exact replay.
        debug_assert!(guard_kernel_gate_enabled());
        let kernel_gate = build_guard_kernel_gate(
            &mut ir_func,
            &isel_func,
            proof_ctx,
            trust_ir_source.map(|(module, _)| module),
        );

        // Phase 3: Optimization (including proof-consuming optimizations)
        let phase_timer = log_pipeline_phase_start(&ir_func, "optimization");
        let optimization_start = Instant::now();
        let validation = self.composed_optimization_validation(&composition);
        let mut optimization_stats = self.run_optimization_with_proof_metadata_and_gate_checked(
            &mut ir_func,
            proof_optimization_metadata,
            provenance.as_mut(),
            kernel_gate,
            validation,
        )?;
        composition.pass_runs(std::mem::take(
            &mut optimization_stats.pass_validation.transitions,
        ));
        // Sentinel S4 (AArch64 production parity with x86): fail closed if the
        // independent re-check of any kernel-authorized guard elimination
        // rejects. The boxed proof pass surfaces its re-check verdict through
        // `PassStats::kernel_recheck`; a rejection aborts the compile before
        // regalloc/encoding can emit code that deleted a guard it could not
        // independently re-justify.
        if let Err(reason) = optimization_stats.kernel_recheck() {
            return Err(PipelineError::GuardKernelRecheckRejected(format!(
                "in `{}`: {reason}",
                ir_func.name
            )));
        }
        metrics.proof_optimization_certificates = proof_optimization_certificate_citations(
            &ir_func.name,
            &optimization_stats.proof_optimization_certificates,
        );
        metrics.certified_pass_runs = optimization_stats.certified_pass_runs.clone();
        metrics.optimization_pass_changes = optimization_stats.changed_runs.clone();
        metrics.pass_validation = optimization_stats.pass_validation.clone();
        metrics.timings.optimization = Some(optimization_start.elapsed());
        log_pipeline_phase_end(&ir_func, "optimization", phase_timer);

        // Phase 3.5: Verification (optional)
        let phase_timer = log_pipeline_phase_start(&ir_func, "verification");
        let verification_start = Instant::now();
        self.run_verification(&ir_func)?;
        if self.function_verification_selected(&ir_func.name) {
            metrics.timings.verification = Some(verification_start.elapsed());
        }
        log_pipeline_phase_end(&ir_func, "verification", phase_timer);

        // Phase 3.75: AOT PGO counter injection (profile-generate mode only).
        //
        // Deliberately AFTER optimization + verification (the canary must
        // count the SAME optimized CFG a later profile-use compile will query,
        // and the counters must not perturb or be moved by the optimizer) and
        // BEFORE register allocation (the increments use fresh vregs that the
        // allocator assigns like any other code). `None` sink = byte-identical
        // default path.
        self.inject_profile_counters(&mut ir_func)?;

        #[cfg(test)]
        crate::composed_transition::test_hooks::unvalidated_step(&mut ir_func);

        // L10-P1: capture the function entering register allocation.
        let mut value_flow = self.begin_post_ra_value_flow_with(validation.config, &ir_func);
        composition.pre_allocation(&ir_func);

        // Phase 4-6: Register Allocation
        let phase_timer = log_pipeline_phase_start(&ir_func, "regalloc");
        let regalloc_start = Instant::now();
        let regalloc = self.run_regalloc(&mut ir_func)?;
        metrics.spill_slot_count = regalloc.spill_slot_count;
        metrics.post_ra_copies_coalesced = regalloc.post_ra_copies_coalesced;
        metrics.timings.regalloc = Some(regalloc_start.elapsed());
        log_pipeline_phase_end(&ir_func, "regalloc", phase_timer);

        // Phase 6.5: Lower pseudo Copy instructions to real moves.
        let phase_timer = log_pipeline_phase_start(&ir_func, "copy-lowering");
        lower_copies(&mut ir_func)?;
        eliminate_dead_unallocated_defs(&mut ir_func);
        bind_dead_unallocated_defs_to_discard_registers(&mut ir_func)?;
        ensure_no_unresolved_vregs(&ir_func, "regalloc/copy lowering")?;
        log_pipeline_phase_end(&ir_func, "copy-lowering", phase_timer);
        self.check_post_ra_value_flow_composed(
            &mut value_flow,
            trust_cg_verify::post_ra_value_flow::Stage::Allocation,
            &ir_func,
            None,
            Some(&mut metrics.pass_validation),
            Some(&mut composition),
        )?;

        // Phase 7: Frame Lowering
        let phase_timer = log_pipeline_phase_start(&ir_func, "frame-lowering");
        let frame_lowering_start = Instant::now();
        let frame_layout =
            self.run_frame_lowering_for_source(&mut ir_func, Some(input), direct_call_admission)?;
        // Retain the layout so module callers can thread it into whole-module
        // unwind-table emission (`compile_module_with_globals_and_layouts`).
        metrics.frame_layout = Some(frame_layout);
        metrics.timings.frame_lowering = Some(frame_lowering_start.elapsed());
        log_pipeline_phase_end(&ir_func, "frame-lowering", phase_timer);

        // Phase 7.25: Expand proof-only guards before branch resolution.
        crate::lower::expand_trap_bounds_check_exact(&mut ir_func);
        crate::lower::expand_trap_null_if_zero(&mut ir_func);
        crate::lower::expand_trap_div_zero_if_zero(&mut ir_func);
        crate::lower::expand_trap_shift_range_if_oob(&mut ir_func);
        crate::lower::expand_trap_overflow_exact(&mut ir_func);
        expand_aarch64_llsc_atomics(&mut ir_func)?;

        // Phase 7.4: Fall-through branch layout (O2/O3).
        self.apply_aarch64_branch_layout(&mut ir_func, Some(&mut metrics.pass_validation))?;

        // Phase 7.5: Branch Resolution
        let phase_timer = log_pipeline_phase_start(&ir_func, "branch-resolution");
        let branch_resolution_start = Instant::now();
        resolve_branches_after_authority(&mut ir_func)?;
        let (evidence, final_stream_check) = self.recheck_aarch64_post_regalloc_checked(
            &ir_func,
            direct_call_admission.integrity_policy(),
        )?;
        self.check_post_ra_value_flow_composed(
            &mut value_flow,
            trust_cg_verify::post_ra_value_flow::Stage::FrameLayout,
            &ir_func,
            metrics.frame_layout.as_ref(),
            Some(&mut metrics.pass_validation),
            Some(&mut composition),
        )?;
        metrics.aarch64_machine_code = Some(evidence);
        metrics.stack_limit_certificate = self.certify_aarch64_stack_limit(input, &ir_func)?;
        // X-OPCODES-P6: the final stream performs the source's volatile
        // accesses, in order, on every path. Enforced on every preparation.
        metrics.volatile_access_preservation =
            Some(check_aarch64_volatile_access_preservation(input, &ir_func)?);
        metrics.timings.branch_resolution = Some(branch_resolution_start.elapsed());
        log_pipeline_phase_end(&ir_func, "branch-resolution", phase_timer);

        seed_spilled_value_debug_provenance(
            &ir_func,
            &mut provenance,
            &regalloc.debug_snapshot,
            &debug_value_bindings,
        )?;
        seed_register_value_debug_provenance(&ir_func, &mut provenance, &regalloc.debug_snapshot)?;
        seed_constant_value_debug_provenance(&ir_func, &mut provenance)?;
        seed_stack_alloca_debug_provenance(&ir_func, &mut provenance)?;

        // L09-P3: the chain's last link encodes the final function under the
        // proof-grade policy; the route then publishes exactly these bytes.
        if composition.recording() {
            // Its ENC-5 telemetry would count the published function twice.
            let encoded =
                crate::decode_check::without_telemetry(|| encode_for_composed_transition(&ir_func));
            composition.encoding(
                &ir_func,
                match &encoded {
                    Ok((code, fixups)) => Ok((code.as_slice(), *fixups)),
                    Err(error) => Err(error.to_string()),
                },
            );
        }
        metrics.composed_transition = composition.finish();

        Ok((ir_func, metrics, provenance, final_stream_check))
    }

    /// Phases 1-2 alone: instruction selection and the conversion to the
    /// canonical machine IR behind the L10-P5 identity admission, with the
    /// source's debug, stack-protector and stack-limit requirements attached
    /// as [`Self::compile_function`] attaches them. The result is the
    /// optimizer's input; [`Self::prepare_ir_function`] continues from it.
    pub fn select_ir_function(
        &self,
        input: &trust_cg_lower::Function,
    ) -> Result<IrMachFunction, PipelineError> {
        let (isel_func, _value_map) = self.run_isel(input, None)?;
        let mut ir_func = isel_func
            .try_to_ir_func()
            .map_err(PipelineError::MachIdAdmission)?;
        ir_func.debug_meta = input.debug_meta.clone();
        ir_func.stack_protector = input.stack_protector;
        ir_func.stack_limit = self.resolve_aarch64_stack_limit(input)?;
        Ok(ir_func)
    }

    /// Prepare a pre-built IR function through phases 3-7.5 (optimization
    /// through branch resolution) without encoding or Mach-O emission.
    ///
    /// Like [`prepare_function`](Self::prepare_function) but skips ISel,
    /// accepting an `IrMachFunction` directly. The returned function is ready
    /// for [`compile_module`](Self::compile_module).
    pub fn prepare_ir_function(&self, ir_func: &mut IrMachFunction) -> Result<(), PipelineError> {
        self.validate_aarch64_mach_function_for_profile(ir_func)?;

        // Phase 3: Optimization
        self.run_optimization_checked(ir_func)?;

        // Phase 3.5: Verification (optional)
        self.run_verification(ir_func)?;

        self.inject_profile_counters(ir_func)?;

        // L10-P1: capture the function entering register allocation.
        let mut value_flow = self.begin_post_ra_value_flow(ir_func);

        // Phase 4-6: Register Allocation
        let _regalloc = self.run_regalloc(ir_func)?;

        // Phase 6.5: Lower pseudo Copy instructions to real moves.
        lower_copies(ir_func)?;
        eliminate_dead_unallocated_defs(ir_func);
        bind_dead_unallocated_defs_to_discard_registers(ir_func)?;
        ensure_no_unresolved_vregs(ir_func, "regalloc/copy lowering")?;
        self.check_post_ra_value_flow(
            &mut value_flow,
            trust_cg_verify::post_ra_value_flow::Stage::Allocation,
            ir_func,
            None,
            None,
        )?;

        // Phase 7: Frame Lowering
        let frame_layout = self.run_frame_lowering(ir_func)?;

        // Phase 7.25: Expand proof-only guards before branch resolution.
        crate::lower::expand_trap_bounds_check_exact(ir_func);
        crate::lower::expand_trap_null_if_zero(ir_func);
        crate::lower::expand_trap_div_zero_if_zero(ir_func);
        crate::lower::expand_trap_shift_range_if_oob(ir_func);
        crate::lower::expand_trap_overflow_exact(ir_func);
        expand_aarch64_llsc_atomics(ir_func)?;

        // Phase 7.4: Fall-through branch layout (O2/O3).
        self.apply_aarch64_branch_layout(ir_func, None)?;

        // Phase 7.5: Branch Resolution
        resolve_branches_after_authority(ir_func)?;
        self.recheck_aarch64_post_regalloc(ir_func)?;
        self.check_post_ra_value_flow(
            &mut value_flow,
            trust_cg_verify::post_ra_value_flow::Stage::FrameLayout,
            ir_func,
            Some(&frame_layout),
            None,
        )?;

        Ok(())
    }

    /// Encode an already-allocated IR function to Mach-O.
    ///
    /// Skips ISel, optimization, and regalloc. Useful for testing the
    /// encoding and emission phases in isolation.
    pub fn encode_and_emit(&self, ir_func: &mut IrMachFunction) -> Result<Vec<u8>, PipelineError> {
        reject_unsupported_aarch64_object_format(&self.config.target_triple)?;
        self.validate_aarch64_mach_function_for_profile(ir_func)?;

        // Phase 7: Frame Lowering
        let frame_layout = self.run_frame_lowering(ir_func)?;

        // Phase 7.25: Expand proof-only guards before encoding.
        crate::lower::expand_trap_bounds_check_exact(ir_func);
        crate::lower::expand_trap_null_if_zero(ir_func);
        crate::lower::expand_trap_div_zero_if_zero(ir_func);
        crate::lower::expand_trap_shift_range_if_oob(ir_func);
        crate::lower::expand_trap_overflow_exact(ir_func);
        expand_aarch64_llsc_atomics(ir_func)?;

        // Phase 7.5: Branch Resolution. Input branches are symbolic (the
        // profile validation above refuses resolved immediates), and frame
        // lowering adds its own: stack-probe loops and the guard-failure edge.
        resolve_branches_after_authority(ir_func)?;
        self.recheck_aarch64_post_regalloc(ir_func)?;

        // Phase 8: Encoding. Capture block offsets when EH is present so any
        // unresolved EH metadata can be bound to the exact final BL/BLR and
        // landing-pad offsets before LSDA generation. Pre-authored offsets are
        // accepted only when they exactly match the final encoding.
        let (code, fixups, eh_block_offsets) = if ir_func.eh_metadata.has_eh_info() {
            let (code, fixups, block_offsets) =
                encode_function_with_fixups_and_blocks_impl_with_sites(
                    ir_func,
                    None,
                    None,
                    self.aarch64_integrity_policy,
                )?;
            (code, fixups, Some(block_offsets))
        } else {
            let (code, fixups) =
                encode_function_with_fixups_under(ir_func, self.aarch64_integrity_policy)?;
            (code, fixups, None)
        };

        // Phase 8.5: LSDA Generation
        if let Some(block_offsets) = &eh_block_offsets {
            resolve_eh_offsets_with_propagation(
                ir_func,
                block_offsets,
                code.len(),
                &self.eh_propagation,
            )?;
        }
        let lsda = generate_lsda_for_function(ir_func)?;

        // ELF target: emit with `.eh_frame` (and `.gcc_except_table` when the
        // function carries EH structure) — same fork as `compile_function`.
        // A single-function object binds its function `STB_GLOBAL`; a
        // non-ELF format refuses `pie`/`pic` here rather than ignore them.
        reject_aarch64_object_relocation_model_violations(
            self.config.relocation_model,
            &self.config.target_triple,
            std::slice::from_ref(&ir_func.name),
            &ElfModuleSymbolPlan::legacy(),
            &[],
            &fixups,
        )?;
        if target_triple_uses_elf(&self.config.target_triple) {
            let personality = if lsda.is_some() {
                Some(
                    crate::exception_handling::required_personality_symbol(
                        ir_func.eh_metadata.personality.as_deref(),
                    )
                    .map_err(|error| PipelineError::MalformedAarch64Eh {
                        function: ir_func.name.clone(),
                        detail: format!("invalid exception-handling personality: {error}"),
                    })?,
                )
            } else {
                None
            };
            let debug =
                self.elf_single_function_debug_image(ir_func, &code, &frame_layout, None)?;
            if let Some(obj_bytes) = emit_single_function_target_elf_if_needed(
                &self.config.target_triple,
                &ir_func.name,
                &code,
                &fixups,
                lsda.as_ref().zip(personality),
                Some(&frame_layout),
                ir_func.text_align_log2,
                self.function_sections,
                debug.as_ref(),
            )? {
                return Ok(obj_bytes);
            }
        }

        // Phase 9: Mach-O Emission (with compact unwind + LSDA)
        let obj_bytes = self.emit_macho(
            ir_func,
            &code,
            Some(&frame_layout),
            lsda.as_ref(),
            None,
            Some(&fixups),
        )?;

        Ok(obj_bytes)
    }

    /// Compile multiple pre-built IR functions into a single Mach-O .o file.
    ///
    /// All functions are concatenated into one `__text` section. Cross-function
    /// BL/B instructions with [`Symbol`](IrOperand::Symbol) operands are resolved
    /// into `ARM64_RELOC_BRANCH26` relocations, allowing the linker (or a
    /// subsequent static link step) to patch the call targets.
    ///
    /// This is the correct path for producing .o files with multiple functions —
    /// unlike [`compile_function`](Self::compile_function) which produces one .o
    /// per function and cannot represent cross-function calls.
    ///
    /// Each function must already be in post-regalloc, post-frame-lowering state
    /// (physical registers, branches resolved). The caller can prepare functions
    /// using the pipeline's individual phases or by building IR directly.
    pub fn compile_module(&self, functions: &[IrMachFunction]) -> Result<Vec<u8>, PipelineError> {
        self.compile_module_with_globals(functions, &[])
    }

    #[cfg(feature = "verify")]
    pub fn module_relocation_inventory_report(
        &self,
        functions: &[IrMachFunction],
        object_name: impl Into<String>,
    ) -> Result<Option<trust_cg_verify::ObjectRelocationInventoryReport>, PipelineError> {
        self.module_relocation_inventory_report_with_object_state(functions, &[], &[], object_name)
    }

    /// Build the relocation inventory from the production module's complete
    /// relocation-bearing input surface.
    ///
    /// Unlike the legacy code/fixup-only wrapper above, this includes relocation
    /// rows introduced after text encoding: global-data pointer slots, Darwin
    /// TLV descriptors, whole-module compact-unwind / DWARF fallback records,
    /// and ELF FDEs. Certified-object promotion must use this method so an
    /// known object-side row can sit outside the proof authority boundary. This
    /// pre-emission report MIRRORS the emitters' relocation construction; it
    /// is not an exact-object digest. The per-object binding half of the
    /// Certified composition is the shared ELF reparse gate, which the
    /// checked-write funnel runs over every emitted object's exact bytes (a
    /// record mismatch fails the write closed, so a promoted-but-unreparsed
    /// object cannot exist). That this mirror and the emitters agree on WHICH
    /// rows exist is checked after emission by `Compiler::compile`: the
    /// object's relocation-type multiset must equal the report's kinds (on
    /// Mach-O with each record's modeled shape, SUBTRACTOR pairing and ADDEND
    /// prefix checked too,
    /// [`crosscheck_aarch64_macho_relocation_inventory_digest`]), and on
    /// AArch64 ELF every `.eh_frame` / `DW.ref` record must equal a mirrored
    /// [`AArch64ElfUnwindRelocationRow`]
    /// ([`crosscheck_aarch64_elf_unwind_relocation_rows`]). Any new emitter
    /// relocation must still be added to this mirror in the same change.
    #[cfg(feature = "verify")]
    pub fn module_relocation_inventory_report_with_object_state(
        &self,
        functions: &[IrMachFunction],
        globals: &[ObjectGlobal],
        frame_layouts: &[Option<crate::frame::FrameLayout>],
        object_name: impl Into<String>,
    ) -> Result<Option<trust_cg_verify::ObjectRelocationInventoryReport>, PipelineError> {
        self.module_relocation_inventory_report_with_symbol_linkage(
            functions,
            globals,
            frame_layouts,
            &ModuleSymbolLinkage::default(),
            object_name,
        )
    }

    /// [`module_relocation_inventory_report_with_object_state`](Self::module_relocation_inventory_report_with_object_state)
    /// for an emission carrying `symbol_linkage`.
    ///
    /// Bindings add no relocation row. A weak undefined reference does,
    /// however, change what a direct branch resolves to: for
    /// `R_AARCH64_CALL26`/`JUMP26` against an undefined weak symbol the
    /// linker substitutes an implementation-defined target (a PLT slot or the
    /// next instruction) instead of the modeled `S + A - P` value, so such a
    /// module refuses the inventory (fail-closed) rather than certify that
    /// row. GOT and absolute references to weak symbols keep their modeled
    /// formulas with `S = 0`.
    ///
    /// Every exception-table row is `Unverified` in the report, so an EH
    /// module's report is never promotable. A caller that cross-checks the
    /// emitted object uses
    /// [`module_relocation_inventory_with_symbol_linkage`](Self::module_relocation_inventory_with_symbol_linkage).
    #[cfg(feature = "verify")]
    pub fn module_relocation_inventory_report_with_symbol_linkage(
        &self,
        functions: &[IrMachFunction],
        globals: &[ObjectGlobal],
        frame_layouts: &[Option<crate::frame::FrameLayout>],
        symbol_linkage: &ModuleSymbolLinkage,
        object_name: impl Into<String>,
    ) -> Result<Option<trust_cg_verify::ObjectRelocationInventoryReport>, PipelineError> {
        Ok(self
            .module_relocation_inventory_with_symbol_linkage(
                functions,
                globals,
                frame_layouts,
                symbol_linkage,
                object_name,
            )?
            .map(ModuleRelocationInventory::into_report_without_rows))
    }

    /// [`module_relocation_inventory_report_with_symbol_linkage`](Self::module_relocation_inventory_report_with_symbol_linkage)
    /// plus the exact `.eh_frame` / `DW.ref` rows the AArch64 ELF inventory
    /// mirrored, so the caller can check them against the emitted object.
    ///
    /// Exception handling. On AArch64 ELF an EH module's rows are enumerated
    /// exactly (see [`AArch64ElfUnwindRelocationRow`]): the zPLR CIE's
    /// personality `R_AARCH64_PREL32` against the `DW.ref.<personality>`
    /// slot, one FDE pc-begin and one FDE LSDA `R_AARCH64_PREL32` per
    /// function, and the slot's `R_AARCH64_ABS64` to the personality. The
    /// `.gcc_except_table` carries none: its call-site offsets are
    /// function-relative and its only type-table entries are the NULL
    /// catch-all slots. Every EH shape outside that enumeration is refused
    /// with [`PipelineError::EhSidecarUnsupported`] (fail-closed): Mach-O EH
    /// (compact-unwind personality/LSDA fields and `__eh_frame` pairs are not
    /// enumerated), a typed catch or exception-specification filter, a
    /// non-omitted LPStart or unknown LSDA encoding, more than one
    /// personality, a CIE whose pointer encodings differ from the mirrored
    /// ones, and an EH module without a frame layout for every function.
    ///
    /// Enumerating the rows does not make exception tables promotable: they
    /// carry no proof obligation, so every exception-table row is reported
    /// `Unverified` (an EH module's report is never promotable), and
    /// `Compiler` refuses a certified compile with exception tables before
    /// it builds this inventory (`CompileError::ExceptionTablesUnproved`,
    /// `[TCG-EH-UNPROVED]`).
    #[cfg(feature = "verify")]
    pub fn module_relocation_inventory_with_symbol_linkage(
        &self,
        functions: &[IrMachFunction],
        globals: &[ObjectGlobal],
        frame_layouts: &[Option<crate::frame::FrameLayout>],
        symbol_linkage: &ModuleSymbolLinkage,
        object_name: impl Into<String>,
    ) -> Result<Option<ModuleRelocationInventory>, PipelineError> {
        use crate::macho::fixup::FixupList;
        use trust_cg_verify::ObjectRelocationKind;

        reject_unsupported_aarch64_object_format(&self.config.target_triple)?;
        let elf = target_triple_uses_elf(&self.config.target_triple);
        validate_aarch64_object_globals_with(globals, elf)?;
        let _machine_code = self.aarch64_module_machine_code_evidence(functions)?;
        let object_name = object_name.into();

        for func in functions
            .iter()
            .filter(|func| func.eh_metadata.has_eh_info())
        {
            if !elf {
                return Err(PipelineError::EhSidecarUnsupported {
                    function: func.name.clone(),
                    api: "module_relocation_inventory_report",
                    reason: "Mach-O (Darwin) EH object emission adds personality and LSDA \
                             fields to `__LD,__compact_unwind` entries and personality/LSDA \
                             rows to `__eh_frame` FDEs that this inventory does not \
                             enumerate; only AArch64 ELF EH rows are enumerated, so it \
                             refuses rather than return an incomplete or promotable report \
                             (fail-closed)"
                        .to_string(),
                });
            }
            reject_unenumerated_aarch64_elf_eh_metadata(func)?;
        }

        let layouts_complete = !functions.is_empty()
            && (0..functions.len())
                .all(|i| frame_layouts.get(i).is_some_and(|layout| layout.is_some()));

        let estimated_code_size = checked_aarch64_capacity(
            "<module>",
            "estimated combined code capacity",
            functions.len(),
            100,
        )?;
        let mut combined_code = Vec::with_capacity(estimated_code_size);
        let mut combined_fixups = FixupList::new();
        let mut func_offsets: Vec<(String, u64)> = Vec::with_capacity(functions.len());
        let mut func_eh: Vec<ModuleFunctionEhData> = Vec::with_capacity(functions.len());
        for func in functions {
            // Mirror the production emitters' inter-function alignment padding
            // exactly, or the inventory's fixup offsets would drift from the
            // real object's.
            pad_aarch64_text_for_function_alignment(
                &mut combined_code,
                &func.name,
                func.text_align_log2,
            )?;
            let func_start = checked_aarch64_object_u64(
                &func.name,
                "combined text function offset",
                combined_code.len(),
            )?;
            func_offsets.push((func.name.clone(), func_start));
            // The emitters' own encoder: a non-EH function takes the plain
            // module path, an EH function also returns its resolved LSDA and
            // personality.
            let (code, fixups, lsda) = encode_module_function_with_fixups_and_eh(
                func,
                self.aarch64_integrity_policy,
                &self.eh_propagation,
            )?;
            let code_len =
                checked_aarch64_object_u32(&func.name, "encoded code length", code.len())?;
            for fixup in fixups.iter() {
                let mut adjusted = fixup.clone();
                adjusted.offset =
                    checked_aarch64_fixup_offset(&func.name, func_start, fixup.offset)?;
                combined_fixups.push(adjusted);
            }
            func_eh.push(ModuleFunctionEhData { code_len, lsda });
            extend_aarch64_object_code(&mut combined_code, &func.name, &code)?;
        }

        if !elf {
            reject_unsupported_aarch64_object_format(&self.config.target_triple)?;

            // The module DWARF writer emits address relocations derived from
            // source/provenance tables after text encoding. Until those rows
            // are enumerated from the same debug plan, refuse to issue an
            // incomplete inventory rather than silently certify around them.
            if self.config.emit_debug && !functions.is_empty() {
                return Err(PipelineError::ObjectRelocationInventoryIncomplete {
                    object: object_name,
                    reason: "Mach-O DWARF sections emit ARM64_RELOC_UNSIGNED address rows that are not yet enumerated by the certified-object inventory (fail-closed)"
                        .to_string(),
                });
            }

            let mut object_rows = Vec::new();

            // One absolute-pointer relocation for every symbol-address slot in
            // an emitted data definition: a `__DATA,__data` / `__DATA,__const`
            // / explicit-section slot, or a `__DATA,__thread_data` TLS
            // initial-value-template slot. Imports define no section.
            for global in globals.iter().filter(|global| !global.is_import) {
                object_rows.extend(std::iter::repeat_n(
                    ObjectRelocationKind::AArch64MachOUnsigned,
                    global.symbol_refs.len(),
                ));
            }

            // Every Darwin TLV definition emits two absolute descriptor rows:
            // `__tlv_bootstrap` and the initial-value-template pointer.
            let tls_definitions = globals
                .iter()
                .filter(|global| global.is_thread_local && !global.is_import)
                .count();
            object_rows.extend(std::iter::repeat_n(
                ObjectRelocationKind::AArch64MachOUnsigned,
                tls_definitions.saturating_mul(2),
            ));

            // The production Compiler always supplies complete frame layouts.
            // Mach-O then emits one compact-unwind function-pointer row per
            // function; a DWARF-fallback FDE adds a SUBTRACTOR+UNSIGNED pair.
            let (mut compact_entries, mut dwarf_fallbacks) = (0usize, 0usize);
            if layouts_complete {
                for layout in frame_layouts.iter().take(functions.len()).flatten() {
                    object_rows.push(ObjectRelocationKind::AArch64MachOUnsigned);
                    compact_entries += 1;
                    if crate::frame::encode_compact_unwind(layout).needs_dwarf_fallback() {
                        object_rows.push(ObjectRelocationKind::AArch64MachOSubtractor);
                        object_rows.push(ObjectRelocationKind::AArch64MachOUnsigned);
                        dwarf_fallbacks += 1;
                    }
                }
            }

            // AArch64 Mach-O symbolic data relocations: name every emitted row.
            // Registry coverage and the ENC-9 reparse binding decide promotion
            // inside the report; `Compiler::compile` then requires the emitted
            // (or cache-hit) object's records to equal these rows by kind
            // (`crosscheck_aarch64_macho_relocation_inventory_digest`).
            return Ok(Some(ModuleRelocationInventory {
                report: aarch64_macho_relocation_inventory_report(
                    object_name,
                    &combined_fixups,
                    object_rows,
                ),
                elf_unwind_rows: Vec::new(),
                trusted_unwind_tables: aarch64_macho_unwind_trust_disclosure(
                    compact_entries,
                    dwarf_fallbacks,
                ),
            }));
        }

        // Data placement: the emitters' own classification, so a placement
        // they refuse (a reserved name such as `.eh_frame` or
        // `.gcc_except_table`, `[TCG-SECTION-RESERVED]`) is refused here too.
        plan_elf_placed_global_sections(globals)?;

        // The ELF DWARF sections add R_AARCH64_ABS64 code-address rows and
        // R_AARCH64_ABS32 section-offset rows derived from the debug plan after
        // text encoding. They are not enumerated here, so refuse to issue an
        // incomplete inventory, exactly as the Mach-O branch above does.
        if self.config.emit_debug && !functions.is_empty() {
            return Err(PipelineError::ObjectRelocationInventoryIncomplete {
                object: object_name,
                reason: "ELF DWARF sections emit R_AARCH64_ABS64/R_AARCH64_ABS32 rows that are not yet enumerated by the certified-object inventory (fail-closed)"
                    .to_string(),
            });
        }
        let weak_undefined: BTreeSet<&str> = symbol_linkage
            .weak_undefined_functions()
            .iter()
            .map(String::as_str)
            .chain(
                globals
                    .iter()
                    .filter(|global| global.is_import && global.is_weak)
                    .map(|global| global.name.as_str()),
            )
            .collect();
        for fixup in combined_fixups.iter() {
            let crate::macho::FixupTarget::NamedSymbol(name) = &fixup.target else {
                continue;
            };
            if !weak_undefined.contains(name.as_str()) {
                continue;
            }
            let kind = aarch64_elf_reloc_kind(&self.config.target_triple, &combined_code, fixup)?;
            if matches!(
                kind,
                crate::elf::AArch64RelocType::Call26 | crate::elf::AArch64RelocType::Jump26
            ) {
                return Err(PipelineError::ObjectRelocationInventoryIncomplete {
                    object: object_name,
                    reason: format!(
                        "{kind:?} at text offset {:#x} targets weak undefined `{name}`; the \
                         linker's undefined-weak branch resolution is not the modeled S + A - P \
                         value formula (fail-closed)",
                        fixup.offset
                    ),
                });
            }
        }
        let mut object_rows = Vec::new();
        // One `R_AARCH64_ABS64` for every symbol-address slot in an emitted
        // definition, whatever its section: `.data`, `.data.rel.ro`, an
        // explicit or COMDAT section, or a thread-local's `.tdata`
        // initial-value template (`.rela.tdata`). The row names only the
        // S + A value the linker writes into the template; that the TLS
        // runtime copies the relocated template into every thread is loader
        // behavior, not part of this row. Imports define no section.
        for global in globals.iter().filter(|global| !global.is_import) {
            object_rows.extend(std::iter::repeat_n(
                ObjectRelocationKind::AArch64ElfAbs64,
                global.symbol_refs.len(),
            ));
        }
        // The whole-module ELF emitter gives every function an FDE when every
        // frame layout is supplied, even when the module has no EH; an EH
        // module adds the personality, LSDA and `DW.ref` slot rows. Without
        // complete layouts it emits no unwind table, and refuses an EH module.
        let elf_unwind_rows = if layouts_complete {
            self.aarch64_elf_module_unwind_relocation_rows(
                functions,
                globals,
                frame_layouts,
                symbol_linkage,
                &combined_code,
                &func_offsets,
                &func_eh,
            )?
        } else if let Some(func) = functions.iter().find(|func| func.eh_metadata.has_eh_info()) {
            return Err(PipelineError::EhSidecarUnsupported {
                function: func.name.clone(),
                api: "module_relocation_inventory_report",
                reason: "the module carries exception-handling structure but not a frame \
                         layout for every function, so the ELF emitter refuses it (every \
                         function needs an `.eh_frame` FDE) and there is no object to \
                         inventory (fail-closed)"
                    .to_string(),
            });
        } else {
            Vec::new()
        };
        object_rows.extend(
            elf_unwind_rows
                .iter()
                .map(AArch64ElfUnwindRelocationRow::inventory_kind),
        );
        let mut report = aarch64_elf_relocation_inventory_report(
            object_name,
            &self.config.target_triple,
            &combined_code,
            &combined_fixups,
            object_rows,
        )?;
        mark_exception_table_rows_unverified(&mut report, &elf_unwind_rows);
        Ok(Some(ModuleRelocationInventory {
            report,
            trusted_unwind_tables: aarch64_elf_unwind_trust_disclosure(&elf_unwind_rows),
            elf_unwind_rows,
        }))
    }

    /// The AArch64 ELF module emitter's `.eh_frame` and `DW.ref` slot
    /// relocation rows, mirrored for the relocation inventory (every frame
    /// layout supplied).
    ///
    /// The personality choice, `.gcc_except_table` layout, `.eh_frame` CFI
    /// and text placement come from the helpers
    /// [`emit_aarch64_elf_module_with_unwind`] reads; the rows below are
    /// decided here, independently of the emitter's relocation calls:
    ///
    /// * EH module: the CIE personality `R_AARCH64_PREL32` against
    ///   `DW.ref.<personality>` (addend 0);
    /// * every function: its FDE pc-begin `R_AARCH64_PREL32` against its
    ///   text section's `STT_SECTION` anchor, addend its offset in that
    ///   section;
    /// * EH module, every function: its FDE LSDA `R_AARCH64_PREL32` against
    ///   the `.gcc_except_table` anchor, addend its LSDA's offset (a non-EH
    ///   function's LSDA is the synthetic filler);
    /// * EH module: the `.data.DW.ref.<personality>` slot's `R_AARCH64_ABS64`
    ///   to the personality (offset 0, addend 0).
    ///
    /// Every LSDA is checked to need no relocation, and the CIE's pointer
    /// encodings must be the ones these rows assume; anything else is refused.
    #[cfg(feature = "verify")]
    #[allow(clippy::too_many_arguments)]
    fn aarch64_elf_module_unwind_relocation_rows(
        &self,
        functions: &[IrMachFunction],
        globals: &[ObjectGlobal],
        frame_layouts: &[Option<crate::frame::FrameLayout>],
        symbol_linkage: &ModuleSymbolLinkage,
        combined_code: &[u8],
        func_offsets: &[(String, u64)],
        func_eh: &[ModuleFunctionEhData],
    ) -> Result<Vec<AArch64ElfUnwindRelocationRow>, PipelineError> {
        use crate::elf::constants::{R_AARCH64_ABS64, R_AARCH64_PREL32};
        const PCREL_SDATA4: u8 = 0x1b;
        const INDIRECT_PCREL_SDATA4: u8 = 0x9b;
        let refuse = |function: &str, reason: String| PipelineError::EhSidecarUnsupported {
            function: function.to_string(),
            api: "module_relocation_inventory_report",
            reason,
        };

        // Where each body lands: the FDE pc-begin anchor and addend.
        let plan = ElfModuleSymbolPlan::new(symbol_linkage, func_offsets, globals)?;
        let facts = Self::elf_function_facts(functions, func_eh, &plan);
        let text = plan_elf_text(
            crate::elf::ElfMachine::AArch64,
            combined_code,
            func_offsets,
            aarch64_module_text_align_log2(functions),
            ElfTextOptions {
                function_sections: self.function_sections,
                functions: &facts,
            },
        )?;
        if text.functions.len() != functions.len() {
            return Err(PipelineError::ObjectRelocationInventoryIncomplete {
                object: "<module>".to_string(),
                reason: format!(
                    "the ELF text plan placed {} of {} functions (fail-closed)",
                    text.functions.len(),
                    functions.len()
                ),
            });
        }

        // One personality: a second one would need its own CIE and slot.
        let mut first_personality: Option<(&str, &str)> = None;
        for (eh, (function, _)) in func_eh.iter().zip(func_offsets) {
            let Some(lsda) = &eh.lsda else {
                continue;
            };
            let personality = lsda.canonical_personality();
            match first_personality {
                None => first_personality = Some((personality, function.as_str())),
                Some((first, owner)) if first != personality => {
                    return Err(refuse(
                        function,
                        format!(
                            "its personality `{personality}` differs from `{first}` of \
                             `{owner}`; a second personality needs its own CIE and `DW.ref` \
                             slot, and this inventory enumerates one of each (fail-closed)"
                        ),
                    ));
                }
                Some(_) => {}
            }
        }
        let module_has_eh = first_personality.is_some();
        let personality = aarch64_elf_module_personality(func_eh)?;
        if personality != first_personality.map(|(personality, _)| personality) {
            return Err(PipelineError::ObjectRelocationInventoryIncomplete {
                object: "<module>".to_string(),
                reason: format!(
                    "the emitter's personality {personality:?} is not the inventory's \
                     {first_personality:?} (fail-closed)"
                ),
            });
        }
        let (lsda_data, lsda_offsets) = aarch64_elf_module_lsda_table(
            &self.config.target_triple,
            func_eh,
            func_offsets,
            module_has_eh,
            personality,
        )?;
        let cfi = aarch64_elf_module_cfi(func_eh, func_offsets, frame_layouts, module_has_eh)?;

        // The rows below assume these CIE pointer encodings: 4-byte
        // PC-relative FDE and LSDA pointers, and a personality read through
        // the 8-byte `DW.ref` slot.
        let cie = cfi.cie();
        let (augmentation, personality_encoding, lsda_encoding): (&[u8], _, _) = if module_has_eh {
            (b"zPLR\0", Some(INDIRECT_PCREL_SDATA4), Some(PCREL_SDATA4))
        } else {
            (b"zR\0", None, None)
        };
        if cie.augmentation != augmentation
            || cie.fde_pointer_encoding != PCREL_SDATA4
            || cie.personality_encoding != personality_encoding
            || cie.lsda_encoding != lsda_encoding
        {
            let reason = format!(
                "the ELF CIE (augmentation {:?}, FDE pointer {:#04x}, personality {:?}, LSDA \
                 {:?}) does not use the pointer encodings this inventory enumerates \
                 (fail-closed)",
                String::from_utf8_lossy(&cie.augmentation),
                cie.fde_pointer_encoding,
                cie.personality_encoding,
                cie.lsda_encoding
            );
            return Err(match first_personality {
                Some((_, owner)) => refuse(owner, reason),
                None => PipelineError::ObjectRelocationInventoryIncomplete {
                    object: "<module>".to_string(),
                    reason,
                },
            });
        }

        // Every LSDA (real and filler) must need no relocation.
        let mut starts: Vec<(usize, usize)> = lsda_offsets
            .iter()
            .enumerate()
            .filter_map(|(index, start)| {
                start
                    .and_then(|start| usize::try_from(start).ok())
                    .map(|start| (start, index))
            })
            .collect();
        starts.sort_unstable();
        for (position, &(start, index)) in starts.iter().enumerate() {
            let end = starts
                .get(position + 1)
                .map_or(lsda_data.len(), |&(next, _)| next);
            let lsda = lsda_data.get(start..end).ok_or_else(|| {
                PipelineError::ObjectRelocationInventoryIncomplete {
                    object: "<module>".to_string(),
                    reason: format!("LSDA range {start}..{end} is out of bounds (fail-closed)"),
                }
            })?;
            aarch64_elf_lsda_needs_no_relocation(lsda).map_err(|problem| {
                refuse(
                    &func_offsets[index].0,
                    format!(
                        "its `.gcc_except_table` LSDA would need a relocation this inventory \
                         does not enumerate: {problem} (fail-closed)"
                    ),
                )
            })?;
        }

        let pc_begin_fields = cfi.fde_pc_begin_relocation_offsets();
        let lsda_fields = cfi.fde_lsda_relocation_offsets();
        let lsda_field_count = if module_has_eh { functions.len() } else { 0 };
        if pc_begin_fields.len() != functions.len() || lsda_fields.len() != lsda_field_count {
            return Err(PipelineError::ObjectRelocationInventoryIncomplete {
                object: "<module>".to_string(),
                reason: format!(
                    "{} functions but {} FDE pc-begin and {} LSDA fields (fail-closed)",
                    functions.len(),
                    pc_begin_fields.len(),
                    lsda_fields.len()
                ),
            });
        }
        use AArch64ElfRelocationSymbol::{Named, SectionAnchor};
        use AArch64ElfSectionIdentity::{Defining, Unique};
        let row =
            |role, section, offset: u64, r_type, symbol, addend| AArch64ElfUnwindRelocationRow {
                role,
                section,
                offset,
                r_type,
                symbol,
                addend,
            };
        let eh_frame = || Unique(".eh_frame".to_string());
        let mut rows = Vec::with_capacity(2 * functions.len() + 2);
        let personality = match personality {
            Some(personality) => {
                let field = cfi.cie_personality_relocation_offset().ok_or_else(|| {
                    PipelineError::ObjectRelocationInventoryIncomplete {
                        object: "<module>".to_string(),
                        reason: "the zPLR CIE has no personality field (fail-closed)".to_string(),
                    }
                })?;
                rows.push(row(
                    AArch64ElfUnwindRelocationRole::CiePersonality,
                    eh_frame(),
                    u64::from(field),
                    R_AARCH64_PREL32,
                    Named(format!("DW.ref.{personality}")),
                    0,
                ));
                Some(personality)
            }
            None => None,
        };
        for (index, placed) in text.functions.iter().enumerate() {
            let function = func_offsets[index].0.clone();
            let body_offset = i64::try_from(placed.offset).map_err(|_| {
                PipelineError::ObjectRelocationInventoryIncomplete {
                    object: "<module>".to_string(),
                    reason: format!(
                        "`{function}` text offset {} is not a representable addend",
                        placed.offset
                    ),
                }
            })?;
            // pc-begin: the anchor of the section that DEFINES the
            // function's symbol (never a section name: several COMDAT
            // bodies can land in same-named sections), plus its offset.
            rows.push(row(
                AArch64ElfUnwindRelocationRole::FdePcBegin {
                    function: function.clone(),
                },
                eh_frame(),
                u64::from(pc_begin_fields[index]),
                R_AARCH64_PREL32,
                SectionAnchor(Defining(function.clone())),
                body_offset,
            ));
            if module_has_eh {
                let lsda_offset = lsda_offsets[index].ok_or_else(|| {
                    refuse(
                        &function,
                        "its FDE has an LSDA field but no LSDA was laid out (fail-closed)"
                            .to_string(),
                    )
                })?;
                rows.push(row(
                    AArch64ElfUnwindRelocationRole::FdeLsda { function },
                    eh_frame(),
                    u64::from(lsda_fields[index]),
                    R_AARCH64_PREL32,
                    SectionAnchor(Unique(".gcc_except_table".to_string())),
                    lsda_offset,
                ));
            }
        }
        if let Some(personality) = personality {
            // The slot's own section is the one its symbol is defined in.
            rows.push(row(
                AArch64ElfUnwindRelocationRole::PersonalitySlot,
                Defining(format!("DW.ref.{personality}")),
                0,
                R_AARCH64_ABS64,
                Named(personality.to_string()),
                0,
            ));
        }
        Ok(rows)
    }

    pub fn compile_module_with_globals(
        &self,
        functions: &[IrMachFunction],
        globals: &[ObjectGlobal],
    ) -> Result<Vec<u8>, PipelineError> {
        self.compile_module_with_globals_and_layouts(functions, globals, &[])
    }

    /// Like [`compile_module_with_globals`](Self::compile_module_with_globals),
    /// but additionally threads each function's post-frame-lowering
    /// [`FrameLayout`](crate::frame::FrameLayout) (1:1 with `functions`; produced
    /// by [`prepare_function_with_metrics`](Self::prepare_function_with_metrics)
    /// as [`PreparationMetrics::frame_layout`]).
    ///
    /// When a complete layout vector is supplied, whole-module unwind tables
    /// (the x86 EH-Lane-5 analogue, FUZZ-7 [TCG-EH-WALK]) give EVERY function a
    /// `__LD,__compact_unwind` entry — and a DWARF FDE when its frame needs the
    /// fallback — even if the module itself has no handler. That lets an
    /// exception raised below a plain trust-cg frame unwind THROUGH it. A
    /// layout-less non-EH caller emits its code and globals without unwind tables.
    ///
    /// Calling this with an EH-carrying module and missing layouts FAILS CLOSED
    /// (never a silent table drop).
    pub fn compile_module_with_globals_and_layouts(
        &self,
        functions: &[IrMachFunction],
        globals: &[ObjectGlobal],
        frame_layouts: &[Option<crate::frame::FrameLayout>],
    ) -> Result<Vec<u8>, PipelineError> {
        // Byte-identity with every pre-existing caller is structural, not
        // asserted: this IS the emission path, called with no bindings (so every
        // definition is global), with only the reported layout discarded.
        self.compile_module_emission(functions, globals, frame_layouts, &[])
            .map(|emission| emission.object)
    }

    /// Emit a whole-module object AND report where each function's code landed.
    ///
    /// This is [`compile_module_with_globals_and_layouts`](Self::compile_module_with_globals_and_layouts)
    /// plus two things it cannot express:
    ///
    /// * **`bindings`** — per-function symbol binding, 1:1 with `functions` when
    ///   non-empty. An EMPTY slice means every definition is
    ///   [`FunctionSymbolBinding::GLOBAL`], which is exactly the legacy
    ///   behaviour, so an empty-bindings call is byte-for-byte what the older
    ///   entry point produced. A binding is a symbol-table attribute ONLY: it
    ///   never perturbs a code byte, a text offset, or a relocation target.
    /// * **`text_extents`** — the offset and encoded length of every function
    ///   inside the combined text section. A caller that must prove the shipped
    ///   object contains the bytes it verified needs the emitter's own account
    ///   of the layout, not an independent re-derivation of it.
    ///
    /// Every binding is honoured on ELF: the emitters add symbols through the
    /// writer's checked handle API and resolve relocation indices only after
    /// the locals-first table is complete. Mach-O honours local, global, weak
    /// (`N_WEAK_DEF`) and hidden bindings. Weak undefined references need
    /// [`compile_module_emission_with_symbol_linkage`](Self::compile_module_emission_with_symbol_linkage).
    pub fn compile_module_emission(
        &self,
        functions: &[IrMachFunction],
        globals: &[ObjectGlobal],
        frame_layouts: &[Option<crate::frame::FrameLayout>],
        bindings: &[FunctionSymbolBinding],
    ) -> Result<ModuleEmission, PipelineError> {
        self.compile_module_emission_with_target_evidence(
            functions,
            globals,
            frame_layouts,
            bindings,
        )
        .map(AArch64ModuleEmission::into_emission)
    }

    /// Emit a whole-module object while retaining the validated union of
    /// optional AArch64 features required by its machine-code functions.
    ///
    /// Feature derivation reuses the admission walk required by module
    /// emission; it does not rescan the machine functions. The legacy
    /// [`compile_module_emission`](Self::compile_module_emission) delegates here
    /// and drops only the evidence result.
    pub fn compile_module_emission_with_target_evidence(
        &self,
        functions: &[IrMachFunction],
        globals: &[ObjectGlobal],
        frame_layouts: &[Option<crate::frame::FrameLayout>],
        bindings: &[FunctionSymbolBinding],
    ) -> Result<AArch64ModuleEmission, PipelineError> {
        self.compile_module_emission_with_symbol_linkage(
            functions,
            globals,
            frame_layouts,
            &ModuleSymbolLinkage::new(bindings.to_vec(), BTreeSet::new()),
        )
    }

    /// The per-function facts the AArch64 ELF text layout consumes: each
    /// body's encoded length and alignment, whether `plan` makes it a COMDAT
    /// definition (its own grouped section), and its validated explicit
    /// section, if any.
    fn elf_function_facts<'a>(
        functions: &[IrMachFunction],
        func_eh: &[ModuleFunctionEhData],
        plan: &ElfModuleSymbolPlan<'a>,
    ) -> Vec<ElfFunctionFacts<'a>> {
        functions
            .iter()
            .zip(func_eh)
            .map(|(func, eh)| ElfFunctionFacts {
                code_len: u64::from(eh.code_len),
                align_log2: func.text_align_log2,
                comdat: plan.comdat_functions.contains(func.name.as_str()),
                section: plan.explicit_sections.get(func.name.as_str()).copied(),
            })
            .collect()
    }

    /// Whole-module emission carrying the complete [`ModuleSymbolLinkage`]:
    /// per-function definition bindings AND the undefined function references
    /// that must be weak. Weak data references travel on `globals`
    /// (`is_import && is_weak`).
    ///
    /// AArch64 ELF spells every binding and emits each weak reference as an
    /// `STB_WEAK` undefined symbol; a weak name that is also defined here is
    /// refused. Mach-O spells weak definitions (`N_WEAK_DEF`; a COMDAT function
    /// must be one) and refuses weak references (typed
    /// [`PipelineError::TargetObjectUnsupported`]) rather than emit them strong.
    ///
    /// Under `-g` the module DWARF describes subprograms and line rows only;
    /// [`compile_module_emission_with_debug_provenance`](Self::compile_module_emission_with_debug_provenance)
    /// also describes parameters and variables.
    pub fn compile_module_emission_with_symbol_linkage(
        &self,
        functions: &[IrMachFunction],
        globals: &[ObjectGlobal],
        frame_layouts: &[Option<crate::frame::FrameLayout>],
        symbol_linkage: &ModuleSymbolLinkage,
    ) -> Result<AArch64ModuleEmission, PipelineError> {
        self.compile_module_emission_with_debug_variables(
            functions,
            globals,
            frame_layouts,
            symbol_linkage,
            ModuleDebugVariables::LinesOnly,
        )
    }

    /// [`compile_module_emission_with_symbol_linkage`](Self::compile_module_emission_with_symbol_linkage)
    /// whose `-g` DWARF also describes every function's parameters and
    /// variables, as a single-function object does.
    ///
    /// `debug_provenance` is 1:1 with `functions`: each function's
    /// register-debug provenance ([`PreparationMetrics::debug_provenance`] of a
    /// `-g` preparation), or `None` for a function prepared without one, whose
    /// provenance-backed locals then keep their DIEs with empty location
    /// lists. Parameters need no provenance. A function whose
    /// `frame_layouts` slot is absent emits no DIE for a stack-slot local or
    /// an unclaimed frame slot, no frame-slot range for a provenance-backed
    /// local, and an empty location list for a stack-passed parameter. Each
    /// function's locations are built over the instruction list the module
    /// encoder emitted and moved onto the function's text offset; DWARF
    /// emission refuses any range outside its function (a range left
    /// function-relative is refused only when it starts below the
    /// function's text offset). Without `emit_debug` the object is the one
    /// [`compile_module_emission_with_symbol_linkage`](Self::compile_module_emission_with_symbol_linkage)
    /// emits. ELF function sections and COMDAT function text stay refused
    /// under `-g`.
    pub fn compile_module_emission_with_debug_provenance(
        &self,
        functions: &[IrMachFunction],
        globals: &[ObjectGlobal],
        frame_layouts: &[Option<crate::frame::FrameLayout>],
        symbol_linkage: &ModuleSymbolLinkage,
        debug_provenance: &[Option<&trust_cg_ir::ProvenanceMap>],
    ) -> Result<AArch64ModuleEmission, PipelineError> {
        if debug_provenance.len() != functions.len() {
            return Err(PipelineError::DebugInfoInput(format!(
                "module emission received {} debug provenance slot(s) for {} function(s); \
                 they must be 1:1 with the functions (fail-closed)",
                debug_provenance.len(),
                functions.len()
            )));
        }
        self.compile_module_emission_with_debug_variables(
            functions,
            globals,
            frame_layouts,
            symbol_linkage,
            ModuleDebugVariables::WithProvenance(debug_provenance),
        )
    }

    /// The sequential whole-module emitter behind
    /// [`compile_module_emission_with_symbol_linkage`](Self::compile_module_emission_with_symbol_linkage)
    /// and [`compile_module_emission_with_debug_provenance`](Self::compile_module_emission_with_debug_provenance);
    /// `debug_variables` only selects what the `-g` DWARF describes.
    fn compile_module_emission_with_debug_variables(
        &self,
        functions: &[IrMachFunction],
        globals: &[ObjectGlobal],
        frame_layouts: &[Option<crate::frame::FrameLayout>],
        symbol_linkage: &ModuleSymbolLinkage,
        debug_variables: ModuleDebugVariables<'_>,
    ) -> Result<AArch64ModuleEmission, PipelineError> {
        use crate::macho::fixup::FixupList;

        let bindings = symbol_linkage.function_bindings();
        if !bindings.is_empty() && bindings.len() != functions.len() {
            return Err(PipelineError::ObjectEmission(format!(
                "module emission received {} symbol binding(s) for {} function(s); \
                 a binding vector must be empty or 1:1 with the functions",
                bindings.len(),
                functions.len()
            )));
        }

        reject_unsupported_aarch64_object_format(&self.config.target_triple)?;
        validate_aarch64_object_globals_with(
            globals,
            target_triple_uses_elf(&self.config.target_triple),
        )?;
        let machine_code = self.aarch64_module_machine_code_evidence(functions)?;

        // Symbol-address data relocations (vtable / `static FNS: [fn(); N]`
        // slots) are emitted for the Mach-O writer below via
        // `add_global_data_section` → `ARM64_RELOC_UNSIGNED` (the AArch64
        // analogue of the x86-64 emitter's `X86_64_RELOC_UNSIGNED` path). The ELF
        // emitters share `add_aarch64_elf_global_relocations` for ABS64 slots,
        // whether or not the caller supplies unwind frame layouts.

        // Phase 1: Encode each function, collecting code bytes and fixups.
        // Track each function's byte offset within the combined __text section.
        // EH functions additionally resolve their post-layout LSDA here.
        // Pre-allocate based on estimated 4 bytes per instruction * ~25 insts/func.
        let estimated_code_size = checked_aarch64_capacity(
            "<module>",
            "estimated combined code capacity",
            functions.len(),
            100,
        )?;
        let mut combined_code = Vec::with_capacity(estimated_code_size);
        let mut combined_fixups = FixupList::new();
        let mut func_offsets: Vec<(String, u64)> = Vec::with_capacity(functions.len());
        let mut func_eh: Vec<ModuleFunctionEhData> = Vec::with_capacity(functions.len());
        let mut text_extents: Vec<TextFunctionExtent> = Vec::with_capacity(functions.len());

        for func in functions {
            pad_aarch64_text_for_function_alignment(
                &mut combined_code,
                &func.name,
                func.text_align_log2,
            )?;
            let func_start = checked_aarch64_object_u64(
                &func.name,
                "combined text function offset",
                combined_code.len(),
            )?;
            func_offsets.push((func.name.clone(), func_start));

            let (code, fixups, lsda) = encode_module_function_with_fixups_and_eh(
                func,
                self.aarch64_integrity_policy,
                &self.eh_propagation,
            )?;
            let code_len =
                checked_aarch64_object_u32(&func.name, "encoded code length", code.len())?;

            // The layout report is READ OFF the emission, not recomputed: this
            // is the same `func_start` the symbol table gets and the same
            // encoded length the unwind tables get. `func_start` is already
            // past the alignment padding, and `code_len` excludes the padding
            // that follows — so `len` is the function's own bytes, which is
            // what a consumer can compare against that function emitted alone.
            text_extents.push(TextFunctionExtent {
                name: func.name.clone(),
                offset: func_start,
                len: u64::from(code_len),
            });

            // Adjust fixup offsets to be relative to the combined section.
            for fixup in fixups.iter() {
                let mut adjusted = fixup.clone();
                adjusted.offset =
                    checked_aarch64_fixup_offset(&func.name, func_start, fixup.offset)?;
                combined_fixups.push(adjusted);
            }

            func_eh.push(ModuleFunctionEhData { code_len, lsda });
            extend_aarch64_object_code(&mut combined_code, &func.name, &code)?;
        }

        // Select object format based on the configured target triple.
        // Linux-flavored triples produce ELF with whole-module `.eh_frame`
        // unwind tables (walk-through FDEs when layouts are threaded, LSDAs
        // for EH functions); layout-less legacy callers keep the plain
        // emission and an EH module missing layouts fails closed inside.
        // Every ELF emitter resolves relocation symbol indices through the
        // writer's checked handles after the table is complete, so any binding
        // is honoured without shifting a relocation target. The function
        // sections policy and COMDAT definitions only choose the text section
        // each body lands in.
        if target_triple_uses_elf(&self.config.target_triple) {
            let plan = ElfModuleSymbolPlan::new(symbol_linkage, &func_offsets, globals)?;
            reject_aarch64_object_relocation_model_violations(
                self.config.relocation_model,
                &self.config.target_triple,
                &func_offsets
                    .iter()
                    .map(|(name, _)| name.clone())
                    .collect::<Vec<_>>(),
                &plan,
                globals,
                &combined_fixups,
            )?;
            let facts = Self::elf_function_facts(functions, &func_eh, &plan);
            let debug = if self.config.emit_debug && !functions.is_empty() {
                self.module_debug_info(
                    functions,
                    &func_offsets,
                    &func_eh,
                    frame_layouts,
                    "",
                    debug_variables,
                )?
                .try_emit_section_image()?
            } else {
                None
            };
            if let Some(obj) = emit_aarch64_elf_module_with_unwind(
                &self.config.target_triple,
                &combined_code,
                &func_offsets,
                globals,
                &combined_fixups,
                &func_eh,
                frame_layouts,
                aarch64_module_text_align_log2(functions),
                &plan,
                ElfTextOptions {
                    function_sections: self.function_sections,
                    functions: &facts,
                },
                debug.as_ref(),
            )? {
                return Ok(AArch64ModuleEmission::new(
                    ModuleEmission {
                        object: obj,
                        text_extents,
                    },
                    machine_code,
                ));
            }
        }
        reject_unsupported_aarch64_object_format(&self.config.target_triple)?;
        // Mach-O implements only the static relocation model.
        reject_aarch64_object_relocation_model_violations(
            self.config.relocation_model,
            &self.config.target_triple,
            &[],
            &ElfModuleSymbolPlan::legacy(),
            globals,
            &combined_fixups,
        )?;
        reject_macho_weak_symbol_linkage(
            &self.config.target_triple,
            functions,
            symbol_linkage,
            globals,
        )?;

        let object = self.emit_module_macho_with_unwind(
            &combined_code,
            combined_fixups,
            &func_offsets,
            &func_eh,
            frame_layouts,
            globals,
            functions,
            bindings,
            debug_variables,
        )?;
        Ok(AArch64ModuleEmission::new(
            ModuleEmission {
                object,
                text_extents,
            },
            machine_code,
        ))
    }

    /// Compile multiple pre-built IR functions into a single Mach-O .o file,
    /// using rayon to encode functions in parallel.
    ///
    /// Each function is encoded independently into its own buffer on a worker
    /// thread. Results are then merged sequentially (fast memcpy) into the
    /// combined __text section. This eliminates the sequential encoding
    /// bottleneck for modules with many functions.
    ///
    /// Falls back to [`compile_module`](Self::compile_module) for single-function
    /// modules where parallel overhead would dominate.
    pub fn compile_module_parallel(
        &self,
        functions: &[IrMachFunction],
    ) -> Result<Vec<u8>, PipelineError> {
        self.compile_module_parallel_with_globals(functions, &[])
    }

    pub fn compile_module_parallel_with_globals(
        &self,
        functions: &[IrMachFunction],
        globals: &[ObjectGlobal],
    ) -> Result<Vec<u8>, PipelineError> {
        self.compile_module_parallel_with_globals_and_layouts(functions, globals, &[])
    }

    /// Parallel variant of
    /// [`compile_module_with_globals_and_layouts`](Self::compile_module_with_globals_and_layouts)
    /// — see there for the whole-module unwind-table semantics of
    /// `frame_layouts`.
    pub fn compile_module_parallel_with_globals_and_layouts(
        &self,
        functions: &[IrMachFunction],
        globals: &[ObjectGlobal],
        frame_layouts: &[Option<crate::frame::FrameLayout>],
    ) -> Result<Vec<u8>, PipelineError> {
        self.compile_module_parallel_emission_with_target_evidence(
            functions,
            globals,
            frame_layouts,
        )
        .map(|emission| emission.into_emission().object)
    }

    /// Parallel whole-module emission retaining exact text layout and the
    /// validated union of required optional AArch64 features.
    ///
    /// Results preserve function input order. The bytes are identical to
    /// [`compile_module_parallel_with_globals_and_layouts`](Self::compile_module_parallel_with_globals_and_layouts),
    /// which delegates here and drops only layout/evidence metadata.
    pub fn compile_module_parallel_emission_with_target_evidence(
        &self,
        functions: &[IrMachFunction],
        globals: &[ObjectGlobal],
        frame_layouts: &[Option<crate::frame::FrameLayout>],
    ) -> Result<AArch64ModuleEmission, PipelineError> {
        self.compile_module_parallel_emission_with_symbol_linkage(
            functions,
            globals,
            frame_layouts,
            &ModuleSymbolLinkage::default(),
        )
    }

    /// Parallel variant of
    /// [`compile_module_emission_with_symbol_linkage`](Self::compile_module_emission_with_symbol_linkage):
    /// the same bytes, the same symbol-linkage validation and refusals.
    pub fn compile_module_parallel_emission_with_symbol_linkage(
        &self,
        functions: &[IrMachFunction],
        globals: &[ObjectGlobal],
        frame_layouts: &[Option<crate::frame::FrameLayout>],
        symbol_linkage: &ModuleSymbolLinkage,
    ) -> Result<AArch64ModuleEmission, PipelineError> {
        use crate::macho::fixup::FixupList;
        use rayon::prelude::*;

        let bindings = symbol_linkage.function_bindings();
        if !bindings.is_empty() && bindings.len() != functions.len() {
            return Err(PipelineError::ObjectEmission(format!(
                "module emission received {} symbol binding(s) for {} function(s); \
                 a binding vector must be empty or 1:1 with the functions",
                bindings.len(),
                functions.len()
            )));
        }

        let Some(worker_count) = crate::resource_limits::worker_count_for_items(functions.len())?
        else {
            // Not enough to justify parallel overhead. Delegate to the richer
            // sequential core so validation and feature derivation still occur
            // exactly once.
            return self.compile_module_emission_with_symbol_linkage(
                functions,
                globals,
                frame_layouts,
                symbol_linkage,
            );
        };

        reject_unsupported_aarch64_object_format(&self.config.target_triple)?;
        validate_aarch64_object_globals_with(
            globals,
            target_triple_uses_elf(&self.config.target_triple),
        )?;
        let machine_code = self.aarch64_module_machine_code_evidence(functions)?;

        // Symbol-address data relocations are emitted by the Mach-O writer via
        // `add_global_data_section` (`ARM64_RELOC_UNSIGNED`); both ELF paths use
        // `add_aarch64_elf_global_relocations` (`R_AARCH64_ABS64`).

        let pool = crate::resource_limits::build_rayon_pool(worker_count)
            .map_err(PipelineError::WorkerPool)?;

        // Phase 1: Encode each function in parallel, producing per-function buffers.
        // Each encoding is fully independent — no shared mutable state. EH
        // functions additionally resolve their post-layout LSDA here.
        type EncodedModuleFn = (String, Vec<u8>, FixupList, Option<FunctionLsda>);
        let encoding_environment =
            trust_cg_process_env::EnvOverrideSnapshot::capture_current_thread();
        let integrity_policy = self.aarch64_integrity_policy;
        let eh_propagation = &self.eh_propagation;
        let encoded: Vec<Result<EncodedModuleFn, PipelineError>> = pool.install(|| {
            functions
                .par_iter()
                .map(|func| {
                    encoding_environment.run(|| {
                        let (code, fixups, lsda) = encode_module_function_with_fixups_and_eh(
                            func,
                            integrity_policy,
                            eh_propagation,
                        )?;
                        Ok((func.name.clone(), code, fixups, lsda))
                    })
                })
                .collect()
        });

        // Phase 2: Merge per-function buffers sequentially (fast memcpy).
        // Pre-calculate total size for a single allocation.
        let mut total_size: usize = 0;
        let mut results: Vec<EncodedModuleFn> = Vec::with_capacity(encoded.len());
        for result in encoded {
            let entry = result?;
            total_size = checked_aarch64_size_sum(
                &entry.0,
                "combined code byte length",
                total_size,
                entry.1.len(),
            )?;
            results.push(entry);
        }

        let mut combined_code = Vec::with_capacity(total_size);
        let mut combined_fixups = FixupList::new();
        let mut func_offsets: Vec<(String, u64)> = Vec::with_capacity(results.len());
        let mut func_eh: Vec<ModuleFunctionEhData> = Vec::with_capacity(results.len());
        let mut text_extents: Vec<TextFunctionExtent> = Vec::with_capacity(results.len());

        for (func, (name, code, fixups, lsda)) in functions.iter().zip(results) {
            // `par_iter().collect()` preserves input order, so results[i]
            // is functions[i]'s encoding; the alignment request must come
            // from the SAME function whose code is being placed.
            debug_assert_eq!(func.name, name);
            pad_aarch64_text_for_function_alignment(
                &mut combined_code,
                &name,
                func.text_align_log2,
            )?;
            let func_start = checked_aarch64_object_u64(
                &name,
                "combined text function offset",
                combined_code.len(),
            )?;
            let code_len = checked_aarch64_object_u32(&name, "encoded code length", code.len())?;
            func_offsets.push((name.clone(), func_start));
            text_extents.push(TextFunctionExtent {
                name: name.clone(),
                offset: func_start,
                len: u64::from(code_len),
            });

            // Adjust fixup offsets to be relative to the combined section.
            for fixup in fixups.iter() {
                let mut adjusted = fixup.clone();
                adjusted.offset = checked_aarch64_fixup_offset(&name, func_start, fixup.offset)?;
                combined_fixups.push(adjusted);
            }

            func_eh.push(ModuleFunctionEhData { code_len, lsda });
            extend_aarch64_object_code(&mut combined_code, &name, &code)?;
        }

        // ELF: whole-module `.eh_frame` emission (see the sequential path).
        if target_triple_uses_elf(&self.config.target_triple) {
            let plan = ElfModuleSymbolPlan::new(symbol_linkage, &func_offsets, globals)?;
            reject_aarch64_object_relocation_model_violations(
                self.config.relocation_model,
                &self.config.target_triple,
                &func_offsets
                    .iter()
                    .map(|(name, _)| name.clone())
                    .collect::<Vec<_>>(),
                &plan,
                globals,
                &combined_fixups,
            )?;
            let facts = Self::elf_function_facts(functions, &func_eh, &plan);
            let debug = if self.config.emit_debug && !functions.is_empty() {
                self.module_debug_info(
                    functions,
                    &func_offsets,
                    &func_eh,
                    frame_layouts,
                    "",
                    ModuleDebugVariables::LinesOnly,
                )?
                .try_emit_section_image()?
            } else {
                None
            };
            if let Some(obj) = emit_aarch64_elf_module_with_unwind(
                &self.config.target_triple,
                &combined_code,
                &func_offsets,
                globals,
                &combined_fixups,
                &func_eh,
                frame_layouts,
                aarch64_module_text_align_log2(functions),
                &plan,
                ElfTextOptions {
                    function_sections: self.function_sections,
                    functions: &facts,
                },
                debug.as_ref(),
            )? {
                return Ok(AArch64ModuleEmission::new(
                    ModuleEmission {
                        object: obj,
                        text_extents,
                    },
                    machine_code,
                ));
            }
        }
        reject_unsupported_aarch64_object_format(&self.config.target_triple)?;
        // Mach-O implements only the static relocation model.
        reject_aarch64_object_relocation_model_violations(
            self.config.relocation_model,
            &self.config.target_triple,
            &[],
            &ElfModuleSymbolPlan::legacy(),
            globals,
            &combined_fixups,
        )?;
        reject_macho_weak_symbol_linkage(
            &self.config.target_triple,
            functions,
            symbol_linkage,
            globals,
        )?;

        let object = self.emit_module_macho_with_unwind(
            &combined_code,
            combined_fixups,
            &func_offsets,
            &func_eh,
            frame_layouts,
            globals,
            functions,
            symbol_linkage.function_bindings(),
            ModuleDebugVariables::LinesOnly,
        )?;
        Ok(AArch64ModuleEmission::new(
            ModuleEmission {
                object,
                text_extents,
            },
            machine_code,
        ))
    }

    /// Phase 2+3 of the generic multi-function module emitters: build the
    /// Mach-O object (combined `__text`, symbols, branch relocations) and —
    /// when the module carries exception-handling structure — the WHOLE-MODULE
    /// unwind tables.
    ///
    /// ## Whole-module unwind tables (EH A64 Lane 5, the x86 FUZZ-7 analogue)
    ///
    /// When ANY function in the module has an LSDA, EVERY function in it must
    /// be WALKABLE by the unwinder: a panic raised in (or below) one function
    /// of this module unwinds through its sibling frames (`main`, shims, plain
    /// no-drop helpers) on its way to the handler. A frame with no unwind entry
    /// stops phase-1 unwinding dead (`_URC_END_OF_STACK` — libstd aborts with
    /// "failed to initiate panic, error 5"), skipping every cleanup Drop — the
    /// FUZZ-7 [TCG-EH-WALK] miscompile class, previously closed on x86-64
    /// (502c09f) and now ported here for aarch64 Mach-O.
    ///
    /// The emission mirrors the PROVEN single-function aarch64 EH path
    /// (`emit_macho`), N-ary:
    ///
    /// * every function gets a 32-byte `__LD,__compact_unwind` entry whose
    ///   `function` field is relocated `ARM64_RELOC_UNSIGNED` against the
    ///   function's OWN symbol (exact atom association for ld64 — the aarch64
    ///   equivalent of x86's section-based reloc scheme);
    /// * a function whose frame the compact encoding cannot describe
    ///   (`UNWIND_ARM64_MODE_DWARF`) gets a DWARF FDE in `__TEXT,__eh_frame`
    ///   under the CIE of its own personality (one zPLR CIE group per
    ///   personality, or a single zR CIE when no EH function needs the
    ///   fallback), with the same subtractor+unsigned self-relative
    ///   pc-begin/LSDA relocation scheme the single-function path uses;
    /// * an EH function's REAL LSDA lands in `__TEXT,__gcc_except_tab`
    ///   (referenced from its compact entry via `with_lsda_symbol`, or from its
    ///   FDE augmentation when in DWARF mode), and each typed-catch TType slot
    ///   is relocated `ARM64_RELOC_POINTER_TO_GOT` against its typeinfo symbol;
    /// * when a CIE must be zPLR (an EH function needs the DWARF
    ///   fallback), every OTHER DWARF-fallback function gets a synthetic
    ///   ALL-FILLER LSDA (one `landing_pad == 0` call-site region covering
    ///   `[0, code_len)` — the personality's "no handler here, continue
    ///   unwinding" answer), because a zPLR CIE declares "L" and every FDE
    ///   under it must carry an LSDA field. The filler can only tell the
    ///   unwinder to KEEP WALKING — it can never dispatch to a wrong pad.
    ///
    /// A module with NO EH function still emits walk-through unwind metadata
    /// when complete layouts are supplied (the production `Compiler` path).
    /// Layout-less legacy callers remain byte-identical to the pre-port emitter.
    fn emit_module_macho_with_unwind(
        &self,
        combined_code: &[u8],
        mut combined_fixups: crate::macho::fixup::FixupList,
        func_offsets: &[(String, u64)],
        func_eh: &[ModuleFunctionEhData],
        frame_layouts: &[Option<crate::frame::FrameLayout>],
        globals: &[ObjectGlobal],
        // Post-codegen IR functions (1:1 and same order as `func_offsets` /
        // `func_eh`), threaded solely to emit DWARF debug sections when
        // `self.config.emit_debug` is set. Their per-instruction `source_loc`s
        // and `debug_meta` feed the `__DWARF` line program / subprograms.
        functions: &[IrMachFunction],
        // Per-function symbol binding, 1:1 with `func_offsets` when non-empty.
        // Empty means every definition is global, which is what every legacy
        // caller passes and what keeps their output byte-identical.
        bindings: &[FunctionSymbolBinding],
        // What the `-g` DWARF describes beyond subprograms and line rows.
        debug_variables: ModuleDebugVariables<'_>,
    ) -> Result<Vec<u8>, PipelineError> {
        use crate::macho::MachOWriter;
        use crate::macho::reloc::Relocation;
        use crate::unwind::{
            CompactUnwindEntry, CompactUnwindSection, add_compact_unwind_to_writer,
        };

        let mut writer = MachOWriter::new();
        writer.set_build_version(self.macho_build_version()?);
        writer.add_text_section_with_align(
            combined_code,
            u32::from(aarch64_module_text_align_log2(functions)),
        );

        let module_has_eh = func_eh.iter().any(|f| f.lsda.is_some());
        // Unwind tables are not only for EH modules: an exception (or Rust
        // panic) raised BELOW a plain trust-cg frame must be able to unwind
        // THROUGH it to an outer handler. A frame with no unwind entry stops
        // phase-1 unwinding dead (the unwinder cannot restore FP/LR/SP past
        // it) and the process terminates — the cross-module face of the
        // FUZZ-7 [TCG-EH-WALK] class. So: whenever the caller threads a
        // complete set of frame layouts (the real `Compiler` path always
        // does), emit walk-through unwind entries for every function even
        // when nothing in the module catches. EH modules keep the stricter
        // rule: missing layouts FAIL CLOSED inside the planner. Layout-less
        // legacy callers (direct `compile_module*` API users) keep the old
        // no-unwind-section output.
        let layouts_complete = !func_eh.is_empty()
            && (0..func_eh.len()).all(|i| frame_layouts.get(i).is_some_and(|l| l.is_some()));

        // Whole-module unwind planning + section/symbol CREATION happens BEFORE
        // `add_module_symbols_for_fixups` computes final nlist indices: the
        // LSDA / EH_Frame locals and the personality undefined shift the final
        // dysymtab order, so every symbol must exist before any index is read
        // (the same critical ordering the single-function `emit_macho`
        // documents).
        let eh_emission = if module_has_eh || layouts_complete {
            Some(self.plan_module_unwind_sections(
                &mut writer,
                func_offsets,
                func_eh,
                frame_layouts,
            )?)
        } else {
            None
        };

        // Add defined function symbols and undefined external symbols needed by
        // branch fixups. Track final nlist indices for fixup resolution.
        let no_typeinfo_symbols = BTreeSet::new();
        let symbol_map = add_module_symbols_for_fixups(
            &mut writer,
            func_offsets,
            globals,
            &combined_fixups,
            bindings,
            eh_emission
                .as_ref()
                .map_or(&no_typeinfo_symbols, |plan| &plan.typeinfo_symbols),
        )?;

        // Resolve named symbol fixups to numeric indices, then convert fixups
        // to relocations.
        combined_fixups.resolve_named_symbols_with_exact(
            |name| {
                symbol_map
                    .ordinary_by_abi_name
                    .get(&macho_symbol_name(name))
                    .copied()
            },
            |name| symbol_map.exact_function_by_raw_name.get(name).copied(),
        )?;

        let relocations = combined_fixups.resolve_to_relocations()?;
        for reloc in relocations {
            writer.add_relocation(0, reloc)?; // section 0 = __text
        }

        // Emit the unwind entries + relocations now that the symbol table is
        // final (all indices below are final nlist indices).
        if let Some(plan) = eh_emission {
            // Final nlist index of each personality routine an EH function
            // names. A walk-through-only module plans none, so nothing below
            // may reference a personality (fail-closed at each use site).
            let mut personality_indices: BTreeMap<&str, u32> = BTreeMap::new();
            for (name, symbol) in &plan.personality_symbols {
                personality_indices.insert(
                    name.as_str(),
                    final_macho_symbol_index(
                        &mut writer,
                        *symbol,
                        "module personality unwind emission",
                    )?,
                );
            }
            let require_personality = |name: Option<&str>| -> Result<u32, PipelineError> {
                name.and_then(|name| personality_indices.get(name).copied())
                    .ok_or_else(|| {
                        PipelineError::Unwind(format!(
                            "module unwind emission: an EH entry needs personality routine \
                             {name:?} but the module planned no symbol for it (fail-closed)"
                        ))
                    })
            };
            let function_index = |i: usize| -> Result<u32, PipelineError> {
                let name = &func_offsets[i].0;
                symbol_map
                    .exact_function_by_raw_name
                    .get(name)
                    .copied()
                    .ok_or_else(|| {
                        PipelineError::Unwind(format!(
                            "module unwind emission: no symbol for function `{name}`"
                        ))
                    })
            };

            // Typed-catch TType slots: `ARM64_RELOC_POINTER_TO_GOT`, pc-relative,
            // 4 bytes, against the typeinfo symbol -- the exact form clang
            // emits for a `DW_EH_PE_indirect|pcrel|sdata4` entry, so ld64 and
            // the standalone linker both bind it through the GOT. The symbol
            // pass above registered every name, so a miss is a planner bug,
            // not a silent NULL (catch-all) slot.
            for (i, f) in func_eh.iter().enumerate() {
                let Some(lsda) = &f.lsda else { continue };
                if lsda.image.typeinfo_relocations.is_empty() {
                    continue;
                }
                let (lsda_section, lsda_base) =
                    plan.lsda_section.zip(plan.lsda_offsets[i]).ok_or_else(|| {
                        PipelineError::Unwind(format!(
                            "module unwind emission: typed-catch LSDA of `{}` was not laid out \
                             in __gcc_except_tab (fail-closed)",
                            func_offsets[i].0
                        ))
                    })?;
                for reloc in &lsda.image.typeinfo_relocations {
                    let symbol_index = symbol_map
                        .ordinary_by_abi_name
                        .get(&macho_symbol_name(&reloc.symbol))
                        .copied()
                        .ok_or_else(|| {
                            PipelineError::Unwind(format!(
                                "module unwind emission: typeinfo symbol `{}` of `{}` has no \
                                 Mach-O symbol (fail-closed)",
                                reloc.symbol, func_offsets[i].0
                            ))
                        })?;
                    let offset = lsda_base.checked_add(reloc.offset).ok_or_else(|| {
                        PipelineError::Unwind(format!(
                            "module unwind emission: typeinfo slot offset of `{}` overflows \
                             __gcc_except_tab",
                            func_offsets[i].0
                        ))
                    })?;
                    writer.add_relocation(
                        lsda_section,
                        Relocation::pointer_to_got_pcrel(offset, symbol_index),
                    )?;
                }
            }

            // One compact unwind entry per function (ld64's primary unwind
            // input), each bound to ITS function's personality. DWARF-mode
            // entries carry no personality/LSDA fields -- ld64 reads both from
            // the FDE.
            let mut cu_section = CompactUnwindSection::new();
            for (i, f) in func_eh.iter().enumerate() {
                let mut entry = CompactUnwindEntry::new(
                    0, // function_offset baked 0; relocated against the fn's own symbol
                    f.code_len,
                    plan.encodings[i].encoding,
                    function_index(i)?,
                );
                if !plan.encodings[i].needs_dwarf_fallback() && f.lsda.is_some() {
                    entry = entry.with_personality_symbol(require_personality(
                        plan.personalities[i].as_deref(),
                    )?);
                    let lsda_symbol = plan.lsda_symbols[i].ok_or_else(|| {
                        PipelineError::Unwind(format!(
                            "module unwind emission: EH function `{}` has no LSDA symbol",
                            func_offsets[i].0
                        ))
                    })?;
                    entry = entry.with_lsda_symbol(final_macho_symbol_index(
                        &mut writer,
                        lsda_symbol,
                        "module LSDA unwind emission",
                    )?);
                }
                cu_section.add_entry(entry);
            }
            add_compact_unwind_to_writer(&mut writer, &cu_section)?;

            if let Some(dwarf) = plan.dwarf {
                let eh_frame_index = final_macho_symbol_index(
                    &mut writer,
                    dwarf.eh_frame_symbol,
                    "module EH frame relocation emission",
                )?;
                for group in &dwarf.groups {
                    let in_section =
                        |offset: u32, what: &'static str| -> Result<u32, PipelineError> {
                            let offset =
                                checked_aarch64_macho_relocation_offset("<module>", what, offset)?;
                            group.base.checked_add(offset).ok_or_else(|| {
                                PipelineError::Unwind(format!(
                                    "module unwind emission: {what} overflows __eh_frame"
                                ))
                            })
                        };
                    if let Some(offset) = group.cfi.cie_personality_relocation_offset() {
                        let offset = in_section(offset, "CIE personality relocation offset")?;
                        writer.add_relocation(
                            dwarf.eh_frame_section,
                            Relocation::pointer_to_got_pcrel(
                                offset,
                                require_personality(group.personality.as_deref())?,
                            ),
                        )?;
                    }
                    for (k, pc_begin_offset) in group
                        .cfi
                        .fde_pc_begin_relocation_offsets()
                        .into_iter()
                        .enumerate()
                    {
                        let i = group.fde_functions[k];
                        let pc_begin_offset =
                            in_section(pc_begin_offset, "FDE PC-begin relocation offset")?;
                        writer.add_relocation(
                            dwarf.eh_frame_section,
                            Relocation::subtractor(pc_begin_offset, eh_frame_index, 3),
                        )?;
                        writer.add_relocation(
                            dwarf.eh_frame_section,
                            Relocation::unsigned_ptr(pc_begin_offset, function_index(i)?),
                        )?;
                    }
                    // LSDA slots exist for every FDE exactly when the CIE is
                    // zPLR, so the k-th offset belongs to the k-th FDE's
                    // function.
                    for (k, lsda_offset) in group
                        .cfi
                        .fde_lsda_relocation_offsets()
                        .into_iter()
                        .enumerate()
                    {
                        let i = group.fde_functions[k];
                        let lsda_offset = in_section(lsda_offset, "FDE LSDA relocation offset")?;
                        let lsda_symbol = plan.lsda_symbols[i].ok_or_else(|| {
                            PipelineError::Unwind(format!(
                                "module unwind emission: FDE for `{}` has an LSDA slot but \
                                 no LSDA symbol",
                                func_offsets[i].0
                            ))
                        })?;
                        let lsda_index = final_macho_symbol_index(
                            &mut writer,
                            lsda_symbol,
                            "module FDE LSDA relocation emission",
                        )?;
                        writer.add_relocation(
                            dwarf.eh_frame_section,
                            Relocation::subtractor(lsda_offset, eh_frame_index, 3),
                        )?;
                        writer.add_relocation(
                            dwarf.eh_frame_section,
                            Relocation::unsigned_ptr(lsda_offset, lsda_index),
                        )?;
                    }
                }
            }
        }

        // Emit DWARF debug sections when debug info is requested. Unlike the
        // single-function `emit_macho`, the unwind path fuses every function
        // into one `__text` section, so the compilation unit carries one
        // `DW_TAG_subprogram` per function whose `low_pc` is the function's byte
        // offset within `__text` and whose `.debug_line` rows are shifted by the
        // same offset (o-local addresses). The DWARF address fields carry
        // `ARM64_RELOC_UNSIGNED` relocations against `__text`; ld combines
        // those with the STABS debug map (N_OSO/N_FUN) synthesized from the
        // object's function symbols so the o-local PCs become final linked
        // addresses. This is what lets a forced backtrace resolve
        // `file:line:col` for panic=unwind (EH) modules, which always route
        // here.
        if self.config.emit_debug && !functions.is_empty() {
            let debug_info = self.module_debug_info(
                functions,
                func_offsets,
                func_eh,
                frame_layouts,
                "_",
                debug_variables,
            )?;
            crate::dwarf_info::add_debug_info_to_writer(&mut writer, &debug_info)?;
        }

        let object = writer.write()?;
        if module_has_eh {
            if functions.len() != func_offsets.len() || functions.len() != func_eh.len() {
                return Err(PipelineError::Unwind(format!(
                    "EH obligations need one machine function per emitted function ({} functions, {} offsets, {} unwind records)",
                    functions.len(),
                    func_offsets.len(),
                    func_eh.len()
                )));
            }
            let mut placed = Vec::with_capacity(functions.len());
            for (index, function) in functions.iter().enumerate() {
                let layout = frame_layouts
                    .get(index)
                    .and_then(Option::as_ref)
                    .ok_or_else(|| {
                        PipelineError::Unwind(format!(
                            "EH obligations need the frame layout of `{}`",
                            function.name
                        ))
                    })?;
                placed.push((
                    function,
                    func_offsets[index].1,
                    func_eh[index].code_len,
                    layout,
                ));
            }
            self.check_macho_eh_obligations(&object, &placed)?;
        }
        Ok(object)
    }

    /// The exception-table obligations (ledger L03-P14) over an emitted
    /// Mach-O object that carries exception tables: every function's LSDA,
    /// personality and unwind description, decided by
    /// `trust_cg_verify::eh_obligations` over the object's bytes against the
    /// machine functions and frame layouts (testing grade, decided in
    /// process). A violation fails the emission closed by name
    /// (`[TCG-EH-OBLIGATION]`). `TCG_TRACE_EH_OBLIGATIONS=1` prints the
    /// per-object report.
    ///
    /// `functions` are `(machine function, __text offset, emitted length,
    /// frame layout)` in emission order.
    fn check_macho_eh_obligations(
        &self,
        object: &[u8],
        functions: &[(&IrMachFunction, u64, u32, &crate::frame::FrameLayout)],
    ) -> Result<(), PipelineError> {
        let mut intent = trust_cg_verify::eh_obligations::EhObjectIntent::default();
        for &(function, text_offset, code_len, layout) in functions {
            let function_intent = eh_obligation_intent::function_intent(
                function,
                text_offset,
                code_len,
                layout,
                &self.eh_propagation,
                &macho_symbol_name,
            )
            .map_err(|detail| PipelineError::MalformedAarch64Eh {
                function: function.name.clone(),
                detail: format!("exception-table obligation intent: {detail}"),
            })?;
            intent.functions.push(function_intent);
        }
        let report = trust_cg_verify::eh_obligations::check_macho_object(object, &intent)
            .map_err(eh_obligation_intent::obligation_error)?;
        eh_obligation_intent::record_capture("macho", object, &intent, &report, None);
        if trust_cg_verify::diag::eh_obligation_trace_enabled() {
            eprintln!("TCG_EH_OBLIGATIONS macho {}", report.summary());
        }
        Ok(())
    }

    /// Build the `__gcc_except_tab` / `__eh_frame` sections and their symbols
    /// for an EH-carrying module, and compute each function's compact unwind
    /// encoding. Fails closed when a function is missing its frame layout
    /// (every frame needs an unwind entry — see
    /// [`emit_module_macho_with_unwind`](Self::emit_module_macho_with_unwind)).
    fn plan_module_unwind_sections(
        &self,
        writer: &mut crate::macho::MachOWriter,
        func_offsets: &[(String, u64)],
        func_eh: &[ModuleFunctionEhData],
        frame_layouts: &[Option<crate::frame::FrameLayout>],
    ) -> Result<ModuleUnwindPlan, PipelineError> {
        use crate::dwarf_cfi::{DwarfCfiSection, DwarfFde};
        use crate::exception_handling::generate_lsda_from_pads;
        use crate::macho::constants::S_REGULAR;

        // Every frame must be describable: a function without a layout would
        // get NO unwind entry, i.e. an unwalkable frame (the exact hole this
        // emission closes). Fail closed, never a silent drop.
        for (i, (name, _)) in func_offsets.iter().enumerate() {
            if frame_layouts.get(i).is_none_or(|layout| layout.is_none()) {
                return Err(PipelineError::Unwind(format!(
                    "module carries exception-handling structure, so EVERY function \
                     needs an unwind-table entry (a frame without one stops unwinding \
                     at phase 1 — skipped cleanup Drops at run time), but no frame \
                     layout was provided for `{name}`. Thread per-function frame \
                     layouts via compile_module_with_globals_and_layouts (fail-closed)."
                )));
            }
        }
        let layout = |i: usize| -> &crate::frame::FrameLayout {
            frame_layouts[i].as_ref().expect("checked above")
        };

        // Personalities: every EH function binds its own compact-unwind entry
        // to its personality routine, and each personality that needs the
        // DWARF fallback gets its own zPLR CIE. A module may therefore mix
        // `__gxx_personality_v0` and `rust_eh_personality`.
        let personalities: Vec<Option<String>> = func_eh
            .iter()
            .map(|f| {
                f.lsda
                    .as_ref()
                    .map(|lsda| lsda.canonical_personality().to_string())
            })
            .collect();
        let distinct_personalities: BTreeSet<String> =
            personalities.iter().flatten().cloned().collect();
        // Filler LSDAs are personality-agnostic ("no handler here, keep
        // unwinding"); they ride under the first personality's CIE.
        let filler_personality: Option<&str> =
            distinct_personalities.iter().next().map(String::as_str);

        let encodings: Vec<crate::frame::CompactUnwindEncoding> = (0..func_eh.len())
            .map(|i| crate::frame::encode_compact_unwind(layout(i)))
            .collect();
        // zPLR CIE required iff an EH function itself needs the DWARF fallback
        // (its LSDA then rides on its FDE, and the CIE must declare P+L).
        let dwarf_has_eh = func_eh
            .iter()
            .zip(&encodings)
            .any(|(f, enc)| f.lsda.is_some() && enc.needs_dwarf_fallback());

        // `__TEXT,__gcc_except_tab`: real LSDAs for EH functions; synthetic
        // ALL-FILLER LSDAs for non-EH functions that get an FDE under a zPLR
        // CIE (every FDE under "L" must carry an LSDA; the filler's single
        // `landing_pad == 0` region over `[0, code_len)` reads as "continue
        // unwinding" — it can never dispatch to a wrong pad). Typed-catch
        // TType slots are recorded here and relocated once the symbol table
        // is final (`emit_module_macho_with_unwind`).
        let mut lsda_data: Vec<u8> = Vec::new();
        let mut lsda_offsets: Vec<Option<u32>> = vec![None; func_eh.len()];
        let mut typeinfo_symbols = BTreeSet::new();
        for (i, f) in func_eh.iter().enumerate() {
            let bytes: Option<Vec<u8>> = match &f.lsda {
                Some(lsda) => {
                    for reloc in &lsda.image.typeinfo_relocations {
                        typeinfo_symbols.insert(reloc.symbol.clone());
                    }
                    Some(lsda.image.bytes.clone())
                }
                None if dwarf_has_eh && encodings[i].needs_dwarf_fallback() => {
                    // `dwarf_has_eh` implies some function has an LSDA, and
                    // every LSDA carries a personality, so a filler
                    // personality exists here — keep the guard fail-closed.
                    let personality = filler_personality.ok_or_else(|| {
                        PipelineError::Unwind(format!(
                            "synthetic filler LSDA for module function {} needs a \
                             personality routine but the module has none (fail-closed)",
                            func_offsets[i].0
                        ))
                    })?;
                    let bytes = generate_lsda_from_pads(personality, &[], &[(0, f.code_len, 0)])
                        .map_err(|error| {
                            PipelineError::Unwind(format!(
                                "synthetic filler LSDA for module function {} is invalid: {error}",
                                func_offsets[i].0
                            ))
                        })?;
                    Some(bytes)
                }
                None => None,
            };
            if let Some(bytes) = bytes {
                // 4-byte align each LSDA within the section (matching the
                // section's 2^2 alignment; LSDA offsets are symbol-addressed).
                let max_growth = checked_aarch64_size_sum(
                    &func_offsets[i].0,
                    "LSDA section growth",
                    bytes.len(),
                    3,
                )?;
                checked_aarch64_size_sum(
                    &func_offsets[i].0,
                    "LSDA section byte length",
                    lsda_data.len(),
                    max_growth,
                )?;
                lsda_data.try_reserve(max_growth).map_err(|error| {
                    PipelineError::Unwind(format!(
                        "LSDA section allocation for `{}` failed: {error}",
                        func_offsets[i].0
                    ))
                })?;
                while !lsda_data.len().is_multiple_of(4) {
                    lsda_data.push(0);
                }
                lsda_offsets[i] = Some(checked_aarch64_object_u32(
                    &func_offsets[i].0,
                    "LSDA section offset",
                    lsda_data.len(),
                )?);
                lsda_data.extend_from_slice(&bytes);
            }
        }
        let mut lsda_symbols: Vec<Option<usize>> = vec![None; func_eh.len()];
        let mut lsda_section = None;
        if !lsda_data.is_empty() {
            let section = writer.add_custom_section(
                b"__gcc_except_tab",
                b"__TEXT",
                &lsda_data,
                2, // 2^2 = 4-byte alignment (matching LLVM)
                S_REGULAR,
            );
            lsda_section = Some(section);
            for (i, offset) in lsda_offsets.iter().enumerate() {
                if let Some(offset) = offset {
                    let name = format!("_GCC_except_table_{}", func_offsets[i].0);
                    lsda_symbols[i] =
                        Some(writer.add_symbol(&name, section + 1, u64::from(*offset), false)?);
                }
            }
        }

        // `__TEXT,__eh_frame`: one FDE per DWARF-fallback function, grouped
        // under the CIE of its personality (one zPLR CIE per personality
        // that needs the fallback; the filler frames join the first group),
        // or under a single zR CIE when no EH function needs the fallback.
        // Each group is serialized on its own, decode-checked, stripped of
        // its terminator and concatenated; the self-relative addends are
        // baked against the group's position in the section.
        let mut dwarf = None;
        if encodings.iter().any(|enc| enc.needs_dwarf_fallback()) {
            let mut group_keys: Vec<Option<String>> = Vec::new();
            let mut group_members: Vec<Vec<usize>> = Vec::new();
            for (i, f) in func_eh.iter().enumerate() {
                if !encodings[i].needs_dwarf_fallback() {
                    continue;
                }
                let key: Option<String> = if !dwarf_has_eh {
                    None
                } else if f.lsda.is_some() {
                    personalities[i].clone()
                } else {
                    filler_personality.map(str::to_string)
                };
                let slot = match group_keys.iter().position(|existing| *existing == key) {
                    Some(slot) => slot,
                    None => {
                        group_keys.push(key);
                        group_members.push(Vec::new());
                        group_keys.len() - 1
                    }
                };
                group_members[slot].push(i);
            }
            let mut eh_frame: Vec<u8> = Vec::new();
            let mut groups = Vec::with_capacity(group_keys.len());
            for (key, members) in group_keys.into_iter().zip(group_members) {
                let mut cfi = if key.is_some() {
                    DwarfCfiSection::new_aarch64_with_eh()
                } else {
                    DwarfCfiSection::new()
                };
                for &i in &members {
                    let mut fde = DwarfFde::from_layout(layout(i), 0, func_eh[i].code_len, 0);
                    if key.is_some() {
                        fde = fde.with_lsda();
                    }
                    cfi.add_fde(fde);
                }
                let mut bytes = cfi.to_bytes();
                // ENC-EHDC: the independent decoder must read the full
                // serialization (terminator included, pointer fields still at
                // their intent value) back to the CIE/FDE intent first.
                crate::dwarf_cfi_decode_check::verify_eh_frame_roundtrip(&cfi, &bytes)?;
                // ld64's arm64 `__eh_frame` reader parses entries up to the
                // SECTION BOUNDS and rejects the ELF-style zero-length
                // terminator entry with "empty CIE" (Apple's own toolchain
                // emits no terminator on Mach-O). Strip the 4 trailing zero
                // bytes before emission; every relocation-patch offset below
                // lies before it.
                strip_verified_eh_frame_terminator(&mut bytes)?;
                if bytes.is_empty() {
                    continue;
                }
                let base = checked_aarch64_object_u32(
                    "<module>",
                    "__eh_frame group base",
                    eh_frame.len(),
                )?;
                for pc_begin_offset in cfi.fde_pc_begin_relocation_offsets() {
                    let addend = -(i64::from(base) + i64::from(pc_begin_offset));
                    let offset = pc_begin_offset as usize;
                    bytes[offset..offset + 8].copy_from_slice(&addend.to_le_bytes());
                }
                for lsda_offset in cfi.fde_lsda_relocation_offsets() {
                    let addend = -(i64::from(base) + i64::from(lsda_offset));
                    let offset = lsda_offset as usize;
                    bytes[offset..offset + 8].copy_from_slice(&addend.to_le_bytes());
                }
                eh_frame.extend_from_slice(&bytes);
                groups.push(ModuleUnwindDwarfGroup {
                    cfi,
                    base,
                    personality: key,
                    fde_functions: members,
                });
            }
            if !eh_frame.is_empty() {
                const EH_FRAME_FLAGS: u32 = 0x6800_000B;
                let eh_frame_section = writer.add_custom_section(
                    b"__eh_frame",
                    b"__TEXT",
                    &eh_frame,
                    3, // 2^3 = 8-byte alignment
                    EH_FRAME_FLAGS,
                );
                let eh_frame_symbol =
                    writer.add_symbol("EH_Frame", eh_frame_section + 1, 0, false)?;
                dwarf = Some(ModuleUnwindDwarf {
                    eh_frame_section,
                    eh_frame_symbol,
                    groups,
                });
            }
        }

        let mut personality_symbols = BTreeMap::new();
        for personality in &distinct_personalities {
            let symbol = writer.add_symbol(&format!("_{personality}"), 0, 0, true)?;
            personality_symbols.insert(personality.clone(), symbol);
        }

        Ok(ModuleUnwindPlan {
            personality_symbols,
            personalities,
            lsda_symbols,
            lsda_section,
            lsda_offsets,
            typeinfo_symbols,
            encodings,
            dwarf,
        })
    }

    // --- Phase implementations ---

    /// Phase 1: Run instruction selection on the input function.
    ///
    /// When `proof_ctx` is provided, returns the ISel value map alongside
    /// the function so the caller can propagate proof annotations to the IR.
    fn run_isel(
        &self,
        input: &trust_cg_lower::Function,
        proof_ctx: Option<&trust_cg_lower::ProofContext>,
    ) -> Result<
        (
            trust_cg_lower::isel::ISelFunction,
            Option<
                std::collections::HashMap<
                    trust_cg_lower::instructions::Value,
                    trust_cg_lower::isel::ISelOperand,
                >,
            >,
        ),
        PipelineError,
    > {
        self.run_isel_with_call_admission(
            input,
            proof_ctx,
            Aarch64DirectCallAdmission::Compatibility,
        )
    }

    fn run_isel_with_call_admission(
        &self,
        input: &trust_cg_lower::Function,
        proof_ctx: Option<&trust_cg_lower::ProofContext>,
        direct_call_admission: Aarch64DirectCallAdmission,
    ) -> Result<
        (
            trust_cg_lower::isel::ISelFunction,
            Option<
                std::collections::HashMap<
                    trust_cg_lower::instructions::Value,
                    trust_cg_lower::isel::ISelOperand,
                >,
            >,
        ),
        PipelineError,
    > {
        use trust_cg_lower::isel::InstructionSelector;

        input.validate_eh_structure().map_err(|reason| {
            PipelineError::Unwind(format!(
                "invalid exception-handling structure in `{}`: {reason}",
                input.name
            ))
        })?;

        let sig = trust_cg_lower::function::Signature {
            params: input.signature.params.clone(),
            returns: input.signature.returns.clone(),
        };

        let mut isel = InstructionSelector::new(input.name.clone(), sig.clone());
        if direct_call_admission == Aarch64DirectCallAdmission::SealedCore {
            isel.enable_sealed_core_native_calls();
        }
        // The function's own target features extend the profile for this
        // function alone; every other function selects under the profile.
        let function_features = self.resolve_aarch64_function_target_features(input)?;
        let admitted_features = self
            .aarch64_target_machine
            .for_function(function_features)
            .map_err(|error| aarch64_target_machine_contract_error(&input.name, error))?
            .admitted_features();
        isel.set_lse_enabled(admitted_features.admits(AArch64IsaFeature::Lse));
        isel.set_lse2_enabled(admitted_features.admits(AArch64IsaFeature::Lse2));
        isel.set_fp16_enabled(admitted_features.admits(AArch64IsaFeature::Fp16));
        isel.set_crc_enabled(admitted_features.admits(AArch64IsaFeature::Crc));
        isel.set_function_target_features(function_features);
        // Pick the calling convention from the TARGET, not from the host.
        // AArch64 has two incompatible conventions for stack arguments and
        // trust-cg targets both; classifying a Linux/ELF target with DarwinPCS
        // puts narrow stack arguments at packed offsets while every
        // LLVM-compiled caller (std, libc, any mixed build) writes them into
        // 8-byte slots. An empty or unrecognized triple is refused here rather
        // than defaulted. Must be set before formal arguments or calls are
        // lowered.
        isel.set_abi_variant(self.resolved_aarch64_abi()?);
        if let Some(ctx) = proof_ctx {
            isel.seed_lattice_bounds_capabilities(&ctx.lattice_bounds_capabilities);
            isel.seed_aggregate_call_intents(&ctx.aggregate_call_intents);
        }

        // Propagate stack slot metadata from the LIR function to the ISel.
        isel.set_stack_slots(input.stack_slots.clone());

        // Seed Value->Type hints from the adapter (Call/CallIndirect result
        // types, see #381). Must happen BEFORE select_block_* so that
        // `value_type()` lookups during selection return the true callee
        // return type instead of the I64 default.
        isel.seed_value_types(&input.value_types);

        // Seed pure-callee names so `select_call` can stamp the emitted Bl
        // with `ProofAnnotation::Pure` for SROA partial-escape (#456).
        // A public `Pure` label cannot authorize SROA's partial-escape transform.  Preserve the
        // names in LIR/report metadata, but do not stamp behavior-changing call proof annotations.
        if trust_cg_lower::guard_evidence::validator_guard_replay_authority_available() {
            isel.seed_pure_callees(&input.pure_callees);
        }

        // Seed importer-licensed libm-pure callee names (intrinsic-origin math
        // libcalls). NOT gated on the validator-guard replay authority above:
        // the license authority here is the importer's own verified proof (the
        // llvm.* intrinsic's `speculatable willreturn nounwind memory(none)`
        // attribute set plus module-wide plain-use exclusion), and the stamped
        // `InstFlags::LIBM_PURE_CALL` is metadata consumed only by the gated
        // `loop-dead-pure-sink` pass — it never authorizes SROA/DCE/reordering.
        isel.seed_libm_pure_callees(&input.libm_pure_callees);
        // The indirect-return (`sret`) convention: which parameter of THIS
        // function is the hidden return buffer (placed in X8, not X0), and which
        // direct callees take one. Both are ABI facts the frontend stated.
        isel.seed_sret_param(input.abi_sret_param)
            .map_err(|e| PipelineError::ISel(e.to_string()))?;
        isel.seed_sret_arg_callees(&input.sret_arg_callees);
        isel.seed_sret_arg_indirect_callees(&input.sret_arg_indirect_callees);

        // Whole-function pre-scan for Iconst origins. Enables cross-block
        // rematerialization in `use_value` so an SSA constant defined in one
        // block can be reused in any non-dominated successor.
        isel.seed_iconst_origins(input.blocks.values().map(|bb| bb.instructions.as_slice()));

        // Whole-function value use counts: the idiom-fusion analyses
        // (overflow/smulh/bitreverse/mul-add) skip pattern-intermediate defs
        // and MUST see cross-block uses (branch-arg edge copies) to keep that
        // sound — the miniz_oxide `inflate::core::transfer` madd-fusion class
        // ("value ... not defined before use"). See
        // `InstructionSelector::value_use_counts`.
        isel.seed_function_value_use_counts(input);

        // Lower formal arguments at entry: copies ABI physical registers into
        // VRegs and populates the value_map for function parameters. They must
        // run once per call, so an entry block that a back edge re-enters gets
        // them in a dedicated block ahead of it.
        if input.entry_block_is_branch_target() {
            isel.lower_formal_arguments_before_reentered_entry(&sig, input.entry_block)
                .map(drop)
        } else {
            isel.lower_formal_arguments(&sig, input.entry_block)
        }
        .map_err(|e| PipelineError::ISel(e.to_string()))?;

        let block_order = input.layout_order();

        // Process blocks in layout order. For non-entry blocks, define block
        // parameter Values before processing instructions.

        let _t_loop_start = std::time::Instant::now();
        for block_ref in &block_order {
            let _t_block = std::time::Instant::now();
            let basic_block = &input.blocks[block_ref];
            if *block_ref != input.entry_block && !basic_block.params.is_empty() {
                isel.define_block_params(&basic_block.params);
            }
            let trust_ir_origins = input
                .trust_ir_origins
                .get(block_ref)
                .map(Vec::as_slice)
                .unwrap_or(&[]);
            isel.select_block_with_provenance(
                *block_ref,
                &basic_block.instructions,
                &basic_block.source_locs,
                trust_ir_origins,
            )
            .map_err(|e| PipelineError::ISel(e.to_string()))?;
            let _d = _t_block.elapsed().as_millis();
            if _d > 5 && std::env::var_os("TY_TRUST_CG_JIT_PROFILE").is_some() {
                eprintln!("[JIT Profile] block {} took {}ms", block_ref.0, _d);
            }
        }
        if std::env::var_os("TY_TRUST_CG_JIT_PROFILE").is_some() {
            eprintln!(
                "[JIT Profile] run_isel loop total: {:?}",
                _t_loop_start.elapsed()
            );
        }

        // The EH type table is frontend-owned binding data beside the
        // structural sidecar: forward it with the personality so typed
        // catches reach the LSDA emitter bound to their typeinfo symbols.
        if proof_ctx.is_some() || !input.debug_value_bindings.is_empty() {
            let (mut func, value_map) = isel
                .finalize_with_value_map_and_eh_info(&input.eh_info)
                .map_err(|e| PipelineError::Unwind(e.to_string()))?;
            func.eh_type_table = input.eh_type_table.clone();
            Ok((func, Some(value_map)))
        } else {
            let mut func = isel
                .finalize_with_eh_info(&input.eh_info)
                .map_err(|e| PipelineError::Unwind(e.to_string()))?;
            func.eh_type_table = input.eh_type_table.clone();
            Ok((func, None))
        }
    }

    /// Phase 3: Run optimization passes and instruction scheduling.
    ///
    /// After the main optimization pipeline, runs pre-register-allocation
    /// instruction scheduling. The scheduler variant depends on the
    /// optimization level:
    ///
    /// - **O0**: No scheduling (fastest compile).
    /// - **O1**: [`trust_cg_opt::scheduler::InstructionScheduler`] (fast, ILP-focused).
    /// - **O2/O3**: [`trust_cg_opt::scheduler::PressureAwareScheduler`]
    ///   (balances ILP with register pressure to reduce spills).
    fn run_optimization_checked(
        &self,
        func: &mut IrMachFunction,
    ) -> Result<trust_cg_opt::PassStats, PipelineError> {
        let function = func.name.clone();
        catch_optimization_invariant(function, || self.run_optimization(func))
            .and_then(|result| result)
    }

    fn run_optimization_with_proof_metadata_checked(
        &self,
        func: &mut IrMachFunction,
        proof_metadata: Option<trust_cg_opt::proof_opts::ProofOptimizationMetadata>,
        provenance: Option<&mut trust_cg_ir::ProvenanceMap>,
    ) -> Result<trust_cg_opt::PassStats, PipelineError> {
        let function = func.name.clone();
        catch_optimization_invariant(function, || {
            self.run_optimization_with_proof_metadata(func, proof_metadata, provenance)
        })
        .and_then(|result| result)
    }

    fn run_optimization_with_proof_metadata_and_gate_checked(
        &self,
        func: &mut IrMachFunction,
        proof_metadata: Option<trust_cg_opt::proof_opts::ProofOptimizationMetadata>,
        provenance: Option<&mut trust_cg_ir::ProvenanceMap>,
        kernel_gate: Option<AArch64KernelGate>,
        validation: OptimizationValidation,
    ) -> Result<trust_cg_opt::PassStats, PipelineError> {
        let function = func.name.clone();
        catch_optimization_invariant(function, || {
            self.run_optimization_with_proof_metadata_and_gate(
                func,
                proof_metadata,
                provenance,
                kernel_gate,
                validation,
            )
        })
        .and_then(|result| result)
    }

    fn run_optimization(
        &self,
        func: &mut IrMachFunction,
    ) -> Result<trust_cg_opt::PassStats, PipelineError> {
        self.run_optimization_with_proof_metadata(func, None, None)
    }

    fn run_optimization_with_proof_metadata(
        &self,
        func: &mut IrMachFunction,
        proof_metadata: Option<trust_cg_opt::proof_opts::ProofOptimizationMetadata>,
        provenance: Option<&mut trust_cg_ir::ProvenanceMap>,
    ) -> Result<trust_cg_opt::PassStats, PipelineError> {
        if cfg!(test) {
            // Retain the structural proof-pass model for in-crate unit tests.  Downstream and
            // integration builds compile the production branch below.
            return self.run_optimization_with_proof_metadata_and_gate(
                func,
                proof_metadata,
                provenance,
                None,
                self.optimization_validation(),
            );
        }

        // Default/private callers do not carry an exact validator replay capability.  Do not let a
        // caller-supplied sidecar reach proof optimization, and install the empty gate explicitly:
        // `None` would select the legacy label-only guard path.
        self.run_optimization_with_proof_metadata_and_gate(
            func,
            None,
            provenance,
            Some(AArch64KernelGate::Empty),
            self.optimization_validation(),
        )
    }

    fn run_optimization_with_proof_metadata_and_gate(
        &self,
        func: &mut IrMachFunction,
        proof_metadata: Option<trust_cg_opt::proof_opts::ProofOptimizationMetadata>,
        provenance: Option<&mut trust_cg_ir::ProvenanceMap>,
        kernel_gate: Option<AArch64KernelGate>,
        validation: OptimizationValidation,
    ) -> Result<trust_cg_opt::PassStats, PipelineError> {
        use trust_cg_opt::pass_manager::MachinePass;
        use trust_cg_opt::pipeline::{OptLevel as OptOptLevel, OptimizationPipeline};
        use trust_cg_opt::scheduler::{InstructionScheduler, PressureAwareScheduler};

        // L10-P5: the instruction-selection output (or whatever a caller
        // handed in) must not hold an ID at or above its allocator's counter,
        // at every level (O0 runs no pass manager).
        admit_mach_ids(func, "optimization entry")?;

        let opt_level = match self.config.opt_level {
            OptLevel::O0 => OptOptLevel::O0,
            OptLevel::O1 => OptOptLevel::O1,
            OptLevel::O2 => OptOptLevel::O2,
            OptLevel::O3 => OptOptLevel::O3,
        };

        // Run the optimization pipeline for the selected level.
        //
        // sincos-merge (Darwin arm64 only) needs to know whether the object
        // target is Mach-O: `___sincos_stret` and its {d0=sin, d1=cos} return
        // ABI are Apple-specific: only an explicit Apple/darwin triple
        // qualifies. An empty triple is not Darwin (and is refused by every
        // target-dependent phase).
        let target_is_darwin = target_triple_uses_macho(&self.config.target_triple);
        let mut pipeline = OptimizationPipeline::new(opt_level)
            .with_target_is_darwin(target_is_darwin)
            // Capability ownership stays in codegen; optimization receives a
            // boolean admission and must otherwise choose its portable shape.
            // The admission is this function's: the profile plus its own
            // target features.
            .with_aarch64_dotprod(
                self.aarch64_target_machine
                    .admitted_features()
                    .admits(AArch64IsaFeature::DotProd)
                    || func
                        .function_target_features
                        .contains(AArch64IsaFeature::DotProd),
            );
        if let Some(disabled) = &self.config.disabled_passes_override {
            pipeline = pipeline.with_disabled_passes(disabled.clone());
        }
        if let Some(enabled) = self.config.contains4_scanner_batch_rewrite_override {
            pipeline = pipeline.with_contains4_scanner_batch_rewrite(enabled);
        }
        if self.config.skip_cse_gvn {
            // CSE/GVN extend live ranges on the bet that the allocator will
            // rematerialize under pressure; the JIT-latency profile disables
            // remat, so for these kernels the bet loses and the passes only add
            // spill traffic. The passes are value-preserving, so skipping them
            // is a pure code-quality choice with no effect on results.
            pipeline = pipeline.without_redundancy_elimination();
        }
        // A non-unwinding frame with an exception table
        // (`EhPropagation::NounwindFrame`) stops an exception at each call whose
        // region is a gap. A tail branch removes the frame before the callee
        // runs, so its table is never consulted and the exception keeps
        // unwinding into the caller's caller. LLVM forms such a tail call only
        // where its IR marks the call `tail`, which needs every alloca of the
        // frame unescaped (measured on a `nounwind` frame holding an invoke:
        // `b` for `cb(1); f(x - 3)` at O1-O3, `bl` once `black_box` takes an
        // address), and this backend cannot see that analysis. So no call of
        // such a frame becomes a tail call: where LLVM's does, the search fails
        // phase one here (earlier, OD-58). A tail call to a callee that may
        // unwind would keep unwinding as its covered region does, so refusing
        // it changes no outcome. Frames without an exception table keep theirs.
        if matches!(self.eh_propagation, EhPropagation::NounwindFrame { .. })
            && func.eh_metadata.has_eh_info()
        {
            pipeline = pipeline.without_tail_calls();
        }
        if self.certified_pass_execution {
            pipeline = pipeline.with_certified_pass_execution();
        }
        let pass_validation = validation.config;
        pipeline = pipeline
            .with_pass_validation(pass_validation)
            .with_pass_transitions(validation.transitions);
        match kernel_gate {
            Some(AArch64KernelGate::Empty) => {
                // Route every candidate through the fail-closed empty-authority policy.
                pipeline = pipeline.with_kernel_gate(
                    trust_cg_lower::guard_evidence::production_guard_replay_evidence(),
                    std::collections::HashMap::new(),
                );
            }
            Some(AArch64KernelGate::Lattice(authority)) => {
                pipeline = pipeline.with_lattice_kernel_gate(authority);
            }
            None => {}
        }
        if let Some(metadata) = proof_metadata {
            pipeline = pipeline.with_proof_optimization_metadata(metadata);
        }
        if let Some(profile) = self.profile_use.clone() {
            pipeline = pipeline.with_profile_use(profile);
        }
        let phase_timer = log_pipeline_phase_start(func, "opt-pass-manager");
        let mut stats = if let Some(provenance) = provenance {
            pipeline.run_with_provenance(func, provenance)
        } else {
            pipeline.run(func)
        };
        log_pipeline_phase_end(func, "opt-pass-manager", phase_timer);
        // L10-P5: the pass manager admitted every pass boundary it ran, or
        // stopped at the first refused one.
        stats
            .id_admission()
            .map_err(PipelineError::MachIdAdmission)?;
        // A refused run fails before any later step builds on it.
        Self::enforce_pass_validation(func, pass_validation, &stats.pass_validation)?;

        // The opt-in CEGIS superoptimizer checks each rewrite with its own
        // solver query; no pass validator covers it, so a run that changed
        // the function is recorded as uncovered.
        let cegis_fingerprint = (cfg!(feature = "verify")
            && pass_validation.policy.is_active()
            && self.config.cegis_superopt_budget_sec.is_some_and(|n| n > 0))
        .then(|| trust_cg_opt::pass_validation::function_fingerprint(func));
        let cegis_interface = validation.transitions.map(|digest| digest(func));
        let phase_timer = log_pipeline_phase_start(func, "cegis-superopt");
        let _ = admit_phase_allocations(func, "CEGIS superoptimization", |func| {
            self.run_cegis_superopt_checked(func)
        })??;
        log_pipeline_phase_end(func, "cegis-superopt", phase_timer);
        if let Some(before) = cegis_fingerprint
            && trust_cg_opt::pass_validation::function_fingerprint(func) != before
        {
            trust_cg_opt::pass_validation::record_unvalidated_change(
                pass_validation,
                "cegis-superopt",
                func,
                &mut stats.pass_validation,
            );
        }
        trust_cg_opt::pass_validation::record_unvalidated_transition(
            validation.transitions,
            "cegis-superopt",
            cegis_interface,
            func,
            &mut stats.pass_validation,
        );
        // L09-P3 route tests: an armed rewrite run through this function's
        // own validation and transition recording, as a pass would be.
        #[cfg(test)]
        crate::composed_transition::test_hooks::optimizer_step(
            func,
            pass_validation,
            validation.transitions,
            &mut stats.pass_validation,
        );

        // Pre-register-allocation instruction scheduling.
        // Skip at O0 for fastest compile. At O1, use the fast ILP scheduler.
        // At O2+, use pressure-aware scheduling by default. Each run is
        // checked by the dependence-preservation validator like the
        // optimizer's own scheduler runs.
        if !self.pass_disabled("sched") {
            let scheduler: Option<Box<dyn MachinePass>> = match self.config.opt_level {
                OptLevel::O0 => None,
                OptLevel::O1 => Some(Box::new(InstructionScheduler)),
                OptLevel::O2 | OptLevel::O3 => Some(Box::new(PressureAwareScheduler)),
            };
            if let Some(mut sched) = scheduler {
                let phase_timer = log_pipeline_phase_start(func, "codegen-scheduler");
                admit_phase_allocations(func, "the codegen scheduler", |func| {
                    Self::run_validated_codegen_scheduler(
                        func,
                        sched.as_mut(),
                        validation,
                        &mut stats,
                    )
                })??;
                log_pipeline_phase_end(func, "codegen-scheduler", phase_timer);
            }
        }
        self.finish_pass_validation(func, pass_validation, &mut stats)?;
        Ok(stats)
    }

    /// Run the codegen pipeline's pre-allocation scheduler `sched` under
    /// pass validation (the dependence-preservation validator, like the
    /// optimizer's own scheduler runs), recording the verdict in `stats`, and
    /// refuse the compile when `config`'s policy refuses it.
    fn run_validated_codegen_scheduler(
        func: &mut IrMachFunction,
        sched: &mut dyn trust_cg_opt::pass_manager::MachinePass,
        validation: OptimizationValidation,
        stats: &mut trust_cg_opt::PassStats,
    ) -> Result<(), PipelineError> {
        trust_cg_opt::pass_validation::run_validated_with_transitions(
            validation.config,
            validation.transitions,
            sched,
            func,
            &mut stats.pass_validation,
        );
        Self::enforce_pass_validation(func, validation.config, &stats.pass_validation)
    }

    /// Close one function's optimizer-side pass validation: refuse what the
    /// policy refuses (including an uncovered CEGIS run under
    /// `require-coverage`), report what the diagnostic policy does not
    /// refuse ([`Self::warn_pass_validation_failures`]), and, under certified
    /// pass execution, add one certified-pass-chain record per pass a
    /// validator covered
    /// ([`trust_cg_opt::PassValidationSummary::certified_pass_runs`]).
    fn finish_pass_validation(
        &self,
        func: &IrMachFunction,
        config: trust_cg_opt::PassValidationConfig,
        stats: &mut trust_cg_opt::PassStats,
    ) -> Result<(), PipelineError> {
        Self::enforce_pass_validation(func, config, &stats.pass_validation)?;
        Self::warn_pass_validation_failures(func, config, &stats.pass_validation);
        if self.certified_pass_execution {
            let runs = stats.pass_validation.certified_pass_runs(&func.name);
            stats.certified_pass_runs.extend(runs);
        }
        Ok(())
    }

    /// The diagnostic policy's report: one `trust-cg: warning:` line on
    /// standard error for each refuted or unproved run it kept (and a count
    /// of any it did not), so a failed validation in a default compile is
    /// never silent. The verdicts also reach the caller in
    /// [`PreparationMetrics::pass_validation`] and the compile result's
    /// `CompilationMetrics::pass_validation`. Uncovered runs are expected
    /// under the default scope and are counted there, not printed. The
    /// refusing policies fail the compile instead, and `off` records nothing.
    fn warn_pass_validation_failures(
        func: &IrMachFunction,
        config: trust_cg_opt::PassValidationConfig,
        summary: &trust_cg_opt::PassValidationSummary,
    ) {
        if config.policy != trust_cg_opt::PassValidationPolicy::Diagnostic {
            return;
        }
        let failed = summary.refuted() + summary.unproved();
        if failed == 0 {
            return;
        }
        let mut reported = 0u32;
        for record in summary.refusing_records() {
            reported += 1;
            eprintln!(
                "trust-cg: warning: pass validation did not validate `{}` in `{}` ({}: {}): {}",
                record.pass_name,
                func.name,
                record.validator.map_or("none", |v| v.as_str()),
                record.verdict.as_str(),
                record.verdict.reason().unwrap_or_default()
            );
        }
        if failed > reported {
            eprintln!(
                "trust-cg: warning: pass validation did not validate {} more run(s) in `{}` \
                 (records past the kept limit)",
                failed - reported,
                func.name
            );
        }
    }

    /// Refuse the compile when `config`'s policy refuses a recorded pass
    /// validation ([`trust_cg_opt::PassValidationSummary::first_refusal`]).
    fn enforce_pass_validation(
        func: &IrMachFunction,
        config: trust_cg_opt::PassValidationConfig,
        summary: &trust_cg_opt::PassValidationSummary,
    ) -> Result<(), PipelineError> {
        let Some(record) = summary.first_refusal(config.policy) else {
            return Ok(());
        };
        Err(PipelineError::PassValidationFailed {
            function: func.name.clone(),
            pass: record.pass_name.clone(),
            validator: record.validator.map_or("none", |v| v.as_str()),
            verdict: record.verdict.as_str(),
            reason: record
                .verdict
                .reason()
                .unwrap_or("no validator covers this pass")
                .to_string(),
        })
    }

    /// Phase 3.5: Run function-level verification (optional).
    ///
    /// When `self.config.verify` is true and the `verify` feature is enabled,
    /// calls [`trust_cg_verify::verify_function`] on the optimized IR. Returns an
    /// error only if any instruction *fails* verification (i.e., a proof was
    /// found but produced Invalid/Unknown). Unverified instructions (no proof
    /// available) are tolerated — they are expected for opcodes not yet covered
    /// by the proof database.
    ///
    /// When the `verify` feature is disabled, this is a no-op.
    #[cfg(feature = "verify")]
    fn run_verification(&self, func: &IrMachFunction) -> Result<(), PipelineError> {
        // Skip the expensive ProofDatabase construction + evaluation when
        // verification is disabled. Previously we always ran verify_function()
        // and only checked the result when config.verify was true, but
        // ProofDatabase::new() alone consumes significant stack space in debug
        // builds (hundreds of proof obligations with SmtExpr trees), which
        // contributed to stack overflows on the default 8 MB test-thread stack.
        // See issue #205.
        if !self.function_verification_selected(&func.name) {
            return Ok(());
        }

        let report = crate::jit_cert::run_on_proof_verifier_stack(
            "trust-cg-pipeline-proof-verifier",
            || trust_cg_verify::verify_function(func),
        );
        Self::enforce_verification_report(report)
    }

    /// Fail-closed translation of a per-instruction verification report into
    /// the pipeline verdict: any failed function prerequisite or FAILED
    /// instruction (a bound proof that refuted) rejects the compile; unverified/skipped instructions are
    /// tolerated (expected for opcodes without proof coverage).
    ///
    /// Split out of [`Self::run_verification`] so tests can drive the exact
    /// enforcement path with a refuted report — `verify_function` cannot be
    /// made to refute on well-formed input from here (the refutation content
    /// lives in trust-cg-verify's reconstruction/TV-2 layers), so the
    /// corrupted-lowering harness injects the report it produces.
    #[cfg(feature = "verify")]
    fn enforce_verification_report(
        report: trust_cg_verify::FunctionVerificationReport,
    ) -> Result<(), PipelineError> {
        if report.has_failures() {
            return Err(PipelineError::VerificationFailed {
                function: report.function_name.clone(),
                failures: report.failed_count()
                    + usize::from(report.precondition_failure.is_some()),
                coverage: report.coverage_percent(),
                report,
            });
        }

        Ok(())
    }

    /// Stub when `verify` feature is disabled — verification is a no-op,
    /// EXCEPT under [`DispatchVerifyMode::Sampled`]: a caller that opted into
    /// sampled verification must not get a silent no-op (fail closed). The
    /// legacy `verify = true` + no-feature combination keeps its historical
    /// silent-skip behaviour.
    #[cfg(not(feature = "verify"))]
    fn run_verification(&self, func: &IrMachFunction) -> Result<(), PipelineError> {
        if self.config.verify_dispatch.samples_function(&func.name) {
            return Err(PipelineError::SampledVerifyUnavailable {
                function: func.name.clone(),
            });
        }
        Ok(())
    }

    /// Whether phase 3.5 function-level verification runs for `name`:
    /// either full verification (`config.verify`) or the deterministic
    /// [`DispatchVerifyMode::Sampled`] sample selects it.
    fn function_verification_selected(&self, name: &str) -> bool {
        self.config.verify || self.config.verify_dispatch.samples_function(name)
    }

    /// Phase 4-6: Run register allocation and apply results.
    ///
    /// Returns the spill-slot count and a small post-rebuild snapshot used by
    /// debug provenance seeding to distinguish allocated values from spills.
    fn run_regalloc(&self, ir_func: &mut IrMachFunction) -> Result<RegAllocOutcome, PipelineError> {
        // L10-P5: covers verification and profile-counter injection too.
        admit_mach_ids(ir_func, "register allocation entry")?;
        rebuild_ir_cfg_edges_from_branch_operands(ir_func);
        // This is the last signature-bearing authority boundary before
        // `ir_to_regalloc` intentionally drops the canonical signature. Run it
        // after every optimizer/scheduler mutation, not only at the public
        // pre-optimization entry, so no pass can silently remove or alter a
        // `RET`'s authenticated ABI return-register sink metadata.
        self.validate_aarch64_mach_function_for_profile(ir_func)?;
        eliminate_dead_register_formal_copies(ir_func);
        eliminate_dead_literal_materializations(ir_func);
        // Regalloc phase-internal attribution (Task 3): the pipeline-side seams
        // that bracket the core allocator. Gated on the SAME env var as pass
        // timing (via `trust_cg_time_pipeline_enabled`, which is true under
        // TRUST_CG_TIME_PASSES); cached, so OFF is a single atomic load.
        let ra_time = trust_cg_time_pipeline_enabled();

        // Phase 4: Convert IR to regalloc format
        let t = ra_time.then(Instant::now);
        let mut ra_func = ir_to_regalloc(ir_func)?;
        if let Some(t) = t {
            eprintln!(
                "[trust-cg-time-regalloc] func={} pass=pipeline stage=ir-to-regalloc elapsed_us={}",
                ra_func.name,
                t.elapsed().as_micros()
            );
        }

        // LEVER A (TCG_AARCH64_RA_LOOP_DEPTH, default OFF): the aarch64 path
        // never populates RegAllocBlock::loop_depth (the ir_to_regalloc adapter
        // copies the IR block's 0-stub field), so compute_spill_weight
        // degenerates to static use-density and evicts hot-loop heap bases in
        // favor of remat-eligible constants with many static uses. When the flag
        // is set, fill loop_depth with the CFG's natural-loop nesting depth
        // (dominator/back-edge analysis, deterministic) before liveness/regalloc
        // runs, restoring the 10^depth hot-loop weighting. Mirrors x86's opt-in
        // TCG_X86_RA_LOOP_DEPTH; default OFF => byte-identical to HEAD.
        // LIVE-RANGE SPLITTING (TCG_AARCH64_RA_SPLIT) also needs non-degenerate
        // loop-depth weights, but it populates them TRANSIENTLY inside the
        // regalloc split driver (only the re-allocation pass + KEEP-BETTER metric
        // see them; the depth-0 state is restored whenever the split is declined,
        // so a program the split does not help stays byte-identical to HEAD).
        // Coupling Lever A here at the pipeline level instead would apply it to
        // the FIRST allocation too and regress values it does not help (measured:
        // fannkuch grows reloads under pipeline-level depth). So the split flag is
        // deliberately NOT wired here; only Lever A (TCG_AARCH64_RA_LOOP_DEPTH)
        // is. Both default OFF => byte-identical to HEAD.
        //
        // GREEDY ALLOCATOR (DEFAULT ON since the 2026-07-18 flip; escape hatch
        // TCG_AARCH64_RA_LINEARSCAN=1 restores the legacy LinearScan): selects
        // the LLVM-style Greedy strategy for the aarch64 AOT path (the strategy
        // x86-64 production AOT drives through the same translation validator;
        // splitting is held OFF here — see the config-site comment below for
        // the measured split P0). The greedy eviction heuristics price spill
        // weight at 10^depth, so this ALSO populates loop depths
        // unconditionally (the coherent pair: depth-aware weights are what make
        // greedy's eviction pick the right victims).
        // FLIP EVIDENCE (measured on main at 09674fa, 46-program reliable set,
        // interleaved best-of-5, all bit-exact): geomean 1.0758 -> 1.0275
        // (ON/OFF 0.955); lists 2.12->1.00, ReedSolomon 2.41->1.47, salsa20
        // 1.84->1.20, huffbench 1.97->1.49, dry 1.30->1.19, almabench
        // 1.56->1.48; the ONE >5% regression is matmul_f64_4x4 1.26->1.55
        // (pressure-shuffle class — documented, diagnosis queued); the older
        // sieve +7.7% regression did NOT recur post-branch-forwarding.
        // Compile +1.5% suite / +1-1.7% at scale. Canonical torture with
        // greedy 1064 PASS / 0 MISCOMPILE; zero validator incidents.
        let mut ra_greedy = std::env::var_os("TCG_AARCH64_RA_LINEARSCAN").is_none()
            || std::env::var_os("TCG_AARCH64_RA_GREEDY").is_some();
        if ra_greedy || std::env::var_os("TCG_AARCH64_RA_LOOP_DEPTH").is_some() {
            let t = ra_time.then(Instant::now);
            trust_cg_regalloc::populate_loop_depths(&mut ra_func);
            if let Some(t) = t {
                eprintln!(
                    "[trust-cg-time-regalloc] func={} pass=pipeline stage=loop-depth elapsed_us={}",
                    ra_func.name,
                    t.elapsed().as_micros()
                );
            }
        }

        // LOOP-FREE ALLOCATOR ROUTING (default ON alongside the greedy flip;
        // escape hatch TCG_AARCH64_RA_GREEDY_ALWAYS=1 forces greedy even here):
        // route functions with NO natural loops back to LinearScan.
        //
        // WHY. Greedy's ONE >5% regression under the 2026-07-18 flip is
        // matmul_f64_4x4 (1.26 -> 1.57 end-to-end). Disasm-grounded root cause,
        // a three-line chain that ONLY fires in loop-free straight-line code:
        //   (1) spill weight degenerates to static use-density here — the
        //       10^depth hot-loop term is inert at depth 0 (liveness.rs:596),
        //       so populate_loop_depths above leaves every block at depth 0;
        //   (2) greedy processes intervals in density order, so the long
        //       multi-use whole-block FMA-chain intervals are handled LAST, and
        //       can_evict (greedy.rs:884) is unwinnable for a whole-block span —
        //       every preg already hosts a denser short temp somewhere on the
        //       span, so nothing can be evicted;
        //   (3) splitting is held OFF here (the fail-silent split P0 documented
        //       at the config site below), so the loser is whole-vreg spilled
        //       with a reload materialized INTO each FMA use (21 spill ops vs
        //       LinearScan's 8). LinearScan's positional (program-order)
        //       processing handles straight-line register pressure correctly.
        //
        // ZERO-RISK TO THE FLIP EVIDENCE. Every measured >5% flip WIN
        // (lists / ReedSolomon / salsa20 / huffbench / dry / almabench) is
        // loop-DRIVEN, i.e. max loop depth > 0, so those functions keep greedy
        // unchanged. Only loop-free functions — where the flip's own evidence
        // shows greedy has no upside and the one regression — move back.
        //
        // Read mechanism: populate_loop_depths (above, run under the same gate)
        // fills RegAllocBlock::loop_depth with the natural-loop nesting count;
        // a simple max over blocks == 0 means the function has no natural loop.
        // TCG_AARCH64_RA_LINEARSCAN=1 already forces ra_greedy=false everywhere
        // (this block is then a no-op); TCG_AARCH64_RA_GREEDY_ALWAYS=1 opts a
        // loop-free function back INTO greedy for future measurement.
        if ra_greedy && std::env::var_os("TCG_AARCH64_RA_GREEDY_ALWAYS").is_none() {
            let max_loop_depth = ra_func
                .blocks
                .iter()
                .map(|b| b.loop_depth)
                .max()
                .unwrap_or(0);
            if max_loop_depth == 0 {
                ra_greedy = false;
            }
        }

        // Debug: dump block structure before regalloc
        #[cfg(debug_assertions)]
        if std::env::var("TRUST_CG_DEBUG_REGALLOC").is_ok() {
            eprintln!("=== REGALLOC DEBUG: {} ===", ra_func.name);
            for (bi, block) in ra_func.blocks.iter().enumerate() {
                eprintln!(
                    "  block {}: insts={:?} succs={:?} preds={:?}",
                    bi,
                    block.insts.len(),
                    block.succs,
                    block.preds
                );
            }
            for (ii, inst) in ra_func.insts.iter().enumerate() {
                eprintln!(
                    "  inst {}: opc={} defs={:?} uses={:?}",
                    ii,
                    inst.opcode,
                    inst.defs
                        .iter()
                        .filter_map(|o| o.as_vreg())
                        .collect::<Vec<_>>(),
                    inst.uses
                        .iter()
                        .filter_map(|o| o.as_vreg())
                        .collect::<Vec<_>>()
                );
            }
        }

        // Phase 5: Run the allocator
        let mut ra_config = if self.config.enable_jit_fast_regalloc {
            // Latency-tuned profile for in-process JIT shapes: coalescing,
            // splitting, remat, and slot reuse off. Runs on the LinearScan
            // core, which carries the defensive `active_allocation_overlaps`
            // interference guard, so the JIT and AOT allocators share one
            // correct code path. The disabled passes are what cost time, not
            // the strategy. See AllocConfig::jit_latency_aarch64.
            trust_cg_regalloc::AllocConfig::jit_latency_aarch64()
        } else if ra_greedy {
            // GREEDY ALLOCATOR SWITCH (TCG_AARCH64_RA_GREEDY): LLVM-style greedy
            // eviction-based allocation, the strategy x86-64 production AOT
            // uses. Loop depths were populated above under the same gate so the
            // greedy spill-weight eviction sees the 10^depth hot-loop signal.
            //
            // LIVE-RANGE SPLITTING (TCG_AARCH64_RA_SPLITTING=1, default OFF): x86
            // runs greedy WITH splitting in production; aarch64 now can too, but
            // behind an opt-in gate while the exec evidence is gathered. (Distinct
            // from TCG_AARCH64_RA_SPLIT, which gates the separate LinearScan-side
            // gap-split experiment in trust_cg_regalloc::try_allocate; this flag
            // gates the GREEDY allocate_with_splitting path.)
            //
            // HISTORY. Measured 2026-07-18, greedy `allocate_with_splitting` on
            // this pipeline SILENTLY MISCOMPILED — a split piece's spill-slot
            // store landed on one CFG path while a reload sat on a path the store
            // did not dominate, so the reload read an uninitialized slot (repros:
            // gcc-c-torture 990628-1.c SIGSEGV; ReedSolomon rsdec_204 NULL heap
            // base). TWO things have since landed that unblock this:
            //   (1) the regalloc translation validator's slot-initialization
            //       dominance gate (`check_slot_init_dominance`, 029393b) — a
            //       reload not dominated by a store on EVERY path is now a NAMED
            //       compile error, so the class is fail-CLOSED, never silent;
            //   (2) this materialization now anchors a split connector's store at
            //       the PSEUDO_COPY split boundary (the def site of the spilled
            //       split child), which the splitter's own CFG-safety rules make
            //       dominate every reload of that piece — see
            //       `retained_spill_materialization_sites` /
            //       `materialize_spilled_operands_at_sites`.
            // The validator gate is the oracle and stays always-on regardless of
            // this flag: if a placement is ever wrong, the compile fails closed.
            //
            // SPLITTING FLIP CAMPAIGN (measured 2026-07-22, aarch64 native, this
            // release dylib, certs-off, best-of-11..15). A/B over the 18-prog
            // beat-llvm suite + the 7-prog gt set, three ways: forced LinearScan
            // (TCG_AARCH64_RA_LINEARSCAN=1), default adaptive greedy, and
            // greedy+splitting (this flag). Result: NO-GO — splitting stays
            // default-OFF.
            //   * CORRECTNESS: 25 progs x 3 strategies, zero exit mismatches,
            //     zero compile-fails, zero regalloc-validator false positives.
            //     Splitting's historically fail-SILENT class (the 2026-07-18
            //     990628-1 / rsdec_204 miscompiles noted above) came back
            //     fail-CLEAN here — the dominance gate + anchored materialization
            //     hold across the whole corpus.
            //   * PERF: on the noise-clean compute-dominated subset (LLVM>=30ms,
            //     11 progs) geomean vs LLVM was split 0.9545 < greedy 0.9642 <
            //     linear-scan 0.9700 — so greedy correctly beats LinearScan
            //     (re-confirms the d9ecd29d flip on this corpus too), and
            //     splitting adds only ~1% on top, almost entirely v1_saxpy
            //     (~8% real, held across reruns) while p1_xorshift slightly
            //     regresses and the sub-10ms micro-progs (h1/v2/v3) swing >20%
            //     run-to-run (startup-noise-dominated, not codegen signal).
            //   * p4_matmul, the benchmark that motivated the regalloc frontier,
            //     is RA-INVARIANT: linear-scan == greedy == greedy+split == 83ms
            //     (~2.8x LLVM). Its gap is the audited auto-vectorization loss,
            //     not register allocation — splitting does nothing for its
            //     24-accumulator inner loop.
            // A ~1%, single-benchmark-carried, noise-adjacent win does not clear
            // the bar to flip a previously-miscompiling default on by default, so
            // splitting remains opt-in behind this flag pending a higher-pressure
            // corpus (lists / ReedSolomon / salsa20 class) where it can show a
            // broad-based win.
            let mut cfg = trust_cg_regalloc::AllocConfig::greedy_aarch64();
            cfg.enable_splitting = std::env::var_os("TCG_AARCH64_RA_SPLITTING").is_some();
            cfg
        } else {
            trust_cg_regalloc::AllocConfig::default_aarch64()
        };
        // AArch64 post-RA rematerialization inside the allocator is left OFF: on
        // this pipeline the allocator does NOT assign physical registers to
        // spilled values (they stay VRegs; the pipeline's spill-materialization
        // pass assigns scratch pregs per use-site later). The allocator-side
        // `apply_rematerialization` replaces a spill-reload with a clone of the
        // constant's defining instruction that still carries the spilled VReg as
        // its def, then drops the vreg from `result.spills`; that clone is never
        // materialized to a physical register, so the consuming instruction reads
        // an unresolved VReg the encoder rejects ("unresolved virtual register(s)
        // after regalloc/copy lowering"). Rematerialization of Free (pure integer
        // immediate) spilled constants is instead performed soundly in the
        // pipeline's spill-materialization path, where the reload's scratch preg
        // is already known — see `remat_free_spilled_constants` and its use in
        // `materialize_spilled_operands_at_sites`.
        ra_config.enable_remat = false;
        let t = ra_time.then(Instant::now);
        let result = trust_cg_regalloc::allocate(&mut ra_func, &ra_config)
            .map_err(|e| PipelineError::RegAlloc(e.to_string()))?;
        if let Some(t) = t {
            eprintln!(
                "[trust-cg-time-regalloc] func={} pass=pipeline stage=allocate-core elapsed_us={}",
                ra_func.name,
                t.elapsed().as_micros()
            );
        }
        let spill_slot_count = result.spills.len();

        // SPLIT DIAGNOSTIC (TCG_AARCH64_RA_SPLIT_STATS, default OFF): count
        // spilled vregs that are the DEF of a PSEUDO_COPY split connector — i.e.
        // split PIECES that were spilled, exercising the split-boundary store
        // path this materialization must place dominance-correctly. A whole-vreg
        // spill's def is a real instruction, so it is not counted. Diagnostic
        // only; no effect on codegen.
        if std::env::var_os("TCG_AARCH64_RA_SPLIT_STATS").is_some() && !result.spills.is_empty() {
            use trust_cg_regalloc::machine_types::RegAllocOperand as RaOp;
            let spilled_ids: std::collections::BTreeSet<u32> =
                result.spills.iter().map(|s| s.vreg.id).collect();
            let mut piece_spills = 0usize;
            for inst in &ra_func.insts {
                if inst.opcode == trust_cg_regalloc::phi_elim::PSEUDO_COPY {
                    for d in &inst.defs {
                        if let RaOp::VReg(v) = d
                            && spilled_ids.contains(&v.id)
                        {
                            piece_spills += 1;
                        }
                    }
                }
            }
            eprintln!(
                "[trust-cg-split-stats] func={} spills={} split_piece_spills={}",
                ra_func.name,
                result.spills.len(),
                piece_spills
            );
        }

        // Debug: dump allocation
        #[cfg(debug_assertions)]
        if std::env::var("TRUST_CG_DEBUG_REGALLOC").is_ok() {
            eprintln!("  allocation:");
            let mut allocs: Vec<_> = result.allocation.iter().collect();
            allocs.sort_by_key(|(v, _)| v.id);
            for (vreg, preg) in allocs {
                eprintln!("    v{} -> {:?}", vreg.id, preg);
            }
            let mut spills: Vec<_> = result.spills.iter().map(|spill| spill.vreg.id).collect();
            spills.sort_unstable();
            eprintln!("  spills: {:?}", spills);
            eprintln!("=== END REGALLOC DEBUG ===");
        }

        // Phase 5.5: Post-RA spill optimization — eliminate dead stores,
        // redundant reloads, and dead definitions in spill code. Runs on the
        // regalloc-format function which still has spill pseudo-instructions.
        // Enabled at O1+ optimization levels. The `post_ra` bisect key lets a
        // caller disable it via TRUST_CG_DISABLE_PASSES for debugging.
        let post_ra_enabled =
            self.config.opt_level != OptLevel::O0 && !self.pass_disabled("post_ra");
        if post_ra_enabled {
            let t = ra_time.then(Instant::now);
            let _post_ra_stats = trust_cg_regalloc::post_ra_optimize(&mut ra_func);
            if let Some(t) = t {
                eprintln!(
                    "[trust-cg-time-regalloc] func={} pass=pipeline stage=post-ra-optimize elapsed_us={}",
                    ra_func.name,
                    t.elapsed().as_micros()
                );
            }
        }

        // Phase 5.6: Materialize the allocation on the regalloc-side function and
        // remove redundant physical-register copies before rebuilding IR and
        // lowering Copy pseudos to real MOVs.
        //
        // This now runs for spillful functions too. It used to be gated to
        // spill-free functions, which left high-register-pressure (spillful)
        // functions — exactly the ones that emit the most redundant reg-reg
        // moves — with no post-RA coalescing at all.
        //
        // Coalescing is inherently spill-safe: spilled values stay as VRegs
        // (they are never present in `result.allocation`, so
        // `apply_regalloc_to_regalloc` leaves them untouched), and
        // `post_ra_coalesce` only ever renames or deletes redundant *physical*
        // register copies. VRegs and the PSEUDO_SPILL_LOAD/STORE pseudos (which
        // carry VReg + StackSlot operands and no pregs) are invisible to its
        // liveness and rename logic, so spilled values are never disturbed. The
        // scratch registers used by later spill materialization are reserved and
        // never allocated, so coalescing can neither produce nor depend on them.
        //
        // `retained_spill_materialization_sites` is computed *after* coalescing
        // so each spill site anchors to an instruction that still lives in its
        // block. Computing it first would let a coalesced-away copy become a
        // dangling anchor that the rebuild remap silently drops (losing a spill
        // reload/store). Coalescing removes NOP'd copies from the block
        // instruction lists, so the post-coalesce anchors are always live.
        let mut post_ra_copies_coalesced = 0u32;
        // Physical-copy canonicalization is also needed at O0: ABI formal
        // copies may name Wn and Xn of the same hardware register. The
        // coalescer checks high-half liveness before removing such copies;
        // comparing register numbers in lower_copies would be unsound.
        // Keep the explicit pass bisect available at every optimization level.
        if !self.pass_disabled("post_ra") {
            let t = ra_time.then(Instant::now);
            apply_regalloc_to_regalloc(&mut ra_func, &result.allocation);
            let post_ra_coalesce_stats = if post_ra_enabled {
                trust_cg_regalloc::post_ra_coalesce(&mut ra_func)
            } else {
                trust_cg_regalloc::eliminate_physical_self_copies(&mut ra_func)
            };
            post_ra_copies_coalesced = post_ra_coalesce_stats.copies_removed;
            if let Some(t) = t {
                eprintln!(
                    "[trust-cg-time-regalloc] func={} pass=pipeline stage=post-ra-coalesce elapsed_us={}",
                    ra_func.name,
                    t.elapsed().as_micros()
                );
            }
        }
        let spill_sites = retained_spill_materialization_sites(&ra_func, &result.spills);

        // Allocation ran on `ra_func`; `ir_func` is still the pre-allocation
        // function, where a formal read is distinguishable from body code.
        let abi_variant = self.resolved_aarch64_abi()?;
        let formal_reads = aarch64_entry_formal_reads(ir_func, abi_variant);

        // Phase 6: Rebuild the IR from the regalloc-side function so interval
        // splitting, phi elimination, and spill-side rewrites are visible to
        // the encoder path.
        let t = ra_time.then(Instant::now);
        let inst_map = rebuild_ir_from_regalloc_with_map(ir_func, &ra_func)?;
        // L10-P5: the rebuilt arenas replace the admitted ones; the first
        // post-allocation rewrite that allocates (spill materialization,
        // spill slots, reload elision) re-derives every identity first.
        ir_func.require_id_admission_before_allocation();
        if let Some(t) = t {
            eprintln!(
                "[trust-cg-time-regalloc] func={} pass=pipeline stage=rebuild-ir elapsed_us={}",
                ra_func.name,
                t.elapsed().as_micros()
            );
        }
        let debug_defs = collect_regalloc_debug_defs(ir_func);
        let mut spill_sites = remap_spill_materialization_sites(spill_sites, &inst_map);
        let effective_spills =
            effective_spills_from_materialization_sites(&spill_sites, &result.spills);

        // Phase 6.5: Apply the allocation back to the rebuilt IR, then
        // materialize any remaining spilled values into that same IR.
        apply_regalloc(ir_func, &result.allocation);
        verify_aarch64_formal_entry_copy_hazards(
            ir_func,
            &remap_aarch64_formal_reads(&formal_reads, &inst_map),
        )?;
        ensure_spill_stack_slots(ir_func, &effective_spills);
        add_missing_spill_materialization_sites(ir_func, &mut spill_sites, &effective_spills);
        // Free-constant rematerialization: recover the pure-integer-immediate
        // move templates of spilled constants from their (still-VReg) defs
        // BEFORE materialization creates the reloads. This is the sound,
        // scratch-register-aware replacement for allocator-side remat — see the
        // note on `ra_config.enable_remat` above.
        let remat_consts = find_free_remat_spilled_constants(ir_func, &effective_spills);
        let spill_debug_info = materialize_spilled_operands_at_sites(ir_func, &spill_sites)?;
        // Turn each per-iteration reload of a Free constant into a per-iteration
        // recompute (`ldur scratch,[frame]` -> `movz scratch,#imm`), killing the
        // spilled-loop-constant reload traffic.
        let remat_reloads = remat_free_spilled_constant_reloads(ir_func, &remat_consts);
        if remat_reloads > 0 && trust_cg_time_pipeline_enabled() {
            eprintln!(
                "[trust-cg-time-regalloc] func={} pass=pipeline stage=remat-free-const reloads={}",
                ir_func.name, remat_reloads
            );
        }
        // Drop redundant two-copy round-trips before the call-arg fixup so it
        // does not misread a relocation round-trip as a parallel-move swap.
        eliminate_redundant_copy_roundtrips(ir_func);
        fixup_aarch64_call_arg_source_clobbers(ir_func, abi_variant)?;

        // Phase 6.6: Redundant spill-slot reload elision — delete a reload of
        // a regalloc spill slot whose bytes provably still sit in the target
        // scratch register (block-local; see the pass doc for the alias and
        // scratch-liveness proofs). Runs after every reload/store has been
        // materialized and after the copy fixups so the block contents are
        // final. Kill switch TCG_SPILL_RELOAD_CSE_OFF; bisect key
        // `spill_reload_cse`.
        if post_ra_enabled && !self.pass_disabled("spill_reload_cse") {
            let regalloc_spill_slots: BTreeSet<StackSlotId> =
                effective_spills.iter().map(|spill| spill.slot).collect();
            let reloads_elided = elide_redundant_spill_slot_reloads(ir_func, &regalloc_spill_slots);
            if reloads_elided > 0 && trust_cg_time_pipeline_enabled() {
                eprintln!(
                    "[trust-cg-time-regalloc] func={} pass=pipeline stage=spill-reload-cse elided={}",
                    ir_func.name, reloads_elided
                );
            }
        }

        // Phase 6.7: Post-RA branch forwarding. `split_critical_edges` (inside
        // the allocator, after the last CfgSimplify) leaves empty jump-only
        // trampoline blocks on critical edges; `post_ra_coalesce` above then
        // strips their phi copies, so a hot-loop back-edge pays two taken
        // branches per iteration. Retarget every direct branch through such
        // trampolines to their ultimate destination and drop the now-dead
        // trampolines from the layout. Pure branch-target rewrite (no register
        // or instruction changes) and gated with `post_ra` so it only runs when
        // coalescing has actually emptied the trampolines. Kill switch:
        // TRUST_CG_DISABLE_PASSES=branch_forward.
        // Phase 6.8: POST-RA scalar post-index formation. The `lsl`/`add`/`ldr`
        // address recompute this folds does not exist in the mid-end -- the
        // optimizer's `post_index` pass is provably inert there, because the
        // index is a loop-carried register (2 defs, 3 reads, different block) or
        // the load sits on a diamond arm. Post-RA is the first point the shape
        // exists, and where the binary patch that priced this lever operated.
        // Kill switch: TRUST_CG_DISABLE_PASSES=post_index_late.
        if post_ra_enabled && !self.pass_disabled("post_index_late") {
            let pi = crate::post_index_late::form_post_index_loads(ir_func);
            if pi.folded > 0 && trust_cg_time_pipeline_enabled() {
                eprintln!(
                    "[trust-cg-time-regalloc] func={} pass=pipeline stage=post-index-late folded={}",
                    ir_func.name, pi.folded
                );
            }
        }

        if post_ra_enabled && !self.pass_disabled("branch_forward") {
            let t = ra_time.then(Instant::now);
            let bf_stats = crate::branch_forward::forward_post_ra_branches(ir_func);
            if let Some(t) = t {
                eprintln!(
                    "[trust-cg-time-regalloc] func={} pass=pipeline stage=branch-forward forwarded={} removed={} elapsed_us={}",
                    ir_func.name,
                    bf_stats.branches_forwarded,
                    bf_stats.trampolines_removed,
                    t.elapsed().as_micros()
                );
            }
        }

        // L10-P5: the rebuilt arena, spill slots and post-RA rewrites took
        // their first allocation's admission above; report a refusal there.
        // Frame lowering re-derives at its own first allocation, and branch
        // resolution's entry admits whatever reaches it.
        if let Some(error) = ir_func.id_admission_refusal() {
            return Err(PipelineError::MachIdAdmission(trust_cg_ir::MachIdRefusal {
                function: ir_func.name.clone(),
                boundary: "the first allocation after register allocation".to_string(),
                error,
            }));
        }

        let spill_slots: BTreeMap<_, _> = effective_spills
            .iter()
            .map(|spill| (spill.vreg, spill.slot))
            .collect();
        let spilled_vregs = spill_slots.keys().copied().collect();

        Ok(RegAllocOutcome {
            spill_slot_count,
            post_ra_copies_coalesced,
            debug_snapshot: RegAllocDebugSnapshot {
                allocation: result.allocation,
                spilled_vregs,
                spill_slots,
                spill_stores: spill_debug_info.stores,
                inst_map,
                defs: debug_defs,
            },
        })
    }

    /// Phase 7: Frame lowering — prologue/epilogue + frame index elimination.
    ///
    /// Returns the computed [`FrameLayout`] so downstream phases (compact unwind
    /// emission) can use it without recomputing.
    fn run_frame_lowering(
        &self,
        func: &mut IrMachFunction,
    ) -> Result<crate::frame::FrameLayout, PipelineError> {
        self.run_frame_lowering_for_source(func, None, Aarch64DirectCallAdmission::Compatibility)
    }

    /// [`Self::run_frame_lowering`] for a function lowered from `source`, the
    /// exact LIR function instruction selection consumed and the verifier
    /// later pairs with it. Without a source, every envelope the zero-storage
    /// policy keeps for the source-bound frame owner is retained.
    ///
    /// The frame is lowered for a proof-grade publication when this pipeline
    /// selected [`Self::with_proof_grade_aarch64_publication`] or
    /// `direct_call_admission` is sealed Core. Sealed Core is proof-grade
    /// whatever the builder selected: its raw dataflow check, final-stream
    /// recheck and encoder already enforce that policy, so its frame takes
    /// the same no-red-zone, zero-storage leaf policy and stack-limit refusal.
    fn run_frame_lowering_for_source(
        &self,
        func: &mut IrMachFunction,
        source: Option<&trust_cg_lower::Function>,
        direct_call_admission: Aarch64DirectCallAdmission,
    ) -> Result<crate::frame::FrameLayout, PipelineError> {
        use crate::frame;

        let proof_grade = self.proof_grade_aarch64_publication()
            || direct_call_admission.integrity_policy()
                == Aarch64IntegrityPolicy::ProofGradeEnforce;

        // Red zone, shrink-wrap eligibility and canary support are target
        // facts; an empty or unrecognized triple is refused before any of
        // them is decided.
        self.resolved_aarch64_abi()?;

        // L10-P5: frame lowering allocates the protector slot, prologue and
        // epilogue instructions and probe blocks; its first allocation
        // re-derives whatever copy lowering and dead-definition binding left.
        func.require_id_admission_before_allocation();

        if func.stack_protector.is_enabled() {
            stack_protector_target_abi(&self.config.target_triple)?;
        }

        frame::ensure_stack_protector_slot(func).map_err(|error| {
            mach_id_refusal_or(func, "frame lowering", PipelineError::FrameLowering(error))
        })?;

        // A U10 stack-limit check has no LIR source, so a proof-grade
        // publication cannot credit it: refuse rather than publish
        // uncredited words or drop the request.
        if func.stack_limit.is_some() && proof_grade {
            return Err(PipelineError::StackLimitNotProofQualified {
                function: func.name.clone(),
            });
        }

        // Compute outgoing arg area size from actual call sites. ISel emits
        // stack-passed arguments as stores with base=SP; scanning those stores
        // yields the high-water mark the caller must reserve at the bottom of
        // its own frame so the stores do not overlap the saved FP/LR pair
        // (bug fix: test_differential_call_with_stack_args, issue #301).
        // The checked frame view excludes arena instructions that optimization
        // unlinked from the emitted layout, including dead calls and arguments.
        //
        // A proof-grade publication uses the zero-storage audit on every
        // target. Linear source/return routing no longer needs a frame;
        // actual B rows retain separately replayed control evidence. Sources
        // that still rely on the frame-bound owner preserve that envelope.
        // Proof mode keeps red-zone storage disabled, while the compatibility
        // lane retains its existing target red-zone policy.
        let force_frame_pointers = self.config.aarch64_force_frame_pointers;
        let enable_red_zone = target_triple_allows_aarch64_red_zone(&self.config.target_triple)
            && !proof_grade
            && !force_frame_pointers;
        // A source the frame owner never judges cannot earn envelope credit.
        // A bounded linear scalar source can instead bind its final allocated
        // return routing without a frame; its actual B rows receive separate
        // replayed next-PC evidence. Both use the ordinary zero-storage audit,
        // which still refuses storage, calls and preserved-register effects.
        // Other frame-owner sources keep their existing proof envelope until
        // equivalent frameless evidence covers their domain. Explicit frame
        // pointer requests always retain their frame.
        let leaf_policy = if force_frame_pointers {
            frame::LeafFramePolicy::Keep
        } else if !enable_red_zone
            && source.is_some_and(|source| {
                !trust_cg_verify::source_bound_frame::source_requires_frame_proof_envelope(source)
            })
        {
            frame::LeafFramePolicy::OmitZeroStorageWithoutFrameOwner
        } else {
            frame::LeafFramePolicy::OmitZeroStorage
        };
        let layout = frame::try_compute_emitted_frame_layout(func, enable_red_zone, leaf_policy)
            .map_err(PipelineError::FrameLowering)?;
        frame::eliminate_frame_indices(func, &layout)?;
        // FINDING #10a: frame lowering can now fail closed (e.g. a constant-count
        // alloca whose byte size overflows u64) instead of aborting; surface it
        // as a recoverable pipeline error.
        //
        // Shrink-wrapping (ON by default; kill switch TCG_AARCH64_SHRINKWRAP_OFF)
        // is only sound for Darwin Mach-O FRAME-mode unwind: ELF/DWARF-fallback
        // FDEs hardcode the entry prologue, so an ELF triple declines. Only
        // Apple and ELF triples get past `resolved_aarch64_abi` above.
        let shrink_wrap_eligibility =
            if force_frame_pointers || target_triple_uses_elf(&self.config.target_triple) {
                frame::ShrinkWrapEligibility::Disabled
            } else {
                frame::ShrinkWrapEligibility::DarwinFrame
            };
        frame::insert_prologue_epilogue_shrinkwrap(func, &layout, shrink_wrap_eligibility)
            .map_err(|error| {
                mach_id_refusal_or(func, "frame lowering", PipelineError::FrameLowering(error))
            })?;

        // Expand TLSDESC call forms into their fixed four-slot sequences now
        // that no later pass can separate or reallocate them (see
        // `expand_tlsdesc_call_sequences`; the shape is re-verified at encode).
        expand_tlsdesc_call_sequences(func)?;

        // Regalloc spill/reload can orphan a GOT/TLVP page-offset load from
        // its feeding ADRP; re-pair by rematerializing the ADRP at the load
        // (see `repair_orphaned_got_page_pairs` — required for relocation
        // correctness, enforced fail-closed at encode).
        repair_orphaned_got_page_pairs(func);

        // Final safety net: legalize any scalar load/store whose fully-resolved
        // base+offset is outside BOTH encodable AArch64 immediate ranges (e.g. a
        // spill store `str x16, [x29, #-384]` whose slot offset landed out of
        // range). Runs last in frame lowering — after every pass that can
        // finalize an offset, and before branch resolution — so the instructions
        // it inserts are counted in PC-relative branch offsets.
        frame::legalize_large_mem_offsets(func)
            .map_err(|e| PipelineError::Encoding(e.to_string()))?;

        // AArch64 ELF: fuse `ADRP+ADD+LDR/STR` into `ADRP+LDR/STR #:lo12:`
        // where the symbol's placement guarantees the access alignment. Runs
        // after every offset-finalizing pass and before branch resolution, so
        // the removed ADDs are reflected in branch displacements.
        if target_triple_uses_elf(&self.config.target_triple)
            && let Some(alignments) = &self.elf_lo12_symbol_alignments
        {
            fuse_elf_lo12_memory_accesses(func, alignments);
        }
        Ok(layout)
    }

    /// Phase 9: Emit a Mach-O .o file from encoded machine code.
    ///
    /// When `frame_layout` is provided, a `__LD,__compact_unwind` section is
    /// emitted containing a single compact unwind entry for the function.
    /// This is required by macOS for backtraces, profilers, and exception handling.
    ///
    /// When `lsda` is provided, a `__TEXT,__gcc_except_tab` section is
    /// emitted containing the LSDA (Language-Specific Data Area) for exception
    /// handling. The personality routine reads this data to dispatch exceptions
    /// to the correct landing pad. Each typed-catch TType slot of the image is
    /// relocated `ARM64_RELOC_POINTER_TO_GOT` (pc-relative) against its
    /// typeinfo symbol, the form clang emits for `DW_EH_PE_indirect|pcrel|sdata4`.
    ///
    /// When `self.config.emit_debug` is true, DWARF debug sections are also
    /// emitted (`__DWARF,__debug_info`, `__debug_abbrev`, `__debug_str`,
    /// `__debug_line`).
    ///
    /// An object carrying exception tables is emitted only once the
    /// exception-table obligations (ledger L03-P14) hold for it
    /// ([`Self::check_macho_eh_obligations`]).
    fn emit_macho(
        &self,
        ir_func: &IrMachFunction,
        code: &[u8],
        frame_layout: Option<&crate::frame::FrameLayout>,
        lsda: Option<&crate::exception_handling::LsdaImage>,
        debug_provenance: Option<(
            &trust_cg_ir::ProvenanceMap,
            &BTreeMap<trust_cg_ir::TrustIrInstId, trust_cg_ir::SourceLoc>,
        )>,
        fixups: Option<&crate::macho::fixup::FixupList>,
    ) -> Result<Vec<u8>, PipelineError> {
        let object =
            self.emit_macho_object(ir_func, code, frame_layout, lsda, debug_provenance, fixups)?;
        if lsda.is_some() {
            let code_len =
                checked_aarch64_object_u32(&ir_func.name, "encoded code length", code.len())?;
            let layout = frame_layout.ok_or_else(|| {
                PipelineError::Unwind(format!(
                    "EH obligations need the frame layout of `{}`",
                    ir_func.name
                ))
            })?;
            self.check_macho_eh_obligations(&object, &[(ir_func, 0, code_len, layout)])?;
        }
        Ok(object)
    }

    /// [`Self::emit_macho`] without the exception-table obligations: the
    /// object writer alone.
    fn emit_macho_object(
        &self,
        ir_func: &IrMachFunction,
        code: &[u8],
        frame_layout: Option<&crate::frame::FrameLayout>,
        lsda: Option<&crate::exception_handling::LsdaImage>,
        debug_provenance: Option<(
            &trust_cg_ir::ProvenanceMap,
            &BTreeMap<trust_cg_ir::TrustIrInstId, trust_cg_ir::SourceLoc>,
        )>,
        fixups: Option<&crate::macho::fixup::FixupList>,
    ) -> Result<Vec<u8>, PipelineError> {
        use crate::dwarf_cfi::{DwarfCfiSection, DwarfFde};
        use crate::macho::MachOWriter;
        use crate::macho::constants::S_REGULAR;
        use crate::macho::reloc::Relocation;
        use crate::unwind::{
            CompactUnwindEntry, CompactUnwindSection, add_compact_unwind_to_writer,
        };

        let func_name = &ir_func.name;
        let code_len = checked_aarch64_object_u32(func_name, "encoded code length", code.len())?;
        let mut writer = MachOWriter::new();
        writer.set_build_version(self.macho_build_version()?);
        // Honor the function's emission-time alignment request (loop-head
        // alignment): a single-function object places the function at section
        // offset 0, so section alignment alone makes its function-relative
        // 32-byte boundaries absolute.
        writer.add_text_section_with_align(code, u32::from(ir_func.text_align_log2.max(2)));

        // Add the function symbol with Mach-O name mangling (_prefix).
        let symbol_name = format!("_{}", func_name);
        // Section index 1 = __text (first section, 1-based).
        let symbol_id = writer.add_symbol(&symbol_name, 1, 0, true)?;

        let mut lsda_symbol_id = None;
        let mut lsda_section_index = None;
        let mut personality_symbol_id = None;
        let mut typeinfo_symbol_ids: HashMap<String, crate::macho::SymbolId> = HashMap::new();

        // Emit LSDA (__gcc_except_tab) section + its symbols for exception
        // handling. Non-DWARF compact-unwind entries reference this section
        // directly; DWARF fallback entries reference it from the FDE
        // augmentation data. It must appear in __TEXT to be PC-relative
        // addressable on AArch64 macOS.
        //
        // CRITICAL ORDERING: these symbols MUST be created BEFORE the text
        // fixups are resolved to relocations below. The LSDA symbol is a *local*
        // (defined) symbol; `MachOWriter::write` emits symbols in Mach-O
        // dysymtab order (locals, then external-defined, then undefined), so
        // inserting a local symbol shifts the final index of every undefined
        // symbol. If we resolved the BL relocations first (computing each
        // callee's `final_symbol_index`) and then added the LSDA local symbol,
        // every text relocation would point one slot too early — the linker
        // would wire `bl cxx_throw` to the wrong callee. Adding the EH symbols
        // up front makes the symbol table final before any index is read.
        if let Some(lsda) = lsda {
            let lsda_section = writer.add_custom_section(
                b"__gcc_except_tab",
                b"__TEXT",
                &lsda.bytes,
                2, // 2^2 = 4-byte alignment (matching LLVM)
                S_REGULAR,
            );
            lsda_section_index = Some(lsda_section);
            let name = format!("_GCC_except_table_{}", func_name);
            lsda_symbol_id = Some(writer.add_symbol(&name, lsda_section + 1, 0, false)?);

            let personality = crate::exception_handling::required_personality_symbol(
                ir_func.eh_metadata.personality.as_deref(),
            )
            .map_err(|error| PipelineError::MalformedAarch64Eh {
                function: ir_func.name.clone(),
                detail: format!("invalid exception-handling personality: {error}"),
            })?;
            let name = format!("_{}", personality);
            personality_symbol_id = Some(writer.add_symbol(&name, 0, 0, true)?);

            // Typed-catch typeinfo symbols: undefined externals the LSDA's
            // TType slots relocate against, registered under the same
            // before-any-final-index rule as the LSDA local above.
            for reloc in &lsda.typeinfo_relocations {
                let abi_name = macho_symbol_name(&reloc.symbol);
                if abi_name == symbol_name {
                    return Err(PipelineError::MalformedAarch64Function {
                        function: ir_func.name.clone(),
                        detail: format!(
                            "typed catch typeinfo symbol `{}` names the function itself",
                            reloc.symbol
                        ),
                    });
                }
                if let std::collections::hash_map::Entry::Vacant(entry) =
                    typeinfo_symbol_ids.entry(abi_name)
                {
                    let id = writer.add_symbol(entry.key(), 0, 0, true)?;
                    entry.insert(id);
                }
            }
        }

        // Register every fixup target before unwind emission can expose a
        // final nlist index. A later DWARF `EH_Frame` local changes final symbol
        // order, so target registration and numeric-index resolution must be
        // separate phases.
        let fixup_symbol_ids = if let Some(fixups) = fixups
            && !fixups.is_empty()
        {
            Some(add_single_function_symbol_ids_for_fixups(
                &mut writer,
                func_name,
                symbol_id,
                fixups,
                &typeinfo_symbol_ids,
            )?)
        } else {
            None
        };

        // Emit compact unwind section if we have frame layout information.
        if let Some(layout) = frame_layout {
            let probe_entry = CompactUnwindEntry::from_layout(
                layout, 0, // function_offset (relocated via ARM64_RELOC_UNSIGNED)
                code_len, 0,
            );
            let needs_dwarf_fallback = probe_entry.needs_dwarf_fallback();
            let mut eh_frame_info = None;

            if needs_dwarf_fallback {
                let has_eh = lsda.is_some();
                let mut cfi = if has_eh {
                    DwarfCfiSection::new_aarch64_with_eh()
                } else {
                    DwarfCfiSection::new()
                };
                let mut fde = DwarfFde::from_layout(layout, 0, code_len, 0);
                if has_eh {
                    fde = fde.with_lsda();
                }
                cfi.add_fde(fde);
                let mut eh_frame = cfi.to_bytes();
                // ENC-EHDC: decode the full serialization back to intent
                // before any byte ships, then strip the zero terminator:
                // ld64-arm64 parses to the section bounds and rejects a
                // zero-length entry as "empty CIE" (see the module-batch site).
                crate::dwarf_cfi_decode_check::verify_eh_frame_roundtrip(&cfi, &eh_frame)?;
                strip_verified_eh_frame_terminator(&mut eh_frame)?;
                if !eh_frame.is_empty() {
                    const EH_FRAME_FLAGS: u32 = 0x6800_000B;
                    for pc_begin_offset in cfi.fde_pc_begin_relocation_offsets() {
                        let addend = -(pc_begin_offset as i64);
                        let offset = pc_begin_offset as usize;
                        eh_frame[offset..offset + 8].copy_from_slice(&addend.to_le_bytes());
                    }
                    for lsda_offset in cfi.fde_lsda_relocation_offsets() {
                        let addend = -(lsda_offset as i64);
                        let offset = lsda_offset as usize;
                        eh_frame[offset..offset + 8].copy_from_slice(&addend.to_le_bytes());
                    }
                    let eh_frame_section = writer.add_custom_section(
                        b"__eh_frame",
                        b"__TEXT",
                        &eh_frame,
                        3, // 2^3 = 8-byte alignment
                        EH_FRAME_FLAGS,
                    );
                    let eh_frame_symbol =
                        writer.add_symbol("EH_Frame", eh_frame_section + 1, 0, false)?;
                    eh_frame_info = Some((eh_frame_section, eh_frame_symbol, cfi));
                }
            }

            let function_symbol_index =
                final_macho_symbol_index(&mut writer, symbol_id, "function unwind emission")?;
            let personality_symbol_index = personality_symbol_id
                .map(|id| final_macho_symbol_index(&mut writer, id, "personality unwind emission"))
                .transpose()?;
            let lsda_symbol_index = lsda_symbol_id
                .map(|id| final_macho_symbol_index(&mut writer, id, "LSDA unwind emission"))
                .transpose()?;
            let eh_frame_symbol_index = eh_frame_info
                .as_ref()
                .map(|(_, symbol_id, _)| {
                    final_macho_symbol_index(
                        &mut writer,
                        *symbol_id,
                        "EH frame relocation emission",
                    )
                })
                .transpose()?;

            let mut cu_section = CompactUnwindSection::new();
            let mut entry = CompactUnwindEntry::from_layout(
                layout,
                0, // function_offset (relocated via ARM64_RELOC_UNSIGNED)
                code_len,
                function_symbol_index,
            );
            if !needs_dwarf_fallback {
                if let Some(symbol_index) = personality_symbol_index {
                    entry = entry.with_personality_symbol(symbol_index);
                }
                if let Some(symbol_index) = lsda_symbol_index {
                    entry = entry.with_lsda_symbol(symbol_index);
                }
            }
            cu_section.add_entry(entry);
            add_compact_unwind_to_writer(&mut writer, &cu_section)?;

            if let Some((eh_frame_section, _, cfi)) = eh_frame_info
                && let Some(eh_frame_symbol_index) = eh_frame_symbol_index
            {
                if let (Some(offset), Some(symbol_index)) = (
                    cfi.cie_personality_relocation_offset(),
                    personality_symbol_index,
                ) {
                    let offset = checked_aarch64_macho_relocation_offset(
                        func_name,
                        "CIE personality relocation offset",
                        offset,
                    )?;
                    writer.add_relocation(
                        eh_frame_section,
                        Relocation::pointer_to_got_pcrel(offset, symbol_index),
                    )?;
                }
                for pc_begin_offset in cfi.fde_pc_begin_relocation_offsets() {
                    let pc_begin_offset = checked_aarch64_macho_relocation_offset(
                        func_name,
                        "FDE PC-begin relocation offset",
                        pc_begin_offset,
                    )?;
                    writer.add_relocation(
                        eh_frame_section,
                        Relocation::subtractor(pc_begin_offset, eh_frame_symbol_index, 3),
                    )?;
                    writer.add_relocation(
                        eh_frame_section,
                        Relocation::unsigned_ptr(pc_begin_offset, function_symbol_index),
                    )?;
                }
                if let Some(symbol_index) = lsda_symbol_index {
                    for lsda_offset in cfi.fde_lsda_relocation_offsets() {
                        let lsda_offset = checked_aarch64_macho_relocation_offset(
                            func_name,
                            "FDE LSDA relocation offset",
                            lsda_offset,
                        )?;
                        writer.add_relocation(
                            eh_frame_section,
                            Relocation::subtractor(lsda_offset, eh_frame_symbol_index, 3),
                        )?;
                        writer.add_relocation(
                            eh_frame_section,
                            Relocation::unsigned_ptr(lsda_offset, symbol_index),
                        )?;
                    }
                }
            }
        }

        // Resolve text fixups only after every unwind/LSDA symbol has been
        // registered. A relocation stores a final nlist index and therefore
        // freezes the writer's symbol table; adding an EH_Frame local after
        // this point would otherwise silently invalidate earlier indices.
        if let Some(fixups) = fixups
            && let Some(fixup_symbol_ids) = fixup_symbol_ids
        {
            let mut finalize = |entries: HashMap<String, crate::macho::SymbolId>|
             -> Result<HashMap<String, u32>, PipelineError> {
                entries
                    .into_iter()
                    .map(|(name, symbol_id)| {
                    let final_index = writer.final_symbol_index(symbol_id)?.ok_or_else(|| {
                        PipelineError::ObjectEmission(
                            "symbol missing before Mach-O fixup resolution".to_string(),
                        )
                    })?;
                    Ok((name, final_index))
                })
                    .collect()
            };
            let ordinary_symbol_map = finalize(fixup_symbol_ids.ordinary_by_abi_name)?;
            let exact_symbol_map = finalize(fixup_symbol_ids.exact_function_by_raw_name)?;
            let mut resolved_fixups = fixups.clone();
            resolved_fixups.resolve_named_symbols_with_exact(
                |name| ordinary_symbol_map.get(&macho_symbol_name(name)).copied(),
                |name| exact_symbol_map.get(name).copied(),
            )?;
            let relocations = resolved_fixups.resolve_to_relocations()?;
            for reloc in relocations {
                writer.add_relocation(0, reloc)?;
            }
        }

        // Bind every typed-catch TType slot through the GOT
        // (`ARM64_RELOC_POINTER_TO_GOT`, pc-relative, 4 bytes). The symbol
        // table is final here: every typeinfo undefined predates the first
        // final-index read above.
        if let Some(lsda) = lsda
            && !lsda.typeinfo_relocations.is_empty()
        {
            let lsda_section = lsda_section_index.ok_or_else(|| {
                PipelineError::Unwind(format!(
                    "typed-catch LSDA of `{func_name}` has no __gcc_except_tab section (fail-closed)"
                ))
            })?;
            for reloc in &lsda.typeinfo_relocations {
                let symbol_id = typeinfo_symbol_ids
                    .get(&macho_symbol_name(&reloc.symbol))
                    .copied()
                    .ok_or_else(|| {
                        PipelineError::Unwind(format!(
                            "typeinfo symbol `{}` of `{func_name}` was not registered before \
                             relocation emission (fail-closed)",
                            reloc.symbol
                        ))
                    })?;
                let symbol_index = final_macho_symbol_index(
                    &mut writer,
                    symbol_id,
                    "LSDA typeinfo relocation emission",
                )?;
                writer.add_relocation(
                    lsda_section,
                    Relocation::pointer_to_got_pcrel(reloc.offset, symbol_index),
                )?;
            }
        }

        // Emit DWARF debug sections when debug info is requested.
        if self.config.emit_debug {
            let debug_info = self.single_function_debug_info(
                ir_func,
                code_len,
                frame_layout,
                debug_provenance,
                symbol_name.clone(),
            )?;
            crate::dwarf_info::add_debug_info_to_writer(&mut writer, &debug_info)?;
        }

        Ok(writer.write()?)
    }

    /// DWARF image of one function emitted alone into an AArch64 ELF object:
    /// `None` unless `-g` (`emit_debug`) is set and the target is ELF. The
    /// description is [`Self::single_function_debug_info`], the one the
    /// Mach-O path uses, so both formats carry the same DIEs and line rows.
    fn elf_single_function_debug_image(
        &self,
        ir_func: &IrMachFunction,
        code: &[u8],
        frame_layout: &crate::frame::FrameLayout,
        debug_provenance: Option<(
            &trust_cg_ir::ProvenanceMap,
            &BTreeMap<trust_cg_ir::TrustIrInstId, trust_cg_ir::SourceLoc>,
        )>,
    ) -> Result<Option<crate::dwarf_info::DwarfSectionImage>, PipelineError> {
        if !self.config.emit_debug || !target_triple_uses_elf(&self.config.target_triple) {
            return Ok(None);
        }
        let code_len =
            checked_aarch64_object_u32(&ir_func.name, "encoded code length", code.len())?;
        let debug_info = self.single_function_debug_info(
            ir_func,
            code_len,
            Some(frame_layout),
            debug_provenance,
            ir_func.name.clone(),
        )?;
        Ok(debug_info.try_emit_section_image()?)
    }

    /// DWARF description of one function emitted alone at text offset 0:
    /// source-named parameters at their ABI locations (bounded to the entry
    /// range before the first clobber), locals from debug metadata and the
    /// provenance-derived register / spill-slot / constant location lists, and
    /// the line program. Mach-O and ELF single-function objects share it;
    /// `linkage_name` is the object-format symbol spelling.
    fn single_function_debug_info(
        &self,
        ir_func: &IrMachFunction,
        code_len: u32,
        frame_layout: Option<&crate::frame::FrameLayout>,
        debug_provenance: Option<(
            &trust_cg_ir::ProvenanceMap,
            &BTreeMap<trust_cg_ir::TrustIrInstId, trust_cg_ir::SourceLoc>,
        )>,
        linkage_name: String,
    ) -> Result<crate::dwarf_info::DwarfDebugInfo, PipelineError> {
        use crate::dwarf_info::{
            DwarfDebugInfo, EnumType, Enumerator, FunctionDebugInfo, SourceLanguage, StructMember,
            StructType,
        };
        let func_name = &ir_func.name;

        let debug_meta = &ir_func.debug_meta;

        // Determine source file name from debug_meta or fall back to function name.
        let default_file = format!("{}.rs", func_name);
        let source_file = debug_meta.source_file.as_deref().unwrap_or(&default_file);

        let mut debug_info = DwarfDebugInfo::new(source_file, ".", SourceLanguage::Rust);
        debug_info.add_standard_types();

        for sty in &debug_meta.struct_types {
            debug_info.add_struct_type(StructType {
                name: sty.name.clone(),
                byte_size: sty.byte_size,
                members: sty
                    .members
                    .iter()
                    .map(|member| StructMember {
                        name: member.name.clone(),
                        offset: member.offset,
                        type_index: dwarf_standard_type_index(member.ty),
                    })
                    .collect(),
            });
        }

        for ety in &debug_meta.enum_types {
            debug_info.add_enum_type(EnumType {
                name: ety.name.clone(),
                byte_size: ety.byte_size,
                underlying_type_index: dwarf_standard_type_index(ety.underlying_type),
                enumerators: ety
                    .enumerators
                    .iter()
                    .map(|enumerator| Enumerator {
                        name: enumerator.name.clone(),
                        value: enumerator.value,
                    })
                    .collect(),
            });
        }

        // The function sits at text offset 0, so its function-relative
        // locations need no rebasing.
        let (params, variables) = self.function_debug_locations(
            ir_func,
            code_len,
            frame_layout,
            debug_provenance.map(|(provenance, _)| provenance),
        )?;

        let line_entries = build_source_line_entries(ir_func, debug_provenance);

        let decl_line = if debug_meta.decl_line > 0 {
            debug_meta.decl_line as u16
        } else {
            1
        };

        let (name, linkage_name) = subprogram_names(debug_meta, func_name, linkage_name);
        debug_info.add_function(FunctionDebugInfo {
            name,
            linkage_name,
            low_pc: 0,
            size: code_len,
            params,
            variables,
            scopes: vec![],
            line_entries,
            decl_file: 1,
            decl_line,
        });
        Ok(debug_info)
    }

    /// Parameters and variables of one function, described over its own
    /// `code_len` encoded bytes from offset 0. The single-function and
    /// whole-module DWARF descriptions share it.
    ///
    /// Parameters are source-named at their ABI locations, a register one
    /// bounded to the entry range before its first clobber; they need no
    /// provenance. Locals come from the function's debug metadata: stack-slot
    /// and constant locals directly, and each provenance-backed local from
    /// `provenance`'s register / spill-slot / constant / alloca ranges. Without
    /// a map such a local keeps its DIE with an empty location list. Every
    /// frame-base-relative range is clipped to the code where X29 is the frame
    /// pointer.
    ///
    /// `ir_func` must be the exact instruction list the encoder emitted: the
    /// byte offsets are counted over its block layout.
    fn function_debug_locations(
        &self,
        ir_func: &IrMachFunction,
        code_len: u32,
        frame_layout: Option<&crate::frame::FrameLayout>,
        provenance: Option<&trust_cg_ir::ProvenanceMap>,
    ) -> Result<
        (
            Vec<crate::dwarf_info::FunctionParam>,
            Vec<crate::dwarf_info::VariableDebugInfo>,
        ),
        PipelineError,
    > {
        use crate::dwarf_info::{FunctionParam, VariableLocation};
        let debug_meta = &ir_func.debug_meta;

        // Build parameter debug info from source names and ABI locations.
        let lower_param_types: Vec<LowerType> = ir_func
            .signature
            .params
            .iter()
            .map(lower_type_from_ir_type)
            .collect();
        let abi_param_locations =
            AppleAArch64ABI::classify_params_with(self.resolved_aarch64_abi()?, &lower_param_types);
        let param_count = debug_meta
            .param_names
            .len()
            .max(ir_func.signature.params.len());
        let params: Vec<FunctionParam> = (0..param_count)
            .map(|i| {
                let name = debug_meta
                    .param_names
                    .get(i)
                    .cloned()
                    .unwrap_or_else(|| format!("arg{}", i));
                let type_index = ir_func
                    .signature
                    .params
                    .get(i)
                    .map(dwarf_type_index_for_ir_type)
                    .unwrap_or(3);
                let location = abi_param_locations
                    .get(i)
                    .map_or(VariableLocation::Register(0), |loc| {
                        bounded_dwarf_param_location(ir_func, loc, frame_layout, code_len)
                    });
                FunctionParam {
                    name,
                    type_index,
                    location,
                }
            })
            .collect();

        let variables =
            build_debug_variables(ir_func, debug_meta, frame_layout, code_len, provenance);

        // Frame-base-relative locations hold only where X29 is this frame's
        // frame pointer (not in the prologue before it is set, nor after an
        // epilogue reloads it).
        let fp_ranges = frame_pointer_valid_ranges(ir_func);
        let params = params
            .into_iter()
            .map(|mut param| {
                param.location = clip_frame_base_location(param.location, &fp_ranges)?;
                Ok(param)
            })
            .collect::<Result<Vec<_>, PipelineError>>()?;
        let variables = variables
            .into_iter()
            .map(|mut var| {
                var.location = clip_frame_base_location(var.location, &fp_ranges)?;
                Ok(var)
            })
            .collect::<Result<Vec<_>, PipelineError>>()?;
        Ok((params, variables))
    }

    // --- Dispatch verification ---

    /// Verify a dispatch plan against a compute graph, applying the configured
    /// [`DispatchVerifyMode`] policy.
    ///
    /// Returns:
    /// - `Ok(plan)` if verification passes or is disabled
    /// - `Ok(cpu_only_plan)` if verification fails under
    ///   [`DispatchVerifyMode::FallbackOnFailure`]
    /// - `Err(DispatchVerificationFailed)` if verification fails under
    ///   [`DispatchVerifyMode::ErrorOnFailure`]
    pub fn verify_dispatch_plan(
        &self,
        graph: &ComputeGraph,
        plan: DispatchPlan,
        recommendations: &[TargetRecommendation],
    ) -> Result<DispatchPlan, PipelineError> {
        match self.config.verify_dispatch {
            DispatchVerifyMode::Off => Ok(plan),
            DispatchVerifyMode::FallbackOnFailure => {
                let report = verify_dispatch_plan_properties(graph, &plan);
                if report.all_ok() {
                    Ok(plan)
                } else {
                    // Fall back to a CPU-only plan.
                    Ok(generate_cpu_only_plan(graph, recommendations))
                }
            }
            // Sampled applies its sampling to per-FUNCTION verification only;
            // dispatch plans are one-per-graph, so they get the fail-closed
            // ErrorOnFailure treatment.
            DispatchVerifyMode::ErrorOnFailure | DispatchVerifyMode::Sampled { .. } => {
                let report = verify_dispatch_plan_properties(graph, &plan);
                if report.all_ok() {
                    Ok(plan)
                } else {
                    let violations = report.total_violations();
                    let summary = format!("{}", report);
                    Err(PipelineError::DispatchVerificationFailed {
                        violations,
                        summary,
                        report,
                    })
                }
            }
        }
    }

    /// Generate a dispatch plan, verify it, and return the verified (or
    /// fallback) plan. This is the primary integration point for dispatch
    /// verification in the compilation pipeline.
    ///
    /// Combines plan generation with verification in a single call.
    pub fn generate_and_verify_dispatch(
        &self,
        graph: &ComputeGraph,
        recommendations: &[TargetRecommendation],
    ) -> Result<DispatchPlan, PipelineError> {
        let plan = generate_dispatch_plan(graph, recommendations);
        self.verify_dispatch_plan(graph, plan, recommendations)
    }

    /// Generate Metal kernel code for GPU-targeted dispatch operations.
    ///
    /// This is the primary integration point for Metal kernel generation in
    /// the compilation pipeline. It takes a verified dispatch plan and compute
    /// graph, and produces all MSL kernel sources plus host-side dispatch code.
    ///
    /// Typical usage:
    /// ```text
    /// let plan = pipeline.generate_and_verify_dispatch(&graph, &recs)?;
    /// let metal = pipeline.emit_metal_kernels(&plan, &graph)?;
    /// // metal.kernels contains MSL sources to compile with `xcrun metal`
    /// // metal.dispatch_code contains Objective-C host dispatch code
    /// ```
    pub fn emit_metal_kernels(
        &self,
        plan: &DispatchPlan,
        graph: &ComputeGraph,
    ) -> Result<crate::metal_emitter::MetalOutput, PipelineError> {
        crate::metal_emitter::emit_metal_kernels(plan, graph).map_err(PipelineError::from)
    }
}

// ---------------------------------------------------------------------------
// CoreML MIL generation from dispatch plan
// ---------------------------------------------------------------------------

/// Output of CoreML MIL program generation from a dispatch plan.
///
/// Contains the generated MIL program, any ANE compatibility warnings, and
/// an estimated latency based on the dispatch plan's cycle estimates for
/// ANE-targeted nodes.
#[derive(Debug, Clone)]
pub struct CoreMLOutput {
    /// The generated MIL program representing ANE-targeted operations.
    pub program: MilProgram,
    /// ANE compatibility warnings (empty if fully compatible).
    pub warnings: Vec<String>,
    /// Estimated latency in microseconds for the ANE subgraph, derived from
    /// the dispatch plan's per-node cycle estimates at an assumed 1 GHz
    /// Neural Engine clock.
    pub estimated_latency_us: u64,
}

/// Collect ANE-targeted nodes from a dispatch plan and request a CoreML MIL
/// program from the corresponding compute graph nodes.
///
/// This is the fail-closed integration boundary between the dispatch pipeline
/// and the CoreML emitter. It:
/// 1. Collects all node IDs assigned to `NeuralEngine` in the plan
/// 2. Resolves those IDs to `ComputeNode` references from the graph
/// 3. Delegates exact-recipe validation to
///    [`CoreMLEmitter::emit_program_from_nodes`]
/// 4. Validates ANE compatibility via [`validate_ane_compatibility`]
/// 5. Estimates latency from the plan's per-node cycle costs
///
/// TrustIR does not yet carry an exact tensor primitive/shape recipe, so the
/// emitter currently rejects every non-empty request with
/// `NoExactCoreMlRecipe`; steps 4 and 5 remain the future success path once
/// that canonical recipe exists. This function must not infer semantics from
/// operation names, byte counts, or public target labels.
pub fn emit_coreml_program(
    plan: &DispatchPlan,
    graph: &ComputeGraph,
) -> Result<CoreMLOutput, PipelineError> {
    // Step 1: Collect ANE-targeted node IDs from the dispatch plan assignment.
    let mut ane_node_ids: Vec<ComputeNodeId> = plan
        .assignment
        .iter()
        .filter(|(_, target)| **target == ComputeTarget::NeuralEngine)
        .map(|(id, _)| *id)
        .collect();

    if ane_node_ids.is_empty() {
        return Err(PipelineError::CoreMLEmit(CoreMLEmitError::EmptyNodeList));
    }

    // Sort by node ID for deterministic ordering.
    ane_node_ids.sort_by_key(|id| id.0);

    // Step 2: Resolve node IDs to ComputeNode references from the graph.
    let mut ane_nodes: Vec<ComputeNode> = Vec::with_capacity(ane_node_ids.len());
    for node_id in &ane_node_ids {
        let node = graph.node(*node_id).ok_or(PipelineError::CoreMLEmit(
            CoreMLEmitError::MissingPlanNode { node_id: *node_id },
        ))?;
        ane_nodes.push(node.clone());
    }

    // Step 3: Generate MIL program from ANE nodes.
    let mut emitter = CoreMLEmitter::new();
    let program = emitter.emit_program_from_nodes(&ane_nodes)?;

    // Step 4: Validate ANE compatibility.
    let warnings = validate_ane_compatibility(&program);

    // Step 5: Estimate latency from dispatch plan cycle costs.
    // Sum the estimated_cycles from KernelLaunch ops targeting NeuralEngine
    // nodes. Convert cycles to microseconds assuming ~1 GHz ANE clock.
    let total_ane_cycles: u64 = plan
        .ops
        .iter()
        .filter_map(|op| match op {
            DispatchOp::KernelLaunch {
                target: ComputeTarget::NeuralEngine,
                estimated_cycles,
                ..
            } => Some(*estimated_cycles),
            _ => None,
        })
        .sum();

    // 1 GHz = 1 cycle per ns. Convert cycles to microseconds: cycles / 1000.
    let estimated_latency_us = total_ane_cycles.saturating_div(1000).max(1);

    Ok(CoreMLOutput {
        program,
        warnings,
        estimated_latency_us,
    })
}

// ---------------------------------------------------------------------------
// CPU-only dispatch plan fallback
// ---------------------------------------------------------------------------

/// Generate a CPU-only dispatch plan as a safe fallback.
///
/// When dispatch verification fails, this function generates a conservative
/// plan that runs every node on `CpuScalar`. No data transfers or
/// synchronizations are needed because all execution stays on the CPU.
pub fn generate_cpu_only_plan(
    graph: &ComputeGraph,
    _recommendations: &[TargetRecommendation],
) -> DispatchPlan {
    use trust_cg_lower::dispatch::DispatchOp;
    use trust_cg_lower::target_analysis::ComputeTarget;

    let mut assignment = HashMap::new();
    let mut ops = Vec::new();
    let mut total_cycles: u64 = 0;

    // Walk nodes in ID order. Since all nodes are on the same target
    // (CpuScalar), no transfers or syncs are needed.
    let mut node_ids: Vec<_> = graph.nodes.iter().map(|n| n.id).collect();
    node_ids.sort_by_key(|id| id.0);

    for node_id in &node_ids {
        assignment.insert(*node_id, ComputeTarget::CpuScalar);

        let node = graph.node(*node_id);
        let estimated_cycles = node
            .and_then(|n| n.costs.get(&ComputeTarget::CpuScalar))
            .map(|c| c.latency_cycles)
            .unwrap_or(1);

        ops.push(DispatchOp::CpuFallback {
            node_id: *node_id,
            reason: "dispatch verification fallback".to_string(),
        });
        total_cycles = total_cycles.saturating_add(estimated_cycles);
    }

    DispatchPlan {
        ops,
        assignment,
        estimated_total_cycles: total_cycles,
    }
}

// ---------------------------------------------------------------------------
// Convenience: compile_to_object — one-shot compilation
// ---------------------------------------------------------------------------

/// Compile a trust_ir function to an Apple arm64 Mach-O .o file in one call.
///
/// This legacy one-shot API is defined as the `aarch64-apple-darwin` target
/// (DarwinPCS, Mach-O) and names it explicitly; use a target-aware
/// [`Pipeline`] or `Compiler` for any other target.
pub fn compile_to_object(
    input: &trust_cg_lower::Function,
    opt_level: OptLevel,
) -> Result<Vec<u8>, PipelineError> {
    let config = PipelineConfig {
        opt_level,
        emit_debug: false,
        verify_dispatch: DispatchVerifyMode::FallbackOnFailure,
        verify: false,
        cegis_superopt_budget_sec: None,
        target_triple: "aarch64-apple-darwin".to_string(),
        aarch64_force_frame_pointers: false,
        enable_fsym_trust_ir_preflight: false,
        // AOT object compilation keeps the full quality regalloc.
        enable_jit_fast_regalloc: false,
        // ...and therefore keeps CSE/GVN (rematerialization is available).
        skip_cse_gvn: false,
        disabled_passes_override: None,
        contains4_scanner_batch_rewrite_override: None,
        relocation_model: trust_cg_lower::RelocationModel::Static,
    };
    // The named Apple target resolves to the guaranteed Apple arm64 ISA
    // profile; binding it explicitly keeps this API's contract visible.
    let pipeline = Pipeline::new(config).with_aarch64_isa_profile(AArch64IsaProfile::APPLE_ARM64);
    pipeline.compile_function(input)
}

/// Run the dialect-framework progressive-lowering pipeline (verif -> trust_ir ->
/// machir -> MachFunction) on a [`trust_cg_dialect::DialectModule`] and return
/// one [`IrMachFunction`] per contained function.
///
/// Integration point for Trust Codegen#433 / trust_ir#428. The `DialectModule` must have
/// the `verif`, `trust_ir`, and `machir` dialects registered (see
/// [`trust_cg_dialect::dialects::conversions::register_all`]). Any op that no
/// registered pattern handles trips the legality gate inside
/// [`trust_cg_dialect::lower_module`] — producing a hard error in one known
/// location rather than leaking an unknown op into the MachFunction.
///
/// This is an early hook: for modules that arrive as `DialectModule` the
/// frontend calls this and then feeds the resulting MachFunctions through
/// the rest of the pipeline (regalloc, frame lowering, encoding, Mach-O).
/// `trust_ir::Module` frontends continue to use the legacy
/// [`Pipeline::compile_function`] path. Both paths converge at MachFunction.
pub fn dialect_lower_module(
    module: &mut trust_cg_dialect::DialectModule,
) -> Result<Vec<IrMachFunction>, trust_cg_dialect::LowerModuleError> {
    trust_cg_dialect::lower_module(module)
}

/// Build an `add(a: i32, b: i32) -> i32` function directly in IR.
///
/// This is a convenience for testing the pipeline without needing the full
/// trust_ir input infrastructure. It builds the function directly in trust-cg-ir
/// types with physical registers (simulating post-ISel + post-regalloc state).
pub fn build_add_test_function() -> IrMachFunction {
    use trust_cg_ir::function::Type;
    use trust_cg_ir::regs::{X0, X1};

    let sig = IrSignature::new(vec![Type::I32, Type::I32], vec![Type::I32]);
    let mut func = IrMachFunction::new("add".to_string(), sig);
    let entry = func.entry;

    // ADD X0, X0, X1 (result in X0 per ABI)
    let add = IrMachInst::new(
        IrOpcode::AddRR,
        vec![
            IrOperand::PReg(X0),
            IrOperand::PReg(X0),
            IrOperand::PReg(X1),
        ],
    );
    let add_id = func.push_inst(add);
    func.append_inst(entry, add_id);

    // RET
    let ret = IrMachInst::new(IrOpcode::Ret, vec![]).with_implicit_uses(&[X0]);
    let ret_id = func.push_inst(ret);
    func.append_inst(entry, ret_id);

    func
}

