    #[test]
    fn encode_with_provenance_records_offsets_for_emitted_non_pseudos() {
        let sig = IrSignature::new(vec![], vec![Type::I64]);
        let mut func = IrMachFunction::new("encode_provenance".to_string(), sig);
        let entry = func.entry;

        let copy = func.push_inst(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X0), IrOperand::PReg(X1)],
        ));
        let movz = func.push_inst(IrMachInst::new(
            IrOpcode::Movz,
            vec![IrOperand::PReg(X0), IrOperand::Imm(42)],
        ));
        let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]).with_implicit_uses(&[X0]));
        func.append_inst(entry, copy);
        func.append_inst(entry, movz);
        func.append_inst(entry, ret);

        let mut provenance = trust_cg_ir::ProvenanceMap::new();
        let pass = trust_cg_ir::PassId::new("test-isel");
        provenance.record_lowering(trust_cg_ir::TrustIrInstId(0), &[copy], pass.clone());
        provenance.record_lowering(trust_cg_ir::TrustIrInstId(1), &[movz], pass.clone());
        provenance.record_lowering(trust_cg_ir::TrustIrInstId(2), &[ret], pass);

        let (code, fixups, block_offsets) =
            encode_function_with_fixups_and_blocks_with_provenance(&func, &mut provenance)
                .expect("encoding should succeed");

        assert_eq!(code.len(), 8);
        assert!(fixups.is_empty());
        assert_eq!(block_offsets.get(&entry), Some(&0));
        assert_eq!(provenance.get_offset(copy), None);
        assert_eq!(provenance.get_offset(movz), Some(0));
        assert_eq!(provenance.get_offset(ret), Some(4));
        assert_eq!(provenance.num_encoded(), 2);

        provenance.build_transitive();
        assert_eq!(provenance.query_offset(trust_cg_ir::TrustIrInstId(0)), None);
        assert_eq!(
            provenance.query_offset(trust_cg_ir::TrustIrInstId(1)),
            Some(&[0][..])
        );
        assert_eq!(
            provenance.query_offset(trust_cg_ir::TrustIrInstId(2)),
            Some(&[4][..])
        );
    }

    #[test]
    fn provenance_line_entries_use_encoded_offsets() {
        let sig = IrSignature::new(vec![], vec![Type::I64]);
        let mut func = IrMachFunction::new("debug_line_provenance".to_string(), sig);
        let entry = func.entry;

        let copy = func.push_inst(
            IrMachInst::new(
                IrOpcode::Copy,
                vec![IrOperand::PReg(X0), IrOperand::PReg(X1)],
            )
            .with_source_loc(trust_cg_ir::SourceLoc {
                file: 0,
                line: 10,
                col: 1,
            }),
        );
        let movz = func.push_inst(IrMachInst::new(
            IrOpcode::Movz,
            vec![IrOperand::PReg(X0), IrOperand::Imm(42)],
        ));
        func.append_inst(entry, copy);
        func.append_inst(entry, movz);

        let trust_ir_id = trust_cg_ir::TrustIrInstId(7);
        let mut provenance = trust_cg_ir::ProvenanceMap::new();
        provenance.record_lowering(trust_ir_id, &[movz], trust_cg_ir::PassId::new("test-isel"));
        provenance.record_encoding(movz, 0);
        provenance.build_transitive();

        let mut trust_ir_source_locs = BTreeMap::new();
        trust_ir_source_locs.insert(
            trust_ir_id,
            trust_cg_ir::SourceLoc {
                file: 0,
                line: 42,
                col: 9,
            },
        );

        let entries = build_source_line_entries(&func, Some((&provenance, &trust_ir_source_locs)));

        assert_eq!(entries.len(), 1);
        assert_eq!(entries[0].address, 0);
        assert_eq!(entries[0].line, 42);
        assert_eq!(entries[0].column, 9);
        assert!(entries[0].is_stmt);
    }

    #[test]
    fn debug_line_entries_mark_only_consecutive_line_starts_as_statements() {
        let sig = IrSignature::new(vec![], vec![Type::I64]);
        let mut func = IrMachFunction::new("debug_line_statement_rows".to_string(), sig);
        let entry = func.entry;

        for (line, col) in [(42, 9), (42, 13), (42, 17), (43, 9)] {
            let inst = func.push_inst(
                IrMachInst::new(IrOpcode::Movz, vec![IrOperand::PReg(X0), IrOperand::Imm(1)])
                    .with_source_loc(trust_cg_ir::SourceLoc { file: 0, line, col }),
            );
            func.append_inst(entry, inst);
        }

        let entries = build_source_line_entries(&func, None);
        let statement_rows = entries
            .iter()
            .map(|entry| (entry.line, entry.column, entry.is_stmt))
            .collect::<Vec<_>>();

        assert_eq!(
            statement_rows,
            vec![
                (42, 9, true),
                (42, 13, false),
                (42, 17, false),
                (43, 9, true)
            ]
        );
    }

    #[test]
    fn bounded_dwarf_param_location_uses_entry_range_until_first_clobber() {
        let sig = IrSignature::new(vec![Type::I64], vec![Type::I64]);
        let mut func = IrMachFunction::new("debug_param_scope".to_string(), sig);
        let entry = func.entry;

        let use_x0 = func.push_inst(IrMachInst::new(
            IrOpcode::AddRR,
            vec![
                IrOperand::PReg(X1),
                IrOperand::PReg(X0),
                IrOperand::PReg(X2),
            ],
        ));
        let clobber_x0 = func.push_inst(IrMachInst::new(
            IrOpcode::Movz,
            vec![IrOperand::PReg(X0), IrOperand::Imm(0)],
        ));
        func.append_inst(entry, use_x0);
        func.append_inst(entry, clobber_x0);

        assert_eq!(
            bounded_dwarf_param_location(&func, &ArgLocation::Reg(X0), None, 8),
            crate::dwarf_info::VariableLocation::location_list(
                0,
                4,
                crate::dwarf_info::VariableLocation::Register(0)
            )
        );
    }

