    fn debug_test_layout(uses_frame_pointer: bool, csa: u32) -> crate::frame::FrameLayout {
        crate::frame::FrameLayout {
            callee_saved_pairs: Vec::new(),
            callee_saved_area_size: csa,
            spill_area_size: 0,
            local_area_size: 0,
            outgoing_arg_area_size: 0,
            total_frame_size: csa,
            uses_frame_pointer,
            is_leaf: false,
            uses_red_zone: false,
            fp_to_spill_offset: -(csa as i32 - 16),
            has_dynamic_alloc: false,
        }
    }

    #[test]
    fn stack_argument_debug_location_is_cfa_relative() {
        use crate::dwarf_info::VariableLocation;
        let arg = ArgLocation::Stack { offset: 8, size: 8 };
        // X29 = CFA - 16 whatever the callee-saved area size, so the second
        // stack slot (CFA + 8) is X29 + 24, not X29 + csa + 8.
        for csa in [16, 48, 96] {
            assert_eq!(
                dwarf_param_location(&arg, Some(&debug_test_layout(true, csa))),
                VariableLocation::FrameOffset(24),
                "csa {csa}"
            );
        }
        assert_eq!(
            dwarf_param_location(&arg, Some(&debug_test_layout(false, 0))),
            VariableLocation::RegOffset(31, 8),
            "a frameless function keeps SP at the CFA"
        );
        assert_eq!(
            dwarf_param_location(&arg, None),
            VariableLocation::LocationList(Vec::new()),
            "no layout, no claimed location"
        );
    }

    fn debug_fp_function(with_frame: bool) -> IrMachFunction {
        use trust_cg_ir::regs::{SpecialReg, X29, X30};
        let sig = IrSignature::new(vec![], vec![Type::I64]);
        let mut func = IrMachFunction::new("debug_fp_ranges".to_string(), sig);
        let entry = func.entry;
        let sp = || IrOperand::Special(SpecialReg::SP);
        let mut insts = Vec::new();
        if with_frame {
            insts.push(IrMachInst::new(
                IrOpcode::StpPreIndex,
                vec![
                    IrOperand::PReg(X29),
                    IrOperand::PReg(X30),
                    sp(),
                    IrOperand::Imm(-16),
                ],
            )); // 0
            insts.push(IrMachInst::new(
                IrOpcode::AddRI,
                vec![IrOperand::PReg(X29), sp(), IrOperand::Imm(0)],
            )); // 4
        }
        insts.push(IrMachInst::new(
            IrOpcode::Movz,
            vec![IrOperand::PReg(X0), IrOperand::Imm(1)],
        ));
        if with_frame {
            insts.push(IrMachInst::new(
                IrOpcode::LdpPostIndex,
                vec![
                    IrOperand::PReg(X29),
                    IrOperand::PReg(X30),
                    sp(),
                    IrOperand::Imm(16),
                ],
            )); // 12
        }
        insts.push(IrMachInst::new(IrOpcode::Ret, vec![]));
        for inst in insts {
            let id = func.push_inst(inst);
            func.append_inst(entry, id);
        }
        func
    }

    #[test]
    fn frame_base_locations_cover_only_frame_pointer_code() {
        use crate::dwarf_info::{LocationListEntry, VariableLocation};
        let func = debug_fp_function(true);
        // X29 is set by the instruction at 4 and reloaded by the one at 12,
        // which still executes with the old value.
        let ranges = frame_pointer_valid_ranges(&func);
        assert_eq!(ranges, vec![(8, 16)]);

        let fbreg = VariableLocation::FrameOffset(-8);
        let expected_entry = LocationListEntry::from_location(8, 8, &fbreg);
        assert_eq!(
            clip_frame_base_location(fbreg.clone(), &ranges).unwrap(),
            VariableLocation::LocationList(vec![expected_entry.clone()])
        );
        let register = LocationListEntry::from_location(0, 20, &VariableLocation::Register(3));
        let mixed = VariableLocation::LocationList(vec![
            LocationListEntry::from_location(0, 20, &fbreg),
            register.clone(),
        ]);
        assert_eq!(
            clip_frame_base_location(mixed, &ranges).unwrap(),
            VariableLocation::LocationList(vec![register, expected_entry]),
            "register ranges are kept; frame-base ranges are clipped"
        );

        // A frameless function never sets X29: no frame-base location holds.
        let frameless = debug_fp_function(false);
        let ranges = frame_pointer_valid_ranges(&frameless);
        assert!(ranges.is_empty());
        assert_eq!(
            clip_frame_base_location(fbreg, &ranges).unwrap(),
            VariableLocation::LocationList(Vec::new())
        );
    }

