    #[cfg(feature = "verify")]
    #[test]
    fn aarch64_macho_branch26_and_unsigned_relocation_inventory_promotes() {
        use trust_cg_verify::{
            ObjectProofBinding, ObjectRelocationInventoryReport, ObjectRelocationKind,
            ObjectRelocationProofRegistry, RelocationInventoryStatus,
        };

        // (A) A direct call (`Bl symbol`) emits an `ARM64_RELOC_BRANCH26` row.
        // The row cites the aarch64_macho_call_reloc_proofs lane and the
        // report is built under the default-Enforce ENC-9 reparse binding —
        // the Certified composition (lane + container-bound reparse) —
        // so the inventory PROMOTES.
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("main".to_string(), sig);
        append_framed_external_call(&mut func, "printf");

        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-apple-darwin".to_string(),
            ..Default::default()
        });
        let report = pipeline
            .module_relocation_inventory_report(&[func], "macho.o")
            .expect("inventory report is produced for Mach-O symbolic fixups")
            .expect("AArch64 Mach-O target yields a report");

        assert!(
            report.is_promotable(),
            "BRANCH26 is lane-covered and ENC-9 bound; it must promote: {report:?}"
        );
        assert!(
            report
                .entries
                .iter()
                .any(|e| e.kind == ObjectRelocationKind::AArch64MachOBranch26),
            "BRANCH26 row must be present: {report:?}"
        );
        assert!(
            report
                .entries
                .iter()
                .all(|entry| { entry.status == RelocationInventoryStatus::Verified })
        );
        assert!(report.promotion_rejection_reason().is_none());

        // (B) An `ARM64_RELOC_UNSIGNED` row (absolute pointer slot) is now in
        // the production registry (aarch64_macho_data_reloc_proofs lane), but
        // a registry row alone is Trusted, not Certified: UNBOUND it stays
        // fail-closed (the 54762bc4 doctrine), and it promotes only under the
        // ENC-9 reparse-enforced binding.
        let registry = ObjectRelocationProofRegistry::aarch64_macho_production();
        let unbound = ObjectRelocationInventoryReport::from_emitted_kinds_with_registry(
            "macho.o",
            [ObjectRelocationKind::AArch64MachOUnsigned],
            &registry,
        );
        assert!(
            !unbound.is_promotable(),
            "a lane-covered but UNBOUND UNSIGNED row must stay fail-closed: {unbound:?}"
        );
        assert!(
            unbound
                .promotion_rejection_reason()
                .is_some_and(|r| r.contains("lacks an independent reparse binding"))
        );
        let bound = ObjectRelocationInventoryReport::from_emitted_kinds_with_registry_and_binding(
            "macho.o",
            [ObjectRelocationKind::AArch64MachOUnsigned],
            &registry,
            ObjectProofBinding::MachOReparseEnforced,
        );
        assert!(
            bound.is_promotable(),
            "a lane-covered, ENC-9-bound UNSIGNED row must promote: {bound:?}"
        );
        assert!(bound.entries.iter().all(|e| {
            e.kind == ObjectRelocationKind::AArch64MachOUnsigned
                && e.status == RelocationInventoryStatus::Verified
        }));
    }

    #[cfg(feature = "verify")]
    #[test]
    fn aarch64_macho_adrp_add_global_inventory_promotes() {
        // An ADRP + ADD pair addressing a local global emits the PAGE21 +
        // PAGEOFF12 rows. Both cite the aarch64_macho_data_reloc_proofs lane
        // and the report is built under the default-Enforce ENC-9 reparse
        // binding, so the inventory PROMOTES (the Certified composition).
        use trust_cg_ir::regs::X0;

        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("read_global".to_string(), sig);

        // ADRP x0, _G@PAGE
        let adrp = IrMachInst::new(
            IrOpcode::Adrp,
            vec![IrOperand::PReg(X0), IrOperand::Symbol("_G".to_string())],
        );
        // ADD x0, x0, _G@PAGEOFF
        let add = IrMachInst::new(
            IrOpcode::AddPCRel,
            vec![
                IrOperand::PReg(X0),
                IrOperand::PReg(X0),
                IrOperand::Symbol("_G".to_string()),
            ],
        );
        let ret = IrMachInst::new(IrOpcode::Ret, vec![]);
        let adrp_id = func.push_inst(adrp);
        let add_id = func.push_inst(add);
        let ret_id = func.push_inst(ret);
        func.append_inst(func.entry, adrp_id);
        func.append_inst(func.entry, add_id);
        func.append_inst(func.entry, ret_id);

        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-apple-darwin".to_string(),
            ..Default::default()
        });
        let report = pipeline
            .module_relocation_inventory_report(&[func], "macho.o")
            .expect("inventory report is produced")
            .expect("AArch64 Mach-O target yields a report");

        assert!(
            report.is_promotable(),
            "the lane-covered, ENC-9-bound PAGE21/PAGEOFF12 pair must promote: {report:?}"
        );
        assert!(report.promotion_rejection_reason().is_none());
        let kinds: Vec<_> = report.entries.iter().map(|e| e.kind).collect();
        assert!(
            kinds.contains(&trust_cg_verify::ObjectRelocationKind::AArch64MachOPage21),
            "expected a PAGE21 row: {report:?}"
        );
        assert!(
            kinds.contains(&trust_cg_verify::ObjectRelocationKind::AArch64MachOPageoff12),
            "expected a PAGEOFF12 row: {report:?}"
        );
        for entry in &report.entries {
            assert_eq!(
                entry.status,
                trust_cg_verify::RelocationInventoryStatus::Verified,
                "every emitted page-pair row must be Verified under the composition: {entry:?}"
            );
        }
    }

    #[cfg(feature = "verify")]
    #[test]
    fn aarch64_macho_production_inventory_matches_all_serialized_relocation_rows() {
        use trust_cg_verify::ObjectRelocationKind;

        let make_ret = |name: &str| {
            let mut func = IrMachFunction::new(name.to_string(), IrSignature::new(vec![], vec![]));
            let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
            func.append_inst(func.entry, ret);
            func
        };
        let functions = vec![make_ret("main"), make_ret("dynamic_frame")];
        let globals = vec![
            ObjectGlobal {
                name: "FN_SLOT".to_string(),
                data: vec![0; 8],
                mutable: true,
                is_external: true,
                symbol_refs: vec![GlobalSymbolRef {
                    offset: 0,
                    symbol: "main".to_string(),
                    addend: 0,
                }],
                is_thread_local: false,
                is_import: false,
                is_weak: false,
                align: 8,
                visibility: trust_ir::Visibility::Default,
                retained: false,
                section: None,
                comdat: false,
            },
            ObjectGlobal {
                name: "TLS_BYTES".to_string(),
                data: vec![1, 2, 3, 4],
                mutable: true,
                is_external: true,
                symbol_refs: vec![],
                is_thread_local: true,
                is_import: false,
                is_weak: false,
                align: 4,
                visibility: trust_ir::Visibility::Default,
                retained: false,
                section: None,
                comdat: false,
            },
        ];
        let layouts = vec![
            Some(test_frame_layout_fp_frame()),
            Some(test_frame_layout_dynamic()),
        ];
        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-apple-darwin".to_string(),
            ..Default::default()
        });

        let object = pipeline
            .compile_module_with_globals_and_layouts(&functions, &globals, &layouts)
            .expect("production Mach-O object should emit");
        let parsed = crate::macho::linker::MachOParser::parse(&object)
            .expect("production Mach-O object should parse");
        let mut actual: Vec<ObjectRelocationKind> = parsed
            .sections
            .iter()
            .flat_map(|section| section.relocations.iter())
            .map(|relocation| aarch64_macho_object_relocation_kind(relocation.kind))
            .collect();

        let report = pipeline
            .module_relocation_inventory_report_with_object_state(
                &functions,
                &globals,
                &layouts,
                "production.o",
            )
            .expect("production inventory should be generated")
            .expect("AArch64 Mach-O has a relocation inventory");
        let mut inventoried: Vec<ObjectRelocationKind> =
            report.entries.iter().map(|entry| entry.kind).collect();

        actual.sort_unstable();
        inventoried.sort_unstable();
        assert_eq!(
            inventoried, actual,
            "the production object report must inventory every serialized relocation row exactly"
        );
        crosscheck_aarch64_macho_relocation_inventory_digest(&object, &inventoried)
            .expect("the production digest must agree with the emitted object");
        assert_eq!(
            actual
                .iter()
                .filter(|kind| **kind == ObjectRelocationKind::AArch64MachOUnsigned)
                .count(),
            6,
            "data + TLS descriptors + compact unwind + fallback FDE unsigned rows"
        );
        assert_eq!(
            actual
                .iter()
                .filter(|kind| **kind == ObjectRelocationKind::AArch64MachOSubtractor)
                .count(),
            1,
            "the dynamic frame's fallback FDE emits one subtractor row"
        );
        // Every serialized kind (UNSIGNED, SUBTRACTOR) is lane-covered and
        // the report is built under the default-Enforce ENC-9 reparse
        // binding, so the production inventory now PROMOTES with every row
        // Verified. (The inventory==serialized sensor above remains the
        // unsound-under-report guard.)
        assert!(
            report.is_promotable(),
            "lane-covered, ENC-9-bound production inventory must promote: {report:?}"
        );
        assert!(
            report
                .entries
                .iter()
                .all(|entry| entry.status == trust_cg_verify::RelocationInventoryStatus::Verified)
        );
    }

    /// An AArch64 Mach-O module whose object carries every production row
    /// family: a `__text` BRANCH26 call, a `__DATA,__data` pointer slot, the
    /// two `__thread_vars` descriptor rows, a compact-unwind entry per
    /// function, and the DWARF-fallback FDE's SUBTRACTOR+UNSIGNED pair in
    /// `__eh_frame`. Returns the inventory's kinds and the object, after
    /// requiring the production digest to accept them.
    #[cfg(feature = "verify")]
    fn aarch64_macho_digest_fixture() -> (Vec<trust_cg_verify::ObjectRelocationKind>, Vec<u8>) {
        let mut caller =
            IrMachFunction::new("caller".to_string(), IrSignature::new(vec![], vec![]));
        append_framed_external_call(&mut caller, "printf");
        let mut dynamic = IrMachFunction::new(
            "dynamic_frame".to_string(),
            IrSignature::new(vec![], vec![]),
        );
        let ret = dynamic.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
        dynamic.append_inst(dynamic.entry, ret);
        let functions = vec![caller, dynamic];
        let global =
            |name: &str, data: Vec<u8>, symbol_refs, is_thread_local, align| ObjectGlobal {
                name: name.to_string(),
                data,
                mutable: true,
                is_external: true,
                symbol_refs,
                is_thread_local,
                is_import: false,
                is_weak: false,
                align,
                visibility: trust_ir::Visibility::Default,
                retained: false,
                section: None,
                comdat: false,
            };
        let globals = vec![
            global(
                "FN_SLOT",
                vec![0; 8],
                vec![GlobalSymbolRef {
                    offset: 0,
                    symbol: "caller".to_string(),
                    addend: 0,
                }],
                false,
                8,
            ),
            global("TLS_BYTES", vec![1, 2, 3, 4], vec![], true, 4),
        ];
        let layouts = vec![
            Some(test_frame_layout_fp_frame()),
            Some(test_frame_layout_dynamic()),
        ];
        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-apple-darwin".to_string(),
            ..Default::default()
        });
        let object = pipeline
            .compile_module_with_globals_and_layouts(&functions, &globals, &layouts)
            .expect("the digest fixture must emit");
        let report = pipeline
            .module_relocation_inventory_report_with_object_state(
                &functions, &globals, &layouts, "digest.o",
            )
            .expect("the digest fixture's inventory must be generated")
            .expect("AArch64 Mach-O has a relocation inventory");
        let kinds: Vec<_> = report.entries.iter().map(|entry| entry.kind).collect();
        crosscheck_aarch64_macho_relocation_inventory_digest(&object, &kinds)
            .expect("the production digest must agree with the emitted object");
        (kinds, object)
    }

    /// File offset and record count of Mach-O section `sectname`'s relocation
    /// table, read straight off the load commands (test-side mutation aid).
    #[cfg(feature = "verify")]
    fn macho_section_reloc_table(object: &[u8], sectname: &[u8]) -> (usize, usize) {
        let rd = |off: usize| {
            u32::from_le_bytes(object[off..off + 4].try_into().expect("4 bytes")) as usize
        };
        let mut command = 32;
        for _ in 0..rd(16) {
            if rd(command) == 0x19 {
                for index in 0..rd(command + 64) {
                    let section = command + 72 + index * 80;
                    let name = &object[section..section + 16];
                    let len = name.iter().position(|b| *b == 0).unwrap_or(16);
                    if &name[..len] == sectname {
                        return (rd(section + 56), rd(section + 60));
                    }
                }
            }
            command += rd(command + 4);
        }
        panic!("section {} not found", String::from_utf8_lossy(sectname));
    }

    /// Rewrite the second word (`r_symbolnum:24 r_pcrel:1 r_length:2
    /// r_extern:1 r_type:4`) of relocation record `index` in `sectname`.
    #[cfg(feature = "verify")]
    fn mutate_macho_reloc_word(
        object: &mut [u8],
        sectname: &[u8],
        index: usize,
        mutate: impl FnOnce(u32) -> u32,
    ) {
        let (reloff, nreloc) = macho_section_reloc_table(object, sectname);
        assert!(index < nreloc, "record {index} out of {nreloc}");
        let word = reloff + index * 8 + 4;
        let value = u32::from_le_bytes(object[word..word + 4].try_into().unwrap());
        object[word..word + 4].copy_from_slice(&mutate(value).to_le_bytes());
    }

    #[cfg(feature = "verify")]
    fn macho_reloc_type(word: u32) -> u8 {
        (word >> 28) as u8
    }

    /// The Mach-O artifact digest refuses an inventory that under- or
    /// over-reports the emitted rows and bytes that are not an ARM64 Mach-O
    /// object, and its raw-type mapping agrees with the emitter mapping.
    #[cfg(feature = "verify")]
    #[test]
    fn aarch64_macho_relocation_digest_refuses_under_and_over_reported_inventories() {
        use crate::macho::AArch64RelocKind as K;
        use trust_cg_verify::ObjectRelocationKind as O;
        let (kinds, object) = aarch64_macho_digest_fixture();
        let refused = |bytes: &[u8], inventory: &[O], what: &str| {
            assert!(
                matches!(
                    crosscheck_aarch64_macho_relocation_inventory_digest(bytes, inventory),
                    Err(PipelineError::RelocationInventoryDigest(_))
                ),
                "{what}"
            );
        };

        let mut under = kinds.clone();
        let unsigned = under
            .iter()
            .rposition(|kind| *kind == O::AArch64MachOUnsigned)
            .unwrap();
        under.remove(unsigned);
        refused(&object, &under, "an under-reporting inventory");
        let mut over = kinds.clone();
        over.push(O::AArch64MachOUnsigned);
        refused(&object, &over, "an over-reporting inventory");
        refused(
            b"not a mach-o",
            &kinds,
            "bytes that are not a Mach-O object",
        );
        let mut x86 = crate::macho::MachOWriter::for_target(crate::macho::MachOTarget::X86_64);
        x86.add_text_section(&[0xC3]);
        let x86 = x86.write().expect("an x86-64 Mach-O object must emit");
        refused(&x86, &[], "an x86-64 Mach-O object");

        for kind in [
            K::Unsigned,
            K::Subtractor,
            K::Branch26,
            K::Page21,
            K::Pageoff12,
            K::GotLoadPage21,
            K::GotLoadPageoff12,
            K::PointerToGot,
            K::TlvpLoadPage21,
            K::TlvpLoadPageoff12,
            K::Addend,
            K::AuthenticatedPointer,
        ] {
            assert_eq!(
                aarch64_macho_kind_from_r_type(kind as u8),
                aarch64_macho_object_relocation_kind(kind),
                "{kind:?}"
            );
        }
    }

    /// An object whose relocation table carries a kind the inventory did not
    /// enumerate is refused even when the row COUNT still agrees, and an
    /// inventory that truthfully names the foreign kind still cannot promote.
    #[cfg(feature = "verify")]
    #[test]
    fn aarch64_macho_relocation_digest_refuses_an_unenumerated_relocation_kind() {
        use trust_cg_verify::ObjectRelocationKind as O;
        let (kinds, object) = aarch64_macho_digest_fixture();
        let (_, compact_rows) = macho_section_reloc_table(&object, b"__compact_unwind");
        assert_eq!(compact_rows, 2, "one function pointer per function");

        // UNSIGNED -> ARM64_RELOC_AUTHENTICATED_POINTER (11), same 8-byte shape.
        let mut foreign = object.clone();
        mutate_macho_reloc_word(&mut foreign, b"__compact_unwind", 1, |word| {
            assert_eq!(
                macho_reloc_type(word),
                0,
                "compact-unwind rows are UNSIGNED"
            );
            (word & 0x0FFF_FFFF) | (11 << 28)
        });
        let error = crosscheck_aarch64_macho_relocation_inventory_digest(&foreign, &kinds)
            .expect_err("an unenumerated relocation kind in the object must refuse");
        assert!(
            matches!(&error, PipelineError::RelocationInventoryDigest(message)
                if message.contains("AArch64MachOOther(11)")),
            "{error}"
        );

        // UNSIGNED -> POINTER_TO_GOT (7) in its own 4-byte pc-relative shape.
        let mut got = object.clone();
        mutate_macho_reloc_word(&mut got, b"__compact_unwind", 0, |word| {
            (word & 0x00FF_FFFF) | (1 << 24) | (2 << 25) | (1 << 27) | (7 << 28)
        });
        assert!(matches!(
            crosscheck_aarch64_macho_relocation_inventory_digest(&got, &kinds),
            Err(PipelineError::RelocationInventoryDigest(_))
        ));

        // The digest accepts an inventory that names the foreign row truthfully,
        // but that row has no value-proof lane: the report never promotes.
        let mut truthful = kinds.clone();
        let replaced = truthful
            .iter()
            .position(|kind| *kind == O::AArch64MachOUnsigned)
            .unwrap();
        truthful[replaced] = O::AArch64MachOOther(11);
        crosscheck_aarch64_macho_relocation_inventory_digest(&foreign, &truthful)
            .expect("a truthful inventory matches the object");
        let registry = trust_cg_verify::ObjectRelocationProofRegistry::aarch64_macho_production();
        let named = trust_cg_verify::ObjectRelocationInventoryReport::from_emitted_kinds_with_registry_and_binding(
            "foreign.o",
            truthful,
            &registry,
            trust_cg_verify::ObjectProofBinding::MachOReparseEnforced,
        );
        assert!(!named.is_promotable(), "{named:?}");
        let uncovered = named.uncovered_relocations();
        assert_eq!(uncovered.len(), 1, "{named:?}");
        assert_eq!(uncovered[0].kind, O::AArch64MachOOther(11));
    }

    /// The digest binds lane credit to the record semantics the lanes model:
    /// a covered kind in the wrong `r_pcrel`/`r_length` shape, or a SUBTRACTOR
    /// that is not immediately followed by its UNSIGNED minuend, is refused
    /// although the kind multiset is unchanged.
    #[cfg(feature = "verify")]
    #[test]
    fn aarch64_macho_relocation_digest_binds_record_shape_and_subtractor_pairing() {
        let (kinds, object) = aarch64_macho_digest_fixture();
        let refused = |bytes: &[u8], what: &str, reason: &str| {
            let error = crosscheck_aarch64_macho_relocation_inventory_digest(bytes, &kinds)
                .expect_err(what);
            assert!(
                matches!(&error, PipelineError::RelocationInventoryDigest(message)
                    if message.contains(reason)),
                "{what}: {error}"
            );
        };

        let mut pcrel_unsigned = object.clone();
        mutate_macho_reloc_word(&mut pcrel_unsigned, b"__compact_unwind", 0, |w| {
            w | (1 << 24)
        });
        refused(
            &pcrel_unsigned,
            "a pc-relative UNSIGNED is not the proved abs64 row",
            "value-proof lane",
        );

        let mut short_unsigned = object.clone();
        mutate_macho_reloc_word(&mut short_unsigned, b"__data", 0, |w| {
            (w & !(3 << 25)) | (2 << 25)
        });
        refused(
            &short_unsigned,
            "a 4-byte UNSIGNED is not the proved abs64 row",
            "value-proof lane",
        );

        let (_, text_rows) = macho_section_reloc_table(&object, b"__text");
        assert_eq!(text_rows, 1, "the call is the only __text row");
        let mut absolute_branch = object.clone();
        mutate_macho_reloc_word(&mut absolute_branch, b"__text", 0, |w| {
            assert_eq!(macho_reloc_type(w), 2, "the call is BRANCH26");
            w & !(1 << 24)
        });
        refused(
            &absolute_branch,
            "an absolute BRANCH26 is not the proved pc-relative row",
            "value-proof lane",
        );

        // Swap the DWARF-fallback FDE's SUBTRACTOR+UNSIGNED records: same
        // multiset, UNSIGNED first.
        let (reloff, nreloc) = macho_section_reloc_table(&object, b"__eh_frame");
        let types: Vec<u8> = (0..nreloc)
            .map(|index| {
                let word = reloff + index * 8 + 4;
                macho_reloc_type(u32::from_le_bytes(
                    object[word..word + 4].try_into().unwrap(),
                ))
            })
            .collect();
        let subtractor = types
            .iter()
            .position(|kind| *kind == 1)
            .expect("__eh_frame carries a SUBTRACTOR+UNSIGNED pair");
        assert_eq!(types[subtractor + 1], 0, "{types:?}");
        let mut swapped = object.clone();
        let first = reloff + subtractor * 8;
        let (head, tail) = swapped.split_at_mut(first + 8);
        head[first..first + 8].swap_with_slice(&mut tail[..8]);
        refused(
            &swapped,
            "a SUBTRACTOR without its immediately following UNSIGNED must refuse",
            "minuend",
        );
    }

    /// `ARM64_RELOC_ADDEND` is a prefix record, not an inventory row: it folds
    /// into the BRANCH26/PAGE21/PAGEOFF12 row it modifies, and an ADDEND whose
    /// partner is missing, displaced, or of a kind the resolver never pairs it
    /// with is refused.
    #[cfg(feature = "verify")]
    #[test]
    fn aarch64_macho_relocation_digest_folds_addend_prefix_records_into_their_row() {
        use crate::macho::AArch64RelocKind as K;
        use crate::macho::reloc::{Relocation, create_addend_pair};
        use trust_cg_verify::ObjectRelocationKind as O;

        let mut writer = crate::macho::MachOWriter::new();
        writer.add_text_section(&[0x1F, 0x20, 0x03, 0xD5].repeat(3));
        writer.add_symbol("_start", 1, 0, true).unwrap();
        writer.add_symbol("_ext", 0, 0, true).unwrap();
        let (addend, branch) = create_addend_pair(0, 1, K::Branch26, 8);
        writer.add_relocation(0, addend).unwrap();
        writer.add_relocation(0, branch).unwrap();
        let (addend, page) = create_addend_pair(4, 1, K::Page21, 0x10);
        writer.add_relocation(0, addend).unwrap();
        writer.add_relocation(0, page).unwrap();
        writer
            .add_relocation(0, Relocation::pageoff12(8, 1))
            .unwrap();
        let object = writer.write().expect("the addend object must emit");
        let (_, text_rows) = macho_section_reloc_table(&object, b"__text");
        assert_eq!(text_rows, 5, "two ADDEND prefixes + three fixup rows");

        let rows = [
            O::AArch64MachOBranch26,
            O::AArch64MachOPage21,
            O::AArch64MachOPageoff12,
        ];
        crosscheck_aarch64_macho_relocation_inventory_digest(&object, &rows)
            .expect("ADDEND prefixes fold into their rows");
        let mut with_addend_row = rows.to_vec();
        with_addend_row.push(O::AArch64MachOOther(10));
        assert!(
            crosscheck_aarch64_macho_relocation_inventory_digest(&object, &with_addend_row)
                .is_err(),
            "an ADDEND prefix is never an inventory row of its own"
        );

        // Displace the BRANCH26 partner: the first ADDEND is orphaned.
        let (reloff, _) = macho_section_reloc_table(&object, b"__text");
        let mut orphan = object.clone();
        orphan[reloff + 8..reloff + 12].copy_from_slice(&4u32.to_le_bytes());
        let error = crosscheck_aarch64_macho_relocation_inventory_digest(&orphan, &rows)
            .expect_err("an ADDEND without its same-address partner must refuse");
        assert!(error.to_string().contains("ARM64_RELOC_ADDEND"), "{error}");

        // Partner of a kind the resolver never prefixes (GOT_LOAD_PAGE21).
        let mut foreign_partner = object.clone();
        mutate_macho_reloc_word(&mut foreign_partner, b"__text", 1, |w| {
            assert_eq!(macho_reloc_type(w), 2);
            (w & 0x0FFF_FFFF) | (5 << 28)
        });
        let got_rows = [
            O::AArch64MachOGotLoadPage21,
            O::AArch64MachOPage21,
            O::AArch64MachOPageoff12,
        ];
        assert!(
            crosscheck_aarch64_macho_relocation_inventory_digest(&foreign_partner, &got_rows)
                .is_err(),
            "ADDEND may only prefix BRANCH26/PAGE21/PAGEOFF12"
        );

        // An ADDEND prefix that is itself extern is malformed.
        let mut extern_addend = object.clone();
        mutate_macho_reloc_word(&mut extern_addend, b"__text", 0, |w| {
            assert_eq!(macho_reloc_type(w), 10);
            w | (1 << 27)
        });
        assert!(
            crosscheck_aarch64_macho_relocation_inventory_digest(&extern_addend, &rows).is_err()
        );
    }

    #[cfg(feature = "verify")]
    #[test]
    fn aarch64_elf_production_inventory_includes_global_and_fde_rows() {
        use trust_cg_verify::{ObjectRelocationKind, RelocationInventoryStatus};

        let mut func = IrMachFunction::new("main".to_string(), IrSignature::new(vec![], vec![]));
        let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
        func.append_inst(func.entry, ret);
        let functions = vec![func];
        let globals = vec![ObjectGlobal {
            name: "FN_SLOT".to_string(),
            data: vec![0; 8],
            mutable: true,
            is_external: true,
            symbol_refs: vec![GlobalSymbolRef {
                offset: 0,
                symbol: "main".to_string(),
                addend: 0,
            }],
            is_thread_local: false,
            is_import: false,
            is_weak: false,
            align: 8,
            visibility: trust_ir::Visibility::Default,
            retained: false,
            section: None,
            comdat: false,
        }];
        let layouts = vec![Some(test_frame_layout_fp_frame())];
        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-unknown-linux-gnu".to_string(),
            ..Default::default()
        });
        let report = pipeline
            .module_relocation_inventory_report_with_object_state(
                &functions,
                &globals,
                &layouts,
                "production.o",
            )
            .expect("production ELF inventory should be generated")
            .expect("AArch64 ELF has a relocation inventory");
        let kinds: Vec<_> = report.entries.iter().map(|entry| entry.kind).collect();
        assert_eq!(
            kinds
                .iter()
                .filter(|kind| **kind == ObjectRelocationKind::AArch64ElfAbs64)
                .count(),
            1
        );
        assert_eq!(
            kinds
                .iter()
                .filter(|kind| **kind == ObjectRelocationKind::AArch64ElfPrel32)
                .count(),
            1
        );
        // ABS64/PREL32 now carry the Certified composition: value-lane
        // registry rows (aarch64_elf_reloc_proofs) + the shared ELF reparse
        // binding (default Enforce).
        assert!(report.is_promotable(), "{report:?}");
        assert!(report.entries.iter().all(|entry| {
            matches!(
                entry.kind,
                ObjectRelocationKind::AArch64ElfAbs64 | ObjectRelocationKind::AArch64ElfPrel32
            ) && entry.status == RelocationInventoryStatus::Verified
        }));
    }

    #[cfg(feature = "verify")]
    #[test]
    fn aarch64_macho_debug_inventory_fails_closed_until_dwarf_rows_are_enumerated() {
        let mut func = IrMachFunction::new("main".to_string(), IrSignature::new(vec![], vec![]));
        let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
        func.append_inst(func.entry, ret);
        let functions = vec![func];
        let layouts = vec![Some(test_frame_layout_fp_frame())];
        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-apple-darwin".to_string(),
            emit_debug: true,
            ..Default::default()
        });
        let error = pipeline
            .module_relocation_inventory_report_with_object_state(
                &functions,
                &[],
                &layouts,
                "debug.o",
            )
            .expect_err("an incomplete DWARF relocation inventory must fail closed");
        assert!(
            matches!(error, PipelineError::ObjectRelocationInventoryIncomplete {
                ref object,
                ref reason,
            } if object == "debug.o"
                && reason.contains("DWARF")
                && reason.contains("ARM64_RELOC_UNSIGNED")
                && reason.contains("fail-closed")),
            "unexpected diagnostic: {error}"
        );
    }

    /// `ARM64_RELOC_UNSIGNED` adds the resolved address to the in-place
    /// bytes, so the emitter must write the declared implicit addend into
    /// every relocated slot, zero included: nonzero placeholder bytes left by
    /// a producer must not be silently added to the target address.
    #[test]
    fn aarch64_macho_zero_addend_erases_nonzero_pointer_placeholder() {
        let mut func = IrMachFunction::new(
            "pointer_target".to_string(),
            IrSignature::new(vec![], vec![]),
        );
        let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
        func.append_inst(func.entry, ret);
        let global = ObjectGlobal {
            name: "ADVERSARIAL_POINTER".to_string(),
            data: vec![0xA5; 8],
            mutable: true,
            is_external: false,
            symbol_refs: vec![GlobalSymbolRef {
                offset: 0,
                symbol: "pointer_target".to_string(),
                addend: 0,
            }],
            is_thread_local: false,
            is_import: false,
            is_weak: false,
            align: 8,
            visibility: trust_ir::Visibility::Default,
            retained: false,
            section: None,
            comdat: false,
        };
        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-apple-darwin".to_string(),
            ..Default::default()
        });

        let object = pipeline
            .compile_module_with_globals(&[func], &[global])
            .expect("AArch64 Mach-O pointer initializer should emit");
        let parsed = crate::macho::linker::MachOParser::parse(&object).expect("parse Mach-O");
        let data = parsed
            .sections
            .iter()
            .find(|section| section.name == "__data")
            .expect("missing __data");
        assert_eq!(
            data.data,
            vec![0; 8],
            "the declared zero implicit addend must replace placeholder bytes"
        );
        assert_eq!(data.relocations.len(), 1);
        assert_eq!(
            data.relocations[0].kind,
            crate::macho::reloc::AArch64RelocKind::Unsigned
        );
    }

