    /// A Mach-O thread-local whose initial-value template embeds symbol
    /// addresses relocates the `__DATA,__thread_data` template: one
    /// `ARM64_RELOC_UNSIGNED` per slot (an in-module function here, and an
    /// undefined external registered for the second slot), the addend baked
    /// into the slot, and the descriptor path untouched.
    #[test]
    fn aarch64_macho_tls_symbol_address_template_relocates_thread_data() {
        let mut func = IrMachFunction::new("main".to_string(), IrSignature::new(vec![], vec![]));
        let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
        func.append_inst(func.entry, ret);
        let globals = vec![ObjectGlobal {
            name: "TLS_PTR".to_string(),
            data: vec![0; 24],
            mutable: true,
            is_external: true,
            symbol_refs: vec![
                GlobalSymbolRef {
                    offset: 0,
                    symbol: "main".to_string(),
                    addend: 0,
                },
                GlobalSymbolRef {
                    offset: 16,
                    symbol: "external_target".to_string(),
                    addend: 24,
                },
            ],
            is_thread_local: true,
            is_import: false,
            is_weak: false,
            align: 8,
            visibility: trust_ir::Visibility::Default,
            retained: false,
            section: None,
            comdat: false,
        }];
        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-apple-darwin".to_string(),
            ..Default::default()
        });
        let object = pipeline
            .compile_module_with_globals(&[func], &globals)
            .expect("a relocated TLS template compiles on the AArch64 Mach-O path");
        let parsed = crate::macho::linker::MachOParser::parse(&object).expect("parse object");
        let thread_data = parsed
            .sections
            .iter()
            .find(|section| section.name == "__thread_data")
            .expect("__thread_data section");
        assert_eq!(
            thread_data.section_type(),
            crate::macho::constants::S_THREAD_LOCAL_REGULAR
        );
        assert_eq!(thread_data.data.len(), 24);
        assert_eq!(&thread_data.data[16..24], &24i64.to_le_bytes());
        assert_eq!(&thread_data.data[0..8], &[0u8; 8]);
        let mut targets: Vec<(u32, String)> = thread_data
            .relocations
            .iter()
            .map(|reloc| {
                assert_eq!(reloc.kind, crate::macho::reloc::AArch64RelocKind::Unsigned);
                assert!(reloc.is_extern && !reloc.pc_relative && reloc.length == 3);
                (
                    reloc.offset,
                    parsed.symbols[reloc.symbol_index as usize].name.to_string(),
                )
            })
            .collect();
        targets.sort();
        assert_eq!(
            targets,
            vec![
                (0, "_main".to_string()),
                (16, "_external_target".to_string())
            ]
        );
        let external = parsed
            .symbols
            .iter()
            .find(|symbol| symbol.name == "_external_target")
            .expect("undefined external registered for the template slot");
        assert!(external.is_undefined());
        // The descriptor path is unchanged: `_TLS_PTR` names the
        // `__thread_vars` descriptor and its two pointer relocations remain.
        let thread_vars = parsed
            .sections
            .iter()
            .find(|section| section.name == "__thread_vars")
            .expect("__thread_vars section");
        assert_eq!(thread_vars.relocations.len(), 2);
        #[cfg(feature = "verify")]
        {
            let inventory = pipeline
                .module_relocation_inventory_report_with_object_state(
                    &[{
                        let mut func = IrMachFunction::new(
                            "main".to_string(),
                            IrSignature::new(vec![], vec![]),
                        );
                        let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
                        func.append_inst(func.entry, ret);
                        func
                    }],
                    &globals,
                    &[],
                    "tls_template.o",
                )
                .expect("inventory report")
                .expect("Mach-O inventory");
            assert_eq!(
                inventory
                    .entries
                    .iter()
                    .filter(|entry| {
                        entry.kind == trust_cg_verify::ObjectRelocationKind::AArch64MachOUnsigned
                    })
                    .count(),
                4,
                "two template slots plus the two descriptor pointers"
            );
        }
    }

    /// The thread-local of the ELF template twins: an ALL-ZERO 24-byte
    /// template with a slot for an in-module function at 0 and one for an
    /// undefined external (+24) at 16.
    fn elf_tls_template_twin_global() -> ObjectGlobal {
        ObjectGlobal {
            name: "TLS_PTR".to_string(),
            data: vec![0; 24],
            mutable: true,
            is_external: true,
            symbol_refs: vec![
                GlobalSymbolRef {
                    offset: 0,
                    symbol: "main".to_string(),
                    addend: 0,
                },
                GlobalSymbolRef {
                    offset: 16,
                    symbol: "external_target".to_string(),
                    addend: 24,
                },
            ],
            is_thread_local: true,
            is_import: false,
            is_weak: false,
            align: 8,
            visibility: trust_ir::Visibility::Default,
            retained: false,
            section: None,
            comdat: false,
        }
    }

    /// The ELF twin of `aarch64_macho_tls_symbol_address_template_relocates_thread_data`:
    /// an AArch64 ELF thread-local whose template embeds symbol addresses
    /// stays a PROGBITS `.tdata` template even when its bytes are all zero
    /// (never `.tbss`, which has no bytes to relocate), and each slot is one
    /// `R_AARCH64_ABS64` in `.rela.tdata` with its addend in `r_addend`
    /// against an `STT_TLS`-free target (the undefined external is
    /// registered untyped). The certified inventory counts both rows.
    #[test]
    fn aarch64_elf_tls_symbol_address_template_relocates_tdata() {
        use crate::elf::constants::{
            SHF_ALLOC, SHF_TLS, SHF_WRITE, SHT_PROGBITS, STT_NOTYPE, STT_TLS,
        };
        let main = || {
            let mut func =
                IrMachFunction::new("main".to_string(), IrSignature::new(vec![], vec![]));
            let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
            func.append_inst(func.entry, ret);
            func
        };
        let globals = vec![elf_tls_template_twin_global()];
        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-unknown-linux-gnu".to_string(),
            ..Default::default()
        });
        let object = pipeline
            .compile_module_with_globals(&[main()], &globals)
            .expect("a relocated TLS template compiles on the AArch64 ELF path");
        let records = crate::elf::reparse::read_object_records(&object).expect("reparse ELF");
        assert!(
            records
                .sections
                .iter()
                .all(|section| section.name != ".tbss"),
            "a template with pointer slots is never zero-fill"
        );
        let (tdata_index, tdata) = records
            .sections
            .iter()
            .enumerate()
            .find(|(_, section)| section.name == ".tdata")
            .expect(".tdata section");
        assert_eq!(tdata.sh_type, SHT_PROGBITS);
        assert_eq!(tdata.sh_flags, SHF_ALLOC | SHF_WRITE | SHF_TLS);
        assert_eq!(elf_section_data(&object, ".tdata"), &[0u8; 24]);
        let holder = records
            .symbols
            .iter()
            .find(|symbol| symbol.name == "TLS_PTR")
            .expect("template symbol");
        assert_eq!(holder.symbol_type, STT_TLS);
        assert_eq!(usize::from(holder.section_index), tdata_index);
        let external = records
            .symbols
            .iter()
            .find(|symbol| symbol.name == "external_target")
            .expect("undefined external registered for the template slot");
        assert!(external.is_undefined_reference());
        assert_eq!(external.symbol_type, STT_NOTYPE);
        let mut slots: Vec<(u64, u32, String, i64)> = records
            .relocations
            .iter()
            .filter(|relocation| relocation.target_section == tdata_index)
            .map(|relocation| {
                (
                    relocation.record.r_offset,
                    relocation.record.reloc_type,
                    records.symbols[relocation.record.symbol_index as usize]
                        .name
                        .clone(),
                    relocation.record.r_addend,
                )
            })
            .collect();
        slots.sort();
        let abs64 = crate::elf::constants::R_AARCH64_ABS64;
        assert_eq!(
            slots,
            vec![
                (holder.value, abs64, "main".to_string(), 0),
                (holder.value + 16, abs64, "external_target".to_string(), 24),
            ],
            "every template slot relocates with its addend in r_addend"
        );
        assert!(
            find_elf_section_view(&object, ".rela.tdata").is_some(),
            "the slots relocate through .rela.tdata"
        );
        #[cfg(feature = "verify")]
        {
            let inventory = pipeline
                .module_relocation_inventory_report_with_object_state(
                    &[main()],
                    &globals,
                    &[],
                    "tls_template.o",
                )
                .expect("inventory report")
                .expect("ELF inventory");
            assert_eq!(
                inventory.entries.len(),
                records.relocations.len(),
                "the inventory names every relocation row the object carries"
            );
            assert_eq!(
                inventory
                    .entries
                    .iter()
                    .filter(|entry| {
                        entry.kind == trust_cg_verify::ObjectRelocationKind::AArch64ElfAbs64
                    })
                    .count(),
                2,
                "both .rela.tdata rows are inventoried, never dropped"
            );
        }
    }

    /// The ELF reparse gate binds `.rela.tdata` like any other relocation
    /// section: a template relocation record omitted from the bytes (the
    /// section shrunk by one record) or an altered addend fails the check
    /// against the writer's intent.
    #[test]
    fn aarch64_elf_tls_template_reparse_refuses_an_omitted_tdata_record() {
        let mut writer = crate::elf::ElfWriter::new(crate::elf::ElfMachine::AArch64);
        let text = writer.add_text_section(&[0xc0, 0x03, 0x5f, 0xd6]);
        let globals = vec![elf_tls_template_twin_global()];
        let rows = add_elf_global_sections(&mut writer, &globals).expect("placement");
        let mut symbols = Vec::new();
        for row in &rows {
            symbols.push((
                row.name.clone(),
                add_elf_global_row_symbol(&mut writer, row).unwrap(),
            ));
        }
        symbols.push((
            "main".to_string(),
            writer
                .add_checked_symbol(crate::elf::ElfSymbol {
                    name: "main".to_string(),
                    section: text,
                    value: 0,
                    size: 4,
                    is_global: true,
                    sym_type: crate::elf::constants::STT_FUNC,
                    is_weak: false,
                    visibility: crate::elf::constants::STV_DEFAULT,
                })
                .unwrap(),
        ));
        symbols.push((
            "external_target".to_string(),
            writer
                .add_checked_symbol(elf_undefined_symbol(
                    "external_target",
                    crate::elf::constants::STT_NOTYPE,
                    &ElfModuleSymbolPlan::legacy(),
                ))
                .unwrap(),
        ));
        let indices = final_elf_symbol_indices(&mut writer, &symbols).unwrap();
        add_aarch64_elf_global_relocations(&mut writer, &globals, &rows, &indices).unwrap();
        let bytes = writer.write_checked().unwrap();
        let intent = writer.reparse_object_intent();
        crate::elf::reparse::check_object(&intent, &bytes)
            .expect("the intact TLS template object matches its intent");

        let rela = find_elf_section_view(&bytes, ".rela.tdata").expect(".rela.tdata");
        assert_eq!(rela.size, 2 * crate::elf::constants::ELF64_RELA_SIZE as u64);
        let header = elf_section_header_offset(&bytes, ".rela.tdata");
        let mut omitted = bytes.clone();
        omitted[header + 32..header + 40].copy_from_slice(
            &(rela.size - crate::elf::constants::ELF64_RELA_SIZE as u64).to_le_bytes(),
        );
        assert_eq!(
            crate::elf::reparse::read_object_records(&omitted)
                .expect("the shrunk object stays readable")
                .relocations
                .len(),
            1
        );
        assert!(
            crate::elf::reparse::check_object(&intent, &omitted).is_err(),
            "an omitted .rela.tdata record must fail the reparse gate"
        );
        let mut readdended = bytes.clone();
        readdended[rela.offset as usize + crate::elf::constants::ELF64_RELA_SIZE + 16] ^= 0x08;
        assert!(
            crate::elf::reparse::check_object(&intent, &readdended).is_err(),
            "an altered template addend must fail the reparse gate"
        );
    }

    /// Byte offset of the named section's header, by an independent walk.
    fn elf_section_header_offset(bytes: &[u8], target_name: &str) -> usize {
        let index = elf_section_index(bytes, target_name).expect("section") as usize;
        read_elf_u64(bytes, 40) as usize + index * read_elf_u16(bytes, 58) as usize
    }

    /// A pointer slot whose TARGET is a declared thread-local is refused by
    /// name on both AArch64 object formats, from a template and from ordinary
    /// data, naming a definition or an import; the same slot naming a plain
    /// data global compiles.
    #[test]
    fn aarch64_pointer_slot_naming_a_thread_local_is_refused_by_name() {
        let main = || {
            let mut func =
                IrMachFunction::new("main".to_string(), IrSignature::new(vec![], vec![]));
            let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
            func.append_inst(func.entry, ret);
            func
        };
        let tls_definition = ObjectGlobal {
            name: "TLS_TARGET".to_string(),
            data: vec![7; 8],
            symbol_refs: vec![],
            ..elf_tls_template_twin_global()
        };
        let tls_import = ObjectGlobal {
            name: "TLS_IMPORT".to_string(),
            data: vec![],
            symbol_refs: vec![],
            is_import: true,
            ..elf_tls_template_twin_global()
        };
        let data_holder = |target: &str| ObjectGlobal {
            name: "DATA_PTR".to_string(),
            data: vec![0; 8],
            symbol_refs: vec![GlobalSymbolRef {
                offset: 0,
                symbol: target.to_string(),
                addend: 0,
            }],
            is_thread_local: false,
            ..elf_tls_template_twin_global()
        };
        let template_holder = |target: &str| ObjectGlobal {
            symbol_refs: vec![GlobalSymbolRef {
                offset: 8,
                symbol: target.to_string(),
                addend: 0,
            }],
            ..elf_tls_template_twin_global()
        };
        let cases = [
            ("TLS_PTR", 8, "TLS_TARGET", template_holder("TLS_TARGET")),
            ("TLS_PTR", 8, "TLS_IMPORT", template_holder("TLS_IMPORT")),
            ("TLS_PTR", 8, "TLS_PTR", template_holder("TLS_PTR")),
            ("DATA_PTR", 0, "TLS_TARGET", data_holder("TLS_TARGET")),
            ("DATA_PTR", 0, "TLS_IMPORT", data_holder("TLS_IMPORT")),
        ];
        for triple in ["aarch64-unknown-linux-gnu", "aarch64-apple-darwin"] {
            let pipeline = Pipeline::new(PipelineConfig {
                target_triple: triple.to_string(),
                ..Default::default()
            });
            for (holder, offset, target, global) in &cases {
                let globals = vec![tls_definition.clone(), tls_import.clone(), global.clone()];
                let error = pipeline
                    .compile_module_with_globals(&[main()], &globals)
                    .expect_err("a pointer slot naming a thread-local is refused");
                assert!(
                    matches!(error, PipelineError::ObjectEmission(ref reason) if
                        reason.starts_with("[TCG-TLS-SLOT-TARGET]")
                            && reason.contains(&format!("`{holder}`"))
                            && reason.contains(&format!("byte offset {offset}"))
                            && reason.contains(&format!("thread-local `{target}`"))
                            && reason.contains("fail-closed")),
                    "{triple} {holder}->{target}: unexpected diagnostic: {error}"
                );
            }
            // The same slots naming plain data compile.
            let plain = ObjectGlobal {
                name: "PLAIN".to_string(),
                is_thread_local: false,
                data: vec![1; 8],
                symbol_refs: vec![],
                ..elf_tls_template_twin_global()
            };
            let globals = vec![
                tls_definition.clone(),
                plain,
                template_holder("PLAIN"),
                ObjectGlobal {
                    name: "DATA_PTR".to_string(),
                    ..data_holder("PLAIN")
                },
            ];
            pipeline
                .compile_module_with_globals(&[main()], &globals)
                .unwrap_or_else(|error| panic!("{triple}: slots naming plain data: {error}"));
        }
    }

    #[test]
    fn aarch64_object_global_out_of_bounds_pointer_slot_returns_error() {
        let mut func = IrMachFunction::new("main".to_string(), IrSignature::new(vec![], vec![]));
        let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
        func.append_inst(func.entry, ret);
        let globals = vec![ObjectGlobal {
            name: "BROKEN_SLOT".to_string(),
            data: vec![0; 4],
            mutable: true,
            is_external: true,
            symbol_refs: vec![GlobalSymbolRef {
                offset: 0,
                symbol: "main".to_string(),
                addend: 0,
            }],
            is_thread_local: false,
            is_import: false,
            is_weak: false,
            align: 4,
            visibility: trust_ir::Visibility::Default,
            retained: false,
            section: None,
            comdat: false,
        }];
        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-apple-darwin".to_string(),
            ..Default::default()
        });
        let error = pipeline
            .compile_module_with_globals(&[func], &globals)
            .expect_err("an out-of-bounds pointer slot must be rejected, not panic");
        assert!(
            matches!(error, PipelineError::ObjectEmission(ref reason) if
                reason.contains("BROKEN_SLOT")
                    && reason.contains("exceeds its 4 initializer bytes")
                    && reason.contains("fail-closed")),
            "unexpected diagnostic: {error}"
        );
    }

    #[test]
    fn elf_tls_templates_preserve_declared_alignment_and_zero_padding() {
        for machine in [
            crate::elf::ElfMachine::AArch64,
            crate::elf::ElfMachine::X86_64,
        ] {
            let mut writer = crate::elf::ElfWriter::new(machine);
            let globals: Vec<_> = [
                ("small", vec![1, 2, 3], 1, false),
                ("aligned64", vec![4, 5, 6, 7, 8], 64, false),
                ("aligned128", vec![9, 10, 11], 128, false),
                ("tail", vec![12, 13], 2, false),
                ("import", vec![], 8192, true),
            ]
            .into_iter()
            .map(|(name, data, align, is_import)| ObjectGlobal {
                name: name.to_owned(),
                data,
                align,
                is_import,
                mutable: true,
                is_thread_local: true,
                is_external: true,
                is_weak: false,
                symbol_refs: vec![],
                visibility: trust_ir::Visibility::Default,
                retained: false,
                section: None,
                comdat: false,
            })
            .collect();
            let rows = add_elf_global_sections(&mut writer, &globals).expect("placement");
            assert_eq!(rows.len(), 4, "imports must not contribute TLS definitions");
            let mut expected = vec![0; 146];
            for ((global, row), offset) in globals.iter().zip(&rows).zip([0, 64, 128, 144]) {
                assert_eq!(row.name, global.name);
                assert_eq!(row.offset, offset as u64);
                assert_eq!(row.size, global.data.len() as u64);
                assert!(row.is_tls && row.is_external && !row.is_weak);
                expected[offset..offset + global.data.len()].copy_from_slice(&global.data);
            }
            let object = writer.write_checked().unwrap();
            let section = find_elf_section_view(&object, ".tdata").unwrap();
            assert_eq!(
                section.align, 128,
                "do not cap TLS definitions at 16 or include imports"
            );
            assert_eq!(section.offset % 128, 0);
            assert_eq!(
                section.sh_flags,
                0x403 /* SHF_ALLOC|SHF_WRITE|SHF_TLS */
            );
            assert_eq!(elf_section_data(&object, ".tdata"), expected);
        }
    }

    #[test]
    fn elf_immutable_pointer_sections_preserve_layout_and_symbol_binding() {
        let plain = ObjectGlobal {
            name: "PLAIN".into(),
            data: vec![1, 2, 3],
            mutable: false,
            is_external: false,
            symbol_refs: vec![],
            is_thread_local: false,
            is_import: false,
            is_weak: false,
            align: 1,
            visibility: trust_ir::Visibility::Default,
            retained: false,
            section: None,
            comdat: false,
        };
        let pointer = ObjectGlobal {
            name: "POINTER".into(),
            data: vec![0; 8],
            align: 64,
            symbol_refs: vec![GlobalSymbolRef {
                offset: 0,
                symbol: "provider".into(),
                addend: 8,
            }],
            ..plain.clone()
        };
        let globals = vec![
            plain.clone(),
            pointer.clone(),
            ObjectGlobal {
                name: "WEAK_POINTER".into(),
                data: vec![0; 16],
                align: 128,
                is_external: true,
                is_weak: true,
                ..pointer.clone()
            },
            ObjectGlobal {
                name: "MUTABLE_POINTER".into(),
                mutable: true,
                ..pointer
            },
            ObjectGlobal {
                name: "IMPORTED".into(),
                data: vec![],
                is_external: true,
                is_import: true,
                ..plain.clone()
            },
            ObjectGlobal {
                name: "TLS".into(),
                is_thread_local: true,
                ..plain
            },
        ];
        let mut writer = crate::elf::ElfWriter::new(crate::elf::ElfMachine::AArch64);
        let rows = add_elf_global_sections(&mut writer, &globals).expect("placement");
        assert_eq!(rows.len(), 5, "imports must not define storage");
        let object = writer.write_checked().unwrap();
        for (name, flags) in [
            (".data", 3),
            (".rodata", 2),
            (".data.rel.ro", 3),
            (".tdata", 0x403),
        ] {
            let section = find_elf_section_view(&object, name).unwrap();
            assert_eq!(section.sh_flags, flags, "{name}");
        }
        assert_eq!(elf_section_data(&object, ".rodata"), &[1, 2, 3]);
        assert_eq!(elf_section_data(&object, ".data"), &[0; 8]);
        let section = find_elf_section_view(&object, ".data.rel.ro").unwrap();
        assert_eq!(section.align, 128);
        assert_eq!(section.offset % 128, 0);
        assert_eq!(elf_section_data(&object, ".data.rel.ro"), &[0; 144]);
        let local = rows.iter().find(|row| row.name == "POINTER").unwrap();
        let weak = rows.iter().find(|row| row.name == "WEAK_POINTER").unwrap();
        assert_eq!(local.section, weak.section);
        assert_eq!((local.offset, local.size), (0, 8));
        assert_eq!((weak.offset, weak.size), (128, 16));
        assert!(!local.is_external && !local.is_weak && !local.is_tls);
        assert!(weak.is_external && weak.is_weak && !weak.is_tls);
        for row in rows.iter().filter(|row| row.section != local.section) {
            assert!(matches!(
                row.name.as_str(),
                "PLAIN" | "MUTABLE_POINTER" | "TLS"
            ));
        }

        // A retained relocated constant gets its own `.data.rel.ro.POINTER`
        // section (`SHF_GNU_RETAIN`, writable for its relocation, its own
        // alignment), as llc places an `@llvm.used` global; the shared
        // `.data.rel.ro` keeps its weak neighbour and no retention, so
        // `--gc-sections` may still drop that neighbour. No other section's
        // flags or bytes change.
        let mut retained_globals = globals.clone();
        retained_globals[1].retained = true;
        let mut retained_writer = crate::elf::ElfWriter::new(crate::elf::ElfMachine::AArch64);
        let retained_rows =
            add_elf_global_sections(&mut retained_writer, &retained_globals).expect("placement");
        let retained_object = retained_writer.write_checked().unwrap();
        for name in [".data", ".rodata", ".tdata"] {
            assert_eq!(
                find_elf_section_view(&retained_object, name)
                    .unwrap()
                    .sh_flags,
                find_elf_section_view(&object, name).unwrap().sh_flags,
                "{name}"
            );
            assert_eq!(
                elf_section_data(&retained_object, name),
                elf_section_data(&object, name),
                "retention changed {name} bytes"
            );
        }
        let shared = find_elf_section_view(&retained_object, ".data.rel.ro").unwrap();
        assert_eq!((shared.sh_flags, shared.size), (3, 16));
        let own = find_elf_section_view(&retained_object, ".data.rel.ro.POINTER").unwrap();
        assert_eq!(
            (own.sh_flags, own.size, own.align),
            (3 | crate::elf::constants::SHF_GNU_RETAIN, 8, 64)
        );
        let row = |name: &str| retained_rows.iter().find(|row| row.name == name).unwrap();
        assert_eq!(
            Some(row("POINTER").section),
            elf_section_index(&retained_object, ".data.rel.ro.POINTER")
        );
        assert_eq!(row("POINTER").offset, 0);
        assert_eq!(
            Some(row("WEAK_POINTER").section),
            elf_section_index(&retained_object, ".data.rel.ro")
        );
        assert_eq!(row("WEAK_POINTER").offset, 0);
    }

    #[test]
    fn elf_zero_fill_definitions_use_nobits_with_layout_preserved() {
        use crate::elf::constants::{SHF_GNU_RETAIN, SHF_TLS, SHT_NOBITS, SHT_PROGBITS};
        let base = ObjectGlobal {
            name: String::new(),
            data: vec![],
            mutable: true,
            is_external: true,
            symbol_refs: vec![],
            is_thread_local: false,
            is_import: false,
            is_weak: false,
            align: 1,
            visibility: trust_ir::Visibility::Default,
            retained: false,
            section: None,
            comdat: false,
        };
        let global = |name: &str, data: Vec<u8>, align: u32| ObjectGlobal {
            name: name.into(),
            data,
            align,
            ..base.clone()
        };
        let tls = |name: &str, data: Vec<u8>, align: u32| ObjectGlobal {
            is_thread_local: true,
            ..global(name, data, align)
        };
        let globals = vec![
            global("DATA", vec![1, 2, 3], 1),
            global("ZERO_SMALL", vec![0; 5], 1),
            ObjectGlobal {
                is_external: false,
                ..global("ZERO_LOCAL_ALIGNED", vec![0; 4096], 64)
            },
            global("ZERO_SIZED", vec![], 8),
            // A relocated pointer slot needs file bytes to patch: never NOBITS.
            ObjectGlobal {
                symbol_refs: vec![GlobalSymbolRef {
                    offset: 0,
                    symbol: "target".into(),
                    addend: 0,
                }],
                ..global("ZERO_SLOT", vec![0; 8], 8)
            },
            // Immutable zero constants keep read-only protection in .rodata.
            ObjectGlobal {
                mutable: false,
                ..global("RO_ZERO", vec![0; 16], 16)
            },
            tls("TLS_INIT", vec![7; 4], 8),
            tls("TLS_ZERO", vec![0; 24], 32),
            ObjectGlobal {
                mutable: false,
                ..tls("TLS_ZERO_CONST", vec![0; 4], 4)
            },
            ObjectGlobal {
                is_import: true,
                ..tls("TLS_IMPORT", vec![], 8)
            },
        ];
        let mut writer = crate::elf::ElfWriter::new(crate::elf::ElfMachine::AArch64);
        let rows = add_elf_global_sections(&mut writer, &globals).expect("placement");
        let object = writer
            .write_checked()
            .expect("zero-fill object must pass reparse");
        let row = |name: &str| rows.iter().find(|row| row.name == name).unwrap();
        let section_of = |name: &str| {
            let shndx = row(name).section;
            [
                ".data",
                ".bss",
                ".rodata",
                ".data.rel.ro",
                ".tdata",
                ".tbss",
            ]
            .into_iter()
            .find(|candidate| elf_section_index(&object, candidate) == Some(shndx))
            .unwrap()
        };
        for (name, section, offset, size, is_tls) in [
            ("DATA", ".data", 0, 3, false),
            ("ZERO_SLOT", ".data", 8, 8, false),
            ("ZERO_SMALL", ".bss", 0, 5, false),
            ("ZERO_LOCAL_ALIGNED", ".bss", 64, 4096, false),
            ("ZERO_SIZED", ".bss", 4160, 0, false),
            ("RO_ZERO", ".rodata", 0, 16, false),
            ("TLS_INIT", ".tdata", 0, 4, true),
            ("TLS_ZERO", ".tbss", 0, 24, true),
            ("TLS_ZERO_CONST", ".tbss", 32, 4, true),
        ] {
            let row = row(name);
            assert_eq!(section_of(name), section, "{name}");
            assert_eq!(
                (row.offset, row.size, row.is_tls),
                (offset, size, is_tls),
                "{name}"
            );
        }
        assert!(!row("ZERO_LOCAL_ALIGNED").is_external);
        assert!(rows.iter().all(|row| row.name != "TLS_IMPORT"));
        for (name, sh_type, flags, size, align) in [
            (".data", SHT_PROGBITS, 0x3, 16, 8),
            (".bss", SHT_NOBITS, 0x3, 4160, 64),
            (".tdata", SHT_PROGBITS, 0x3 | SHF_TLS, 4, 16),
            (".tbss", SHT_NOBITS, 0x3 | SHF_TLS, 36, 32),
        ] {
            let section = find_elf_section_view(&object, name).unwrap();
            assert_eq!(
                (
                    section.sh_type,
                    section.sh_flags,
                    section.size,
                    section.align
                ),
                (sh_type, flags, size, align),
                "{name}"
            );
        }
        // Only the initialized bytes occupy the file; zero-fill sizes do not.
        assert!(object.len() < 4096, "object is {} bytes", object.len());
        assert_eq!(&elf_section_data(&object, ".data")[..3], &[1, 2, 3]);

        // Retention applies per definition: a retained zero-fill global gets
        // its own NOBITS `.bss.ZERO_SMALL` (`SHF_GNU_RETAIN`), and neither the
        // shared `.bss` it leaves nor `.data` is retained.
        let mut retained = globals.clone();
        retained[1].retained = true;
        let mut writer = crate::elf::ElfWriter::new(crate::elf::ElfMachine::AArch64);
        add_elf_global_sections(&mut writer, &retained).expect("placement");
        let object = writer.write_checked().unwrap();
        for (name, sh_type, flags, size) in [
            (".bss.ZERO_SMALL", SHT_NOBITS, 0x3 | SHF_GNU_RETAIN, 5),
            (".bss", SHT_NOBITS, 0x3, 4096),
            (".data", SHT_PROGBITS, 0x3, 16),
        ] {
            let section = find_elf_section_view(&object, name).unwrap();
            assert_eq!(
                (section.sh_type, section.sh_flags, section.size),
                (sh_type, flags, size),
                "{name}"
            );
        }
    }

    /// Every `SHT_GROUP` section of `object`: (signature symbol, flag word,
    /// member section names), read by an independent header walk.
    fn elf_comdat_groups(object: &[u8]) -> Vec<(String, u32, Vec<String>)> {
        let records = crate::elf::reparse::read_object_records(object).expect("reparse");
        let shoff = read_elf_u64(object, 40) as usize;
        records
            .sections
            .iter()
            .enumerate()
            .filter(|(_, section)| section.sh_type == crate::elf::metadata::SHT_GROUP)
            .map(|(index, _)| {
                let header = shoff + index * 64;
                let offset = read_elf_u64(object, header + 24) as usize;
                let size = read_elf_u64(object, header + 32) as usize;
                let info = read_elf_u32(object, header + 44) as usize;
                let words: Vec<u32> = (0..size / 4)
                    .map(|word| read_elf_u32(object, offset + word * 4))
                    .collect();
                (
                    records.symbols[info].name.clone(),
                    words[0],
                    words[1..]
                        .iter()
                        .map(|&member| records.sections[member as usize].name.clone())
                        .collect(),
                )
            })
            .collect()
    }

    /// Zero-fill COMDAT definitions (`LinkOnce`/`LinkOnceOdr`/`WeakOdr`
    /// linkage) are `SHT_NOBITS` `.bss.<sym>` / `.tbss.<sym>` members of their
    /// own `GRP_COMDAT` group, and explicit zero-fill names are `SHT_NOBITS`,
    /// with alignment, symbol sizes and `STT_TLS` preserved and no file
    /// bytes. Nonzero, immutable and relocated COMDAT twins keep PROGBITS
    /// bytes. The reparse gate passes the object and refuses byte mutations
    /// of a grouped NOBITS member's type, `SHF_GROUP`/`SHF_TLS` flags, size
    /// and group payload.
    #[test]
    fn elf_zero_fill_comdat_and_explicit_sections_are_grouped_or_shared_nobits() {
        use crate::elf::constants::{
            SHF_ALLOC, SHF_GNU_RETAIN, SHF_TLS, SHF_WRITE, SHT_NOBITS, SHT_PROGBITS,
        };
        use crate::elf::metadata::SHF_GROUP;
        let base = ObjectGlobal {
            name: String::new(),
            data: vec![],
            mutable: true,
            is_external: true,
            symbol_refs: vec![],
            is_thread_local: false,
            is_import: false,
            is_weak: true,
            align: 1,
            visibility: trust_ir::Visibility::Default,
            retained: false,
            section: None,
            comdat: true,
        };
        let comdat = |name: &str, data: Vec<u8>, align: u32| ObjectGlobal {
            name: name.into(),
            data,
            align,
            ..base.clone()
        };
        let explicit = |name: &str, section: &str, data: Vec<u8>, align: u32| ObjectGlobal {
            is_weak: false,
            comdat: false,
            section: Some(section.into()),
            ..comdat(name, data, align)
        };
        let globals = vec![
            comdat("cd_zero", vec![0; 4096], 64),
            comdat("cd_init", vec![5; 8], 8),
            ObjectGlobal {
                mutable: false,
                ..comdat("cd_ro_zero", vec![0; 16], 16)
            },
            ObjectGlobal {
                symbol_refs: vec![GlobalSymbolRef {
                    offset: 0,
                    symbol: "cd_zero".into(),
                    addend: 8,
                }],
                ..comdat("cd_slot", vec![0; 8], 8)
            },
            ObjectGlobal {
                is_thread_local: true,
                ..comdat("cd_tls_zero", vec![0; 24], 32)
            },
            ObjectGlobal {
                is_thread_local: true,
                mutable: false,
                ..comdat("cd_tls_zero_const", vec![0; 4], 4)
            },
            ObjectGlobal {
                is_thread_local: true,
                ..comdat("cd_tls_init", vec![7; 4], 4)
            },
            ObjectGlobal {
                retained: true,
                ..comdat("cd_kept_zero", vec![0; 8], 8)
            },
            // A COMDAT definition with an explicit zero-fill name keeps it.
            ObjectGlobal {
                section: Some(".bss.cd_named".into()),
                ..comdat("cd_named_zero", vec![0; 12], 4)
            },
            // Explicit, non-COMDAT zero-fill names: one shared NOBITS
            // section per name, packed with each member's alignment.
            explicit("ex_zero_a", ".bss.tcg", vec![0; 5], 1),
            ObjectGlobal {
                mutable: false,
                ..explicit("ex_zero_b", ".bss.tcg", vec![0; 16], 16)
            },
            ObjectGlobal {
                is_thread_local: true,
                ..explicit("ex_tls_zero", ".tbss.tcg", vec![0; 40], 8)
            },
            explicit("ex_sbss", ".sbss", vec![0; 4], 4),
            explicit("ex_lbss", ".lbss.tcg", vec![0; 2048], 256),
        ];
        let mut writer = crate::elf::ElfWriter::new(crate::elf::ElfMachine::AArch64);
        add_elf_global_object_symbols(&mut writer, &globals).expect("placement");
        let object = writer
            .write_checked()
            .expect("grouped NOBITS object must pass the reparse gate");
        // Only initialized bytes occupy the file (4096 + 2048 zero bytes do not).
        assert!(object.len() < 4096, "object is {} bytes", object.len());

        let rw = SHF_ALLOC | SHF_WRITE;
        for (name, sh_type, flags, size, align) in [
            (".bss.cd_zero", SHT_NOBITS, rw | SHF_GROUP, 4096, 64),
            (".data.cd_init", SHT_PROGBITS, rw | SHF_GROUP, 8, 8),
            (
                ".rodata.cd_ro_zero",
                SHT_PROGBITS,
                SHF_ALLOC | SHF_GROUP,
                16,
                16,
            ),
            (".data.cd_slot", SHT_PROGBITS, rw | SHF_GROUP, 8, 8),
            (
                ".tbss.cd_tls_zero",
                SHT_NOBITS,
                rw | SHF_TLS | SHF_GROUP,
                24,
                32,
            ),
            (
                ".tbss.cd_tls_zero_const",
                SHT_NOBITS,
                rw | SHF_TLS | SHF_GROUP,
                4,
                4,
            ),
            (
                ".tdata.cd_tls_init",
                SHT_PROGBITS,
                rw | SHF_TLS | SHF_GROUP,
                4,
                4,
            ),
            (
                ".bss.cd_kept_zero",
                SHT_NOBITS,
                rw | SHF_GROUP | SHF_GNU_RETAIN,
                8,
                8,
            ),
            (".bss.cd_named", SHT_NOBITS, rw | SHF_GROUP, 12, 4),
            (".bss.tcg", SHT_NOBITS, rw, 32, 16),
            (".tbss.tcg", SHT_NOBITS, rw | SHF_TLS, 40, 8),
            (".sbss", SHT_NOBITS, rw, 4, 4),
            (".lbss.tcg", SHT_NOBITS, rw, 2048, 256),
        ] {
            let section =
                find_elf_section_view(&object, name).unwrap_or_else(|| panic!("{name} missing"));
            assert_eq!(
                (
                    section.sh_type,
                    section.sh_flags,
                    section.size,
                    section.align
                ),
                (sh_type, flags, size, align),
                "{name}"
            );
        }
        assert!(
            find_elf_section_view(&object, ".data").is_none()
                && find_elf_section_view(&object, ".bss").is_none()
                && find_elf_section_view(&object, ".tbss").is_none(),
            "COMDAT and explicit definitions leave the implicit sections empty"
        );
        assert_eq!(&elf_section_data(&object, ".data.cd_init"), &[5; 8]);
        assert_eq!(&elf_section_data(&object, ".tdata.cd_tls_init"), &[7; 4]);

        // Symbols: placed in their own section with their own size; STT_TLS
        // for thread-locals; STB_WEAK for COMDAT, STB_GLOBAL for explicit.
        let symbols = elf_symbols(&object);
        let records = crate::elf::reparse::read_object_records(&object).unwrap();
        for (name, section, value, size, tls, weak) in [
            ("cd_zero", ".bss.cd_zero", 0, 4096, false, true),
            ("cd_tls_zero", ".tbss.cd_tls_zero", 0, 24, true, true),
            (
                "cd_tls_zero_const",
                ".tbss.cd_tls_zero_const",
                0,
                4,
                true,
                true,
            ),
            ("cd_named_zero", ".bss.cd_named", 0, 12, false, true),
            ("ex_zero_a", ".bss.tcg", 0, 5, false, false),
            ("ex_zero_b", ".bss.tcg", 16, 16, false, false),
            ("ex_tls_zero", ".tbss.tcg", 0, 40, true, false),
            ("ex_lbss", ".lbss.tcg", 0, 2048, false, false),
        ] {
            let symbol = symbols.iter().find(|symbol| symbol.name == name).unwrap();
            let record = records.symbols.iter().find(|r| r.name == name).unwrap();
            assert_eq!(
                (
                    symbol.section,
                    record.value,
                    symbol.size,
                    symbol.info & 0xf,
                    symbol.info >> 4
                ),
                (
                    elf_section_index(&object, section).unwrap(),
                    value,
                    size,
                    if tls {
                        crate::elf::constants::STT_TLS
                    } else {
                        crate::elf::constants::STT_OBJECT
                    },
                    if weak { 2 } else { 1 }
                ),
                "{name}"
            );
        }

        // One GRP_COMDAT group per COMDAT definition, signed by its symbol.
        let mut groups = elf_comdat_groups(&object);
        groups.sort();
        let group = |signature: &str, members: &[&str]| {
            (
                signature.to_string(),
                1u32,
                members.iter().map(|member| member.to_string()).collect(),
            )
        };
        let mut expected = vec![
            group("cd_zero", &[".bss.cd_zero"]),
            group("cd_init", &[".data.cd_init"]),
            group("cd_ro_zero", &[".rodata.cd_ro_zero"]),
            // The emitters add slot relocations after placement; at this
            // level the relocated twin's group holds its PROGBITS bytes.
            group("cd_slot", &[".data.cd_slot"]),
            group("cd_tls_zero", &[".tbss.cd_tls_zero"]),
            group("cd_tls_zero_const", &[".tbss.cd_tls_zero_const"]),
            group("cd_tls_init", &[".tdata.cd_tls_init"]),
            group("cd_kept_zero", &[".bss.cd_kept_zero"]),
            group("cd_named_zero", &[".bss.cd_named"]),
        ];
        expected.sort();
        assert_eq!(groups, expected);
        assert!(
            records
                .relocations
                .iter()
                .all(|reloc| records.sections[reloc.target_section].sh_type != SHT_NOBITS),
            "no relocation patches a zero-fill section"
        );

        // Reparse-gate refutations on the grouped NOBITS members.
        let intent = writer.reparse_object_intent();
        crate::elf::reparse::check_object(&intent, &object).expect("faithful object");
        let shoff = read_elf_u64(&object, 40) as usize;
        let header =
            |name: &str| shoff + usize::from(elf_section_index(&object, name).unwrap()) * 64;
        let mutate = |name: &str, field: usize, value: u64, width: usize| {
            let mut bytes = object.clone();
            let at = header(name) + field;
            bytes[at..at + width].copy_from_slice(&value.to_le_bytes()[..width]);
            bytes
        };
        for (label, mutated) in [
            (
                ".bss.cd_zero NOBITS->PROGBITS",
                mutate(".bss.cd_zero", 4, u64::from(SHT_PROGBITS), 4),
            ),
            (
                ".bss.cd_zero loses SHF_GROUP",
                mutate(".bss.cd_zero", 8, rw, 8),
            ),
            (".bss.cd_zero shrinks", mutate(".bss.cd_zero", 32, 4088, 8)),
            (
                ".tbss.cd_tls_zero loses SHF_TLS",
                mutate(".tbss.cd_tls_zero", 8, rw | SHF_GROUP, 8),
            ),
            (
                ".tbss.cd_tls_zero NOBITS->PROGBITS",
                mutate(".tbss.cd_tls_zero", 4, u64::from(SHT_PROGBITS), 4),
            ),
            (
                ".bss.tcg gains SHF_GROUP",
                mutate(".bss.tcg", 8, rw | SHF_GROUP, 8),
            ),
        ] {
            assert!(
                crate::elf::reparse::check_object(&intent, &mutated).is_err(),
                "{label} must be refused"
            );
        }
        // The cd_zero group's member word retargeted at the ungrouped
        // `.bss.tcg`.
        let group_header = (0..)
            .map(|index| shoff + index * 64)
            .find(|&at| {
                read_elf_u32(&object, at + 4) == crate::elf::metadata::SHT_GROUP
                    && records.symbols[read_elf_u32(&object, at + 44) as usize].name == "cd_zero"
            })
            .unwrap();
        let payload = read_elf_u64(&object, group_header + 24) as usize;
        let mut retargeted = object.clone();
        retargeted[payload + 4..payload + 8].copy_from_slice(
            &u32::from(elf_section_index(&object, ".bss.tcg").unwrap()).to_le_bytes(),
        );
        assert!(crate::elf::reparse::check_object(&intent, &retargeted).is_err());

        // The placed-section funnel refuses nonzero NOBITS content even if a
        // class were ever computed wrongly (classification never does).
        let mut writer = crate::elf::ElfWriter::new(crate::elf::ElfMachine::AArch64);
        let nonzero = comdat("cd_nonzero", vec![0, 1], 1);
        let class = crate::object_sections::ElfExplicitSection {
            sh_type: SHT_NOBITS,
            sh_flags: rw,
            entsize: 0,
            min_align: 1,
            tls: false,
        };
        let error = add_placed_elf_section(&mut writer, None, ".bss.bad", &class, &[&nonzero])
            .expect_err("nonzero NOBITS bytes must be refused");
        assert!(error.to_string().contains("nonzero bytes"), "{error}");
    }

    #[test]
    fn compile_module_aarch64_linux_thread_local_global_emits_tdata_definition() {
        // A thread-local DEFINITION on the ELF path lands in `.tdata`
        // (SHF_TLS) with an STT_TLS symbol carrying the template offset —
        // NEVER a plain `.data` symbol (one shared copy would be a silent
        // miscompile). Structural check on the emitted bytes.
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("main".to_string(), sig);
        let ret = IrMachInst::new(IrOpcode::Ret, vec![]);
        let ret_id = func.push_inst(ret);
        func.append_inst(func.entry, ret_id);

        let globals = vec![ObjectGlobal {
            name: "TLS_BYTES".to_string(),
            data: vec![1, 2, 3, 4],
            mutable: true,
            is_external: true,
            symbol_refs: vec![],
            is_thread_local: true,
            is_import: false,
            is_weak: false,
            align: 1,
            visibility: trust_ir::Visibility::Default,
            retained: false,
            section: None,
            comdat: false,
        }];
        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-unknown-linux-gnu".to_string(),
            ..Default::default()
        });
        let obj = pipeline
            .compile_module_with_globals(&[func], &globals)
            .expect("ELF thread-local definition must compile to a .tdata template");
        assert_eq!(&obj[0..4], b"\x7fELF");
        let tdata = find_elf_section_view(&obj, ".tdata")
            .expect("thread-local definition must produce a .tdata section");
        // SHF_ALLOC|SHF_WRITE|SHF_TLS and the exact template bytes.
        assert_eq!(
            tdata.sh_flags & crate::elf::constants::SHF_TLS,
            crate::elf::constants::SHF_TLS,
            ".tdata must carry SHF_TLS"
        );
        let template = &obj[tdata.offset as usize..(tdata.offset + tdata.size) as usize];
        assert_eq!(&template[..4], &[1, 2, 3, 4]);
        assert!(
            elf_symbol_names(&obj).iter().any(|n| n == "TLS_BYTES"),
            "the TLS template symbol must be emitted"
        );
        assert!(
            find_elf_section_view(&obj, ".data").is_none(),
            "a thread-local must NOT be emitted as a plain .data definition"
        );
    }

    #[test]
    fn compile_module_aarch64_darwin_emits_thread_local_tlv_sections_and_symbols() {
        // A thread-local object global on the Darwin Mach-O path must materialize
        // the TLV sections (`__thread_data` initial-value template +
        // `__thread_vars` `tlv_descriptor`) and the descriptor / init / bootstrap
        // symbols. Structural check on the emitted bytes (no host needed).
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("main".to_string(), sig);
        let ret = IrMachInst::new(IrOpcode::Ret, vec![]);
        let ret_id = func.push_inst(ret);
        func.append_inst(func.entry, ret_id);

        let globals = vec![ObjectGlobal {
            name: "X".to_string(),
            data: vec![0xCD, 0xAB, 0x00, 0x00],
            mutable: true,
            is_external: true,
            symbol_refs: vec![],
            is_thread_local: true,
            is_import: false,
            is_weak: false,
            align: 1,
            visibility: trust_ir::Visibility::Default,
            retained: false,
            section: None,
            comdat: false,
        }];
        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-apple-darwin".to_string(),
            ..Default::default()
        });
        let obj = pipeline
            .compile_module_with_globals(&[func], &globals)
            .expect("thread-local global should emit Darwin TLV sections");

        // Valid Mach-O.
        assert_eq!(&obj[0..4], &0xFEED_FACFu32.to_le_bytes());
        // The TLV section names and the descriptor/init/bootstrap symbol names
        // are present (as raw section-name / string-table bytes).
        let contains = |needle: &[u8]| obj.windows(needle.len()).any(|w| w == needle);
        assert!(contains(b"__thread_data"), "missing __thread_data section");
        assert!(contains(b"__thread_vars"), "missing __thread_vars section");
        assert!(contains(b"_X\0"), "missing descriptor symbol _X");
        assert!(
            contains(b"_X$tlv$init\0"),
            "missing init symbol _X$tlv$init"
        );
        assert!(
            contains(b"__tlv_bootstrap\0"),
            "missing dyld thunk import __tlv_bootstrap"
        );
        // The 4-byte initial-value template `CD AB 00 00` is in the object.
        assert!(
            contains(&[0xCD, 0xAB, 0x00, 0x00]),
            "missing thread-local initial value template"
        );
    }

    #[test]
    fn compile_module_aarch64_linux_emits_byte_globals_as_object_symbols() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("main".to_string(), sig);
        let ret = IrMachInst::new(IrOpcode::Ret, vec![]);
        let ret_id = func.push_inst(ret);
        func.append_inst(func.entry, ret_id);

        let globals = vec![
            ObjectGlobal {
                name: "MUT_BYTES".to_string(),
                data: vec![1, 2, 3],
                mutable: true,
                is_external: true,
                symbol_refs: vec![],
                is_thread_local: false,
                is_import: false,
                is_weak: false,
                align: 1,
                visibility: trust_ir::Visibility::Default,
                retained: false,
                section: None,
                comdat: false,
            },
            ObjectGlobal {
                name: "IMM_BYTES".to_string(),
                data: vec![4, 5],
                mutable: false,
                is_external: true,
                symbol_refs: vec![],
                is_thread_local: false,
                is_import: false,
                is_weak: false,
                align: 8,
                visibility: trust_ir::Visibility::Default,
                retained: false,
                section: None,
                comdat: false,
            },
        ];
        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-unknown-linux-gnu".to_string(),
            ..Default::default()
        });
        let obj = pipeline
            .compile_module_with_globals(&[func], &globals)
            .expect("Linux AArch64 byte globals should be emitted into ELF");

        assert_eq!(&obj[0..4], b"\x7fELF");
        assert_eq!(elf_section_data(&obj, ".data"), &[1, 2, 3]);
        assert_eq!(elf_section_data(&obj, ".rodata"), &[4, 5]);

        let symbols = elf_symbols(&obj);
        for (name, size) in [("MUT_BYTES", 3), ("IMM_BYTES", 2)] {
            let symbol = symbols
                .iter()
                .find(|symbol| symbol.name == name)
                .expect("global object symbol should be present");
            assert_ne!(symbol.section, 0, "global object must be defined");
            assert_eq!(symbol.size, size);
            assert_eq!(
                symbol.info & 0x0f,
                crate::elf::constants::STT_OBJECT,
                "global object must use STT_OBJECT"
            );
        }
    }

    #[test]
    fn emit_x86_64_elf_function_symbols_preserves_byte_globals() {
        let plan = legacy_elf_text_plan(
            crate::elf::ElfMachine::X86_64,
            &[0xc3],
            &[("main".to_string(), 0)],
            2,
        );
        let obj = emit_elf_with_function_symbols(
            crate::elf::ElfMachine::X86_64,
            &plan,
            &[ObjectGlobal {
                name: "X86_BYTES".to_string(),
                data: vec![9, 8, 7, 6],
                mutable: true,
                is_external: true,
                symbol_refs: vec![],
                is_thread_local: false,
                is_import: false,
                is_weak: false,
                align: 1,
                visibility: trust_ir::Visibility::Default,
                retained: false,
                section: None,
                comdat: false,
            }],
            &ElfModuleSymbolPlan::legacy(),
            None,
        )
        .expect("checked ELF write should pass the reparse gate");

        assert_eq!(&obj[0..4], b"\x7fELF");
        assert_eq!(u16::from_le_bytes([obj[18], obj[19]]), 62);
        assert_eq!(elf_section_data(&obj, ".data"), &[9, 8, 7, 6]);
        let symbol = elf_symbols(&obj)
            .into_iter()
            .find(|symbol| symbol.name == "X86_BYTES")
            .expect("x86_64 ELF global object symbol should be present");
        assert_ne!(symbol.section, 0);
        assert_eq!(symbol.info & 0x0f, crate::elf::constants::STT_OBJECT);
        assert_eq!(symbol.size, 4);
    }

    #[test]
    fn compile_module_aarch64_linux_bl_external_emits_call26_relocation() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("main".to_string(), sig);
        append_framed_external_call(&mut func, "printf");

        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-unknown-linux-gnu".to_string(),
            ..Default::default()
        });
        let obj = pipeline
            .compile_module(&[func])
            .expect("Linux AArch64 BL fixup should emit an ELF relocation");

        assert_eq!(&obj[0..4], b"\x7fELF");
        assert_eq!(u16::from_le_bytes([obj[18], obj[19]]), 183);
        let symbols = elf_symbol_names(&obj);
        let printf_idx = symbols
            .iter()
            .position(|name| name == "printf")
            .expect("undefined printf symbol should be present");
        let relocs = elf_relocations(&obj);
        assert_eq!(relocs.len(), 1);
        // The BL follows the frame-record save.
        assert_eq!(relocs[0].r_offset, 4);
        assert_eq!(
            relocs[0].reloc_type,
            crate::elf::constants::R_AARCH64_CALL26
        );
        assert_eq!(relocs[0].symbol_index as usize, printf_idx);
        assert_eq!(relocs[0].r_addend, 0);
    }

    #[test]
    fn compile_module_parallel_aarch64_linux_b_internal_emits_jump26_relocation() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut caller = IrMachFunction::new("caller".to_string(), sig.clone());
        let call = IrMachInst::new(IrOpcode::B, vec![IrOperand::Symbol("callee".to_string())]);
        let call_id = caller.push_inst(call);
        caller.append_inst(caller.entry, call_id);

        let mut callee = IrMachFunction::new("callee".to_string(), sig);
        let ret = IrMachInst::new(IrOpcode::Ret, vec![]);
        let ret_id = callee.push_inst(ret);
        callee.append_inst(callee.entry, ret_id);

        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-unknown-linux-gnu".to_string(),
            ..Default::default()
        });
        let obj = pipeline
            .compile_module_parallel(&[caller, callee])
            .expect("parallel Linux AArch64 B fixup should emit an ELF relocation");

        assert_eq!(&obj[0..4], b"\x7fELF");
        let symbols = elf_symbol_names(&obj);
        let callee_idx = symbols
            .iter()
            .position(|name| name == "callee")
            .expect("defined callee symbol should be present");
        let relocs = elf_relocations(&obj);
        assert_eq!(relocs.len(), 1);
        assert_eq!(relocs[0].r_offset, 0);
        assert_eq!(
            relocs[0].reloc_type,
            crate::elf::constants::R_AARCH64_JUMP26
        );
        assert_eq!(relocs[0].symbol_index as usize, callee_idx);
    }

    fn build_aarch64_feature_module_function(
        name: &str,
        feature: Option<AArch64IsaFeature>,
    ) -> IrMachFunction {
        use trust_cg_ir::aarch64_regs::{H0, H1, H2, V0, V1, V2, W0, W1};

        let mut func = IrMachFunction::new(name.to_owned(), IrSignature::new(vec![], vec![]));
        let entry = func.entry;
        let insts = match feature {
            None => Vec::new(),
            Some(AArch64IsaFeature::Lse) => vec![
                IrMachInst::new(IrOpcode::Movz, vec![IrOperand::PReg(X0), IrOperand::Imm(1)]),
                IrMachInst::new(IrOpcode::Movz, vec![IrOperand::PReg(X2), IrOperand::Imm(0)]),
                IrMachInst::new(
                    IrOpcode::Ldadd,
                    vec![
                        IrOperand::PReg(X0),
                        IrOperand::PReg(X1),
                        IrOperand::PReg(X2),
                    ],
                ),
            ],
            // LDP is the FEAT_LSE2-gated instruction the 128-bit atomic load
            // lowers to: single-copy atomic only under LSE2 at 16-byte
            // alignment, which is why it needs its own feature bit.
            Some(AArch64IsaFeature::Lse2) => vec![
                IrMachInst::new(IrOpcode::Movz, vec![IrOperand::PReg(X2), IrOperand::Imm(0)]),
                IrMachInst::new(
                    IrOpcode::LdpRI,
                    vec![
                        IrOperand::PReg(X0),
                        IrOperand::PReg(X1),
                        IrOperand::PReg(X2),
                    ],
                ),
            ],
            Some(AArch64IsaFeature::DotProd) => vec![
                IrMachInst::new(
                    IrOpcode::NeonMovi,
                    vec![IrOperand::PReg(V0), IrOperand::Imm(0)],
                ),
                IrMachInst::new(
                    IrOpcode::NeonMovi,
                    vec![IrOperand::PReg(V1), IrOperand::Imm(0)],
                ),
                IrMachInst::new(
                    IrOpcode::NeonMovi,
                    vec![IrOperand::PReg(V2), IrOperand::Imm(0)],
                ),
                IrMachInst::new(
                    IrOpcode::NeonUdotV,
                    vec![
                        IrOperand::PReg(V0),
                        IrOperand::PReg(V1),
                        IrOperand::PReg(V2),
                        IrOperand::Imm(1),
                    ],
                ),
            ],
            Some(AArch64IsaFeature::Fp16) => vec![
                IrMachInst::new(
                    IrOpcode::FmovImm,
                    vec![IrOperand::PReg(H1), IrOperand::FImm(1.0)],
                ),
                IrMachInst::new(
                    IrOpcode::FmovImm,
                    vec![IrOperand::PReg(H2), IrOperand::FImm(2.0)],
                ),
                IrMachInst::new(
                    IrOpcode::FaddRR,
                    vec![
                        IrOperand::PReg(H0),
                        IrOperand::PReg(H1),
                        IrOperand::PReg(H2),
                    ],
                ),
            ],
            // CRC32CX W0, W1, X2: FEAT_CRC32, outside every static profile,
            // so the probe carries it as its own function feature.
            Some(AArch64IsaFeature::Crc) => {
                func.function_target_features =
                    TargetFeatureSet::from_aarch64_features([AArch64IsaFeature::Crc]);
                vec![
                    IrMachInst::new(IrOpcode::Movz, vec![IrOperand::PReg(W1), IrOperand::Imm(1)]),
                    IrMachInst::new(IrOpcode::Movz, vec![IrOperand::PReg(X2), IrOperand::Imm(2)]),
                    IrMachInst::new(
                        IrOpcode::Crc32Cx,
                        vec![
                            IrOperand::PReg(W0),
                            IrOperand::PReg(W1),
                            IrOperand::PReg(X2),
                        ],
                    ),
                ]
            }
            Some(other) => panic!("no probe instruction for {other:?}"),
        };
        for inst in insts {
            let inst = func.push_inst(inst);
            func.append_inst(entry, inst);
        }
        let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
        func.append_inst(entry, ret);
        func
    }

    #[test]
    fn module_emission_unions_target_evidence_and_parallel_bytes_in_real_worker_route() {
        let mut functions = vec![
            build_aarch64_feature_module_function("baseline_probe", None),
            build_aarch64_feature_module_function("lse_probe", Some(AArch64IsaFeature::Lse)),
            build_aarch64_feature_module_function(
                "dotprod_probe",
                Some(AArch64IsaFeature::DotProd),
            ),
            build_aarch64_feature_module_function("fp16_probe", Some(AArch64IsaFeature::Fp16)),
            build_aarch64_feature_module_function("crc_probe", Some(AArch64IsaFeature::Crc)),
        ];
        functions.extend((5..32).map(|index| {
            build_aarch64_feature_module_function(&format!("baseline_probe_{index}"), None)
        }));
        assert_eq!(
            crate::resource_limits::worker_count_for_items(functions.len()).unwrap(),
            Some(2),
            "module evidence parity must exercise the real parallel encoder route"
        );

        let pipeline = Pipeline::new(PipelineConfig::for_target("aarch64-apple-darwin"));
        let sequential = pipeline
            .compile_module_emission_with_target_evidence(&functions, &[], &[], &[])
            .expect("sequential Apple AArch64 module emission succeeds");
        let parallel = pipeline
            .compile_module_parallel_emission_with_target_evidence(&functions, &[], &[])
            .expect("parallel Apple AArch64 module emission succeeds");
        // NOT `AArch64IsaFeature::ALL`: LSE2 is an ATOMICITY RULE rather than an
        // instruction set, so no opcode-keyed rule requires it (see
        // `observe_aarch64_inst_isa_requirements` — `LdpRI` is emitted both as a
        // 128-bit atomic load, which relies on LSE2, and as ordinary frame
        // save/restore, which does not). An emitted instruction stream therefore
        // cannot EVIDENCE LSE2, and its admission is enforced at the ISel gate
        // before emission. Expect exactly the evidenceable features the probes
        // emit, CRC32 among them through the crc probe's own feature.
        let expected = OutputTargetFeatures::try_from_output([
            AArch64IsaFeature::Crc,
            AArch64IsaFeature::DotProd,
            AArch64IsaFeature::Fp16,
            AArch64IsaFeature::Lse,
        ])
        .unwrap();

        assert_eq!(sequential.machine_code().required_features(), expected);
        // The module admission is the profile plus the probes' own features.
        assert_eq!(
            AArch64IsaProfile::from(sequential.machine_code().admitted_features()),
            AArch64IsaProfile::APPLE_ARM64.with_feature(AArch64IsaFeature::Crc, true)
        );
        assert_eq!(parallel.machine_code(), sequential.machine_code());
        assert_eq!(
            sequential.emission().object.as_slice(),
            parallel.emission().object.as_slice(),
            "parallel evidence API must preserve sequential object bytes"
        );
        assert_eq!(
            sequential.emission().text_extents.as_slice(),
            parallel.emission().text_extents.as_slice(),
            "parallel evidence API must preserve exact function order/layout"
        );

        let legacy_sequential = pipeline
            .compile_module_emission(&functions, &[], &[], &[])
            .expect("legacy sequential emission delegates successfully");
        let legacy_parallel = pipeline
            .compile_module_parallel_with_globals_and_layouts(&functions, &[], &[])
            .expect("legacy parallel emission delegates successfully");
        assert_eq!(
            legacy_sequential.object.as_slice(),
            sequential.emission().object.as_slice()
        );
        assert_eq!(
            legacy_parallel.as_slice(),
            parallel.emission().object.as_slice()
        );
    }

    #[test]
    fn module_emission_evidence_is_baseline_and_fails_closed_outside_admission() {
        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-unknown-linux-gnu".to_owned(),
            ..PipelineConfig::default()
        });
        let baseline = [build_aarch64_feature_module_function("baseline_only", None)];
        let emission = pipeline
            .compile_module_emission_with_target_evidence(&baseline, &[], &[], &[])
            .expect("baseline Linux AArch64 module emits");
        assert_eq!(
            emission.machine_code().required_features(),
            OutputTargetFeatures::NONE
        );

        let lse = [build_aarch64_feature_module_function(
            "unadmitted_lse",
            Some(AArch64IsaFeature::Lse),
        )];
        assert!(matches!(
            pipeline.compile_module_emission_with_target_evidence(&lse, &[], &[], &[]),
            Err(PipelineError::Aarch64LseNotAdmitted {
                opcode: IrOpcode::Ldadd,
                ..
            })
        ));

        // The same LSE word is admitted when the function states `lse` itself,
        // and only there: the module evidence admits it, the profile does not.
        let mut own_lse =
            build_aarch64_feature_module_function("own_lse", Some(AArch64IsaFeature::Lse));
        own_lse.function_target_features =
            TargetFeatureSet::from_aarch64_features([AArch64IsaFeature::Lse]);
        let emission = pipeline
            .compile_module_emission_with_target_evidence(
                &[
                    own_lse,
                    build_aarch64_feature_module_function("baseline", None),
                ],
                &[],
                &[],
                &[],
            )
            .expect("a function's own lse admits its LSE word");
        assert_eq!(
            emission.machine_code().required_features(),
            OutputTargetFeatures::try_from_output([AArch64IsaFeature::Lse]).unwrap()
        );
        assert_eq!(pipeline.aarch64_isa_profile(), AArch64IsaProfile::BASELINE);

        // A CRC32 word in a function that does not state `crc` is refused by
        // the feature's name, on every profile.
        let mut crc =
            build_aarch64_feature_module_function("unadmitted_crc", Some(AArch64IsaFeature::Crc));
        crc.function_target_features = TargetFeatureSet::EMPTY;
        assert!(matches!(
            pipeline.compile_module_emission_with_target_evidence(&[crc], &[], &[], &[]),
            Err(PipelineError::Aarch64FeatureNotAdmitted {
                opcode: IrOpcode::Crc32Cx,
                feature: "crc",
                ..
            })
        ));
    }

    /// Build a small self-contained LIR function `name() -> i64 { return a + b }`
    /// plus an empty proof context, for batch-prepare determinism tests.
    fn build_add_lir_function(
        name: &str,
        a: i64,
        b: i64,
    ) -> (trust_cg_lower::Function, trust_cg_lower::ProofContext) {
        use trust_cg_lower::function::{BasicBlock, Signature};
        use trust_cg_lower::instructions::{Block, Instruction, Opcode, Value};
        use trust_cg_lower::types::Type as LowerType;

        let mut func = trust_cg_lower::Function::new(
            name.to_string(),
            Signature {
                params: vec![],
                returns: vec![LowerType::I64],
            },
        );
        func.entry_block = Block(0);
        func.block_order = vec![Block(0)];
        func.blocks.insert(
            Block(0),
            BasicBlock {
                params: vec![],
                instructions: vec![
                    Instruction {
                        opcode: Opcode::Iconst {
                            ty: LowerType::I64,
                            imm: a,
                        },
                        args: vec![],
                        results: vec![Value(0)],
                    },
                    Instruction {
                        opcode: Opcode::Iconst {
                            ty: LowerType::I64,
                            imm: b,
                        },
                        args: vec![],
                        results: vec![Value(1)],
                    },
                    Instruction {
                        opcode: Opcode::Iadd,
                        args: vec![Value(0), Value(1)],
                        results: vec![Value(2)],
                    },
                    Instruction {
                        opcode: Opcode::Return,
                        args: vec![Value(2)],
                        results: vec![],
                    },
                ],
                source_locs: vec![],
            },
        );
        func.value_types.insert(Value(0), LowerType::I64);
        func.value_types.insert(Value(1), LowerType::I64);
        func.value_types.insert(Value(2), LowerType::I64);
        (func, trust_cg_lower::ProofContext::default())
    }

    #[test]
    fn prepare_functions_parallel_is_byte_identical_to_serial() {
        // A multi-function module mirroring the TY compiled-BFS shape (several
        // independent functions prepared together). The work-aware scheduler
        // requires 16 items per worker, so 32 pins a real two-worker route.
        let inputs: Vec<(trust_cg_lower::Function, trust_cg_lower::ProofContext)> = (0..32)
            .map(|i| build_add_lir_function(&format!("kern_fn_{i}"), i * 7 + 1, i * 3 + 2))
            .collect();
        assert_eq!(
            crate::resource_limits::worker_count_for_items(inputs.len()).unwrap(),
            Some(2),
            "the determinism test must exercise the real parallel worker path"
        );

        let pipeline = Pipeline::new(PipelineConfig {
            opt_level: OptLevel::O2,
            target_triple: "aarch64-unknown-linux-gnu".to_string(),
            ..Default::default()
        });

        // Serial reference: the exact per-function call the batch API fans out.
        let serial_with_evidence: Vec<(IrMachFunction, AArch64MachineCodeEvidence)> = inputs
            .iter()
            .map(|(func, ctx)| {
                let (prepared, metrics) = pipeline
                    .prepare_function_with_metrics(func, Some(ctx))
                    .expect("serial prepare succeeds");
                let evidence = metrics
                    .aarch64_machine_code
                    .expect("serial preparation retains AArch64 evidence");
                (prepared, evidence)
            })
            .collect();

        // Parallel batch under test. Its richer result is what a manual batch
        // caller such as TY can consume without serializing or rescanning.
        let parallel_with_evidence: Vec<(IrMachFunction, AArch64MachineCodeEvidence)> = pipeline
            .prepare_functions_parallel_with_metrics(&inputs)
            .into_iter()
            .map(|result| {
                let (prepared, metrics) = result.expect("parallel prepare succeeds");
                let evidence = metrics
                    .aarch64_machine_code
                    .expect("parallel preparation retains AArch64 evidence");
                (prepared, evidence)
            })
            .collect();
        let (serial, serial_evidence): (Vec<_>, Vec<_>) = serial_with_evidence.into_iter().unzip();
        let (parallel, parallel_evidence): (Vec<_>, Vec<_>) =
            parallel_with_evidence.into_iter().unzip();

        assert_eq!(
            serial.len(),
            parallel.len(),
            "batch must return one result per input"
        );

        // 1. Structural byte-identity, function-by-function, in input order.
        //    Debug captures the symbol name, vreg numbering, block/inst order,
        //    operands, and frame layout — any nondeterminism would surface here.
        for (i, (s, p)) in serial.iter().zip(&parallel).enumerate() {
            assert_eq!(
                s.name, inputs[i].0.name,
                "serial result order skew at index {i}"
            );
            assert_eq!(s.name, p.name, "name mismatch / order skew at index {i}");
            assert_eq!(
                format!("{s:#?}"),
                format!("{p:#?}"),
                "prepared IrMachFunction differs at index {i} ({})",
                s.name
            );
            assert_eq!(
                serial_evidence[i], parallel_evidence[i],
                "typed machine-code evidence differs at index {i} ({})",
                s.name
            );
            assert_eq!(
                parallel_evidence[i].required_features(),
                OutputTargetFeatures::NONE,
                "baseline add kernel unexpectedly requires an optional ISA feature"
            );
        }

        // The compatibility API delegates to the richer batch route and drops
        // metrics only. A small prefix pins that legacy result shape without
        // repeating the entire six-function workload.
        let legacy: Vec<IrMachFunction> = pipeline
            .prepare_functions_parallel(&inputs[..2])
            .into_iter()
            .map(|result| result.expect("legacy parallel prepare succeeds"))
            .collect();
        assert_eq!(legacy.len(), 2);
        for (index, prepared) in legacy.iter().enumerate() {
            assert_eq!(prepared.name, inputs[index].0.name);
            assert_eq!(format!("{prepared:#?}"), format!("{:#?}", serial[index]));
        }

        // 2. End-to-end byte-identity of the linked object (symbol order + code
        //    bytes + relocations) — the property TY's positional JIT-link relies
        //    on. Encoding is deterministic, so this is a true serial-vs-parallel
        //    diff of the prepared functions.
        let serial_obj = pipeline
            .compile_module(&serial)
            .expect("serial module encodes");
        let parallel_obj = pipeline
            .compile_module(&parallel)
            .expect("parallel module encodes");
        assert_eq!(
            serial_obj, parallel_obj,
            "serial vs parallel module object bytes differ"
        );
    }

    fn assert_aarch64_linux_unsupported_symbol_fixup_fails_closed(
        insts: impl IntoIterator<Item = IrMachInst>,
        expected_reason: &str,
    ) {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("main".to_string(), sig);
        let ret = IrMachInst::new(IrOpcode::Ret, vec![]);
        for inst in insts {
            let inst_id = func.push_inst(inst);
            func.append_inst(func.entry, inst_id);
        }
        let ret_id = func.push_inst(ret);
        func.append_inst(func.entry, ret_id);

        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-unknown-linux-gnu".to_string(),
            ..Default::default()
        });
        let err = pipeline
            .compile_module(&[func])
            .expect_err("unsupported AArch64 ELF fixup should fail closed");

        match err {
            PipelineError::TargetObjectUnsupported { format, reason, .. } => {
                assert_eq!(format, "ELF");
                assert!(
                    reason.contains(expected_reason),
                    "expected reason containing {expected_reason:?}, got {reason:?}"
                );
            }
            other => panic!("expected TargetObjectUnsupported, got {other:?}"),
        }
    }

    #[test]
    fn compile_module_aarch64_linux_adrp_add_external_emits_page_relocations() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("main".to_string(), sig);
        let adrp = IrMachInst::new(
            IrOpcode::Adrp,
            vec![
                IrOperand::PReg(X16),
                IrOperand::Symbol("global".to_string()),
            ],
        );
        let add = IrMachInst::new(
            IrOpcode::AddPCRel,
            vec![
                IrOperand::PReg(X16),
                IrOperand::PReg(X16),
                IrOperand::Symbol("global".to_string()),
            ],
        );
        let ret = IrMachInst::new(IrOpcode::Ret, vec![]);
        let adrp_id = func.push_inst(adrp);
        let add_id = func.push_inst(add);
        let ret_id = func.push_inst(ret);
        func.append_inst(func.entry, adrp_id);
        func.append_inst(func.entry, add_id);
        func.append_inst(func.entry, ret_id);

        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-unknown-linux-gnu".to_string(),
            ..Default::default()
        });
        let obj = pipeline
            .compile_module(&[func])
            .expect("Linux AArch64 ADRP+ADD fixups should emit ELF relocations");

        assert_eq!(&obj[0..4], b"\x7fELF");
        let symbols = elf_symbol_names(&obj);
        let global_idx = symbols
            .iter()
            .position(|name| name == "global")
            .expect("undefined global symbol should be present");
        let relocs = elf_relocations(&obj);
        assert_eq!(relocs.len(), 2);
        assert_eq!(relocs[0].r_offset, 0);
        assert_eq!(
            relocs[0].reloc_type,
            crate::elf::constants::R_AARCH64_ADR_PREL_PG_HI21
        );
        assert_eq!(relocs[0].symbol_index as usize, global_idx);
        assert_eq!(relocs[0].r_addend, 0);
        assert_eq!(relocs[1].r_offset, 4);
        assert_eq!(
            relocs[1].reloc_type,
            crate::elf::constants::R_AARCH64_ADD_ABS_LO12_NC
        );
        assert_eq!(relocs[1].symbol_index as usize, global_idx);
        assert_eq!(relocs[1].r_addend, 0);
    }

