            let mut fixups = crate::macho::fixup::FixupList::new();
            fixups.push(crate::macho::fixup::Fixup {
                offset: 0,
                kind,
                tls_model: Some(model),
                target: crate::macho::FixupTarget::NamedSymbol("tls_global".to_string()),
                addend: 0,
            });

            let err = emit_aarch64_elf_with_supported_fixups(
                "aarch64-unknown-linux-gnu",
                &[0; 8],
                &[],
                &[],
                &fixups,
                &legacy_elf_text_plan(crate::elf::ElfMachine::AArch64, &[0; 8], &[], 2),
                &ElfModuleSymbolPlan::legacy(),
                None,
            )
            .expect_err("TLS-provenance fixups must not emit as non-TLS ELF relocations");

