    #[test]
    fn exact_function_address_fixups_preserve_binding_and_reject_unsupported_shapes() {
        use crate::macho::{AArch64RelocKind, FixupTarget};
        let pair = [
            IrMachInst::new(
                IrOpcode::Adrp,
                vec![
                    IrOperand::PReg(X17),
                    IrOperand::ExactModuleSymbol("target".into()),
                ],
            ),
            IrMachInst::new(
                IrOpcode::AddPCRel,
                vec![
                    IrOperand::PReg(X16),
                    IrOperand::PReg(X17),
                    IrOperand::ExactModuleSymbol("target".into()),
                ],
            ),
        ];
        let function = |instructions: &[IrMachInst]| {
            let mut function =
                IrMachFunction::new("address".into(), IrSignature::new(vec![], vec![]));
            for instruction in instructions {
                let id = function.push_inst(instruction.clone());
                function.append_inst(function.entry, id);
            }
            function
        };
        let input = function(&pair);
        let (_, fixups) = encode_function_with_fixups(&input).unwrap();
        let fixups: Vec<_> = fixups.iter().collect();
        assert_eq!(fixups.len(), 2);
        assert_eq!(fixups[0].kind, AArch64RelocKind::Page21);
        assert_eq!(fixups[1].kind, AArch64RelocKind::Pageoff12);
        assert!(fixups.iter().all(
            |fixup| matches!(&fixup.target, FixupTarget::ExactNamedSymbol(name) if name == "target")
        ));
        // The compatibility code-only emitter lacks a binding-bearing
        // relocation result and must not silently drop this carrier.
        assert!(crate::lower::encode_function(&input).is_err());
        for opcode in [
            IrOpcode::LdrGot,
            IrOpcode::LdrTlvp,
            IrOpcode::AddTprelLo12,
            IrOpcode::Nop,
        ] {
            let mut bad = pair.clone();
            bad[1].opcode = opcode;
            assert!(
                encode_function_with_fixups(&function(&bad)).is_err(),
                "{opcode:?}"
            );
        }
        let branch = IrMachInst::new(
            IrOpcode::Bl,
            vec![IrOperand::ExactModuleSymbol("target".into())],
        );
        assert!(encode_function_with_fixups(&function(&[branch])).is_err());
        for index in 0..2 {
            let mut bad = pair.clone();
            bad[index]
                .operands
                .push(IrOperand::Symbol("unrelated".into()));
            assert!(
                encode_function_with_fixups(&function(&bad)).is_err(),
                "extra ordinary operand at {index}"
            );
            bad = pair.clone();
            bad[index].operands[0] = IrOperand::PReg(trust_cg_ir::regs::W0);
            assert!(
                encode_function_with_fixups(&function(&bad)).is_err(),
                "narrow destination at {index}"
            );
        }
    }

    /// General-dynamic and local-dynamic TLS lower through the TLS-descriptor
    /// call form on Linux: ISel emits one `TlsDescCall` (a call to regalloc),
    /// frame lowering expands it into the fixed ADRP/LDR/ADD/BLR slots, and
    /// encoding emits the four `R_AARCH64_TLSDESC_*` relocations.
    #[test]
    fn run_isel_aarch64_linux_dynamic_tls_models_lower_through_tlsdesc() {
        use trust_cg_ir::TlsModel;
        use trust_cg_lower::function::{BasicBlock, Function as LowerFunction, Signature};
        use trust_cg_lower::instructions::{Block, Instruction, Opcode, Value};
        use trust_cg_lower::types::Type as LowerType;

        for model in [TlsModel::GeneralDynamic, TlsModel::LocalDynamic] {
            let mut func = LowerFunction::new(
                format!("tls_{model:?}"),
                Signature {
                    params: vec![],
                    returns: vec![LowerType::I64],
                },
            );
            func.entry_block = Block(0);
            func.block_order = vec![Block(0)];
            func.blocks.insert(
                Block(0),
                BasicBlock {
                    params: vec![],
                    instructions: vec![
                        Instruction {
                            opcode: Opcode::TlsRef {
                                name: "tls_global".to_string(),
                                model,
                                local_exec_offset: None,
                            },
                            args: vec![],
                            results: vec![Value(0)],
                        },
                        Instruction {
                            opcode: Opcode::Return,
                            args: vec![Value(0)],
                            results: vec![],
                        },
                    ],
                    source_locs: vec![],
                },
            );

            let pipeline = Pipeline::new(PipelineConfig {
                target_triple: "aarch64-unknown-linux-gnu".to_string(),
                opt_level: OptLevel::O0,
                ..PipelineConfig::default()
            });
            let (selected, _) = pipeline
                .run_isel(&func, None)
                .unwrap_or_else(|err| panic!("{model:?} must select TLSDESC: {err}"));
            let block = &selected.blocks[&Block(0)];
            let calls: Vec<_> = block
                .insts
                .iter()
                .filter(|inst| inst.opcode == IrOpcode::TlsDescCall)
                .collect();
            assert_eq!(calls.len(), 1, "{model:?}: one TLSDESC call form");
            assert_eq!(
                calls[0].operands,
                vec![trust_cg_lower::isel::ISelOperand::Symbol(
                    "tls_global".to_string()
                )]
            );
            assert!(
                IrOpcode::TlsDescCall.default_flags().is_call(),
                "{model:?}: the resolver call is a call"
            );

            let prepared = pipeline.prepare_function(&func).unwrap();
            assert!(
                prepared
                    .block_order
                    .iter()
                    .flat_map(|&block| prepared.block(block).insts.iter())
                    .all(|&id| prepared.inst(id).opcode != IrOpcode::TlsDescCall),
                "{model:?}: frame lowering must expand every TLSDESC call form"
            );
            let (_, fixups) = encode_function_with_fixups(&prepared).unwrap();
            let kinds: Vec<_> = fixups
                .iter()
                .map(|fixup| (fixup.kind, fixup.tls_model))
                .collect();
            assert_eq!(
                kinds,
                [
                    crate::macho::AArch64RelocKind::ElfTlsdescAdrPage21,
                    crate::macho::AArch64RelocKind::ElfTlsdescLd64Lo12,
                    crate::macho::AArch64RelocKind::ElfTlsdescAddLo12,
                    crate::macho::AArch64RelocKind::ElfTlsdescCall,
                ]
                .map(|kind| (kind, Some(TlsModel::GeneralDynamic)))
                .to_vec(),
                "{model:?}"
            );
            let offsets: Vec<_> = fixups.iter().map(|fixup| fixup.offset).collect();
            assert!(
                offsets.windows(2).all(|pair| pair[1] == pair[0] + 4),
                "{model:?}: the four TLSDESC slots are contiguous: {offsets:?}"
            );

            // A reordered or interleaved sequence is refused at encode.
            let block = prepared.block_order[0];
            let ldr = prepared
                .block(block)
                .insts
                .iter()
                .position(|&id| prepared.inst(id).opcode == IrOpcode::LdrTlsdesc)
                .unwrap();
            let mut reordered = prepared.clone();
            reordered.blocks[block.0 as usize].insts.swap(ldr, ldr + 1);
            encode_function_with_fixups(&reordered)
                .expect_err("a reordered TLSDESC sequence must fail closed");
            let mut interleaved = prepared.clone();
            let padding = interleaved.push_inst(IrMachInst::new(IrOpcode::AlignNop, vec![]));
            interleaved.blocks[block.0 as usize]
                .insts
                .insert(ldr + 2, padding);
            let err = encode_function_with_fixups(&interleaved)
                .expect_err("an instruction between the TLSDESC slots must fail closed");
            assert!(
                err.to_string().contains("TLSDESC call sequence"),
                "{model:?}: {err}"
            );
        }
    }

    /// The encode-time TLSDESC shape check refuses a non-ABI resolver
    /// register and a sequence whose symbol changes between slots.
    #[test]
    fn tlsdesc_sequence_verifier_rejects_wrong_registers_and_symbols() {
        use trust_cg_ir::regs::{X0, X1, X2};
        let slots = |ldr_dst: PReg, call_symbol: &str| {
            let sig = IrSignature::new(vec![], vec![]);
            let mut func = IrMachFunction::new("tlsdesc".to_string(), sig);
            let symbol = IrOperand::Symbol("v".into());
            for inst in [
                IrMachInst::new(IrOpcode::Adrp, vec![IrOperand::PReg(X0), symbol.clone()]),
                IrMachInst::new(
                    IrOpcode::LdrTlsdesc,
                    vec![
                        IrOperand::PReg(ldr_dst),
                        IrOperand::PReg(X0),
                        symbol.clone(),
                    ],
                ),
                IrMachInst::new(
                    IrOpcode::AddTlsdescLo12,
                    vec![IrOperand::PReg(X0), IrOperand::PReg(X0), symbol],
                ),
                IrMachInst::new(
                    IrOpcode::BlrTlsdesc,
                    vec![IrOperand::PReg(X1), IrOperand::Symbol(call_symbol.into())],
                ),
            ] {
                let id = func.push_inst(inst);
                func.append_inst(func.entry, id);
            }
            let insts = func.block(func.entry).insts.clone();
            verify_tlsdesc_call_sequence(&func, &insts, 3)
        };
        assert_eq!(slots(X1, "v").unwrap(), "v");
        assert!(slots(X2, "v").is_err(), "resolver must be loaded into x1");
        assert!(slots(X1, "w").is_err(), "all four slots name one symbol");
    }

    /// InitialExec is no longer in the fail-closed set: through the real
    /// `run_isel` pipeline entry it selects the GOT-indirect TPREL sequence
    /// (ADRP + LdrGottprel + MRS + ADD), whose fixups the ELF emitter maps to
    /// the TLSIE relocation pair.
    #[test]
    fn run_isel_aarch64_linux_initial_exec_tls_selects_got_indirect_sequence() {
        use trust_cg_ir::TlsModel;
        use trust_cg_ir::inst::AArch64Opcode;
        use trust_cg_lower::function::{BasicBlock, Function as LowerFunction, Signature};
        use trust_cg_lower::instructions::{Block, Instruction, Opcode, Value};
        use trust_cg_lower::types::Type as LowerType;

        let mut func = LowerFunction::new(
            "tls_initial_exec".to_string(),
            Signature {
                params: vec![],
                returns: vec![LowerType::I64],
            },
        );
        func.entry_block = Block(0);
        func.block_order = vec![Block(0)];
        func.blocks.insert(
            Block(0),
            BasicBlock {
                params: vec![],
                instructions: vec![
                    Instruction {
                        opcode: Opcode::TlsRef {
                            name: "tls_global".to_string(),
                            model: TlsModel::InitialExec,
                            local_exec_offset: None,
                        },
                        args: vec![],
                        results: vec![Value(0)],
                    },
                    Instruction {
                        opcode: Opcode::Return,
                        args: vec![Value(0)],
                        results: vec![],
                    },
                ],
                source_locs: vec![],
            },
        );

        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-unknown-linux-gnu".to_string(),
            opt_level: OptLevel::O0,
            ..PipelineConfig::default()
        });
        let (isel_func, _) = pipeline
            .run_isel(&func, None)
            .expect("InitialExec TlsRef must select the GOT-indirect TPREL sequence");

        let block = &isel_func.blocks[&trust_cg_lower::instructions::Block(0)];
        let opcodes: Vec<_> = block.insts.iter().map(|i| i.opcode).collect();
        assert_eq!(
            &opcodes[..4],
            &[
                AArch64Opcode::Adrp,
                AArch64Opcode::LdrGottprel,
                AArch64Opcode::Mrs,
                AArch64Opcode::AddRR,
            ],
            "InitialExec must lower to ADRP;LDR(gottprel);MRS;ADD, got {opcodes:?}"
        );
        // Same-register, same-symbol ADRP/LDR pairing (the encode-time TLSIE
        // page-kind reconstruction depends on it).
        assert_eq!(block.insts[1].operands[1], block.insts[0].operands[0]);
        assert_eq!(
            block.insts[0].operands[1],
            trust_cg_lower::isel::ISelOperand::Symbol("tls_global".to_string())
        );
        assert_eq!(
            block.insts[1].operands[2],
            trust_cg_lower::isel::ISelOperand::Symbol("tls_global".to_string())
        );
    }

    #[test]
    fn compile_function_aarch64_linux_local_exec_tls_uses_preresolved_offset_without_relocs() {
        use trust_cg_ir::TlsModel;
        use trust_cg_lower::function::{BasicBlock, Function as LowerFunction, Signature};
        use trust_cg_lower::instructions::{Block, Instruction, Opcode, Value};
        use trust_cg_lower::types::Type as LowerType;

        let mut func = LowerFunction::new(
            "tls_local_exec".to_string(),
            Signature {
                params: vec![],
                returns: vec![LowerType::I64],
            },
        );
        func.entry_block = Block(0);
        func.block_order = vec![Block(0)];
        func.blocks.insert(
            Block(0),
            BasicBlock {
                params: vec![],
                instructions: vec![
                    Instruction {
                        opcode: Opcode::TlsRef {
                            name: "tls_global".to_string(),
                            model: TlsModel::LocalExec,
                            local_exec_offset: Some(0x40),
                        },
                        args: vec![],
                        results: vec![Value(0)],
                    },
                    Instruction {
                        opcode: Opcode::Return,
                        args: vec![Value(0)],
                        results: vec![],
                    },
                ],
                source_locs: vec![],
            },
        );

        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-unknown-linux-gnu".to_string(),
            opt_level: OptLevel::O0,
            ..PipelineConfig::default()
        });
        let obj = pipeline
            .compile_function(&func)
            .expect("pre-resolved LocalExec TLS should emit AArch64 ELF without TLS relocations");

        assert_eq!(&obj[0..4], b"\x7fELF");
        assert!(
            find_elf_section_view(&obj, ".rela.text").is_none(),
            "pre-resolved LocalExec TLS must not synthesize ELF TLSLE relocations"
        );
        assert!(
            elf_symbol_names(&obj)
                .iter()
                .all(|name| name != "tls_global"),
            "pre-resolved LocalExec TLS must not leave an unresolved TLS symbol"
        );
    }

    #[cfg(feature = "verify")]
    #[test]
    fn aarch64_linux_local_exec_preresolved_inventory_has_zero_relocation_rows() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("tls_local_exec_preresolved".to_string(), sig);
        let mrs = func.push_inst(IrMachInst::new(
            IrOpcode::Mrs,
            vec![IrOperand::PReg(X0), IrOperand::Imm(0xDE82)],
        ));
        let add = func.push_inst(IrMachInst::new(
            IrOpcode::AddRI,
            vec![
                IrOperand::PReg(X0),
                IrOperand::PReg(X0),
                IrOperand::Imm(0x40),
            ],
        ));
        let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
        func.append_inst(func.entry, mrs);
        func.append_inst(func.entry, add);
        func.append_inst(func.entry, ret);

        let pipeline = Pipeline::new(PipelineConfig {
            target_triple: "aarch64-unknown-linux-gnu".to_string(),
            ..PipelineConfig::default()
        });
        let report = pipeline
            .module_relocation_inventory_report(&[func], "aarch64-linux-local-exec.o")
            .expect("AArch64 ELF inventory should be computed")
            .expect("AArch64 Linux ELF should produce an inventory report");

        assert!(report.entries.is_empty());
        assert!(report.is_promotable());
    }

    #[test]
    fn run_isel_uses_layout_order_not_numeric_block_ids() {
        use trust_cg_lower::function::{BasicBlock, Function as LowerFunction, Signature};
        use trust_cg_lower::instructions::{Block, Instruction, Opcode, Value};
        use trust_cg_lower::types::Type as LowerType;

        let mut func = LowerFunction::new(
            "entry_high_id".to_string(),
            Signature {
                params: vec![],
                returns: vec![LowerType::I64],
            },
        );
        func.entry_block = Block(10);
        func.block_order = vec![Block(10), Block(1)];
        func.blocks.insert(
            Block(10),
            BasicBlock {
                params: vec![],
                instructions: vec![
                    Instruction {
                        opcode: Opcode::Iconst {
                            ty: LowerType::I64,
                            imm: 7,
                        },
                        args: vec![],
                        results: vec![Value(0)],
                    },
                    Instruction {
                        opcode: Opcode::Jump { dest: Block(1) },
                        args: vec![],
                        results: vec![],
                    },
                ],
                source_locs: vec![],
            },
        );
        func.blocks.insert(
            Block(1),
            BasicBlock {
                params: vec![],
                instructions: vec![
                    Instruction {
                        opcode: Opcode::Copy,
                        args: vec![Value(0)],
                        results: vec![Value(1)],
                    },
                    Instruction {
                        opcode: Opcode::Return,
                        args: vec![Value(1)],
                        results: vec![],
                    },
                ],
                source_locs: vec![],
            },
        );

        let pipeline = Pipeline::new(PipelineConfig {
            opt_level: OptLevel::O0,
            ..PipelineConfig::for_target("aarch64-apple-darwin")
        });
        let (isel_func, _) = pipeline
            .run_isel(&func, None)
            .expect("entry block must be selected before its successors");

        assert_eq!(isel_func.block_order, vec![Block(10), Block(1)]);
    }

    #[test]
    fn run_isel_uses_cfg_order_for_dominated_late_defs() {
        use trust_cg_lower::function::{BasicBlock, Function as LowerFunction, Signature};
        use trust_cg_lower::instructions::{Block, Instruction, Opcode, Value};
        use trust_cg_lower::types::Type as LowerType;

        let mut func = LowerFunction::new(
            "dominated_late_def".to_string(),
            Signature {
                params: vec![],
                returns: vec![LowerType::I64],
            },
        );
        func.entry_block = Block(0);
        func.block_order = vec![Block(0), Block(1), Block(2)];
        func.blocks.insert(
            Block(0),
            BasicBlock {
                params: vec![],
                instructions: vec![Instruction {
                    opcode: Opcode::Jump { dest: Block(2) },
                    args: vec![],
                    results: vec![],
                }],
                source_locs: vec![],
            },
        );
        func.blocks.insert(
            Block(1),
            BasicBlock {
                params: vec![],
                instructions: vec![Instruction {
                    opcode: Opcode::Return,
                    args: vec![Value(0)],
                    results: vec![],
                }],
                source_locs: vec![],
            },
        );
        func.blocks.insert(
            Block(2),
            BasicBlock {
                params: vec![],
                instructions: vec![
                    Instruction {
                        opcode: Opcode::Iconst {
                            ty: LowerType::I64,
                            imm: 42,
                        },
                        args: vec![],
                        results: vec![Value(0)],
                    },
                    Instruction {
                        opcode: Opcode::Jump { dest: Block(1) },
                        args: vec![],
                        results: vec![],
                    },
                ],
                source_locs: vec![],
            },
        );

        let pipeline = Pipeline::new(PipelineConfig {
            opt_level: OptLevel::O0,
            ..PipelineConfig::for_target("aarch64-apple-darwin")
        });
        let (isel_func, _) = pipeline
            .run_isel(&func, None)
            .expect("CFG RPO must select the dominating definition before the dominated use");

        assert_eq!(isel_func.block_order, vec![Block(0), Block(2), Block(1)]);
    }

