    #[test]
    fn classify_def_use_post_index_writeback_roles_are_not_flattened() {
        let vec = VReg::new(0, RegClass::Fpr128);
        let base = VReg::new(1, RegClass::Gpr64);
        let st1 = make_inst(
            IrOpcode::NeonSt1Post,
            vec![
                IrOperand::VReg(vec),
                IrOperand::VReg(base),
                IrOperand::Imm(5),
            ],
        );
        let (defs, uses, _) = classify_def_use(&st1).unwrap();
        assert_eq!(
            defs.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![base]
        );
        assert_eq!(
            uses.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![vec, base]
        );

        let loaded = VReg::new(2, RegClass::Fpr128);
        let ld1 = make_inst(
            IrOpcode::NeonLd1Post,
            vec![
                IrOperand::VReg(loaded),
                IrOperand::VReg(base),
                IrOperand::Imm(5),
            ],
        );
        let (defs, uses, _) = classify_def_use(&ld1).unwrap();
        assert_eq!(
            defs.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![loaded, base]
        );
        assert_eq!(
            uses.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![base]
        );

        let x0 = VReg::new(3, RegClass::Gpr64);
        let x1 = VReg::new(4, RegClass::Gpr64);
        let ldp_post = make_inst(
            IrOpcode::LdpPostIndex,
            vec![
                IrOperand::VReg(x0),
                IrOperand::VReg(x1),
                IrOperand::VReg(base),
                IrOperand::Imm(16),
            ],
        );
        let (defs, uses, _) = classify_def_use(&ldp_post).unwrap();
        assert_eq!(
            defs.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![x0, x1, base]
        );
        assert_eq!(
            uses.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![base]
        );

        // LDP Q-pair post-index mirrors LdpPostIndex: BOTH Q registers are
        // defs and the base is a def-use — flattening operand 1 to a use
        // would hide the second loaded register from regalloc.
        let q0 = VReg::new(10, RegClass::Fpr128);
        let q1 = VReg::new(11, RegClass::Fpr128);
        let neon_ldp = make_inst(
            IrOpcode::NeonLdpQPost,
            vec![
                IrOperand::VReg(q0),
                IrOperand::VReg(q1),
                IrOperand::VReg(base),
                IrOperand::Imm(32),
            ],
        );
        let (defs, uses, _) = classify_def_use(&neon_ldp).unwrap();
        assert_eq!(
            defs.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![q0, q1, base]
        );
        assert_eq!(
            uses.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![base]
        );

        // STP Q-pair post-index is the STORE mirror: BOTH Q registers are USES
        // (stored), only the base is a def (writeback). Flattening operand 1 to
        // a def would fabricate a phantom write of the second stored register.
        let neon_stp = make_inst(
            IrOpcode::NeonStpQPost,
            vec![
                IrOperand::VReg(q0),
                IrOperand::VReg(q1),
                IrOperand::VReg(base),
                IrOperand::Imm(32),
            ],
        );
        let (defs, uses, _) = classify_def_use(&neon_stp).unwrap();
        assert_eq!(
            defs.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![base]
        );
        assert_eq!(
            uses.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![q0, q1, base]
        );

        let stp_pre = make_inst(
            IrOpcode::StpPreIndex,
            vec![
                IrOperand::VReg(x0),
                IrOperand::VReg(x1),
                IrOperand::VReg(base),
                IrOperand::Imm(-16),
            ],
        );
        let (defs, uses, _) = classify_def_use(&stp_pre).unwrap();
        assert_eq!(
            defs.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![base]
        );
        assert_eq!(
            uses.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![x0, x1, base]
        );

        let ldr_pre = make_inst(
            IrOpcode::LdrPreIndex,
            vec![
                IrOperand::VReg(x0),
                IrOperand::VReg(base),
                IrOperand::Imm(8),
            ],
        );
        let (defs, uses, _) = classify_def_use(&ldr_pre).unwrap();
        assert_eq!(
            defs.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![x0, base]
        );
        assert_eq!(
            uses.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![base]
        );

        let str_post = make_inst(
            IrOpcode::StrPostIndex,
            vec![
                IrOperand::VReg(x0),
                IrOperand::VReg(base),
                IrOperand::Imm(-8),
            ],
        );
        let (defs, uses, _) = classify_def_use(&str_post).unwrap();
        assert_eq!(
            defs.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![base]
        );
        assert_eq!(
            uses.iter()
                .filter_map(|op| op.as_vreg())
                .collect::<Vec<_>>(),
            vec![x0, base]
        );
    }

    #[test]
    fn rebuild_post_index_writeback_operands_from_regalloc_roles() {
        use trust_cg_regalloc::machine_types::RegAllocOperand as RaOp;

        let vec = VReg::new(0, RegClass::Fpr128);
        let base = VReg::new(1, RegClass::Gpr64);

        assert_eq!(
            regalloc_explicit_operand_count(IrOpcode::NeonSt1Post, 1, 3).unwrap(),
            3
        );
        assert_eq!(
            rebuild_operands_from_regalloc(
                IrOpcode::NeonSt1Post,
                &[RaOp::VReg(base)],
                &[RaOp::VReg(vec), RaOp::VReg(base), RaOp::Imm(5)],
            )
            .unwrap(),
            vec![
                IrOperand::VReg(vec),
                IrOperand::VReg(base),
                IrOperand::Imm(5),
            ]
        );

        let loaded = VReg::new(2, RegClass::Fpr128);
        assert_eq!(
            regalloc_explicit_operand_count(IrOpcode::NeonLd1Post, 2, 2).unwrap(),
            3
        );
        assert_eq!(
            rebuild_operands_from_regalloc(
                IrOpcode::NeonLd1Post,
                &[RaOp::VReg(loaded), RaOp::VReg(base)],
                &[RaOp::VReg(base), RaOp::Imm(5)],
            )
            .unwrap(),
            vec![
                IrOperand::VReg(loaded),
                IrOperand::VReg(base),
                IrOperand::Imm(5),
            ]
        );

        let x0 = VReg::new(3, RegClass::Gpr64);
        let x1 = VReg::new(4, RegClass::Gpr64);
        assert_eq!(
            regalloc_explicit_operand_count(IrOpcode::LdpPostIndex, 3, 2).unwrap(),
            4
        );
        assert_eq!(
            regalloc_explicit_operand_count(IrOpcode::NeonLdpQPost, 3, 2).unwrap(),
            4
        );
        let q0 = VReg::new(10, RegClass::Fpr128);
        let q1 = VReg::new(11, RegClass::Fpr128);
        assert_eq!(
            rebuild_operands_from_regalloc(
                IrOpcode::NeonLdpQPost,
                &[RaOp::VReg(q0), RaOp::VReg(q1), RaOp::VReg(base)],
                &[RaOp::VReg(base), RaOp::Imm(32)],
            )
            .unwrap(),
            vec![
                IrOperand::VReg(q0),
                IrOperand::VReg(q1),
                IrOperand::VReg(base),
                IrOperand::Imm(32),
            ]
        );
        assert_eq!(
            regalloc_explicit_operand_count(IrOpcode::StpPreIndex, 1, 4).unwrap(),
            4
        );
        // STP Q-pair post-index: 1 def (base writeback) + 4 uses (both Q data
        // regs, old base, immediate) — the STORE mirror of NeonLdpQPost.
        assert_eq!(
            regalloc_explicit_operand_count(IrOpcode::NeonStpQPost, 1, 4).unwrap(),
            4
        );
        assert_eq!(
            rebuild_operands_from_regalloc(
                IrOpcode::NeonStpQPost,
                &[RaOp::VReg(base)],
                &[
                    RaOp::VReg(q0),
                    RaOp::VReg(q1),
                    RaOp::VReg(base),
                    RaOp::Imm(32)
                ],
            )
            .unwrap(),
            vec![
                IrOperand::VReg(q0),
                IrOperand::VReg(q1),
                IrOperand::VReg(base),
                IrOperand::Imm(32),
            ]
        );
        assert_eq!(
            regalloc_explicit_operand_count(IrOpcode::LdrPreIndex, 2, 2).unwrap(),
            3
        );
        assert_eq!(
            regalloc_explicit_operand_count(IrOpcode::LdrPostIndex, 2, 2).unwrap(),
            3
        );
        assert_eq!(
            regalloc_explicit_operand_count(IrOpcode::StrPreIndex, 1, 3).unwrap(),
            3
        );
        assert_eq!(
            regalloc_explicit_operand_count(IrOpcode::StrPostIndex, 1, 3).unwrap(),
            3
        );
        assert_eq!(
            rebuild_operands_from_regalloc(
                IrOpcode::LdrPostIndex,
                &[RaOp::VReg(x0), RaOp::VReg(base)],
                &[RaOp::VReg(base), RaOp::Imm(8)],
            )
            .unwrap(),
            vec![
                IrOperand::VReg(x0),
                IrOperand::VReg(base),
                IrOperand::Imm(8),
            ]
        );
        assert_eq!(
            rebuild_operands_from_regalloc(
                IrOpcode::StrPreIndex,
                &[RaOp::VReg(base)],
                &[RaOp::VReg(x0), RaOp::VReg(base), RaOp::Imm(-8)],
            )
            .unwrap(),
            vec![
                IrOperand::VReg(x0),
                IrOperand::VReg(base),
                IrOperand::Imm(-8),
            ]
        );
        assert_eq!(
            rebuild_operands_from_regalloc(
                IrOpcode::StpPreIndex,
                &[RaOp::VReg(base)],
                &[
                    RaOp::VReg(x0),
                    RaOp::VReg(x1),
                    RaOp::VReg(base),
                    RaOp::Imm(-16),
                ],
            )
            .unwrap(),
            vec![
                IrOperand::VReg(x0),
                IrOperand::VReg(x1),
                IrOperand::VReg(base),
                IrOperand::Imm(-16),
            ]
        );
    }

    #[test]
    fn classify_operand_positions_ldpri_matches_def_use() {
        let v0 = VReg::new(0, RegClass::Gpr64);
        let v1 = VReg::new(1, RegClass::Gpr64);
        let base = VReg::new(2, RegClass::Gpr64);
        let inst = make_inst(
            IrOpcode::LdpRI,
            vec![
                IrOperand::VReg(v0),
                IrOperand::VReg(v1),
                IrOperand::VReg(base),
                IrOperand::Imm(0),
            ],
        );

        let (def_positions, use_positions) = classify_operand_positions(&inst);
        assert_eq!(def_positions, vec![0, 1]);
        assert_eq!(use_positions, vec![2, 3]);

        let (defs, uses, _) = classify_def_use(&inst).unwrap();
        assert_eq!(defs.len(), def_positions.len());
        assert_eq!(uses.len(), use_positions.len());
    }

    #[test]
    fn classify_def_use_empty_operands_no_defs_no_uses() {
        // An instruction with no operands -> empty defs and uses regardless of flags
        let inst = make_inst(IrOpcode::Nop, vec![]);

        let (defs, uses, _) = classify_def_use(&inst).unwrap();
        assert!(defs.is_empty());
        assert!(uses.is_empty());
    }

    #[test]
    fn classify_def_use_mov_immediate() {
        // MovI: [dst, imm] -> defs=[dst], uses=[imm]
        let v0 = VReg::new(0, RegClass::Gpr64);
        let inst = make_inst(
            IrOpcode::MovI,
            vec![IrOperand::VReg(v0), IrOperand::Imm(100)],
        );

        let (defs, uses, _) = classify_def_use(&inst).unwrap();
        assert_eq!(defs.len(), 1);
        assert_eq!(uses.len(), 1);
        assert_eq!(defs[0].as_vreg(), Some(v0));
    }

    #[test]
    fn classify_def_use_movk_first_operand_is_read_write() {
        let v0 = VReg::new(0, RegClass::Gpr64);
        let inst = make_inst(
            IrOpcode::Movk,
            vec![
                IrOperand::VReg(v0),
                IrOperand::Imm(0x1234),
                IrOperand::Imm(16),
            ],
        );

        let (defs, uses, _) = classify_def_use(&inst).unwrap();
        assert_eq!(defs.len(), 1);
        assert_eq!(uses.len(), 3);
        assert_eq!(defs[0].as_vreg(), Some(v0));
        assert_eq!(uses[0].as_vreg(), Some(v0));
    }

    #[test]
    fn atomic_lse_def_use_regalloc_rebuild_and_spill_roles() {
        use trust_cg_regalloc::machine_types::{
            RegAllocBlock, RegAllocFunction, RegAllocInst, RegAllocOperand as RaOp,
        };

        let update = VReg::new(0, RegClass::Gpr64);
        let old = VReg::new(1, RegClass::Gpr64);
        let addr = VReg::new(2, RegClass::Gpr64);

        for opcode in [
            IrOpcode::Ldadd,
            IrOpcode::Ldadda,
            IrOpcode::Ldaddal,
            IrOpcode::Ldclr,
            IrOpcode::Ldclra,
            IrOpcode::Ldclral,
            IrOpcode::Ldeor,
            IrOpcode::Ldeora,
            IrOpcode::Ldeoral,
            IrOpcode::Ldset,
            IrOpcode::Ldseta,
            IrOpcode::Ldsetal,
            IrOpcode::Ldsmax,
            IrOpcode::Ldsmaxa,
            IrOpcode::Ldsmaxal,
            IrOpcode::Ldsmin,
            IrOpcode::Ldsmina,
            IrOpcode::Ldsminal,
            IrOpcode::Ldumax,
            IrOpcode::Ldumaxa,
            IrOpcode::Ldumaxal,
            IrOpcode::Ldumin,
            IrOpcode::Ldumina,
            IrOpcode::Lduminal,
            IrOpcode::Swp,
            IrOpcode::Swpa,
            IrOpcode::Swpal,
        ] {
            let inst = make_inst(
                opcode,
                vec![
                    IrOperand::VReg(update),
                    IrOperand::VReg(old),
                    IrOperand::VReg(addr),
                ],
            );
            let (def_positions, use_positions) = classify_operand_positions(&inst);
            assert_eq!(def_positions, vec![1], "{opcode:?}");
            assert_eq!(use_positions, vec![0, 2], "{opcode:?}");

            let (defs, uses, _) = classify_def_use(&inst).unwrap();
            assert_eq!(defs.len(), 1, "{opcode:?}");
            assert_eq!(uses.len(), 2, "{opcode:?}");
            assert_eq!(defs[0].as_vreg(), Some(old), "{opcode:?}");
            assert_eq!(uses[0].as_vreg(), Some(update), "{opcode:?}");
            assert_eq!(uses[1].as_vreg(), Some(addr), "{opcode:?}");
        }

        let expected = VReg::new(10, RegClass::Gpr64);
        let desired = VReg::new(11, RegClass::Gpr64);
        let cas_addr = VReg::new(12, RegClass::Gpr64);
        for opcode in [
            IrOpcode::Cas,
            IrOpcode::Casa,
            IrOpcode::Casal,
            IrOpcode::Casl,
        ] {
            let inst = make_inst(
                opcode,
                vec![
                    IrOperand::VReg(expected),
                    IrOperand::VReg(desired),
                    IrOperand::VReg(cas_addr),
                ],
            );
            let (def_positions, use_positions) = classify_operand_positions(&inst);
            assert_eq!(def_positions, vec![0], "{opcode:?}");
            assert_eq!(use_positions, vec![0, 1, 2], "{opcode:?}");

            let (defs, uses, _) = classify_def_use(&inst).unwrap();
            assert_eq!(defs.len(), 1, "{opcode:?}");
            assert_eq!(uses.len(), 3, "{opcode:?}");
            assert_eq!(defs[0].as_vreg(), Some(expected), "{opcode:?}");
            assert_eq!(uses[0].as_vreg(), Some(expected), "{opcode:?}");
            assert_eq!(uses[1].as_vreg(), Some(desired), "{opcode:?}");
            assert_eq!(uses[2].as_vreg(), Some(cas_addr), "{opcode:?}");
        }

        let sig = IrSignature::new(vec![], vec![]);
        let mut rebuilt = IrMachFunction::new("atomic_rebuild".to_string(), sig);
        let entry = rebuilt.entry;
        for inst in [
            IrMachInst::new(
                IrOpcode::Ldadd,
                vec![
                    IrOperand::VReg(update),
                    IrOperand::VReg(old),
                    IrOperand::VReg(addr),
                ],
            ),
            IrMachInst::new(
                IrOpcode::Cas,
                vec![
                    IrOperand::VReg(expected),
                    IrOperand::VReg(desired),
                    IrOperand::VReg(cas_addr),
                ],
            ),
        ] {
            let id = rebuilt.push_inst(inst);
            rebuilt.append_inst(entry, id);
        }

        let ra_func = RegAllocFunction {
            name: "atomic_rebuild".to_string(),
            insts: vec![
                RegAllocInst {
                    opcode: IrOpcode::Ldadd as u16,
                    defs: vec![RaOp::VReg(old)],
                    uses: vec![RaOp::VReg(update), RaOp::VReg(addr)],
                    implicit_defs: Vec::new(),
                    implicit_uses: Vec::new(),
                    tied_operands: Vec::new(),
                    flags: IrOpcode::Ldadd.default_flags(),
                },
                RegAllocInst {
                    opcode: IrOpcode::Cas as u16,
                    defs: vec![RaOp::VReg(expected)],
                    uses: vec![
                        RaOp::VReg(expected),
                        RaOp::VReg(desired),
                        RaOp::VReg(cas_addr),
                    ],
                    implicit_defs: Vec::new(),
                    implicit_uses: Vec::new(),
                    tied_operands: Vec::new(),
                    flags: IrOpcode::Cas.default_flags(),
                },
            ],
            blocks: vec![RegAllocBlock {
                insts: vec![InstId(0), InstId(1)],
                preds: Vec::new(),
                succs: Vec::new(),
                loop_depth: 0,
            }],
            block_order: vec![BlockId(0)],
            entry_block: BlockId(0),
            next_vreg: 13,
            next_stack_slot: 0,
            stack_slots: BTreeMap::new(),
        };

        rebuild_ir_from_regalloc(&mut rebuilt, &ra_func).unwrap();
        assert_eq!(
            rebuilt.insts[0].operands,
            vec![
                IrOperand::VReg(update),
                IrOperand::VReg(old),
                IrOperand::VReg(addr),
            ]
        );
        assert_eq!(
            rebuilt.insts[1].operands,
            vec![
                IrOperand::VReg(expected),
                IrOperand::VReg(desired),
                IrOperand::VReg(cas_addr),
            ]
        );

        let mut rmw_spill = IrMachFunction::new(
            "atomic_rmw_spill".to_string(),
            IrSignature::new(vec![], vec![]),
        );
        let rmw_id = rmw_spill.push_inst(IrMachInst::new(
            IrOpcode::Ldadd,
            vec![
                IrOperand::VReg(update),
                IrOperand::VReg(old),
                IrOperand::PReg(X2),
            ],
        ));
        rmw_spill.append_inst(rmw_spill.entry, rmw_id);
        materialize_spilled_operands(
            &mut rmw_spill,
            &[
                trust_cg_regalloc::SpillInfo {
                    vreg: update,
                    slot: StackSlotId(0),
                },
                trust_cg_regalloc::SpillInfo {
                    vreg: old,
                    slot: StackSlotId(1),
                },
            ],
        )
        .unwrap();
        let block = rmw_spill.block(rmw_spill.entry);
        assert_eq!(block.insts.len(), 3);
        assert_eq!(rmw_spill.inst(block.insts[0]).opcode, IrOpcode::LdrRI);
        assert_eq!(rmw_spill.inst(block.insts[1]).opcode, IrOpcode::Ldadd);
        assert_eq!(
            rmw_spill.inst(block.insts[1]).operands,
            vec![
                IrOperand::PReg(X16),
                IrOperand::PReg(X17),
                IrOperand::PReg(X2),
            ]
        );
        assert_eq!(rmw_spill.inst(block.insts[2]).opcode, IrOpcode::StrRI);
        assert_eq!(
            rmw_spill.inst(block.insts[2]).operands[0],
            IrOperand::PReg(X17)
        );

        let mut cas_spill = IrMachFunction::new(
            "atomic_cas_spill".to_string(),
            IrSignature::new(vec![], vec![]),
        );
        let cas_id = cas_spill.push_inst(IrMachInst::new(
            IrOpcode::Cas,
            vec![
                IrOperand::VReg(expected),
                IrOperand::PReg(X1),
                IrOperand::PReg(X2),
            ],
        ));
        cas_spill.append_inst(cas_spill.entry, cas_id);
        materialize_spilled_operands(
            &mut cas_spill,
            &[trust_cg_regalloc::SpillInfo {
                vreg: expected,
                slot: StackSlotId(0),
            }],
        )
        .unwrap();
        let block = cas_spill.block(cas_spill.entry);
        assert_eq!(block.insts.len(), 3);
        assert_eq!(cas_spill.inst(block.insts[0]).opcode, IrOpcode::LdrRI);
        assert_eq!(cas_spill.inst(block.insts[1]).opcode, IrOpcode::Cas);
        assert_eq!(
            cas_spill.inst(block.insts[1]).operands,
            vec![
                IrOperand::PReg(X16),
                IrOperand::PReg(X1),
                IrOperand::PReg(X2),
            ]
        );
        assert_eq!(cas_spill.inst(block.insts[2]).opcode, IrOpcode::StrRI);
        assert_eq!(
            cas_spill.inst(block.insts[2]).operands[0],
            IrOperand::PReg(X16)
        );
    }

    #[test]
    fn exclusive_store_status_def_use_and_rebuild() {
        use trust_cg_regalloc::machine_types::RegAllocOperand as RaOp;

        let status = VReg::new(0, RegClass::Gpr32);
        let address = VReg::new(2, RegClass::Gpr64);
        for class in [RegClass::Gpr32, RegClass::Gpr64] {
            let value = VReg::new(1, class);
            let operands = vec![
                IrOperand::VReg(status),
                IrOperand::VReg(value),
                IrOperand::VReg(address),
            ];
            // Opcode semantics, not mutable store/call flags, own these roles.
            for flags in [
                IrOpcode::Stlxr.default_flags(),
                InstFlags::EMPTY,
                IrOpcode::Stlxr.default_flags().union(InstFlags::IS_CALL),
            ] {
                let mut inst = make_inst(IrOpcode::Stlxr, operands.clone());
                inst.flags = flags;
                assert_eq!(classify_operand_positions(&inst), (vec![0], vec![1, 2]));
                assert_eq!(
                    aarch64_operand_roles(IrOpcode::Stlxr, 3),
                    vec![OperandRole::Def, OperandRole::Use, OperandRole::Use]
                );
                let (defs, uses, tied) = classify_def_use(&inst).unwrap();
                assert_eq!(defs, vec![RaOp::VReg(status)]);
                assert_eq!(uses, vec![RaOp::VReg(value), RaOp::VReg(address)]);
                assert!(tied.is_empty(), "the previous status is not an input");
                assert_eq!(
                    rebuild_operands_from_regalloc(IrOpcode::Stlxr, &defs, &uses).unwrap(),
                    operands
                );
            }
        }
    }

    /// `LlscRmw64 [old, new, status, value, addr, op, ordering]` with the
    /// operands in `mask` spilled (slot `i` for operand `i`) and the others in
    /// `X0, X1, W2, X3, X4`, followed by `tail`.
    fn llsc_rmw_spill_function(mask: u32, tail: Vec<IrMachInst>) -> (IrMachFunction, Vec<VReg>) {
        let regs = vec![
            VReg::new(0, RegClass::Gpr64),
            VReg::new(1, RegClass::Gpr64),
            VReg::new(2, RegClass::Gpr32),
            VReg::new(3, RegClass::Gpr64),
            VReg::new(4, RegClass::Gpr64),
        ];
        let physical = [X0, X1, trust_cg_ir::aarch64_regs::W2, X3, X4];
        let mut func = IrMachFunction::new("llsc_spills".into(), IrSignature::new(vec![], vec![]));
        let mut operands: Vec<IrOperand> = (0..5)
            .map(|i| {
                if mask & (1 << i) != 0 {
                    IrOperand::VReg(regs[i])
                } else {
                    IrOperand::PReg(physical[i])
                }
            })
            .collect();
        operands.push(IrOperand::Imm(0));
        operands.push(IrOperand::Imm(3));
        let id = func.push_inst(make_inst(IrOpcode::LlscRmw64, operands));
        func.append_inst(func.entry, id);
        for inst in tail {
            let id = func.push_inst(inst);
            func.append_inst(func.entry, id);
        }
        for _ in 0..5 {
            func.stack_slots.push(IrStackSlot::new(8, 8));
        }
        (func, regs)
    }

    fn llsc_spills_for(mask: u32, regs: &[VReg]) -> Vec<trust_cg_regalloc::SpillInfo> {
        (0..5)
            .filter(|i| mask & (1 << i) != 0)
            .map(|i| trust_cg_regalloc::SpillInfo {
                vreg: regs[i],
                slot: StackSlotId(i as u32),
            })
            .collect()
    }

    /// `(is_load, register, slot)` of a flagged spill access.
    fn flagged_spill_access(inst: &IrMachInst) -> Option<(bool, PReg, StackSlotId)> {
        if !inst.flags.is_spill_slot_access() {
            return None;
        }
        spill_access_shape(inst)
    }

    #[test]
    fn llsc_pseudo_spills_are_materialized_around_the_pseudo_in_distinct_registers() {
        // Every subset of the five register operands spilled: uses reload into
        // X16/X17 first, defs never take an IP scratch, every spilled operand
        // gets its own register, all traffic sits before or after the pseudo,
        // and the expanded loop passes the exclusive-window check.
        for mask in 1u32..32 {
            let ret = make_inst(IrOpcode::Ret, vec![]);
            let (mut func, regs) = llsc_rmw_spill_function(mask, vec![ret]);
            materialize_spilled_operands(&mut func, &llsc_spills_for(mask, &regs))
                .unwrap_or_else(|error| panic!("mask {mask:#07b}: {error}"));
            let insts: Vec<IrMachInst> = func
                .block(func.entry)
                .insts
                .iter()
                .map(|id| func.inst(*id).clone())
                .collect();
            let at = insts
                .iter()
                .position(|inst| inst.opcode == IrOpcode::LlscRmw64)
                .unwrap();
            let pseudo = &insts[at];
            let registers: Vec<PReg> = pseudo.operands[..5]
                .iter()
                .map(|operand| operand.as_preg().expect("materialized register"))
                .collect();
            for (index, a) in registers.iter().enumerate() {
                for b in &registers[index + 1..] {
                    assert!(!regs_overlap(*a, *b), "mask {mask:#07b}: {registers:?}");
                }
            }
            let spilled_uses = (mask >> 3).count_ones() as usize;
            let spilled_defs = (mask & 0b111).count_ones() as usize;
            // No register is live after the pseudo here: nothing is saved.
            assert_eq!(at, spilled_uses, "mask {mask:#07b}: {insts:#?}");
            assert_eq!(insts.len(), at + 1 + spilled_defs + 1, "mask {mask:#07b}");
            for (offset, reload) in insts[..at].iter().enumerate() {
                let (is_load, reg, slot) = flagged_spill_access(reload).unwrap();
                let position = slot.0 as usize;
                assert!(is_load && position >= 3, "mask {mask:#07b}: {reload:?}");
                assert_eq!(reg, registers[position], "mask {mask:#07b}");
                // Uses take X16 then X17, in operand order.
                assert_eq!(reg, [X16, X17][offset], "mask {mask:#07b}");
            }
            for store in &insts[at + 1..at + 1 + spilled_defs] {
                let (is_load, reg, slot) = flagged_spill_access(store).unwrap();
                let position = slot.0 as usize;
                assert!(!is_load && position < 3, "mask {mask:#07b}: {store:?}");
                assert_eq!(reg, registers[position], "mask {mask:#07b}");
                assert!(
                    !regs_overlap(reg, X16) && !regs_overlap(reg, X17),
                    "mask {mask:#07b}: a def must not take an IP scratch: {reg:?}"
                );
            }
            assert_eq!(crate::llsc::expand_llsc_atomics(&mut func), Ok(1));
            assert_eq!(crate::llsc::check_exclusive_windows(&func), Ok(1));
        }
    }

    #[test]
    fn llsc_pseudo_spill_saves_and_restores_live_borrowed_registers() {
        // Every allocatable GPR other than the pseudo's own is read after the
        // pseudo, so the three spilled defs must borrow live registers: each
        // is saved to an emergency slot before the reloads and restored after
        // the spill stores, all flagged and all outside the pseudo.
        let borrowable = llsc_borrowable_gprs();
        let tail: Vec<IrMachInst> = borrowable
            .iter()
            .map(|&n| {
                let reg = PReg::new(u16::from(n));
                make_inst(
                    IrOpcode::CmpRR,
                    vec![IrOperand::PReg(reg), IrOperand::PReg(reg)],
                )
            })
            .chain(std::iter::once(make_inst(IrOpcode::Ret, vec![])))
            .collect();
        let (mut func, regs) = llsc_rmw_spill_function(0b11111, tail);
        let spill_slot_count = func.stack_slots.len();
        materialize_spilled_operands(&mut func, &llsc_spills_for(0b11111, &regs)).unwrap();
        let insts: Vec<IrMachInst> = func
            .block(func.entry)
            .insts
            .iter()
            .map(|id| func.inst(*id).clone())
            .collect();
        let at = insts
            .iter()
            .position(|inst| inst.opcode == IrOpcode::LlscRmw64)
            .unwrap();
        // 3 saves, 2 reloads, pseudo, 3 def stores, 3 restores.
        assert_eq!(at, 5, "{insts:#?}");
        let saves: Vec<_> = insts[..3]
            .iter()
            .map(|inst| flagged_spill_access(inst).unwrap())
            .collect();
        let restores: Vec<_> = insts[at + 4..at + 7]
            .iter()
            .map(|inst| flagged_spill_access(inst).unwrap())
            .collect();
        assert_eq!(func.stack_slots.len(), spill_slot_count + 3);
        for (index, &(is_load, reg, slot)) in saves.iter().enumerate() {
            assert!(!is_load && preg_class(reg) == RegClass::Gpr64);
            assert!(slot.0 as usize >= spill_slot_count, "{slot:?}");
            let emergency = &func.stack_slots[slot.0 as usize];
            assert_eq!((emergency.size, emergency.align), (8, 8));
            // Restored in reverse order from the same slot.
            assert_eq!(restores[2 - index], (true, reg, slot));
            assert!(!regs_overlap(reg, X16) && !regs_overlap(reg, X17));
        }
        let pseudo = &insts[at];
        for &(_, reg, _) in &saves {
            assert!(
                pseudo.operands[..3]
                    .iter()
                    .any(|operand| operand.as_preg().is_some_and(|p| regs_overlap(p, reg))),
                "each saved register hosts a spilled def: {reg:?} in {pseudo:?}"
            );
        }
        for (store, position) in insts[at + 1..at + 4].iter().zip(0..3u32) {
            let (is_load, reg, slot) = flagged_spill_access(store).unwrap();
            assert!(!is_load);
            assert_eq!(slot, StackSlotId(position));
            assert_eq!(Some(reg), pseudo.operands[position as usize].as_preg());
        }
        assert_eq!(crate::llsc::expand_llsc_atomics(&mut func), Ok(1));
        assert_eq!(crate::llsc::check_exclusive_windows(&func), Ok(1));
    }

    #[test]
    fn gpr_live_after_follows_successors_and_fails_open_on_indirect_branches() {
        let mut func = IrMachFunction::new("live_after".into(), IrSignature::new(vec![], vec![]));
        let entry = func.entry;
        let next = func.create_block();
        let pseudo = func.push_inst(make_inst(IrOpcode::Nop, vec![]));
        func.append_inst(entry, pseudo);
        // x9 is redefined before its read; x10 is read in `next`.
        let def9 = func.push_inst(make_inst(
            IrOpcode::Movz,
            vec![IrOperand::PReg(X9), IrOperand::Imm(1)],
        ));
        func.append_inst(entry, def9);
        let read = func.push_inst(make_inst(
            IrOpcode::AddRR,
            vec![
                IrOperand::PReg(X0),
                IrOperand::PReg(X9),
                IrOperand::PReg(trust_cg_ir::aarch64_regs::X10),
            ],
        ));
        func.append_inst(next, read);
        let ret = func.push_inst(make_inst(IrOpcode::Ret, vec![]).with_implicit_uses(&[X0]));
        func.append_inst(next, ret);
        func.add_edge(entry, next);
        let pseudos = BTreeSet::from([pseudo]);
        let live = aarch64_gpr_live_after(&func, &pseudos)[&pseudo];
        assert_eq!(live, 1 << 10, "{live:#b}");
        // An indirect branch anywhere makes every register live.
        let br = func.push_inst(make_inst(
            IrOpcode::Br,
            vec![IrOperand::PReg(trust_cg_ir::aarch64_regs::X11)],
        ));
        func.append_inst(next, br);
        assert_eq!(
            aarch64_gpr_live_after(&func, &pseudos)[&pseudo],
            ALL_GPR_LOCATIONS
        );
    }

    #[test]
    fn flagged_pair_and_other_unformed_spill_shapes_are_refused_by_name() {
        let check = |opcode: IrOpcode, operands: Vec<IrOperand>| {
            let mut func =
                IrMachFunction::new("unformed_spill".into(), IrSignature::new(vec![], vec![]));
            let mut access = make_inst(opcode, operands);
            access.flags.insert(InstFlags::SPILL_SLOT_ACCESS);
            let id = func.push_inst(access);
            func.append_inst(func.entry, id);
            let ret = func.push_inst(make_inst(IrOpcode::Ret, vec![]));
            func.append_inst(func.entry, ret);
            reject_aarch64_unformed_spill_shapes(&func).map_err(|error| error.to_string())
        };
        let sp = || IrOperand::Special(trust_cg_ir::regs::SpecialReg::SP);
        let pair = check(
            IrOpcode::StpRI,
            vec![
                IrOperand::PReg(X9),
                IrOperand::PReg(trust_cg_ir::aarch64_regs::X10),
                sp(),
                IrOperand::Imm(16),
            ],
        )
        .unwrap_err();
        assert!(pair.contains(AARCH64_PAIR_SPILL_TAG), "{pair}");
        let q_pair = check(
            IrOpcode::LdpRI,
            vec![
                IrOperand::PReg(V16),
                IrOperand::PReg(V17),
                sp(),
                IrOperand::Imm(32),
            ],
        )
        .unwrap_err();
        assert!(q_pair.contains(AARCH64_PAIR_SPILL_TAG), "{q_pair}");
        let writeback = check(
            IrOpcode::StrPreIndex,
            vec![IrOperand::PReg(X9), sp(), IrOperand::Imm(-16)],
        )
        .unwrap_err();
        assert!(writeback.contains(AARCH64_SPILL_SHAPE_TAG), "{writeback}");
        // The shapes spill materialization forms, Q included, pass.
        for data in [X9, V16] {
            check(
                IrOpcode::StrRI,
                vec![
                    IrOperand::PReg(data),
                    IrOperand::MemOp {
                        base: trust_cg_ir::aarch64_regs::X29,
                        offset: -32,
                    },
                ],
            )
            .unwrap();
        }
    }

    #[test]
    fn exclusive_store_spills_preserve_distinct_status_and_inputs() {
        for class in [RegClass::Gpr32, RegClass::Gpr64] {
            for mask in 1..8 {
                let status = VReg::new(0, RegClass::Gpr32);
                let value = VReg::new(1, class);
                let address = VReg::new(2, RegClass::Gpr64);
                let regs = [status, value, address];
                let physical = [W0, if class == RegClass::Gpr32 { W1 } else { X1 }, X2];
                let mut func = IrMachFunction::new(
                    "exclusive_spills".into(),
                    IrSignature::new(vec![], vec![]),
                );
                let operands = (0..3)
                    .map(|i| {
                        if mask & (1 << i) != 0 {
                            IrOperand::VReg(regs[i])
                        } else {
                            IrOperand::PReg(physical[i])
                        }
                    })
                    .collect();
                let id = func.push_inst(make_inst(IrOpcode::Stlxr, operands));
                func.append_inst(func.entry, id);
                let spills: Vec<_> = (0..3)
                    .filter(|i| mask & (1 << i) != 0)
                    .map(|i| trust_cg_regalloc::SpillInfo {
                        vreg: regs[i],
                        slot: StackSlotId(i as u32),
                    })
                    .collect();
                let result = materialize_spilled_operands(&mut func, &spills);
                if mask == 7 {
                    // Two input scratches cannot also host a non-overlapping
                    // status. An opaque whole-loop spill strategy is separate.
                    assert!(
                        matches!(result, Err(PipelineError::RegAlloc(ref message))
                        if message.contains("store-exclusive status")),
                        "{class:?}: {result:?}"
                    );
                    continue;
                }
                result.unwrap();
                let block = func.block(func.entry);
                let exclusive_position = block
                    .insts
                    .iter()
                    .position(|id| func.inst(*id).opcode == IrOpcode::Stlxr)
                    .unwrap();
                let inst = func.inst(block.insts[exclusive_position]);
                let registers: Vec<_> = inst
                    .operands
                    .iter()
                    .map(|operand| match operand {
                        IrOperand::PReg(reg) => *reg,
                        other => panic!("unmaterialized exclusive operand: {other:?}"),
                    })
                    .collect();
                assert!(!regs_overlap(registers[0], registers[1]));
                assert!(!regs_overlap(registers[0], registers[2]));
                assert_eq!(exclusive_position, (mask & 6_u32).count_ones() as usize);
                for id in &block.insts[..exclusive_position] {
                    let load = func.inst(*id);
                    assert_eq!(load.opcode, IrOpcode::LdrRI);
                    assert_ne!(
                        load.operands[1],
                        IrOperand::StackSlot(StackSlotId(0)),
                        "STLXR must not reload a previous status"
                    );
                }
                let suffix = &block.insts[exclusive_position + 1..];
                assert_eq!(suffix.len(), usize::from(mask & 1 != 0));
                if let Some(id) = suffix.first() {
                    let store = func.inst(*id);
                    assert_eq!(store.opcode, IrOpcode::StrRI);
                    assert_eq!(
                        store.operands,
                        vec![
                            IrOperand::PReg(registers[0]),
                            IrOperand::StackSlot(StackSlotId(0))
                        ]
                    );
                }
            }
        }
    }

    #[test]
    fn exclusive_store_spilled_status_cannot_reuse_a_reserved_input_scratch() {
        for input_position in [1, 2] {
            for reserved in [X16, X17] {
                let status = VReg::new(0, RegClass::Gpr32);
                let input = VReg::new(1, RegClass::Gpr64);
                let mut operands = vec![
                    IrOperand::VReg(status),
                    IrOperand::VReg(input),
                    IrOperand::PReg(reserved),
                ];
                if input_position == 2 {
                    operands.swap(1, 2);
                }
                let mut func = IrMachFunction::new(
                    "exclusive_reserved_scratch".into(),
                    IrSignature::new(vec![], vec![]),
                );
                let id = func.push_inst(make_inst(IrOpcode::Stlxr, operands));
                func.append_inst(func.entry, id);
                let result = materialize_spilled_operands(
                    &mut func,
                    &[
                        trust_cg_regalloc::SpillInfo {
                            vreg: status,
                            slot: StackSlotId(0),
                        },
                        trust_cg_regalloc::SpillInfo {
                            vreg: input,
                            slot: StackSlotId(1),
                        },
                    ],
                );
                assert!(
                    matches!(result, Err(PipelineError::RegAlloc(ref message))
                    if message.contains("store-exclusive status")),
                    "{reserved:?}: {result:?}"
                );
            }
        }
    }

    #[test]
    fn classify_def_use_physical_register_operands() {
        // Post-regalloc instruction with PRegs
        let inst = make_inst(
            IrOpcode::AddRR,
            vec![
                IrOperand::PReg(X0),
                IrOperand::PReg(X1),
                IrOperand::PReg(X2),
            ],
        );

        let (defs, uses, _) = classify_def_use(&inst).unwrap();
        assert_eq!(defs.len(), 1);
        assert_eq!(uses.len(), 2);
        assert_eq!(defs[0].as_preg(), Some(X0));
        assert_eq!(uses[0].as_preg(), Some(X1));
    }

    #[test]
    fn classify_def_use_rejects_frame_index_operand() {
        // FrameIndex should be lowered before regalloc; classify_def_use should error
        let inst = make_inst(
            IrOpcode::AddRR,
            vec![
                IrOperand::FrameIndex(trust_cg_ir::types::FrameIdx(-8)),
                IrOperand::PReg(X0),
            ],
        );

        let result = classify_def_use(&inst);
        assert!(result.is_err());
        match result.unwrap_err() {
            PipelineError::InvalidOperand(msg) => {
                assert!(msg.contains("FrameIndex"));
            }
            other => panic!("expected InvalidOperand, got {:?}", other),
        }
    }

