    fn classify_def_use_cbz_branch() {
        let inst = make_inst(
            IrOpcode::Cbz,
            vec![IrOperand::PReg(X0), IrOperand::Block(BlockId(3))],
        );

        let (defs, uses, _) = classify_def_use(&inst).unwrap();
        assert!(defs.is_empty(), "cbz is a branch, no defs");
        assert_eq!(uses.len(), 2);
    }

