    fn register_offset_spill_fixture(
        opcode: IrOpcode,
        classes: [RegClass; 3],
        suffix: Vec<IrOperand>,
    ) -> (IrMachFunction, Vec<trust_cg_regalloc::SpillInfo>) {
        let mut func = IrMachFunction::new(
            "register_offset_spill_fixture".to_string(),
            IrSignature::new(vec![], vec![]),
        );
        let vregs = [
            VReg::new(0, classes[0]),
            VReg::new(1, classes[1]),
            VReg::new(2, classes[2]),
        ];
        let mut operands: Vec<_> = vregs.iter().copied().map(IrOperand::VReg).collect();
        operands.extend(suffix);
        let inst_id = func.push_inst(IrMachInst::new(opcode, operands));
        func.append_inst(func.entry, inst_id);
        let spills = vregs
            .into_iter()
            .enumerate()
            .map(|(slot, vreg)| trust_cg_regalloc::SpillInfo {
                vreg,
                slot: StackSlotId(slot as u32),
            })
            .collect();
        (func, spills)
    }

    fn register_offset_partial_spill_fixture(
        opcode: IrOpcode,
        classes: [RegClass; 3],
        physical_data: PReg,
        mask: u8,
        mode: Option<i64>,
    ) -> (IrMachFunction, Vec<trust_cg_regalloc::SpillInfo>) {
        let (mut func, mut spills) = register_offset_spill_fixture(
            opcode,
            classes,
            mode.map(IrOperand::Imm).into_iter().collect(),
        );
        for (pos, preg) in [physical_data, PReg::new(9), PReg::new(3)]
            .into_iter()
            .enumerate()
        {
            if mask & (1 << pos) == 0 {
                func.inst_mut(InstId(0)).operands[pos] = IrOperand::PReg(preg);
            }
        }
        spills.retain(|spill| mask & (1 << spill.vreg.id) != 0);
        (func, spills)
    }

    fn narrow_register_offset_rows() -> [(IrOpcode, IrOpcode, bool, u32, u32); 4] {
        // Independent architectural words: byte/halfword access is opcode-fixed,
        // even when the data value lives in an X rather than W register.
        [
            (IrOpcode::LdrbRO, IrOpcode::LdrbRI, true, 0, 0x3860_0800),
            (IrOpcode::LdrhRO, IrOpcode::LdrhRI, true, 1, 0x7860_0800),
            (IrOpcode::StrbRO, IrOpcode::StrbRI, false, 0, 0x3820_0800),
            (IrOpcode::StrhRO, IrOpcode::StrhRI, false, 1, 0x7820_0800),
        ]
    }

    fn narrow_register_offset_modes() -> [Option<i64>; 9] {
        [
            None,
            Some(4),
            Some(5),
            Some(6),
            Some(7),
            Some(12),
            Some(13),
            Some(14),
            Some(15),
        ]
    }

    fn narrow_register_offset_pre_ra_result(inst: &IrMachInst, route: usize) -> Result<(), String> {
        // A panic is an unexpected failure, never a successful refusal. Catch
        // each route separately so malformed-shape baselines retain the census.
        std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let mut func =
                IrMachFunction::new("narrow_ro_pre_ra".into(), IrSignature::new(vec![], vec![]));
            func.next_vreg = 3;
            let id = func.push_inst(inst.clone());
            func.append_inst(func.entry, id);
            let ret = func.push_inst(make_inst(IrOpcode::Ret, vec![]));
            func.append_inst(func.entry, ret);
            match route {
                0 => validate_aarch64_mach_function(&func).map_err(|e| e.to_string()),
                1 => classify_def_use(inst)
                    .map(|_| ())
                    .map_err(|e| e.to_string()),
                2 => ir_to_regalloc(&func).map(|_| ()).map_err(|e| e.to_string()),
                _ => unreachable!("three authored pre-RA routes"),
            }
        }))
        .unwrap_or_else(|_| Err("PANIC instead of register-offset refusal".into()))
    }

    fn narrow_register_offset_named_refusal(result: &Result<(), String>) -> bool {
        matches!(result, Err(error) if error.contains("register-offset") && !error.starts_with("PANIC"))
    }

    fn narrow_register_offset_invalid_operands() -> Vec<Vec<IrOperand>> {
        let good = vec![
            IrOperand::VReg(VReg::new(0, RegClass::Gpr64)),
            IrOperand::VReg(VReg::new(1, RegClass::Gpr64)),
            IrOperand::VReg(VReg::new(2, RegClass::Gpr64)),
            IrOperand::Imm(6),
        ];
        let mut bad = Vec::new();
        for mode in [
            -1_i64,
            i64::MIN,
            i64::MAX,
            0,
            1,
            2,
            3,
            8,
            9,
            10,
            11,
            16,
            20,
            21,
            22,
            23,
            28,
            29,
            30,
            31,
            (1_i64 << 32) + 4,
            (1_i64 << 32) + 6,
            (1_i64 << 32) + 12,
            -(1_i64 << 32) + 6,
        ] {
            let mut operands = good.clone();
            operands[3] = IrOperand::Imm(mode);
            bad.push(operands);
        }
        for operand in [
            IrOperand::PReg(X17),
            IrOperand::Special(trust_cg_ir::regs::SpecialReg::XZR),
            IrOperand::MemOp {
                base: X16,
                offset: 6,
            },
            IrOperand::StackSlot(StackSlotId(3)),
        ] {
            let mut operands = good.clone();
            operands[3] = operand;
            bad.push(operands);
        }
        for tail in [IrOperand::Imm(0), IrOperand::PReg(X17)] {
            let mut operands = good.clone();
            operands.push(tail);
            bad.push(operands);
        }
        for len in 0..3 {
            bad.push(good[..len].to_vec());
        }
        for position in 0..3 {
            let mut invalid = vec![
                RegClass::System,
                RegClass::Fpr8,
                RegClass::Fpr16,
                RegClass::Fpr32,
                RegClass::Fpr64,
                RegClass::Fpr128,
            ];
            if position == 1 {
                invalid.push(RegClass::Gpr32);
            }
            for class in invalid {
                let mut operands = good.clone();
                operands[position] = IrOperand::VReg(VReg::new(position as u32, class));
                bad.push(operands);
            }
        }
        for (position, registers) in [(0, [31, 162, 96]), (1, [32, 160, 96]), (2, [31, 162, 96])] {
            for register in registers {
                let mut operands = good.clone();
                operands[position] = IrOperand::PReg(PReg::new(register));
                bad.push(operands);
            }
        }
        for position in 0..3 {
            let mut operands = good.clone();
            operands[position] = IrOperand::Imm(0);
            bad.push(operands);
            let mut operands = good.clone();
            operands[position] = IrOperand::Special(if position == 1 {
                trust_cg_ir::regs::SpecialReg::XZR
            } else {
                trust_cg_ir::regs::SpecialReg::SP
            });
            bad.push(operands);
        }
        assert_eq!(bad.len(), 67);
        bad
    }

