    #[test]
    fn narrow_register_offset_spill_refuses_before_raw_intent_is_erased() {
        let mut attempted = 0;
        let mut failures = Vec::new();
        for (opcode, _, load, _, _) in narrow_register_offset_rows() {
            for (case, operands) in narrow_register_offset_invalid_operands()
                .into_iter()
                .enumerate()
            {
                for mask in [0_u8, 1, 2, 4, 7] {
                    let (mut original, mut spills) =
                        register_offset_spill_fixture(opcode, [RegClass::Gpr64; 3], vec![]);
                    original.inst_mut(InstId(0)).operands = operands.clone();
                    // Preserve each malformed VReg's actual class in the spill map.
                    spills.clear();
                    for (position, operand) in operands.iter().take(3).enumerate() {
                        if mask & (1 << position) != 0
                            && let IrOperand::VReg(vreg) = operand
                        {
                            spills.push(trust_cg_regalloc::SpillInfo {
                                vreg: *vreg,
                                slot: StackSlotId(position as u32),
                            });
                        }
                    }
                    let mut uses = FxHashMap::default();
                    let mut defs = FxHashMap::default();
                    for spill in &spills {
                        if load && spill.vreg.id == 0 {
                            defs.insert(spill.vreg, spill.slot);
                        } else {
                            uses.insert(spill.vreg, spill.slot);
                        }
                    }
                    let mut func = original.clone();
                    let snapshot = func.inst(InstId(0)).clone();
                    let before = format!("{func:?}");
                    let mut appended = Vec::new();
                    let mut debug = SpillMaterializationDebugInfo::default();
                    attempted += 1;
                    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                        materialize_spilled_register_offset_mem(
                            &mut func,
                            InstId(0),
                            &snapshot,
                            &uses,
                            &defs,
                            &mut appended,
                            &mut debug,
                        )
                        .map(|_| ())
                        .map_err(|e| e.to_string())
                    }))
                    .unwrap_or_else(|_| Err("PANIC instead of register-offset refusal".into()));
                    if !narrow_register_offset_named_refusal(&result)
                        || before != format!("{func:?}")
                        || !appended.is_empty()
                        || !debug.stores.is_empty()
                    {
                        failures.push(format!(
                            "helper/{opcode:?}/case{case}/mask{mask}: {result:?}; arena={:?}",
                            func.insts
                        ));
                    }
                    if !spills.is_empty() {
                        attempted += 1;
                        let mut func = original;
                        let before = format!("{:?}", func.insts);
                        let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                            materialize_spilled_operands(&mut func, &spills)
                                .map(|_| ())
                                .map_err(|e| e.to_string())
                        }))
                        .unwrap_or_else(|_| Err("PANIC instead of register-offset refusal".into()));
                        // No claim of outer block-list rollback: require the
                        // original instruction arena and operand bytes intact.
                        if !narrow_register_offset_named_refusal(&result)
                            || before != format!("{:?}", func.insts)
                        {
                            failures.push(format!(
                                "generic/{opcode:?}/case{case}/mask{mask}: {result:?}; arena={:?}",
                                func.insts
                            ));
                        }
                    }
                }
            }
        }
        eprintln!(
            "narrow RO spill negatives: attempted={attempted}, failures={}",
            failures.len()
        );
        assert_eq!(attempted, 2324);
        assert!(
            failures.is_empty(),
            "{} failures; first32:\n{}",
            failures.len(),
            failures
                .iter()
                .take(32)
                .cloned()
                .collect::<Vec<_>>()
                .join("\n")
        );
    }

    #[test]
    fn narrow_register_offset_all_spill_masks_preserve_width_and_index_view() {
        let mut attempted = 0;
        let mut failures = Vec::new();
        for (opcode, ri, load, scale, ro_word) in narrow_register_offset_rows() {
            for (data, bank) in [(RegClass::Gpr32, 32_u16), (RegClass::Gpr64, 0)] {
                for index_class in [RegClass::Gpr32, RegClass::Gpr64] {
                    for mode in narrow_register_offset_modes() {
                        for mask in 0..8_u8 {
                            attempted += 1;
                            let (mut func, spills) = register_offset_partial_spill_fixture(
                                opcode,
                                [data, RegClass::Gpr64, index_class],
                                PReg::new(bank + 8),
                                mask,
                                mode,
                            );
                            let result = materialize_spilled_operands(&mut func, &spills);
                            let context =
                                format!("{opcode:?}/{data:?}/{index_class:?}/{mode:?}/mask{mask}");
                            if let Err(error) = result {
                                failures.push(format!("{context}: {error}"));
                                continue;
                            }
                            let packed = mode.unwrap_or(6) as u32;
                            let mut expected = Vec::new();
                            let expected_word = if mask == 7 {
                                expected.push((
                                    IrOpcode::LdrRI,
                                    vec![
                                        IrOperand::PReg(X16),
                                        IrOperand::StackSlot(StackSlotId(1)),
                                    ],
                                ));
                                expected.push((
                                    IrOpcode::LdrRI,
                                    vec![
                                        IrOperand::PReg(if index_class == RegClass::Gpr32 {
                                            W17
                                        } else {
                                            X17
                                        }),
                                        IrOperand::StackSlot(StackSlotId(2)),
                                    ],
                                ));
                                if let Some(ext) = match packed {
                                    4 | 5 => Some(IrOpcode::Uxtw),
                                    12 | 13 => Some(IrOpcode::Sxtw),
                                    _ => None,
                                } {
                                    expected.push((
                                        ext,
                                        vec![IrOperand::PReg(X17), IrOperand::PReg(X17)],
                                    ));
                                }
                                if packed & 1 != 0 && scale != 0 {
                                    expected.push((
                                        IrOpcode::LslRI,
                                        vec![
                                            IrOperand::PReg(X17),
                                            IrOperand::PReg(X17),
                                            IrOperand::Imm(i64::from(scale)),
                                        ],
                                    ));
                                }
                                let address = if load { X16 } else { X17 };
                                let transfer = PReg::new(bank + if load { 17 } else { 16 });
                                expected.push((
                                    IrOpcode::AddRR,
                                    vec![
                                        IrOperand::PReg(address),
                                        IrOperand::PReg(X16),
                                        IrOperand::PReg(X17),
                                    ],
                                ));
                                if !load {
                                    expected.push((
                                        IrOpcode::LdrRI,
                                        vec![
                                            IrOperand::PReg(transfer),
                                            IrOperand::StackSlot(StackSlotId(0)),
                                        ],
                                    ));
                                }
                                expected.push((
                                    ri,
                                    vec![
                                        IrOperand::PReg(transfer),
                                        IrOperand::PReg(address),
                                        IrOperand::Imm(0),
                                    ],
                                ));
                                if load {
                                    expected.push((
                                        IrOpcode::StrRI,
                                        vec![
                                            IrOperand::PReg(transfer),
                                            IrOperand::StackSlot(StackSlotId(0)),
                                        ],
                                    ));
                                }
                                0x3900_0000
                                    | (scale << 30)
                                    | if load { 1 << 22 } else { 0 }
                                    | if load { (16 << 5) | 17 } else { (17 << 5) | 16 }
                            } else {
                                let mut next_scratch = 16_u16;
                                let mut regs = [PReg::new(bank + 8), PReg::new(9), PReg::new(3)];
                                let order: &[usize] = if load { &[1, 2] } else { &[0, 1, 2] };
                                for &position in order {
                                    if mask & (1 << position) == 0 {
                                        continue;
                                    }
                                    let register_bank = if position == 0 {
                                        bank
                                    } else if position == 2 && index_class == RegClass::Gpr32 {
                                        32
                                    } else {
                                        0
                                    };
                                    let reload = PReg::new(register_bank + next_scratch);
                                    expected.push((
                                        IrOpcode::LdrRI,
                                        vec![
                                            IrOperand::PReg(reload),
                                            IrOperand::StackSlot(StackSlotId(position as u32)),
                                        ],
                                    ));
                                    regs[position] =
                                        if position == 2 && matches!(packed, 6 | 7 | 14 | 15) {
                                            PReg::new(next_scratch)
                                        } else {
                                            reload
                                        };
                                    next_scratch += 1;
                                }
                                if load && mask & 1 != 0 {
                                    regs[0] = PReg::new(bank + next_scratch);
                                }
                                let mut operands: Vec<_> =
                                    regs.into_iter().map(IrOperand::PReg).collect();
                                if let Some(mode) = mode {
                                    operands.push(IrOperand::Imm(mode));
                                }
                                expected.push((opcode, operands));
                                if load && mask & 1 != 0 {
                                    expected.push((
                                        IrOpcode::StrRI,
                                        vec![
                                            IrOperand::PReg(regs[0]),
                                            IrOperand::StackSlot(StackSlotId(0)),
                                        ],
                                    ));
                                }
                                ro_word
                                    | (u32::from(regs[2].encoding() % 32) << 16)
                                    | ((packed >> 1) << 13)
                                    | ((packed & 1) << 12)
                                    | (u32::from(regs[1].encoding()) << 5)
                                    | u32::from(regs[0].encoding() % 32)
                            };
                            let actual: Vec<_> = func.blocks[func.entry.0 as usize]
                                .insts
                                .iter()
                                .map(|id| {
                                    let inst = func.inst(*id);
                                    (inst.opcode, inst.operands.clone())
                                })
                                .collect();
                            let word =
                                crate::aarch64::encode::encode_instruction(func.inst(InstId(0)));
                            if actual != expected
                                || word.as_ref().ok() != Some(&expected_word)
                                || ensure_no_unresolved_vregs(&func, "narrow RO spill matrix")
                                    .is_err()
                            {
                                failures.push(format!("{context}: expected={expected:?}, actual={actual:?}, word={word:?}, expected_word={expected_word:08x}"));
                            }
                        }
                    }
                }
            }
        }
        eprintln!(
            "narrow RO valid spill masks: attempted={attempted}, failures={}",
            failures.len()
        );
        assert_eq!(attempted, 1152);
        assert!(
            failures.is_empty(),
            "{} failures; first32:\n{}",
            failures.len(),
            failures
                .iter()
                .take(32)
                .cloned()
                .collect::<Vec<_>>()
                .join("\n")
        );
    }

    #[test]
    fn narrow_register_offset_never_widens_unreloaded_physical_w_index() {
        let mut attempted = 0;
        let mut failures = Vec::new();
        for (opcode, _, _, _, _) in narrow_register_offset_rows() {
            for (data, bank) in [(RegClass::Gpr32, 32), (RegClass::Gpr64, 0)] {
                for mode in [None, Some(6), Some(7), Some(14), Some(15)] {
                    for mask in 0..4_u8 {
                        attempted += 1;
                        let (mut func, spills) = register_offset_partial_spill_fixture(
                            opcode,
                            [data, RegClass::Gpr64, RegClass::Gpr32],
                            PReg::new(bank + 8),
                            mask,
                            mode,
                        );
                        func.inst_mut(InstId(0)).operands[2] = IrOperand::PReg(PReg::new(35));
                        let result = materialize_spilled_operands(&mut func, &spills);
                        let retained = func.inst(InstId(0));
                        let refused = result.is_err()
                            || crate::aarch64::encode::encode_instruction(retained).is_err();
                        if retained.operands[2] != IrOperand::PReg(PReg::new(35)) || !refused {
                            failures.push(format!(
                                "{opcode:?}/{data:?}/{mode:?}/mask{mask}: {result:?}; {retained:?}"
                            ));
                        }
                    }
                }
            }
        }
        eprintln!(
            "narrow RO unreloaded W: attempted={attempted}, failures={}",
            failures.len()
        );
        assert_eq!(attempted, 160);
        assert!(
            failures.is_empty(),
            "{} failures:\n{}",
            failures.len(),
            failures.join("\n")
        );
    }

    #[test]
    fn register_offset_partial_spill_preserves_reload_width_and_index_view() {
        // Independent physical register-bank origins and architectural store
        // words. No encoder scale/mode/scratch helper supplies expectations.
        let widths = [
            (RegClass::Gpr32, 32, 0xb820_0800_u32),
            (RegClass::Gpr64, 0, 0xf820_0800),
            (RegClass::Fpr16, 165, 0x7c20_0800),
            (RegClass::Fpr32, 128, 0xbc20_0800),
            (RegClass::Fpr64, 96, 0xfc20_0800),
            (RegClass::Fpr128, 64, 0x3ca0_0800),
        ];
        let mut attempted = 0;
        let mut failures = Vec::new();
        for opcode in [IrOpcode::LdrRO, IrOpcode::StrRO] {
            let load = opcode == IrOpcode::LdrRO;
            for (class, bank, store_word) in widths {
                for index_class in [RegClass::Gpr32, RegClass::Gpr64] {
                    for mask in [4_u8, 6, 5] {
                        for mode in [
                            None,
                            Some(4),
                            Some(5),
                            Some(6),
                            Some(7),
                            Some(12),
                            Some(13),
                            Some(14),
                            Some(15),
                        ] {
                            attempted += 1;
                            let (mut func, spills) = register_offset_partial_spill_fixture(
                                opcode,
                                [class, RegClass::Gpr64, index_class],
                                PReg::new(bank + 8),
                                mask,
                                mode,
                            );
                            let context =
                                format!("{opcode:?}/{class:?}/{index_class:?}/mask{mask}/{mode:?}");
                            if let Err(error) = materialize_spilled_operands(&mut func, &spills) {
                                failures.push(format!("{context}: refused {error}"));
                                continue;
                            }
                            let gpr_data = matches!(class, RegClass::Gpr32 | RegClass::Gpr64);
                            let rm = if mask == 6 || (mask == 5 && !load && gpr_data) {
                                17
                            } else {
                                16
                            };
                            let reload = PReg::new(
                                rm + if index_class == RegClass::Gpr32 {
                                    32
                                } else {
                                    0
                                },
                            );
                            let packed = mode.unwrap_or(6);
                            let full_index = matches!(packed, 6 | 7 | 14 | 15);
                            let index = if full_index { PReg::new(rm) } else { reload };
                            let rn = if mask == 6 { 16 } else { 9 };
                            let rt = if mask == 5 {
                                if load && gpr_data { 17 } else { 16 }
                            } else {
                                8
                            };
                            let transfer = PReg::new(bank + rt);
                            let mut expected = Vec::new();
                            if mask == 5 && !load {
                                expected.push((
                                    IrOpcode::LdrRI,
                                    vec![
                                        IrOperand::PReg(transfer),
                                        IrOperand::StackSlot(StackSlotId(0)),
                                    ],
                                ));
                            }
                            if mask == 6 {
                                expected.push((
                                    IrOpcode::LdrRI,
                                    vec![
                                        IrOperand::PReg(X16),
                                        IrOperand::StackSlot(StackSlotId(1)),
                                    ],
                                ));
                            }
                            expected.push((
                                IrOpcode::LdrRI,
                                vec![
                                    IrOperand::PReg(reload),
                                    IrOperand::StackSlot(StackSlotId(2)),
                                ],
                            ));
                            let mut operands = vec![
                                IrOperand::PReg(transfer),
                                IrOperand::PReg(PReg::new(rn)),
                                IrOperand::PReg(index),
                            ];
                            if let Some(mode) = mode {
                                operands.push(IrOperand::Imm(mode));
                            }
                            expected.push((opcode, operands));
                            if mask == 5 && load {
                                expected.push((
                                    IrOpcode::StrRI,
                                    vec![
                                        IrOperand::PReg(transfer),
                                        IrOperand::StackSlot(StackSlotId(0)),
                                    ],
                                ));
                            }
                            let actual: Vec<_> = func.blocks[func.entry.0 as usize]
                                .insts
                                .iter()
                                .map(|id| {
                                    let inst = func.inst(*id);
                                    (inst.opcode, inst.operands.clone())
                                })
                                .collect();
                            let expected_word = store_word
                                | if load { 1 << 22 } else { 0 }
                                | (u32::from(rm) << 16)
                                | (((packed as u32) >> 1) << 13)
                                | (((packed as u32) & 1) << 12)
                                | (u32::from(rn) << 5)
                                | u32::from(rt);
                            let encoded =
                                crate::aarch64::encode::encode_instruction(func.inst(InstId(0)));
                            if actual != expected || encoded.as_ref().ok() != Some(&expected_word) {
                                failures.push(format!("{context}: expected={expected:?}, actual={actual:?}, word={encoded:?}, expected_word={expected_word:08x}"));
                            }
                        }
                    }
                }
            }
        }
        assert_eq!(attempted, 648);
        assert!(
            failures.is_empty(),
            "{} failures across {attempted} partial-spill rows (first 32 shown):\n{}",
            failures.len(),
            failures[..failures.len().min(32)].join("\n")
        );
    }

    #[test]
    fn register_offset_partial_spill_never_widens_unreloaded_physical_index() {
        let mut failures = Vec::new();
        let mut attempted = 0;
        for opcode in [IrOpcode::LdrRO, IrOpcode::StrRO] {
            for (class, bank) in [
                (RegClass::Gpr32, 32),
                (RegClass::Gpr64, 0),
                (RegClass::Fpr16, 165),
                (RegClass::Fpr32, 128),
                (RegClass::Fpr64, 96),
                (RegClass::Fpr128, 64),
            ] {
                for mode in [None, Some(6), Some(7), Some(14), Some(15)] {
                    attempted += 1;
                    // Only the base is spilled. There is no local W3 write
                    // establishing any property of X3's upper half.
                    let (mut func, spills) = register_offset_partial_spill_fixture(
                        opcode,
                        [class, RegClass::Gpr64, RegClass::Gpr32],
                        PReg::new(bank + 8),
                        2,
                        mode,
                    );
                    func.inst_mut(InstId(0)).operands[2] = IrOperand::PReg(PReg::new(35));
                    let result = materialize_spilled_operands(&mut func, &spills);
                    let retained = func.inst(InstId(0));
                    let unchanged_index = retained.operands[2] == IrOperand::PReg(PReg::new(35));
                    let refused = result.is_err()
                        || crate::aarch64::encode::encode_instruction(retained).is_err();
                    if !unchanged_index || !refused {
                        failures.push(format!(
                            "{opcode:?}/{class:?}/{mode:?}: result={result:?}, final={retained:?}"
                        ));
                    }
                }
            }
        }
        assert_eq!(attempted, 60);
        assert!(
            failures.is_empty(),
            "{} unauthorized index admissions across {attempted} rows (first 32 shown):\n{}",
            failures.len(),
            failures[..failures.len().min(32)].join("\n")
        );
    }

    #[test]
    fn register_offset_partial_spill_refuses_system_before_bank_erasure() {
        let mut attempted = 0;
        let mut failures = Vec::new();
        for opcode in [IrOpcode::LdrRO, IrOpcode::StrRO] {
            for position in [0, 2] {
                for mode in [4, 5, 12, 13] {
                    attempted += 1;
                    let mut classes = [RegClass::Gpr64; 3];
                    classes[position] = RegClass::System;
                    let (mut func, spills) = register_offset_partial_spill_fixture(
                        opcode,
                        classes,
                        PReg::new(8),
                        1 << position,
                        Some(mode),
                    );
                    if let Some(failure) =
                        register_offset_spill_refusal_failure(func.clone(), &spills)
                    {
                        failures.push(format!("helper: {failure}"));
                    }
                    let original = format!("{:?}", func.inst(InstId(0)));
                    let result = materialize_spilled_operands(&mut func, &spills);
                    let retained = func.inst(InstId(0));
                    if result.is_ok()
                        || func.insts.len() != 1
                        || original != format!("{retained:?}")
                    {
                        failures.push(format!("generic/{opcode:?}/position{position}/mode{mode}: result={result:?}, arena={:?}, final_word={:?}", func.insts, crate::aarch64::encode::encode_instruction(retained)));
                    }
                }
            }
        }
        assert_eq!(attempted, 16);
        assert!(
            failures.is_empty(),
            "{} refusal/nonmutation failures across {attempted} single-System-spill rows (helper and generic routes; first 32 shown):\n{}",
            failures.len(),
            failures[..failures.len().min(32)].join("\n")
        );
    }

    // Check the precise helper boundary, not transactional rollback of the
    // outer materializer (which already takes the block's instruction list).
    fn register_offset_spill_refusal_failure(
        mut func: IrMachFunction,
        spills: &[trust_cg_regalloc::SpillInfo],
    ) -> Option<String> {
        let inst_id = func.blocks[func.entry.0 as usize].insts[0];
        let snapshot = func.inst(inst_id).clone();
        let mut uses = FxHashMap::default();
        let mut defs = FxHashMap::default();
        for spill in spills {
            if spill.vreg.id == 0 && snapshot.opcode == IrOpcode::LdrRO {
                defs.insert(spill.vreg, spill.slot);
            } else {
                uses.insert(spill.vreg, spill.slot);
            }
        }
        let before = format!("{func:?}");
        let mut appended = Vec::new();
        let mut debug = SpillMaterializationDebugInfo::default();
        let result = materialize_spilled_register_offset_mem(
            &mut func,
            inst_id,
            &snapshot,
            &uses,
            &defs,
            &mut appended,
            &mut debug,
        );
        let unchanged =
            before == format!("{func:?}") && appended.is_empty() && debug.stores.is_empty();
        if matches!(result, Err(PipelineError::RegAlloc(_))) && unchanged {
            None
        } else {
            Some(format!(
                "{snapshot:?}: result={result:?}, unchanged={unchanged}, appended={appended:?}, debug={debug:?}"
            ))
        }
    }

    #[test]
    fn register_offset_spill_all_widths_extensions_and_scales() {
        // Expected scratch classes and access-size shifts are authored here,
        // independently of the production scale and scratch-pool helpers.
        let widths = [
            (RegClass::Gpr32, 2, W16, W17),
            (RegClass::Gpr64, 3, X16, X17),
            (RegClass::Fpr16, 1, H16, H17),
            (RegClass::Fpr32, 2, S16, S17),
            (RegClass::Fpr64, 3, D16, D17),
            (RegClass::Fpr128, 4, V16, V17),
        ];
        let modes = [
            None,
            Some(4),
            Some(5),
            Some(6),
            Some(7),
            Some(12),
            Some(13),
            Some(14),
            Some(15),
        ];
        let mut attempted = 0;
        let mut failures = Vec::new();
        for opcode in [IrOpcode::LdrRO, IrOpcode::StrRO] {
            for (class, scale, store_scratch, load_scratch) in widths {
                for index_class in [RegClass::Gpr32, RegClass::Gpr64] {
                    for mode in modes {
                        attempted += 1;
                        let (mut func, spills) = register_offset_spill_fixture(
                            opcode,
                            [class, RegClass::Gpr64, index_class],
                            mode.map(IrOperand::Imm).into_iter().collect(),
                        );
                        let context = format!("{opcode:?}/{class:?}/{index_class:?}/{mode:?}");
                        if let Err(error) = materialize_spilled_operands(&mut func, &spills) {
                            failures.push(format!("{context}: refused {error}"));
                            continue;
                        }
                        let index_reload = if index_class == RegClass::Gpr32 {
                            W17
                        } else {
                            X17
                        };
                        let mut expected = vec![
                            (
                                IrOpcode::LdrRI,
                                vec![IrOperand::PReg(X16), IrOperand::StackSlot(StackSlotId(1))],
                            ),
                            (
                                IrOpcode::LdrRI,
                                vec![
                                    IrOperand::PReg(index_reload),
                                    IrOperand::StackSlot(StackSlotId(2)),
                                ],
                            ),
                        ];
                        let packed = mode.unwrap_or(6);
                        let extension = match packed {
                            4 | 5 => Some(IrOpcode::Uxtw),
                            12 | 13 => Some(IrOpcode::Sxtw),
                            6 | 7 | 14 | 15 => None,
                            _ => unreachable!("fixed authored positive mode"),
                        };
                        if let Some(extension) = extension {
                            expected.push((
                                extension,
                                vec![IrOperand::PReg(X17), IrOperand::PReg(X17)],
                            ));
                        }
                        if matches!(packed, 5 | 7 | 13 | 15) {
                            expected.push((
                                IrOpcode::LslRI,
                                vec![
                                    IrOperand::PReg(X17),
                                    IrOperand::PReg(X17),
                                    IrOperand::Imm(scale),
                                ],
                            ));
                        }
                        let is_load = opcode == IrOpcode::LdrRO;
                        let addr = if is_load { X16 } else { X17 };
                        expected.push((
                            IrOpcode::AddRR,
                            vec![
                                IrOperand::PReg(addr),
                                IrOperand::PReg(X16),
                                IrOperand::PReg(X17),
                            ],
                        ));
                        if is_load {
                            expected.push((
                                IrOpcode::LdrRI,
                                vec![
                                    IrOperand::PReg(load_scratch),
                                    IrOperand::PReg(addr),
                                    IrOperand::Imm(0),
                                ],
                            ));
                            expected.push((
                                IrOpcode::StrRI,
                                vec![
                                    IrOperand::PReg(load_scratch),
                                    IrOperand::StackSlot(StackSlotId(0)),
                                ],
                            ));
                        } else {
                            expected.push((
                                IrOpcode::LdrRI,
                                vec![
                                    IrOperand::PReg(store_scratch),
                                    IrOperand::StackSlot(StackSlotId(0)),
                                ],
                            ));
                            expected.push((
                                IrOpcode::StrRI,
                                vec![
                                    IrOperand::PReg(store_scratch),
                                    IrOperand::PReg(addr),
                                    IrOperand::Imm(0),
                                ],
                            ));
                        }
                        let actual: Vec<_> = func.blocks[func.entry.0 as usize]
                            .insts
                            .iter()
                            .map(|id| {
                                let inst = func.inst(*id);
                                (inst.opcode, inst.operands.clone())
                            })
                            .collect();
                        let ri_opcode = if is_load {
                            IrOpcode::LdrRI
                        } else {
                            IrOpcode::StrRI
                        };
                        if actual != expected || func.inst(InstId(0)).opcode != ri_opcode {
                            failures.push(format!(
                                "{context}: expected={expected:?}, actual={actual:?}"
                            ));
                        }
                        if let Err(error) =
                            ensure_no_unresolved_vregs(&func, "register-offset complete spill")
                        {
                            failures.push(format!("{context}: unresolved {error}"));
                        }
                    }
                }
            }
        }
        // In particular, the 12 default-mode/Gpr32-index cases must reload
        // W17 before using X17: this establishes zero high bits physically.
        assert_eq!(attempted, 216);
        assert!(
            failures.is_empty(),
            "{} failures across {attempted} full spill reconstructions (first 32 shown):\n{}",
            failures.len(),
            failures[..failures.len().min(32)].join("\n")
        );
    }

    #[test]
    fn register_offset_spill_refuses_raw_modes_and_tails_before_mutation() {
        let mut suffixes: Vec<Vec<IrOperand>> = [
            -1_i64,
            i64::MIN,
            i64::MAX,
            0,
            1,
            2,
            3,
            8,
            9,
            10,
            11,
            16,
            20,
            21,
            22,
            23,
            28,
            29,
            30,
            31,
            (1_i64 << 32) + 4,
            (1_i64 << 32) + 6,
            (1_i64 << 32) + 12,
            -(1_i64 << 32) + 6,
        ]
        .into_iter()
        .map(|mode| vec![IrOperand::Imm(mode)])
        .collect();
        for operand in [
            IrOperand::PReg(X17),
            IrOperand::Special(trust_cg_ir::regs::SpecialReg::XZR),
            IrOperand::MemOp {
                base: X16,
                offset: 6,
            },
            IrOperand::StackSlot(StackSlotId(3)),
        ] {
            suffixes.push(vec![operand]);
        }
        suffixes.push(vec![IrOperand::Imm(6), IrOperand::Imm(0)]);
        suffixes.push(vec![IrOperand::Imm(4), IrOperand::PReg(X17)]);
        assert_eq!(suffixes.len(), 30);
        let mut attempted = 0;
        let mut failures = Vec::new();
        for opcode in [IrOpcode::LdrRO, IrOpcode::StrRO] {
            for index in [RegClass::Gpr32, RegClass::Gpr64] {
                for suffix in &suffixes {
                    attempted += 1;
                    let (func, spills) = register_offset_spill_fixture(
                        opcode,
                        [RegClass::Gpr64, RegClass::Gpr64, index],
                        suffix.clone(),
                    );
                    if let Some(failure) = register_offset_spill_refusal_failure(func, &spills) {
                        failures.push(failure);
                    }
                }
            }
        }
        assert_eq!(attempted, 120);
        assert!(
            failures.is_empty(),
            "{} refusal/nonmutation failures across {attempted} malformed spill inputs (first 32 shown):\n{}",
            failures.len(),
            failures[..failures.len().min(32)].join("\n")
        );
    }

    #[test]
    fn register_offset_spill_refuses_unsupported_classes_before_mutation() {
        let invalid_by_position = [
            vec![RegClass::System, RegClass::Fpr8],
            vec![
                RegClass::Gpr32,
                RegClass::System,
                RegClass::Fpr8,
                RegClass::Fpr16,
                RegClass::Fpr32,
                RegClass::Fpr64,
                RegClass::Fpr128,
            ],
            vec![
                RegClass::System,
                RegClass::Fpr8,
                RegClass::Fpr16,
                RegClass::Fpr32,
                RegClass::Fpr64,
                RegClass::Fpr128,
            ],
        ];
        let mut attempted = 0;
        let mut failures = Vec::new();
        for opcode in [IrOpcode::LdrRO, IrOpcode::StrRO] {
            for mode in [
                None,
                Some(4),
                Some(5),
                Some(6),
                Some(7),
                Some(12),
                Some(13),
                Some(14),
                Some(15),
            ] {
                for (position, invalid) in invalid_by_position.iter().enumerate() {
                    for class in invalid {
                        attempted += 1;
                        let mut classes = [RegClass::Gpr64; 3];
                        classes[position] = *class;
                        let (func, spills) = register_offset_spill_fixture(
                            opcode,
                            classes,
                            mode.map(IrOperand::Imm).into_iter().collect(),
                        );
                        if let Some(failure) = register_offset_spill_refusal_failure(func, &spills)
                        {
                            failures.push(failure);
                        }
                    }
                }
            }
        }
        assert_eq!(attempted, 270);
        assert!(
            failures.is_empty(),
            "{} refusal/nonmutation failures across {attempted} unsupported-class spill inputs (first 32 shown):\n{}",
            failures.len(),
            failures[..failures.len().min(32)].join("\n")
        );
    }

    #[test]
    fn materialize_spilled_operands_handles_strro_spilled_gpr32_index() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("test".to_string(), sig);

        let value = VReg::new(0, RegClass::Gpr64);
        let base = VReg::new(1, RegClass::Gpr64);
        let index = VReg::new(2, RegClass::Gpr32);
        let inst_id = func.push_inst(IrMachInst::new(
            IrOpcode::StrRO,
            vec![
                IrOperand::VReg(value),
                IrOperand::VReg(base),
                IrOperand::VReg(index),
            ],
        ));
        func.append_inst(func.entry, inst_id);

        let spills = vec![
            trust_cg_regalloc::SpillInfo {
                vreg: value,
                slot: StackSlotId(0),
            },
            trust_cg_regalloc::SpillInfo {
                vreg: base,
                slot: StackSlotId(1),
            },
            trust_cg_regalloc::SpillInfo {
                vreg: index,
                slot: StackSlotId(2),
            },
        ];

        materialize_spilled_operands(&mut func, &spills).unwrap();

        let block = &func.blocks[func.entry.0 as usize];
        assert_eq!(block.insts.len(), 5);

        let load_index = func.inst(block.insts[1]);
        assert_eq!(load_index.opcode, IrOpcode::LdrRI);
        assert_eq!(load_index.operands[0], IrOperand::PReg(W17));
        assert_eq!(load_index.operands[1], IrOperand::StackSlot(StackSlotId(2)));

        let add_addr = func.inst(block.insts[2]);
        assert_eq!(add_addr.opcode, IrOpcode::AddRR);
        assert_eq!(
            add_addr.operands,
            vec![
                IrOperand::PReg(X17),
                IrOperand::PReg(X16),
                IrOperand::PReg(X17),
            ]
        );

        let store = func.inst(block.insts[4]);
        assert_eq!(store.opcode, IrOpcode::StrRI);
        assert_eq!(
            store.operands,
            vec![
                IrOperand::PReg(X16),
                IrOperand::PReg(X17),
                IrOperand::Imm(0),
            ]
        );
    }

