    fn assert_materializes_mixed_spilled_multiply_accumulate(
        opcode: IrOpcode,
        rhs_class: RegClass,
        acc_class: RegClass,
    ) {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("test".to_string(), sig);

        let lhs = VReg::new(0, RegClass::Gpr64);
        let rhs = VReg::new(1, rhs_class);
        let acc = VReg::new(2, acc_class);
        let inst_id = func.push_inst(IrMachInst::new(
            opcode,
            vec![
                IrOperand::PReg(X0),
                IrOperand::VReg(lhs),
                IrOperand::VReg(rhs),
                IrOperand::VReg(acc),
            ],
        ));
        func.append_inst(func.entry, inst_id);

        let spills = vec![
            trust_cg_regalloc::SpillInfo {
                vreg: lhs,
                slot: StackSlotId(0),
            },
            trust_cg_regalloc::SpillInfo {
                vreg: rhs,
                slot: StackSlotId(1),
            },
            trust_cg_regalloc::SpillInfo {
                vreg: acc,
                slot: StackSlotId(2),
            },
        ];

        materialize_spilled_operands(&mut func, &spills).unwrap();

        let block = &func.blocks[func.entry.0 as usize];
        assert_eq!(block.insts.len(), 5);

        let load_lhs = func.inst(block.insts[0]);
        assert_eq!(load_lhs.opcode, IrOpcode::LdrRI);
        assert_eq!(load_lhs.operands[0], IrOperand::PReg(X16));
        assert_eq!(load_lhs.operands[1], IrOperand::StackSlot(StackSlotId(0)));

        let load_rhs = func.inst(block.insts[1]);
        assert_eq!(load_rhs.opcode, IrOpcode::LdrRI);
        assert_eq!(load_rhs.operands[0], IrOperand::PReg(W17));
        assert_eq!(load_rhs.operands[1], IrOperand::StackSlot(StackSlotId(1)));

        let mul = func.inst(block.insts[2]);
        assert_eq!(mul.opcode, IrOpcode::MulRR);
        assert_eq!(
            mul.operands,
            vec![
                IrOperand::PReg(X0),
                IrOperand::PReg(X16),
                IrOperand::PReg(X17),
            ]
        );

        let load_acc = func.inst(block.insts[3]);
        assert_eq!(load_acc.opcode, IrOpcode::LdrRI);
        assert_eq!(
            load_acc.operands[0],
            IrOperand::PReg(if acc_class == RegClass::Gpr32 {
                W17
            } else {
                X17
            })
        );
        assert_eq!(load_acc.operands[1], IrOperand::StackSlot(StackSlotId(2)));

        let combine = func.inst(block.insts[4]);
        if opcode == IrOpcode::Madd {
            assert_eq!(combine.opcode, IrOpcode::AddRR);
            assert_eq!(
                combine.operands,
                vec![
                    IrOperand::PReg(X0),
                    IrOperand::PReg(X0),
                    IrOperand::PReg(X17),
                ]
            );
        } else {
            assert_eq!(combine.opcode, IrOpcode::SubRR);
            assert_eq!(
                combine.operands,
                vec![
                    IrOperand::PReg(X0),
                    IrOperand::PReg(X17),
                    IrOperand::PReg(X0),
                ]
            );
        }
    }

    #[test]
    fn materialize_spilled_operands_handles_madd_mixed_gpr64_gpr32_gpr64() {
        assert_materializes_mixed_spilled_multiply_accumulate(
            IrOpcode::Madd,
            RegClass::Gpr32,
            RegClass::Gpr64,
        );
    }

    #[test]
    fn materialize_spilled_operands_handles_madd_mixed_gpr64_gpr32_gpr32() {
        assert_materializes_mixed_spilled_multiply_accumulate(
            IrOpcode::Madd,
            RegClass::Gpr32,
            RegClass::Gpr32,
        );
    }

    #[test]
    fn materialize_spilled_operands_handles_msub_mixed_gpr64_gpr32_gpr32() {
        assert_materializes_mixed_spilled_multiply_accumulate(
            IrOpcode::Msub,
            RegClass::Gpr32,
            RegClass::Gpr32,
        );
    }

    #[test]
    fn rebuild_ir_from_regalloc_strips_spill_pseudos() {
        use trust_cg_regalloc::machine_types::{
            RegAllocBlock, RegAllocFunction, RegAllocInst, RegAllocOperand, RegAllocStackSlot,
        };

        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("test".to_string(), sig);
        let v0 = VReg::new(0, RegClass::Gpr64);

        let mut stack_slots = BTreeMap::new();
        stack_slots.insert(StackSlotId(0), RegAllocStackSlot::new(8, 8));

        let ra_func = RegAllocFunction {
            name: "test".to_string(),
            insts: vec![
                RegAllocInst {
                    opcode: trust_cg_regalloc::spill::PSEUDO_SPILL_LOAD,
                    defs: vec![RegAllocOperand::VReg(v0)],
                    uses: vec![RegAllocOperand::StackSlot(StackSlotId(0))],
                    implicit_defs: Vec::new(),
                    implicit_uses: Vec::new(),
                    tied_operands: Vec::new(),
                    flags: InstFlags::READS_MEMORY,
                },
                RegAllocInst {
                    opcode: IrOpcode::AddRR as u16,
                    defs: vec![RegAllocOperand::VReg(v0)],
                    uses: vec![RegAllocOperand::PReg(X1), RegAllocOperand::PReg(X2)],
                    implicit_defs: Vec::new(),
                    implicit_uses: Vec::new(),
                    tied_operands: Vec::new(),
                    flags: IrOpcode::AddRR.default_flags(),
                },
                RegAllocInst {
                    opcode: trust_cg_regalloc::spill::PSEUDO_SPILL_STORE,
                    defs: Vec::new(),
                    uses: vec![
                        RegAllocOperand::VReg(v0),
                        RegAllocOperand::StackSlot(StackSlotId(0)),
                    ],
                    implicit_defs: Vec::new(),
                    implicit_uses: Vec::new(),
                    tied_operands: Vec::new(),
                    flags: InstFlags::WRITES_MEMORY,
                },
            ],
            blocks: vec![RegAllocBlock {
                insts: vec![InstId(0), InstId(1), InstId(2)],
                preds: Vec::new(),
                succs: Vec::new(),
                loop_depth: 0,
            }],
            block_order: vec![BlockId(0)],
            entry_block: BlockId(0),
            next_vreg: 1,
            next_stack_slot: 1,
            stack_slots,
        };

        rebuild_ir_from_regalloc(&mut func, &ra_func).unwrap();

        assert_eq!(func.insts.len(), 1);
        assert_eq!(func.insts[0].opcode, IrOpcode::AddRR);
        assert_eq!(func.blocks[0].insts, vec![InstId(0)]);
    }

    /// Every allocation rebuild used to leak a fresh copy of each
    /// instruction's implicit register lists (LeakSanitizer under the
    /// `fuzz_compile_function` libFuzzer target, L13-P7). Equal lists now share
    /// one interned copy across rebuilt functions.
    #[test]
    fn rebuild_ir_from_regalloc_shares_implicit_register_lists() {
        use trust_cg_regalloc::machine_types::{
            RegAllocBlock, RegAllocFunction, RegAllocInst, RegAllocOperand,
        };

        let ra_func = RegAllocFunction {
            name: "calls".to_string(),
            insts: vec![
                RegAllocInst {
                    opcode: IrOpcode::Blr as u16,
                    defs: Vec::new(),
                    uses: vec![RegAllocOperand::PReg(X2)],
                    implicit_defs: vec![X0, X1, X2],
                    implicit_uses: vec![X0, X1],
                    tied_operands: Vec::new(),
                    flags: IrOpcode::Blr.default_flags(),
                },
                RegAllocInst {
                    opcode: IrOpcode::Ret as u16,
                    defs: Vec::new(),
                    uses: Vec::new(),
                    implicit_defs: Vec::new(),
                    implicit_uses: vec![X0],
                    tied_operands: Vec::new(),
                    flags: IrOpcode::Ret.default_flags(),
                },
            ],
            blocks: vec![RegAllocBlock {
                insts: vec![InstId(0), InstId(1)],
                preds: Vec::new(),
                succs: Vec::new(),
                loop_depth: 0,
            }],
            block_order: vec![BlockId(0)],
            entry_block: BlockId(0),
            next_vreg: 0,
            next_stack_slot: 0,
            stack_slots: BTreeMap::new(),
        };
        let rebuild = || {
            let mut func =
                IrMachFunction::new("calls".to_string(), IrSignature::new(vec![], vec![]));
            rebuild_ir_from_regalloc(&mut func, &ra_func).unwrap();
            func
        };
        let (first, second) = (rebuild(), rebuild());
        assert_eq!(first.insts.len(), 2);
        assert_eq!(first.insts[0].implicit_defs, &[X0, X1, X2]);
        assert_eq!(first.insts[0].implicit_uses, &[X0, X1]);
        assert_eq!(first.insts[1].implicit_uses, &[X0]);
        for (a, b) in first.insts.iter().zip(&second.insts) {
            assert!(std::ptr::eq(a.implicit_defs, b.implicit_defs));
            assert!(std::ptr::eq(a.implicit_uses, b.implicit_uses));
        }
    }

    #[test]
    fn rebuild_ir_from_regalloc_rejects_same_id_different_class_retained_spill() {
        use trust_cg_regalloc::machine_types::{
            RegAllocBlock, RegAllocFunction, RegAllocInst, RegAllocOperand, RegAllocStackSlot,
        };

        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("test".to_string(), sig);
        let v0_spill = VReg::new(0, RegClass::Gpr64);
        let v0_use = VReg::new(0, RegClass::Gpr32);
        let cmp_id = func.push_inst(IrMachInst::new(
            IrOpcode::CmpRR,
            vec![IrOperand::VReg(v0_use), IrOperand::PReg(W0)],
        ));
        func.append_inst(func.entry, cmp_id);

        let mut stack_slots = BTreeMap::new();
        stack_slots.insert(StackSlotId(0), RegAllocStackSlot::new(8, 8));

        let ra_func = RegAllocFunction {
            name: "test".to_string(),
            insts: vec![
                RegAllocInst {
                    opcode: trust_cg_regalloc::spill::PSEUDO_SPILL_LOAD,
                    defs: vec![RegAllocOperand::VReg(v0_use)],
                    uses: vec![RegAllocOperand::StackSlot(StackSlotId(0))],
                    implicit_defs: Vec::new(),
                    implicit_uses: Vec::new(),
                    tied_operands: Vec::new(),
                    flags: InstFlags::READS_MEMORY,
                },
                RegAllocInst {
                    opcode: IrOpcode::CmpRR as u16,
                    defs: Vec::new(),
                    uses: vec![RegAllocOperand::VReg(v0_use), RegAllocOperand::PReg(W0)],
                    implicit_defs: Vec::new(),
                    implicit_uses: Vec::new(),
                    tied_operands: Vec::new(),
                    flags: IrOpcode::CmpRR.default_flags(),
                },
            ],
            blocks: vec![RegAllocBlock {
                insts: vec![InstId(0), InstId(1)],
                preds: Vec::new(),
                succs: Vec::new(),
                loop_depth: 0,
            }],
            block_order: vec![BlockId(0)],
            entry_block: BlockId(0),
            next_vreg: 1,
            next_stack_slot: 1,
            stack_slots,
        };
        let stale_spills = vec![trust_cg_regalloc::SpillInfo {
            vreg: v0_spill,
            slot: StackSlotId(0),
        }];

        let spill_sites = retained_spill_materialization_sites(&ra_func, &stale_spills);
        let inst_map = rebuild_ir_from_regalloc_with_map(&mut func, &ra_func).unwrap();
        let mut spill_sites = remap_spill_materialization_sites(spill_sites, &inst_map);
        let effective_spills =
            effective_spills_from_materialization_sites(&spill_sites, &stale_spills);
        assert!(
            effective_spills.is_empty(),
            "same numeric vreg id with a different class must not retain a stale spill"
        );

        apply_regalloc(&mut func, &BTreeMap::new());
        ensure_spill_stack_slots(&mut func, &effective_spills);
        add_missing_spill_materialization_sites(&func, &mut spill_sites, &effective_spills);
        materialize_spilled_operands_at_sites(&mut func, &spill_sites).unwrap();

        let block = func.block(func.entry);
        assert_eq!(block.insts.len(), 1);
        let cmp = func.inst(block.insts[0]);
        assert_eq!(cmp.opcode, IrOpcode::CmpRR);
        assert_eq!(
            cmp.operands,
            vec![IrOperand::VReg(v0_use), IrOperand::PReg(W0)]
        );
        assert!(ensure_no_unresolved_vregs(&func, "post-ra test").is_err());
    }

