        use trust_cg_regalloc::machine_types::{
            RegAllocBlock, RegAllocFunction, RegAllocInst, RegAllocOperand,
        };

        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("ambiguous_incoming_arg_restore".to_string(), sig);
        let entry = func.entry;
        let incoming_value = VReg::new(0, RegClass::Gpr64);
        let state_value = VReg::new(1, RegClass::Gpr64);

