    #[test]
    fn aarch64_call_arg_fixup_ignores_formal_copy_before_call_setup() {
        static CALL_ARGS: [PReg; 1] = [W0];

        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("formal_then_call_arg".to_string(), sig);
        let entry = func.entry;

        let formal_copy = func.push_inst(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(W1), IrOperand::PReg(W0)],
        ));
        let call_arg = func.push_inst(call_arg_setup(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(W0), IrOperand::PReg(W1)],
        )));
        let call = func.push_inst(
            IrMachInst::new(IrOpcode::Bl, vec![IrOperand::Symbol("_callee".into())])
                .with_implicit_uses(&CALL_ARGS),
        );
        func.append_inst(entry, formal_copy);
        func.append_inst(entry, call_arg);
        func.append_inst(entry, call);

        fixup_aarch64_call_arg_source_clobbers(&mut func, AArch64AbiVariant::Darwin).unwrap();

        let insts = func.block(entry).insts.clone();
        assert_eq!(insts, vec![formal_copy, call_arg, call]);
        assert_eq!(
            func.inst(insts[0]).operands,
            vec![IrOperand::PReg(W1), IrOperand::PReg(W0)]
        );
        assert_eq!(
            func.inst(insts[1]).operands,
            vec![IrOperand::PReg(W0), IrOperand::PReg(W1)]
        );
    }

    #[test]
    fn aarch64_call_arg_fixup_repairs_marked_arg_source_across_transient_clobber() {
        static CALL_ARGS: [PReg; 3] = [X0, X1, X2];

        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("call_arg_temp_alias".to_string(), sig);
        let entry = func.entry;

        let copy_x0 = func.push_inst(call_arg_setup(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X0), IrOperand::PReg(X3)],
        )));
        let movz_w0 = func.push_inst(IrMachInst::new(
            IrOpcode::Movz,
            vec![IrOperand::PReg(W0), IrOperand::Imm(15)],
        ));
        let copy_x1 = func.push_inst(call_arg_setup(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X1), IrOperand::PReg(X4)],
        )));
        let uxtw_x2 = func.push_inst(call_arg_setup(IrMachInst::new(
            IrOpcode::Uxtw,
            vec![IrOperand::PReg(X2), IrOperand::PReg(W0)],
        )));
        let call = func.push_inst(
            IrMachInst::new(IrOpcode::Blr, vec![IrOperand::PReg(X21)])
                .with_implicit_uses(&CALL_ARGS),
        );
        func.append_inst(entry, copy_x0);
        func.append_inst(entry, movz_w0);
        func.append_inst(entry, copy_x1);
        func.append_inst(entry, uxtw_x2);
        func.append_inst(entry, call);

        fixup_aarch64_call_arg_source_clobbers(&mut func, AArch64AbiVariant::Darwin).unwrap();
        let insts = &func.block(entry).insts;
        assert_eq!(insts.len(), 6, "one exact source preserve is required");
        assert_eq!(
            func.inst(insts[0]).operands,
            vec![IrOperand::PReg(W9), IrOperand::PReg(W0)]
        );
        assert_eq!(
            func.inst(uxtw_x2).operands,
            vec![IrOperand::PReg(X2), IrOperand::PReg(W9)]
        );
    }

    #[test]
    fn aarch64_call_arg_provenance_distinguishes_sequential_reload_from_parallel_setup() {
        static CALL_ARGS: [PReg; 2] = [X1, X2];
        let mut func = IrMachFunction::new(
            "sequential_reload_before_args".to_string(),
            IrSignature::new(vec![], vec![]),
        );
        let entry = func.entry;

        // A spill reload is sequential: X2 must receive X16 before the marked
        // X1 setup reads it.  The following marked identity records that the
        // same reloaded value is also the X2 argument.  Adjacency-based
        // reconstruction used to misread the first two instructions as a
        // parallel source clobber and reject this exact production shape.
        let reload = func.push_inst(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X2), IrOperand::PReg(X16)],
        ));
        let setup_x1 = func.push_inst(call_arg_setup(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X1), IrOperand::PReg(X2)],
        )));
        let setup_x2 = func.push_inst(call_arg_setup(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X2), IrOperand::PReg(X2)],
        )));
        let call = func.push_inst(
            IrMachInst::new(IrOpcode::Bl, vec![IrOperand::Symbol("_callee".into())])
                .with_implicit_uses(&CALL_ARGS),
        );
        for id in [reload, setup_x1, setup_x2, call] {
            func.append_inst(entry, id);
        }

        fixup_aarch64_call_arg_source_clobbers(&mut func, AArch64AbiVariant::Darwin).unwrap();
        assert_eq!(
            func.block(entry).insts,
            vec![reload, setup_x1, setup_x2, call]
        );
        lower_copies(&mut func).unwrap();
        assert_eq!(func.inst(reload).opcode, IrOpcode::MOVXrr);
        assert_eq!(func.inst(setup_x1).opcode, IrOpcode::MOVXrr);
        assert_eq!(func.inst(setup_x2).opcode, IrOpcode::Nop);
        verify_aarch64_final_call_argument_sequence(
            &func.name,
            func.block(entry).insts.iter().map(|&id| func.inst(id)),
        )
        .expect("the exact sequential reload plus marked setup must verify");
    }

