    #[test]
    fn aarch64_boundary_rejects_cfg_metadata_that_omits_encoded_edge() {
        let mut func = IrMachFunction::new(
            "stale_cfg_metadata".to_string(),
            IrSignature::new(vec![], vec![]),
        );
        let target = func.create_block();
        let branch = func.push_inst(IrMachInst::new(IrOpcode::B, vec![IrOperand::Block(target)]));
        func.append_inst(func.entry, branch);
        let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
        func.append_inst(target, ret);
        // Deliberately omit add_edge(entry, target): stale metadata must not
        // become regalloc authority when the encoded branch says otherwise.

        let err = encode_function(&func)
            .expect_err("CFG metadata that omits an encoded edge must fail closed");
        assert!(matches!(
            &err,
            PipelineError::MalformedAarch64Function { .. }
        ));
        assert!(err.to_string().contains("successor metadata"));
    }

    #[test]
    fn aarch64_symbolic_boundary_rejects_resolved_branch_bypass() {
        let mut func = IrMachFunction::new(
            "resolved_branch_cfg_bypass".to_string(),
            IrSignature::new(vec![], vec![]),
        );
        let symbolic_source = func.create_block();
        let target = func.create_block();

        let resolved = func.push_inst(IrMachInst::new(IrOpcode::B, vec![IrOperand::Imm(1)]));
        func.append_inst(func.entry, resolved);
        let symbolic = func.push_inst(IrMachInst::new(IrOpcode::B, vec![IrOperand::Block(target)]));
        func.append_inst(symbolic_source, symbolic);
        let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
        func.append_inst(target, ret);
        // Deliberately omit all CFG metadata. A single resolved branch must not
        // disable exact checking for the still-symbolic branch in another block.

        let err = validate_aarch64_mach_function(&func)
            .expect_err("resolved branch operands must be rejected before CFG authority");
        assert!(err.to_string().contains("resolved immediate"));
    }

    #[test]
    fn aarch64_cfg_derivation_treats_empty_and_all_pseudo_blocks_as_fallthrough() {
        for with_pseudo in [false, true] {
            let mut func = IrMachFunction::new(
                format!("fallthrough_{with_pseudo}"),
                IrSignature::new(vec![], vec![]),
            );
            let next = func.create_block();
            if with_pseudo {
                let nop = func.push_inst(IrMachInst::new(IrOpcode::Nop, vec![]));
                func.append_inst(func.entry, nop);
            }
            let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
            func.append_inst(next, ret);
            func.add_edge(func.entry, next);

            validate_aarch64_mach_function(&func)
                .expect("empty/all-pseudo blocks must fall through in layout order");
        }
    }

    #[test]
    fn aarch64_cfg_derivation_uses_last_non_pseudo_terminator() {
        let mut func = IrMachFunction::new(
            "trailing_pseudo_after_branch".to_string(),
            IrSignature::new(vec![], vec![]),
        );
        let layout_next = func.create_block();
        let target = func.create_block();
        let branch = func.push_inst(IrMachInst::new(IrOpcode::B, vec![IrOperand::Block(target)]));
        func.append_inst(func.entry, branch);
        let nop = func.push_inst(IrMachInst::new(IrOpcode::Nop, vec![]));
        func.append_inst(func.entry, nop);
        for block in [layout_next, target] {
            let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
            func.append_inst(block, ret);
        }
        func.add_edge(func.entry, target);

        validate_aarch64_mach_function(&func)
            .expect("a trailing pseudo must not invent a layout-fallthrough edge");
    }

    #[test]
    fn aarch64_cfg_derivation_treats_trailing_brk_and_traps_as_hard_terminators() {
        for opcode in [IrOpcode::Brk, IrOpcode::TrapOverflow] {
            let mut func = IrMachFunction::new(
                format!("hard_terminator_{opcode:?}"),
                IrSignature::new(vec![], vec![]),
            );
            let next = func.create_block();
            let terminator = func.push_inst(IrMachInst::new(opcode, vec![]));
            func.append_inst(func.entry, terminator);
            let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
            func.append_inst(next, ret);

            let edges = derive_ir_cfg_edges_from_branch_operands(&func);
            assert!(
                !edges.contains(&(func.entry, next)),
                "trailing {opcode:?} must not acquire layout fallthrough: {edges:?}"
            );
        }
    }

    #[test]
    fn aarch64_cfg_derivation_includes_eh_landing_pad_edges() {
        let mut func = IrMachFunction::new(
            "invoke_cfg_edges".to_string(),
            IrSignature::new(vec![], vec![]),
        );
        let normal = func.create_block();
        let unwind = func.create_block();
        let call = func.push_inst(IrMachInst::new(
            IrOpcode::Bl,
            vec![IrOperand::Symbol("may_unwind".into())],
        ));
        func.append_inst(func.entry, call);
        for block in [normal, unwind] {
            let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
            func.append_inst(block, ret);
        }
        func.add_edge(func.entry, normal);
        func.add_edge(func.entry, unwind);
        func.eh_metadata.personality = Some("rust_eh_personality".to_string());
        func.eh_metadata
            .add_call_site(trust_cg_ir::function::EhCallSiteEntry {
                call_block: func.entry,
                start_offset: 0,
                length: 0,
                landing_pad_block: Some(unwind),
            });

        validate_aarch64_mach_function(&func)
            .expect("Invoke unwind transfer must participate in exact CFG authority");
    }

    #[test]
    fn aarch64_resolved_cfg_reconstruction_recovers_blocks_and_ignores_guard_skips() {
        let mut func = IrMachFunction::new(
            "resolved_cfg_reconstruction".to_string(),
            IrSignature::new(vec![], vec![]),
        );
        let target = func.create_block();
        let branch = func.push_inst(IrMachInst::new(IrOpcode::B, vec![IrOperand::Imm(1)]));
        func.append_inst(func.entry, branch);
        let ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
        func.append_inst(target, ret);

        assert!(
            func.block(func.entry).succs.is_empty(),
            "fixture must begin with missing/stale resolved CFG metadata"
        );
        let reconstructed = reconstruct_aarch64_resolved_cfg(&func)
            .expect("resolved block-start target must reconstruct exactly");
        assert_eq!(reconstructed.block(func.entry).succs, vec![target]);
        enforce_aarch64_post_regalloc_resolved(&func)
            .expect("final post-RA gate must use reconstructed, not stale, CFG authority");

        let mut guard = IrMachFunction::new(
            "resolved_intra_block_guard".to_string(),
            IrSignature::new(vec![], vec![]),
        );
        for inst in [
            IrMachInst::new(
                IrOpcode::CmpRI,
                vec![IrOperand::PReg(X0), IrOperand::Imm(0)],
            ),
            IrMachInst::new(IrOpcode::BCond, vec![IrOperand::Imm(0), IrOperand::Imm(2)]),
            IrMachInst::new(IrOpcode::Brk, vec![]),
            IrMachInst::new(IrOpcode::Ret, vec![]),
        ] {
            let id = guard.push_inst(inst);
            guard.append_inst(guard.entry, id);
        }
        let guard_view = reconstruct_aarch64_resolved_cfg(&guard)
            .expect("validated +2/BRK guard skip is intra-block control flow");
        assert!(guard_view.block(guard.entry).succs.is_empty());
        enforce_aarch64_post_regalloc_resolved(&guard)
            .expect("validated intra-block guard must pass the final authority gate");
    }

