    #[test]
    fn eliminate_dead_unallocated_defs_nops_pure_dead_vreg_defs() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("test".to_string(), sig);

        let v0 = VReg::new(0, RegClass::Gpr32);
        let v1 = VReg::new(1, RegClass::Gpr32);
        let v2 = VReg::new(2, RegClass::Gpr64);

        func.push_inst(IrMachInst::new(
            IrOpcode::MovI,
            vec![IrOperand::VReg(v0), IrOperand::Imm(7)],
        ));
        func.push_inst(IrMachInst::new(
            IrOpcode::MovR,
            vec![IrOperand::VReg(v1), IrOperand::PReg(W0)],
        ));
        func.push_inst(IrMachInst::new(
            IrOpcode::AddRR,
            vec![
                IrOperand::VReg(v2),
                IrOperand::PReg(X0),
                IrOperand::PReg(X1),
            ],
        ));

        eliminate_dead_unallocated_defs(&mut func);

        for inst in &func.insts {
            assert_eq!(inst.opcode, IrOpcode::Nop);
            assert!(inst.flags.contains(InstFlags::IS_PSEUDO));
            assert!(inst.operands.is_empty());
        }
    }

