    #[test]
    fn regalloc_opcode_to_ir_accepts_append_only_volatile_opcode_tail() {
        for opcode in [
            IrOpcode::VolatileLdrRI,
            IrOpcode::VolatileLdrbRI,
            IrOpcode::VolatileLdrhRI,
            IrOpcode::VolatileStrRI,
            IrOpcode::VolatileStrbRI,
            IrOpcode::VolatileStrhRI,
            // The TLSDESC call form is selected by ISel and so crosses
            // register allocation; its expanded slots never do.
            IrOpcode::TlsDescCall,
        ] {
            assert_eq!(regalloc_opcode_to_ir(opcode as u16).unwrap(), opcode);
        }
        for opcode in [
            IrOpcode::LdrTlsdesc,
            IrOpcode::AddTlsdescLo12,
            IrOpcode::BlrTlsdesc,
        ] {
            assert!(
                regalloc_opcode_to_ir(opcode as u16).is_err(),
                "{opcode:?} exists only after frame lowering and must not round-trip regalloc"
            );
        }
        assert!(regalloc_opcode_to_ir(IrOpcode::BlrTlsdesc as u16 + 1).is_err());
        // Emission-time padding sits between the volatile tail and the TLSDESC
        // call form; it never crosses register allocation and stays refused.
        assert_eq!(
            IrOpcode::VolatileStrhRI as u16 + 1,
            IrOpcode::AlignNop as u16
        );
        assert!(regalloc_opcode_to_ir(IrOpcode::AlignNop as u16).is_err());
    }

    #[test]
    fn regalloc_opcode_to_ir_admits_only_the_llsc_pseudo_tail_after_volatile() {
        for pseudo in trust_cg_ir::llsc::LlscPseudo::ALL {
            let opcode = pseudo.opcode();
            assert_eq!(regalloc_opcode_to_ir(opcode as u16).unwrap(), opcode);
        }
        // Emission-only opcodes never reach allocation.
        for opcode in [
            IrOpcode::AlignNop,
            IrOpcode::Ldxr,
            IrOpcode::Stxr,
            IrOpcode::Stlxrh,
            IrOpcode::Clrex,
            IrOpcode::Ldxp,
            IrOpcode::Stlxp,
        ] {
            assert!(regalloc_opcode_to_ir(opcode as u16).is_err(), "{opcode:?}");
        }
        assert_eq!(
            regalloc_opcode_to_ir(IrOpcode::FrintnRR as u16).unwrap(),
            IrOpcode::FrintnRR
        );
        // The FEAT_CRC32 forms are appended after FRINTN and are selected
        // before allocation, so every one round-trips; nothing after them.
        for opcode in [
            IrOpcode::Crc32B,
            IrOpcode::Crc32H,
            IrOpcode::Crc32W,
            IrOpcode::Crc32X,
            IrOpcode::Crc32Cb,
            IrOpcode::Crc32Ch,
            IrOpcode::Crc32Cw,
            IrOpcode::Crc32Cx,
        ] {
            assert_eq!(regalloc_opcode_to_ir(opcode as u16).unwrap(), opcode);
        }
        assert_eq!(IrOpcode::FrintnRR as u16 + 1, IrOpcode::Crc32B as u16);
        assert!(regalloc_opcode_to_ir(IrOpcode::Crc32Cx as u16 + 1).is_err());
    }

    // =========================================================================
    // resolve_branches tests
    // =========================================================================

    #[test]
    fn resolve_branches_single_block_no_branches() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("test".to_string(), sig);
        let entry = func.entry;

        let add = IrMachInst::new(
            IrOpcode::AddRR,
            vec![
                IrOperand::PReg(X0),
                IrOperand::PReg(X0),
                IrOperand::PReg(X1),
            ],
        );
        let add_id = func.push_inst(add);
        func.append_inst(entry, add_id);

        let ret = IrMachInst::new(IrOpcode::Ret, vec![]);
        let ret_id = func.push_inst(ret);
        func.append_inst(entry, ret_id);

        resolve_branches(&mut func).expect("branch-free function must validate and resolve");

        // No branches, nothing should change
        assert_eq!(func.insts[add_id.0 as usize].operands.len(), 3);
    }

    #[test]
    fn resolve_branches_replaces_block_operand_with_offset() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("test".to_string(), sig);
        let entry = func.entry;
        let bb1 = func.create_block();

        // bb0: B bb1
        let br = IrMachInst::new(IrOpcode::B, vec![IrOperand::Block(bb1)]);
        let br_id = func.push_inst(br);
        func.append_inst(entry, br_id);

        // bb1: RET
        let ret = IrMachInst::new(IrOpcode::Ret, vec![]);
        let ret_id = func.push_inst(ret);
        func.append_inst(bb1, ret_id);
        func.add_edge(entry, bb1);

        resolve_branches(&mut func).expect("valid branch function must resolve");

        // Branch at offset 0 targets bb1 at offset 1 -> relative offset = 1
        let resolved_operand = &func.insts[br_id.0 as usize].operands[0];
        assert!(
            matches!(resolved_operand, IrOperand::Imm(1)),
            "expected Imm(1), got {:?}",
            resolved_operand
        );
    }

