    /// The `LC_BUILD_VERSION` (platform, minos, sdk) of a Mach-O object,
    /// read from the load commands independently of the writer.
    fn macho_build_version_fields(object: &[u8]) -> Option<(u32, u32, u32)> {
        let word = |offset: usize| {
            object
                .get(offset..offset + 4)
                .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
        };
        let ncmds = word(16)?;
        let mut offset = 32usize;
        for _ in 0..ncmds {
            let (command, size) = (word(offset)?, word(offset + 4)? as usize);
            if command == crate::macho::constants::LC_BUILD_VERSION {
                return Some((word(offset + 8)?, word(offset + 12)?, word(offset + 16)?));
            }
            offset += size;
        }
        None
    }

    /// X-DARWIN-P13: both Mach-O emitters record the triple's macOS
    /// deployment target, keep 14.0 for an unversioned Apple triple, and
    /// refuse Apple platforms other than macOS instead of stamping them macOS.
    /// Object emission selects no SDK, so its SDK field stays zero at every
    /// deployment minimum, as specified by `MachOBuildVersion::sdk`.
    #[test]
    fn macho_emitters_record_the_triple_deployment_target() {
        let function = build_add_test_function();
        for (triple, minos) in [
            ("aarch64-apple-darwin", 0x000E_0000),
            ("aarch64-apple-macos12.0", 0x000C_0000),
            ("aarch64-apple-macos13.3.1", 0x000D_0301),
            ("arm64-apple-macosx15.1", 0x000F_0100),
        ] {
            let pipeline = Pipeline::new(PipelineConfig::for_target(triple));
            let single = pipeline.encode_and_emit(&mut function.clone()).unwrap();
            let module = pipeline
                .compile_module(std::slice::from_ref(&function))
                .unwrap();
            for object in [&single, &module] {
                assert_eq!(
                    macho_build_version_fields(object),
                    Some((crate::macho::constants::PLATFORM_MACOS, minos, 0)),
                    "{triple}"
                );
            }
        }
        for triple in [
            "arm64-apple-ios17.0",
            "arm64-apple-ios",
            "aarch64-apple-darwin23",
            "aarch64-apple-macos10.15",
            "aarch64-apple-macos14..0",
        ] {
            let pipeline = Pipeline::new(PipelineConfig::for_target(triple));
            for result in [
                pipeline.encode_and_emit(&mut function.clone()),
                pipeline.compile_module(std::slice::from_ref(&function)),
            ] {
                match result {
                    Err(PipelineError::MachODeploymentTarget(error)) => {
                        assert!(error.to_string().contains("[TCG-MACHO-DEPLOYMENT]"));
                    }
                    other => {
                        panic!("{triple}: expected a deployment-target refusal, got {other:?}")
                    }
                }
            }
        }
    }

    /// X-DARWIN-P12: an empty or unrecognized triple is a typed refusal at
    /// every target-dependent Pipeline entry, never a silent DarwinPCS /
    /// Mach-O default; explicit Apple and ELF triples select their ABI.
    #[test]
    fn pipeline_refuses_empty_and_unrecognized_targets_at_every_entry() {
        use trust_cg_lower::abi::AArch64AbiTargetError;
        use trust_cg_lower::function::{BasicBlock, Signature};
        use trust_cg_lower::instructions::{Block, Instruction, Opcode, Value};

        // `fn tiny() -> i64 { 7 }` in LIR, for the instruction-selection entry.
        let mut lir = trust_cg_lower::Function::new(
            "tiny",
            Signature {
                params: vec![],
                returns: vec![trust_cg_lower::types::Type::I64],
            },
        );
        lir.entry_block = Block(0);
        lir.block_order = vec![Block(0)];
        lir.blocks.insert(
            Block(0),
            BasicBlock {
                params: vec![],
                instructions: vec![
                    Instruction {
                        opcode: Opcode::Iconst {
                            ty: trust_cg_lower::types::Type::I64,
                            imm: 7,
                        },
                        args: vec![],
                        results: vec![Value(0)],
                    },
                    Instruction {
                        opcode: Opcode::Return,
                        args: vec![Value(0)],
                        results: vec![],
                    },
                ],
                source_locs: vec![],
            },
        );
        lir.value_types
            .insert(Value(0), trust_cg_lower::types::Type::I64);
        for (triple, expected) in [
            ("aarch64-apple-darwin", Ok(AArch64AbiVariant::Darwin)),
            ("arm64-apple-ios", Ok(AArch64AbiVariant::Darwin)),
            ("aarch64-unknown-linux-gnu", Ok(AArch64AbiVariant::Aapcs64)),
            ("", Err(AArch64AbiTargetError::Empty)),
            (
                "aarch64",
                Err(AArch64AbiTargetError::Unrecognized("aarch64".into())),
            ),
            (
                "not-a-triple",
                Err(AArch64AbiTargetError::Unrecognized("not-a-triple".into())),
            ),
            (
                "aarch64-pc-windows-msvc",
                Err(AArch64AbiTargetError::Unrecognized(
                    "aarch64-pc-windows-msvc".into(),
                )),
            ),
        ] {
            let pipeline = Pipeline::new(PipelineConfig::for_target(triple));
            match (pipeline.resolved_aarch64_abi(), expected) {
                (Ok(actual), Ok(expected)) => assert_eq!(actual, expected, "{triple:?}"),
                (Err(PipelineError::TargetAbiUnresolved(actual)), Err(expected)) => {
                    assert_eq!(actual, expected, "{triple:?}");
                    assert!(actual.to_string().contains("[TCG-TARGET-ABI]"));
                }
                (actual, expected) => panic!("{triple:?}: {actual:?} vs {expected:?}"),
            }
        }

        // The refusal reaches instruction selection, frame lowering and
        // object emission; a named target compiles the same function.
        let function = build_add_test_function();
        let empty = Pipeline::new(PipelineConfig::default());
        for result in [
            empty.prepare_function(&lir).map(|_| ()),
            empty.prepare_ir_function(&mut function.clone()),
            empty.encode_and_emit(&mut function.clone()).map(|_| ()),
            empty
                .compile_module(std::slice::from_ref(&function))
                .map(|_| ()),
        ] {
            assert!(
                matches!(
                    result,
                    Err(PipelineError::TargetAbiUnresolved(
                        AArch64AbiTargetError::Empty
                    ))
                ),
                "{result:?}"
            );
        }
        let windows = Pipeline::new(PipelineConfig::for_target("aarch64-pc-windows-msvc"));
        assert!(matches!(
            windows.prepare_ir_function(&mut function.clone()),
            Err(PipelineError::TargetAbiUnresolved(
                AArch64AbiTargetError::Unrecognized(_)
            ))
        ));
        for triple in ["aarch64-apple-darwin", "aarch64-unknown-linux-gnu"] {
            let named = Pipeline::new(PipelineConfig::for_target(triple));
            named
                .prepare_function(&lir)
                .unwrap_or_else(|error| panic!("{triple}: {error:?}"));
            named
                .compile_module(std::slice::from_ref(&function))
                .unwrap_or_else(|error| panic!("{triple}: {error:?}"));
        }
    }

    /// The host derivation is explicit and recorded in the config.
    #[test]
    fn pipeline_host_target_is_explicit_and_recorded() {
        let config = PipelineConfig::for_host_aarch64();
        assert_eq!(
            config.target_triple,
            TargetSpec::host_for_architecture(Target::Aarch64).triple()
        );
        let pipeline = Pipeline::new(config);
        if cfg!(target_os = "macos") {
            assert_eq!(
                pipeline.resolved_aarch64_abi().unwrap(),
                AArch64AbiVariant::Darwin
            );
        } else if cfg!(target_os = "linux") {
            assert_eq!(
                pipeline.resolved_aarch64_abi().unwrap(),
                AArch64AbiVariant::Aapcs64
            );
        }
    }

