    #[test]
    fn ir_to_regalloc_preserves_function_name() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("my_function".to_string(), sig);
        let entry = func.entry;

        let ret = IrMachInst::new(IrOpcode::Ret, vec![]);
        let ret_id = func.push_inst(ret);
        func.append_inst(entry, ret_id);

        let ra_func = ir_to_regalloc(&func).unwrap();
        assert_eq!(ra_func.name, "my_function");
    }

    #[test]
    fn ir_to_regalloc_converts_stack_slots() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("test".to_string(), sig);
        func.alloc_stack_slot(trust_cg_ir::function::StackSlot::new(8, 8));
        func.alloc_stack_slot(trust_cg_ir::function::StackSlot::new(16, 16));

        let entry = func.entry;
        let ret = IrMachInst::new(IrOpcode::Ret, vec![]);
        let ret_id = func.push_inst(ret);
        func.append_inst(entry, ret_id);

        let ra_func = ir_to_regalloc(&func).unwrap();
        assert_eq!(ra_func.stack_slots.len(), 2);
        assert_eq!(ra_func.next_stack_slot, 2);
    }

    #[test]
    fn ir_to_regalloc_preserves_runtime_stack_slot_metadata() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("runtime_slot".to_string(), sig);
        func.alloc_stack_slot(StackSlot::new(8, 8));
        func.alloc_stack_slot(StackSlot::new_dynamic(StackSlotSizeSource::Value(5), 16));

        let entry = func.entry;
        let ret = IrMachInst::new(IrOpcode::Ret, vec![]);
        let ret_id = func.push_inst(ret);
        func.append_inst(entry, ret_id);

        let ra_func = ir_to_regalloc(&func).unwrap();
        let fixed = ra_func.stack_slots.get(&StackSlotId(0)).unwrap();
        let runtime = ra_func.stack_slots.get(&StackSlotId(1)).unwrap();

        assert_eq!(ra_func.next_stack_slot, 2);
        assert_eq!(fixed.allocation, StackSlotAllocationKind::Fixed);
        assert_eq!(runtime.size, 0);
        assert_eq!(runtime.align, 16);
        assert!(runtime.is_runtime_sized());
        assert_eq!(
            runtime.allocation,
            StackSlotAllocationKind::RuntimeSized {
                size_source: StackSlotSizeSource::Value(5)
            }
        );
    }

    #[test]
    fn rebuild_ir_from_regalloc_preserves_stack_slot_metadata() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("runtime_rebuild".to_string(), sig);
        func.alloc_stack_slot(StackSlot::new_dynamic(StackSlotSizeSource::Value(6), 16));

        let entry = func.entry;
        let ret = IrMachInst::new(IrOpcode::Ret, vec![]);
        let ret_id = func.push_inst(ret);
        func.append_inst(entry, ret_id);

        let ra_func = ir_to_regalloc(&func).unwrap();
        rebuild_ir_from_regalloc(&mut func, &ra_func).unwrap();

        assert_eq!(func.stack_slots.len(), 1);
        assert!(func.stack_slots[0].is_runtime_sized());
        assert_eq!(
            func.stack_slots[0].size_source(),
            Some(StackSlotSizeSource::Value(6))
        );
        assert_eq!(func.stack_slots[0].align, 16);
    }

    #[test]
    fn ir_to_regalloc_preserves_block_order() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("test".to_string(), sig);
        let entry = func.entry;
        let bb1 = func.create_block();

        // Add instructions to both blocks
        let nop1 = IrMachInst::new(IrOpcode::Nop, vec![]);
        let nop1_id = func.push_inst(nop1);
        func.append_inst(entry, nop1_id);

        let nop2 = IrMachInst::new(IrOpcode::Nop, vec![]);
        let nop2_id = func.push_inst(nop2);
        func.append_inst(bb1, nop2_id);

        let ra_func = ir_to_regalloc(&func).unwrap();
        assert_eq!(ra_func.block_order.len(), 2);
        assert_eq!(ra_func.block_order[0], BlockId(0));
        assert_eq!(ra_func.block_order[1], BlockId(1));
        assert_eq!(ra_func.entry_block, BlockId(0));
    }

    #[test]
    fn rebuild_ir_cfg_edges_uses_actual_branch_operands_before_regalloc() {
        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("stale_cfg_edges".to_string(), sig);
        let entry = func.entry;
        let fallthrough = func.create_block();
        let cold = func.create_block();

        let branch = func.push_inst(IrMachInst::new(
            IrOpcode::BCond,
            vec![IrOperand::Imm(1), IrOperand::Block(cold)],
        ));
        func.append_inst(entry, branch);
        let fallthrough_ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
        func.append_inst(fallthrough, fallthrough_ret);
        let cold_ret = func.push_inst(IrMachInst::new(IrOpcode::Ret, vec![]));
        func.append_inst(cold, cold_ret);

        func.block_mut(entry).succs.push(cold);
        func.block_mut(cold).preds.push(entry);

        rebuild_ir_cfg_edges_from_branch_operands(&mut func);

        assert_eq!(func.block(entry).succs, vec![cold, fallthrough]);
        assert_eq!(func.block(fallthrough).preds, vec![entry]);
        assert_eq!(func.block(cold).preds, vec![entry]);

        let ra_func = ir_to_regalloc(&func).unwrap();
        assert_eq!(
            ra_func.blocks[entry.0 as usize].succs,
            vec![cold, fallthrough]
        );
    }

    #[test]
    fn formal_abi_sources_preserve_linux_i128_alignment_gap() {
        let signature = IrSignature::new(vec![Type::I64, Type::I128, Type::I64], vec![]);
        // Independent ABI expectations: AAPCS64 rounds a 16-byte scalar up to
        // an even register; Darwin permits the odd pair. X1 is scratch in the
        // former and an incoming value in the latter.
        assert_eq!(
            aarch64_formal_abi_source_regs(&signature, AArch64AbiVariant::Aapcs64),
            vec![X0, X2, X3, X4],
        );
        assert_eq!(
            aarch64_formal_abi_source_regs(&signature, AArch64AbiVariant::Darwin),
            vec![X0, X1, X2, X3],
        );
    }

    #[test]
    fn formal_copy_guard_distinguishes_linux_padding_from_unread_arguments() {
        use trust_cg_ir::aarch64_regs::{X10, X11};

        let mut function = IrMachFunction::new(
            "linux_i128_formals".into(),
            IrSignature::new(vec![Type::I64, Type::I128, Type::I64], vec![]),
        );
        let entry = function.entry;
        for (dst, src) in [(X9, X0), (X1, X2), (X10, X3), (X11, X4)] {
            let inst = function.push_inst(IrMachInst::new(
                IrOpcode::Copy,
                vec![IrOperand::PReg(dst), IrOperand::PReg(src)],
            ));
            function.append_inst(entry, inst);
        }
        let reads = aarch64_entry_formal_reads(&function, AArch64AbiVariant::Aapcs64);
        verify_aarch64_formal_entry_copy_hazards(&function, &reads)
            .expect("writing the Linux ABI padding register must not lose an argument");
        let first = function.block(entry).insts[0];
        function.inst_mut(first).operands[0] = IrOperand::PReg(X2);
        let error = verify_aarch64_formal_entry_copy_hazards(&function, &reads).unwrap_err();
        assert!(matches!(
            error,
            PipelineError::Aarch64FormalArgCopyHazard(_)
        ));
        assert!(
            error
                .to_string()
                .contains("dst=x2 aliases unread ABI source x2")
        );
    }

    #[test]
    fn verifier_rejects_formal_copy_dest_aliasing_later_unread_abi_source() {
        let sig = IrSignature::new(vec![Type::I64, Type::I64], vec![]);
        let mut func = IrMachFunction::new("formal_copy_hazard".to_string(), sig);
        let entry = func.entry;

        let first = func.push_inst(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X1), IrOperand::PReg(X0)],
        ));
        let second = func.push_inst(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(X0), IrOperand::PReg(X1)],
        ));
        func.append_inst(entry, first);
        func.append_inst(entry, second);

        let reads = aarch64_entry_formal_reads(&func, AArch64AbiVariant::Darwin);
        let err = verify_aarch64_formal_entry_copy_hazards(&func, &reads).unwrap_err();
        assert!(
            matches!(err, PipelineError::Aarch64FormalArgCopyHazard(_)),
            "unexpected verifier error: {err}"
        );
        assert!(
            err.to_string()
                .contains("dst=x1 aliases unread ABI source x1"),
            "diagnostic should identify the clobbered unread formal source: {err}"
        );
    }

    #[test]
    fn verifier_allows_formal_copy_that_reads_its_own_abi_source_alias() {
        let sig = IrSignature::new(
            vec![Type::I64, Type::I64, Type::I64, Type::I32, Type::I64],
            vec![],
        );
        let mut func = IrMachFunction::new("formal_copy_same_source_alias".to_string(), sig);
        let entry = func.entry;

        for (dst, src) in [(X0, X0), (X1, X1), (X2, X2)] {
            let inst = func.push_inst(IrMachInst::new(
                IrOpcode::Copy,
                vec![IrOperand::PReg(dst), IrOperand::PReg(src)],
            ));
            func.append_inst(entry, inst);
        }
        let i32_formal = func.push_inst(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(W3), IrOperand::PReg(X3)],
        ));
        let later = func.push_inst(IrMachInst::new(
            IrOpcode::Copy,
            vec![IrOperand::PReg(W4), IrOperand::PReg(X4)],
        ));
        func.append_inst(entry, i32_formal);
        func.append_inst(entry, later);

        let reads = aarch64_entry_formal_reads(&func, AArch64AbiVariant::Darwin);
        verify_aarch64_formal_entry_copy_hazards(&func, &reads).unwrap();
    }

    /// Entry block of `f(p0..p7, i, j)` before allocation: `v0` is the formal
    /// copy of the one live register parameter (incoming in `live_formal`),
    /// the stack formals `i`/`j` load into `v1`/`v2`, and `body` follows.
    /// Returns that function and a copy with `allocation` applied.
    fn formal_guard_case(
        live_formal: PReg,
        body: impl FnOnce(&mut IrMachFunction, BlockId),
        allocation: &[(u32, PReg)],
    ) -> (IrMachFunction, IrMachFunction) {
        let sig = IrSignature::new(vec![Type::I64; 10], vec![]);
        let mut func = IrMachFunction::new("stack_formals_forwarded".to_string(), sig);
        let entry = func.entry;
        let v = |id| IrOperand::VReg(VReg::new(id, RegClass::Gpr64));
        for inst in [
            make_inst(IrOpcode::Copy, vec![v(0), IrOperand::PReg(live_formal)]),
            make_inst(
                IrOpcode::LdrRI,
                vec![v(1), IrOperand::PReg(X29), IrOperand::IncomingArg(0)],
            ),
            make_inst(
                IrOpcode::LdrRI,
                vec![v(2), IrOperand::PReg(X29), IrOperand::IncomingArg(8)],
            ),
        ] {
            push_entry(&mut func, entry, inst);
        }
        body(&mut func, entry);
        let mut allocated = func.clone();
        let allocation: BTreeMap<VReg, PReg> = allocation
            .iter()
            .map(|&(id, preg)| (VReg::new(id, RegClass::Gpr64), preg))
            .collect();
        apply_regalloc(&mut allocated, &allocation);
        (func, allocated)
    }

    fn push_entry(func: &mut IrMachFunction, entry: BlockId, inst: IrMachInst) {
        let id = func.push_inst(inst);
        func.append_inst(entry, id);
    }

    /// `g(j, i)` with `p1` dead: the stack formals are allocated straight to
    /// X0/X1, so the call-argument setups become identities over them.
    fn stack_formals_as_call_args(func: &mut IrMachFunction, entry: BlockId) {
        let v = |id| IrOperand::VReg(VReg::new(id, RegClass::Gpr64));
        for (dst, src) in [(X0, 2), (X1, 1)] {
            push_entry(
                func,
                entry,
                call_arg_setup(make_inst(
                    IrOpcode::Copy,
                    vec![IrOperand::PReg(dst), v(src)],
                )),
            );
        }
        push_entry(
            func,
            entry,
            make_inst(IrOpcode::Bl, vec![IrOperand::Symbol("_g".to_string())]),
        );
    }

    /// Block arguments `(i, p2)` with `p3` dead: `i` is allocated to X3 and
    /// its block-argument copy reads X3 after the load wrote it.
    fn stack_formals_as_block_args(func: &mut IrMachFunction, entry: BlockId) {
        let v = |id| IrOperand::VReg(VReg::new(id, RegClass::Gpr64));
        push_entry(func, entry, make_inst(IrOpcode::Copy, vec![v(3), v(1)]));
        push_entry(func, entry, make_inst(IrOpcode::Copy, vec![v(4), v(0)]));
        push_entry(func, entry, make_inst(IrOpcode::Ret, vec![]));
    }

    #[test]
    fn formal_copy_guard_admits_stack_formals_forwarded_through_dead_incoming_registers() {
        let cases: [(
            &str,
            PReg,
            fn(&mut IrMachFunction, BlockId),
            &[(u32, PReg)],
            &str,
        ); 2] = [
            (
                "call arguments",
                X0,
                stack_formals_as_call_args,
                &[(0, X19), (1, X1), (2, X0)],
                "dst=x1 aliases unread ABI source x1",
            ),
            (
                "block arguments",
                X2,
                stack_formals_as_block_args,
                &[(0, X20), (1, X3), (2, X21), (3, X9), (4, X8)],
                "dst=x3 aliases unread ABI source x3",
            ),
        ];
        for abi in [AArch64AbiVariant::Aapcs64, AArch64AbiVariant::Darwin] {
            for (name, live_formal, body, allocation, misread) in cases {
                let (before, allocated) = formal_guard_case(live_formal, body, allocation);
                let reads = aarch64_entry_formal_reads(&before, abi);
                assert_eq!(
                    reads,
                    vec![(before.block(before.entry).insts[0], live_formal)],
                    "{abi:?} {name}: only the formal copy reads an incoming register"
                );
                verify_aarch64_formal_entry_copy_hazards(&allocated, &reads).unwrap_or_else(
                    |error| panic!("{abi:?} {name}: valid entry block refused: {error}"),
                );

                // Selected on the allocated function, the forwarding copy has
                // the shape of a formal read behind the load that wrote it.
                let misread_reads = aarch64_entry_formal_reads(&allocated, abi);
                let error = verify_aarch64_formal_entry_copy_hazards(&allocated, &misread_reads)
                    .unwrap_err();
                assert!(
                    error.to_string().contains(misread),
                    "{abi:?} {name}: {error}"
                );
            }
        }
    }

    #[test]
    fn formal_copy_guard_refuses_an_allocation_over_an_unread_incoming_register() {
        // `p0` allocated to X1 overwrites `p1` before its formal copy reads it.
        let sig = IrSignature::new(vec![Type::I64; 10], vec![]);
        let mut before = IrMachFunction::new("formal_clobber".to_string(), sig);
        let entry = before.entry;
        let v = |id| IrOperand::VReg(VReg::new(id, RegClass::Gpr64));
        for inst in [
            make_inst(IrOpcode::Copy, vec![v(0), IrOperand::PReg(X0)]),
            make_inst(IrOpcode::Copy, vec![v(1), IrOperand::PReg(X1)]),
            make_inst(
                IrOpcode::LdrRI,
                vec![v(2), IrOperand::PReg(X29), IrOperand::IncomingArg(0)],
            ),
            make_inst(IrOpcode::Copy, vec![v(3), v(2)]),
            make_inst(IrOpcode::Ret, vec![]),
        ] {
            push_entry(&mut before, entry, inst);
        }
        let reads = aarch64_entry_formal_reads(&before, AArch64AbiVariant::Darwin);
        assert_eq!(reads.len(), 2, "both register formals are formal reads");
        let mut allocated = before.clone();
        let allocation: BTreeMap<VReg, PReg> = [(0, X1), (1, X19), (2, X20), (3, X21)]
            .into_iter()
            .map(|(id, preg)| (VReg::new(id, RegClass::Gpr64), preg))
            .collect();
        apply_regalloc(&mut allocated, &allocation);
        let error = verify_aarch64_formal_entry_copy_hazards(&allocated, &reads).unwrap_err();
        assert!(
            error
                .to_string()
                .contains("dst=x1 aliases unread ABI source x1"),
            "{error}"
        );
    }

    /// `f(p0..p8)` whose entry block materializes `formals` (instructions over
    /// `v0`/`v1`, `p8` stack-passed) and branches to `header`; the loop body
    /// branches back to the entry block when `back_edge_to_entry`, else to
    /// `header`. Returns the pre-allocation formal reads and the allocated
    /// function.
    fn re_entered_formal_case(
        formals: Vec<IrMachInst>,
        back_edge_to_entry: bool,
    ) -> (Vec<(InstId, PReg)>, IrMachFunction) {
        let sig = IrSignature::new(vec![Type::I64; 9], vec![]);
        let mut func = IrMachFunction::new("re_entered_formals".to_string(), sig);
        let entry = func.entry;
        let header = func.create_block();
        let body = func.create_block();
        let exit = func.create_block();
        let v = |id| IrOperand::VReg(VReg::new(id, RegClass::Gpr64));
        for inst in formals {
            push_entry(&mut func, entry, inst);
        }
        push_entry(
            &mut func,
            entry,
            make_inst(IrOpcode::B, vec![IrOperand::Block(header)]),
        );
        for inst in [
            make_inst(IrOpcode::CmpRI, vec![v(0), IrOperand::Imm(0)]),
            make_inst(
                IrOpcode::BCond,
                vec![
                    IrOperand::Imm(i64::from(trust_cg_ir::CondCode::EQ.encoding())),
                    IrOperand::Block(exit),
                ],
            ),
            make_inst(IrOpcode::B, vec![IrOperand::Block(body)]),
        ] {
            push_entry(&mut func, header, inst);
        }
        let target = if back_edge_to_entry { entry } else { header };
        for inst in [
            make_inst(IrOpcode::SubRI, vec![v(0), v(0), IrOperand::Imm(1)]),
            make_inst(IrOpcode::AddRR, vec![v(1), v(1), v(0)]),
            make_inst(IrOpcode::B, vec![IrOperand::Block(target)]),
        ] {
            push_entry(&mut func, body, inst);
        }
        push_entry(&mut func, exit, make_inst(IrOpcode::Ret, vec![]));
        for (from, to) in [
            (entry, header),
            (header, exit),
            (header, body),
            (body, target),
        ] {
            func.add_edge(from, to);
        }
        let reads = aarch64_entry_formal_reads(&func, AArch64AbiVariant::Darwin);
        let allocation: BTreeMap<VReg, PReg> = [(0, X19), (1, X20)]
            .into_iter()
            .map(|(id, preg)| (VReg::new(id, RegClass::Gpr64), preg))
            .collect();
        apply_regalloc(&mut func, &allocation);
        (reads, func)
    }

    #[test]
    fn formal_copy_guard_refuses_an_entry_block_re_entered_over_its_formals() {
        let v = |id| IrOperand::VReg(VReg::new(id, RegClass::Gpr64));
        let register_formals = vec![
            make_inst(IrOpcode::Copy, vec![v(0), IrOperand::PReg(X0)]),
            make_inst(IrOpcode::Copy, vec![v(1), IrOperand::PReg(X1)]),
        ];
        let stack_formal = vec![make_inst(
            IrOpcode::LdrRI,
            vec![v(0), IrOperand::PReg(X29), IrOperand::IncomingArg(0)],
        )];
        for (name, formals) in [
            ("register formals", register_formals),
            ("stack formal", stack_formal),
        ] {
            let (reads, once) = re_entered_formal_case(formals.clone(), false);
            verify_aarch64_formal_entry_copy_hazards(&once, &reads)
                .unwrap_or_else(|error| panic!("{name}: entry run once refused: {error}"));

            let (reads, re_entered) = re_entered_formal_case(formals, true);
            let error = verify_aarch64_formal_entry_copy_hazards(&re_entered, &reads)
                .expect_err("formals re-run by a back edge must be refused");
            assert!(
                matches!(error, PipelineError::Aarch64FormalArgCopyHazard(_))
                    && error.to_string().contains("is a branch target"),
                "{name}: {error}"
            );
        }

        // An entry block with no formal materialization may be re-entered.
        let (reads, re_entered) = re_entered_formal_case(Vec::new(), true);
        assert!(reads.is_empty());
        verify_aarch64_formal_entry_copy_hazards(&re_entered, &reads).unwrap();
    }

    #[test]
    fn ir_to_regalloc_adds_aarch64_call_clobbers() {
        static EXISTING_DEFS: [PReg; 2] = [PReg::new(0), PReg::new(19)];

        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("test".to_string(), sig);
        let entry = func.entry;
        let call = IrMachInst::new(
            IrOpcode::Bl,
            vec![IrOperand::Symbol("_external_action".to_string())],
        )
        .with_implicit_defs(&EXISTING_DEFS);
        let call_id = func.push_inst(call);
        func.append_inst(entry, call_id);

        let ra_func = ir_to_regalloc(&func).unwrap();
        let implicit_defs = &ra_func.insts[0].implicit_defs;

        assert!(implicit_defs.contains(&PReg::new(0))); // X0
        assert!(implicit_defs.contains(&PReg::new(15))); // X15
        assert!(implicit_defs.contains(&PReg::new(32))); // W0
        assert!(implicit_defs.contains(&PReg::new(64))); // V0
        assert!(implicit_defs.contains(&PReg::new(80))); // V16
        assert!(implicit_defs.contains(&PReg::new(112))); // D16
        assert!(implicit_defs.contains(&PReg::new(144))); // S16
        assert!(implicit_defs.contains(&PReg::new(19))); // Existing non-clobber preserved.
        assert_eq!(
            implicit_defs
                .iter()
                .filter(|&&preg| preg == PReg::new(0))
                .count(),
            1,
            "existing implicit defs should not be duplicated"
        );
    }

    #[test]
    fn ir_to_regalloc_blr_adds_call_clobbers_and_preserves_arg_live_ins() {
        static ARG_LIVE_INS: [PReg; 8] = [
            PReg::new(0),
            PReg::new(1),
            PReg::new(2),
            PReg::new(3),
            PReg::new(4),
            PReg::new(5),
            PReg::new(6),
            PReg::new(7),
        ];

        let sig = IrSignature::new(vec![], vec![]);
        let mut func = IrMachFunction::new("indirect_call".to_string(), sig);
        let entry = func.entry;
        let call = IrMachInst::new(IrOpcode::Blr, vec![IrOperand::PReg(X16)])
            .with_implicit_uses(&ARG_LIVE_INS);
        let call_id = func.push_inst(call);
        func.append_inst(entry, call_id);

        let ra_func = ir_to_regalloc(&func).unwrap();
        let ra_call = &ra_func.insts[0];

        assert!(ra_call.flags.is_call(), "BLR must remain a call");
        assert!(
            ra_call.defs.is_empty(),
            "BLR must not treat its target as a def"
        );
        assert_eq!(ra_call.uses.len(), 1);
        assert_eq!(ra_call.uses[0].as_preg(), Some(X16));

        for preg in ARG_LIVE_INS {
            assert!(
                ra_call.implicit_uses.contains(&preg),
                "argument register {preg:?} must be live into BLR"
            );
        }

        assert!(ra_call.implicit_defs.contains(&PReg::new(0))); // X0
        assert!(ra_call.implicit_defs.contains(&PReg::new(7))); // X7
        assert!(ra_call.implicit_defs.contains(&PReg::new(15))); // X15
        assert!(ra_call.implicit_defs.contains(&PReg::new(16))); // X16/IP0
        assert!(ra_call.implicit_defs.contains(&PReg::new(17))); // X17/IP1
        assert!(ra_call.implicit_defs.contains(&PReg::new(18))); // X18 platform register
        assert!(ra_call.implicit_defs.contains(&PReg::new(30))); // X30/LR
        assert!(ra_call.implicit_defs.contains(&PReg::new(48))); // W16
        assert!(ra_call.implicit_defs.contains(&PReg::new(49))); // W17
        assert!(ra_call.implicit_defs.contains(&PReg::new(50))); // W18
        assert!(ra_call.implicit_defs.contains(&PReg::new(62))); // W30
        assert!(ra_call.implicit_defs.contains(&PReg::new(64))); // V0
        assert!(ra_call.implicit_defs.contains(&PReg::new(80))); // V16
    }

    #[test]
    fn rebuild_ir_preserves_frontend_copy_before_lowering_return_copy() {
        use trust_cg_regalloc::machine_types::{
            RegAllocBlock, RegAllocFunction, RegAllocInst, RegAllocOperand as RaOp,
        };

        let sig = IrSignature::new(vec![], vec![]);
        let mut ir_func = IrMachFunction::new("return_copy".to_string(), sig);
        let entry = ir_func.entry;
        let v0 = VReg::new(0, RegClass::Gpr64);

        for inst in [
            IrMachInst::new(
                IrOpcode::Movz,
                vec![IrOperand::VReg(v0), IrOperand::Imm(42)],
            ),
            IrMachInst::new(
                IrOpcode::Copy,
                vec![IrOperand::PReg(X0), IrOperand::VReg(v0)],
            ),
            IrMachInst::new(IrOpcode::Ret, vec![IrOperand::PReg(X30)]),
        ] {
            let id = ir_func.push_inst(inst);
            ir_func.append_inst(entry, id);
        }

        let ra_func = RegAllocFunction {
            name: "return_copy".to_string(),
            insts: vec![
                RegAllocInst {
                    opcode: IrOpcode::Movz as u16,
                    defs: vec![RaOp::VReg(v0)],
                    uses: vec![RaOp::Imm(42)],
                    implicit_defs: Vec::new(),
                    implicit_uses: Vec::new(),
                    tied_operands: Vec::new(),
                    flags: IrOpcode::Movz.default_flags(),
                },
                RegAllocInst {
                    opcode: IrOpcode::Copy as u16,
                    defs: vec![RaOp::PReg(X0)],
                    uses: vec![RaOp::VReg(v0)],
                    implicit_defs: Vec::new(),
                    implicit_uses: Vec::new(),
                    tied_operands: Vec::new(),
                    flags: IrOpcode::Copy.default_flags(),
                },
                RegAllocInst {
                    opcode: IrOpcode::Ret as u16,
                    defs: Vec::new(),
                    uses: vec![RaOp::PReg(X30)],
                    implicit_defs: Vec::new(),
                    implicit_uses: vec![X0],
                    tied_operands: Vec::new(),
                    flags: IrOpcode::Ret.default_flags(),
                },
            ],
            blocks: vec![RegAllocBlock {
                insts: vec![InstId(0), InstId(1), InstId(2)],
                preds: Vec::new(),
                succs: Vec::new(),
                loop_depth: 0,
            }],
            block_order: vec![BlockId(0)],
            entry_block: BlockId(0),
            next_vreg: 1,
            next_stack_slot: 0,
            stack_slots: BTreeMap::new(),
        };

        rebuild_ir_from_regalloc(&mut ir_func, &ra_func).unwrap();
        let copy_id = ir_func.block(ir_func.entry).insts[1];
        assert_eq!(ir_func.inst(copy_id).opcode, IrOpcode::Copy);

        let mut allocation = BTreeMap::new();
        allocation.insert(v0, X28);
        apply_regalloc(&mut ir_func, &allocation);
        lower_copies(&mut ir_func).unwrap();

        let lowered_copy = ir_func.inst(copy_id);
        assert_eq!(lowered_copy.opcode, IrOpcode::MOVXrr);
        assert_eq!(
            lowered_copy.operands,
            vec![IrOperand::PReg(X0), IrOperand::PReg(X28)]
        );
        assert!(!lowered_copy.flags.contains(InstFlags::IS_PSEUDO));
    }

