    /// A refused pass validation fails the preparation by pass name under
    /// `enforce`; `diagnostic` records it and compiles on; a missing
    /// validation refuses only under `require-coverage`.
    #[test]
    fn pass_validation_refusal_names_the_pass_and_follows_the_policy() {
        use trust_cg_opt::{
            PassValidationConfig, PassValidationPolicy, PassValidationRecord, ValidationVerdict,
            ValidatorKind,
        };
        let func = IrMachFunction::new("pv_refusal".to_string(), IrSignature::new(vec![], vec![]));
        let mut stats = trust_cg_opt::PassStats::default();
        stats.pass_validation.record(
            PassValidationRecord {
                pass_name: "gvn".to_string(),
                function_name: "pv_refusal".to_string(),
                validator: None,
                verdict: ValidationVerdict::Uncovered,
            },
            true,
        );
        assert!(
            Pipeline::enforce_pass_validation(
                &func,
                PassValidationConfig::enforce(),
                &stats.pass_validation
            )
            .is_ok(),
            "enforce does not refuse an uncovered pass"
        );
        let require = PassValidationConfig {
            policy: PassValidationPolicy::RequireCoverage,
            ..PassValidationConfig::enforce()
        };
        match Pipeline::enforce_pass_validation(&func, require, &stats.pass_validation) {
            Err(PipelineError::PassValidationFailed {
                pass,
                validator,
                verdict,
                ..
            }) => {
                assert_eq!(pass, "gvn");
                assert_eq!(validator, "none");
                assert_eq!(verdict, "uncovered");
            }
            other => panic!("require-coverage refuses an uncovered pass, got {other:?}"),
        }
        stats.pass_validation.record(
            PassValidationRecord {
                pass_name: "pressure-aware-scheduler".to_string(),
                function_name: "pv_refusal".to_string(),
                validator: Some(ValidatorKind::DependencePreservation),
                verdict: ValidationVerdict::Refuted("memory dependence reversed".to_string()),
            },
            true,
        );
        assert!(
            Pipeline::enforce_pass_validation(
                &func,
                PassValidationConfig::diagnostic(),
                &stats.pass_validation
            )
            .is_ok()
        );
        match Pipeline::enforce_pass_validation(
            &func,
            PassValidationConfig::enforce(),
            &stats.pass_validation,
        ) {
            Err(error @ PipelineError::PassValidationFailed { .. }) => {
                let text = error.to_string();
                assert!(text.contains("pressure-aware-scheduler"), "{text}");
                assert!(text.contains("dependence-preservation: refuted"), "{text}");
                assert!(text.contains("memory dependence reversed"), "{text}");
                assert!(text.contains("pv_refusal"), "{text}");
            }
            other => panic!("enforce refuses a refuted run, got {other:?}"),
        }
    }

    /// The codegen pipeline's own scheduler step enforces its validation:
    /// a scheduler run that reverses a store/load dependence refuses the
    /// compile by name under `enforce`, and is recorded (not refused) under
    /// `diagnostic`.
    #[test]
    fn codegen_scheduler_step_refuses_a_dependence_breaking_run() {
        use trust_cg_opt::{PassValidationConfig, ValidatorKind};
        struct SwapStoreLoad;
        impl trust_cg_opt::pass_manager::MachinePass for SwapStoreLoad {
            fn name(&self) -> &str {
                "pressure-aware-scheduler"
            }

            fn run(&mut self, func: &mut IrMachFunction) -> bool {
                let entry = func.entry;
                func.block_mut(entry).insts.swap(0, 1);
                true
            }
        }
        let build = || {
            let mut func =
                IrMachFunction::new("pv_sched".to_string(), IrSignature::new(vec![], vec![]));
            let v = |id| {
                trust_cg_ir::MachOperand::VReg(trust_cg_ir::VReg::new(
                    id,
                    trust_cg_ir::RegClass::Gpr64,
                ))
            };
            let entry = func.entry;
            for inst in [
                trust_cg_ir::MachInst::new(
                    trust_cg_ir::AArch64Opcode::StrRI,
                    vec![v(1), v(10), trust_cg_ir::MachOperand::Imm(0)],
                ),
                trust_cg_ir::MachInst::new(
                    trust_cg_ir::AArch64Opcode::LdrRI,
                    vec![v(2), v(10), trust_cg_ir::MachOperand::Imm(0)],
                ),
                trust_cg_ir::MachInst::new(trust_cg_ir::AArch64Opcode::Ret, vec![]),
            ] {
                let id = func.push_inst(inst);
                func.append_inst(entry, id);
            }
            func
        };
        let mut func = build();
        let mut stats = trust_cg_opt::PassStats::default();
        match Pipeline::run_validated_codegen_scheduler(
            &mut func,
            &mut SwapStoreLoad,
            OptimizationValidation {
                config: PassValidationConfig::enforce(),
                transitions: None,
            },
            &mut stats,
        ) {
            Err(PipelineError::PassValidationFailed {
                function,
                pass,
                validator,
                verdict,
                reason,
            }) => {
                assert_eq!(function, "pv_sched");
                assert_eq!(pass, "pressure-aware-scheduler");
                assert_eq!(validator, ValidatorKind::DependencePreservation.as_str());
                assert_eq!(verdict, "refuted");
                assert!(reason.contains("memory"), "{reason}");
            }
            other => panic!("enforce refuses the reordered pair, got {other:?}"),
        }
        let mut func = build();
        let mut stats = trust_cg_opt::PassStats::default();
        assert!(
            Pipeline::run_validated_codegen_scheduler(
                &mut func,
                &mut SwapStoreLoad,
                OptimizationValidation {
                    config: PassValidationConfig::diagnostic(),
                    transitions: None,
                },
                &mut stats,
            )
            .is_ok(),
            "the diagnostic policy records and compiles on"
        );
        assert_eq!(stats.pass_validation.refuted(), 1);
    }

