    #[cfg(feature = "verify")]
    #[test]
    fn run_verification_enabled_reports_coverage() {
        let pipeline = Pipeline::new(PipelineConfig {
            verify: true,
            ..PipelineConfig::for_target("aarch64-apple-darwin")
        });

        // Build a function with only verified instructions. Route through
        // the pipeline's run_verification entrypoint so the test exercises
        // the pipeline's verification wiring (not just trust_cg_verify).
        let sig = IrSignature::new(vec![Type::I64, Type::I64], vec![Type::I64]);
        let mut func = IrMachFunction::new("all_verified".to_string(), sig);
        let entry = func.entry;

        // E0.2: only completely discharged instruction-built obligations are
        // credited, so use 8-bit extensions (exhaustive reconstruction), not
        // 64-bit ADD/SUB (sampled, reported but uncredited).
        let uxtb = IrMachInst::new(
            IrOpcode::Uxtb,
            vec![IrOperand::PReg(W0), IrOperand::PReg(W1)],
        );
        let uxtb_id = func.push_inst(uxtb);
        func.append_inst(entry, uxtb_id);

        let sxtb = IrMachInst::new(
            IrOpcode::Sxtb,
            vec![IrOperand::PReg(W0), IrOperand::PReg(W1)],
        );
        let sxtb_id = func.push_inst(sxtb);
        func.append_inst(entry, sxtb_id);

        // Pipeline verification path: should pass with no failed proofs.
        pipeline
            .run_verification(&func)
            .expect("run_verification: all instructions verified");

        // Direct trust_cg_verify report for coverage details.
        let report = crate::jit_cert::run_on_proof_verifier_stack(
            "trust-cg-pipeline-test-proof-verifier",
            || trust_cg_verify::verify_function(&func),
        );
        assert_eq!(report.verified_count(), 2);
        assert_eq!(report.failed_count(), 0);
        assert_eq!(report.coverage_percent(), 100.0);
    }

